import { registerOwnerPasskeyRoutes } from './owner-passkey-routes.js';
import { ownerMfaDepsFrom } from "./owner-mfa-deps.js";
import { registerOwnerMfaRoutes } from "./owner-mfa-routes.js";
import { registerOwnerRecoveryRoutes } from "./owner-recovery-routes.js";
import { readRequestCookie } from "#src/server/http/request-cookie";
import type { Express, NextFunction, Request, Response } from "express";

import {
  AuthInvalidCredentialsError,
  IdentityValidationError,
  type IdentityRepos,
  type PrincipalKind as IdentityPrincipalKind,
  type PrincipalRecord,
} from "@jini-ai/user-management";
import {
  beginOwnerLogin,
  beginPrincipalSignIn,
  completeOwnerLogin,
  createSessionForPrincipal,
  getEffectivePermissions,
  login,
  logout,
  NodeSessionTokens,
  validateSession,
  type AuthServiceDeps,
} from "@jini-ai/user-management/server";
import type { PrincipalKind } from "#src/contracts/core/gated-mutations/ports";
import { parseAuthenticatedJsonBody } from "../shared/json-body-parsers.js";
import type { ClockDeps, IdentityDeps, RouteDeps } from "../../routes/types.js";
import { authenticateApiKey, type ApiKeyServiceDeps } from "#src/features/identity/api-key-service";
import { createRateLimiter, LOGIN_STRICT, resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { createBootSessionTokenStore, redeemBootSessionToken } from "#src/features/identity/boot-session-token";
import { sendAdminFailure } from "./routes/system/site-share-errors.js";
import { allowsLocalOwnerSignInRequest, bootLocalOwnerSignIn, type LocalOwnerSignInPolicy } from "../../runtime/boot/local-owner-signin.js";
import { DEFAULT_OWNER_PASSWORD } from "#src/features/identity/wiring";
import { callerMayManageUserTrash, principalHoldsBuiltinAdminRole, principalHoldsOwnerWildcard } from "#src/features/identity/delete-user-service";
import { canPublishToLive } from "#src/features/publish-content/live-site-policy";

/**
 * @file Real session auth for the admin origin (ADR-021 / SPEC-006).
 *
 * Purpose:
 * Gates /api/admin/* behind a server-side session backed by the `identity`
 * library's principal/RBAC model. This REPLACES the pre-SPEC-006
 * hardcoded-credential HMAC-cookie scheme (stateless signed `{userId, exp}`
 * token, a single env-var username/password pair, always resolving to the
 * literal actor `"user-local"`) with real argon2id password verification
 * against the seeded `users` table and a real, server-side, revocable
 * `sessions` row per login (REQ-06).
 *
 * How it relates to the project:
 * - Registered by `server/app.ts` ahead of admin routes.
 * - `TOVU_ADMIN_USER`/`TOVU_ADMIN_PASSWORD` still set the *seeded* owner's
 *   username/password at first boot (`identity/seed.ts`) — same env vars as
 *   before, but they now seed a real hashed credential rather than being
 *   compared directly on every login.
 * - Route handlers that need "who is calling" read `getAuthedPrincipal(res)`
 *   (set here once per request) rather than re-parsing the cookie.
 * - The login route is additionally guarded by the `LOGIN_STRICT` rate-limit
 *   profile (REQ-14/AC-18, `core/rate-limit/rate-limit.ts`) before credentials are checked.
 *
 * SPEC-006 REQ-08 (2026-08-24): the gate now accepts a SECOND credential type — an issued API key
 * presented as `Authorization: Bearer <raw-key>` (or `ApiKey <raw-key>`, the spelling api.spec §2
 * uses; both are accepted so an ordinary HTTP client's bearer-token support works unchanged). Both
 * credentials resolve to the same thing — a `PrincipalRecord` on `res.locals` — so every existing
 * `getAuthedPrincipal`/`authorize()` call downstream is untouched by the addition: an api_key
 * principal's grants come from its issuance snapshot and are evaluated by the same `authorize()`.
 *
 * The cookie is tried first, so a browser request behaves EXACTLY as before and the header path is
 * reached only when there is no session to find.
 *
 * Scope: this applies to every surface that mounts `requireAdminSession`, which today is
 * `/api/admin` (`modules/core.ts`) AND `/api/assistant/chats` (`modules/assistant-chats.ts`) — not
 * `/api/admin` alone. Both are admin-authenticated surfaces whose per-route authorization is
 * unchanged, so a key reaches exactly the routes its snapshotted permissions already allow;
 * `openapi/006-identity-and-authorization.yaml` documents the `/api/admin` half.
 *
 * Architectural role:
 * `requireAdminSession`/`registerAuthRoutes` are middleware/route factories
 * that close over the identity repos + hasher + the `identityReady` seed
 * promise (`registerAuthRoutes` still takes the full `RouteDeps` bag it's
 * registered against; `requireAdminSession`/`currentPrincipal` take only
 * `SessionAuthDeps` — see that type's own doc) — the composition roots
 * (`server/app.ts`) pass `routeDeps` in either way, since `RouteDeps` is a
 * strict superset of `SessionAuthDeps`. Not a port (ADR-006): one real
 * session/credential implementation.
 */
const SESSION_COOKIE = "tovu_session";

// The extracted minter keeps the 32-byte hex bearer and SHA-256 digest in
// user-management/server/session-tokens.ts; binding it preserves existing session rows.
const sessionTokens = new NodeSessionTokens({});
// Tovu's absolute 30-day lifetime is product policy, passed explicitly to both minting paths.
const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * `Bearer <raw-key>` or `ApiKey <raw-key>`, case-insensitive on the scheme. The captured group is
 * a live credential: it is passed straight to `authenticateApiKey` and is never logged, echoed in
 * an error body, or attached to `res.locals`.
 */
const API_KEY_AUTHORIZATION_PATTERN = /^(?:Bearer|ApiKey)[ \t]+(\S+)$/i;

/** How the current request authenticated. Route families that must not be reachable by a machine
 *  credential (see `routes/admin/api-keys/*`) branch on this.
 *
 * `"publish_key"` is resolved by `publish-trust-auth.ts`'s `requirePublishTrust`, NOT by
 * `currentCredential` below — a publishing session token is never a credential this file can
 * issue or validate, and it reaches only the routes `grant.ts`'s `PUBLISH_TRUST_ROUTES` names.
 * It is listed here so the existing `rejectUnlessSessionCredential` guard (which admits only
 * `"session"`) refuses it on every machine-credential-forbidden route without a second edit. */
export type AuthCredentialKind = "session" | "api_key" | "publish_key";

/**
 * Maps how a request authenticated onto the principal class a gated ceremony records
 * (`core/gated-mutations/ports.ts`'s `PrincipalKind`).
 *
 * Exists so a route stops hardcoding `principalKind: "user"` for every caller. The mapping is
 * total and deliberately has no default arm: a new credential kind is a compile error here rather
 * than a silent re-label of automation as a human.
 *
 * `"agent"` is unreachable from this mapping because no agent authenticates through the admin HTTP
 * gate — agent-driven ceremonies pass their own kind directly from each feature's own
 * `tool-registrations.ts`.
 *
 * @complexity O(1).
 */
export function gatedPrincipalKindFor(kind: AuthCredentialKind): PrincipalKind {
  switch (kind) {
    case "session":
      return "user";
    case "api_key":
      return "api_key";
    case "publish_key":
      return "publish_key";
    // Preserve the undefined fallback for runtime inputs outside this exhaustive union.
    default: return undefined as never;
  }
}

/**
 * A principal an admin credential may resolve to: any kind but a site `member`. Members sign in on
 * the member origin with their own session (ADR-030 §3) and `authorize()` denies them every
 * operator permission (F3144); `currentCredential` also refuses an operator session or API key that
 * resolves to one, so admin routes can rely on this type.
 */
export type OperatorPrincipalRecord = PrincipalRecord & { kind: Exclude<IdentityPrincipalKind, "member"> };

function isOperatorPrincipal(principal: PrincipalRecord): principal is OperatorPrincipalRecord {
  return principal.kind !== "member";
}

/** A resolved credential: who is calling, and which of the two credential types proved it. */
export interface AuthenticatedCredential {
  principal: OperatorPrincipalRecord;
  kind: AuthCredentialKind;
}

/**
 * Deps `requireAdminSession`/`currentPrincipal` actually need: the identity repos (9 fields) plus
 * clock/idGen for `identity/*`'s `login`/`logout`/`validateSession`. Narrower than full `RouteDeps` —
 * see `routes/types.ts`'s `ClockDeps`/`IdentityDeps` doc for why this Slice-1 extraction exists.
 */
type SessionAuthDeps = IdentityDeps & ClockDeps;

/** Assemble the `IdentityRepos` bag `identity/*` functions expect from `RouteDeps`'s flat fields. */
function identityReposFrom(deps: IdentityDeps): IdentityRepos {
  return {
    transactions: deps.transactions,
    principals: deps.principalRepo,
    users: deps.userRepo,
    sessions: deps.sessionRepo,
    roles: deps.roleRepo,
    policies: deps.policyRepo,
    policyPermissions: deps.policyPermissionRepo,
    rolePolicies: deps.rolePolicyRepo,
    principalRoles: deps.principalRoleRepo,
    principalPolicies: deps.principalPolicyRepo,
  };
}

/** Bind the host's ISO clock and the required bearer strategy to Jini's auth ports. */
function authServiceDepsFrom(deps: SessionAuthDeps): AuthServiceDeps {
  return {
    repos: identityReposFrom(deps),
    ...(deps.mfaStore ? { mfaStore: deps.mfaStore } : {}),
    hasher: deps.passwordHasher,
    clock: { nowMs: () => Date.parse(deps.clock.nowIso()) },
    idGen: deps.idGen,
    tokens: sessionTokens,
  };
}

/** Assemble the `ApiKeyServiceDeps` bag `authenticateApiKey` expects from `RouteDeps`'s flat fields. */
function apiKeyServiceDepsFrom(deps: SessionAuthDeps): ApiKeyServiceDeps {
  return {
    ...authServiceDepsFrom(deps),
    apiKeys: deps.apiKeyRepo,
    secretHasher: deps.apiKeySecretHasher,
  };
}

function readSessionToken({ req, localOwnerSignIn }: { req: Request; localOwnerSignIn: LocalOwnerSignInPolicy }, _optional = {}): string | null {
  // The port cookie is a dev capability, never a second production authentication name.
  const localToken = localOwnerSignIn.enabled ? readRequestCookie({ request: req, name: localSessionCookieName(req) }) : undefined;
  return localToken ?? readRequestCookie({ request: req, name: SESSION_COOKIE }) ?? null;
}

/** Revoke only the two session cookies this listener clears, using Jini's idempotent revoker.
 * Clearing a browser cookie alone leaves a captured bearer usable until expiry.
 * @complexity O(1): at most two session lookups/revocations; other tabs' sessions stay valid.
 */
async function revokeRequestSessions({ deps, req }: { deps: SessionAuthDeps; req: Request }, _optional = {}): Promise<void> {
  const tokens = new Set([readRequestCookie({ request: req, name: SESSION_COOKIE }),
    readRequestCookie({ request: req, name: localSessionCookieName(req) })]);
  for (const rawToken of tokens) {
    if (rawToken) await logout({ deps: authServiceDepsFrom(deps), input: { workspaceId: deps.workspaceId, rawToken } });
  }
}

/** Cookies ignore ports. Local browser sites need separate names to remain signed in together. */
function localSessionCookieName(req: Request): string {
  return `${SESSION_COOKIE}_local_${req.socket?.localPort ?? 0}`;
}

/** REQ-06: `HttpOnly`, `SameSite=Strict`, `Secure`, bound to the admin origin. */
function setSessionCookie(res: Response, rawToken: string, expiresAtIso: string, { name = SESSION_COOKIE }: { name?: string } = {}): void {
  const maxAge = Math.max(0, new Date(expiresAtIso).getTime() - Date.now());
  res.cookie(name, rawToken, { httpOnly: true, path: "/", maxAge, sameSite: "strict", secure: true });
  // A deliberate password sign-in supersedes local owner bootstrap, including a non-owner login.
  if (name === SESSION_COOKIE && readRequestCookie({ request: res.req, name: localSessionCookieName(res.req) })) {
    res.clearCookie(localSessionCookieName(res.req), { httpOnly: true, path: "/", sameSite: "strict", secure: true });
  }
}

function clearSessionCookie(res: Response): void {
  res.clearCookie(SESSION_COOKIE, { httpOnly: true, path: "/", sameSite: "strict", secure: true });
  if (readRequestCookie({ request: res.req, name: localSessionCookieName(res.req) })) {
    res.clearCookie(localSessionCookieName(res.req), { httpOnly: true, path: "/", sameSite: "strict", secure: true });
  }
}

/** Pull the raw key out of an `Authorization` header, or `null` when there is no key-shaped one. */
function readApiKeyCredential(req: Request): string | null {
  const header = req.headers.authorization;
  if (!header) return null;
  const match = API_KEY_AUTHORIZATION_PATTERN.exec(header.trim());
  return match ? match[1] : null;
}

/**
 * Resolve whichever credential this request carries to its principal, applying every fail-closed
 * check for that credential type. Awaits `deps.identityReady` first so this never races first-boot
 * seeding.
 *
 * The cookie is tried first and the `Authorization` header only when no session resolved, so an
 * ordinary browser request without a local port cookie keeps its existing behavior. Local dev
 * cookies use the same validator and repos; only their browser cookie name differs.
 * Both paths are all-or-nothing: `validateSession` and `authenticateApiKey` each return `null` for
 * every rejection reason (missing, invalid, expired, revoked, disabled principal) rather than a
 * distinguishable error, so the 401 below cannot be used as an oracle either way.
 *
 * @returns the principal plus WHICH credential proved it, or `null`.
 * @complexity O(1) — one cookie parse plus one session lookup, or one header parse plus one
 *   indexed api-key lookup and one key derivation.
 * @overallScore 100
 */
export async function currentCredential(
  deps: SessionAuthDeps,
  req: Request,
  { localOwnerSignIn = bootLocalOwnerSignIn }: { localOwnerSignIn?: LocalOwnerSignInPolicy } = {},
): Promise<AuthenticatedCredential | null> {
  const rawToken = readSessionToken({ req, localOwnerSignIn });
  if (rawToken) {
    await deps.identityReady;
    const resolved = await validateSession({
      deps: authServiceDepsFrom(deps),
      input: { workspaceId: deps.workspaceId, rawToken },
    });
    // A member principal is refused like a missing session (no oracle): only a hand-minted row
    // could pair one with an operator session.
    if (resolved?.principal && isOperatorPrincipal(resolved.principal)) return { principal: resolved.principal, kind: "session" };
  }

  const rawKey = readApiKeyCredential(req);
  if (!rawKey) return null;

  await deps.identityReady;
  const authenticated = await authenticateApiKey({
    deps: apiKeyServiceDepsFrom(deps),
    input: { workspaceId: deps.workspaceId, rawKey },
  });
  return authenticated && isOperatorPrincipal(authenticated.principal)
    ? { principal: authenticated.principal, kind: "api_key" }
    : null;
}

/**
 * Resolve the current request's credential to its principal, discarding which credential it was.
 * Thin wrapper over `currentCredential` — kept because callers that only ever needed "who is
 * calling" should not have to destructure a shape they ignore.
 *
 * @complexity O(1) — see `currentCredential`.
 * @overallScore 100
 */
export async function currentPrincipal(deps: SessionAuthDeps, req: Request,
  options: { localOwnerSignIn?: LocalOwnerSignInPolicy } = {},
): Promise<OperatorPrincipalRecord | null> {
  return (await currentCredential(deps, req, options))?.principal ?? null;
}

/**
 * Read the principal `requireAdminSession` attached to this request. Route
 * handlers under `/api/admin` call this instead of re-parsing the cookie.
 * Throws if called on a request that didn't pass through
 * `requireAdminSession` first — a wiring bug, not a runtime auth outcome.
 */
export function getAuthedPrincipal(res: Response): OperatorPrincipalRecord {
  const principal = res.locals.principal as OperatorPrincipalRecord | undefined;
  if (!principal) {
    throw new Error(
      "getAuthedPrincipal: no principal on res.locals — requireAdminSession must run before this route"
    );
  }
  return principal;
}

/**
 * Read HOW the current request authenticated (SPEC-006 REQ-08). Route families that must stay
 * out of reach of a machine credential call this and refuse anything but `"session"` — the
 * spec-level rule that an API key can never mint, issue, or revoke another API key, which is what
 * keeps key issuance from being a privilege-escalation primitive.
 *
 * Throws if called on a request that didn't pass through `requireAdminSession` first — a wiring
 * bug, not a runtime auth outcome (same contract as `getAuthedPrincipal`).
 */
export function getAuthedCredentialKind(res: Response): AuthCredentialKind {
  const kind = res.locals.authCredentialKind as AuthCredentialKind | undefined;
  if (!kind) {
    throw new Error(
      "getAuthedCredentialKind: no credential kind on res.locals — requireAdminSession must run before this route"
    );
  }
  return kind;
}

/** What every route family that refuses a machine credential sends — identical shape whether the
 *  refusal came from `routes/api-keys/*` or `routes/system/site-key.ts`, so a caller can branch
 *  on `code`/`details.reason` without knowing which family answered. */
export interface CredentialKindForbiddenBody {
  error: string;
  code: "FORBIDDEN";
  details: { permission: string; reason: "credential_kind_not_permitted" };
}

/**
 * The shared "this action must stay out of reach of a machine credential" guard
 * (`getAuthedCredentialKind`'s own doc names the rule). Two route families call this today:
 * `routes/api-keys/deps.ts`'s `rejectApiKeyCredential` (an api_key may never mint, issue, or
 * revoke another key — SPEC-006 REQ-08) and `routes/system/site-key.ts` (an api_key may never
 * read or mint the site key, since a leaked key would then expose every other stored
 * credential). Both need the identical 403 shape, so this is the one place that shape is spelled
 * out; each caller supplies only the wording and the permission name its own 403 body should carry.
 *
 * Runs before any body read or existence check that route performs, so an api_key caller learns
 * nothing beyond "this credential type is not permitted here."
 *
 * @returns `true` when the request may proceed. On `false` the 403 has already been sent.
 * @complexity O(1).
 */
export function rejectUnlessSessionCredential(
  res: Response,
  context: { message: string; permission: string }
): boolean {
  if (getAuthedCredentialKind(res) === "session") return true;

  const body: CredentialKindForbiddenBody = {
    error: context.message,
    code: "FORBIDDEN",
    details: { permission: context.permission, reason: "credential_kind_not_permitted" },
  };
  res.status(403).json(body);
  return false;
}

/**
 * Express middleware factory: reject unauthenticated /api/admin requests; attach the principal,
 * then parse the JSON body at the authenticated limit (`json-body-parsers.ts`).
 *
 * Steps aside for a request `publish-trust-auth.ts`'s `requirePublishTrust` already resolved. That
 * gate mounts immediately before this one and only ever reaches `next()` with a credential
 * attached when it has verified the token's MAC, its audience, its expiry, its grant AND that the
 * request is on a route `grant.ts`'s `PUBLISH_TRUST_ROUTES` names — so by the time this sees the
 * marker, every check this middleware would perform has a stricter counterpart that already ran.
 * `res.locals` is server-side and per-request: no client can set the marker.
 * Credential-store failures go to Express's error handler through `next(error)`.
 */
export function requireAdminSession(deps: SessionAuthDeps,
  { localOwnerSignIn = bootLocalOwnerSignIn }: { localOwnerSignIn?: LocalOwnerSignInPolicy } = {},
) {
  return async function requireAdminSessionMiddleware(
    req: Request,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      if (res.locals.authCredentialKind === "publish_key") {
        parseAuthenticatedJsonBody(req, res, next);
        return;
      }

      const credential = await currentCredential(deps, req, { localOwnerSignIn });
      if (!credential) {
        res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
        return;
      }
      res.locals.principal = credential.principal;
      res.locals.authCredentialKind = credential.kind;
      // The app-level parser leaves gated paths unparsed, so an anonymous body is never read.
      parseAuthenticatedJsonBody(req, res, next);
    } catch (error) {
      // Forward failed credential resolution; Express 4 drops rejected middleware promises.
      next(error);
    }
  };
}

/**
 * Loopback peer addresses. IPv4-mapped IPv6 (`::ffff:127.0.0.1`) is what Node reports for an IPv4
 * client on a dual-stack listener, so it belongs here; `localhost` deliberately does not, because
 * this is compared against a resolved socket address, never a name.
 */
const IPV4_LOOPBACK = "127.0.0.1";
const LOOPBACK_PEERS = new Set([IPV4_LOOPBACK, "::1", `::ffff:${IPV4_LOOPBACK}`]);

/**
 * Whether this request came from this machine.
 *
 * Proven from the SOCKET, not inferred from the bind address: `serve.ts` binds `127.0.0.1` by
 * default (LAN-bind plan, 2026-09-23), but `TOVU_HOST` can widen that, and `index.ts` still binds
 * every interface by default — so a remote client is possible on either boot path and this check
 * stays regardless of what either one is currently bound to.
 * `req.ip`/`X-Forwarded-For` are deliberately not consulted — a header is attacker-controlled, and
 * this is the check that stands between a boot token and the network.
 *
 * @complexity O(1).
 */
function isLoopbackPeer(req: Request): boolean {
  const peer = req.socket.remoteAddress;
  return typeof peer === "string" && LOOPBACK_PEERS.has(peer);
}

/**
 * Mint a session row for an already-identified principal and return its raw token.
 *
 * Thin wrapper over `@jini-ai/user-management/server`'s `createSessionForPrincipal` (2026-09-06) — the
 * library's own password-free session minter, factored out of `login()` so this route no longer
 * has to hand-roll session construction. This used to duplicate `auth-service.ts`'s private
 * `hashToken`/token-generation inline (with its own base64url encoding, diverging from the
 * library's hex) because `login()` was the only minter and hard-requires a password; that
 * duplication, and the encoding drift it carried, is gone now that both paths share one minter.
 * The caller still VERIFIES the result through the library's own `validateSession` before handing
 * the cookie out — that check is what would have caught the old drift, and stays as defense in
 * depth even though the shared minter removes the drift's actual cause.
 *
 * @complexity O(1) — one session write (inside the shared minter).
 */
async function mintSessionForPrincipal(deps: SessionAuthDeps, principalId: string): Promise<{ mfaRequired: true; pendingToken: string } | { rawToken: string; expiresAt: string }> {
  if (deps.mfaStore) {
    const result = await beginPrincipalSignIn({ deps: await ownerMfaDepsFrom({ deps }),
      input: { workspaceId: deps.workspaceId, principalId } }, { sessionTtlMs: SESSION_TTL_MS });
    if ("mfaRequired" in result) return result;
    return { rawToken: result.rawToken, expiresAt: result.session.expiresAt };
  }
  const { session, rawToken } = await createSessionForPrincipal({
    deps: authServiceDepsFrom(deps),
    input: { workspaceId: deps.workspaceId, principalId },
  }, { sessionTtlMs: SESSION_TTL_MS });
  return { rawToken, expiresAt: session.expiresAt };
}

/** Resolve the seeded boot owner only after identity initialization, refusing non-operators. */
async function resolveBootOwner(
  { deps }: { deps: SessionAuthDeps },
  _optional = {},
): Promise<{ principalId: string; principal: OperatorPrincipalRecord } | null> {
  await deps.identityReady;
  const principalId = await deps.ownerPrincipalId;
  const principal = await deps.principalRepo.findById({ workspaceId: deps.workspaceId, id: principalId });
  if (!principal || principal.status !== "active" || !isOperatorPrincipal(principal)) return null;
  return { principalId, principal };
}

/** Anonymous auth replies disclose only the operation, recovery action and incident ID.
 * Wrap the cause so the shared helper's domain-specific refusals cannot disclose backend facts.
 * Diagnostics retain the cause through the shared redactor; no credentials enter the reply.
 * @complexity O(diagnostic length) redaction, one log and at most one configured tracker event.
 */
function sendAuthFailure(
  { res, error, operation }: { res: Response; error: unknown; operation: "login" | "logout" | "boot-session" },
  _options = {},
): void {
  const signingOut = operation === "logout";
  sendAdminFailure({ res, error: new Error("Authentication operation failed", { cause: error }) }, {
    operation: `auth-${operation}`,
    message: signingOut ? "Sign-out could not finish." : "Sign-in could not finish.",
    failure: {
      step: `auth-${operation}`,
      action: signingOut ? "Try signing out again. If it still fails, copy details and report this problem." : "Try signing in again. If it still fails, copy details and report this problem.",
    },
  });
}

/** Shared desktop/browser exchange: consume once, verify the real session, then set its cookie.
 * Resolves null after sending the existing rejection body. Repository failures propagate.
 * @complexity O(1): a bounded number of principal/session lookups and one session write.
 */
export async function redeemOwnerBootSession(
  { deps, res, token }: { deps: SessionAuthDeps; res: Response; token: unknown },
  { redeem = redeemBootSessionToken, cookieName = SESSION_COOKIE }: { redeem?: (token: unknown) => boolean; cookieName?: string } = {},
): Promise<OperatorPrincipalRecord | null> {
  if (!redeem(token)) {
    res.status(401).json({ error: "invalid or spent boot token", code: "UNAUTHENTICATED" });
    return null;
  }
  const owner = await resolveBootOwner({ deps });
  if (!owner) {
    sendAuthFailure({ res, error: new Error("Boot owner is unavailable"), operation: "boot-session" });
    return null;
  }
  const { principalId, principal } = owner;
  const minted = await mintSessionForPrincipal(deps, principalId);
  if ("mfaRequired" in minted) { res.setHeader("Cache-Control", "no-store"); res.json(minted); return null; }
  const { rawToken, expiresAt } = minted;
  // The fork guard promised in `mintSessionForPrincipal`'s doc: prove the row this route just
  // wrote is one the library itself will accept, BEFORE setting a cookie on it. Without this, a
  // future change to the library's private token hashing would leave every desktop launch
  // silently unauthenticated with nothing pointing at the cause.
  const confirmed = await validateSession({
    deps: authServiceDepsFrom(deps), input: { workspaceId: deps.workspaceId, rawToken },
  });
  if (!confirmed?.principal) {
    sendAuthFailure({ res, error: new Error("Boot session confirmation failed"), operation: "boot-session" });
    return null;
  }
  // The ordinary desktop cookie also replaces/clears local bootstrap; revoke what it supersedes.
  if (cookieName === SESSION_COOKIE) await revokeRequestSessions({ deps, req: res.req });
  setSessionCookie(res, rawToken, expiresAt, { name: cookieName });
  return principal;
}

/** Told after an owner or admin signs in. Only the serving app passes one (its automatic form pull);
 * `signedIn` must return at once: it runs after the session cookie is set and is never awaited. */
export interface AdminSignInPort {
  signedIn(required?: Record<string, never>, optional?: Record<string, never>): void;
}

/** The site's owner (an unconstrained `*` holder) or a holder of the built-in `admin` role — the
 * identity feature's two role classifiers, never a permission string, so a custom role that was
 * granted broad permissions does not count. @complexity Owner check first; role lookup only if not.
 */
async function isOwnerOrBuiltinAdmin({ deps, principalId }: { deps: SessionAuthDeps; principalId: string }, _optional = {}): Promise<boolean> {
  const authDeps = authServiceDepsFrom(deps);
  if (await principalHoldsOwnerWildcard({ deps: authDeps, workspaceId: deps.workspaceId, principalId })) return true;
  return principalHoldsBuiltinAdminRole({ deps: authDeps, workspaceId: deps.workspaceId, principalId });
}

/** After a successful sign-in, tells `port` when the principal is the owner or an admin. Returns at
 * once: the role lookup runs in the background, and its failure (or the port's) is logged without
 * any identity detail and never reaches the sign-in response. @complexity O(1) here. */
function signalAdminSignIn({ deps, principalId, port }: { deps: SessionAuthDeps; principalId: string; port: AdminSignInPort | undefined }, _optional = {}): void {
  if (!port) return;
  void isOwnerOrBuiltinAdmin({ deps, principalId })
    .then((eligible) => { if (eligible) port.signedIn(); })
    .catch(() => console.warn("[admin-auth] post-sign-in form pull check failed; sign-in is unaffected"));
}

/** Shared request metadata for every ordinary owner session. O(1), no I/O. */
function sessionRequestOptions({ req }: { req: Request }) {
  return { ip: req.ip, userAgent: req.get("user-agent") ?? undefined, sessionTtlMs: SESSION_TTL_MS };
}

/** MFA proofs are strings; objects/numbers never become bearer tokens by coercion. O(1). */
function mfaBodyText({ req, key }: { req: Request; key: string }): string {
  return typeof req.body?.[key] === "string" ? req.body[key] as string : "";
}

/** Registers login/logout/me and the loopback boot exchange before the admin session gate.
 * `onAdminSignIn` hears every owner/admin sign-in: password login and both boot-session exchanges. */
export function registerAuthRoutes(app: Express, deps: RouteDeps,
  { localOwnerSignIn = bootLocalOwnerSignIn, onAdminSignIn }: { localOwnerSignIn?: LocalOwnerSignInPolicy; onAdminSignIn?: AdminSignInPort } = {},
): void {
  // REQ-14/AC-18: LOGIN_STRICT (10 req/60s per client IP) brute-force guard on
  // AUTH_LOGIN. One limiter instance per `registerAuthRoutes` call, so each
  // `createApp()`/`createRouteDeps()` pair (and therefore each test's server)
  // gets an isolated counter store rather than sharing process-wide state.
  const loginRateLimiter = createRateLimiter({ profile: LOGIN_STRICT, clock: { nowMs: () => Date.parse(deps.clock.nowIso()) } });

  registerOwnerRecoveryRoutes({ app, deps, limiter: loginRateLimiter,
    authenticate: req => currentPrincipal(deps, req, { localOwnerSignIn }),
    desktopOwnerReset: localOwnerSignIn.enabled && !!localOwnerSignIn.acceptsCapability,
    ...(localOwnerSignIn.acceptsCapability ? { acceptsDesktopCapability: localOwnerSignIn.acceptsCapability } : {}) });

  registerOwnerMfaRoutes({ app, deps, limiter: loginRateLimiter,
    authenticate: req => currentCredential(deps, req, { localOwnerSignIn }) });
  registerOwnerPasskeyRoutes({ app, deps, limiter: loginRateLimiter,
    authenticate: req => currentCredential(deps, req, { localOwnerSignIn }),
    signedIn: async (req, res, result) => {
      await revokeRequestSessions({ deps, req });
      setSessionCookie(res, result.rawToken, result.session.expiresAt);
      const user = await deps.userRepo.findByPrincipalId({ workspaceId: deps.workspaceId, principalId: result.principal.id });
      signalAdminSignIn({ deps, principalId: result.principal.id, port: onAdminSignIn });
      res.json({ user: { id: result.principal.id, username: user?.username ?? result.principal.displayName } });
    },
  });

  app.post("/api/admin/v1/auth/login", async (req, res) => {
    try {
      await deps.identityReady;

      // Client-IP resolution (api.spec §3): no explicit trusted-proxy list is supplied here.
      // resolveClientIp falls back to Express's req.ip under the host's trust-proxy policy,
      // or the socket peer; an untrusted X-Forwarded-For is never honored.
      const clientIp = resolveClientIp(req);
      const rateLimitResult = await loginRateLimiter.check({ key: clientIp });
      if (!rateLimitResult.allowed) {
        res.setHeader("Retry-After", String(rateLimitResult.retryAfterSeconds));
        res.status(429).json({
          error: "too many login attempts",
          code: "RATE_LIMIT_EXCEEDED",
          details: { retryAfterSeconds: rateLimitResult.retryAfterSeconds },
        });
        return;
      }

      const username = String(req.body?.username ?? "");
      const password = String(req.body?.password ?? "");

      const result = deps.mfaStore
        ? await beginOwnerLogin({ deps: await ownerMfaDepsFrom({ deps }), input: { workspaceId: deps.workspaceId, username, password } },
          sessionRequestOptions({ req }))
        : await login({
        deps: authServiceDepsFrom(deps),
        input: {
          workspaceId: deps.workspaceId,
          username,
          password,
        },
      }, sessionRequestOptions({ req }));

      res.setHeader("Cache-Control", "no-store");
      if ("mfaRequired" in result) { res.json(result); return; }
      const { principal, session, rawToken } = result;

      // Credentials succeeded; revoke both superseded bearers before clearing/replacing cookies.
      await revokeRequestSessions({ deps, req });
      setSessionCookie(res, rawToken, session.expiresAt);
      signalAdminSignIn({ deps, principalId: principal.id, port: onAdminSignIn });
      res.json({ user: { id: principal.id, username } });
    } catch (err) {
      if (err instanceof AuthInvalidCredentialsError) {
        res.status(401).json({ error: "invalid username or password", code: "UNAUTHENTICATED" });
        return;
      }
      sendAuthFailure({ res, error: err, operation: "login" });
    }
  });

  app.post("/api/admin/v1/auth/mfa/login", async (req, res) => {
    res.setHeader("Cache-Control", "no-store");
    try {
      const rate = await loginRateLimiter.check({ key: resolveClientIp(req) });
      if (!rate.allowed) {
        res.setHeader("Retry-After", String(rate.retryAfterSeconds));
        res.status(429).json({ error: "Too many authenticator attempts. Wait a minute and try again.", code: "RATE_LIMIT_EXCEEDED" });
        return;
      }
      const result = await completeOwnerLogin({ deps: await ownerMfaDepsFrom({ deps }),
        input: { workspaceId: deps.workspaceId, pendingToken: mfaBodyText({ req, key: "pendingToken" }),
          code: mfaBodyText({ req, key: "code" }) } },
      sessionRequestOptions({ req }));
      await revokeRequestSessions({ deps, req });
      setSessionCookie(res, result.rawToken, result.session.expiresAt);
      const user = await deps.userRepo.findByPrincipalId({ workspaceId: deps.workspaceId, principalId: result.principal.id });
      signalAdminSignIn({ deps, principalId: result.principal.id, port: onAdminSignIn });
      res.json({ user: { id: result.principal.id, username: user?.username ?? result.principal.displayName } });
    } catch (error) {
      if (error instanceof IdentityValidationError) { res.status(400).json({ error: error.message, code: "MFA_REFUSED" }); return; }
      sendAuthFailure({ res, error, operation: "login" });
    }
  });

  app.post("/api/admin/v1/auth/logout", async (req, res) => {
    // Express 4 drops a rejected async handler, so without this a failing identity bootstrap or
    // session store leaves the request hanging instead of answering like the login route does.
    try {
      await deps.identityReady;
      await revokeRequestSessions({ deps, req });
      clearSessionCookie(res);
      res.json({ ok: true });
    } catch (error) {
      sendAuthFailure({ res, error, operation: "logout" });
    }
  });

  /**
   * Exchange a single-use boot token for an ordinary admin session.
   *
   * Exists so a process that STARTED this server can prove it started it without knowing a
   * password. The token is minted only when the launcher passed `--emit-boot-token`, lives in this
   * process's memory for one launch, and is destroyed on first redemption
   * (`features/identity/boot-session-token.ts`).
   *
   * **This route knows nothing about who is calling it.** No desktop/Electron branch, no
   * `TOVU_DESKTOP_*` name — the contract is only "a valid single-use loopback token starts a
   * session", so nothing here has to change or be removed if a particular launcher goes away.
   *
   * Every rejection is a flat 401 with no distinguishing detail: unarmed, wrong, and already-spent
   * are indistinguishable to a caller, so this cannot be used as an oracle for whether a token
   * exists. There is deliberately NO arm in which an unminted token means "allow" — an unarmed
   * store refuses every input, so an ordinary `tovu serve` (which mints nothing) has this route
   * present but permanently closed.
   *
   * The session it creates is an ordinary one: a real, revocable `sessions` row bound to the seeded
   * owner principal, resolved by the same `validateSession` and gated by the same `authorize()` as
   * a password login. Nothing downstream can tell the difference, and no bypass flag is threaded
   * anywhere.
   */
  app.post("/api/admin/v1/auth/boot-session", async (req, res, next) => {
    // Checked before the token is even looked at, so a remote caller cannot probe redemption.
    if (!isLoopbackPeer(req)) {
      res.status(403).json({ error: "boot-session is loopback-only", code: "FORBIDDEN" });
      return;
    }
    try {
      const principal = await redeemOwnerBootSession({ deps, res, token: req.body?.token });
      if (!principal) return;
      signalAdminSignIn({ deps, principalId: principal.id, port: onAdminSignIn });
      res.json({ user: { id: principal.id } });
    } catch (error) { next(error); }
  });

  // Desktop must present its private launch capability before browser-style header admission.
  // The browser has no private parent stdout pipe. A launcher-armed, same-origin loopback
  // request uses a request-scoped one-time token; no raw boot token is exposed to JS or logs.
  // Separate stores prevent concurrent tabs, or the desktop's still-armed token, burning each other.
  app.post("/api/admin/v1/auth/local-boot-session", async (req, res, next) => {
    if (!localOwnerSignIn.enabled || (localOwnerSignIn.acceptsCapability &&
      !localOwnerSignIn.acceptsCapability({ capability: req.get("x-tovu-desktop-owner-signin") }))) {
      res.status(404).json({ error: "local owner sign-in is disabled", code: "NOT_FOUND" });
      return;
    }
    if (!isLoopbackPeer(req) || !allowsLocalOwnerSignInRequest({
      host: req.headers.host, origin: req.get("origin"), fetchSite: req.get("sec-fetch-site"),
      fetchMode: req.get("sec-fetch-mode"), headers: req.headers,
    })) {
      res.status(403).json({ error: "local owner sign-in requires a same-origin loopback request", code: "FORBIDDEN" });
      return;
    }
    res.setHeader("Cache-Control", "no-store");
    try {
      // Keep an existing human session; auto sign-in must never promote a non-owner account.
      const existing = await currentPrincipal(deps, req, { localOwnerSignIn });
      if (existing) { res.json({ user: { id: existing.id } }); return; }
      const store = createBootSessionTokenStore();
      const principal = await redeemOwnerBootSession({ deps, res, token: store.mint() }, {
        redeem: store.redeem, cookieName: localSessionCookieName(req),
      });
      if (!principal) return;
      signalAdminSignIn({ deps, principalId: principal.id, port: onAdminSignIn });
      res.json({ user: { id: principal.id } });
    } catch (error) { next(error); }
  });

  app.get("/api/admin/v1/auth/me", async (req, res) => {
    const principal = await currentPrincipal(deps, req, { localOwnerSignIn });
    if (!principal) {
      res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
      return;
    }

    const userRow = await deps.userRepo.findByPrincipalId({
      workspaceId: deps.workspaceId,
      principalId: principal.id,
    });
    const effectivePermissions = await getEffectivePermissions({
      deps: identityReposFrom(deps),
      input: { workspaceId: deps.workspaceId, principalId: principal.id },
    });
    // Delete-user plan v2 (2026-09-24), Slice 4 — the admin Users screen's row-menu Delete item
    // needs to know, for the SIGNED-IN caller, whether they are actually allowed to trash/restore/
    // purge users (the OWNER DECISION 2026-09-24 gate: owner or the built-in `admin` role — see
    // `delete-user-service.ts`'s `callerMayManageUserTrash` for why that is NOT the same test as
    // `effectivePermissions.includes("*")`: the built-in admin role deliberately holds no `user.
    // manage`/`*` grant, so a permission-string check alone would hide a working affordance from an
    // admin-role caller even though the DELETE route itself already lets them use it). Reuses the
    // exact function the route layer and the Trash restore/purge override both gate on, so this
    // affordance-hiding flag can never drift from the real boundary — see that function's own doc
    // comment ("NOT A SECURITY BOUNDARY", `lib/permissions.ts`'s header on the admin side).
    const authServiceDeps = authServiceDepsFrom(deps);
    const canManageUserTrash = await callerMayManageUserTrash({
      deps: authServiceDeps,
      workspaceId: deps.workspaceId,
      callerPrincipalId: principal.id,
    });

    res.json({
      user: { id: principal.id, username: userRow?.username ?? principal.displayName },
      effectivePermissions,
      canManageUserTrash,
      // Affordance flag, not the boundary: the admin hides every Publish entry point when this is
      // `false` (the live site); the push routes refuse on their own (`live-site-policy.ts`).
      canPublishToLive: canPublishToLive(),
    });
  });

  // Password-banner plan (2026-09-24), Slice 2: tells the DASHBOARD (not deployment-overview,
  // which is owner-only and `system.read`-gated) whether the SIGNED-IN CALLER's own stored
  // credential still verifies against `DEFAULT_OWNER_PASSWORD`. No extra permission is needed —
  // it's a check against your own row, so it can't be used to probe anyone else's password.
  // Deliberately a separate route from `/auth/me` rather than a field on it: that route runs on
  // every admin boot, and only the dashboard needs the ~tens-of-ms argon2id verify this adds.
  //
  // Results are memoized by the stored hash: argon2id is deliberately expensive, and a signed-in
  // session could otherwise call this in a loop. A hash is salted per write, so any password change
  // produces a new key and is re-verified — the cache can never report a stale answer. Capped and
  // cleared wholesale; it only holds hashes already in the DB and booleans.
  const defaultPasswordByHash = new Map<string, boolean>();
  const usesDefaultPasswordFor = async (passwordHash: string): Promise<boolean> => {
    const cached = defaultPasswordByHash.get(passwordHash);
    if (cached !== undefined) return cached;
    const result = await deps.passwordHasher.verify({ hash: passwordHash, password: DEFAULT_OWNER_PASSWORD });
    if (defaultPasswordByHash.size >= 256) defaultPasswordByHash.clear();
    defaultPasswordByHash.set(passwordHash, result);
    return result;
  };
  app.get("/api/admin/v1/auth/me/password-status", async (req, res) => {
    const principal = await currentPrincipal(deps, req, { localOwnerSignIn });
    if (!principal) {
      res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
      return;
    }

    const userRow = await deps.userRepo.findByPrincipalId({
      workspaceId: deps.workspaceId,
      principalId: principal.id,
    });
    const usesDefaultPassword = userRow
      ? await usesDefaultPasswordFor(userRow.passwordHash)
      : false;

    res.json({ usesDefaultPassword });
  });
}

import { pluginHookRefusalText } from "#src/contracts/core/plugin-hook-failed-error";
import { PluginHookFailedError } from "@jini-ai/plugins/host";
import { redactSecretShapes } from "@tovu/contracts/secret-redaction";

/**
 * @file P0c fix (hooks v2 plan, 2026-09-23) — `PluginHookFailedError`'s own doc comment
 * (`hook-registry.ts`) has always claimed it is "caught by the caller, mapped to 500
 * `PLUGIN_HOOK_FAILED`", but no route ever actually did that: every content-save route's local
 * `send*Error` function fell through to the generic `{error:"internal error"}` 500 with no `code`
 * at all, so a client (admin UI or an agent tool) could never tell a plugin's hook failure apart
 * from any other internal error. One shared function so every content-save route's error mapper
 * gets the SAME shape instead of re-typing it (and risking a drift) at each call site.
 */

/** The only part of Express's `Response` this function writes through (`status().json()`). Narrow
 *  so a caller's real `Response` fits as-is and a unit test can pass a two-method capturing fake. */
export interface PluginHookErrorResponse {
  status(code: number): { json(body: unknown): unknown };
}

export interface PluginHookFailedBody {
  readonly error: string;
  readonly code: "PLUGIN_HOOK_FAILED";
  readonly pluginId: string;
}

/**
 * The `PLUGIN_HOOK_FAILED` envelope every HTTP route returns for a hook refusal. `error` is fixed
 * text (`pluginHookRefusalText`, or `publicText` when the route is not a save), never `err.message`:
 * that quotes the plugin's own thrown error, which can carry a credential, SQL or a path — agent
 * tools redact it the same way. The redacted message goes to the server log instead, the only place the
 * cause survives for a preview (a save's also lands in the quarantine reason).
 *
 * @complexity O(n) in the diagnostic text scanned for secrets.
 */
export function pluginHookFailedBody(err: PluginHookFailedError, optional: { publicText?: string } = {}): PluginHookFailedBody {
  // eslint-disable-next-line no-console
  console.warn(redactSecretShapes({ text: `[plugin-runtime] '${err.pluginId}' hook refused a request: ${err.message}` }).text);
  return { error: optional.publicText ?? pluginHookRefusalText(err), code: "PLUGIN_HOOK_FAILED", pluginId: err.pluginId };
}

/**
 * If `err` is a `PluginHookFailedError`, writes the 500 `PLUGIN_HOOK_FAILED` envelope
 * ({@link pluginHookFailedBody}) and returns `true`. Returns `false` (writes nothing) for any other
 * error, so a route's own error mapper can call this first and fall through to its remaining
 * branches unchanged.
 * @complexity O(n) in the diagnostic text when a hook failure is handled.
 */
export function sendPluginHookFailedError(res: PluginHookErrorResponse, err: unknown): boolean {
  if (!(err instanceof PluginHookFailedError)) return false;
  res.status(500).json(pluginHookFailedBody(err));
  return true;
}

import { sendAdminFailure } from './routes/system/site-share-errors.js';
import type { Express, Request, Response } from 'express';
import { IdentityValidationError, OwnerRequiredError } from '@jini-ai/user-management';
import { beginOwnerEnrollment, confirmOwnerEnrollment, removeOwnerFactor } from '@jini-ai/user-management/server';
import type { RouteDeps } from '../../routes/types.js';
import type { RateLimiter } from '#src/contracts/core/rate-limit/rate-limit';
import { resolveClientIp } from '#src/contracts/core/rate-limit/rate-limit';
import { resolveSiteConsentOrigin } from '../public-http/middleware/site-consent.js';
import { ownerMfaDepsFrom } from './owner-mfa-deps.js';

type Admission = { app: Express; deps: RouteDeps; limiter: RateLimiter;
  authenticate: (req: Request) => Promise<{ principal: { id: string }; kind: string } | null> };
type Action = 'enroll' | 'confirm' | 'remove';

/** Only known domain refusals reach the browser; storage exceptions never disclose secrets.
 * @complexity O(1), one response, no request input logged.
 */
function failure(res: Response, error: unknown): void {
  const expected = error instanceof IdentityValidationError || error instanceof OwnerRequiredError;
  if (!expected) {
    sendAdminFailure({ res, error }, { operation: 'owner-authenticator', code: 'MFA_UNAVAILABLE',
      message: 'Authenticator action could not finish.', failure: { step: 'owner-authenticator',
        action: 'Try a new attempt, or use your authenticator app or recovery code to sign in. Copy the error ID if it continues.' } });
    return;
  }
  let status = 503;
  if (expected) status = 400;
  if (error instanceof OwnerRequiredError) status = 403;
  res.status(status).json({
    error: error.message,
    code: 'MFA_REFUSED', details: { operation: 'owner-authenticator' },
  });
}

/** Reject cross-origin or machine credentials before any secret lookup. O(1), bounded headers. */
async function admit({ req, res, admission }: { req: Request; res: Response; admission: Admission }): Promise<string | null> {
  if (!acceptsRequest(req)) {
    res.status(403).json({ error: 'Open this site’s security settings and submit the authenticator action there.', code: 'MFA_ORIGIN_REFUSED' });
    return null;
  }
  const caller = await admission.authenticate(req);
  const ownerId = await admission.deps.ownerPrincipalId;
  if (caller?.kind !== 'session' || caller.principal.id !== ownerId) {
    throw new OwnerRequiredError({ message: 'Sign in as the site owner to change this authenticator.' });
  }
  const rate = await admission.limiter.check({ key: resolveClientIp(req) });
  if (rate.allowed) return ownerId;
  res.setHeader('Retry-After', String(rate.retryAfterSeconds));
  res.status(429).json({ error: 'Too many authenticator attempts. Wait a minute and try again.', code: 'RATE_LIMIT_EXCEEDED' });
  return null;
}

/** Match the existing recovery origin policy before accepting an explicit JSON action. */
function acceptsRequest(req: Request): boolean {
  if (!req.is('application/json') || req.get('sec-fetch-site') === 'cross-site') return false;
  const origin = req.get('origin');
  return !origin || origin === resolveSiteConsentOrigin({ request: req });
}

/** Read only scalar text from the JSON boundary; malformed values are refused by Jini. */
function bodyText(req: Request, key: string): string {
  return typeof req.body?.[key] === 'string' ? req.body[key] : '';
}

/** Explicit owner action only; Jini owns password/factor proof and atomic state changes.
 * @complexity O(1) admission and bounded factor I/O, plus existing owner session revocation.
 */
async function handle({ req, res, action, admission }: { req: Request; res: Response; action: Action; admission: Admission }): Promise<void> {
  res.setHeader('Cache-Control', 'no-store');
  try {
    const ownerId = await admit({ req, res, admission });
    if (!ownerId) return;
    const deps = await ownerMfaDepsFrom(admission);
    const input = { workspaceId: admission.deps.workspaceId, principalId: ownerId,
      password: bodyText(req, 'password'), code: bodyText(req, 'code') };
    if (action === 'enroll') {
      const user = await admission.deps.userRepo.findByPrincipalId(input);
      res.json(await beginOwnerEnrollment({ deps, input: { ...input, label: user?.username ?? 'Owner', issuer: 'Tovu' } }, {}));
      return;
    }
    if (action === 'confirm') await confirmOwnerEnrollment({ deps, input: { ...input,
      pendingToken: bodyText(req, 'pendingToken') } }, {});
    else await removeOwnerFactor({ deps, input }, {});
    res.status(204).send();
  } catch (error) { failure(res, error); }
}

/** Routes precede the admin session gate; each management action admits its own owner session.
 * Status is explicit, not polled. No secret or pending proof is returned by status.
 * @complexity O(1) registration; status performs one indexed factor lookup on explicit load.
 */
export function registerOwnerMfaRoutes(admission: Admission, _options: Record<string, never> = {}): void {
  for (const action of ['enroll', 'confirm', 'remove'] as const) {
    admission.app.post(`/api/admin/v1/auth/mfa/${action}`, (req, res) => handle({ req, res, action, admission }));
  }
  admission.app.get('/api/admin/v1/auth/mfa', async (req, res) => {
    res.setHeader('Cache-Control', 'no-store');
    try {
      const caller = await admission.authenticate(req);
      const isOwner = caller?.kind === 'session' && caller.principal.id === await admission.deps.ownerPrincipalId;
      const factor = isOwner ? await admission.deps.mfaStore?.factor({ workspaceId: admission.deps.workspaceId,
        principalId: caller.principal.id }) : null;
      res.json({ isOwner, available: isOwner && !!admission.deps.mfaStore, enrolled: !!factor });
    } catch (error) { failure(res, error); }
  });
}

import { sendAdminFailure } from './routes/system/site-share-errors.js';
import type { Express, Request, Response } from 'express';
import { IdentityValidationError, OwnerRequiredError } from '@jini-ai/user-management';
import { beginOwnerPasskeyEnrollment, confirmOwnerPasskeyEnrollment, beginOwnerPasskeyLogin, completeOwnerPasskeyLogin,
  removeOwnerPasskey, createSimpleWebAuthnPasskeys, type OwnerPasskeyDeps } from '@jini-ai/user-management/server';
import type { RouteDeps } from '../../routes/types.js';
import type { RateLimiter } from '#src/contracts/core/rate-limit/rate-limit';
import { resolveClientIp } from '#src/contracts/core/rate-limit/rate-limit';
import { ownerMfaDepsFrom } from './owner-mfa-deps.js';

type Admission = { app: Express; deps: RouteDeps; limiter: RateLimiter;
  authenticate: (req: Request) => Promise<{ principal: { id: string }; kind: string } | null>;
  signedIn: (req: Request, res: Response, result: Awaited<ReturnType<typeof completeOwnerPasskeyLogin>>) => Promise<void> };
type Action = 'enroll' | 'confirm' | 'begin-login' | 'login' | 'remove';

/** Trusted composition origin includes the public port; localhost uses the actual listener port.
 * Request Host, Origin and forwarding headers never select the RP or expected origin. O(1).
 */
export function ownerPasskeySite({ deps, localPort }: { deps: Pick<RouteDeps, 'passkeyOrigin' | 'derivedPublicOrigin'>; localPort?: number }, _options: Record<string, never> = {}) {
  const configured = deps.passkeyOrigin ?? deps.derivedPublicOrigin;
  if (!configured) throw new IdentityValidationError({ message: 'Passkeys are unavailable in this host. Use your authenticator app or recovery code.' });
  const url = new URL(configured);
  if (url.protocol !== 'https:' && !(url.protocol === 'http:' && url.hostname === 'localhost')) {
    throw new IdentityValidationError({ message: 'Passkeys require HTTPS or localhost in a supported browser. Use your authenticator app or recovery code here.' });
  }
  if (!deps.passkeyOrigin && url.hostname === 'localhost' && localPort) url.port = String(localPort);
  return { origin: url.origin, rpId: url.hostname, name: 'Tovu' };
}

/** Compose Jini from the serving site's trusted scope and credential adapter; O(1), no poll. */
async function passkeyDeps(admission: Admission, req: Request): Promise<OwnerPasskeyDeps> {
  if (!admission.deps.passkeyStore) throw new IdentityValidationError({ message: 'Passkeys are unavailable in this host. Use your authenticator app or recovery code.' });
  return { mfa: await ownerMfaDepsFrom(admission), credentials: admission.deps.passkeyStore,
    webauthn: createSimpleWebAuthnPasskeys({}, {}), site: ownerPasskeySite({ deps: admission.deps, localPort: req.socket.localPort }) };
}

/** Admission failures reveal no credentials; protocol proofs are never logged. O(1). */
function failure(res: Response, error: unknown): void {
  const expected = error instanceof IdentityValidationError || error instanceof OwnerRequiredError;
  if (!expected) {
    sendAdminFailure({ res, error }, { operation: 'owner-passkey', code: 'PASSKEY_UNAVAILABLE',
      message: 'Passkey action could not finish.', failure: { step: 'owner-passkey',
        action: 'Try a new attempt, or use your authenticator app or recovery code to sign in. Copy the error ID if it continues.' } });
    return;
  }
  res.status(error instanceof OwnerRequiredError ? 403 : 400).json({
    error: error.message,
    code: 'PASSKEY_REFUSED', details: { operation: 'owner-passkey' },
  });
}

/** Authenticate management calls separately; login calls require the password-created pending proof. */
async function admit(admission: Admission, req: Request, action: Action, deps: OwnerPasskeyDeps) {
  if (action === 'begin-login' || action === 'login') return;
  const caller = await admission.authenticate(req);
  if (caller?.kind !== 'session' || caller.principal.id !== deps.mfa.seededOwnerPrincipalId) {
    throw new OwnerRequiredError({ message: 'Sign in as the site owner to manage passkeys.' });
  }
}

/** One single-send ceremony action; cap encoded registration/assertion input before verification.
 * @complexity O(b+n), b <= 16 KiB request bytes and n <= 5 credentials; no polling.
 */
async function handle(admission: Admission, req: Request, res: Response, action: Action): Promise<void> {
  res.setHeader('Cache-Control', 'no-store');
  try {
    const deps = await passkeyDeps(admission, req);
    if (!req.is('application/json') || req.get('sec-fetch-site') === 'cross-site' || req.get('origin') !== deps.site.origin) {
      res.status(403).json({ error: 'Open this site in your browser and start the passkey action there.', code: 'PASSKEY_ORIGIN_REFUSED' }); return;
    }
    if (Buffer.byteLength(JSON.stringify(req.body)) > (action === 'confirm' ? 16384 : 8192)) {
      res.status(413).json({ error: 'This passkey response is too large. Try another passkey or your authenticator app.', code: 'PASSKEY_TOO_LARGE' }); return;
    }
    const rate = await admission.limiter.check({ key: resolveClientIp(req) });
    if (!rate.allowed) { res.setHeader('Retry-After', String(rate.retryAfterSeconds));
      res.status(429).json({ error: 'Too many passkey attempts. Wait a minute and try again.', code: 'RATE_LIMIT_EXCEEDED' }); return; }
    await admit(admission, req, action, deps);
    await execute(admission, req, res, action, deps);
  } catch (error) { failure(res, error); }
}

/** Transport-only dispatch; scope never comes from the request body. */
async function execute(admission: Admission, req: Request, res: Response, action: Action, deps: OwnerPasskeyDeps) {
  const value = (key: string) => typeof req.body?.[key] === 'string' ? req.body[key] as string : '';
  const input = { workspaceId: admission.deps.workspaceId, principalId: deps.mfa.seededOwnerPrincipalId,
    password: value('password'), code: value('code'), pendingToken: value('pendingToken'), response: req.body?.response, id: value('id') };
  switch (action) {
    case 'enroll': res.json(await beginOwnerPasskeyEnrollment({ deps, input })); return;
    case 'confirm': await confirmOwnerPasskeyEnrollment({ deps, input }); break;
    case 'begin-login': res.json(await beginOwnerPasskeyLogin({ deps, input })); return;
    case 'login': await admission.signedIn(req, res, await completeOwnerPasskeyLogin({ deps, input }, { sessionTtlMs: 30 * 24 * 60 * 60 * 1000 })); return;
    case 'remove': await removeOwnerPasskey({ deps, input }); break;
  }
  res.status(204).send();
}

/** Status reads only public credential identifiers for the signed-in owner, once per settings load. */
export function registerOwnerPasskeyRoutes(admission: Admission, _options: Record<string, never> = {}): void {
  for (const action of ['enroll', 'confirm', 'begin-login', 'login', 'remove'] as const) {
    admission.app.post(`/api/admin/v1/auth/passkeys/${action}`, (req, res) => handle(admission, req, res, action));
  }
  admission.app.get('/api/admin/v1/auth/passkeys', async (req, res) => {
    res.setHeader('Cache-Control', 'no-store');
    try {
      const caller = await admission.authenticate(req);
      const isOwner = caller?.kind === 'session' && caller.principal.id === await admission.deps.ownerPrincipalId;
      if (!isOwner) { res.json({ isOwner: false, credentials: [] }); return; }
      const deps = await passkeyDeps(admission, req);
      const credentials = await deps.credentials.list({ workspaceId: admission.deps.workspaceId, principalId: deps.mfa.seededOwnerPrincipalId });
      res.json({ isOwner: true, credentials: credentials.map(c => ({ id: c.id })) });
    } catch (error) { failure(res, error); }
  });
}

import { ownerMfaDepsFrom } from './owner-mfa-deps.js';
import { isLocalAdminRequest } from './local-admin-request.js';
import { resolveSiteConsentOrigin } from '../public-http/middleware/site-consent.js';
import type { Express, Request, Response } from 'express';
import { IdentityValidationError, OwnerRequiredError } from '@jini-ai/user-management';
import { issueRecoveryCodes, recoverOwner, resetOwnerPassword, type OwnerRecoveryDeps } from '@jini-ai/user-management/server';
import type { RouteDeps } from '../../routes/types.js';
import { identityServiceDepsFrom } from './routes/users/deps.js';
import { resolveClientIp, type RateLimiter } from '#src/contracts/core/rate-limit/rate-limit';

type Admission = {
  app: Express;
  deps: RouteDeps;
  authenticate: (req: Request) => Promise<{ id: string } | null>;
  limiter: RateLimiter;
  desktopOwnerReset: boolean;
  acceptsDesktopCapability?: (input: { capability: string | undefined }) => boolean;
};
type Action = 'issue' | 'recover' | 'reset';

/** Reject cross-site submissions and require a JSON body before touching secrets.
 * @complexity O(1), bounded request headers; no I/O.
 */
function acceptsRecoveryRequest(req: Request): boolean {
  if (!req.is('application/json') || req.get('sec-fetch-site') === 'cross-site') return false;
  const origin = req.get('origin');
  return !origin || origin === resolveSiteConsentOrigin({ request: req });
}

/** Map only known safe validation messages; raw exception details may contain SQL or credentials.
 * @complexity O(1), one response; never logs request input.
 */
function recoveryFailure({ res, error, action }: { res: Response; error: unknown; action: Action }): void {
  const expected = error instanceof IdentityValidationError || error instanceof OwnerRequiredError;
  res.status(error instanceof OwnerRequiredError ? 403 : expected ? 400 : 503).json({
    error: expected ? error.message : 'Owner recovery could not be saved. Retry once, then ask the host operator to check the identity database.',
    code: expected ? 'RECOVERY_REFUSED' : 'RECOVERY_UNAVAILABLE',
    details: { operation: `owner-recovery-${action}` },
  });
}

/** Bind server-selected scope to Jini; callers cannot choose another principal or workspace.
 * @complexity O(1) composition, waiting for existing identity bootstrap only.
 */
async function recoveryDeps({ deps }: Pick<Admission, 'deps'>): Promise<OwnerRecoveryDeps> {
  await deps.identityReady;
  if (!deps.recoveryCodes) throw new Error('Durable recovery storage is not configured');
  return { ...(deps.mfaStore ? { mfa: await ownerMfaDepsFrom({ deps }) } : {}), auth: identityServiceDepsFrom(deps), codes: deps.recoveryCodes, seededOwnerPrincipalId: await deps.ownerPrincipalId };
}

/** Reset requires this request's private launch proof as well as local transport and owner session.
 * No cookie alone proves possession of the launcher's capability. An enrolled owner can recover
 * with that private proof without first obtaining the MFA-gated normal session.
 * @complexity O(h) in request header names; no I/O.
 */
function acceptsDesktopReset({ req, admission }: { req: Request; admission: Admission }): boolean {
  return admission.desktopOwnerReset && isLocalAdminRequest({ req }) &&
    admission.acceptsDesktopCapability?.({ capability: req.get('x-tovu-desktop-owner-signin') }) === true;
}

/** Require an existing owner session for kit issuance and the desktop reset transition.
 * The launch-proof exchange remains the existing local-boot-session route, preserving staff sessions.
 * @complexity O(1), one session admission plus already-resolved owner identity.
 */
async function admitOwner({ req, action, admission, ownerId }: { req: Request; action: Action; admission: Admission; ownerId: string }): Promise<void> {
  if (action === 'recover' || (action === 'reset' && acceptsDesktopReset({ req, admission }))) return;
  const caller = await admission.authenticate(req);
  if (!caller || caller.id !== ownerId || (action === 'reset' && !acceptsDesktopReset({ req, admission }))) {
    throw new OwnerRequiredError({ message: 'Sign in as the site owner to use this recovery action. On desktop, reopen the site to restore your owner session.' });
  }
}

/** One explicit mutation per request; shares LOGIN_STRICT with password login to bound guessing.
 * @complexity O(s) for reset's existing session revocation, otherwise ten fixed hash rows.
 */
async function handleRecovery({ req, res, action, admission }: { req: Request; res: Response; action: Action; admission: Admission }): Promise<void> {
  res.setHeader('Cache-Control', 'no-store');
  try {
    if (!acceptsRecoveryRequest(req)) {
      res.status(403).json({ error: 'Recovery requires a same-origin JSON request. Open the site sign-in page and try again.', details: { operation: 'owner-recovery-origin' } });
      return;
    }
    const rate = await admission.limiter.check({ key: resolveClientIp(req) });
    if (!rate.allowed) {
      res.setHeader('Retry-After', String(rate.retryAfterSeconds));
      res.status(429).json({ error: 'Too many recovery attempts. Wait a minute and try again.', details: { operation: 'owner-recovery-limit' } });
      return;
    }
    const deps = await recoveryDeps(admission);
    await admitOwner({ req, action, admission, ownerId: deps.seededOwnerPrincipalId });
    const field = (key: 'password' | 'code') => typeof req.body?.[key] === 'string' ? req.body[key] as string : '';
    const input = { workspaceId: admission.deps.workspaceId, principalId: deps.seededOwnerPrincipalId,
      password: field('password'), code: field('code') };
    if (action === 'issue') {
      res.json(await issueRecoveryCodes({ deps, input }, {}));
      return;
    }
    if (action === 'recover') await recoverOwner({ deps, input }, {});
    else await resetOwnerPassword({ deps, input }, {});
    res.status(204).send();
  } catch (error) { recoveryFailure({ res, error, action }); }
}

/** Register before the admin session gate so a code can recover a locked-out owner.
 * @complexity O(1) registration. Status reads no kit: only one authenticated owner comparison.
 */
export function registerOwnerRecoveryRoutes(admission: Admission, _options: Record<string, never> = {}): void {
  for (const [path, action] of [['recovery-codes', 'issue'], ['recover-owner', 'recover'], ['reset-owner', 'reset']] as const) {
    admission.app.post(`/api/admin/v1/auth/${path}`, (req, res) => handleRecovery({ req, res, action, admission }));
  }
  admission.app.get('/api/admin/v1/auth/owner-recovery', async (req, res) => {
    res.setHeader('Cache-Control', 'no-store');
    try {
      const caller = await admission.authenticate(req);
      const isOwner = !!caller && caller.id === await admission.deps.ownerPrincipalId;
      res.json({ isOwner, available: isOwner && !!admission.deps.recoveryCodes, desktopOwnerReset: isOwner && admission.desktopOwnerReset });
    } catch (error) { recoveryFailure({ res, error, action: 'issue' }); }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";

import {
  adminSurfaceBootstrapHeaders,
  createAdminSurfaceActionDispatcher,
  createAdminSurfaceBootstrap,
  type LoadedAdminSurface,
} from "@jini-ai/agent-plugins/admin-surfaces";

import {
  NO_ADMIN_SURFACE_HOST,
  ADMIN_SURFACE_ACTION_PERMISSION,
  withAdminSurfaceSignIns,
  adminSurfaceFileUrl,
  createAgentPluginAdminSurfaceSource,
  findAdminSurface,
  type AdminSurfaceHost,
  type AdminSurfaceRequestContext,
  type AdminSurfaceSource,
} from "#src/features/agent-plugins/admin-surfaces/surfaces";
import { isSameOriginAdminWrite } from "#src/features/agent-plugins/admin-surfaces/same-origin";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteDeps, AgentPluginsRouteRegistrar } from "./deps.js";

/**
 * @file Admin routes for plugin-owned admin surfaces (Jini `@jini-ai/agent-plugins/admin-surfaces`):
 *
 * - `AGENT_PLUGIN_SURFACES` `GET  .../agent-plugins/:pluginId/surfaces` — the admitted surfaces of
 *   one plugin (id, title, frame `src`, declared actions for the host page's early refusal), for the
 *   details modal's tabs. `admin.plugins.read`.
 * - `AGENT_PLUGIN_SURFACE_BOOTSTRAP` `POST .../surfaces/:surfaceId/bootstrap` — the short-lived,
 *   never-cached start data the host page passes into the frame's `init`. `admin.plugins.enable`.
 * - `AGENT_PLUGIN_SURFACE_ACTION` `POST .../surfaces/:surfaceId/actions` — runs one declared action
 *   through Jini's dispatcher (which re-checks the declaration and schemas, because this route can be
 *   called directly). `admin.plugins.enable`.
 *
 * Why the two POSTs need more than the session: bootstrap data may carry a short-lived access token
 * and actions run host handlers, so both refuse API-key credentials (a surface is a browser UI) and
 * cross-origin requests (`same-origin.ts`) BEFORE authorization or any lookup. The surface files
 * themselves are served by the public route in `public-http/routes/agent-plugin-surfaces/files.ts`,
 * because a sandboxed frame's module-script fetches carry no cookie.
 *
 * Ids from the URL are only compared against admitted surfaces, never joined into a path. Errors
 * never echo handler text; the dispatcher already maps throws to surface-safe failures. An action
 * that started a sign-in also returns `hostSignIns`: the authorization links the host itself issued
 * during that request (`issued-sign-ins.ts`), which the host page offers to open, because the
 * sandboxed frame cannot and must never choose a URL for the host page to open.
 */

// Route params need no fallback: Express sets every named param of a matched route to a non-empty
// string (an empty segment never matches), and `requireAdminSession` always runs a JSON body parser
// before these handlers, so `req.body` is at least `{}` (both pinned in the routes integration test).
const WRITE_PERMISSION = ADMIN_SURFACE_ACTION_PERMISSION;
const SURFACE_PATH = "/api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/surfaces";

function sourceFor(deps: AgentPluginsRouteDeps): AdminSurfaceSource {
  return deps.adminSurfaceSource ?? createAgentPluginAdminSurfaceSource({ lifecycle: deps.agentPluginLifecycle });
}

/** Workspace check + permission; `false` when a response was already sent. @complexity O(1) + authorize. */
async function admit(req: Request, res: Response, deps: AgentPluginsRouteDeps, permission: string): Promise<boolean> {
  if (String(req.params.workspaceId) !== deps.workspaceId) {
    res.status(404).json({ error: "workspace was not found" });
    return false;
  }
  return authorizeOrRespond(res, deps.authorize, { principalId: getAuthedPrincipal(res).id, permission, workspaceId: deps.workspaceId });
}

/** The CSRF and credential-kind gates for the two writes; `false` when a 403 was already sent.
 * @complexity O(1). */
function admitWrite(req: Request, res: Response): boolean {
  if (!isSameOriginAdminWrite({ origin: req.get("origin"), host: req.get("host"), fetchSite: req.get("sec-fetch-site") })) {
    res.status(403).json({ error: "admin surface requests must come from the admin page itself", code: "CROSS_ORIGIN_REFUSED" });
    return false;
  }
  return rejectUnlessSessionCredential(res, { message: "admin surfaces accept only a signed-in admin session", permission: WRITE_PERMISSION });
}

/** Resolves the URL's surface, or sends 404. @complexity O(s) admitted surfaces. */
async function surfaceOrRespond(req: Request, res: Response, deps: AgentPluginsRouteDeps): Promise<LoadedAdminSurface | undefined> {
  const surface = await findAdminSurface({ source: sourceFor(deps), workspaceId: deps.workspaceId, pluginId: String(req.params.pluginId), surfaceId: String(req.params.surfaceId) });
  if (!surface) res.status(404).json({ error: "admin surface was not found", code: "ADMIN_SURFACE_NOT_FOUND" });
  return surface;
}

function contextFor(res: Response, deps: AgentPluginsRouteDeps, surface: LoadedAdminSurface): AdminSurfaceRequestContext {
  return { workspaceId: deps.workspaceId, principalId: getAuthedPrincipal(res).id, pluginId: surface.plugin.pluginId, surfaceId: surface.descriptor.id };
}

/** Runs a handler body; any throw becomes a generic 500 that names no server detail. */
async function guarded(res: Response, body: () => Promise<void>): Promise<void> {
  try { await body(); } catch (error) { sendAdminFailure({ res, error }, { operation: "routes/agent-plugins/admin-surfaces", code: "INTERNAL_ERROR" }); }
}

export const registerAgentPluginAdminSurfaceRoutes: AgentPluginsRouteRegistrar = (app: Express, deps) => {
  app.get(SURFACE_PATH, (req, res) => guarded(res, async () => {
    if (!(await admit(req, res, deps, "admin.plugins.read"))) return;
    const pluginId = String(req.params.pluginId);
    const surfaces = (await sourceFor(deps).list({ workspaceId: deps.workspaceId })).filter((surface) => surface.plugin.pluginId === pluginId);
    res.json({ pluginId, surfaces: surfaces.map(({ descriptor }) => ({ id: descriptor.id, title: descriptor.title, src: adminSurfaceFileUrl({ pluginId, surfaceId: descriptor.id, path: descriptor.entry }), actions: descriptor.actions, linkOrigins: descriptor.linkOrigins ?? [] })) });
  }));

  app.post(`${SURFACE_PATH}/:surfaceId/bootstrap`, (req, res) => guarded(res, async () => {
    if (!admitWrite(req, res) || !(await admit(req, res, deps, WRITE_PERMISSION))) return;
    const surface = await surfaceOrRespond(req, res, deps);
    if (!surface) return;
    const host = deps.adminSurfaceHost ?? NO_ADMIN_SURFACE_HOST;
    const data = await host.bootstrapData({ context: contextFor(res, deps, surface) });
    res.set(adminSurfaceBootstrapHeaders()).json(createAdminSurfaceBootstrap({ surfaceId: surface.descriptor.id, data, nowMs: deps.clock.nowMs() }));
  }));

  app.post(`${SURFACE_PATH}/:surfaceId/actions`, (req, res) => guarded(res, async () => {
    if (!admitWrite(req, res) || !(await admit(req, res, deps, WRITE_PERMISSION))) return;
    const surface = await surfaceOrRespond(req, res, deps);
    if (!surface) return;
    const body = req.body as { action?: unknown; payload?: unknown };
    if (typeof body.action !== "string") {
      res.status(400).json({ error: "the request must name an action", code: "INVALID_REQUEST" });
      return;
    }
    const host = deps.adminSurfaceHost ?? NO_ADMIN_SURFACE_HOST;
    const dispatcher = createAdminSurfaceActionDispatcher({ descriptor: surface.descriptor, handlers: host.handlersFor({ pluginId: surface.plugin.pluginId, surfaceId: surface.descriptor.id }) }, {
      // Only the error's class reaches the log: a handler's message could quote provider detail.
      onHandlerError: ({ surfaceId, action, error }) => console.error("[admin-surfaces] action handler failed", { pluginId: surface.plugin.pluginId, surfaceId, action, error: error instanceof Error ? error.name : typeof error }),
    });
    const { action, payload } = body;
    res.set("Cache-Control", "no-store").json(await withAdminSurfaceSignIns({ host, run: () => dispatcher.dispatch({ action, payload, context: contextFor(res, deps, surface) }) }));
  }));
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { preferBundledAgentPluginDigests, readBundledAgentPluginDigests } from "../../../../../features/agent-plugins/lifecycle.js";
import { listInstalledPlugins } from "../../../../../features/agent-plugins/lifecycle.js";
import { PLUGIN_PACKAGE_FILE_LIMITS, readPluginPackageFiles } from "@jini-ai/plugins/host/node";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteRegistrar } from "./deps.js";

/**
 * @file `AGENT_PLUGIN_FILES` — `GET /api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/files`
 * (2026-09-13). The Agent Plugins screen's read-only package-files viewer: every file in ONE
 * installed Agent Plugin's own package root, switched on or off. It replaced the admin bundle's
 * compile-time catalog as that viewer's source — the catalog only knew hand-listed plugins, so
 * `supabase` and `tovuize-site` opened an empty viewer.
 *
 * Mirrors `plugins/files.ts`. Gated on `admin.plugins.read` and authorized BEFORE the id is looked
 * up. The id must equal an installed plugin's own manifest id from a fresh `listInstalledPlugins`
 * walk, so request text is never joined into a path. The first record per id wins — the same
 * single-digest policy `loadAgentPluginSearchCandidates` applies, so the viewer shows the package
 * the listing describes. Path safety (realpath inside this workspace's `packages` directory,
 * symlinks listed but never followed, count and byte caps) is `readPluginPackageFiles`'s.
 *
 * Activation is deliberately not consulted: reading a switched-off plugin's files executes nothing.
 */
export const registerAgentPluginFilesRoute: AgentPluginsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/files", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pluginId = String(req.params.pluginId ?? "");

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.plugins.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const workspaceLayout = deps.agentPluginLayout.forWorkspace(deps.workspaceId);
      // An upgraded bundled plugin's superseded package is dropped first, so this browses the
      // version the running build ships rather than whichever digest the walk reached first.
      const plugin = preferBundledAgentPluginDigests(
        await listInstalledPlugins(workspaceLayout.root),
        await readBundledAgentPluginDigests(workspaceLayout.root),
      ).find((candidate) => candidate.pluginId === pluginId);
      if (!plugin) {
        res.status(404).json({ error: "agent plugin was not found", code: "AGENT_PLUGIN_NOT_FOUND" });
        return;
      }

      const { files, truncated } = await readPluginPackageFiles({
        input: { rootDir: plugin.packageRoot, containerDir: workspaceLayout.pluginPackagesDir({ pluginId }) },
      });
      res.json({ pluginId, files, truncated, limits: PLUGIN_PACKAGE_FILE_LIMITS });
    } catch (error) {
      // Includes `PluginPackagePathError`, whose message names server paths — never echoed.
      sendAdminFailure({ res, error }, { operation: "routes/agent-plugins/files", code: "INTERNAL_ERROR" });
    }
  });
};

import { createAgentPluginUpdateEffects, requireUpdateMcpDeps } from "#src/features/agent-plugins/update-effects";
import type { Request, RequestHandler, Response } from "express";
import { raw } from "express";

import { maxAgentPluginInstallArchiveBytes } from "../../../../../features/agent-plugins/lifecycle.js";
import { installUploadedAgentPlugin } from "#src/features/agent-plugins/install-upload";
import { isAgentPluginName } from "@jini-ai/agent-plugins/lifecycle";
import { loadAgentPluginSearchCandidates } from "#src/features/agent-plugins/tool-registrations";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteDeps, AgentPluginsRouteRegistrar } from "./deps.js";
import { bodyParseRefusal, installErrorResponse, installedAgentPluginRow, type InstallRefusal } from "./install-response.js";

/**
 * @file `AGENT_PLUGIN_INSTALL_ZIP` — `POST /api/admin/v1/workspaces/:workspaceId/agent-plugins/install/zip?expectedSha256=<hex>`
 * (2026-10-06). The Agent Plugins screen's "Add a plugin" upload. Raw `application/zip` body, the
 * same transport `routes/plugins/install.ts` uses for site plugins; all install work is
 * `installUploadedAgentPlugin` (`features/agent-plugins/install-upload.ts`), which goes through
 * the one `installAgentPlugin` the bundled seed uses and leaves the plugin switched off.
 *
 * No `TOVU_PLUGIN_LOCAL_INSTALL` opt-in, unlike site plugins: those packages run server code, while
 * nothing in an uploaded Agent Plugin runs (`trusted-plugin-files.ts` trusts bundled digests only).
 * Gated on `admin.plugins.enable`, the permission the enable switch beside it already needs.
 *
 * Answers 201 with the new row in `list.ts`'s shape, or 200 when the same bytes were already there.
 * Error bodies carry a code and a plain message; no host path ever reaches them.
 *
 * `AGENT_PLUGIN_UPDATE_ZIP` — `POST .../agent-plugins/:pluginId/update/zip?expectedSha256=&expectedOldDigest=`
 * (2026-10-21) shares this handler: the same upload checks, then `installUploadedAgentPlugin({ update })`,
 * which hands the candidate to the lifecycle owner's update transaction. `expectedOldDigest` is the
 * row's `archiveDigest` the operator saw; a changed, bundled, pending or downgraded plugin is a 409
 * with the owner's code. Answers 200 with the updated row and any compatibility warnings.
 */

const DIGEST_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "expectedSha256 must be the file's lowercase hex SHA-256." } };
const NOT_ZIP_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "An application/zip upload is required." } };
const REPLACE_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "replace must be true or false." } };
const PLUGIN_ID_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "pluginId is not a valid Agent Plugin id." } };
const OLD_DIGEST_REFUSAL: InstallRefusal = { status: 400, body: { code: "VALIDATION_ERROR", error: "expectedOldDigest must be the installed revision's lowercase hex SHA-256." } };

/** Which installed revision an update replaces: the URL's plugin id and the digest the operator saw. */
interface UpdateTarget {
  readonly pluginId: string;
  readonly expectedOldDigest: string;
}

/** A checked upload: the zip bytes, the digest the client computed, and whether to replace. */
interface ZipUpload {
  readonly archive: Buffer;
  readonly expectedSha256: string;
  readonly replace: boolean;
}

/** Sends a refusal, logging its operator-side warning first when it has one. */
function sendRefusal(res: Response, refusal: InstallRefusal): void {
  if (refusal.warning) console.warn(refusal.warning);
  res.status(refusal.status).json(refusal.body);
}

/**
 * Checks the query and reads the raw zip body, in this order: digest, content type, body, replace.
 * Runs only after authorization, so no unauthorized request gets its body parsed.
 * @complexity O(b) in body bytes, capped by the raw parser's limit.
 */
async function readZipUpload(required: { req: Request; res: Response; parseZip: RequestHandler }): Promise<ZipUpload | InstallRefusal> {
  const { req, res, parseZip } = required;
  const expectedSha256 = req.query.expectedSha256;
  if (typeof expectedSha256 !== "string" || !/^[a-f0-9]{64}$/.test(expectedSha256)) return DIGEST_REFUSAL;
  // ZIP parsing follows authorization, as in `routes/plugins/install.ts`.
  if (!req.is("application/zip")) return NOT_ZIP_REFUSAL;
  const parseError = await new Promise<unknown>((resolve) => parseZip(req, res, (error?: unknown) => resolve(error)));
  if (parseError) return bodyParseRefusal(parseError);

  const replace = req.query.replace;
  if (replace !== undefined && replace !== "true" && replace !== "false") return REPLACE_REFUSAL;
  return { archive: req.body as Buffer, expectedSha256, replace: replace === "true" };
}

/** The update target from the URL and query, or the refusal for a malformed one. A plain install
 *  has no target. Checked after authorization and before the body is read.
 *  @complexity O(1). */
function readUpdateTarget({ req }: { req: Request }, _optional: Record<string, never> = {}): { update?: UpdateTarget } | InstallRefusal {
  if (req.params.pluginId === undefined) return {};
  const pluginId = req.params.pluginId;
  // The Agent Plugins name grammar (`plugin.json` `name`), owned by Jini's manifest parser: the URL id
  // is checked against it before it names anything on disk.
  if (!isAgentPluginName({ value: pluginId })) return PLUGIN_ID_REFUSAL;
  const expectedOldDigest = req.query.expectedOldDigest;
  if (typeof expectedOldDigest !== "string" || !/^[a-f0-9]{64}$/.test(expectedOldDigest)) return OLD_DIGEST_REFUSAL;
  return { update: { pluginId, expectedOldDigest } };
}

/** The installer's optional ports; an update adds its MCP effects and settings-snapshot owner. */
function installOptions(required: { deps: AgentPluginsRouteDeps; actor: string }, optional: { update?: UpdateTarget } = {}) {
  const { deps, actor } = required;
  const base = { layout: deps.agentPluginLayout, pluginHost: deps.pluginHost };
  if (!optional.update) return base;
  return { ...base, mcpProvisioning: createAgentPluginUpdateEffects({ deps: requireUpdateMcpDeps({ deps }), actor }), snapshotSettings: deps.snapshotAgentPluginSettings };
}

export const registerAgentPluginInstallRoute: AgentPluginsRouteRegistrar = (app, deps) => {
  const parseZip = raw({ type: "application/zip", limit: maxAgentPluginInstallArchiveBytes(), inflate: false });
  const installHandler: RequestHandler = async (req, res) => {
    if (String(req.params.workspaceId) !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return undefined;
    }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "admin.plugins.enable", workspaceId: deps.workspaceId }))) return undefined;
      const target = readUpdateTarget({ req });
      if ("status" in target) return sendRefusal(res, target);
      const upload = await readZipUpload({ req, res, parseZip });
      if ("status" in upload) return sendRefusal(res, upload);
      const result = await installUploadedAgentPlugin({ ...upload, workspaceId: deps.workspaceId, actor: principal.id, ...target },
        installOptions({ deps, actor: principal.id }, target));
      const candidate = (await loadAgentPluginSearchCandidates(deps)).find((entry) => entry.pluginId === result.plugin.pluginId);
      // An update replaces an existing row, so it is never 201.
      const status = result.alreadyInstalled || target.update ? 200 : 201;
      res.status(status).json({ alreadyInstalled: result.alreadyInstalled, warnings: result.warnings ?? [], agentPlugin: installedAgentPluginRow(candidate) });
    } catch (error) {
      // A 500 is redacted for the client, so the operator's log is the only place its cause survives:
      // installErrorResponse logs it (secret-redacted) under the errorId the reply carries.
      const refusal = installErrorResponse(error, { tracker: res.locals?.adminFailureTracker });
      sendRefusal(res, refusal);
    }
    return undefined;
  };
  app.post("/api/admin/v1/workspaces/:workspaceId/agent-plugins/install/zip", installHandler);
  app.post("/api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/update/zip", installHandler);
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { loadAgentPluginSearchCandidates } from "#src/features/agent-plugins/tool-registrations";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteRegistrar } from "./deps.js";
import { agentPluginLifecycleFields } from "./install-response.js";
import { loadAgentPluginConnectionStatuses } from "#src/features/agent-plugins/connection-status";
import { agentPluginMcpPortsOf } from "#src/features/agent-plugins/mcp-host-bindings";

/**
 * @file `AGENT_PLUGINS_LIST` — `GET /api/admin/v1/workspaces/:workspaceId/agent-plugins` (2026-09-09).
 * A plain read, mirroring `plugins/list.ts`'s own shape (workspace-param check, `admin.plugins.read`
 * authorization, one JSON body, no gateway involvement — this is a read with nothing to route
 * through a change-set/outbox pipeline).
 *
 * ---------------------------------------------------------------------------
 * Why this reuses `loadAgentPluginSearchCandidates`, not a second read
 * ---------------------------------------------------------------------------
 * `search_agent_plugin_local` (`features/agent-plugins/tool-registrations.ts`) already resolves
 * "every installed Agent Plugin in this workspace, including disabled ones, with its skills and MCP
 * server ids" — exactly what the admin Agent Plugins screen needs to stop rendering the hardcoded
 * `TOVU_BUNDLED_AGENT_PLUGINS` catalog. Re-deriving that walk here (a second `listInstalledPlugins`
 * call, a second per-plugin skill/mcp.json read, a second single-digest-per-id policy) would give
 * the tool and this route two independent opinions about "what plugins are installed" that could
 * silently drift. This route instead calls the SAME loader and re-shapes its output for the wire —
 * one source of truth, two consumers (a tool and this HTTP surface), the pattern this feature's own
 * `listInstalledPlugins` doc already establishes for its own multiple callers.
 *
 * Permission: reuses `admin.plugins.read` rather than minting `admin.agent-plugins.read` — same
 * reasoning `tool-registrations.ts`'s `plugins_list` merge already gives for reusing this permission
 * across both plugin families: an operator who may see the site/runtime plugin list has no lesser
 * standing to see Agent Plugin ids/skills, and a second gate with an identical threat model would be
 * ceremony, not safety.
 *
 * SECURITY: no absolute host path reaches the response — `loadAgentPluginSearchCandidates` already
 * carries the same no-`packageRoot`-leak discipline `tool-registrations.ts`'s own header states for
 * `search_agent_plugin_local`, and this handler only re-shapes fields that loader already returns.
 */
export const registerAgentPluginsListRoute: AgentPluginsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/agent-plugins", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.plugins.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const candidates = await loadAgentPluginSearchCandidates(deps);
      const connectionStatuses = await loadAgentPluginConnectionStatuses({ workspaceId: deps.workspaceId,
        mcp: deps.externalMcpServerRepo, loadCards: deps.loadPluginCredentialCards, apiConnections: deps.apiConnections?.host, ...agentPluginMcpPortsOf(deps.mcp) });

      res.json({
        agentPlugins: candidates.map((candidate) => ({
          pluginId: candidate.pluginId,
          displayName: candidate.displayName ?? null,
          summary: candidate.summary ?? null,
          version: candidate.version ?? null,
          description: candidate.description ?? null,
          id: candidate.id,
          provides: candidate.provides,
          keywords: candidate.keywords,
          enabled: candidate.enabled,
          ...(connectionStatuses.has(candidate.pluginId) ? { connectionStatus: connectionStatuses.get(candidate.pluginId) } : {}),
          ...agentPluginLifecycleFields({ candidate }),
          skills: candidate.skills,
          mcpServerIds: candidate.mcpServerIds,
        })),
      });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/agent-plugins/list", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { containAgentPluginStatePath } from "#src/features/agent-plugins/lifecycle";
import type { Request, Response } from "express";

import { pluginMemory } from "#src/features/agent-plugins/memory";
import { listInstalledPlugins } from "../../../../../features/agent-plugins/lifecycle.js";
import { DEFAULT_PLUGIN_MEMORY_LIMITS } from "@jini-ai/agent-plugins/persistent-state";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AgentPluginsRouteDeps, AgentPluginsRouteRegistrar } from "./deps.js";

/** A note write: exactly `entryPath` and `text`, both strings. */
interface NoteWrite {
  readonly entryPath: string;
  readonly text: string;
}

/**
 * True only for an object whose keys are exactly `entryPath` and `text`, both strings.
 * @complexity O(k) in the body's key count.
 */
function isNoteWrite(body: unknown): body is NoteWrite {
  if (!body || typeof body !== "object" || Array.isArray(body)) return false;
  if (Object.keys(body).some(key => key !== "entryPath" && key !== "text")) return false;
  if (!("entryPath" in body) || typeof body.entryPath !== "string") return false;
  return "text" in body && typeof body.text === "string";
}

/**
 * Validates and writes one user note, answering the refusal itself.
 * @returns false when a refusal was sent.
 * @complexity O(k) validation plus one note write.
 */
async function writeNoteOrRespond(required: { body: unknown; memory: ReturnType<typeof pluginMemory>; res: Response }): Promise<boolean> {
  const { body, memory, res } = required;
  if (!isNoteWrite(body)) {
    res.status(400).json({ error: "entryPath and text are required", code: "VALIDATION_ERROR" }); return false;
  }
  try { await memory.writeNote({ entryPath: body.entryPath, text: body.text }); }
  catch { res.status(422).json({ error: "note path, text or size is invalid", code: "PLUGIN_MEMORY_INVALID" }); return false; }
  return true;
}

/** @complexity O(p) in installed plugin count. */
async function isInstalled(deps: AgentPluginsRouteDeps, pluginId: string): Promise<boolean> {
  const workspace = deps.agentPluginLayout.forWorkspace(deps.workspaceId);
  return (await listInstalledPlugins(workspace.root)).some(plugin => plugin.pluginId === pluginId);
}

/** The user's notes editor writes notes only; learned knowledge stays separately readable. */
export const registerAgentPluginMemoryRoutes: AgentPluginsRouteRegistrar = (app, deps) => {
  const url = "/api/admin/v1/workspaces/:workspaceId/agent-plugins/:pluginId/memory";
  const handle = (write: boolean) => async (req: Request, res: Response) => {
    if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id,
        permission: write ? "admin.plugins.enable" : "admin.plugins.read", workspaceId: deps.workspaceId }))) return;
      const pluginId = String(req.params.pluginId);
      if (!(await isInstalled(deps, pluginId))) {
        res.status(404).json({ error: "agent plugin was not found", code: "AGENT_PLUGIN_NOT_FOUND" }); return;
      }
      const memory = pluginMemory({ contain: containAgentPluginStatePath, workspaceId: deps.workspaceId, pluginId }, { layout: deps.agentPluginLayout });
      if (write && !(await writeNoteOrRespond({ body: req.body, memory, res }))) return;
      const [learned, notes] = await Promise.all([memory.list({ kind: "learned" }), memory.list({ kind: "notes" })]);
      res.json({ pluginId, learned, notes, limits: DEFAULT_PLUGIN_MEMORY_LIMITS });
    } catch (error) { sendAdminFailure({ res, error }, { operation: "routes/agent-plugins/memory", code: "INTERNAL_ERROR" }); }
  };
  app.get(url, handle(false));
  app.put(url, handle(true));
};

