import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import {
  type DetectedAgent as RuntimeDetectedAgent,
  type RuntimeModelOption,
} from "@jini-ai/agent-runtime";
import { createAssistantDetectionCache, listDetectedAssistantAgents, assistantAgentDiscoveryPending } from "#src/assistant/agent-discovery";
import { ADMIN_ASSISTANT_PERMISSION } from "#src/assistant/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AssistantExecutionRouteDeps, AssistantExecutionRouteRegistrar } from "./execution-deps.js";

/**
 * Narrows one model's OWN `reasoning` (`RuntimeModelOption.reasoning` — Codex's per-model effort
 * levels, populated by `parseCodexDebugModels`) to the `{id,label}` shape, or omits the field when
 * the runtime reported none.
 *
 * `undefined` here means "this runtime doesn't report per-model levels" (see that field's own doc
 * in `@jini-ai/agent-runtime`'s `types.ts`), never "this model supports zero" — so an absent value
 * must stay absent. Defaulting it to `[]` would turn "unknown" into "none", which is exactly the
 * kind of narrowing this projection has already dropped data to twice before (see this file's own
 * header on `reasoningOptions`/`reasoningInModelId`).
 */
function projectModelReasoning(model: RuntimeModelOption): { reasoning?: Array<{ id: string; label: string }> } {
  return model.reasoning?.length
    ? { reasoning: model.reasoning.map((option) => ({ id: option.id, label: option.label })) }
    : {};
}

/** Narrows `agent.models` to the `{id,label,reasoning?}` shape the UI needs, or `{}` when the
 *  runtime found none. Per-model `reasoning` is carried alongside `id`/`label` via
 *  `projectModelReasoning` rather than defaulted — see that function's doc for why. */
function projectModels(
  agent: RuntimeDetectedAgent,
): { models?: Array<{ id: string; label: string; reasoning?: Array<{ id: string; label: string }> }> } {
  return agent.models?.length
    ? {
        models: agent.models.map((model) => ({
          id: model.id,
          label: model.label,
          ...projectModelReasoning(model),
        })),
      }
    : {};
}

/** Narrows `agent.reasoningOptions` to the `{id,label}` shape the UI needs, or `{}` when the runtime declared none. */
function projectReasoningOptions(agent: RuntimeDetectedAgent): { reasoningOptions?: Array<{ id: string; label: string }> } {
  return agent.reasoningOptions?.length
    ? { reasoningOptions: agent.reasoningOptions.map((option) => ({ id: option.id, label: option.label })) }
    : {};
}

/** Narrows `agent.reasoningInModelId` to the `{id,label}` shape the UI needs, or `{}` when the runtime rides no effort suffix. */
function projectReasoningInModelId(agent: RuntimeDetectedAgent): { reasoningInModelId?: { levels: Array<{ id: string; label: string }> } } {
  return agent.reasoningInModelId?.levels.length
    ? {
        reasoningInModelId: {
          levels: agent.reasoningInModelId.levels.map((level) => ({ id: level.id, label: level.label })),
        },
      }
    : {};
}

/**
 * Maps `@jini-ai/agent-runtime`'s `DetectedAgent` onto the `@jini-ai/ui`
 * `ExecutionTab`'s own `DetectedAgent`.
 *
 * This used to narrow the payload to `{id,label,installed,version?,path?}` on
 * the theory that the picker rendered nothing else. It does: the tab's agent
 * cards show the model list and its provenance, the auth status, and the
 * binary path, and every one of those fields already exists on the runtime
 * shape (`types.ts`, the `models` / `modelsSource` / `authStatus` /
 * `authMessage` intersection). Dropping them here left the UI unable to render
 * what detection had already paid to discover.
 *
 * `diagnostics` is still not forwarded — the tab has no affordance for the
 * fix-actions they describe, so it would be dead weight on the wire rather
 * than data the client can use.
 *
 * Both reasoning-effort fields were the same omission a second time, found
 * 2026-09-02 and fixed here. `LocalCliAgentCard` has rendered a "Reasoning
 * effort" control for any agent reporting `reasoningOptions` since it was
 * ported, and `claude`/`codex` have declared those options for just as long —
 * but this projection dropped them, so the control was unreachable in Tovu for
 * every runtime, with nothing failing anywhere to say so.
 * `reasoningInModelId` is the second shape (a runtime whose effort rides as a
 * suffix on the model id, antigravity being the only declarer); the card
 * derives its per-base-model levels from `models`, which this projection
 * already carries, so the vocabulary is all it additionally needs.
 *
 * The three collection-shaped fields (`models`, `reasoningOptions`,
 * `reasoningInModelId`) are each narrowed by a small helper above — every one
 * of them is an independent `presence check + map` branch, and inlined here
 * they pushed this function's cyclomatic complexity to 12 against the repo's
 * ceiling of 9. Extracting them (rather than the five scalar fields below,
 * which are single ternaries with no nested branching) is what brings this
 * back under the gate without changing a single returned value.
 *
 * Exported for `__tests__/detect-agents-projection.test.ts`, which pins both
 * fields so the next narrowing fails there rather than silently in the UI.
 *
 * A third omission of the same shape, found 2026-09-05: `projectModels` dropped each model's OWN
 * `reasoning` (`RuntimeModelOption.reasoning` — Codex's per-model effort levels), leaving no way
 * for a future picker to narrow the effort control to what the SELECTED model actually supports
 * instead of the agent-wide union `reasoningOptions` carries. Fixed by `projectModelReasoning`
 * above. No `@jini-ai/ui` picker reads it yet (`AgentModelOption` there has no `reasoning` field) —
 * this only gets the data to the browser; the picker-side narrowing is a separate, tracked change.
 */
export function toExecutionTabAgent(agent: RuntimeDetectedAgent): {
  id: string;
  label: string;
  installed: boolean;
  version?: string;
  path?: string;
  models?: Array<{ id: string; label: string; reasoning?: Array<{ id: string; label: string }> }>;
  modelsSource?: "live" | "fallback";
  reasoningOptions?: Array<{ id: string; label: string }>;
  reasoningInModelId?: { levels: Array<{ id: string; label: string }> };
  authStatus?: "ok" | "missing" | "unknown";
  authMessage?: string;
} {
  return {
    id: agent.id,
    label: agent.name,
    installed: agent.available,
    ...(agent.version ? { version: agent.version } : {}),
    ...(agent.path ? { path: agent.path } : {}),
    ...projectModels(agent),
    ...(agent.modelsSource ? { modelsSource: agent.modelsSource } : {}),
    ...projectReasoningOptions(agent),
    ...projectReasoningInModelId(agent),
    ...(agent.authStatus ? { authStatus: agent.authStatus } : {}),
    // Auth guidance is operator-facing text from the adapter ("run `x login`"),
    // not provider output, so it carries no credential material.
    ...(agent.authMessage ? { authMessage: agent.authMessage } : {}),
  };
}

/** Read the host snapshot before sampling its pending state; discovery stays with the cache.
 * Rejections propagate to the route's existing internal-error response.
 * @complexity O(1) transport work; inventory discovery is delegated.
 */
async function readDetectionSnapshot(
  { inventory, deps, input }: {
    inventory: ReturnType<typeof createAssistantDetectionCache> | undefined;
    deps: AssistantExecutionRouteDeps;
    input: { force: boolean };
  },
  _options: Record<string, never> = {},
) {
  const agents = await (inventory ? inventory.read(input) : (deps.assistantAgentInventory?.listDetectedAssistantAgents ?? listDetectedAssistantAgents)(input));
  const discoveryPending = inventory ? inventory.isPending({}) : (deps.assistantAgentInventory?.assistantAgentDiscoveryPending ?? assistantAgentDiscoveryPending)();
  return { agents, discoveryPending };
}

/**
 * POST detects code-agent CLIs installed on the server host — the "Execution
 * mode" tab's Local CLI probe (`ExecutionPort.detectLocalAgents` /
 * `.rescanLocalAgents`, both wired to this one route by
 * `apps/admin/src/lib/execution-settings.ts`). Delegates entirely to
 * `@jini-ai/agent-runtime`'s `detectAgents()` (the same spawn-`--version`-and-
 * classify probe traced from Open Design's `apps/daemon/src/runtimes/
 * detection.ts` — see the dispatch trace, Q4).
 *
 * A strict `force:true` body is explicit Rescan. Ordinary reads return the previous
 * inventory immediately while one background scan refreshes it; no per-caller configuration.
 */
export const registerAdminAssistantDetectAgentsRoute: AssistantExecutionRouteRegistrar = (app, deps) => {
  const inventory = deps.detectAgents ? createAssistantDetectionCache({ detector: deps.detectAgents, ...(deps.assistantAgentInventory ? { runtime: deps.assistantAgentInventory.runtime } : {}) }) : undefined;
  app.post("/api/admin/v1/workspaces/:workspaceId/assistant/execution/detect-agents", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: ADMIN_ASSISTANT_PERMISSION,
        workspaceId: deps.workspaceId,
        entityType: "assistant-execution",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for '${ADMIN_ASSISTANT_PERMISSION}' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: ADMIN_ASSISTANT_PERMISSION, reason: authResult.reason },
        });
        return;
      }

      const input = { force: req.body?.force === true };
      const { agents, discoveryPending } = await readDetectionSnapshot({ inventory, deps, input });
      res.json({ data: agents.map(agent => ({ ...toExecutionTabAgent(agent), discoveryPending })) });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/assistant/detect-agents", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { sniffContentType, readChatAttachmentForOwner } from "#src/features/media/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { parseRangeHeader } from "#src/server/inbound/admin-http/range";
import {
  DISALLOWED_INLINE_CONTENT_TYPES,
  sendMediaOriginalResponse,
} from "#src/server/inbound/admin-http/routes/media/original";

/**
 * @file `GET /api/attachments/:ref` — serves one staged chat attachment's bytes back to the
 * principal who uploaded it.
 *
 * WHY IT EXISTS. `@jini-ai/http-kit`'s attachment pack mounts only `POST`/`DELETE`, so bytes could
 * be staged and never read again. The admin's attachment preview modal could therefore only show
 * attachments from the current session, out of a client-side `File` cache; anything from an earlier
 * turn, or anything at all after a reload, had no URL to load from. This is that URL.
 *
 * WHERE THE WORK IS. Everything that decides whether these bytes may be served —
 * ownership, sidecar validation, path containment, and the file-identity gate — lives in
 * `features/media/read-chat-attachment.ts`, which states the authorization rule and the path-safety
 * argument in full. This file is the HTTP shell: session gate, one call, safe headers.
 *
 * NOT A PROXY, unlike every other route on this path. `POST`/`DELETE /api/attachments` forward to
 * the agent daemon because the live `AttachmentStore` lives in that process. This route does not,
 * for two reasons: the daemon's `AttachmentStore` port exposes no non-mutating owner-scoped read
 * (see the module doc linked above), and the principal this route authorizes against is minted in
 * THIS process by `requireAdminSession` — comparing it here means no trusted-header hop between
 * the check and the value it checks.
 *
 * AUTHENTICATION is the `app.use("/api/attachments", requireAdminSession(routeDeps))` mounted in
 * `composition/modules/assistant.ts`. Express's `app.use(path, ...)` matches that prefix AND every
 * subpath, so this route is covered by the same gate that covers the upload it reads back — no
 * second mount, which would be a second thing to keep in sync. `get-chat-attachment-route.test.ts`
 * asserts the unauthenticated 401 through a real request rather than assuming that.
 *
 * SECURITY — this route serves attacker-influenced bytes, so it reuses `routes/media/original.ts`'s
 * response writer verbatim rather than hand-rolling headers (the same reuse
 * `routes/site/media-rendition.ts` already makes of it):
 *  - `Content-Type` is ALWAYS `sniffContentType(bytes)`, computed from the bytes this response is
 *    about to send. The `kind` the store recorded at upload is never consulted for it — and could
 *    not be trusted for it anyway: `detectAttachmentKind` classifies a real AVIF as `'file'` today
 *    (`2026-09-06-tovu-f6-outstanding-worklist.md` §A.1), so the stored `kind` is known to be
 *    wrong for at least one real format while the sniffer used here handles it.
 *  - a sniffed `text/html`/`application/xhtml+xml`/`image/svg+xml` is forced to
 *    `application/octet-stream` + `Content-Disposition: attachment`. A chat composer accepts any
 *    file, so an uploaded `.html` or `.svg` is an ordinary occurrence, and either is a same-origin
 *    stored-XSS vector if a browser ever renders it inline.
 *  - `X-Content-Type-Options: nosniff` is always set, without which the defusal above is moot.
 *  - a restrictive `Content-Security-Policy` and `Cross-Origin-Resource-Policy` ride along, and
 *    `Cache-Control: private, no-store` keeps one principal's attachment out of any shared cache.
 *  - `Range` is honored, so a `<video>` attachment can seek instead of buffering the whole file.
 *
 * NO `Content-Disposition: filename`. The stored display name is available but is not put in a
 * header here: `sanitizeAttachmentName`'s allowlist has not been checked against what a
 * `Content-Disposition` value may safely contain, and a header built from an unverified allowlist
 * is exactly the kind of claim this repo's false-comment register exists to stop. A filename can be
 * added once that is checked.
 */

/** The single, deliberately non-disclosing refusal. Every distinct reason
 *  `readChatAttachmentForOwner` can refuse for — unknown ref, malformed ref, another principal's
 *  attachment, a file that changed since upload — produces this exact response, so a caller cannot
 *  probe for which one applies. Mirrors `AttachmentStore.resolveForRun`'s own non-disclosure
 *  contract. The ref is deliberately not echoed back: it is caller-controlled, and there is nothing
 *  to confirm about it. */
const ATTACHMENT_NOT_FOUND_BODY = { error: "attachment was not found", code: "NOT_FOUND" } as const;

/** Registers the authenticated attachment read shell; the optional owner-scoped reader defaults
 * to the filesystem adapter. Unexpected failures return a private 500 envelope.
 * @complexity O(n) time/space in the attachment bytes read and served.
 */
export function registerAdminChatAttachmentReadRoute(
  app: Express,
  deps: {
    readonly uploadDirectory: string;
    /** Owner-scoped reader boundary; defaults to the real filesystem implementation. */
    readonly readChatAttachmentForOwner?: typeof readChatAttachmentForOwner;
  }
): void {
  app.get("/api/attachments/:ref", async (req, res) => {
    try {
      const result = await (deps.readChatAttachmentForOwner ?? readChatAttachmentForOwner)({ uploadDirectory: deps.uploadDirectory }, {
        ref: String(req.params.ref),
        ownerId: getAuthedPrincipal(res).id,
      });
      if (!result.ok) {
        res.status(404).set("Cache-Control", "private, no-store").json(ATTACHMENT_NOT_FOUND_BODY);
        return;
      }

      const sniffed = sniffContentType({ bytes: result.bytes });
      const forceDownload = DISALLOWED_INLINE_CONTENT_TYPES.has(sniffed);
      sendMediaOriginalResponse(res, result.bytes, parseRangeHeader({ header: req.get("range"), totalLength: result.bytes.byteLength }), {
        safe: forceDownload ? "application/octet-stream" : sniffed,
        forceDownload,
      });
    } catch (error) {
      // `readChatAttachmentForOwner` classifies every expected failure as a refusal rather than
      // throwing, so anything reaching here is genuinely unexpected (a filesystem fault between the
      // identity check and the read, say). Reported without detail — a store failure can carry
      // filesystem paths a caller must not see, the same SEC-005 redaction `attachments.ts` applies.
      sendAdminFailure({ res, error }, { operation: "routes/assistant/get-chat-attachment", code: "INTERNAL_ERROR" });
    }
  });
}

