import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import {
  ADMIN_ASSISTANT_PERMISSION,
  SiteAssistantCredentialValidationError,
  SiteAssistantSecretStoreUnconfiguredError,
  setSiteAssistantCredential,
} from "#src/assistant/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AssistantSettingsRouteRegistrar } from "./deps.js";

/** This route's PUT body shape — every field optional, `undefined` means "leave alone". */
type SiteCredentialBody = { apiKey?: unknown; provider?: unknown; baseUrl?: unknown; model?: unknown };

/**
 * Rejects a present-but-non-string field (a stray `{apiKey: 12345}`) rather than silently treating
 * it as "the caller sent nothing" — see the route doc above for why that distinction matters.
 *
 * @complexity O(fields in body), a small fixed set.
 */
function rejectNonStringFields(body: SiteCredentialBody): void {
  for (const [field, value] of Object.entries(body)) {
    if (value !== undefined && typeof value !== "string") {
      throw new SiteAssistantCredentialValidationError(`${field} must be a string`);
    }
  }
}

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendPutSiteCredentialError(res: Response, err: unknown): void {
  if (err instanceof SiteAssistantCredentialValidationError) {
    res.status(400).json({ error: err.message, code: "SITE_CREDENTIAL_VALIDATION_ERROR" });
    return;
  }
  if (err instanceof SiteAssistantSecretStoreUnconfiguredError) {
    res.status(503).json({
      error:
        "site assistant secret store is not configured — set TOVU_SITE_KEY (a hex-encoded site key) in the server environment",
      code: "SECRET_STORE_UNCONFIGURED",
    });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/assistant/put-site-credential", code: "INTERNAL_ERROR" });
}

/**
 * PUT (partial) the workspace's SITE assistant credential (ADR-058). Body:
 * `{ apiKey?, provider?, baseUrl?, model? }` — omitted `apiKey` leaves the stored key untouched;
 * an empty string is rejected (DELETE clears the key). The response NEVER echoes the key, only the
 * same `{isSet, masked, provider, baseUrl, model, updatedAt}` shape GET returns.
 *
 * Three outcomes, not two: this route adds a `503 SECRET_STORE_UNCONFIGURED` branch on top of
 * `put-settings.ts`'s usual 400-validation/500-other split (ADR-058 §4) — a missing
 * `TOVU_SITE_KEY` is a distinct, actionable operator error, not a generic 500, and not a
 * validation problem with the request body.
 */
export const registerAdminAssistantPutSiteCredentialRoute: AssistantSettingsRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/assistant/site-credential", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: ADMIN_ASSISTANT_PERMISSION,
        workspaceId: deps.workspaceId,
        entityType: "assistant-settings",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for '${ADMIN_ASSISTANT_PERMISSION}' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: ADMIN_ASSISTANT_PERMISSION, reason: authResult.reason },
        });
        return;
      }

      const body = (req.body ?? {}) as SiteCredentialBody;
      // Present-but-not-a-string is a REJECTION here, same as `setSiteAssistantCredential`'s own
      // check for `provider`/`baseUrl`/`model` — an `undefined` field is "leave alone", but a
      // present non-string field (a stray `{apiKey: 12345}`) must not be silently reinterpreted as
      // "the caller sent nothing", which would leave a bad request looking like a no-op success.
      rejectNonStringFields(body);

      const view = await setSiteAssistantCredential(
        {
          repo: deps.siteAssistantCredentialRepo,
          sealer: deps.siteAssistantSecretSealer,
          keyring: deps.siteAssistantSecretKeyring,
          clock: deps.clock,
        },
        {
          workspaceId: deps.workspaceId,
          apiKey: body.apiKey as string | undefined,
          provider: body.provider as string | undefined,
          baseUrl: body.baseUrl as string | undefined,
          model: body.model as string | undefined,
        }
      );
      res.json({ data: view });
    } catch (err) {
      sendPutSiteCredentialError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { detectAgents, type DetectedAgent } from "@jini-ai/agent-runtime";
import { ADMIN_ASSISTANT_PERMISSION } from "#src/assistant/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AssistantExecutionRouteRegistrar } from "./execution-deps.js";
import { resolveTestAgentOutcome } from "./resolve-test-agent-outcome.js";

/** This route's two body fields, trimmed, read off an untyped body in one place.
 *  @complexity O(1). */
function parseTestAgentBody(rawBody: unknown): { agentId: string; model: string } {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    agentId: String(body.agentId ?? "").trim(),
    model: String(body.model ?? "").trim(),
  };
}

/** Select the requested CLI, retaining the route's missing-PATH verdict before readiness checks.
 * @complexity O(n) time for n detected agents, O(1) additional space; no I/O.
 */
function detectedTestAgentOutcome(
  { agents, agentId, model }: { agents: DetectedAgent[]; agentId: string; model: string },
  _options: Record<string, never> = {},
) {
  const agent = agents.find((candidate) => candidate.id === agentId);
  if (!agent || !agent.available) {
    return { ok: false, message: `'${agentId}' was not found on this server's PATH.` };
  }

  // Branch logic (installed/authenticated/model-mismatch/success) lives in
  // `resolveTestAgentOutcome` — a pure function so it can be unit-tested against fabricated
  // `DetectedAgent` objects instead of depending on which CLIs happen to be installed and
  // authenticated on the host running the suite. See that file's doc for why.
  return resolveTestAgentOutcome(agent, model);
}

/**
 * POST re-probes ONE detected code-agent CLI and reports whether it is usable
 * — the Local CLI counterpart of `test-connection.ts`, backing
 * `ExecutionPort.testAgent` (the per-agent Test button on an agent card).
 *
 * Implemented as a fresh `detectAgents()` run scoped to the requested id
 * rather than a new probing mechanism. That run already spawns each CLI's
 * `--version` and its declared auth probe (`probeAgentAuthStatus`), which is
 * exactly the question the button asks: is this CLI present, and is it signed
 * in *right now*? Reusing it adds no new subprocess surface beyond what
 * `detect-agents.ts` already exposes on this same permission.
 *
 * What this deliberately does NOT do is dispatch a real prompt through the
 * agent. The origin's Test did (it had a daemon dispatcher to hand), but a
 * settings screen that silently bills the operator for a model call is a
 * different and more expensive promise than "check this is set up", and Tovu
 * has no such dispatcher wired here. The response says which check ran so the
 * result cannot be over-read.
 *
 * Outcome split follows the error-reporting contract §3.1, matching
 * `test-connection.ts`:
 *  - **200 `{ok:false}`** — the probe RAN and the CLI is not usable (missing,
 *    or reporting that it needs authentication). That verdict is the answer,
 *    so it is a value.
 *  - **5xx** — the probe itself could not run. There is no verdict to report.
 */
export const registerAdminAssistantTestAgentRoute: AssistantExecutionRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/assistant/execution/test-agent", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: ADMIN_ASSISTANT_PERMISSION,
        workspaceId: deps.workspaceId,
        entityType: "assistant-execution",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for '${ADMIN_ASSISTANT_PERMISSION}' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: ADMIN_ASSISTANT_PERMISSION, reason: authResult.reason },
        });
        return;
      }

      const { agentId, model } = parseTestAgentBody(req.body);
      if (!agentId) {
        res.status(400).json({ error: "'agentId' is required", code: "BAD_REQUEST" });
        return;
      }

      const agents = await (deps.detectAgents ?? deps.assistantAgentInventory?.runtime.detectAgents ?? detectAgents)({ agentIds: [agentId] }, { force: true });
      res.json(detectedTestAgentOutcome({ agents, agentId, model }));
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/assistant/test-agent", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { testProviderConnection, type ConnectionTestResponse } from "@jini-ai/agent-runtime";
import { ADMIN_ASSISTANT_PERMISSION } from "#src/assistant/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { AssistantExecutionRouteDeps, AssistantExecutionRouteRegistrar } from "./execution-deps.js";
import { readOptionalString, validateSupportedProtocol, type SupportedExecutionProtocol } from "./execution-request-fields.js";
import { resolveProbeCredential, type ProbeCredentialResolution } from "./stored-credential-probe.js";

interface TestConnectionRequestBody {
  protocol?: unknown;
  baseUrl?: unknown;
  apiKey?: unknown;
  model?: unknown;
  apiVersion?: unknown;
  /** Opt in to testing with the workspace's STORED site credential instead of a key in this body. */
  useStoredCredential?: unknown;
  /** Opt in to testing with the CALLING ADMIN's OWN stored execution credential. A different key
   *  from `useStoredCredential`'s — see `stored-credential-probe.ts`'s header for why the two are
   *  separate flags. */
  useAdminStoredCredential?: unknown;
}

/** True if either required connection-target field is blank.
 *  @complexity O(1). */
function isMissingConnectionTarget(baseUrl: string, model: string): boolean {
  return !baseUrl.trim() || !model.trim();
}

function renderMessage(result: ConnectionTestResponse): string {
  if (result.ok) return result.detail?.trim() ? result.detail : "Connection succeeded";
  return result.detail?.trim() ? result.detail : `Connection failed (${result.kind})`;
}

/**
 * Calls `testProviderConnection` and shapes this route's response body — isolated so the
 * spread-if-present `apiVersion` shape doesn't add to the handler's own branching.
 * Host DNS/dispatcher dependencies are forwarded while redirect refusal is enforced here.
 *
 * @complexity O(1).
 */
async function fetchTestConnectionResponse(
  protocol: SupportedExecutionProtocol,
  credential: Extract<ProbeCredentialResolution, { ok: true }>,
  model: string,
  apiVersion: string | undefined,
  deps: AssistantExecutionRouteDeps
) {
  // The runtime validates only the initial base URL. A provider redirect must not send
  // this probe (and its credentials) to a destination that never passed that guard.
  // The current runtime types put requestInit in optional argument two and require its dispatcher
  // key; undefined uses fetch's default.
  const requestInit = { ...deps.probeRequestInit, redirect: "error", dispatcher: deps.probeRequestInit?.dispatcher } satisfies
    RequestInit & NonNullable<NonNullable<Parameters<typeof testProviderConnection>[1]>["requestInit"]>;
  const result = await (deps.testProviderConnection ?? testProviderConnection)({
    protocol,
    baseUrl: credential.baseUrl,
    apiKey: credential.apiKey,
    model,
  }, {
    dnsLookup: deps.probeDnsLookup,
    requestInit,
    ...(apiVersion ? { apiVersion } : {}),
  });
  return { ok: result.ok, message: renderMessage(result) };
}

/**
 * POST probes a BYOK provider endpoint with the caller-supplied credentials
 * — the "Execution mode" tab's `ExecutionPort.testConnection`, wired by
 * `apps/admin/src/lib/execution-settings.ts`. Delegates to
 * `@jini-ai/agent-runtime`'s `testProviderConnection` (dispatch trace Q2/Q6):
 * this server makes the real outbound request to the provider so the key
 * never has to leave the admin's own browser via a cross-origin fetch, and
 * so the SSRF guard (`validateBaseUrlResolved`) runs against a base URL the
 * SERVER resolves, not one a hostile client could steer client-side.
 *
 * That guard bounds which ADDRESS SPACE a probe may reach (it rejects
 * loopback/RFC1918/link-local/CGNAT), and deliberately not which HOST — every
 * real provider is a public host. It is therefore not what keeps the stored
 * site credential from being sent somewhere it shouldn't go; see
 * `stored-credential-probe.ts` for the separate rule that does.
 *
 * The request body's `apiKey` is used for exactly this one outbound call and
 * is never persisted anywhere on this server — no settings write, no log
 * line includes it (`testProviderConnection` redacts it out of any upstream
 * error text it surfaces). See `assistant/execution-mode-settings.ts` for why
 * that constraint exists (ADR-028 §6) and where the key lives instead
 * (the browser's own localStorage).
 */
export const registerAdminAssistantTestConnectionRoute: AssistantExecutionRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/assistant/execution/test-connection", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: ADMIN_ASSISTANT_PERMISSION,
        workspaceId: deps.workspaceId,
        entityType: "assistant-execution",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for '${ADMIN_ASSISTANT_PERMISSION}' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: ADMIN_ASSISTANT_PERMISSION, reason: authResult.reason },
        });
        return;
      }

      const body = (req.body ?? {}) as TestConnectionRequestBody;
      const protocol = readOptionalString(body.protocol, "");
      const baseUrl = readOptionalString(body.baseUrl, "");
      const model = readOptionalString(body.model, "");
      const apiVersion = readOptionalString(body.apiVersion, undefined);

      const protocolError = validateSupportedProtocol(protocol);
      if (protocolError) {
        res.status(400).json(protocolError);
        return;
      }
      if (isMissingConnectionTarget(baseUrl, model)) {
        res.status(400).json({ error: "baseUrl and model are required", code: "VALIDATION_ERROR" });
        return;
      }

      // Which key probes, and WHERE it is allowed to go — one chokepoint shared with
      // `list-models.ts`. A typed key wins and travels to the endpoint its owner named; EITHER
      // stored credential travels only to the endpoint the server already recorded for it, never to
      // one this request body chose. `principalId` comes from the session, never the body — it is
      // what scopes the admin branch to the caller's own row. See `stored-credential-probe.ts`.
      const credential = await resolveProbeCredential(deps, {
        requestedBaseUrl: baseUrl,
        typedKey: readOptionalString(body.apiKey, ""),
        useStoredCredential: body.useStoredCredential === true,
        useAdminStoredCredential: body.useAdminStoredCredential === true,
        principalId: principal.id,
      });
      if (!credential.ok) {
        res.status(400).json(credential.failure);
        return;
      }

      res.json(await fetchTestConnectionResponse(protocol as SupportedExecutionProtocol, credential, model, apiVersion, deps));
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/assistant/test-connection", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
/** Admin page transport for the same visitor-tools service that assistant chat uses. */
import type { Express, Request, Response } from "express";
import { ForbiddenError, ValueValidationFailedError } from "@jini-ai/core/settings";
import { VisitorToolPolicyValidationError } from "#src/contracts/site-assistant/visitor-tools";
import type { VisitorToolsManagementPort } from "#src/contracts/site-assistant/visitor-tools-management";
import { VisitorToolsRevisionConflictError } from "#src/features/settings/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

export interface VisitorToolsRouteDeps { workspaceId: string; visitorToolsManagement?: VisitorToolsManagementPort }
export const ADMIN_VISITOR_TOOLS_PATH = "/api/admin/v1/workspaces/:workspaceId/assistant/visitor-tools";

/** Map typed service errors without leaking settings/provider failures. @complexity O(1). */
function respondError({ error, res }: { error: unknown; res: Response }, _options = {}): void {
  if (error instanceof VisitorToolsRevisionConflictError) {
    res.status(409).json({ error: error.message, code: "VISITOR_TOOLS_REVISION_CONFLICT", reload: true });
    return;
  }
  if (error instanceof ForbiddenError) {
    res.status(403).json({ error: "visitor-tools.manage is required", code: "FORBIDDEN" });
    return;
  }
  if (error instanceof VisitorToolPolicyValidationError || error instanceof ValueValidationFailedError) {
    res.status(400).json({ error: error.message, code: "VISITOR_TOOLS_VALIDATION_ERROR" });
    return;
  }
  sendAdminFailure({ res, error }, { operation: "routes/assistant/visitor-tools", code: "INTERNAL_ERROR" });
}

/** Single workspace/session boundary; auth and fresh revision checks remain service-owned. */
async function handle({ req, res, deps, operation }: {
  req: Request; res: Response; deps: VisitorToolsRouteDeps; operation: "list" | "configure";
}, _options = {}): Promise<void> {
  if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
    res.status(404).json({ error: "workspace was not found" });
    return;
  }
  try {
    const service = deps.visitorToolsManagement;
    if (!service) throw new Error("Visitor tools service unavailable.");
    const callerPrincipalId = getAuthedPrincipal(res).id;
    if (operation === "list") {
      res.json({ data: await service.list({ callerPrincipalId }) });
      return;
    }
    const prepared = await service.prepare({ callerPrincipalId, input: req.body });
    res.json({ data: await service.apply({ callerPrincipalId, prepared }) });
  } catch (error) { respondError({ error, res }); }
}

/** GET/PUT require visitor-tools.manage through the service; the enclosing admin module requires a session.
