import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Response } from "express";

import type { CommentWriteService, CommentStatus, ModerationAction } from "@jini-ai/cms/comments";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file ADR-031 §6/§9 (SPEC-033) — the 5 moderation action routes (approve/spam/trash/restore/
 * purge). One file, not five — the 5 actions are near-identical (permission check → parse
 * expectedVersion → call the write-service → map the result to a status code), so a single
 * parameterized registrar per action is a reasonable simplification over 5 near-duplicate files
 * (Article III). Each still registers its OWN route/permission pairing explicitly, not a generic
 * `/action/:verb` dispatcher — route paths and permission strings stay grep-able and explicit.
 */
export type AdminCommentsModerateDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & {
  commentWriteService: CommentWriteService;
};

interface ActionSpec {
  path: string;
  permission: string;
  action: ModerationAction;
  toStatus: CommentStatus | null; // null = purge, which has no toStatus
}

/**
 * v1 simplification: `restore` always targets `approved`, regardless of whether the comment was
 * previously `trash` or `spam` — the moderation_log's own `fromStatus` still records exactly
 * which, so this is a UX default (an operator restoring anything wants it visible again), not a
 * loss of audit information.
 */
const ACTIONS: readonly ActionSpec[] = [
  { path: "approve", permission: "comments.moderate", action: "approve", toStatus: "approved" },
  { path: "spam", permission: "comments.moderate", action: "mark_spam", toStatus: "spam" },
  { path: "trash", permission: "comments.delete", action: "trash", toStatus: "trash" },
  { path: "restore", permission: "comments.moderate", action: "restore", toStatus: "approved" },
];

function parseExpectedVersion(raw: unknown): number | null {
  let n: number;
  if (typeof raw === "number") n = raw;
  else if (typeof raw === "string") n = Number(raw);
  else return null;
  return Number.isInteger(n) && n >= 0 ? n : null;
}

/** This route's `{expectedVersion, note}` body, read once — `null` means `expectedVersion` failed
 *  validation. @complexity O(1). */
function parseModerationBody(rawBody: unknown): { expectedVersion: number; note: string | null } | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const expectedVersion = parseExpectedVersion(body.expectedVersion);
  if (expectedVersion === null) return null;
  return { expectedVersion, note: typeof body.note === "string" ? body.note : null };
}

/** Writes the response for a completed `applyModeration` call — 204 on success, the
 *  not-found/version-conflict split mapped from `result.reason` otherwise. @complexity O(1). */
function respondToModerationResult(res: Response, result: Awaited<ReturnType<CommentWriteService["applyModeration"]>>): void {
  if (!result.ok) {
    const status = result.reason === "not-found" ? 404 : 409;
    res.status(status).json({ error: result.reason, currentVersion: "currentVersion" in result ? result.currentVersion : undefined });
    return;
  }
  res.status(204).end();
}

export function registerAdminCommentsModerateRoutes(app: Express, deps: AdminCommentsModerateDeps): void {
  for (const spec of ACTIONS) {
    app.post(`/api/admin/v1/workspaces/:workspaceId/comments/:commentId/${spec.path}`, async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      try {
        const principal = getAuthedPrincipal(res);
        const authResult = await deps.authorize({
          principalId: principal.id,
          permission: spec.permission,
          workspaceId: deps.workspaceId,
          entityType: "comment",
          entityId: req.params.commentId,
        });
        if (!authResult.allowed) {
          res.status(403).json({
            error: `principal '${principal.id}' is not authorized for '${spec.permission}' (${authResult.reason})`,
            code: "FORBIDDEN",
            details: { permission: spec.permission, reason: authResult.reason },
          });
          return;
        }

        const parsedBody = parseModerationBody(req.body);
        if (!parsedBody) {
          res.status(400).json({ error: "expectedVersion is required and must be a non-negative integer" });
          return;
        }

        const result = await deps.commentWriteService.applyModeration({
          workspaceId: deps.workspaceId,
          id: req.params.commentId,
          expectedVersion: parsedBody.expectedVersion,
          action: spec.action,
          toStatus: spec.toStatus!,
          actorPrincipalId: principal.id,
          note: parsedBody.note,
        });

        respondToModerationResult(res, result);
      } catch (err) {
        sendAdminFailure({ res, error: err }, { operation: "routes/comments/moderate", code: "INTERNAL_ERROR" });
      }
    });
  }

  app.post("/api/admin/v1/workspaces/:workspaceId/comments/:commentId/purge", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "comments.delete.force",
        workspaceId: deps.workspaceId,
        entityType: "comment",
        entityId: req.params.commentId,
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'comments.delete.force' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "comments.delete.force", reason: authResult.reason },
        });
        return;
      }

      const body = req.body as Record<string, unknown>;
      const result = await deps.commentWriteService.purge({
        workspaceId: deps.workspaceId,
        id: req.params.commentId,
        actorPrincipalId: principal.id,
        note: typeof body.note === "string" ? body.note : null,
      });

      if (!result.ok) {
        res.status(404).json({ error: result.reason });
        return;
      }
      res.status(204).end();
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/comments/moderate", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { optionalOneOf, optionalString, readToolLimit, ToolInputError } from "@jini-ai/core";
import type { Express } from "express";

import { COMMENT_STATUSES, type CommentRepoPort, type CommentStatus } from "@jini-ai/cms/comments";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file ADR-031 §6 (SPEC-033) — `GET /api/admin/v1/workspaces/:workspaceId/comments/queue`, the
 * moderation queue read. `comments.read`-gated. Mirrors this session's established admin-route
 * shape (workspace-id 404 check → authorize() → 403-on-denial → proceed).
 */
export type AdminCommentsModerationQueueDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & {
  commentRepo: CommentRepoPort;
};

/** Reads the query string through the same Jini checks the `comments_list_moderation_queue` tool
 *  uses, so an off-enum `status` or a malformed `limit` is a 400 rather than a silent `pending` page
 *  or a clamped one. A `limit` above 100 is still capped, as the tool schema promises.
 *  @throws {ToolInputError} naming the bad field.
 *  @complexity O(1). */
function parseQueueQuery(query: Record<string, unknown>): { status: CommentStatus; limit: number; cursor: string | null } {
  const input = { status: query.status, limit: query.limit === undefined ? undefined : Number(query.limit) };
  return {
    status: optionalOneOf({ input, key: "status", values: COMMENT_STATUSES }) ?? "pending",
    limit: readToolLimit({ input, max: 100, fallback: 20 }),
    // A repeated `cursor` arrives as an array: refused, not read as "no cursor" and page 1.
    cursor: optionalString({ input: query, key: "cursor" }) ?? null,
  };
}

export function registerAdminCommentsModerationQueueRoute(app: Express, deps: AdminCommentsModerationQueueDeps): void {
  app.get("/api/admin/v1/workspaces/:workspaceId/comments/queue", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "comments.read",
        workspaceId: deps.workspaceId,
        entityType: "comment",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'comments.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "comments.read", reason: authResult.reason },
        });
        return;
      }

      const { status, limit, cursor } = parseQueueQuery(req.query);
      const page = await deps.commentRepo.listModerationQueue({ workspaceId: deps.workspaceId, status, limit, cursor });
      res.json(page);
    } catch (err) {
      // A bad query value, or a cursor naming no comment (the repo's `invalid cursor`).
      if (err instanceof ToolInputError) {
        res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/comments/moderation-queue", code: "INTERNAL_ERROR" });
    }
  });
}

