import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { acquireOperationLock, releaseOperationLock } from "#src/contracts/core/operation-lock";
import { authorizeForHooks, confirm, execute, ForbiddenError, PlanStaleError, plan, type GatedMutationHooks } from "#src/contracts/core/gated-mutations/gateway";
import { TokenAlreadyRedeemedError, TokenExpiredError } from "#src/contracts/core/gated-mutations/token";
import {
  executeMigrateForward,
  MigrationAlreadyInFlightError,
  RestorePointUnavailableError,
} from "#src/features/database/migrate-forward/execute";
import { buildConfirmOnlyHooks } from "#src/contracts/core/gated-mutations/composition";
import { buildMigrateForwardHooks } from "#src/features/database/gated-hooks";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

const MIGRATE_PERMISSION = "database.migrate";

/**
 * @file SPEC-017 C-103/C-105 — `POST /api/admin/v1/database/migrate-forward/{plan,confirm,execute}`
 * (ADR-041 §3's forward-migrate ceremony). Gated by `database.read` (`plan`) / `database.migrate`
 * (`confirm`/`execute`). Mirrors `routes/admin/taxonomy/merge-term.ts`'s 3-endpoint shape — the
 * `/execute` step additionally wires `core/operation-lock.ts`'s cross-domain lock via
 * `migrate-forward/execute.ts`'s own `executeMigrateForward` orchestration wrapper (U-003-ORD1:
 * lock acquired strictly before the gateway's own `execute()` runs).
 */
function statusFor(err: unknown): { status: number; code: string } {
  if (err instanceof ForbiddenError) return { status: 403, code: err.reasonCode };
  if (err instanceof PlanStaleError) return { status: 409, code: "PLAN_STALE" };
  if (err instanceof TokenExpiredError) return { status: 409, code: "TOKEN_EXPIRED" };
  if (err instanceof TokenAlreadyRedeemedError) return { status: 409, code: "TOKEN_ALREADY_REDEEMED" };
  if (err instanceof RestorePointUnavailableError) return { status: 409, code: "RESTORE_POINT_UNAVAILABLE" };
  if (err instanceof MigrationAlreadyInFlightError) return { status: 409, code: "OPERATION_IN_FLIGHT" };
  return { status: 500, code: "INTERNAL_ERROR" };
}

export function registerAdminDatabaseMigrateForwardRoutes(app: Express, deps: RouteDeps): void {
  app.post("/api/admin/v1/database/migrate-forward/plan", async (_req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const hooks = buildMigrateForwardHooks({
        workspaceId: deps.workspaceId,
        actorId: principal.id,
        clock: deps.clock,
        idGen: deps.idGen,
        dbOps: deps.dbOps,
        restorePointsRepo: deps.restorePointsRepo,
        databaseLedgerRepo: deps.databaseLedgerRepo,
      });

      const result = await plan({
        deps: deps.gatedMutations.gatewayDeps,
        principalId: principal.id,
        principalKind: "user",
        hooks: hooks as unknown as GatedMutationHooks<unknown, unknown>,
      });

      res.json(result);
    } catch (err) {
      const { status, code } = statusFor(err);
      if (status === 500) { sendAdminFailure({ res, error: err }, { code }); return; }
      res.status(status).json({ error: err instanceof Error ? err.message : "internal error", code });
    }
  });

  app.post("/api/admin/v1/database/migrate-forward/confirm", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const { planId, planHash } = req.body ?? {};
      if (typeof planId !== "string" || typeof planHash !== "string") {
        res.status(400).json({ error: "'planId' and 'planHash' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const hooks = buildConfirmOnlyHooks({
        domain: MIGRATE_PERMISSION,
        readPermission: "database.read",
        mutatePermission: MIGRATE_PERMISSION,
        scopeId: deps.workspaceId,
        scopeKind: "instance",
      });

      const record = await confirm({
        deps: deps.gatedMutations.gatewayDeps,
        principalId: principal.id,
        principalKind: "user",
        hooks,
        planId,
        planHash,
      });

      res.json({ confirmationToken: record.confirmationToken });
    } catch (err) {
      const { status, code } = statusFor(err);
      if (status === 500) { sendAdminFailure({ res, error: err }, { code }); return; }
      res.status(status).json({ error: err instanceof Error ? err.message : "internal error", code });
    }
  });

  app.post("/api/admin/v1/database/migrate-forward/execute", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);

      // Audit finding AUD-001 (2026-07-16, external audit TM-20260716-full-session-001):
      // executeMigrateForward acquires the shared cross-domain operation lock strictly before
      // gatewayExecute() runs (U-003-ORD1) -- that ordering exists for mutation-failure/lock-leak
      // safety, not authorization, so an unauthorized-but-authenticated caller could still reach
      // and briefly hold the lock before the gateway's own authorize() rejected them, contending
      // with a concurrent authorized migration. Authorize inline, before any lock acquisition; the
      // gateway's fresh authorize() re-check at execute time (CIC U-001) remains the authoritative
      // check and is unchanged by this.
      //
      // Routed through `authorizeForHooks` (not a hardcoded `deps.authorize` workspace-scoped
      // call) with `scopeKind: "instance"` -- `database.migrate`'s real scope, per
      // `features/database/gated-hooks.ts`'s `buildMigrateForwardHooks` doc comment -- so this
      // pre-check agrees with what `execute()`'s own internal check will decide. A hardcoded
      // workspace-scoped check here would let a workspace-scoped-but-not-instance-authorized
      // caller pass this gate, briefly hold the lock, and only then be rejected deeper inside
      // `execute()` -- reopening the very race AUD-001 closed, one layer up.
      const authResult = await authorizeForHooks(
        deps.gatedMutations.gatewayDeps,
        buildConfirmOnlyHooks({
          domain: MIGRATE_PERMISSION,
          readPermission: "database.read",
          mutatePermission: MIGRATE_PERMISSION,
          scopeId: deps.workspaceId,
          scopeKind: "instance",
        }),
        { principalId: principal.id, permission: MIGRATE_PERMISSION }
      );
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'database.migrate' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: MIGRATE_PERMISSION, reason: authResult.reason },
        });
        return;
      }

      const { confirmationToken } = req.body ?? {};
      if (typeof confirmationToken !== "string") {
        res.status(400).json({ error: "'confirmationToken' (string) is required", code: "VALIDATION_ERROR" });
        return;
      }

      const hooks = buildMigrateForwardHooks({
        workspaceId: deps.workspaceId,
        actorId: principal.id,
        clock: deps.clock,
        idGen: deps.idGen,
        dbOps: deps.dbOps,
        restorePointsRepo: deps.restorePointsRepo,
        databaseLedgerRepo: deps.databaseLedgerRepo,
      });

      const capabilities = await deps.dbOps.getCapabilities();

      const result = await executeMigrateForward({
        siteId: deps.workspaceId,
        confirmationToken,
        costClass: capabilities.restorePoint.costClass,
        operationLock: { acquireOperationLock, releaseOperationLock },
        gatewayExecute: () =>
          execute({
            deps: deps.gatedMutations.gatewayDeps,
            principalId: principal.id,
            principalKind: "user",
            hooks: hooks as unknown as GatedMutationHooks<unknown, { migrated: true }>,
            confirmationToken,
          }),
      });

      res.json(result);
    } catch (err) {
      const { status, code } = statusFor(err);
      if (status === 500) { sendAdminFailure({ res, error: err }, { code }); return; }
      res.status(status).json({ error: err instanceof Error ? err.message : "internal error", code });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Response } from "express";
import { randomUUID } from "node:crypto";

import {
  listRestorePoints,
  createRestorePoint,
  RestorePointUnavailableError,
  ValidationError,
  type RestorePointCostClass,
} from "#src/features/database/restore-points";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { DatabaseRecoveryRouteDeps } from "../database-recovery/deps.js";

/**
 * This route's three writable POST body fields, read off an untyped body in one place.
 *
 * `idempotencyKey` omission (line below, `randomUUID()`) is a deliberate opt-out, not a bug: no
 * caller in this codebase sends `idempotencyKey` today (the admin UI never does), so making it
 * required would turn every existing real call into a 400 for a body shape no one currently
 * requests updating. A caller that wants retry-safety must supply its own key; one that omits it
 * gets a fresh key per request and is treated as "not asking for idempotency," matching the
 * `findExistingRestorePointSummary` check below, which only ever short-circuits a key the caller
 * chose to repeat.
 *
 * @complexity O(1).
 */
function parseRestorePointCreateBody(rawBody: unknown): { trigger: string; costAck: boolean; idempotencyKey: string } {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    trigger: typeof body.trigger === "string" ? body.trigger : "manual",
    costAck: body.costAck === true,
    idempotencyKey: typeof body.idempotencyKey === "string" ? body.idempotencyKey : randomUUID(),
  };
}

/**
 * Resolves the two fields the `capture` closure fills in, into the shape `restorePointsRepo.save`
 * persists — `watermarkAtCapture` defaults to `null` (never captured), `artifactRef` stays
 * `undefined` the same way the inline version did (see the 2026-07-16 note this route carries).
 *
 * @complexity O(1).
 */
function toCapturedRow(captured: { artifactRef: string; watermarkAtCapture: number } | undefined): {
  watermarkAtCapture: number | null;
  artifactRef: string | undefined;
} {
  return {
    watermarkAtCapture: captured?.watermarkAtCapture ?? null,
    artifactRef: captured?.artifactRef,
  };
}

/**
 * AC-11 idempotency check — if `idempotencyKey` already names a persisted restore point, reconstructs
 * the same `{id, costClass, kind}` summary shape a fresh create returns, instead of re-running the
 * real (costly) `capture()` and inserting a second ledger row. Must be called BEFORE `capture()`,
 * not merely before `save()` — checking only before the insert still burns a real backup on every
 * retry.
 *
 * Pairs the narrow `findByIdempotencyKey` lookup with the same `list()` read the GET route already
 * serves, rather than widening `findByIdempotencyKey`'s own return shape — no change needed to
 * either concrete repo (`SqliteRestorePointsRepo`/`InMemoryRestorePointsRepo` already implement
 * both methods). Mirrors `features/recovery/repo.memory.ts`'s `RestorePointDeepLinkLookup` for the
 * identical accepted O(n) tradeoff (restore points are an operator-curated, low-volume list).
 *
 * Two concurrent requests sharing the same key can still both miss this lookup and both capture —
 * this check alone does not close that race. The `(site_id, idempotency_key)` unique index on the
 * `restore_points` table (`database-journal-schema.ts`) prevents a second row from being persisted,
 * but does not prevent a second real capture from running; closing that fully needs an in-process
 * lock, which is out of scope here (see this dispatch's report).
 *
 * @complexity O(1) lookup plus O(n) over the restore-points list only when a repeat key is found.
 */
async function findExistingRestorePointSummary(
  repo: DatabaseRecoveryRouteDeps["restorePointsRepo"],
  idempotencyKey: string
): Promise<{ id: string; costClass: RestorePointCostClass; kind: string } | undefined> {
  const existing = await repo.findByIdempotencyKey(idempotencyKey);
  if (!existing) return undefined;

  const items = await repo.list();
  const row = items.find((item) => item.id === existing.restorePointId);
  // Defensive: the idempotency index just resolved this id, so a missing row here would mean the
  // two reads observed inconsistent state, not a legitimate "not found" — surface it as an error
  // rather than silently falling through to re-capture (which is what this function exists to
  // prevent).
  if (!row) {
    throw new Error(`restore point '${existing.restorePointId}' has a known idempotency key but no persisted row`);
  }
  return { id: row.id, costClass: row.costClass as RestorePointCostClass, kind: row.kind };
}

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendRestorePointCreateError(res: Response, err: unknown): void {
  if (err instanceof RestorePointUnavailableError) {
    res.status(409).json({ error: err.message, code: "RESTORE_POINT_UNAVAILABLE" });
    return;
  }
  if (err instanceof ValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/database/restore-points", code: "INTERNAL_ERROR" });
}

/**
 * @file design-spec.md §3.2/§3.8 — `GET /api/admin/v1/database/restore-points` (newest-first
 * restore-points list, the shared column source Database's and Recovery's own restore-points list
 * views both read — `database.read`'s own description already names "restore points" as part of
 * what it covers, ADR-041 §6). Gated by `database.read`.
 */
export function registerAdminDatabaseRestorePointsListRoute(app: Express, deps: DatabaseRecoveryRouteDeps): void {
  app.get("/api/admin/v1/database/restore-points", async (_req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "database.read",
        workspaceId: deps.workspaceId,
        entityType: "restore-point",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'database.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "database.read", reason: authResult.reason },
        });
        return;
      }

      const result = await listRestorePoints({ repo: deps.restorePointsRepo });
      res.json(result);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/database/restore-points", code: "INTERNAL_ERROR" });
    }
  });
}

/**
 * @file design-spec.md §3.3/§3.8 — `POST /api/admin/v1/database/restore-points` (mints an ad hoc
 * restore point independent of any migration, REQ-22/AC-26/AC-27). Gated by `backup.create`.
 *
 * Composes two already-certified pieces without modifying either: `database/restore-points.ts`'s
 * `createRestorePoint` (the cost-gate decision + the real `dbOps.captureRestorePoint()` backup)
 * and `restorePointsRepo.save()` (the durable row `createRestorePoint` itself never writes — see
 * that function's own doc comment: persistence is deliberately the caller's job). The `capture`
 * closure's result is captured via an outer variable so the route can persist the real
 * `artifactRef`/`watermarkAtCapture` `createRestorePoint`'s return value does not carry.
 */
export function registerAdminDatabaseRestorePointsCreateRoute(app: Express, deps: DatabaseRecoveryRouteDeps): void {
  app.post("/api/admin/v1/database/restore-points", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "backup.create",
        workspaceId: deps.workspaceId,
        entityType: "restore-point",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'backup.create' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "backup.create", reason: authResult.reason },
        });
        return;
      }

      const { trigger, costAck, idempotencyKey } = parseRestorePointCreateBody(req.body);

      // AC-11: a repeat idempotencyKey returns the ORIGINAL restore point — checked before any
      // capability/cost-gate work and, critically, before `capture()` below, since the whole point
      // is to never re-run the real (costly) backup on a retry.
      const existingSummary = await findExistingRestorePointSummary(deps.restorePointsRepo, idempotencyKey);
      if (existingSummary) {
        res.status(201).json({ restorePoint: existingSummary });
        return;
      }

      const capabilities = await deps.dbOps.getCapabilities();
      let captured: { artifactRef: string; watermarkAtCapture: number } | undefined;

      const summary = await createRestorePoint({
        costClass: capabilities.restorePoint.costClass,
        kind: capabilities.restorePoint.kind,
        costAck,
        capture: async () => {
          captured = await deps.dbOps.captureRestorePoint({ scopeId: deps.workspaceId });
          return captured;
        },
      });

      await deps.restorePointsRepo.save({
        restorePointId: summary.id,
        idempotencyKey,
        trigger,
        createdAt: deps.clock.nowIso(),
        createdBy: principal.id,
        costClass: summary.costClass,
        kind: summary.kind,
        // 2026-07-16: was captured above but previously never persisted — the root cause of why
        // Recovery's restore ceremony could only write a "ledger-only" note (no way to know which
        // file to restore from). See `features/recovery/gated-hooks.ts`'s `buildRestoreHooks`.
        ...toCapturedRow(captured),
      });

      res.status(201).json({ restorePoint: summary });
    } catch (err) {
      sendRestorePointCreateError(res, err);
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { DatabaseRecoveryRouteDeps } from "../database-recovery/deps.js";

/**
 * @file ADR-041 §3 — `GET /api/admin/v1/database/schema-state` (this site's drift classification:
 * its persisted `.site-meta.json` schema stamp versus the runtime's applied `__drizzle_migrations`
 * lineage). Gated by `database.read` (ADR-041 §6's permission catalog), matching `timeline.ts`'s
 * and `restore-points.ts`'s list route exactly.
 *
 * WHY THIS ROUTE EXISTS: `db/drift.ts`'s `getDriftStatus` and its `SqliteDatabaseIntrospection
 * Adapter` caller have both been built and correct for some time, but the only thing that ever
 * called them was the `database_get_schema_state` AGENT tool
 * (`features/database/tool-registrations.ts`). A site owner whose database had diverged onto a
 * different migration lineage had no admin surface that would ever tell them — the Database
 * screen's own file header recorded the drift banner as having "no route yet", and this closes
 * exactly that gap. It is the read half only: nothing here migrates, repairs, or reconciles
 * anything. `migrate-forward.ts`'s plan/confirm/execute ceremony remains the only write path, and
 * it keeps its own independent preflight.
 *
 * PASSTHROUGH, DELIBERATELY: the response body is `SchemaStateSummary` verbatim —
 * `{ status, siteMeta, runtime }` — with no server-side rewording, collapsing, or severity ranking.
 * `status` therefore carries all five values the port can produce (`in-sync`/`ahead`/`behind`/
 * `diverged`/`unknown`), and both snapshots stay independently `null`able. That matters for the
 * `"unknown"` case in particular: `getSchemaState()` returns it whenever either snapshot side is
 * unavailable, and flattening it into a boolean here (or defaulting it toward "fine") would
 * manufacture the exact reassurance `adapter.sqlite.ts`'s own "never fabricated" rule exists to
 * prevent. The client is left to decide how to say "we could not determine this".
 *
 * `databaseIntrospection` was already composed into `RouteDeps` in BOTH composition roots
 * (`server/deps.ts`'s real `SqliteDatabaseIntrospectionAdapter`, `server/app.ts`'s
 * `InMemoryDatabaseIntrospectionAdapter`) before this route — it was simply never read over HTTP.
 * See `routes/admin/database-recovery/deps.ts`, whose header previously listed it among the fields
 * excluded from `DatabaseRecoveryRouteDeps` for want of a consumer; this route is that consumer.
 */
export function registerAdminDatabaseSchemaStateRoute(app: Express, deps: DatabaseRecoveryRouteDeps): void {
  app.get("/api/admin/v1/database/schema-state", async (_req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "database.read",
        workspaceId: deps.workspaceId,
        entityType: "database-schema",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'database.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "database.read", reason: authResult.reason },
        });
        return;
      }

      const schemaState = await deps.databaseIntrospection.getSchemaState();
      res.json(schemaState);
    } catch (err) {
      // No `status` field on this envelope, deliberately: a caller that cannot read a status must
      // see the read FAIL, not receive a clean-looking one. See this file's header.

      sendAdminFailure({ res, error: err }, { operation: "routes/database/schema-state", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { ToolInputError } from "@jini-ai/core";
import type { Express, Response } from "express";

import { getTimeline } from "#src/features/database/timeline";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { DatabaseRecoveryRouteDeps } from "../database-recovery/deps.js";

/** A query field, read as a string if present, or `undefined`.
 *  @complexity O(1). */
function readOptionalQueryString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

/** This route's six filter fields, read off `req.query` in one place.
 *  @complexity O(1). */
function parseTimelineFilter(query: Record<string, unknown>) {
  return {
    kind: readOptionalQueryString(query.kind),
    outcome: readOptionalQueryString(query.outcome),
    fromDate: readOptionalQueryString(query.fromDate),
    toDate: readOptionalQueryString(query.toDate),
    cursor: readOptionalQueryString(query.cursor),
    limit: typeof query.limit === "string" ? Number(query.limit) : undefined,
  };
}

/** Maps `getTimeline`'s thrown errors onto the admin error envelope — a `TimelineValidationError`
 *  (matched by `name` since it isn't an exported class here) or the ledger's `ToolInputError` (an
 *  undecodable cursor) is a 400, everything else a 500.
 *  @complexity O(1). */
function sendTimelineError(res: Response, err: unknown): void {
  const isValidationError = err instanceof ToolInputError || (err instanceof Error && err.name === "TimelineValidationError");
  if (!isValidationError) { sendAdminFailure({ res, error: err }); return; }
  const message = err instanceof Error ? err.message : "Invalid timeline query.";
  res.status(400).json({
    error: message,
    code: isValidationError ? "VALIDATION_ERROR" : "INTERNAL_ERROR",
  });
}

/**
 * @file SPEC-017 C-101 / REQ-01 / REQ-04 — `GET /api/admin/v1/database/timeline` (ADR-041 §1's
 * read-first Timeline). Gated by `database.read` (ADR-041 §6's permission catalog).
 *
 * The first (and, for this dispatch, only) Database/Recovery admin route wired end-to-end against
 * a real adapter (`SqliteDatabaseLedgerRepo`, `server/deps.ts`) — demonstrates the sidecar journal
 * is genuinely reachable over HTTP, following the exact pattern
 * `routes/admin/redirects/list.ts` already established. The remaining Database/Recovery API
 * surface (migrate-forward plan/confirm/execute, restore-point creation, the restore ceremony,
 * the Tier-3 browser) stays unwired — that is the admin-UI-adjacent backend work item B in
 * `todos.md` anticipates, not this slice's scope (see the progress ledger's Session 4 entry).
 */
export function registerAdminDatabaseTimelineRoute(app: Express, deps: DatabaseRecoveryRouteDeps): void {
  app.get("/api/admin/v1/database/timeline", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "database.read",
        workspaceId: deps.workspaceId,
        entityType: "database-ledger",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'database.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "database.read", reason: authResult.reason },
        });
        return;
      }

      const result = await getTimeline({
        ledger: deps.databaseLedgerRepo,
        filter: parseTimelineFilter(req.query as Record<string, unknown>),
      });

      res.json(result);
    } catch (err) {
      sendTimelineError(res, err);
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Request, Response } from "express";

import {
  createEmailTemplate,
  editEmailTemplate,
  EmailTemplateInputError,
  EmailTemplateNotFoundError,
  EmailTemplateVersionConflictError,
  getEmailTemplate,
  listEmailTemplates,
  previewEmailTemplate,
  readFieldValues,
  renameEmailTemplate,
  renderEmailTemplateForSend,
  type EmailTemplateDeps,
} from "#src/features/email-templates/index";
import { PAGES_EDIT_HTML_PERMISSION } from "#src/features/pages/index";
import { entityNotLiveResponse } from "#src/server/inbound/admin-http/http/entity-not-live";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { CONTENT_ENTRY_MAX_BODY_BYTES, rejectOversizedJsonBody } from "#src/server/inbound/shared/body-size-limit";
import type { ContentRouteDeps, ContentRouteRegistrar } from "../content/deps.js";

/**
 * @file Admin HTTP surface for HTML email templates. Each handler is a permission check plus ONE
 * shared operation from `features/email-templates/operations.ts` — the same call the
 * `email_template_*` assistant tools make — so the two surfaces cannot drift.
 *
 * Permissions are existing names: reading/previewing is `content.read` and writing raw HTML is
 * `pages.edit_html`, the Pages HTML gates (a template is raw HTML on Pages storage); the send
 * render is `admin.forms.manage`, the mail-status/test-send gate, because its output is what a
 * send path mails.
 *
 * The admin preview HTML keeps the template's scripts. Show it the way the Pages editor shows a
 * Page — in the sandboxed preview iframe WITHOUT `allow-same-origin` (admin `features/pages/
 * rules.ts`'s `PAGE_PREVIEW_IFRAME_SANDBOX`) — never inline in the admin document.
 */

const BASE = "/api/admin/v1/workspaces/:workspaceId/email-templates";

type Handler = (req: Request, res: Response, deps: EmailTemplateDeps) => Promise<unknown>;

/** Maps an operation failure onto its HTTP shape, mirroring `pages/update-html.ts`'s codes. */
function sendError(res: Response, err: unknown): void {
  const live = entityNotLiveResponse(err);
  if (live) {
    res.status(live.status).json(live.body);
    return;
  }
  if (err instanceof EmailTemplateNotFoundError) {
    res.status(404).json({ error: err.message, code: "ENTRY_NOT_FOUND" });
    return;
  }
  if (err instanceof EmailTemplateInputError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof EmailTemplateVersionConflictError) {
    res.status(409).json({ error: err.message, code: "CONCURRENT_EDIT" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/email-templates/routes", code: "INTERNAL_ERROR" });
}

/** The request body as a record; a missing or non-object body reads as `{}` so validation names the field. */
function body(req: Request): Record<string, unknown> {
  const value: unknown = req.body;
  return value !== null && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

/** Workspace check, then authorization BEFORE any body validation, then the operation. */
function route(deps: ContentRouteDeps, permission: string, handler: Handler, status = 200) {
  return async (req: Request, res: Response) => {
    if (String(req.params.workspaceId) !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission, workspaceId: deps.workspaceId }))) return;
      res.status(status).json(await handler(req, res, deps));
    } catch (err) {
      sendError(res, err);
    }
  };
}

const actor = (res: Response) => getAuthedPrincipal(res).id;
const templateId = (req: Request) => String(req.params.templateId);

/**
 * - `GET    …/email-templates` (`content.read`) -> `{ templates: EmailTemplateSummary[] }`
 * - `POST   …/email-templates` (`pages.edit_html`) `{ name, html?, subject?, fields? }` -> 201 detail
 * - `POST   …/email-templates/preview` (`content.read`) `{ id? | html?, values?, mode? }` -> preview
 * - `GET    …/email-templates/:templateId` (`content.read`) -> detail
 * - `PUT    …/email-templates/:templateId/html` (`pages.edit_html`) `{ html, expectedVersion? }` -> detail
 * - `PATCH  …/email-templates/:templateId` (`pages.edit_html`) `{ name, expectedVersion? }` -> detail (rename; trash is the
 *   generic `POST …/trash/items {type: "email-template", id}` on the scoped Trash registration)
 * - `POST   …/email-templates/:templateId/render` (`admin.forms.manage`) `{ values? }` -> `{ subject, html, text, missingFields }`
 */
export const registerAdminEmailTemplateRoutes: ContentRouteRegistrar = (app, deps) => {
  const limit = rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES });
  app.get(BASE, route(deps, "content.read", (req, _res, ops) => listEmailTemplates({ deps: ops, input: req.query })));
  app.post(BASE, limit, route(deps, PAGES_EDIT_HTML_PERMISSION, (req, res, ops) => createEmailTemplate({ deps: ops, input: body(req), actorId: actor(res) }), 201));
  // Before `/:templateId` routes only for readability: methods and segment counts already differ.
  app.post(`${BASE}/preview`, limit, route(deps, "content.read", (req, _res, ops) => previewEmailTemplate({ deps: ops, input: body(req) })));
  app.get(`${BASE}/:templateId`, route(deps, "content.read", (req, _res, ops) => getEmailTemplate({ deps: ops, id: templateId(req) })));
  app.put(`${BASE}/:templateId/html`, limit, route(deps, PAGES_EDIT_HTML_PERMISSION, (req, res, ops) => editEmailTemplate({ deps: ops, input: { ...body(req), id: templateId(req) }, actorId: actor(res) })));
  app.patch(`${BASE}/:templateId`, limit, route(deps, PAGES_EDIT_HTML_PERMISSION, (req, _res, ops) => renameEmailTemplate({ deps: ops, input: { ...body(req), id: templateId(req) } })));
  app.post(`${BASE}/:templateId/render`, limit, route(deps, "admin.forms.manage", (req, _res, ops) => renderEmailTemplateForSend({ deps: ops, id: templateId(req), values: readFieldValues({ value: body(req).values }) })));
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
import { toEntryOutbox } from "#src/features/entries/index";
import { createEntry } from "#src/features/entries/index";
import { processOutbox } from "#src/contracts/core/events/index";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentTypesRouteDeps } from "../content-types/deps.js";
import { entryWriteErrorStatus } from "./write-error-status.js";

/** This route's required `type`/`slug`/`title` (strings) plus the optional `fieldsJson`/`bodyJson`
 *  fields, read off an untyped body in one place. `null` means the required strings failed
 *  validation. @complexity O(1). */
function parseCreateEntryBody(
  rawBody: unknown
): { type: string; slug: string; title: string; fieldsJson: unknown; bodyJson: unknown } | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  if (typeof body.type !== "string" || typeof body.slug !== "string" || typeof body.title !== "string") return null;
  return {
    type: body.type,
    slug: body.slug,
    title: body.title,
    fieldsJson: body.fieldsJson ?? { ext: { site: {} } },
    bodyJson: body.bodyJson,
  };
}

/**
 * @file design-spec.md §1.5/§1.9 — `POST /api/admin/v1/entries` (creates a Collection entry,
 * REQ-13/14/19). Gated by `admin.collections.manage`.
 */
export function registerAdminEntryCreateRoute(app: Express, deps: ContentTypesRouteDeps): void {
  app.post("/api/admin/v1/entries", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.collections.manage",
        workspaceId: deps.workspaceId,
        entityType: "entry",
      });
      if (!authorized) return;

      const parsedBody = parseCreateEntryBody(req.body);
      if (!parsedBody) {
        res.status(400).json({ error: "'type', 'slug', and 'title' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const result = await createEntry({
        deps: {
          entryRepo: deps.entryRepo,
          contentTypeRepo: deps.contentTypeRepo,
          clock: deps.clock,
          ids: deps.idGen,
          // Jini passes entity scope separately; merge it into the host evaluator's request.
          authorize: adaptLegacyAuthorize({ authorize: deps.authorize }),
          outbox: toEntryOutbox(deps),
        },
        input: {
          actorId: principal.id,
          workspaceId: deps.workspaceId,
          ...parsedBody,
        },
      });

      if (!result.ok) {
        const { status, code } = entryWriteErrorStatus({ error: result.error });
        if (status === 500) { sendAdminFailure({ res, error: result.error }, { code }); return; }
        res.status(status).json({ error: result.error.message, code });
        return;
      }

      // 2026-09-03 outbox-drain audit fix — drains the outbox so `createEntry`'s `entry.created`
      // event reaches `bus.subscribe`d consumers before the response rather than on the background
      // drainer's next pass (`serving-app.ts`; mirrors `posts/update.ts`'s identical inline
      // `processOutbox` call).
      await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

      res.status(201).json(result.value);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/entries/create", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { adaptLegacyAuthorize } from "@jini-ai/cms/core";
import { ENTRY_LIFECYCLE_OPS, parseEntryLifecycleOp } from "#src/features/entries/index";
import { toEntryOutbox } from "#src/features/entries/index";
import { processOutbox } from "#src/contracts/core/events/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentTypesRouteDeps } from "../content-types/deps.js";
import { entryWriteErrorStatus } from "./write-error-status.js";

/**
 * @file design-spec.md §1.5/§1.9 — `POST /api/admin/v1/entries/:id/lifecycle` (Publish/Unpublish,
 * REQ-28). Gated by `admin.collections.manage`.
 *
 * ADR-042 closed-union-dispatch: `op` is narrowed to {@link
 * import("../../../../../features/entries/lifecycle-dispatch").EntryLifecycleOp} before lookup —
 * mirrors `inbound/admin-http/routes/content-types/lifecycle.ts`'s identical shape.
 */
export function registerAdminEntryLifecycleRoute(app: Express, deps: ContentTypesRouteDeps): void {
  app.post("/api/admin/v1/entries/:id/lifecycle", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.collections.manage",
        workspaceId: deps.workspaceId,
        entityType: "entry",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.collections.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.collections.manage", reason: authResult.reason },
        });
        return;
      }

      const body = req.body ?? {};
      const op = parseEntryLifecycleOp({ op: body.op });
      if (!op) {
        res.status(400).json({ error: "'op' must be one of 'publish', 'unpublish'", code: "VALIDATION_ERROR" });
        return;
      }
      if (typeof body.expectedVersion !== "number") {
        res.status(400).json({ error: "'expectedVersion' (number) is required", code: "VALIDATION_ERROR" });
        return;
      }

      const handler = ENTRY_LIFECYCLE_OPS[op];
      const result = await handler({
        deps: {
          entryRepo: deps.entryRepo,
          contentTypeRepo: deps.contentTypeRepo,
          clock: deps.clock,
          // Jini passes entity scope separately; merge it into the host evaluator's request.
          authorize: adaptLegacyAuthorize({ authorize: deps.authorize }),
          outbox: toEntryOutbox(deps),
        },
        input: {
          actorId: principal.id,
          workspaceId: deps.workspaceId,
          id: String(req.params.id),
          expectedVersion: body.expectedVersion,
        },
      });

      if (!result.ok) {
        const { status, code } = entryWriteErrorStatus({ error: result.error });
        if (status === 500) { sendAdminFailure({ res, error: result.error }, { code }); return; }
        res.status(status).json({ error: result.error.message, code });
        return;
      }

      // 2026-09-03 outbox-drain audit fix — drains the outbox so `publishEntry`/`unpublishEntry`'s
      // `entry.published`/`entry.unpublished` event reaches `bus.subscribe`d consumers before the
      // response rather than on the background drainer's next pass (`serving-app.ts`; mirrors
      // `posts/update.ts`'s identical inline `processOutbox` call).
      await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

      res.json(result.value);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/entries/lifecycle", code: "INTERNAL_ERROR" });
    }
  });
}

