/**
 * @file design-spec.md §1.5/§1.9 — `PUT /api/admin/v1/entries/:id` (updates an entry's
 * title/fieldsJson, REQ-28). Gated by `admin.collections.manage`.
 */
export function registerAdminEntryUpdateRoute(app: Express, deps: ContentTypesRouteDeps): void {
  app.put("/api/admin/v1/entries/:id", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.collections.manage",
        workspaceId: deps.workspaceId,
        entityType: "entry",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.collections.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.collections.manage", reason: authResult.reason },
        });
        return;
      }

      const body = req.body ?? {};
      if (typeof body.expectedVersion !== "number") {
        res.status(400).json({ error: "'expectedVersion' (number) is required", code: "VALIDATION_ERROR" });
        return;
      }

      const result = await updateEntry({
        deps: {
          entryRepo: deps.entryRepo,
          contentTypeRepo: deps.contentTypeRepo,
          clock: deps.clock,
          // Jini passes entity scope separately; merge it into the host evaluator's request.
          authorize: adaptLegacyAuthorize({ authorize: deps.authorize }),
          outbox: toEntryOutbox(deps),
        },
        input: {
          actorId: principal.id,
          workspaceId: deps.workspaceId,
          id: String(req.params.id),
          title: typeof body.title === "string" ? body.title : undefined,
          fieldsJson: body.fieldsJson,
          // Forwarded rather than dropped. `features/entries/write-service.ts`'s
          // `updateEntry` has always supported `bodyJson` (and leaves the stored
          // value alone when it is `undefined`), but this route never read it —
          // so a rich-text edit to an existing entry returned 200 while the body
          // silently kept its pre-edit value. Two independent audits reproduced
          // that end to end, including with `bodyJson` explicitly in the request.
          //
          // `undefined` when absent is load-bearing: it is what makes a
          // title-only or fields-only PUT keep the existing body instead of
          // clearing it.
          bodyJson: "bodyJson" in body ? body.bodyJson : undefined,
          expectedVersion: body.expectedVersion,
        },
      });

      if (!result.ok) {
        const { status, code } = entryWriteErrorStatus({ error: result.error });
        if (status === 500) { sendAdminFailure({ res, error: result.error }, { code }); return; }
        res.status(status).json({ error: result.error.message, code });
        return;
      }

      // 2026-09-03 outbox-drain audit fix — drains the outbox so `updateEntry`'s `entry.updated`
      // event reaches `bus.subscribe`d consumers before the response rather than on the background
      // drainer's next pass (`serving-app.ts`; mirrors `posts/update.ts`'s identical inline
      // `processOutbox` call).
      await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

      res.json(result.value);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/entries/update", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { readServerAdmissions } from "#src/server/runtime/services/external-mcp-admissions";
import type { ExternalMcpRouteRegistrar } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

/**
 * Reports the server-owned federation's live admissions after the workspace/permission gate.
 * A missing or still-connecting reader answers a distinguishable 503, never an empty roster:
 * an empty list means no tools were admitted, whereas an unavailable report cannot say that.
 * The legacy failure code remains until the admin client's unavailable-state contract migrates.
 * @complexity O(1) dispatch plus the server reader's bounded federation wait.
 */
export const registerAdminExternalMcpAdmissionsRoute: ExternalMcpRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/mcp-servers/admissions", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;

      const result = await (deps.externalMcpAdmissions?.() ?? readServerAdmissions({}, {}));
      if (!result.ok) {
        res.status(503).json(result.body);
        return;
      }
      res
        .status(200)
        .json(result.configFailures !== undefined ? { connections: result.connections, configFailures: result.configFailures } : { connections: result.connections });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/external-mcp/admissions", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { isBuiltInExternalMcpServer } from "#src/features/external-mcp/built-in-connections";
import { deleteExternalMcpServer } from "../../../../../features/external-mcp/external-mcp-store.js";
import type { ExternalMcpRouteRegistrar } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

/**
 * DELETE one external MCP server from the workspace's roster.
 *
 * Answers 404 when no row was removed rather than reporting success for an id that never existed —
 * a silent success here would tell an operator a server is gone when what actually happened is that
 * they deleted a typo and the real one is still configured and still being launched at every boot.
 *
 * Its tools refuse from the next call — `external-mcp-revocation.ts`'s per-call gate re-reads the
 * row on every federated call and refuses one whose row is gone. `restartRequired` stays true
 * because the running assistant still holds the open connection and lists the tools until it
 * restarts. The delete itself is unchanged and permanent.
 */
export const registerAdminExternalMcpDeleteRoute: ExternalMcpRouteRegistrar = (app, deps) => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;

      if (isBuiltInExternalMcpServer({ serverId: String(req.params.serverId ?? ""), ids: deps.builtInExternalMcpServerIds })) {
        res.status(409).json({ error: "built-in MCP connections cannot be removed", code: "BUILT_IN_CONNECTION" });
        return;
      }

      const removed = await deleteExternalMcpServer(
        { repo: deps.externalMcpServerRepo },
        { workspaceId: deps.workspaceId, serverId: String(req.params.serverId ?? "") },
      );
      if (!removed) {
        res.status(404).json({ error: "external MCP server was not found", code: "NOT_FOUND" });
        return;
      }

      res.json({ removed: true, restartRequired: true });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/external-mcp/delete", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { describeExternalMcpOwnership } from "#src/features/external-mcp/built-in-connections";
import { listExternalMcpServerViews } from "../../../../../features/external-mcp/external-mcp-store.js";
import type { ExternalMcpRouteRegistrar } from "./deps.js";
