/**
 * GET the workspace's configured external MCP servers, for Settings → External MCP.
 *
 * Serves the read model only: `envNames` without any env VALUE. There is deliberately no route
 * anywhere that returns a stored env value — the tab has no use for one, and an endpoint that
 * decrypted credentials for display would be a strictly worse trade than showing which variables
 * are set. That property is asserted in `external-mcp-store.test.ts`, not merely intended.
 *
 * Never decrypts, so it cannot fail on a rotated or missing site key — the same property
 * `connectors/get-config.ts` and `media/get-providers.ts` rely on.
 * Owner 2026-10-07: safe hints now unseal on the server, without returning secret values. Missing
 * keys still degrade to metadata-only reads; they must not make this settings list unavailable.
 */
export const registerAdminExternalMcpListRoute: ExternalMcpRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/mcp-servers", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const servers = await listExternalMcpServerViews({ repo: deps.externalMcpServerRepo, sealer: deps.siteAssistantSecretSealer }, deps.workspaceId);
      res.json({ servers: servers.map(server => describeExternalMcpOwnership({ server, ids: deps.builtInExternalMcpServerIds })) });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/external-mcp/list", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";
import { randomBytes } from 'node:crypto';
import { generateOAuthState } from '@jini-ai/oauth';
import { browserBindingCookie, EXTERNAL_MCP_BROWSER_BINDING, EXTERNAL_MCP_SIGN_IN_PATH } from '#src/features/api-connections/browser-binding';
import { ApiConnectionError } from "@jini-ai/integrations/api-connections";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { rejectUnlessSessionCredential } from '#src/server/inbound/admin-http/dev-auth';

import { ExternalMcpReauthRequiredError } from "../../../../../features/external-mcp/external-mcp-oauth.js";
import { ExternalMcpSecretStoreUnconfiguredError, ExternalMcpValidationError } from "../../../../../features/external-mcp/external-mcp-store.js";
import type { ExternalMcpOAuthService } from "../../../../../features/external-mcp/contracts.js";
import { OAuthError } from "@jini-ai/oauth";
import type { RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { externalMcpOAuthCallbackUrl } from "#src/server/inbound/public-http/routes/external-mcp/oauth-callback-url";
import type { ExternalMcpRouteDeps } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

const SHARED_MCP_PERMISSION = 'admin.integrations.manage';

/**
 * @file The operator-facing half of external-MCP OAuth: start a connection, poll a device
 * authorization, drop a connection.
 *
 * Three routes, all behind `requireAdminSession` under `/api/admin` and all through
 * `guardExternalMcpRequest`'s `admin.integrations.manage` gate. The fourth route in this flow — the
 * callback — is public and lives in `routes/external-mcp/oauth-callback.ts`, because a
 * `SameSite=Strict` cookie cannot survive the cross-site redirect that reaches it.
 *
 * ## Rate limiting sits IN FRONT of the auth check
 *
 * Same ordering `routes/admin/connectors/connect.ts` uses, and for the same reason restated for
 * this flow: every hit — even one that will be rejected — reaches a handler that mints sealed
 * `state` or makes a real outbound call to a third-party authorization server using the workspace's
 * own client id. `requireAdminSession` bounds WHO can call this, not how often. See
 * `EXTERNAL_MCP_OAUTH_PER_IP`'s doc for the self-DoS this closes.
 *
 * ## Nothing here retries
 *
 * A connect attempt is a foreground action with a human watching. Failures are reported with a
 * specific code and left in a re-clickable state; the operator retries with one click. The machine
 * does not, because an authorization code is single-use and the first response may have been lost
 * after the provider already redeemed it. `@jini-ai/oauth`'s `errors.ts` carries the full argument.
 */

/** OAuth-specific route dependencies, on top of the roster slice the other three routes use.
 *  `externalMcpOAuth` is `RouteDeps`' own optional field, narrowed to required here — a route family
 *  that cannot run without the service should not be able to compile without it. */
export type ExternalMcpOAuthRouteDeps = ExternalMcpRouteDeps & { readonly externalMcpOAuth: ExternalMcpOAuthService };

/**
 * Maps a caught error onto an HTTP response.
 *
 * Provider response bodies never reach the caller — `OAuthError.message` is built from a closed
 * vocabulary, and `operatorAction` is Tovu's own copy. The `retryable` flag is forwarded so an admin
 * client can tell "wait and poll again" from "this is over", without re-deriving that rule.
 *
 * @complexity O(1).
 */
function sendExternalMcpOAuthError(res: import("express").Response, error: unknown): void {
  if (error instanceof ApiConnectionError) { res.status(error.code === 'access-denied' ? 403 : 400).json({ error: error.message, code: error.code }); return; }
  if (error instanceof ExternalMcpValidationError) {
    res.status(400).json({ error: error.message, code: "INVALID_MCP_SERVER", details: { field: error.field } });
    return;
  }
  if (error instanceof ExternalMcpReauthRequiredError) {
    res.status(409).json({ error: error.message, code: error.code, details: { retryable: false, settingsLink: error.settingsLink } });
    return;
  }
  if (error instanceof ExternalMcpSecretStoreUnconfiguredError) {
    // Same status and code `routes/external-mcp/put.ts` already answers with for this class, so an
    // admin client has one contract to handle rather than two. It matters here because the routes
    // that still surface it — connect and the callback, which must OPEN the blob to authenticate to
    // the token endpoint — otherwise fall through to a bare 500 "internal error", which tells an
    // operator whose site key has rotated nothing about the one thing they can act on.
    res.status(503).json({ error: error.message, code: "SECRET_STORE_UNCONFIGURED" });
    return;
  }
  if (error instanceof OAuthError) {
    // 502 for "we could not reach them", 400 for "they refused us or we asked wrongly" — the two
    // demand different things of the operator (wait/check network vs. check configuration), and
    // collapsing them would tell someone behind a flaky network that their client id is wrong.
    const status = error.code === "OAUTH_PROVIDER_UNREACHABLE" ? 502 : 400;
    res.status(status).json({
      error: error.message,
      code: error.code,
      details: {
        retryable: error.retryable,
        operatorAction: error.operatorAction,
        ...(error.retryAfterSeconds === undefined ? {} : { retryAfterSeconds: error.retryAfterSeconds }),
      },
    });
    return;
  }
  sendAdminFailure({ res, error }, { operation: "routes/external-mcp/oauth", code: "INTERNAL_ERROR" });
}

/** Answers the shared limiter check, writing the 429 itself. `Retry-After` is set so a client can
 *  back off correctly instead of hammering. */
async function withinRateLimit(limiter: RateLimiter, req: import("express").Request, res: import("express").Response): Promise<boolean> {
  const result = await limiter.check({ key: resolveClientIp(req) });
  if (result.allowed) return true;
  res.setHeader("Retry-After", String(result.retryAfterSeconds));
  res.status(429).json({
    error: "too many OAuth attempts",
    code: "RATE_LIMIT_EXCEEDED",
    details: { retryAfterSeconds: result.retryAfterSeconds },
  });
  return false;
}

/**
 * `POST .../mcp-servers/:serverId/oauth/connect` — begins an authorization.
 *
 * The response shape is discriminated by `kind`, mirroring the connectors connect route's
 * `auth.kind`: `redirect_required` carries a URL the admin opens in a popup, `device_code` carries a
 * user code and verification URL the admin renders directly. The device variant never returns the
 * device code itself — that stays server-side and the poll route looks it up.
 *
 * The callback URL is built FROM THE REQUEST (`externalMcpOAuthCallbackUrl`) so a reverse-proxied
 * deployment gets the origin the browser actually used, not the one this process thinks it has.
 */
export function registerAdminExternalMcpOAuthConnectRoute(
  app: Express,
  deps: ExternalMcpOAuthRouteDeps,
  limiter: RateLimiter,
): void {
  registerExternalMcpBrowserSignInRoute(app, deps, limiter);
  registerSharedMcpRoutes(app, deps, limiter);
  app.post("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/oauth/connect", async (req, res) => {
    if (!(await withinRateLimit(limiter, req, res))) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const serverId = String(req.params.serverId ?? "");
      const destination = req.body?.destination;
      if (destination !== undefined && destination !== 'shared') throw new ExternalMcpValidationError('Choose local sign-in or save the connection on this Mac.', 'destination');
      if (destination === 'shared' && !rejectUnlessSessionCredential(res, { message: 'Open Settings → External MCP in your signed-in owner browser to save a shared connection.', permission: SHARED_MCP_PERMISSION })) return;
      const started = await deps.externalMcpOAuth.beginConnect({
        serverId, actorId: getAuthedPrincipal(res).id,
        ...(destination === 'shared' ? { destination } : {}),
        redirectUri: externalMcpOAuthCallbackUrl(req, serverId),
        delivery: 'hosted',
      });
      res.json({ auth: started });
    } catch (error) {
      sendExternalMcpOAuthError(res, error);
    }
  });
}

/** Authenticated, user-opened host hop: one cookie and redirect, never proof in a link.
 * @complexity O(1) plus the existing bounded connect/discovery work for one connection.
 */
function registerExternalMcpBrowserSignInRoute(app: Express, deps: ExternalMcpOAuthRouteDeps, limiter: RateLimiter): void {
  app.get(EXTERNAL_MCP_SIGN_IN_PATH, async (req, res) => {
    res.set({ 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer' });
    if (!(await withinRateLimit(limiter, req, res))) return;
    if (!rejectUnlessSessionCredential(res, { message: 'Open this sign-in link from your signed-in Tovu browser, then try again.', permission: SHARED_MCP_PERMISSION })) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const serverId = String(req.params.serverId ?? '');
      const browserBinding = generateOAuthState({ randomBytesFn: ({ byteLength }) => randomBytes(byteLength) }, { stateBytes: 32 });
      const start = await deps.externalMcpOAuth.beginConnect({ serverId, actorId: getAuthedPrincipal(res).id, redirectUri: externalMcpOAuthCallbackUrl(req, serverId), browserBinding });
      if (start.kind !== 'redirect_required') {
        res.status(400).json({ error: 'This connection uses a device code. Close this window and start again from Settings → External MCP.', code: 'MCP_DEVICE_SIGN_IN_REQUIRED' });
        return;
      }
      res.append('Set-Cookie', browserBindingCookie({ browserBinding }, EXTERNAL_MCP_BROWSER_BINDING));
      res.redirect(302, start.authorizationUrl);
    } catch (error) {
      sendExternalMcpOAuthError(res, error);
    }
  });
}

/**
 * `POST .../mcp-servers/:serverId/oauth/device/poll` — one poll of a device authorization.
 *
 * ONE poll per request, deliberately. The loop belongs to the admin client, which already has a
 * timer and a visible cancel affordance; a server-side loop would hold a request open for minutes,
 * hide the RFC 8628 `slow_down` contract inside a catch block, and give the operator nothing to
 * cancel. `status: "pending"` carries the interval to wait before calling again.
 */
export function registerAdminExternalMcpOAuthDevicePollRoute(
  app: Express,
  deps: ExternalMcpOAuthRouteDeps,
  limiter: RateLimiter,
): void {
  app.post("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/oauth/device/poll", async (req, res) => {
    if (!(await withinRateLimit(limiter, req, res))) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      res.json(await deps.externalMcpOAuth.pollDeviceAuthorization({ serverId: String(req.params.serverId ?? "") }));
    } catch (error) {
      sendExternalMcpOAuthError(res, error);
    }
  });
}

/**
 * `DELETE .../mcp-servers/:serverId/oauth` — drops the stored authorization.
 *
 * Clears the token and returns the connection to `disconnected`. It does NOT delete the row: the
 * operator's command, args and allowlist survive, so reconnecting is one click rather than a
 * re-entry. Deleting the server itself is the existing DELETE route's job.
 *
 * Its tools refuse from the next call, the same as DELETE — `external-mcp-revocation.ts`'s per-call
 * gate refuses a `disconnected` OAuth connection on every federated call. `restartRequired` stays
 * true because the running assistant still holds the open connection and lists the tools until it
 * restarts. Unlike DELETE, reconnecting makes them work again without a restart, once the row is
 * back to `connected`.
 *
 * Not rate-limited: it makes no outbound call, so the self-DoS the other two guard against does not
 * exist here.
 */
export function registerAdminExternalMcpOAuthDisconnectRoute(app: Express, deps: ExternalMcpOAuthRouteDeps): void {
  app.delete("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/oauth", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      await deps.externalMcpOAuth.disconnect({ serverId: String(req.params.serverId ?? "") });
      res.json({ disconnected: true, restartRequired: true });
    } catch (error) {
      sendExternalMcpOAuthError(res, error);
    }
  });
}

/** Saved selection is a session-only owner act; a site reference alone cannot grant itself access. */
function registerSharedMcpRoutes(app: Express, deps: ExternalMcpOAuthRouteDeps, limiter: RateLimiter): void {
  const route = "/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/oauth/shared";
  app.get(route, async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      if (!rejectUnlessSessionCredential(res, { message: 'Open saved connections from your signed-in owner browser.', permission: SHARED_MCP_PERMISSION })) return;
      const result = await deps.externalMcpOAuth.listSharedConnections?.({ serverId: String(req.params.serverId), actorId: getAuthedPrincipal(res).id });
      res.json(result ?? { available: false, connections: [], current: null });
    } catch (error) { sendExternalMcpOAuthError(res, error); }
  });
  app.delete(route, async (req, res) => {
    if (!(await withinRateLimit(limiter, req, res))) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      if (!rejectUnlessSessionCredential(res, { message: 'Choose the local connection from your signed-in owner browser.', permission: SHARED_MCP_PERMISSION })) return;
      if (!deps.externalMcpOAuth.useLocalConnection) throw new ExternalMcpValidationError('Shared connections are unavailable in this profile.', 'credentialId');
      await deps.externalMcpOAuth.useLocalConnection({ serverId: String(req.params.serverId), actorId: getAuthedPrincipal(res).id });
      res.json({ selected: 'local' });
    } catch (error) { sendExternalMcpOAuthError(res, error); }
  });
  app.post(route, async (req, res) => {
    if (!(await withinRateLimit(limiter, req, res))) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      if (!rejectUnlessSessionCredential(res, { message: 'Choose a saved connection from your signed-in owner browser.', permission: SHARED_MCP_PERMISSION })) return;
      const body = req.body as Record<string, unknown> | undefined;
      if (!body || Object.keys(body).some(key => key !== 'credentialId')) throw new ExternalMcpValidationError('Choose an existing saved connection.', 'credentialId');
      if (typeof body.credentialId !== 'string' || body.credentialId.length > 512 || !body.credentialId) {
        throw new ExternalMcpValidationError('Choose an existing saved connection.', 'credentialId');
      }
      if (!deps.externalMcpOAuth.useSharedConnection) throw new ExternalMcpValidationError('Shared connections are available only in this Mac owner profile.', 'credentialId');
      await deps.externalMcpOAuth.useSharedConnection({ serverId: String(req.params.serverId), credentialId: body.credentialId, actorId: getAuthedPrincipal(res).id });
      res.json({ connected: true });
    } catch (error) { sendExternalMcpOAuthError(res, error); }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";

import { probeExternalMcpServer, type ExternalMcpProbeServiceDeps } from "#src/server/runtime/services/external-mcp-probe";
export type { ExternalMcpProbeSessionFactory } from "#src/server/runtime/services/external-mcp-probe";
import { OUTBOUND_CALL_PER_IP, createRateLimiter, resolveClientIp, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import type { ExternalMcpRouteDeps } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

/**
 * @file `POST .../mcp-servers/:serverId/probe` (C-007) — connects to ONE configured server, once,
 * lists its tools, describes the surface, and closes. Registers nothing into any `ToolRegistry`, so
 * R5 (`mcp-federation/trust.ts`'s "frozen at connect") is untouched by this route — see the
 * write-tools implementation outline §3.1/C-4 for the full argument that a probe run in the admin
 * web server cannot un-freeze anything the daemon holds.
 *
 * ## D-7: hosted connections only
 *
 * A `stdio` row is refused before anything is attempted, rather than spawned. The daemon already
 * pays the cost of a local-command child process at boot, with its own timeout and its own
 * catch-and-close (`mcp-federation/bootstrap.ts`); this on-demand admin action is a strictly worse
 * place for that risk to live a second time — a leaked child here is a leaked child in the process
 * serving the whole admin UI, not a subprocess the daemon already knows how to reap. The motivating
 * connection (Higgsfield) is hosted, so this is not a regression for the case that exists today; a
 * `stdio` operator keeps the plain text-field path exactly as it works now.
 *
 * ## Rate limiting sits IN FRONT of the guard
 *
 * Same ordering `oauth.ts` uses and for the same reason: a hit that will be rejected by the
 * permission check has still made this process reach for an outbound socket on the operator's own
 * credentials if the limiter did not run first.
 *
 * ## INV-006 — no secret in the response
 *
 * The response body is built ONLY from `describeRemoteToolSurface`'s output — a pure function over
 * the remote's `tools/list` reply and the two operator name lists (`mcp-federation/trust.ts`). It
 * never touches the resolved launch spec's headers/env, so there is no code path by which a bearer
 * token, a client secret, or an env value could reach this route's response. Any other error this
 * route can raise is either fixed, Tovu-authored copy, or a stored failure REASON string that
 * `external-mcp-store.ts` itself already guarantees is secret-free (it exists specifically to be
 * shown to the operator). See this file's test for the direct property assertion.
 */

export type ExternalMcpProbeRouteDeps = ExternalMcpRouteDeps & ExternalMcpProbeServiceDeps;

/** Builds this route's own probe rate limiter. Reuses {@link OUTBOUND_CALL_PER_IP} rather than
 *  a new profile: a probe is the same self-DoS shape that profile already names — a real outbound
 *  call using the workspace's own credentials — with its own instance so a burst on one connector
 *  family never eats another's budget. */
export function createExternalMcpProbeLimiter(deps: Pick<ExternalMcpRouteDeps, "clock">): RateLimiter {
  return createRateLimiter({ profile: OUTBOUND_CALL_PER_IP, clock: deps.clock });
}

/** Answers the shared limiter check, writing the 429 itself. Mirrors `oauth.ts`'s
 *  `withinRateLimit` — not imported from there, so this route stays independent of a sibling
 *  family's file (see the implementation outline's own "different failure modes, different copy"
 *  argument for why `probe.ts` and `admissions.ts` are separate files in the first place). */
async function withinProbeRateLimit(limiter: RateLimiter, req: Request, res: Response): Promise<boolean> {
  const result = await limiter.check({ key: resolveClientIp(req) });
  if (result.allowed) return true;
  res.setHeader("Retry-After", String(result.retryAfterSeconds));
  res.status(429).json({
    error: "too many probe attempts",
    code: "RATE_LIMIT_EXCEEDED",
    details: { retryAfterSeconds: result.retryAfterSeconds },
  });
  return false;
}

/**
 * `POST .../mcp-servers/:serverId/probe`.
 *
 * @complexity O(t) in the remote's advertised tool count, plus one round trip.
 */
export function registerAdminExternalMcpProbeRoute(app: Express, deps: ExternalMcpProbeRouteDeps, limiter: RateLimiter): void {
  app.post("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/probe", async (req, res) => {
    if (!(await withinProbeRateLimit(limiter, req, res))) return;
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const serverId = String(req.params.serverId ?? "");

      const outcome = await probeExternalMcpServer(deps, serverId);
      res.status(outcome.ok ? 200 : outcome.status).json(outcome.body);
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/external-mcp/probe", code: "INTERNAL_ERROR" });
    }
  });
}

import { ToolAccessLoweringError } from '#src/assistant/external-mcp-roster-change';
import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { describeExternalMcpOwnership } from "#src/features/external-mcp/built-in-connections";
import { ExternalMcpSecretStoreUnconfiguredError, ExternalMcpValidationError, saveExternalMcpServer } from "../../../../../features/external-mcp/external-mcp-store.js";
import { notifyExternalMcpRosterChanged } from "../../../../../assistant/index.js";
import { type SaveExternalMcpOAuthInput } from "../../../../../features/external-mcp/contracts.js";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ExternalMcpRouteRegistrar } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

/** `undefined`/non-string collapses to `""` — the ordinary (non tri-state) field default this
 *  route uses for `command`/`args`/`allowedToolNames`. @complexity O(1). */
function asStringField(value: unknown): string {
  return typeof value === "string" ? value : "";
}

/** Carries a string field ONLY when the caller actually sent one, so `undefined` (keep what is
 *  stored) stays distinguishable from `""` (clear it). The `env` rule, applied to every field that
 *  shares its three-way meaning. @complexity O(1). */
function optionalStringField(value: unknown, key: string): Record<string, string> {
  return typeof value === "string" ? { [key]: value } : {};
}

/**
 * The OAuth block of a PUT body.
 *
 * Every member is tri-state for the same reason `env` is: an operator renaming a connection, or
 * toggling it off, sends no OAuth fields at all, and collapsing that into `""` would clear the
 * client id and secret of a working connection. So absent keys are dropped rather than defaulted,
 * and `saveExternalMcpServer` applies the keep/replace/clear rule.
 *
 * `clientSecret` is read here and never written back — no read model in this subsystem returns it.
 *
 * @complexity O(1).
 */
function parseExternalMcpOAuthBody(rawOAuth: unknown): { oauth?: SaveExternalMcpOAuthInput } {
  if (rawOAuth === null || typeof rawOAuth !== "object" || Array.isArray(rawOAuth)) return {};
  const oauth = rawOAuth as Record<string, unknown>;

  const parsed: SaveExternalMcpOAuthInput = {
    ...optionalStringField(oauth.providerId, "providerId"),
    ...optionalStringField(oauth.grant, "grant"),
    ...optionalStringField(oauth.clientId, "clientId"),
    ...optionalStringField(oauth.clientSecret, "clientSecret"),
    ...optionalStringField(oauth.scopes, "scopes"),
    ...optionalStringField(oauth.tokenEnvName, "tokenEnvName"),
    ...optionalStringField(oauth.authorizationEndpoint, "authorizationEndpoint"),
    ...optionalStringField(oauth.tokenEndpoint, "tokenEndpoint"),
    ...optionalStringField(oauth.deviceAuthorizationEndpoint, "deviceAuthorizationEndpoint"),
  };

  return Object.keys(parsed).length === 0 ? {} : { oauth: parsed };
}

/**
 * This route's writable PUT fields, read off an untyped body in one place. `label`, `url`,
 * `authMode`, `env` and the whole `oauth` block stay spreadable-optional (an absent key vs. an
 * explicit value are different things — see this route's own doc comment on `env`'s three-way
 * meaning); everything else gets its default here.
 *
 * @complexity O(1).
 */
function parseExternalMcpPutBody(rawBody: unknown) {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    ...(typeof body.label === "string" ? { label: body.label } : {}),
    // Defaulted rather than required so a caller that omits it gets the transport that every row
    // written before a second one existed effectively had, instead of a validation error naming a
    // choice it was never offered.
    transport: typeof body.transport === "string" ? body.transport : "stdio",
    enabled: body.enabled !== false,
    command: asStringField(body.command),
    // Only meaningful for a remote transport, and tri-state so a stdio-shaped PUT does not clear a
    // stored endpoint.
    ...optionalStringField(body.url, "url"),
    // Absent keeps an existing row's mode rather than silently demoting an OAuth connection to
    // `static_env` — which is what a toggle or rename would otherwise do.
    ...optionalStringField(body.authMode, "authMode"),
    args: asStringField(body.args),
    allowedToolNames: asStringField(body.allowedToolNames),
    // Same `asStringField` treatment as `allowedToolNames` above — resent in full on every save, not
    // tri-state. NOTE (task #30, R-3): a non-string body value (e.g. an array) collapses to `""`
    // here, which for THIS field silently clears every write grant. Known, pre-existing behaviour of
    // `asStringField` on the sibling field too — undesirable, but it fails CLOSED, so it is not fixed
    // in this change. See `admin-external-mcp-routes.test.ts` for the pinned regression.
    writeAllowedToolNames: asStringField(body.writeAllowedToolNames),
    // Deliberately NOT `asStringField` — see this route's doc comment. `undefined` must survive.
    ...optionalStringField(body.env, "env"),
    // Same three-way meaning as `env`, and write-only: no read model returns the token.
    ...optionalStringField(body.accessToken, "accessToken"),
    ...optionalStringField(body.accessTokenEnvName, "accessTokenEnvName"),
    ...parseExternalMcpOAuthBody(body.oauth),
  };
}

/**
 * PUT one external MCP server — creates it, or replaces the stored row for an existing id.
 *
 * Idempotent-by-id rather than POST-creates/PATCH-updates, because the admin tab's add form and its
 * expand-to-edit card are the same shape submitting the same fields; two routes would be two
 * validators of one contract.
 *
 * `env` is the one field with three distinct meanings, and the route preserves all three rather
 * than collapsing them: ABSENT keeps whatever credentials are stored (what an enable/disable toggle
 * sends, since the UI never received the values to send back), a STRING replaces them, and an EMPTY
 * string clears them. Collapsing absent into empty is how a toggle would silently wipe a token.
 *
 * A saved row does NOT necessarily take effect until the agent daemon restarts — the admitted tool
 * set for any ONE connection is still frozen at connect (`mcp-federation/trust.ts` R5) and this route
 * does not, and cannot, change that: editing an already-admitted connection's allowlist, credentials,
 * or transport here still needs a real restart, because that connection's one-time admission already
 * happened. `restartRequired: true` in the response reflects exactly that — it is conservative by
 * design, not stale: it stays true even for a brand-new row, because whether the SECONDARY hot-reload
 * trigger below actually admitted it depends on facts this route does not read back (daemon
 * reachability, whether the connection is `authMode: "oauth"` and therefore not yet authorized).
 *
 * That said, `restartRequired: true` no longer means "does nothing until restart": turning a
 * connection off stops affected answers immediately; removing a tool or its write permission takes effect on the next tool call.
 * Adding tools, or changing the server's address, command or sign-in method, needs a restart; until
 * then that connection's tools refuse. This is `external-mcp-revocation.ts`'s per-call gate, not this
 * route — the response value itself is unchanged (see that file's header for why).
 *
 * Federation hot-reload trigger (2026-09-11), fired unconditionally after every successful save,
 * best effort for enabled connections (OFF awaits Stop/cleanup): the daemon-side coordinator
 * (`mcp-federation/reload.ts`) is what actually decides whether anything changed — a save that only
 * edited fields on an ALREADY-admitted connection is a genuine no-op there (R5, restated above), and
 * a fresh `authMode: "oauth"` row is a no-op too until its own callback later completes and fires
 * the PRIMARY trigger (`public-http/routes/external-mcp/oauth-callback.ts`). The one case this
 * actually helps is a brand-new, immediately-usable connection (`static_env`/no-OAuth transport) —
 * exactly the "operator save/approve" trigger the feature's own spec calls out as the SECONDARY path,
 * next to a completed OAuth sign-in as the primary one.
 */
export const registerAdminExternalMcpPutRoute: ExternalMcpRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;

      const server = await saveExternalMcpServer(
        {
          repo: deps.externalMcpServerRepo,
          sealer: deps.siteAssistantSecretSealer,
          keyring: deps.siteAssistantSecretKeyring,
          clock: deps.clock,
        },
        {
          workspaceId: deps.workspaceId,
          serverId: String(req.params.serverId ?? ""),
          // The guard above already authorized this same principal — a second, cheap read off
          // `res.locals` (`getAuthedPrincipal` does no I/O), used ONLY to attribute a change to
          // `writeAllowedToolNames` if this save makes one.
          principalId: getAuthedPrincipal(res).id,
          ...parseExternalMcpPutBody(req.body),
        },
      );

      // Ordinary discovery is best effort. OFF awaits Stop/cleanup before reporting success.
      if (server.enabled) void notifyExternalMcpRosterChanged();
      else await notifyExternalMcpRosterChanged({ lowered: { serverIds: [server.serverId] } });
      res.json({ server: describeExternalMcpOwnership({ server, ids: deps.builtInExternalMcpServerIds }), restartRequired: true });
    } catch (err) {
      if (err instanceof ToolAccessLoweringError) {
        res.status(503).json({ error: err.message, code: err.code });
        return;
      }
      if (err instanceof ExternalMcpValidationError) {
        res.status(400).json({ error: err.message, code: "INVALID_MCP_SERVER", details: { field: err.field } });
        return;
      }
      if (err instanceof ExternalMcpSecretStoreUnconfiguredError) {
        res.status(503).json({ error: err.message, code: "SECRET_STORE_UNCONFIGURED" });
        return;
      }
      sendAdminFailure({ res, error: err }, { operation: "routes/external-mcp/put", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { ExternalMcpRouteRegistrar } from "./deps.js";
import { guardExternalMcpRequest } from "./guard.js";

/**
 * @file The Integrations "Always allow" list (owner call 2026-09-28): which remote tools the site
 * owner told the approval card to stop asking about, per external MCP server, and a revoke for each.
 *
 * Reads and deletes `external_mcp_tool_approvals` rows (`assistant/external-mcp-tool-approvals.ts`).
 * Revoking is reversible — the tool's next call just shows the card again — so there is no confirm
 * step anywhere on this path. Granting stays on the card: a grant is pinned to a fingerprint of the
 * tool exactly as the running daemon admitted it, which only the card's own call path has.
 *
 * The fingerprint is never sent: it is a hash the page has no use for.
 *
 * A composition with no store (`externalMcpToolApprovalRepo` unset) can have saved nothing, so its
 * list is empty and every revoke is a 404 — the truthful answer, not an error.
 */
export const registerAdminExternalMcpToolApprovalsRoutes: ExternalMcpRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/mcp-servers/tool-approvals", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const rows = (await deps.externalMcpToolApprovalRepo?.listByWorkspaceId(deps.workspaceId)) ?? [];
      const approvals = rows
        .map(({ serverId, toolName, grantedByPrincipalId, grantedAt }) => ({ serverId, toolName, grantedByPrincipalId, grantedAt }))
        .sort((a, b) => a.serverId.localeCompare(b.serverId) || a.toolName.localeCompare(b.toolName));
      res.json({ approvals });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/external-mcp/tool-approvals", code: "INTERNAL_ERROR" });
    }
  });

  app.delete("/api/admin/v1/workspaces/:workspaceId/mcp-servers/:serverId/tool-approvals/:toolName", async (req, res) => {
    try {
      if (!(await guardExternalMcpRequest(deps, req.params.workspaceId, res))) return;
      const removed =
        (await deps.externalMcpToolApprovalRepo?.delete({
          workspaceId: deps.workspaceId,
          serverId: String(req.params.serverId ?? ""),
          toolName: String(req.params.toolName ?? ""),
        })) ?? false;
      if (!removed) {
        res.status(404).json({ error: "no Always allow is saved for that tool", code: "NOT_FOUND" });
        return;
      }
      res.json({ removed: true });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/external-mcp/tool-approvals", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { updateFormDefinition } from "#src/features/forms/index";
import type { FieldDescriptor, NotifyConfig } from "@jini-ai/cms/forms";
import type { FormAuthoring } from "@jini-ai/cms/forms/html";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { mapFormsWriteError, toAdminFormDefinitionResponse } from "#src/server/inbound/admin-http/http/forms";
import type { FormsRouteRegistrar } from "./deps.js";

function authoringPatch({ body }: { body: Record<string, unknown> }, _options = {}) {
  return {
    ...(typeof body.name === "string" ? { name: body.name } : {}),
    ...(Array.isArray(body.fields) ? { fields: body.fields as FieldDescriptor[] } : {}),
    ...(body.notify !== undefined ? { notify: body.notify as NotifyConfig } : {}),
    ...(body.mode !== undefined ? { mode: body.mode as FormAuthoring["mode"] } : {}),
    ...(body.html !== undefined ? { html: body.html as string } : {}),
    ...(body.provider !== undefined ? { provider: body.provider as FormAuthoring["provider"] } : {}),
  };
}

/** Separate authoring endpoint avoids changing the shared-tree CRUD route. Both permissions and
 * the audit boundary live in the write service, covering route and future tool callers alike. */
export const registerAdminFormsAuthoringRoute: FormsRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/forms/:formId/authoring", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const body = (req.body ?? {}) as Record<string, unknown>;
      const principal = getAuthedPrincipal(res);
      const formId = String(req.params.formId ?? "");
      // Same gate as `update.ts` (f07a92dcb): an empty/ignored body never reaches the write
      // service's gateway, and the write service's own pre-read must not disclose a form's
      // existence to a caller the matching GET denies.
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.forms.manage",
        workspaceId: deps.workspaceId,
        entityType: "form_definition",
        entityId: formId,
      });
      if (!authorized) return;
      const { definition } = await updateFormDefinition({
        deps: { ...deps, repo: deps.formDefinitionRepo },
        input: {
          workspaceId: deps.workspaceId,
          formId,
          actor: { id: principal.id, kind: "user" },
          idempotencyKey: req.get("Idempotency-Key") || undefined,
          patch: authoringPatch({ body }, {}),
        },
      });
      res.json(toAdminFormDefinitionResponse(definition));
    } catch (error) {
      if (mapFormsWriteError(error, res)) return;
      sendAdminFailure({ res, error }, { operation: "routes/forms/authoring", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { FormAuthoring } from "@jini-ai/cms/forms/html";
