import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { FormsRouteDeps, FormsRouteRegistrar } from "./deps.js";

const PERMISSION = "admin.forms.manage";

/** The optional `targetId` from the JSON body, or the reason it was refused. @complexity O(1). */
function parseTargetId(body: unknown): { ok: true; targetId?: string } | { ok: false } {
  const raw = body !== null && typeof body === "object" ? (body as Record<string, unknown>).targetId : undefined;
  if (raw === undefined) return { ok: true };
  return typeof raw === "string" && raw.length > 0 && raw.length <= 64 ? { ok: true, targetId: raw } : { ok: false };
}

/** Keep pull failures correlated with the server log, inside the route's outer fallback. */
async function respondWithPullReport(
  { pull, workspaceId, targetId, res }: {
    pull: NonNullable<FormsRouteDeps["formSubmissionsPull"]>;
    workspaceId: string;
    targetId?: string;
    res: Response;
  },
  _options = {},
): Promise<void> {
  try {
    res.json(await pull.pull({ workspaceId }, targetId ? { targetId } : {}));
  } catch (error) {
    // One host's failure is already a per-destination report; this is a failure before any host
    // was read (the vault, the plugin registry). Log the cause under a reference the reply repeats.
    sendAdminFailure({ res, error }, { operation: "forms-pull",
      message: "Form submission retrieval stopped before any published host was read.",
      failure: { action: "Try pulling submissions again. If it still fails, copy details and report this problem.", step: "forms.submissions.pull" },
    });
  }
}

/**
 * POST — pull the submissions published static sites stored at their hosts into this site
 * (`FormsDeps.formSubmissionsPull`, the same composed port as the `forms_pull_submissions` tool).
 * Body: optional `{ targetId }` to pull from one hosting target only.
 */
export const registerAdminFormsPullSubmissionsRoute: FormsRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/forms/submissions/pull", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({ principalId: principal.id, permission: PERMISSION, workspaceId: deps.workspaceId, entityType: "form_submission" });
      if (!authResult.allowed) {
        res.status(403).json({ error: `principal '${principal.id}' is not authorized for '${PERMISSION}' (${authResult.reason})`, code: "FORBIDDEN",
          details: { permission: PERMISSION, reason: authResult.reason } });
        return;
      }
      const parsed = parseTargetId(req.body);
      if (!parsed.ok) {
        res.status(400).json({ error: "targetId must be a hosting target id of 1-64 characters, or omitted to pull from every published site", code: "FORMS_FIELD_VALIDATION_ERROR",
          details: { fieldErrors: [{ field: "targetId", reason: "must be 1-64 characters" }] } });
        return;
      }
      if (!deps.formSubmissionsPull) {
        res.status(503).json({ error: "pulling form submissions is not available on this site's server; restart the site, then try again", code: "FORMS_PULL_UNAVAILABLE" });
        return;
      }
      await respondWithPullReport({ pull: deps.formSubmissionsPull, workspaceId: deps.workspaceId, targetId: parsed.targetId, res });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/forms/pull-submissions", code: "INTERNAL_ERROR" });
    }
  });
};

import type { FormAuthoring } from "@jini-ai/cms/forms";
import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { mapFormsWriteError, toAdminFormDefinitionResponse } from "#src/server/inbound/admin-http/http/forms";
import {
  FormDefinitionNotFoundError,
  type FieldDescriptor,
  type HtmlFormDefinitionRecord as FormDefinitionRecord,
  type FormDefinitionRepoPort,
  type FormDefinitionStatus,
  type NotifyConfig,
} from "@jini-ai/cms/forms";
import {
  setFormDefinitionStatus,
  updateFormDefinition,
  type FormWriteServiceDeps,
} from "#src/features/forms/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import type { FormsRouteRegistrar } from "./deps.js";

const VALID_STATUSES: readonly FormDefinitionStatus[] = ["active", "disabled"];

/**
 * Applies the PATCH body's field patch and/or status change (each optional, either or both may
 * apply), then falls back to a plain read when neither ran — a request with no recognized fields is
 * a no-op read, not an error, unless the form itself doesn't exist.
 *
 * @throws {FormDefinitionNotFoundError} if neither write ran and the form id doesn't exist either.
 * @complexity O(1) — at most two writes and one read.
 */
async function resolveFormUpdateResult(
  writeDeps: FormWriteServiceDeps,
  repo: FormDefinitionRepoPort,
  params: { workspaceId: string; actor: { id: string; kind: "user" }; formId: string; body: Record<string, unknown> }
): Promise<FormDefinitionRecord> {
  const { workspaceId, actor, formId, body } = params;

  const patch: { name?: string; fields?: FieldDescriptor[]; notify?: NotifyConfig } & FormAuthoring = {};
  if (typeof body.name === "string") patch.name = body.name;
  if (Array.isArray(body.fields)) patch.fields = body.fields as FieldDescriptor[];
  if (body.notify !== undefined) patch.notify = body.notify as NotifyConfig;
  if (body.provider !== undefined) patch.provider = body.provider as FormAuthoring["provider"];

  let definition: FormDefinitionRecord | undefined;
  if (Object.keys(patch).length > 0) {
    ({ definition } = await updateFormDefinition({ deps: writeDeps, input: { workspaceId, actor, formId, patch } }));
  }

  if (typeof body.status === "string" && VALID_STATUSES.includes(body.status as FormDefinitionStatus)) {
    ({ definition } = await setFormDefinitionStatus({
      deps: writeDeps,
      input: { workspaceId, actor, formId, status: body.status as FormDefinitionStatus },
    }));
  }

  if (definition) {
    return definition;
  }

  const existing = await repo.findById({ workspaceId, id: formId });
  if (!existing) {
    throw new FormDefinitionNotFoundError({ message: `form definition '${formId}' was not found` });
  }
  return existing;
}

/**
 * PUT (partial) update a form definition, including the `status` toggle (`FORMS_UPDATE_DEFINITION`,
 * REQ-04). `slug` is deliberately ignored if present in the body (behavior.spec.md §1.1 — handled
 * inside `write-service.ts`'s `updateFormDefinition`, which never reads `patch.slug`).
 */
export const registerAdminFormsUpdateRoute: FormsRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/forms/:formId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const formId = String(req.params.formId ?? "");
    const body = (req.body ?? {}) as Record<string, unknown>;

    try {
      const principal = getAuthedPrincipal(res);
      // Empty/ignored bodies fall through to a read without invoking the write service's
      // gateway. Gate that path too, before it can return a definition or disclose its absence.
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.forms.manage",
        workspaceId: deps.workspaceId,
        entityType: "form_definition",
        entityId: formId,
      });
      if (!authorized) return;
      const actor = { id: principal.id, kind: "user" as const };
      const writeDeps = {
        executeCommand: deps.executeCommand,
        repo: deps.formDefinitionRepo,
        formCollectionProviders: deps.formCollectionProviders,
        clock: deps.clock,
        idGen: deps.idGen,
        changeSets: deps.changeSets,
        outbox: deps.outbox,
        authorize: deps.authorize,
      };

      const definition = await resolveFormUpdateResult(writeDeps, deps.formDefinitionRepo, {
        workspaceId: deps.workspaceId,
        actor,
        formId,
        body,
      });

      res.json(toAdminFormDefinitionResponse(definition));
    } catch (err) {
      if (mapFormsWriteError(err, res)) return;
      sendAdminFailure({ res, error: err }, { operation: "routes/forms/update", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";

import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { FS_FILES_READ_PERMISSION } from "#src/features/fs-files/agent-tools";
import { FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION } from "#src/features/fs-files/custom-root-permission";
import {
  CustomFsRootError,
  getCustomFsRootStatus,
  setCustomFsRoot,
  type CustomFsRootStoreOptional,
} from "#src/features/fs-files/custom-root-store";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin chat composer's folder control: `GET`/`PUT`/`DELETE` on
 * `/api/admin/v1/workspaces/:workspaceId/fs-files/custom-root` — the operator-facing surface for the
 * `fs-files` domain's `custom` root (`features/fs-files/layout.ts`, `custom-root-store.ts`).
 *
 * Shape copied from `routes/system/site-key.ts`: a `Pick<RouteDeps, "workspaceId" | "authorize" | "siteBinding">`
 * deps slice (no settings ledger, no repo — the value is persisted by `custom-root-store.ts`, keyed
 * by `workspaceId`), the same `rejectUnlessAuthorized` two-step, one file for every verb.
 *
 * `storeOptional` (2026-09-10, restart-persistence follow-up) is the one addition beyond that copied
 * shape: a test-only seam so this route's own tests can point `custom-root-store.ts` at a temp site
 * directory instead of the real one — see that field's own doc. Every real caller leaves it unset and
 * gets the real site directory, exactly as before this field existed.
 *
 * Two permissions, split by verb (owner ruling, 2026-09-15):
 *
 * - `GET` — `FS_FILES_READ_PERMISSION` (`content.read`), the SAME permission that gates
 *   `fs_list_files`/`fs_read_file` themselves. Reading which folder is currently configured tells a
 *   caller nothing it could not already read through those tools.
 * - `PUT`/`DELETE` — {@link FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION}, which only `owner` (via its `*`
 *   wildcard) and the built-in `admin` role hold. Choosing the folder is not the same capability as
 *   reading through it: `layout.ts` accepts `/` and a home directory as values, so one `PUT`
 *   re-points the assistant's whole filesystem surface. See that permission's own file for why it is
 *   a new string with a built-in-role grant rather than `workspace.manage`, which NO policy in the
 *   workspace this repo ships actually holds.
 *
 * `PUT`/`DELETE` never read anything under the folder they accept — {@link setCustomFsRoot}'s own doc
 * is explicit that only the path and a single `stat` are involved. The route inherits that property
 * rather than re-deriving it.
 */
export type AdminFsFilesCustomRootDeps = Pick<RouteDeps, "workspaceId" | "authorize" | "siteBinding"> & {
  /** Test seam — defaults to the booted `siteBinding.dir`. Set
   *  only by this route's own tests, to a temp directory, so they never read or write the real site's
   *  `.fs-custom-root.json`. */
  readonly storeOptional?: CustomFsRootStoreOptional;
};

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/fs-files/custom-root";

/** Shared workspace-path-param + permission check every verb below performs first — same shape
 *  `site-key.ts`'s own `rejectUnlessAuthorized`. Takes the permission as a parameter because the
 *  verbs no longer share one (see this file's header). Returns `true` (response already written) iff
 *  the caller should stop. */
async function rejectUnlessAuthorized(
  req: Request,
  res: Response,
  deps: AdminFsFilesCustomRootDeps,
  permission: string,
): Promise<boolean> {
  if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
    res.status(404).json({ error: "workspace was not found" });
    return true;
  }
  const principal = getAuthedPrincipal(res);
  return !(await authorizeOrRespond(res, deps.authorize, {
    principalId: principal.id,
    permission,
    workspaceId: deps.workspaceId,
  }));
}

export function registerAdminFsFilesCustomRootRoutes(app: Express, deps: AdminFsFilesCustomRootDeps): void {
  app.get(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps, FS_FILES_READ_PERMISSION)) return;
    const status = getCustomFsRootStatus(deps.workspaceId, (deps.storeOptional ?? { siteDir: deps.siteBinding.dir }));
    // `vanished`/`vanishedPath` are only present (never `false`/absent-by-omission) when a
    // previously-set folder no longer stats as a directory — additive beyond the original
    // `{ path }` shape, so an existing caller reading only `path` sees no change.
    res.status(200).json(status.vanished ? { path: null, vanished: true, vanishedPath: status.vanishedPath } : { path: status.path ?? null });
  });

  app.put(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps, FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION)) return;

    const path = req.body?.path;
    if (typeof path !== "string" || path.length === 0) {
      res.status(400).json({ error: "'path' is required and must be a non-empty string", code: "VALIDATION_ERROR" });
      return;
    }

    try {
      setCustomFsRoot(deps.workspaceId, path, (deps.storeOptional ?? { siteDir: deps.siteBinding.dir }));
      res.status(200).json({ path: getCustomFsRootStatus(deps.workspaceId, (deps.storeOptional ?? { siteDir: deps.siteBinding.dir })).path });
    } catch (err) {
      if (err instanceof CustomFsRootError) {
        res.status(400).json({ error: err.message, code: "INVALID_PATH" });
        return;
      }
      sendAdminFailure({ res, error: err }, { operation: "routes/fs-files/custom-root", code: "INTERNAL_ERROR" });
    }
  });

  app.delete(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps, FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION)) return;
    setCustomFsRoot(deps.workspaceId, null, (deps.storeOptional ?? { siteDir: deps.siteBinding.dir }));
    res.status(200).json({ path: null });
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";

import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import { isLocalAdminRequest } from "#src/server/inbound/admin-http/local-admin-request";
import { FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION } from "#src/features/fs-files/custom-root-permission";
import type { NativeFolderPicker } from "#src/features/fs-files/native-folder-picker";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin chat composer's folder button: `GET`/`POST` on
 * `/api/admin/v1/workspaces/:workspaceId/fs-files/folder-picker`. `GET` says whether the button may
 * show; `POST` opens the OS folder dialog ON THE SERVER MACHINE and answers `{ path }` (`null` on
 * Cancel). A browser can never read a dropped folder's path; when the server is the owner's own
 * computer, it can ask the OS instead.
 *
 * The dialog appears on the server's screen, so this exists only when that screen is the caller's:
 * - `localHost` (`isLocalTovuHost`, the same host decision `local-credential-copy.ts` uses): a
 *   local launch, never a deployed/hosted runtime. Otherwise 404, as if the route did not exist.
 * - the picker has a chooser on this OS. Otherwise 404 too.
 * - `isLocalAdminRequest`: loopback sockets, no forwarding headers, a loopback Host, same Origin.
 *   Otherwise 403 `local-host-only`.
 * - a session credential (an API key never pops a dialog) holding
 *   `FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION` — the permission that already gates pointing the chat's
 *   file tools at a folder, which the composer does with the picked path (owner/admin only).
 *
 * One dialog at a time per process: a second `POST` while one is open answers 409 `busy`.
 */
export type AdminFsFilesFolderPickerDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & {
  readonly localHost: boolean;
  readonly folderPicker: NativeFolderPicker;
};

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/fs-files/folder-picker";

/** Every admission check, cheapest and least revealing first. Returns `false` once a response was written.
 *  @complexity O(h), h = request header names. */
async function admitted({ req, res, deps }: { req: Request; res: Response; deps: AdminFsFilesFolderPickerDeps }): Promise<boolean> {
  res.setHeader("Cache-Control", "no-store");
  if (!deps.localHost || !deps.folderPicker.available || String(req.params.workspaceId ?? "") !== deps.workspaceId) {
    res.status(404).json({ error: "not found" }); return false;
  }
  if (!isLocalAdminRequest({ req })) { res.status(403).json({ reasonCode: "local-host-only" }); return false; }
  const permission = FS_FILES_CUSTOM_ROOT_MANAGE_PERMISSION;
  if (!rejectUnlessSessionCredential(res, { message: "Sign in to the admin to choose a folder.", permission })) return false;
  return authorizeOrRespond(res, deps.authorize, { principalId: getAuthedPrincipal(res).id, permission, workspaceId: deps.workspaceId });
}

export function registerAdminFsFilesFolderPickerRoutes({ app, deps }: { app: Express; deps: AdminFsFilesFolderPickerDeps }, _optional = {}): void {
  let picking = false;
  app.get(BASE_PATH, async (req, res) => {
    if (await admitted({ req, res, deps })) res.json({ available: true });
  });
  app.post(BASE_PATH, async (req, res) => {
    if (!await admitted({ req, res, deps })) return;
    if (picking) { res.status(409).json({ reasonCode: "busy" }); return; }
    picking = true;
    try {
      res.json({ path: await deps.folderPicker.pick() });
    } catch (error) {
      // Never echo the chooser's stderr: it can carry local paths and account names.
      sendAdminFailure({ res, error }, { operation: "routes/fs-files/folder-picker", code: "INTERNAL_ERROR", details: { reasonCode: "picker-failed" } });
    } finally {
      picking = false;
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Request } from "express";

import { createSubscription, WebhookSubscriptionValidationError } from "#src/features/webhooks/index";
import { toAdminSubscriptionResponse } from "#src/server/inbound/admin-http/http/integrations";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { toWebhookSubscriptionDeps, type IntegrationsRouteRegistrar } from "./deps.js";

/** Pulls the create-subscription fields out of the request body, applying the same
 *  string-coercion/defaulting `createSubscription`'s own validation expects (never throws —
 *  malformed shapes just become empty/invalid values that `createSubscription` rejects). */
function parseCreateSubscriptionInput(req: Request): { label: string; targetUrl: string; topics: string[] } {
  const rawTopics = req.body?.topics;
  return {
    label: String(req.body?.label ?? ""),
    targetUrl: String(req.body?.targetUrl ?? ""),
    topics: Array.isArray(rawTopics) ? rawTopics.map(String) : [],
  };
}

/**
 * POST create a webhook subscription.
 *
 * Gated by `admin.integrations.manage` (registered in `identity/permissions.ts`), checked directly via
 * `authorize()` — mirrors `members/disable.ts`'s pattern since subscription mutations are a direct
 * feature call, not routed through the SPEC-001 command gateway.
 */
export const registerAdminIntegrationsCreateRoute: IntegrationsRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/integrations/subscriptions", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.integrations.manage",
        workspaceId: deps.workspaceId,
        entityType: "webhook_subscription",
      });
      if (!authorized) return;

      const { label, targetUrl, topics } = parseCreateSubscriptionInput(req);
      const { subscription } = await createSubscription({
        // ADR-PIPE-015 GAP-06: the real core/origin egress oracle (see `toWebhookSubscriptionDeps`).
        deps: toWebhookSubscriptionDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          // Dev-mode single-actor placeholder, matching the session/command-gateway convention
          // (`dev-auth.ts`'s fixed `"user-local"` session subject) — no permissions feature yet.
          ownerPrincipalId: "user-local",
          createdByPrincipalId: "user-local",
          label,
          targetUrl,
          topics,
        },
      });

      res.status(201).json({ subscription: toAdminSubscriptionResponse({ subscription, lastDelivery: null }) });
    } catch (err) {
      if (err instanceof WebhookSubscriptionValidationError) {
        res.status(400).json({ error: err.message });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/integrations/create", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { deleteSubscription, WebhookSubscriptionNotFoundError } from "#src/features/webhooks/index";
import { toAdminSubscriptionResponse } from "#src/server/inbound/admin-http/http/integrations";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { toWebhookSubscriptionDeps, type IntegrationsRouteRegistrar } from "./deps.js";

/**
 * DELETE a webhook subscription. Soft-deletes (never row-deletes) — `deleteSubscription` sets
 * `status: "disabled"` + stamps `disabledAt` for audit durability (ADR-036 §2); the response
 * still echoes the (now-disabled) subscription so the admin UI can show its terminal state.
 *
 * Gated by `admin.integrations.manage`, checked directly via `authorize()` (same pattern as `create.ts`).
 */
export const registerAdminIntegrationsDeleteRoute: IntegrationsRouteRegistrar = (app, deps) => {
  app.delete(
    "/api/admin/v1/workspaces/:workspaceId/integrations/subscriptions/:subscriptionId",
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const subscriptionId = String(req.params.subscriptionId ?? "");

      try {
        const principal = getAuthedPrincipal(res);
        const authResult = await deps.authorize({
          principalId: principal.id,
          permission: "admin.integrations.manage",
          workspaceId: deps.workspaceId,
          entityType: "webhook_subscription",
          entityId: subscriptionId,
        });
        if (!authResult.allowed) {
          res.status(403).json({
            error: `principal '${principal.id}' is not authorized for 'admin.integrations.manage' (${authResult.reason})`,
            code: "FORBIDDEN",
            details: { permission: "admin.integrations.manage", reason: authResult.reason },
          });
          return;
        }

        const { subscription } = await deleteSubscription({
          // The shared egress policy is not exercised here: delete never re-validates targetUrl.
          deps: toWebhookSubscriptionDeps(deps),
          input: {
            workspaceId: deps.workspaceId,
            id: subscriptionId,
          },
        });

        res.json({ subscription: toAdminSubscriptionResponse({ subscription, lastDelivery: null }) });
      } catch (err) {
        if (err instanceof WebhookSubscriptionNotFoundError) {
          res.status(404).json({ error: err.message });
          return;
        }

        sendAdminFailure({ res, error: err }, { operation: "routes/integrations/delete", code: "INTERNAL_ERROR" });
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { toAdminDeliveryResponse } from "#src/server/inbound/admin-http/http/integrations";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { IntegrationsRouteRegistrar } from "./deps.js";

/** Default page size when the caller doesn't pass `?limit=`. */
const DEFAULT_DELIVERIES_PAGE_SIZE = 50;
/** Hard cap on a single delivery-log page, regardless of what the caller requests. */
const MAX_DELIVERIES_PAGE_SIZE = 200;

/** Parses and clamps the `?limit=` query param into `[1, MAX_DELIVERIES_PAGE_SIZE]`. */
function resolvePageSize(rawLimit: unknown): number {
  const parsed = Number(rawLimit);
  if (!Number.isFinite(parsed) || parsed <= 0) return DEFAULT_DELIVERIES_PAGE_SIZE;
  return Math.min(Math.floor(parsed), MAX_DELIVERIES_PAGE_SIZE);
}

/**
 * GET the delivery log for one subscription (status, attempts, last response, timestamp),
 * newest-first.
 *
 * Gated by `admin.integrations.manage` — no dedicated read permission exists for the `integrations`
 * domain (no other route in this pass split it into `.read`/`.manage`), so the same single
 * permission that gates subscription mutations also gates this read, mirroring `member.manage`'s
 * coverage of its whole domain.
 */
export const registerAdminIntegrationsDeliveriesRoute: IntegrationsRouteRegistrar = (app, deps) => {
  app.get(
    "/api/admin/v1/workspaces/:workspaceId/integrations/subscriptions/:subscriptionId/deliveries",
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const subscriptionId = String(req.params.subscriptionId ?? "");

      try {
        const principal = getAuthedPrincipal(res);
        const authResult = await deps.authorize({
          principalId: principal.id,
          permission: "admin.integrations.manage",
          workspaceId: deps.workspaceId,
          entityType: "webhook_subscription",
          entityId: subscriptionId,
        });
        if (!authResult.allowed) {
          res.status(403).json({
            error: `principal '${principal.id}' is not authorized for 'admin.integrations.manage' (${authResult.reason})`,
            code: "FORBIDDEN",
            details: { permission: "admin.integrations.manage", reason: authResult.reason },
          });
          return;
        }

        const subscription = await deps.webhookSubscriptionRepo.findById({
          workspaceId: deps.workspaceId,
          id: subscriptionId,
        });
        if (!subscription) {
          res.status(404).json({ error: `webhook subscription '${subscriptionId}' was not found` });
          return;
        }

        const deliveries = await deps.webhookDeliveryRepo.listBySubscription({
          workspaceId: deps.workspaceId,
          subscriptionId,
          limit: resolvePageSize(req.query.limit),
        });

        // Newest-first for the log view — the repo orders before limiting (with id breaking ties).
        // Sorting here after LIMIT would leave the wrong rows on the "most recent" page (F1761).
        res.json({ deliveries: deliveries.map(toAdminDeliveryResponse) });
      } catch (error) {
        sendAdminFailure({ res, error }, { operation: "routes/integrations/deliveries", code: "INTERNAL_ERROR" });
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { WebhookDeliveryRecord } from "#src/features/webhooks/index";
import { toAdminSubscriptionResponse } from "#src/server/inbound/admin-http/http/integrations";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { IntegrationsRouteRegistrar } from "./deps.js";

/**
 * Bound on how many of a subscription's most recent deliveries are read to compute the
 * "last delivery" summary shown per row. Delivery volume grows independently of how many
 * subscriptions exist, so this caps the read cost per subscription per request rather than
 * assuming delivery volume stays small.
 */
const LAST_DELIVERY_LOOKUP_LIMIT = 50;

/**
 * GET all webhook subscriptions for the workspace, each annotated with its most recent delivery
 * (list screen: label, target URL, status, last delivery).
 *
 * Gated by `admin.integrations.manage`, same reasoning as `deliveries.ts` (no split `.read` permission
 * exists for this domain).
 */
export const registerAdminIntegrationsListRoute: IntegrationsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/integrations/subscriptions", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.integrations.manage",
        workspaceId: deps.workspaceId,
        entityType: "webhook_subscription",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.integrations.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.integrations.manage", reason: authResult.reason },
        });
        return;
      }

      const subscriptions = await deps.webhookSubscriptionRepo.listByWorkspace({
        workspaceId: deps.workspaceId,
      });

      const subscriptionResponses = await Promise.all(
        subscriptions.map(async (subscription) => {
          const recentDeliveries = await deps.webhookDeliveryRepo.listBySubscription({
            workspaceId: deps.workspaceId,
            subscriptionId: subscription.id,
            limit: LAST_DELIVERY_LOOKUP_LIMIT,
          });
          return toAdminSubscriptionResponse({
            subscription,
            lastDelivery: mostRecentDelivery(recentDeliveries),
          });
        })
      );

      res.json({ subscriptions: subscriptionResponses });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/integrations/list", code: "INTERNAL_ERROR" });
    }
  });
};

/**
 * Most recent delivery by `createdAt`, computed here rather than assumed from the repo's return
 * order — `WebhookDeliveryRepoPort.listBySubscription` makes no ordering guarantee.
 *
 * @complexity O(n) over the bounded lookup window.
 * @overallScore 100
 */
function mostRecentDelivery(
  deliveries: readonly WebhookDeliveryRecord[]
): WebhookDeliveryRecord | null {
  if (deliveries.length === 0) return null;
  return deliveries.reduce((latest, candidate) =>
    candidate.createdAt > latest.createdAt ? candidate : latest
  );
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Request } from "express";

import {
  pauseSubscription,
  WebhookSubscriptionNotFoundError,
  WebhookSubscriptionValidationError,
} from "#src/features/webhooks/index";
import { toAdminSubscriptionResponse } from "#src/server/inbound/admin-http/http/integrations";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { toWebhookSubscriptionDeps, type IntegrationsRouteRegistrar } from "./deps.js";

/** `{ paused?: boolean }` body — defaults to pausing (`true`) for any non-boolean value,
 *  including absent, so `{ "paused": false }` is the only way to resume. */
function resolvePausedFlag(req: Request): boolean {
  const raw = req.body?.paused;
  return typeof raw === "boolean" ? raw : true;
}

/**
 * POST pause/resume a webhook subscription. One route, both directions — mirrors
 * `pauseSubscription`'s own `{ paused?: boolean }` design (defaults to pausing); body
 * `{ "paused": false }` resumes an already-paused subscription back to `active`.
 *
 * Gated by `admin.integrations.manage`, checked directly via `authorize()` (same pattern as `create.ts`).
 */
export const registerAdminIntegrationsPauseRoute: IntegrationsRouteRegistrar = (app, deps) => {
  app.post(
    "/api/admin/v1/workspaces/:workspaceId/integrations/subscriptions/:subscriptionId/pause",
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const paused = resolvePausedFlag(req);
      const subscriptionId = String(req.params.subscriptionId ?? "");

      try {
        const principal = getAuthedPrincipal(res);
        const authorized = await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.integrations.manage",
          workspaceId: deps.workspaceId,
          entityType: "webhook_subscription",
          entityId: subscriptionId,
        });
        if (!authorized) return;

        const { subscription } = await pauseSubscription(
          {
            // The shared egress policy is not exercised here: pause never re-validates targetUrl.
            deps: toWebhookSubscriptionDeps(deps),
            input: {
              workspaceId: deps.workspaceId,
              id: subscriptionId,
            },
          },
          { paused }
        );

        res.json({ subscription: toAdminSubscriptionResponse({ subscription, lastDelivery: null }) });
      } catch (err) {
        if (err instanceof WebhookSubscriptionNotFoundError) {
          res.status(404).json({ error: err.message });
          return;
        }

        if (err instanceof WebhookSubscriptionValidationError) {
          res.status(400).json({ error: err.message });
          return;
        }

        sendAdminFailure({ res, error: err }, { operation: "routes/integrations/pause", code: "INTERNAL_ERROR" });
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { MediaNotFoundError, MediaStillReferencedError, purgeMedia } from "#src/features/media/index";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { Express, Response } from "express";
import type { MediaRouteDeps } from "./deps.js";
import type { MediaWhereUsedDeps } from "./where-used.js";
import { readRouteParam, rejectForeignWorkspace } from "./route-guards.js";

/**
 * DELETE hard-purges a media asset — second rung of the ADR-027 §5 deletion
 * ladder. Requires Trash first and 409s with the referencing list while current content
 * still uses the asset. Lookup failures refuse deletion. Gated by `media.delete.force` (SPEC-021 REQ-39/OQ-01, ADR-027 §7) — a separate,
 * narrower permission than the ordinary trash's `media.delete`, since this is an irreversible purge
 * (mirrors `admin.menus.delete` vs `admin.menus.delete.force`'s split).
 */
export const registerAdminMediaDeleteRoute = (app: Express, deps: MediaRouteDeps & MediaWhereUsedDeps): void => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/media/:mediaId", async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;

    try {
      const principal = getAuthedPrincipal(res);
      const mediaId = readRouteParam({ req, name: "mediaId" });
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "media.delete.force",
        workspaceId: deps.workspaceId,
        entityType: "media",
        entityId: mediaId,
      });
      if (!authorized) return;

      // `purgeMedia` resolves `{ purged: true }` or throws, so there is no not-purged outcome to skip.
      const { purged } = await purgeMedia({
        deps: {
          mediaRepo: deps.mediaRepo,
          entryRefsRepo: deps.entryRefsRepo,
          postRepo: deps.postRepo,
          blobRepo: deps.assetBlobRepo,
          renditionRepo: deps.assetRenditionRepo,
          blobStore: deps.blobStore,
        },
        input: { workspaceId: deps.workspaceId, id: mediaId },
      });
      // The bytes are gone for good, so the Trash index row has to go with them — otherwise the
      // Trash screen keeps offering a Restore for an asset that no longer exists.
      await deps.forgetRemovedMedia({ workspaceId: deps.workspaceId, id: mediaId });
      res.json({ purged });
    } catch (err) {
      sendPurgeFailure({ res, err });
    }
  });
};

/** 409 with the referencing list while content still uses the asset, 404 for an unknown asset,
 *  otherwise a private 500.
 *  @complexity O(1). */
function sendPurgeFailure({ res, err }: { res: Response; err: unknown }): void {
  if (err instanceof MediaStillReferencedError) {
    res.status(409).json({ error: err.message, referencing: err.referencing });
    return;
  }
  if (err instanceof MediaNotFoundError) {
    res.status(404).json({ error: err.message });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/media/delete", code: "INTERNAL_ERROR" });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
