import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
/** Quick wins A: an admin adapter over the same guarded fetch and upload pipeline as the tool. */
import type { Express } from "express";
import { buildImportFilename, MediaImportValidationError } from "@jini-ai/cms/media/import";
import { MediaValidationError, TOVU_MAX_UPLOAD_BYTES, uploadMedia } from "#src/features/media/index";
import { fetchImage } from "#src/features/media-import/fetch-image";
import { resolveMediaPublicUrls } from "#src/features/media/public-urls";
import { EgressRefusedError } from "#src/platform/http/index";
import type { RouteDeps } from "#src/server/routes/types";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { toAdminMediaResponse } from "#src/server/inbound/admin-http/http/media";
import type { MediaRouteDeps } from "./deps.js";
import { parseOptionalStringField } from "./parse.js";

export type MediaImportUrlRouteDeps = MediaRouteDeps & Pick<RouteDeps, "mediaImportHttpClient">;

function parseImportInput(required: { body: unknown }, _optional: Record<string, never> = {}) {
  const { body } = required;
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    throw new MediaImportValidationError({ message: "url is required" });
  }
  const input = body as Record<string, unknown>;
  if (typeof input.url !== "string" || !input.url.trim()) {
    throw new MediaImportValidationError({ message: "url is required" });
  }
  return {
    url: input.url.trim(),
    filename: parseOptionalStringField(input.filename, "filename"),
    alt: parseOptionalStringField(input.alt, "alt"),
    caption: parseOptionalStringField(input.caption, "caption"),
    credit: parseOptionalStringField(input.credit, "credit"),
  };
}

/** Permission checks precede all outbound I/O; rejected bytes never reach uploadMedia.
 * @complexity O(n) in bounded downloaded bytes, plus fixed-count repository calls. */
export function registerAdminMediaImportUrlRoute(
  required: { app: Express; deps: MediaImportUrlRouteDeps },
  optional: { logEgressRefusal?: (line: string) => void } = {},
): void {
  const { app, deps } = required;
  app.post("/api/admin/v1/workspaces/:workspaceId/media/import-url", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      const auth = await deps.authorize({ principalId: principal.id, permission: "media.upload", workspaceId: deps.workspaceId, entityType: "media" });
      if (!auth.allowed) {
        res.status(403).json({ error: "not authorized for media.upload", code: "FORBIDDEN", details: { permission: "media.upload", reason: auth.reason } });
        return;
      }
      const input = parseImportInput({ body: req.body });
      // This is the dedicated MEDIA_IMPORT_EGRESS_POLICY client from composition, never the
      // credentialed-request client (which has a smaller cap and a different redirect policy).
      const fetched = await fetchImage({ deps: { httpClient: deps.mediaImportHttpClient }, url: input.url });
      const { media } = await uploadMedia({
        deps: { clock: deps.clock, idGen: deps.idGen, mediaRepo: deps.mediaRepo, blobRepo: deps.assetBlobRepo, renditionRepo: deps.assetRenditionRepo, blobStore: deps.blobStore },
        input: {
          workspaceId: deps.workspaceId, bytes: fetched.bytes, contentType: fetched.contentType,
          filename: buildImportFilename({ url: fetched.url, contentType: fetched.contentType }, { override: input.filename }),
          alt: input.alt, caption: input.caption, credit: input.credit, createdByPrincipal: principal.id,
        },
      }, { maxUploadBytes: TOVU_MAX_UPLOAD_BYTES });
      // As with the assistant import and human upload, a failure here must not report success:
      // the next rendition needs the persisted sniffed type to serve this blob correctly.
      await deps.mediaContentTypeStore.set({ workspaceId: deps.workspaceId, sha256: media.source.sha256, contentType: fetched.contentType });
      const publicUrl = (await resolveMediaPublicUrls(deps, [media])).get(media.id) ?? null;
      res.status(201).json({ media: toAdminMediaResponse({ media, contentType: fetched.contentType, publicUrl, byteSize: fetched.bytes.byteLength }) });
    } catch (error) {
      if (error instanceof EgressRefusedError) {
        // Full DNS diagnosis is operator-log-only, matching the assistant tool's refusal contract.
        (optional.logEgressRefusal ?? console.warn)(`[media-import] admin URL import refused: ${error.message}`);
        res.status(400).json({ error: error.callerSafeMessage });
      } else if (error instanceof MediaImportValidationError || error instanceof MediaValidationError) {
        res.status(400).json({ error: error.message });
      } else {
        sendAdminFailure({ res, error }, { operation: "routes/media/import-url", code: "INTERNAL_ERROR" });
      }
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { listMedia } from "#src/features/media/index";
import { resolveMediaPublicUrls } from "#src/features/media/public-urls";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { toAdminMediaListResponse } from "#src/server/inbound/admin-http/http/media";
import { resolveContentTypes } from "./content-type.js";
import { resolveMediaByteSizes } from "./byte-size.js";
import type { MediaRouteRegistrar } from "./deps.js";

/**
 * GET all media in the workspace (all statuses — active + trashed; mirrors `listAdminPosts`).
 * Gated by `media.read` (SPEC-021 REQ-39/OQ-01, ADR-027 §7).
 */
export const registerAdminMediaListRoute: MediaRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/media", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const kind = req.query.kind ?? "media";
    if (kind !== "media" && kind !== "document") { res.status(400).json({ error: "invalid media kind" }); return; }
    if (kind === "document") res.set("Cache-Control", "private, no-store");
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "media.read",
        workspaceId: deps.workspaceId,
        entityType: "media",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'media.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "media.read", reason: authResult.reason },
        });
        return;
      }

      const { media } = await listMedia({
        deps: { mediaRepo: deps.mediaRepo },
        input: { workspaceId: deps.workspaceId, kind },
      });
      const visible = kind === "document" ? media.filter(row => row.status === "active") : media;
      const [contentTypes, publicUrls, byteSizes] = await Promise.all([
        resolveContentTypes(deps, visible),
        resolveMediaPublicUrls(deps, visible),
        resolveMediaByteSizes({ deps, media: visible }),
      ]);
      res.json(toAdminMediaListResponse({ media: visible, contentTypesBySha256: contentTypes, publicUrlsById: publicUrls, byteSizesBySha256: byteSizes }));
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/media/list", code: "INTERNAL_ERROR", message: "The media library could not be loaded." });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { documentContentType, documentDisplayFilename, MAX_DOCUMENT_BYTES } from "@jini-ai/cms/media";
import type { Request, Response } from "express";

import { findMediaByIdOrSlug, sanitizeSvg, sniffContentType, type MediaRecord } from "@jini-ai/cms/media";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { parseRangeHeader, type ParsedRange } from "#src/server/inbound/admin-http/range";
import type { MediaRouteDeps, MediaRouteRegistrar } from "./deps.js";
import { authorizeMediaOrRespond, readRouteParam, rejectForeignWorkspace } from "./route-guards.js";

/**
 * @file GET a media asset's ORIGINAL bytes for the admin UI's `<img>`/`<video>`
 * preview (the admin Media screen currently has no byte-serving route at all —
 * `Media.tsx`'s and `media-service.ts`'s file headers both name this gap; the
 * public `routes/site/media-rendition.ts` route only serves named, registered
 * transforms, and `transform_registry` is empty in every real deployment today).
 *
 * Authenticated + workspace-scoped, unlike the public rendition route: gated by
 * `media.read` (SPEC-021 REQ-39/OQ-01, ADR-027 §7) — the same permission
 * `list.ts` requires, since this route serves exactly the assets that route
 * already lists to the same caller, not a separate higher-trust capability.
 * (`media.download_original` also exists in the catalog, but its own doc
 * comment in `identity/permissions.ts` reserves it for a future short-TTL
 * signed-URL MINTING endpoint — a different, not-yet-built capability — not for
 * gating an ordinary authenticated-session preview fetch.)
 *
 * SECURITY — this route serves attacker-influenced bytes. `uploadMedia`
 * validates its MIME allowlist and sanitizes SVG before storage. Legacy blobs may predate that
 * protection, and response types must describe the actual bytes rather than stored metadata. So:
 *  - `Content-Type` is NEVER the client's upload-time string — it is always
 *    `sniffContentType(bytes)`, computed fresh from the bytes this exact
 *    response is about to send (`content-type-sniffer.ts`).
 *  - SVG is sanitized before inline serving, including blobs that predate safe ingest.
 *  - A sniffed `text/html`/`application/xhtml+xml` (same-origin stored-XSS vectors
 *    if ever rendered inline) is
 *    forced to `application/octet-stream` + `Content-Disposition: attachment`
 *    rather than served as-is — see `DISALLOWED_INLINE_CONTENT_TYPES` below.
 *  - `X-Content-Type-Options: nosniff` is always set, so a browser trusts the
 *    Content-Type this route declares instead of re-sniffing the raw bytes
 *    itself (without this header, the HTML download defusal above is moot — a
 *    sniffing browser could still render forced-`octet-stream` bytes as HTML).
 *  - A restrictive `Content-Security-Policy` and `Cross-Origin-Resource-Policy`
 *    ride along as further defense in depth in case the response is ever
 *    reached by a path other than an `<img>`/`<video>` tag (e.g. direct
 *    navigation to the URL in a new tab).
 *  - `storageKey` is never taken from the request — it only ever comes from
 *    this workspace's own `assetBlobRepo` row, looked up by the media's own
 *    `source.sha256` (mirrors `resolveMediaRendition`'s identical lookup in
 *    `rendition-service.ts`), so there is no path from request input to the
 *    blob store's file-path resolution at all (no traversal surface to guard
 *    beyond "never wire a request field into `storageKey`").
 *  - Trashed assets 410, mirroring `resolveMediaRendition`'s disclosed
 *    trashed-stands-in-for-purged mapping (`rendition-service.ts`'s doc
 *    comment) rather than inventing a new gone/not-found split. Nothing about
 *    a media asset's existence is ever revealed to a caller who fails the
 *    `requireAdminSession` gate (401, before this handler runs at all) or the
 *    `media.read` authorization check immediately below (403, before any
 *    `mediaRepo`/`assetBlobRepo` lookup happens) — the trashed-vs-not-found
 *    distinction is only ever visible to an already-authorized principal.
 *
 * RANGE SUPPORT: `Range: bytes=...` is honored via `parseRangeHeader`
 * (`http/range.ts`) so a `<video>` tag can seek instead of buffering the whole
 * file — see that module's doc comment for the exact malformed/multi-range/
 * out-of-bounds handling this defers to.
 */

/**
 * Keep inline logo styles and data images; sanitization strips references other than document-local
 * fragments and data URLs, so same-origin image loads are unnecessary. Retain the sandbox as
 * defense in depth when an SVG is opened as a top-level document.
 */
export const SVG_CONTENT_SECURITY_POLICY = "default-src 'none'; style-src 'unsafe-inline'; img-src data:; sandbox";

/** Sniffed types that must never be served as their literal `Content-Type` — HTML (and
 * XHTML, which this route blocks even though `sniffContentType` currently folds it into
 * `"text/html"` — see that module's doc comment) are same-origin stored-XSS vectors if a browser
 * ever renders them inline. Kept as an explicit route-level check (rather than only trusting the
 * sniffer's own allowlist shape) so this invariant holds even if `content-type-sniffer.ts` is
 * later extended to recognize more textual formats.
 *
 * Exported (2026-08-24) — `routes/site/media-rendition.ts`'s public video-original route reuses
 * this same check rather than re-declaring it, so the two routes' XSS defusal can't drift apart. */
export const DISALLOWED_INLINE_CONTENT_TYPES: ReadonlySet<string> = new Set([
  "text/html",
  "application/xhtml+xml",
]);

/**
 * Looks up the media row and its source blob, or writes the appropriate early response and returns
 * `null` — 404 for an unknown media id, 410 for a trashed one. Isolated so these three sequential
 * guards don't add to the handler's own branch count.
 *
 * `params.mediaId` (2026-09-07: resolved via `findMediaByIdOrSlug`, not a bare `findById`) may be
 * either the asset's real `id` or its `slug` — this route's `:mediaId` segment is exactly the kind
 * of hand-typeable reference the slug feature exists for. Safe to do here without the FK hazard
 * `resolveMediaRendition`'s own doc calls out for `asset_renditions`: this function's only downstream
 * key is `media.source.sha256` (blob content-addressing), never the raw `params.mediaId` itself.
 *
 * Exported (2026-08-24) — `routes/site/media-rendition.ts`'s public video-original route reuses
 * this same lookup/guard sequence rather than re-implementing it (same "own it once, reuse
 * everywhere" split this codebase already applies to `renderImageTag`/`renderWidgetMediaImage`) —
 * so this one change covers the admin preview route AND the public hand-typed `<video src="/m/
 * {slug-or-id}/original">` case in one edit.
 *
 * `onNotFound` (readable-slugs plan S2b, 2026-09-23): the two callers need DIFFERENT unknown-asset
 * responses. This route's own admin caller keeps its historical `404 {error: "media '<x>' was not
 * found"}` (default, below) — an authenticated caller learning an id doesn't exist is not a
 * security concern. The public video route, however, must make an unknown asset indistinguishable
 * from a gate-denied one (its own `sendMediaNotFound`'s `private, no-store` + `"video rendition not
 * found"` shape), or the difference is a free existence oracle for a caller who only knows a slug
 * is guessable. Passing a callback keeps that policy at the PUBLIC route's own call site rather than
 * teaching this shared function two hardcoded response shapes.
 *
 * @throws {Error} the same data-integrity-gap error the pre-extraction route threw, if the media row
 * exists but its source blob does not (see the inline comment at the throw site).
 * @complexity O(1) — at most two indexed lookups for the media row (slug, then id), plus one blob lookup.
 */
export async function resolveMediaOriginalBlob(
  deps: Pick<MediaRouteDeps, "mediaRepo" | "assetBlobRepo">,
  res: Response,
  params: { workspaceId: string; mediaId: string },
  onNotFound?: (res: Response) => void
): Promise<{ media: MediaRecord; blob: NonNullable<Awaited<ReturnType<MediaRouteDeps["assetBlobRepo"]["findByHash"]>>> } | null> {
  const media = await findMediaByIdOrSlug({ deps: { mediaRepo: deps.mediaRepo }, input: { workspaceId: params.workspaceId, idOrSlug: params.mediaId } });
  if (!media) {
    if (onNotFound) {
      onNotFound(res);
    } else {
      res.status(404).json({ error: `media '${params.mediaId}' was not found` });
    }
    return null;
  }
  if (media.status === "trashed") {
    res.status(410).set("Cache-Control", "no-store").end();
    return null;
  }

  const blob = await deps.assetBlobRepo.findByHash({ workspaceId: params.workspaceId, sha256: media.source.sha256 });
  if (!blob) {
    // Data-integrity gap, not a routine 404 — `uploadMedia`'s invariant (bytes written before
    // the media row) means this should be unreachable. Mirrors `resolveMediaRendition`'s
    // identical branch in `rendition-service.ts`: thrown, not silently treated as not-found.
    throw new Error(`media '${media.id}': source blob for sha256 '${media.source.sha256}' was not found`);
  }
  return { media, blob };
}

/**
 * Writes the security headers documented in this file's header, then the (possibly range-sliced)
 * body. Isolated so the range-decision branching doesn't add to the handler's own branching — the
 * security reasoning for each header stays in the module doc above, not duplicated here.
 *
 * Exported (2026-08-24) — see {@link resolveMediaOriginalBlob}'s doc for why the public
 * video-original route reuses this instead of a second implementation.
 *
 * @complexity O(1) aside from the byte copy for a partial range.
 */
export function sendMediaOriginalResponse(
  res: Response,
  bytes: Uint8Array,
  range: ParsedRange,
  contentType: { safe: string; forceDownload: boolean }
): void {
  const totalLength = bytes.byteLength;
  res.set("X-Content-Type-Options", "nosniff");
  res.set("Content-Security-Policy", contentType.safe === "image/svg+xml"
    ? SVG_CONTENT_SECURITY_POLICY
    : "default-src 'none'; sandbox");
  res.set("Cross-Origin-Resource-Policy", "same-origin");
  res.set("Cache-Control", "private, no-store");
  res.set("Content-Type", contentType.safe);
  res.set("Accept-Ranges", "bytes");
  if (contentType.forceDownload) {
    res.set("Content-Disposition", "attachment");
  }

  if (range.kind === "unsatisfiable") {
    res.status(416).set("Content-Range", `bytes */${totalLength}`).end();
    return;
  }
  if (range.kind === "range") {
    res
      .status(206)
      .set("Content-Range", `bytes ${range.start}-${range.end}/${totalLength}`)
      .send(Buffer.from(bytes.subarray(range.start, range.end + 1)));
    return;
  }
  res.status(200).send(Buffer.from(bytes));
}

export const registerAdminMediaOriginalRoute: MediaRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/media/:mediaId/original", async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;

    try {
      const principal = getAuthedPrincipal(res);
      const mediaId = readRouteParam({ req, name: "mediaId" });
      const authorized = await authorizeMediaOrRespond({ res, authorize: deps.authorize, params: {
        principalId: principal.id,
        permission: "media.read",
        workspaceId: deps.workspaceId,
        entityType: "media",
        entityId: mediaId,
      } });
      if (!authorized) return;

      const resolved = await resolveMediaOriginalBlob(deps, res, { workspaceId: deps.workspaceId, mediaId });
      if (!resolved) {
        return;
      }
      const sendOriginal = resolved.media.kind === "document" ? sendDocumentOriginal : sendInlineOriginal;
      await sendOriginal({ req, res, deps, ...resolved });
    } catch (error) {
      // No typed domain error is thrown on this route's own read path — `media`/`assetBlobRepo`
      // not-found is handled explicitly above via the `null` checks, not by catching an error type
      // (unlike the write routes, which call `media-service.ts` functions that throw
      // `MediaNotFoundError`). Anything reaching here is a genuine unexpected failure (e.g. the
      // blob store's `get()` rejecting, or the "data-integrity gap" throw above).
      sendAdminFailure({ res, error }, { operation: "routes/media/original", code: "INTERNAL_ERROR" });
    }
  });
};

/** What both original senders receive: the request (for `Range`), the response, and the resolved asset. */
interface SendOriginalInput {
  req: Request;
  res: Response;
  deps: Pick<MediaRouteDeps, "blobStore">;
  media: MediaRecord;
  blob: { storageKey: string };
}

/**
 * Serves a document as a download under its display filename, with its filename-policy type.
 * Refuses (throws, so the caller 500s) a document over `MAX_DOCUMENT_BYTES` — before reading the
 * bytes when the store can report a size, and again on the bytes actually read.
 *
 * @complexity O(n) in the document's size (one read, one optional copy for a partial range).
 */
async function sendDocumentOriginal({ req, res, deps, media, blob }: SendOriginalInput): Promise<void> {
  const size = await deps.blobStore.sizeOf?.({ storageKey: blob.storageKey });
  if (size != null && size > MAX_DOCUMENT_BYTES) throw new Error("document exceeds size limit");
  const sourceBytes = await deps.blobStore.get({ storageKey: blob.storageKey });
  if (sourceBytes.byteLength > MAX_DOCUMENT_BYTES) throw new Error("document exceeds size limit");
  const filename = documentDisplayFilename(media);
  // RFC 5987 encoding keeps titles out of header syntax; storage keys never use names.
  // The UTF-8 Buffer round-trip turns a lone UTF-16 surrogate into U+FFFD, which
  // `encodeURIComponent` would otherwise reject with a URIError.
  const encoded = encodeURIComponent(Buffer.from(filename).toString("utf8")).replace(/[!'()*]/g, char => `%${char.charCodeAt(0).toString(16).toUpperCase()}`);
  res.set("Content-Disposition", `attachment; filename="document"; filename*=UTF-8''${encoded}`);
  sendMediaOriginalResponse(res, sourceBytes, parseRangeHeader({ header: req.get("range"), totalLength: sourceBytes.byteLength }), {
    safe: documentContentType({ filename: media.originalFilename ?? "" }), forceDownload: false,
  });
}

/**
 * Serves an image/video inline under the type sniffed from its bytes (see the module doc's
 * SECURITY list): SVG is sanitized first, and HTML is forced to an `octet-stream` download.
 *
 * @complexity O(n) in the asset's size (read, optional SVG sanitize, optional range copy).
 */
async function sendInlineOriginal({ req, res, deps, blob }: SendOriginalInput): Promise<void> {
  const sourceBytes = await deps.blobStore.get({ storageKey: blob.storageKey });
  const sniffed = sniffContentType({ bytes: sourceBytes });
  // Old blobs may predate ingest sanitization; never authorize raw markup from its label.
  const bytes = sniffed === "image/svg+xml" ? await sanitizeSvg({ bytes: sourceBytes }) : sourceBytes;
  const totalLength = bytes.byteLength;
  const forceDownload = DISALLOWED_INLINE_CONTENT_TYPES.has(sniffed);
  // Every response here reflects this principal's authorization at request time and may name
  // whether a specific asset is trashed — never shared-cached (mirrors the public rendition
  // route's `no-store` on its own non-ok outcomes; this route applies it to every outcome
  // since none of its bytes are safe to cache across principals/permission changes). See
  // `sendMediaOriginalResponse` for the rest of the security headers.
  const range = parseRangeHeader({ header: req.get("range"), totalLength });
  sendMediaOriginalResponse(res, bytes, range, {
    safe: forceDownload ? "application/octet-stream" : sniffed,
    forceDownload,
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import {
  MediaProviderCredentialSecretStoreUnconfiguredError,
  MediaProviderCredentialValidationError,
  saveMediaProviderCredentials,
} from "#src/features/media/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { MediaProviderRouteRegistrar } from "./deps.js";

/**
 * PUT the workspace's media-generation vendor credentials as a WHOLE SET. Answers
 * `MediaProvidersPort.saveMediaProviders` in `@jini-ai/ui`.
 *
 * Body is the provider map itself (`{ "openai": { apiKey?, baseUrl?, model? }, … }`), not a wrapped
 * envelope — matching the port's signature. A provider absent from the body is DELETED: the tab
 * sends its entire local map and expresses a cleared credential as an omission, so treating absence
 * as "leave alone" would make Clear silently do nothing.
 *
 * Gated by `admin.integrations.manage`, the same permission every other vendor-credential route in
 * this codebase uses (connectors, commerce, external-mcp, and the webhook-subscription routes in
 * `015-integrations.yaml`) — not `media.write`, which is deprecated and no longer granted to fresh
 * admin roles, so it would silently lock new admins out of a feature legacy admins can still reach.
 *
 * The response never echoes key material — it is the same markers-only map GET returns. Three
 * failure outcomes, mirroring `put-site-credential.ts`'s split: 400 validation (unknown provider
 * id, wrong field type, oversized field), 503 `SECRET_STORE_UNCONFIGURED` (missing
 * `TOVU_SITE_KEY`, detected before any write lands), 500 everything else.
 */
export const registerAdminMediaPutProvidersRoute: MediaProviderRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/media/providers", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.integrations.manage",
        workspaceId: deps.workspaceId,
        entityType: "media",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.integrations.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.integrations.manage", reason: authResult.reason },
        });
        return;
      }

      const providers = await saveMediaProviderCredentials(
        {
          repo: deps.mediaProviderCredentialRepo,
          sealer: deps.siteAssistantSecretSealer,
          keyring: deps.siteAssistantSecretKeyring,
          clock: deps.clock,
          providerCatalog: deps.mediaProviderRegistry,
        },
        { workspaceId: deps.workspaceId, providers: (req.body ?? {}) as Record<string, never> }
      );
      res.json(providers);
    } catch (err) {
      if (err instanceof MediaProviderCredentialValidationError) {
        res.status(400).json({ error: err.message, code: "MEDIA_PROVIDER_CREDENTIAL_VALIDATION_ERROR" });
        return;
      }
      if (err instanceof MediaProviderCredentialSecretStoreUnconfiguredError) {
        res.status(503).json({
          error:
            "the media provider credential store is not configured — set TOVU_SITE_KEY (a hex-encoded site key) in the server environment",
          code: "SECRET_STORE_UNCONFIGURED",
        });
        return;
      }
      sendAdminFailure({ res, error: err }, { operation: "routes/media/put-providers", code: "INTERNAL_ERROR" });
    }
  });
};

import { replaceMediaFile } from '@jini-ai/cms/media';
import type { Express, Response } from 'express';
import { decodeStrictBase64 } from '#src/contracts/core/index';
import { DEFAULT_ALLOWED_MIME_TYPES, MediaValidationError, TOVU_MAX_UPLOAD_BYTES,
  resolveUploadContentType, type MediaRecord } from '#src/features/media/index';
import { getAuthedPrincipal } from '#src/server/inbound/admin-http/dev-auth';
import type { MediaRouteDeps } from './deps.js';
import { authorizeMediaOrRespond, readRouteParam, rejectForeignWorkspace, sendMediaNotFound,
  sendValidationOrInternalError } from './route-guards.js';
import { toStoredMediaResponse } from './stored-media-response.js';

/** The declared content type and base64 payload, refused unless the filename, type and payload are
 *  all non-empty strings. @complexity O(1). */
function readReplacementFields({ body }: { body: unknown }): { filename: string; contentType: string; dataBase64: string } {
  const values = (body ?? {}) as Record<string, unknown>;
  const { filename, contentType, dataBase64 } = values;
  const validFilename = typeof filename === 'string' && Boolean(filename.trim());
  const validContentType = typeof contentType === 'string' && Boolean(contentType);
  if (!validFilename || !validContentType || typeof dataBase64 !== 'string' || !dataBase64) {
    throw new MediaValidationError({ message: 'filename, contentType, and dataBase64 are required' });
  }
  return { filename, contentType, dataBase64 };
}

/** Decodes and verifies the replacement bytes: strict base64, within the host upload cap, and an
 *  allowed type as sniffed from the bytes (not the declared label). A non-empty strict-base64
 *  payload always decodes to at least one byte, and `replaceMediaFile` refuses empty bytes too.
 *  @complexity O(n) in the payload length. */
function parseReplacement({ body }: { body: unknown }) {
  const { filename, contentType, dataBase64 } = readReplacementFields({ body });
  const bytes = decodeStrictBase64(dataBase64);
  if (!bytes) throw new MediaValidationError({ message: 'dataBase64 is not valid base64' });
  if (bytes.byteLength > TOVU_MAX_UPLOAD_BYTES) {
    throw new MediaValidationError({ message: `uploaded file exceeds the ${TOVU_MAX_UPLOAD_BYTES / (1024 * 1024)} MB size cap` });
  }
  const verified = resolveUploadContentType({ bytes, declaredContentType: contentType });
  if (!DEFAULT_ALLOWED_MIME_TYPES.has(verified)) {
    throw new MediaValidationError({ message: `content type '${verified}' is not allowed for upload` });
  }
  return { bytes, contentType: verified, provenance: { kind: 'upload' as const, path: filename } };
}

/** Loads the asset to replace, or writes the refusal and returns `null`: 404 when it does not exist,
 *  409 when it is trashed, 503 when the repository cannot switch a file transactionally. Runs before
 *  the body is decoded. @complexity O(1) — one indexed lookup. */
async function findReplaceableMedia({ deps, res, id }: { deps: MediaRouteDeps; res: Response; id: string }): Promise<MediaRecord | null> {
  const media = await deps.mediaRepo.findById({ workspaceId: deps.workspaceId, id });
  if (!media) { sendMediaNotFound({ res, mediaId: id }); return null; }
  if (media.status !== 'active') {
    res.status(409).json({ error: 'trashed media cannot be replaced', code: 'ENTITY_IN_TRASH' }); return null;
  }
  if (typeof deps.mediaRepo.replaceFileIfVersion !== 'function' ||
    typeof deps.mediaRepo.saveRenditionIfSource !== 'function') {
    res.status(503).json({ error: 'media file replacement is unavailable', code: 'MEDIA_REPLACE_UNAVAILABLE' }); return null;
  }
  return media;
}

/** Same JSON upload protocol and per-entity permission as the host's media metadata route.
 * Source replacement is explicit; PATCH metadata still cannot change a source hash. */
export function registerAdminMediaReplaceRoute({ app, deps }: { app: Express; deps: MediaRouteDeps },
  _optional: Record<string, never> = {}): void {
  app.post('/api/admin/v1/workspaces/:workspaceId/media/:mediaId/replace', async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;
    try {
      const id = readRouteParam({ req, name: 'mediaId' });
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeMediaOrRespond({ res, authorize: deps.authorize, params: { principalId: principal.id,
        permission: 'media.update', workspaceId: deps.workspaceId, entityType: 'media', entityId: id } });
      if (!authorized) return;
      const media = await findReplaceableMedia({ deps, res, id });
      if (!media) return;
      const upload = parseReplacement({ body: req.body });
      const saved = await replaceMediaFile({ deps, media, ...upload, principalId: principal.id }, { maxUploadBytes: TOVU_MAX_UPLOAD_BYTES });
      if (!saved) {
        res.status(409).json({ error: 'media changed while replacing its file', code: 'MEDIA_REPLACE_CONFLICT' }); return;
      }
      res.json(await toStoredMediaResponse({ deps, media: saved, contentType: upload.contentType, byteLength: upload.bytes.byteLength }));
    } catch (error) {
      sendValidationOrInternalError({ res, error });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Response } from 'express';
import { DocumentTextExtractionError, MediaNotFoundError, MediaValidationError, readDocumentText } from '@jini-ai/cms/media';
import { getAuthedPrincipal } from '#src/server/inbound/admin-http/dev-auth';
import type { MediaRouteDeps } from './deps.js';

/** Private source reads share Library tools' 64 KiB UTF-8 paging policy. Authorize before bytes. */
export function registerAdminMediaTextRoute(required: { app: Express; deps: MediaRouteDeps },
  _optional: Record<string, never> = {}): void {
  const { app, deps } = required;
  app.get('/api/admin/v1/workspaces/:workspaceId/media/:mediaId/text', async (req, res) => {
    res.set('Cache-Control', 'private, no-store').set('X-Content-Type-Options', 'nosniff');
    if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ error: 'workspace was not found' }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      const id = String(req.params.mediaId);
      const access = await deps.authorize({ principalId: principal.id, permission: 'media.read', workspaceId: deps.workspaceId, entityType: 'media', entityId: id });
      if (!access.allowed) { res.status(403).json({ error: 'media.read is required', code: 'FORBIDDEN' }); return; }
      res.json(await readDocumentText({ deps: { mediaRepo: deps.mediaRepo, blobRepo: deps.assetBlobRepo, blobStore: deps.blobStore, documentTextExtractors: deps.documentTextExtractors },
        input: { workspaceId: deps.workspaceId, id, offset: parseTextOffset(req.query.offset) } }));
    } catch (error) {
      sendTextReadFailure({ res, error });
    }
  });
}

/** An omitted offset pages from byte 0; anything but a run of decimal digits is refused before any read.
 *  @complexity O(n) in the offset's length. */
function parseTextOffset(rawOffset: unknown): number {
  if (rawOffset === undefined) return 0;
  if (typeof rawOffset !== 'string' || !/^\d+$/u.test(rawOffset)) throw new MediaValidationError({ message: 'offset must be a non-negative byte offset' });
  return Number(rawOffset);
}

/** 404 for a missing document, 400 for a refused read, otherwise a private 500.
 *  @complexity O(1). */
function sendTextReadFailure({ res, error }: { res: Response; error: unknown }): void {
  if (error instanceof DocumentTextExtractionError) {
    res.status(400).json({ error: error.message, code: error.code });
    return;
  }
  let status: number;
  if (error instanceof MediaNotFoundError) status = 404;
  else if (error instanceof MediaValidationError) status = 400;
  else status = 500;
  if (status === 500) { sendAdminFailure({ res, error }); return; }
  res.status(status).json({ error: (error as Error).message });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import type { MediaRecord } from "#src/features/media/index";
import { resolveMediaPublicUrls } from "#src/features/media/public-urls";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { toAdminMediaResponse } from "#src/server/inbound/admin-http/http/media";
import { readRecordedContentType } from "./content-type.js";
import { resolveMediaByteSizes } from "./byte-size.js";
import type { MediaRouteDeps, MediaRouteRegistrar } from "./deps.js";
import { authorizeMediaOrRespond, readRouteParam, rejectForeignWorkspace, sendMediaNotFound } from "./route-guards.js";

/**
 * POST soft-delete (trash) a media asset — first rung of the ADR-027 §5 deletion ladder. Gated by
 * `media.delete` (SPEC-021 REQ-39/OQ-01, ADR-027 §7).
 *
 * The marker flip goes through `deps.removeMedia` rather than `@jini-ai/cms`'s `trashMedia`, so the
 * flip and the Trash index row are one transaction. The `display` snapshot is taken from the record
 * this route already loaded — columns only, no payload parse, so an asset whose metadata is corrupt
 * is still deletable and still listable in the Trash.
 */
export const registerAdminMediaTrashRoute: MediaRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/media/:mediaId/trash", async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;

    try {
      const principal = getAuthedPrincipal(res);
      const mediaId = readRouteParam({ req, name: "mediaId" });
      const authorized = await authorizeMediaOrRespond({ res, authorize: deps.authorize, params: {
        principalId: principal.id,
        permission: "media.delete",
        workspaceId: deps.workspaceId,
        entityType: "media",
        entityId: mediaId,
      } });
      if (!authorized) return;

      const existing = await deps.mediaRepo.findById({ workspaceId: deps.workspaceId, id: mediaId });
      if (!existing) {
        sendMediaNotFound({ res, mediaId });
        return;
      }

      const removed = await deps.removeMedia({
        workspaceId: deps.workspaceId,
        id: mediaId,
        display: { title: existing.title, subtitle: existing.slug },
        at: deps.clock.nowIso(),
        expectedVersion: existing.version,
        actor: { principalId: principal.id },
      });
      if (!removed.ok) {
        sendRemoveFailure({ res, mediaId, reason: removed.reason });
        return;
      }

      // Re-read rather than reconstruct: the marker flip happened in SQL, so this is the one shape
      // guaranteed to match what every other media route returns.
      const media = await deps.mediaRepo.findById({ workspaceId: deps.workspaceId, id: mediaId });
      if (!media) {
        sendMediaNotFound({ res, mediaId });
        return;
      }
      res.json({ media: await toTrashedMediaResponse({ deps, media }) });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/media/trash", code: "INTERNAL_ERROR" });
    }
  });
};

/** Maps a refused marker flip to its response.
 *  @complexity O(1). */
function sendRemoveFailure({ res, mediaId, reason }: { res: Response; mediaId: string; reason: string }): void {
  // `not-found` can only mean the row went away between the read above and the flip.
  if (reason === "not-found") {
    sendMediaNotFound({ res, mediaId });
    return;
  }
  res.status(409).json({ error: `media '${mediaId}' changed while it was being trashed` });
}

/** The admin response for the re-read asset: recorded type, public URL and stored size, read in parallel.
 *  @complexity O(1) — three independent single-asset lookups. */
async function toTrashedMediaResponse({ deps, media }: { deps: MediaRouteDeps; media: MediaRecord }) {
  const [contentType, publicUrl, byteSizes] = await Promise.all([
    readRecordedContentType(deps, media.source.sha256),
    resolveMediaPublicUrls(deps, [media]).then((urls) => urls.get(media.id) ?? null),
    resolveMediaByteSizes({ deps, media: [media] }),
  ]);
  return toAdminMediaResponse({ media, contentType, publicUrl, byteSize: byteSizes.get(media.source.sha256) ?? null });
}

import { adminFailureResponse, type AdminFailurePorts } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { MediaConflictError, MediaNotFoundError, MediaValidationError, updateMediaMetadata } from "#src/features/media/index";
import { resolveMediaPublicUrls } from "#src/features/media/public-urls";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { entityNotLiveResponse } from "#src/server/inbound/admin-http/http/entity-not-live";
import { toAdminMediaResponse } from "#src/server/inbound/admin-http/http/media";
import { readRecordedContentType } from "./content-type.js";
import { resolveMediaByteSizes } from "./byte-size.js";
import type { MediaRouteRegistrar } from "./deps.js";
import { parseOptionalSlugField, parseOptionalStringField, parseOptionalTitleField } from "./parse.js";

/**
 * `undefined` (omitted) survives as `undefined`, `null` (explicit clear) survives as `null` rather
 * than coercing through `convert`, and anything else is passed through `convert` — matching
 * `updateMediaMetadata`'s width/height/cssClass undefined/null/value contract (see that input
 * type's doc). Deliberately distinct from `parse.js`'s string-field parsers: `width`/`height`/
 * `cssClass` accept `null` all the way through to the service layer, which has its own clear
 * semantics for them, whereas `alt`/`caption`/`credit`/`title` are mapped or rejected in `parse.js`
 * before they ever reach `updateMediaMetadata` (see that module's doc for why).
 *
 * @complexity O(1).
 */
function parseOptionalNullableField<T>(raw: unknown, convert: (value: unknown) => T): T | null | undefined {
  if (raw === undefined) return undefined;
  if (raw === null) return null;
  return convert(raw);
}

/**
 * Reads the eight metadata fields `updateMediaMetadata` accepts off an untyped request body,
 * applying the field-level parse rules above. A missing body coerces to `{}` so every field
 * reads as omitted rather than throwing on a property access — the pre-extraction route made the
 * same allowance via `req.body?.field`.
 *
 * `slug` (2026-09-07) joins the fixed key list `updateMediaMetadata` reads — this function silently
 * dropping an unrecognized key is exactly the trap that would have made `slug` a no-op PATCH before
 * this line was added (see `ADS-memory/reports/2026-09-07-media-admin-ui.md`'s "the trap" for the
 * confirmed mechanism: a 200 response with every OTHER field's change applied and no error at all).
 *
 * @complexity O(1) — reads nine fixed properties.
 */
function parseMediaMetadataPatch(rawBody: unknown) {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    title: parseOptionalTitleField(body.title),
    slug: parseOptionalSlugField(body.slug),
    alt: parseOptionalStringField(body.alt, "alt"),
    caption: parseOptionalStringField(body.caption, "caption"),
    credit: parseOptionalStringField(body.credit, "credit"),
    width: parseOptionalNullableField(body.width, Number),
    height: parseOptionalNullableField(body.height, Number),
    cssClass: parseOptionalNullableField(body.cssClass, String),
    // Format/allowlist validation happens entirely in `updateMediaMetadata`
    // (`@jini-ai/cms/media`'s `resolveHtmlAttributesForUpdate`) — this parser's only job is the same
    // undefined-vs-provided/wrong-JSON-type boundary every other field parser in this file owns.
    htmlAttributes: parseOptionalNullableField(body.htmlAttributes, String),
  };
}

/** One mapped error response: the exact status/body this route has always returned for it. */
interface MediaUpdateErrorResponse {
  readonly status: number;
  readonly body: { readonly error: string };
}

/**
 * Maps a thrown `updateMediaMetadata` error to the status/body this route has always returned for
 * it, one function per error type — same table-shaped pattern
 * `custom-credentials/tool-registrations.ts`'s `mapCreateCredentialError` uses for the same reason
 * (source-complexity-drift ceiling: an inline instanceof chain inside the route handler's own
 * try/catch pushed it over 9). Anything not one of the three known error types (plus the new
 * `entityNotLiveResponse` arm, S8, web-high fix plan 2026-09-24) falls through to a generic 500,
 * matching this route's prior behavior exactly.
 *
 * @complexity O(1) — four `instanceof` checks.
 */
function mapMediaUpdateError(err: unknown, options: AdminFailurePorts = {}): MediaUpdateErrorResponse {
  const live = entityNotLiveResponse(err);
  if (live) return live;
  if (err instanceof MediaNotFoundError) return { status: 404, body: { error: err.message } };
  if (err instanceof MediaValidationError) return { status: 400, body: { error: err.message } };
  // A slug collision — either `resolveSlugForUpdate`'s own app-level courtesy check, or (on a
  // genuine race) `SqliteMediaRepo.save()`'s translated UNIQUE-constraint catch; both throw the
  // same `MediaConflictError` so this route needs only one branch regardless of which layer
  // caught it. 409, not 400: the request is well-formed, it just collides with existing state.
  if (err instanceof MediaConflictError) return { status: 409, body: { error: err.message } };
  return adminFailureResponse({ error: err, tracker: options.tracker }, { operation: "routes/media/update" });
}

/**
 * PATCH media metadata (title/slug/alt/caption/credit/width/height/cssClass — `source.sha256` is
 * write-once and this route's input shape has no field for it, matching
 * `updateMediaMetadata`'s contract). Gated by `media.update` (SPEC-021 REQ-39/OQ-01, ADR-027 §7).
 */
export const registerAdminMediaUpdateRoute: MediaRouteRegistrar = (app, deps) => {
  app.patch("/api/admin/v1/workspaces/:workspaceId/media/:mediaId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "media.update",
        workspaceId: deps.workspaceId,
        entityType: "media",
        entityId: String(req.params.mediaId ?? ""),
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'media.update' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "media.update", reason: authResult.reason },
        });
        return;
      }

      const { media } = await updateMediaMetadata({
        deps: { clock: deps.clock, mediaRepo: deps.mediaRepo },
        input: {
          workspaceId: deps.workspaceId,
          id: String(req.params.mediaId ?? ""),
          ...parseMediaMetadataPatch(req.body),
        },
      });
      const [contentType, publicUrl, byteSizes] = await Promise.all([
        readRecordedContentType(deps, media.source.sha256),
        resolveMediaPublicUrls(deps, [media]).then((urls) => urls.get(media.id) ?? null),
        resolveMediaByteSizes({ deps, media: [media] }),
      ]);
      res.json({ media: toAdminMediaResponse({ media, contentType, publicUrl, byteSize: byteSizes.get(media.source.sha256) ?? null }) });
    } catch (err) {
      const { status, body } = mapMediaUpdateError(err, { tracker: res.locals?.adminFailureTracker });
      res.status(status).json(body);
    }
  });
};

import { MAX_DOCUMENT_BYTES, documentContentType, type MediaKind } from "@jini-ai/cms/media";
import { createDocumentArchiveReader } from "#src/features/media/document-archive";
import type { Request, Response } from "express";

import { captureMediaUploaded, MediaConflictError, MediaValidationError, resolveUploadContentType, TOVU_MAX_UPLOAD_BYTES, uploadMedia } from "#src/features/media/index";
import { decodeStrictBase64 } from "#src/contracts/core/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { MediaRouteRegistrar } from "./deps.js";
import { parseOptionalStringField } from "./parse.js";
import { authorizeMediaOrRespond, rejectForeignWorkspace, sendValidationOrInternalError } from "./route-guards.js";
import { toStoredMediaResponse } from "./stored-media-response.js";

/** An upload request's fields after {@link parseUploadRequestFields}. */
interface UploadRequestFields {
  kind: MediaKind;
  filename: string;
  contentType: string;
  dataBase64: string;
  alt: string | undefined;
  caption: string | undefined;
  credit: string | undefined;
}

/** An omitted `kind` is an ordinary media upload; anything other than `media`/`document` is refused.
 *  @complexity O(1). */
function parseUploadKind(raw: unknown): MediaKind {
  const kind = raw ?? "media";
  if (kind !== "media" && kind !== "document") throw new MediaValidationError({ message: "invalid media kind" });
  return kind;
}

/** The three required upload fields plus the three optional metadata fields, parsed off an untyped
 *  body in one place, or `null` if a required field is missing or the wrong shape. `dataBase64` must
 *  be a non-empty string — an absent or non-string value is rejected here rather than reaching
 *  `Buffer.from`. `alt`/`caption`/`credit` go through `parse.js`'s `parseOptionalStringField`, which
 *  throws `MediaValidationError` for a non-string, non-null, non-undefined value — the caller MUST
 *  invoke this inside a `try`/`catch` (or otherwise catch synchronously), not treat it as
 *  throw-free the way the `null` return above is. On upload there is no existing value to preserve,
 *  so an explicit `null` here is equivalent to omitting the field (both end up `""` — see
 *  `uploadMedia`'s `input.alt?.trim() ?? ""`), unlike `update.ts`'s PATCH route where `null` clears
 *  a possibly-non-empty existing value.
 *  @complexity O(1). */
function parseUploadRequestFields(rawBody: unknown): UploadRequestFields | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const kind = parseUploadKind(body.kind);
  const filename = typeof body.filename === "string" ? body.filename : "";
  const contentType = String(body.contentType ?? "");
  const dataBase64 = body.dataBase64;
  if (!filename || (kind === "media" && !contentType)) return null;
  if (typeof dataBase64 !== "string" || !dataBase64) {
    return null;
  }
  return {
    kind,
    filename,
    contentType,
    dataBase64,
    alt: parseOptionalStringField(body.alt, "alt"),
    caption: parseOptionalStringField(body.caption, "caption"),
    credit: parseOptionalStringField(body.credit, "credit"),
  };
}

/**
 * Runs {@link parseUploadRequestFields} and turns both of its failure modes — a thrown
 * `MediaValidationError` (malformed `alt`/`caption`/`credit`) and a `null` return (a required field
 * missing or the wrong shape) — into an already-written 400 response, returning `null` either way
 * so the route handler can bail with one `if (!fields) return;` instead of nesting its own
 * try/catch. Pulled out of the handler to stay under this repo's complexity ceiling, and because
 * this synchronous parse call must be caught here rather than left to the handler's own try/catch
 * further down: Express 4 does not catch a synchronous throw from an async handler outside a
 * try/catch (see the `getAuthedPrincipal` comment below) — an uncaught throw here would hang the
 * request instead of 400ing it.
 *
 * @complexity O(1).
 */
function parseUploadRequestFieldsOrRespond(
  req: Request,
  res: Response
): ReturnType<typeof parseUploadRequestFields> {
  let fields: ReturnType<typeof parseUploadRequestFields>;
  try {
    fields = parseUploadRequestFields(req.body);
  } catch (error) {
    sendValidationOrInternalError({ res, error });
    return null;
  }
  if (!fields) {
    res.status(400).json({ error: "filename, contentType, and dataBase64 are required" });
  }
  return fields;
}

/**
 * Decodes the upload's bytes and verifies their content type, throwing `MediaValidationError` for
 * an over-long document payload or invalid base64.
 *
 * @complexity O(n) in the encoded payload length.
 */
function decodeUploadPayload(
  { kind, filename, contentType, dataBase64 }: Pick<UploadRequestFields, "kind" | "filename" | "contentType" | "dataBase64">,
): { bytes: Uint8Array; contentType: string } {
  // Refuse document base64 inflation before allocation, then let the shared ingress owner
  // check actual bytes. Authorization precedes decoding, archive work, and storage I/O.
  if (kind === "document" && dataBase64.length > 4 * Math.ceil(MAX_DOCUMENT_BYTES / 3)) {
    throw new MediaValidationError({ message: "document exceeds the 50 MiB limit" });
  }
  // `decodeStrictBase64`, not `Buffer.from(x, "base64")`: the latter never throws (it skips
  // characters outside the alphabet instead of refusing them), so a bare try/catch around it can
  // never fire — see that function's own header.
  const bytes = decodeStrictBase64(dataBase64);
  if (!bytes) throw new MediaValidationError({ message: "dataBase64 is not valid base64" });
  // Trust sniffed bytes rather than the client label. HTML/unknown bytes are rejected;
  // uploadMedia sanitizes accepted SVG before hashing/storage.
  const verified = kind === "document" ? documentContentType({ filename }) : resolveUploadContentType({ bytes, declaredContentType: contentType });
  return { bytes, contentType: verified };
}

/** Slug allocation is a courtesy lookup before save. Concurrent uploads can choose the same free
 *  slug; the durable repo enforces uniqueness with `MediaConflictError` (409). Otherwise a validation
 *  failure is 400 and anything else a private 500.
 *  @complexity O(1). */
function sendUploadFailure({ res, error }: { res: Response; error: unknown }): void {
  if (error instanceof MediaConflictError) {
    res.status(409).json({ error: error.message });
    return;
  }
  sendValidationOrInternalError({ res, error });
}

/**
 * POST a new media upload. Gated by `media.upload` (SPEC-021 REQ-39/OQ-01, ADR-027 §7).
 *
 * Request body is JSON with base64-encoded bytes (`dataBase64`) rather than a
 * multipart/form-data stream — this repo has no multipart-parsing dependency
 * yet (no `multer` in `package.json`), and adding one is out of scope for this
 * walking skeleton. This is a real, disclosed simplification: a production
 * upload path should stream bytes (multipart or raw octet-stream), not
 * base64-inflate them through JSON. `express.json()`'s body-size limit was
 * bumped in `server/app.ts` to accommodate this (see that file's comment).
 */
export const registerAdminMediaUploadRoute: MediaRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/media", async (req, res) => {
    if (rejectForeignWorkspace({ req, res, workspaceId: deps.workspaceId })) return;

    const fields = parseUploadRequestFieldsOrRespond(req, res);
    if (!fields) return;
    const { kind, filename, alt, caption, credit } = fields;

    try {
      // Inside the try: requireAdminSession always sets res.locals.principal before this
      // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
      // outside try/catch (the request would otherwise hang instead of 500ing).
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeMediaOrRespond({ res, authorize: deps.authorize, params: {
        principalId: principal.id,
        permission: "media.upload",
        workspaceId: deps.workspaceId,
        entityType: "media",
      } });
      if (!authorized) return;

      const { bytes, contentType: verifiedContentType } = decodeUploadPayload(fields);

      const { media } = await uploadMedia({
        deps: {
          clock: deps.clock,
          idGen: deps.idGen,
          mediaRepo: deps.mediaRepo,
          blobRepo: deps.assetBlobRepo,
          renditionRepo: deps.assetRenditionRepo,
          blobStore: deps.blobStore,
          documentArchiveReader: createDocumentArchiveReader({}),
        },
        input: {
          workspaceId: deps.workspaceId,
          kind,
          bytes,
          filename,
          contentType: verifiedContentType,
          alt,
          caption,
          credit,
          createdByPrincipal: principal.id,
        },
      }, { maxUploadBytes: TOVU_MAX_UPLOAD_BYTES });

      // Only media uses the per-blob sniff cache; document type is its validated filename policy.
      // Record the sniffed type so the admin's type filter agrees with what `original.ts` serves
      // (it never trusts the upload-time string either). Written AFTER `uploadMedia` because the
      // blob row it updates is created there.
      if (kind === "media") await deps.mediaContentTypeStore.set({
        workspaceId: deps.workspaceId,
        sha256: media.source.sha256,
        contentType: verifiedContentType,
      });

      const family = verifiedContentType.split("/")[0];
      let uploadedKind: "document" | "image" | "audio" | "video" | "other";
      if (kind === "document") uploadedKind = "document";
      else if (family === "image" || family === "audio" || family === "video") uploadedKind = family;
      else uploadedKind = "other";
      captureMediaUploaded({ tracker: deps.tracker, actorId: principal.id, byteLength: bytes.byteLength,
        kind: uploadedKind, source: "admin" });
      res.status(201).json(await toStoredMediaResponse({ deps, media, contentType: verifiedContentType, byteLength: bytes.byteLength }));
    } catch (error) {
      sendUploadFailure({ res, error });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from 'express';
import { findMediaWhereUsed } from '#src/features/media/index';
import { getAuthedPrincipal } from '#src/server/inbound/admin-http/dev-auth';
import type { RouteDeps } from '#src/server/routes/types';

export type MediaWhereUsedDeps = Pick<RouteDeps, 'workspaceId' | 'authorize' | 'mediaRepo' | 'entryRefsRepo' | 'postRepo'>;
/** Read-only usage disclosure, sharing the media.read gate and existing workspace isolation. */
export function registerAdminMediaWhereUsedRoute({ app, deps }: { app: Express; deps: MediaWhereUsedDeps }, _optional: Record<string, never> = {}): void {
  app.get('/api/admin/v1/workspaces/:workspaceId/media/:mediaId/where-used', async (req, res) => {
    if (String(req.params.workspaceId ?? '') !== deps.workspaceId) { res.status(404).json({ error: 'workspace was not found' }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      const auth = await deps.authorize({ principalId: principal.id, permission: 'media.read', workspaceId: deps.workspaceId, entityType: 'media' });
      if (!auth.allowed) { res.status(403).json({ error: 'media.read is required', code: 'FORBIDDEN' }); return; }
      const id = String(req.params.mediaId ?? '');
      const media = await deps.mediaRepo.findById({ workspaceId: deps.workspaceId, id });
      if (!media) { res.status(404).json({ error: 'media was not found' }); return; }
      const whereUsed = await findMediaWhereUsed({ deps, input: { workspaceId: deps.workspaceId, mediaId: media.id, slug: media.slug } });
      res.json({ mediaId: media.id, whereUsed });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/media/where-used", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { trashMember, MemberConflictError, MemberNotFoundError, MemberValidationError } from "#src/features/members/index";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteRegistrar } from "#src/server/routes/types";
import type { MembersRouteDeps } from "./deps.js";

/** DELETE moves a member to Trash. The shared adapter revokes sessions and links in the same
 * transaction; only the existing Trash flows may restore or permanently delete it.
 * @complexity One permission check, one member read and the bound Trash operation.
 */
export const registerAdminMemberDeleteRoute: RouteRegistrar = (app, routeDeps) => {
  const deps = routeDeps as MembersRouteDeps;
  app.delete("/api/admin/v1/workspaces/:workspaceId/members/:memberId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" }); return;
    }
    const memberId = String(req.params.memberId ?? "");
    try {
      const principal = getAuthedPrincipal(res);
      if (!await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "member.manage",
        workspaceId: deps.workspaceId, entityType: "member", entityId: memberId })) return;
      res.json(await trashMember({ workspaceId: deps.workspaceId, memberId, actor: { principalId: principal.id } },
        { members: deps.memberRepo, remove: deps.removeMember, clock: deps.clock }));
    } catch (error) {
      if (error instanceof MemberNotFoundError) { res.status(404).json({ error: error.message }); return; }
      if (error instanceof MemberConflictError) { res.status(409).json({ error: error.message }); return; }
      if (error instanceof MemberValidationError) { res.status(400).json({ error: error.message }); return; }
      sendAdminFailure({ res, error }, { operation: "routes/members/delete", code: "INTERNAL_ERROR" });
    }
  });
};

