/** Reads and validates the `?afterId=`/`?limit=` keyset-pagination pair in one place — an invalid
 *  or missing `limit` falls through to the repo port's own `DEFAULT_LIST_LIMIT` (`undefined`, not
 *  an error; this list has no required pagination params). @complexity O(1). */
function parseMembersListQuery(query: Request["query"]): { afterId: string | undefined; limit: number | undefined } {
  const afterId = typeof query.afterId === "string" ? query.afterId : undefined;
  const rawLimit = typeof query.limit === "string" ? Number(query.limit) : undefined;
  const limit = rawLimit !== undefined && Number.isFinite(rawLimit) && rawLimit > 0 ? rawLimit : undefined;
  return { afterId, limit };
}

/**
 * GET members — list a workspace's members for the admin UI (all statuses,
 * `pending`/`active`/`disabled` included; mirrors `listAdminPosts`'s "admin
 * sees everything" behavior in `registerAdminPostListRoute`).
 *
 * No dedicated `listAdminMembers` business-logic function exists in
 * `src/members` (that library exports `MembersWriteService` mutations only,
 * no read-side wrappers) — this route calls `MemberRepoPort.list` directly.
 * That port is already keyset-paginated and bounded (`DEFAULT_LIST_LIMIT =
 * 100` in `repo.memory.ts`), so an `afterId`/`limit` query pair is passed
 * through rather than re-implementing a cap here.
 *
 * ADR-PIPE-013 §1 (FEAT-013 Phase 1): previously ran behind session auth only
 * — no per-action `authorize()` call, unlike `disable.ts`. Closes that live
 * authorization gap by requiring `member.manage`, copying `disable.ts`'s
 * exact call shape (workspace-id 404 check first, then authorize).
 */
export const registerAdminMemberListRoute: RouteRegistrar = (app, routeDeps) => {
  const deps = routeDeps as MembersRouteDeps;

  app.get("/api/admin/v1/workspaces/:workspaceId/members", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);

      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "member.manage",
        workspaceId: deps.workspaceId,
        entityType: "member",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'member.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "member.manage", reason: authResult.reason },
        });
        return;
      }

      const members: MemberRecord[] = await deps.memberRepo.list({
        workspaceId: deps.workspaceId,
        ...parseMembersListQuery(req.query),
      });
      res.json({ members: members.map(toAdminMemberResponse) });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/members/list", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { SenderIdentityNotConfiguredError } from "#src/platform/mail/index";
import type { Response } from "express";

import { MemberSignInUnavailableError, MemberValidationError, requestSignInLink } from "#src/features/members/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteRegistrar } from "#src/server/routes/types";
import { toMembersWriteServiceDeps, type MembersRouteDeps } from "./deps.js";

/**
 * Parses the body and checks the per-email rate limit — ADR-PIPE-013 Decision §2-3 / INV-NEW-03:
 * the shared MAGIC_LINK_PER_EMAIL limiter (same instance the public sign-in route consults, C-015),
 * which the caller must only invoke strictly AFTER `authorize()` succeeds (an unauthorized caller
 * must never reach, and therefore never consume, this check). Writes the 429 response itself on a
 * denial and returns `null`, so the caller can `return` without re-branching.
 *
 * @complexity O(1).
 */
async function parseMagicLinkRequest(
  deps: Pick<MembersRouteDeps, "magicLinkPerEmailLimiter">,
  res: Response,
  rawBody: unknown
): Promise<{ rawEmail: string; redirectPath: string | undefined } | null> {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const rawEmail = String(body.email ?? "");
  const emailKey = rawEmail.trim().toLowerCase();
  // Empty emails are validation errors, never missing-key limiter buckets.
  if (!emailKey) throw new MemberValidationError(`'${rawEmail}' is not a valid email address`);
  const rateLimitResult = await deps.magicLinkPerEmailLimiter.check({ key: emailKey });
  if (!rateLimitResult.allowed) {
    res.setHeader("Retry-After", String(rateLimitResult.retryAfterSeconds));
    res.status(429).json({
      error: "too many sign-in requests for this email",
      code: "RATE_LIMIT_EXCEEDED",
      details: { retryAfterSeconds: rateLimitResult.retryAfterSeconds },
    });
    return null;
  }
  return { rawEmail, redirectPath: body.redirectPath ? String(body.redirectPath) : undefined };
}

/**
 * POST request a passwordless sign-in link for a member email (operator-
 * triggered resend, e.g. from an admin member-detail screen's "resend
 * sign-in link" action).
 *
 * Returns actual mailer acceptance to the authorized operator, including false for skipped or
 * failed sends. Site-wide setup failures return 503. Public callers use the separate generic
 * accepted response so neither membership nor per-address delivery failures can be enumerated.
 * A malformed email reaches the 400 branch below.
 *
 * ADR-PIPE-013 §1 (FEAT-013 Phase 1): previously ran behind session auth only
 * — no per-action `authorize()` call, unlike `disable.ts`. Closes that live
 * authorization gap by requiring `member.manage`, copying `disable.ts`'s
 * exact call shape. INV-NEW-03 (Phase 2, T022, now enforced below):
 * the shared `MAGIC_LINK_PER_EMAIL` rate-limit check must land strictly
 * *after* this `authorize()` call, never before, so an unauthorized caller
 * cannot consume rate-limit budget for a target email as a side channel.
 */
export const registerAdminMemberRequestMagicLinkRoute: RouteRegistrar = (app, routeDeps) => {
  const deps = routeDeps as MembersRouteDeps;

  app.post("/api/admin/v1/workspaces/:workspaceId/members/request-magic-link", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);

      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "member.manage",
        workspaceId: deps.workspaceId,
        entityType: "member",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'member.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "member.manage", reason: authResult.reason },
        });
        return;
      }

      const parsed = await parseMagicLinkRequest(deps, res, req.body);
      if (!parsed) {
        return;
      }

      const result = await requestSignInLink({
        deps: toMembersWriteServiceDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          email: parsed.rawEmail,
          redirectPath: parsed.redirectPath,
        },
      });

      res.json(result);
    } catch (err) {
      sendMagicLinkError({ res, err });
    }
  });
};

function sendMagicLinkError({ res, err }: { res: Response; err: unknown }, _optional = {}): void {
  if (err instanceof MemberSignInUnavailableError || err instanceof SenderIdentityNotConfiguredError) {
    res.status(503).json({ error: err instanceof SenderIdentityNotConfiguredError ? "Member sign-in is unavailable: email is not set up for this site." : err.message, code: "MEMBER_SIGN_IN_UNAVAILABLE" });
    return;
  }
  if (err instanceof MemberValidationError) {
    res.status(400).json({ error: err.message });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/members/request-magic-link", code: "INTERNAL_ERROR" });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";
import { assignLocation, MenuConflictError, MenuNotFoundError, MenuVersionConflictError } from "#src/features/navigation/index";
import { toAdminAssignLocationResponse, type MenuRouteRegistrar } from "#src/server/inbound/admin-http/http/menus";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { entityNotLiveResponse } from "#src/server/inbound/admin-http/http/entity-not-live";

/** Reads+trims `locationKey` off the body in one place; `null` means missing or blank.
 *  @complexity O(1). */
function parseLocationKey(rawBody: unknown): string | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const locationKey = String(body.locationKey ?? "").trim();
  return locationKey || null;
}

/** Maps assignment failures to the existing admin response envelope. @complexity O(1). */
function sendAssignLocationError(
  { res, err }: { res: Response; err: unknown },
  _options: Record<string, never> = {},
): void {
  const live = entityNotLiveResponse(err);
  if (live) {
    res.status(live.status).json(live.body);
    return;
  }
  if (err instanceof MenuNotFoundError) {
    res.status(404).json({ error: err.message });
    return;
  }
  // Either menu's save can lose its compare-and-set to another editor (the whole assignment rolled
  // back); same `VERSION_CONFLICT` code as update-tree, so the admin shows its "reload" copy.
  if (err instanceof MenuVersionConflictError) {
    res.status(409).json({ error: err.message, code: "VERSION_CONFLICT" });
    return;
  }
  if (err instanceof MenuConflictError) {
    res.status(409).json({ error: err.message });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/menus/assign-location", code: "INTERNAL_ERROR" });
}

/**
 * POST assign a menu to a theme location (ADR-029 `assignLocation`).
 *
 * Last-writer-wins: if the location was already bound to a different menu,
 * that menu is displaced (its `locations` field loses the key) and the
 * response includes it as `displacedMenu` so the UI can show what changed.
 *
 * Gated by `admin.menus.assign` (ADR-PIPE-012 D-1/D-2/D-9 — renamed/split from the old flat
 * navigation permission), checked directly via `authorize()` (same pattern as `create.ts`).
 */
export const registerAdminMenuAssignLocationRoute: MenuRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/menus/:menuId/locations", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const locationKey = parseLocationKey(req.body);
    if (!locationKey) {
      res.status(400).json({ error: "locationKey is required" });
      return;
    }

    const menuId = String(req.params.menuId ?? "");

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.menus.assign",
        workspaceId: deps.workspaceId,
        entityType: "menu",
        entityId: menuId,
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.menus.assign' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.menus.assign", reason: authResult.reason },
        });
        return;
      }

      const { menu, binding, displacedMenu } = await assignLocation({
        deps: {
          repo: deps.menuRepo,
          bindingRepo: deps.navLocationBindingRepo,
          clock: deps.clock,
          idGen: deps.idGen,
          outbox: deps.outbox,
        },
        input: {
          workspaceId: deps.workspaceId,
          menuId,
          locationKey,
        },
      });

      res.json(toAdminAssignLocationResponse({ menu, binding, displacedMenu }));
    } catch (err) {
      sendAssignLocationError({ res, err });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { createMenu, MenuConflictError, MenuValidationError } from "#src/features/navigation/index";
import type { MenuHtmlAuthoring, NavItemNode } from "#src/features/navigation/index";
import { authorizeMenuHtmlOrRespond, parseMenuHtmlAuthoring, toAdminMenuResponse, type MenuRouteRegistrar } from "#src/server/inbound/admin-http/http/menus";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

/** This route's three body fields, read off an untyped body in one place, or `null` if a present
 *  `items` isn't an array.
 *  @complexity O(1). */
function parseMenuCreateBody(rawBody: unknown): { title: string; slug: string; items: NavItemNode[] | undefined; authoring: MenuHtmlAuthoring } | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  if (body.items !== undefined && !Array.isArray(body.items)) {
    return null;
  }
  return {
    title: String(body.title ?? ""),
    slug: String(body.slug ?? ""),
    items: body.items as NavItemNode[] | undefined,
    authoring: parseMenuHtmlAuthoring(body),
  };
}

/**
 * POST a new menu (ADR-029 `createMenu`).
 *
 * `items` is optional (defaults to an empty menu); when supplied it is
 * validated end-to-end by `validateAndCloneTree` inside `createMenu` (id
 * uniqueness, depth/count bounds, target-kind allowlist, `url` scheme
 * denylist) — this route only rejects a non-array `items` before handing off.
 *
 * Gated by `admin.menus.create` (ADR-PIPE-012 D-1/D-2/D-9 — renamed/split from the old flat navigation permission),
 * checked directly via `authorize()` — mirrors `members/disable.ts`'s pattern since menu mutations
 * are a direct feature call, not routed through the SPEC-001 command gateway (see `update-tree.ts`'s
 * doc for why).
 */
export const registerAdminMenuCreateRoute: MenuRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/menus", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const parsedBody = parseMenuCreateBody(req.body);
    if (!parsedBody) {
      res.status(400).json({ error: "items must be an array" });
      return;
    }

    try {
      // Inside the try: requireAdminSession always sets res.locals.principal before this
      // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
      // outside try/catch (the request would otherwise hang instead of 500ing).
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.menus.create",
        workspaceId: deps.workspaceId,
        entityType: "menu",
      });
      if (!authorized) return;
      if (!(await authorizeMenuHtmlOrRespond(res, deps, { principalId: principal.id, authoring: parsedBody.authoring }))) return;

      const { menu } = await createMenu({
        deps: { repo: deps.menuRepo, clock: deps.clock, idGen: deps.idGen, outbox: deps.outbox },
        input: {
          workspaceId: deps.workspaceId,
          title: parsedBody.title,
          slug: parsedBody.slug,
          items: parsedBody.items,
          ...parsedBody.authoring,
        },
      });

      res.status(201).json(toAdminMenuResponse(menu));
    } catch (err) {
      if (err instanceof MenuValidationError) {
        res.status(400).json({ error: err.message });
        return;
      }
      if (err instanceof MenuConflictError) {
        res.status(409).json({ error: err.message });
        return;
      }
      sendAdminFailure({ res, error: err }, { operation: "routes/menus/create", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { MenuConflictError, MenuNotFoundError } from "#src/features/navigation/index";
import { trashMenu } from "#src/features/navigation/index";
import { toAdminTrashMenuResponse, type MenuRouteRegistrar } from "#src/server/inbound/admin-http/http/menus";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

/**
 * DELETE a menu — moves it to the Trash (ADR-029 §6 / trash pipeline). No more force/purge ladder:
 * purging (permanent deletion) happens only through the generic Trash surface, which already
 * unassigns a bound menu's locations at purge time (T1's registry `purgeFirst`). A second call
 * against an already-trashed menu 404s like any other not-found — there is no separate
 * `admin.menus.delete.force` permission or `?force=true` behavior left to gate.
 */
export const registerAdminMenuDeleteRoute: MenuRouteRegistrar = (app, deps) => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/menus/:menuId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    const menuId = String(req.params.menuId ?? "");
    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.menus.delete",
        workspaceId: deps.workspaceId,
        entityType: "menu",
        entityId: menuId,
      });
      if (!authorized) return;

      const trashed = await trashMenu(
        { workspaceId: deps.workspaceId, menuId, actor: { principalId: principal.id } },
        { menuRepo: deps.menuRepo, remove: deps.removeMenu, clock: deps.clock }
      );
      res.json(toAdminTrashMenuResponse(trashed));
    } catch (err) {
      if (err instanceof MenuNotFoundError) { res.status(404).json({ error: err.message }); return; }
      if (err instanceof MenuConflictError) { res.status(409).json({ error: err.message }); return; }
      sendAdminFailure({ res, error: err }, { operation: "routes/menus/delete", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { toAdminMenuResponse, type MenuRouteRegistrar } from "#src/server/inbound/admin-http/http/menus";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

/**
 * GET one menu by id, including its full item tree (ADR-029).
 *
 * Gated by `admin.menus.read` (ADR-PIPE-012 D-1/D-2/D-9 — renamed/split from
 * the old flat navigation permission).
 */
export const registerAdminMenuGetRoute: MenuRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/menus/:menuId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const menuId = String(req.params.menuId ?? "");

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.menus.read",
        workspaceId: deps.workspaceId,
        entityType: "menu",
        entityId: menuId,
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.menus.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.menus.read", reason: authResult.reason },
        });
        return;
      }

      // Admin URLs use the slug when one resolves (readable-slugs S6b, 2026-09-23) — this route
      // accepts either so an old id-based bookmark/link keeps working. Slug first, id second: same
      // precedent and rationale as posts' `getAdminPostByIdOrSlug` (`features/post/post.ts`) — the
      // slug is the handle a human typed into the URL; the id is the fallback for a stale link.
      const bySlug = await deps.menuRepo.findBySlug({ workspaceId: deps.workspaceId, slug: menuId.trim().toLowerCase() });
      const menu = bySlug ?? (await deps.menuRepo.findById({ workspaceId: deps.workspaceId, id: menuId }));
      if (!menu) {
        res.status(404).json({ error: `menu '${menuId}' was not found` });
        return;
      }
      res.json(toAdminMenuResponse(menu));
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/menus/get-by-id", code: "INTERNAL_ERROR" });
    }
  });
};

