/** Maps this route's thrown error types onto the admin error envelope.
 *  @complexity O(1). */
function sendPageCreateError(res: Response, err: unknown): void {
  if (sendPluginHookFailedError(res, err)) return;
  if (err instanceof ForbiddenError) {
    res.status(403).json({
      error: err.message,
      code: "FORBIDDEN",
      details: { permission: err.permission, reason: err.reason },
    });
    return;
  }

  if (err instanceof DuplicateCommandError) {
    res.status(409).json({ error: err.message, code: "DUPLICATE_COMMAND", changeSetId: err.changeSetId });
    return;
  }

  if (err instanceof PostValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }

  if (err instanceof PostConflictError) {
    res.status(409).json({ error: err.message, code: "SLUG_CONFLICT" });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/pages/create", code: "INTERNAL_ERROR" });
}

/**
 * POST a new blank draft page — mirrors `posts/create.ts` (same command-gateway
 * wiring, same `post` table, same optional `slug`/`bodyJson`/`status` forwarding
 * and `VALIDATION_ERROR`/`SLUG_CONFLICT` error mapping) but sets `kind: "page"`
 * so it surfaces on the Pages admin list instead of Posts.
 *
 * `rejectOversizedJsonBody` (Security review SEC-snapshot-and-post-create-2026-07-28, Finding 1)
 * enforces api.spec.md §4's documented 1 MiB route-layer body cap ahead of the handler, so an
 * oversized request 413s before `createPost`/the command gateway ever runs — mirrors
 * `posts/create.ts`'s identical wiring.
 */
export const registerAdminPageCreateRoute: ContentRouteRegistrar = (app, deps) => {
  app.post(
    "/api/admin/v1/workspaces/:workspaceId/pages",
    rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }),
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const idempotencyKey = req.get("Idempotency-Key") || undefined;
      const pageId = deps.idGen.newId();

      try {
        // Inside the try: requireAdminSession always sets res.locals.principal before this
        // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
        // outside try/catch (the request would otherwise hang instead of 500ing).
        const principal = getAuthedPrincipal(res);
        const { result } = await executeCommand({
          deps: {
            clock: deps.clock,
            idGen: deps.idGen,
            changeSets: deps.changeSets,
            outbox: deps.outbox,
            authorize: deps.authorize,
          },
          command: {
            workspaceId: deps.workspaceId,
            actor: { id: principal.id, kind: "user" },
            summary: "Create page",
            idempotencyKey,
            permission: "content.write",
          },
          mutation: {
            entityType: "post",
            entityId: pageId,
            operation: "create",
            captureInverse: async () => null,
            execute: () =>
              createPost({
                deps: { repo: deps.postRepo, clock: deps.clock, beforeSaveHook: deps.pluginBeforeSaveHook, outbox: deps.outbox },
                input: {
                  workspaceId: deps.workspaceId,
                  id: pageId,
                  title: String(req.body?.title ?? ""),
                  kind: "page",
                  slug: req.body?.slug !== undefined ? String(req.body.slug) : undefined,
                  bodyJson: req.body?.bodyJson,
                  status: req.body?.status,
                  actorId: principal.id,
                  analyticsSource: "admin",
                },
              }),
            captureEntityVersion: ({ result }) => result.post.version,
          },
        });

        // A page created directly as `status: "published"` now enqueues `entry.published`
        // (`createPost`'s own `deps.outbox` doc) — drained here so SEO's sitemap-cache
        // invalidation subscriber actually sees it, mirroring `posts/create.ts`'s identical fix.
        await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

        res.status(201).json(toAdminPostResponse(result.post));
      } catch (err) {
        sendPageCreateError(res, err);
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { DuplicateCommandError, ForbiddenError, executeCommand } from "@jini-ai/cms/core";
import { processOutbox } from "#src/contracts/core/events/index";
import {
  PostConflictError,
  PostNotFoundError,
  deletePost,
  restorePostForward,
  type PostRecord,
} from "#src/features/post/index";
import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteRegistrar } from "../content/deps.js";

/**
 * DELETE page — the pages half of the delete pair, a separate file from `posts/delete.ts` for the
 * same reason `pages/update.ts` is separate from `posts/update.ts`: posts and pages are separate
 * URL surfaces with genuinely different kind-guard behavior, and this domain's existing
 * create/get/update routes are all already split that way. Matching that split is the convention;
 * collapsing them into one shared file would be the deviation.
 *
 * SOFT delete, revertible through the change-set gateway — see `posts/delete.ts`'s header for the
 * full rationale, which applies identically here.
 *
 * Kind guard (api.spec.md §6/§7 — "kind-mismatch 404s are deliberately indistinguishable from
 * not-found"): `deletePost` itself is kind-blind, exactly like `updatePost`, so this route's own
 * `captureInverse` fetches the row and throws `PostNotFoundError` when it is missing OR its kind
 * isn't `"page"`. A `kind: "post"` id DELETEd through `/pages/:pageId` 404s instead of silently
 * trashing a post via the pages surface. `posts/delete.ts` carries no such guard, mirroring
 * `posts/update.ts`'s own legacy kind-blindness rather than inventing a stricter rule on one
 * surface than its update twin has.
 */
export const registerAdminPageDeleteRoute: ContentRouteRegistrar = (app, deps) => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/pages/:pageId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pageId = String(req.params.pageId ?? "");
    const idempotencyKey = req.get("Idempotency-Key") || undefined;

    let priorPost: PostRecord;

    try {
      const principal = getAuthedPrincipal(res);
      const { result } = await executeCommand({
        deps: {
          clock: deps.clock,
          idGen: deps.idGen,
          changeSets: deps.changeSets,
          outbox: deps.outbox,
          authorize: deps.authorize,
        },
        command: {
          workspaceId: deps.workspaceId,
          actor: { id: principal.id, kind: "user" },
          summary: `Delete page ${pageId}`,
          idempotencyKey,
          permission: "content.write",
        },
        mutation: {
          entityType: "post",
          entityId: pageId,
          operation: "delete",
          captureInverse: async () => {
            const existing = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id: pageId });
            if (existing?.kind !== "page") {
              // Missing id and kind-mismatch both 404 identically (no existence leak, api.spec.md §7).
              throw new PostNotFoundError(`page '${pageId}' was not found`);
            }
            priorPost = existing;
            return { deletedAt: null };
          },
          execute: () =>
            deletePost({
              deps: { repo: deps.postRepo, clock: deps.clock, outbox: deps.outbox, remove: deps.removePost },
              input: { workspaceId: deps.workspaceId, id: pageId, actorId: principal.id },
            }),
          captureEntityVersion: ({ result }) => result.post.version,
          rollback: async () => {
            // See `posts/delete.ts`'s identical note: `forgetRemoved` drops the Trash index row
            // `deletePost` wrote, inside the same transaction as the restore.
            await restorePostForward({
              deps: {
                repo: deps.postRepo,
                clock: deps.clock,
                outbox: deps.outbox,
                forgetRemoved: deps.forgetRemovedPost,
              },
              input: { prior: priorPost, actorId: principal.id },
            });
          },
        },
      });

      await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

      res.json(toAdminPostResponse(result.post));
    } catch (err) {
      if (err instanceof ForbiddenError) {
        res.status(403).json({
          error: err.message,
          code: "FORBIDDEN",
          details: { permission: err.permission, reason: err.reason },
        });
        return;
      }

      if (err instanceof DuplicateCommandError) {
        res.status(409).json({
          error: err.message,
          code: "DUPLICATE_COMMAND",
          changeSetId: err.changeSetId,
        });
        return;
      }

      if (err instanceof PostNotFoundError) {
        res.status(404).json({ error: err.message, code: "ENTRY_NOT_FOUND" });
        return;
      }

      // 2026-09-20: `deletePost` can now raise this when the row's version moved between its read
      // and its write — the same optimistic-concurrency rejection `pages/update.ts` maps onto 409.
      if (err instanceof PostConflictError) {
        res.status(409).json({ error: err.message, code: "ENTRY_CONFLICT" });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/pages/delete", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { getAdminPostByIdOrSlug, PostNotFoundError } from "#src/features/post/index";
import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteRegistrar } from "../content/deps.js";
import { markersOfType } from "@jini-ai/cms/widgets/markers";
import type { PluginExportCatalogRow, PluginExportRuntime } from "#src/features/agent-plugins/exports/runtime";

/** Only describe exports already authored on this page; catalog discovery still belongs to
 * plugins_list. A failed catalog is unavailable, never a broken page editor or a ready button.
 * @complexity O(markers + exports), one catalog load; no templates or secret values returned.
 */
async function pagePluginEmbeds(required: { html: string; workspaceId: string; runtime: PluginExportRuntime | undefined }, _options = {}) {
  if (!required.runtime) return [];
  const markers = markersOfType({ html: required.html, type: "plugin" });
  if (!markers.length) return [];
  const catalog = await required.runtime.catalog({ workspaceId: required.workspaceId }).catch(() => new Map<string, readonly PluginExportCatalogRow[]>());
  const rows = new Map<string, PluginExportCatalogRow>([...catalog.values()].flat().map(row => [JSON.stringify([row.plugin, row.component]), row]));
  return markers.map(({ config }) => {
    const plugin = typeof config.plugin === "string" ? config.plugin : "";
    const component = typeof config.component === "string" ? config.component : "";
    const row = rows.get(JSON.stringify([plugin, component]));
    return { plugin, component, ...(row?.displayName ? { displayName: row.displayName } : {}), availability: row?.availability ?? "PLUGIN_UNAVAILABLE" };
  });
}

/**
 * GET one page (SPEC-002 api.spec.md `PAGE_GET`) — `getAdminPostByIdOrSlug` (same
 * `post` table, same repo `posts/get-by-id.ts` uses, but id-or-slug rather than
 * id-only: the Pages editor URL is slug-based, and this keeps an old id-based
 * bookmark resolving too), plus a `kind === "page"` guard: api.spec.md §6
 * documents `PAGE_GET`'s 404 as "unknown workspace / `ENTRY_NOT_FOUND` (incl.
 * kind mismatch)" — a `kind: "post"` row fetched through `/pages/:pageId` must
 * 404 exactly like an unknown id/slug, not leak the post's existence through
 * this route family ("kind-mismatch 404s are deliberately indistinguishable
 * from not-found", api.spec.md §7).
 *
 * Gated by `content.read` (mirrors `pages/list.ts`'s identical 2026-07-16 authz
 * sweep fix, and `posts/get-by-id.ts`'s own doc note).
 *
 * `code: "ENTRY_NOT_FOUND"` is included on both 404 branches — unlike the legacy
 * `posts/get-by-id.ts` (message-only 404, a modified not new endpoint),
 * errors.spec.md §1/§4 requires `code` on every new endpoint's error response,
 * and names `ENTRY_NOT_FOUND` as exactly this route's not-found/kind-mismatch code.
 */
export const registerAdminPageGetRoute: ContentRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/pages/:pageId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    // Route param kept as `pageId` (external URL shape, untouched) — the value it carries is
    // either the row's id or its slug, resolved below by `getAdminPostByIdOrSlug`.
    const idOrSlug = String(req.params.pageId ?? "");

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "content.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const result = await getAdminPostByIdOrSlug({
        deps: { repo: deps.postRepo },
        input: { workspaceId: deps.workspaceId, idOrSlug },
      });

      if (result.post.kind !== "page") {
        // Kind mismatch — treated identically to not-found (api.spec.md §6/§7).
        res.status(404).json({ error: `page '${idOrSlug}' was not found`, code: "ENTRY_NOT_FOUND" });
        return;
      }

      const response = toAdminPostResponse(result.post);
      const pluginEmbeds = await pagePluginEmbeds({ html: result.post.bodyHtml ?? "", workspaceId: deps.workspaceId, runtime: deps.pluginExports });
      res.json(pluginEmbeds.length ? { ...response, pluginEmbeds } : response);
    } catch (err) {
      if (err instanceof PostNotFoundError) {
        res.status(404).json({ error: err.message, code: "ENTRY_NOT_FOUND" });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/pages/get-by-id", code: "INTERNAL_ERROR" });
    }
  });
};

