import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { PluginEmbedValidationError } from "#src/features/agent-plugins/exports/diagnostics";
import type { Response } from "express";

import {
  DEFAULT_PAGE_SKELETON,
  PAGES_EDIT_HTML_PERMISSION,
  PageConcurrentEditError,
  PageKindMismatchError,
  PageNotFoundError,
} from "#src/features/pages/index";
import { entityNotLiveResponse } from "#src/server/inbound/admin-http/http/entity-not-live";
import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import {
  CONTENT_ENTRY_MAX_BODY_BYTES,
  rejectOversizedJsonBody,
} from "#src/server/inbound/shared/body-size-limit";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteDeps, ContentRouteRegistrar } from "../content/deps.js";

/**
 * The permission this route checks. Named once so the gate, the 403 body, and the agent-tool path to
 * the same store all read from the same place.
 *
 * `pages.edit_html` (SPEC-047 REQ-9) as of 2026-09-05, replacing the interim `content.write` — see
 * this file's Authorization section and `features/pages/permissions.ts` for the grant that makes it
 * a real, held permission rather than a string no policy row spells.
 */
const REQUIRED_PERMISSION = PAGES_EDIT_HTML_PERMISSION;

/**
 * Run the permission gate, sending the 403 itself when it fails.
 *
 * Returns whether the caller may PROCEED — named that way round because the call site reads
 * `if (!(await allowedToWrite(...))) return;`, and a helper called `denied` would invert the sense of
 * the branch every reader has to hold. Extracted rather than inlined so the handler stays inside the
 * 9/9 complexity ceiling this repo gates new code on.
 *
 * Mirrors `pages/list.ts`'s 403 body verbatim (`error`/`code`/`details`) — the admin UI keys off
 * `code`, and a second spelling of the same refusal would be a silent client-side bug.
 */
async function allowedToWrite(deps: ContentRouteDeps, res: Response): Promise<boolean> {
  const principal = getAuthedPrincipal(res);
  return authorizeOrRespond(res, deps.authorize, {
    principalId: principal.id,
    permission: REQUIRED_PERMISSION,
    workspaceId: deps.workspaceId,
  });
}

/** Map a store-layer failure onto its HTTP shape. Extracted from the handler's `catch` for the same
 * complexity reason as {@link allowedToWrite}; behavior is unchanged except for the new
 * `entityNotLiveResponse` arm (S5, web-high fix plan 2026-09-24). */
function sendStoreError(res: Response, err: unknown): void {
  if (err instanceof PluginEmbedValidationError) {
    res.status(400).json({ error: err.message, code: err.code });
    return;
  }
  const live = entityNotLiveResponse(err);
  if (live) {
    res.status(live.status).json(live.body);
    return;
  }
  if (err instanceof PageKindMismatchError) {
    res.status(400).json({ error: err.message, code: "KIND_MISMATCH" });
    return;
  }
  if (err instanceof PageNotFoundError) {
    res.status(404).json({ error: err.message, code: "ENTRY_NOT_FOUND" });
    return;
  }
  if (err instanceof PageConcurrentEditError) {
    res.status(409).json({ error: err.message, code: "CONCURRENT_EDIT" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/pages/update-html", code: "INTERNAL_ERROR" });
}

/** Attach safe editor warnings without changing ordinary saves' response shape. */
function withEmbedWarnings(required: { post: ReturnType<typeof toAdminPostResponse>; store: import("#src/features/pages/index").PagesHtmlDocumentStorePort }, _options = {}) {
  const warnings = required.store.embedWarnings?.() ?? [];
  return warnings.length ? { ...required.post, warnings } : required.post;
}

/**
 * PUT the bespoke-HTML body of a Page (SPEC-047/ADR-056 REQ-4) —
 * `PUT /api/admin/v1/workspaces/:workspaceId/pages/:pageId/html`, body `{ html: string }`.
 *
 * ## Why this is a separate route from `pages/update.ts`, not a field on it
 *
 * `pages/update.ts` writes title/slug/status through `updatePost`, which by construction can only
 * ever produce `body_format: "doc"` rows (`post.ts`'s `resolveBodyFields`, ADR-056 CIC-3). The
 * bespoke-HTML body is written by `PagesHtmlDocumentStore` and nothing else. Folding the html body
 * into the metadata route would put both writers behind one handler and make the invariant a
 * convention a future edit can quietly break; keeping them apart is what makes "exactly one writer
 * of html rows" a structural fact.
 *
 * It also means the two have genuinely different concurrency semantics, and only one of them can
 * offer compare-and-set: the store conditions its `UPDATE` on the `version` captured at `read()`
 * (CIC-1), so a second admin's write lands as a 409 rather than silently discarding the first's
 * edit. `updatePost` has no such guarantee and does not need one for a title.
 *
 * ## First write births the row
 *
 * `ensureHtmlFormat` runs before the write, converting a still-`"doc"` Page to `"html"` and seeding
 * it with the starter skeleton. It is idempotent, so this route is the same two calls whether the
 * page is brand new or has been edited fifty times. **The conversion drops `body_json`** — see that
 * method's own doc; today's only caller is the Pages editor acting on a freshly created Page, and
 * this route must not be offered on a Page carrying authored Tiptap content without a warning the
 * operator actually sees.
 *
 * ## Authorization
 *
 * Gated on `pages.edit_html` (SPEC-047 REQ-9), matching what the agent-tool path
 * (`features/pages/tool-registrations.ts`'s `pages_write_html`) checks. The two writers of
 * `"html"`-format rows are the only two, and they agree.
 *
 * History, because two earlier states of this comment are still quoted elsewhere. Until 2026-08-10
 * this route checked NOTHING — authenticated like every other admin route, but with no per-action
 * authz, so any principal who could reach the admin could write raw unsanitized HTML into the public
 * site. From 2026-08-10 it checked `content.write`, which closed that but not REQ-9's actual intent:
 * the built-in `editor` role holds `content.write`, so an `editor` could still author script into
 * every visitor's browser. This file said so plainly and recorded the gap as blocked on the
 * `@jini-ai/cms` repo, since `authorize()` matches literal `policy_permissions` rows and the built-in
 * role seed lives there.
 *
 * **That blocker was not real, and the gap is now closed.** The permission-migration registry is
 * exported to hosts for exactly this, and the boot-time fan-out that consumes it (`migrateDeprecatedPermission
 * Grants`, called from `features/identity/wiring.ts`) already lives in this repo. `features/pages/
 * permissions.ts` registers `theme.edit -> pages.edit_html`, so every principal already trusted with
 * raw theme source inherits raw-page-HTML authoring: `admin` and `owner` yes, `editor` and `viewer`
 * no. No library change was needed.
 *
 * **Capability removed, deliberately:** an `editor` can no longer write a Page's HTML through this
 * route or through `pages_write_html`. That is REQ-9's whole intent, and it is a real behavior
 * change — an editor keeps `content.write` and every ordinary content operation, and loses only
 * raw-HTML page authoring. `features/pages/__tests__/edit-html-permission.test.ts` pins both halves.
 *
 * ## Not yet done, deliberately, and tracked
 *
 * - **No rate limit** (REQ-10, `PAGES_GENERATION_PER_PRINCIPAL`). Matters once a model drives this
 *   endpoint rather than a human typing in a textarea.
 * - **No command-gateway/change-set record**, unlike `pages/update.ts`. Body writes are therefore
 *   absent from the mutation audit trail and are not revertible through `change-sets/revert`.
 * - **No HTML sanitization, and that is now a decision rather than a gap.** The stored markup is
 *   rendered into the public site unmodified. Sanitizing it would delete the feature — authoring
 *   arbitrary markup is what a Page IS — so the exposure is bounded by WHO may write it instead:
 *   the same principals already trusted with raw theme source, which is the same trust level the
 *   theme layer has always had. The admin preview iframes carry `sandbox` (admin
 *   `features/pages/rules.ts`'s `PAGE_PREVIEW_IFRAME_SANDBOX`, 2026-10-04) WITHOUT
 *   `allow-same-origin` since 2026-10-05, so preview script runs in an opaque origin and cannot reach
 *   the admin document or its APIs; that constant's doc says why. The published page is not sandboxed. A holder
 *   of `pages.edit_html` can still put script on the public site, and that is intended.
 */
export const registerAdminPageUpdateHtmlRoute: ContentRouteRegistrar = (app, deps) => {
  app.put(
    "/api/admin/v1/workspaces/:workspaceId/pages/:pageId/html",
    rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }),
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      try {
        // Authorization runs BEFORE body validation, so an unauthorized principal learns nothing
        // about what this endpoint accepts — same ordering `pages/list.ts` uses.
        if (!(await allowedToWrite(deps, res))) return;

        const pageId = String(req.params.pageId ?? "");
        const html = req.body?.html;

        if (typeof html !== "string") {
          res.status(400).json({ error: "'html' must be a string", code: "VALIDATION_ERROR" });
          return;
        }

        // S1 (fix plan 2026-09-24 row 14) — attributes this route's `post_revisions` rows to the
        // real authenticated principal, not the ledger's `SYSTEM_ACTOR_ID` fallback. Cheap: reads
        // `res.locals`, no second auth check (`allowedToWrite` above already ran one).
        const store = deps.pagesHtmlStore({ workspaceId: deps.workspaceId, postId: pageId, actorId: getAuthedPrincipal(res).id });

        // Validate the submitted HTML before the skeleton conversion can replace a doc body.
        // The store still owns the authoritative seed/write checks for every other caller.
        await deps.pluginExports?.validateHtml({ workspaceId: deps.workspaceId, html });
        // Idempotent: a no-op once the page is already html-format, so both the first write and
        // every later one take this identical path.
        await store.ensureHtmlFormat(DEFAULT_PAGE_SKELETON);
        // `read()` is what captures the version `write()` conditions its compare-and-set on — not a
        // wasted round trip. Dropping it would turn the write into the unconditional overwrite
        // CIC-1 exists to prevent.
        await store.read();
        await store.write(html);

        const updated = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id: pageId });
        if (!updated) {
          // The row was deleted between the write and this read. Nothing was lost that the caller
          // still owns, but it must not be told the write succeeded against a live page.
          res.status(404).json({ error: `page '${pageId}' was not found`, code: "ENTRY_NOT_FOUND" });
          return;
        }

        res.json(withEmbedWarnings({ post: toAdminPostResponse(updated), store }));
      } catch (err) {
        sendStoreError(res, err);
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { DuplicateCommandError, ForbiddenError, executeCommand } from "@jini-ai/cms/core";
import { processOutbox } from "#src/contracts/core/events/index";
import {
  parseExpectedVersion,
  PostConflictError,
  PostNotFoundError,
  PostValidationError,
  PostVersionConflictError,
  resolveFeaturedMediaIdForWrite,
  restorePostForward,
  updatePost,
  versionConflictEnvelope,
  type PostRecord,
  type UpdatePostInput,
} from "#src/features/post/index";
import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import {
  CONTENT_ENTRY_MAX_BODY_BYTES,
  rejectOversizedJsonBody,
} from "#src/server/inbound/shared/body-size-limit";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { sendPluginHookFailedError } from "#src/server/inbound/admin-http/http/plugin-hook-error";
import type { Response } from "express";
import type { ContentRouteRegistrar } from "../content/deps.js";

/** This route's five writable PUT fields, read off an untyped body in one place.
 *  @complexity O(1). */
function parsePageUpdateBody(
  rawBody: unknown
): Pick<UpdatePostInput, "title" | "slug" | "bodyJson" | "status" | "expectedVersion" | "publishAt" | "featuredMediaId"> {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    title: String(body.title ?? ""),
    slug: String(body.slug ?? ""),
    bodyJson: body.bodyJson as UpdatePostInput["bodyJson"],
    status: body.status as UpdatePostInput["status"],
    // Omitted ⇒ unchanged, `null` ⇒ cleared; validated by `updatePost` (2026-10-05).
    publishAt: body.publishAt as UpdatePostInput["publishAt"],
    featuredMediaId: body.featuredMediaId as UpdatePostInput["featuredMediaId"],
    // Validated, not cast — `features/post/expected-version.ts` owns this rule for every arm that
    // accepts a basis, so a mistyped `"3"` is a 400 here exactly as it is on `posts/update.ts`
    // rather than coercing to "no basis sent" and becoming an unguarded save by a client that
    // believes it is protected.
    expectedVersion: parseExpectedVersion(body.expectedVersion),
  };
}

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendPageUpdateError(res: Response, err: unknown): void {
  if (sendPluginHookFailedError(res, err)) return;
  if (err instanceof ForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof DuplicateCommandError) {
    res.status(409).json({ error: err.message, code: "DUPLICATE_COMMAND", changeSetId: err.changeSetId });
    return;
  }
  if (err instanceof PostValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  // BEFORE the `PostConflictError` branch below, because `PostVersionConflictError` extends it and
  // `instanceof` would otherwise be answered by the superclass first — a version conflict reported
  // as `SLUG_CONFLICT` tells the editor to fix a slug that is not the problem. Same ordering, and
  // the same shared envelope, as `posts/update.ts`: one definition of the `code` a client branches
  // on, across every arm that can produce this conflict.
  if (err instanceof PostVersionConflictError) {
    res.status(409).json(versionConflictEnvelope(err));
    return;
  }
  if (err instanceof PostConflictError) {
    res.status(409).json({ error: err.message, code: "SLUG_CONFLICT" });
    return;
  }
  if (err instanceof PostNotFoundError) {
    res.status(404).json({ error: err.message, code: "ENTRY_NOT_FOUND" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/pages/update", code: "INTERNAL_ERROR", message: "The page could not be saved." });
}

/**
 * PUT page (SPEC-002 api.spec.md `PAGE_UPDATE`) — routed through the command
 * gateway exactly like `posts/update.ts` (same gateway wiring, same
 * `updatePost` feature call, same success/error shapes; `kind` in the body is
 * ignored per AC-19, mirroring `updatePost`'s own kind-blind update contract).
 *
 * Kind guard (api.spec.md §6/§7 — "kind-mismatch 404s are deliberately
 * indistinguishable from not-found"): `updatePost` itself has no kind
 * awareness (a page and a post share the identical update contract, per
 * `PostKind`'s own doc: kind is fixed at creation, never mutated by an
 * update), so this route's own `captureInverse` fetches the existing record
 * and throws `PostNotFoundError` when it is missing OR its kind isn't
 * `"page"` — a `kind: "post"` id PUT through `/pages/:pageId` 404s instead of
 * silently updating a post via the pages surface.
 *
 * Error `code` (disclosed deviation from `posts/update.ts`, its mirror-source):
 * `posts/update.ts` handles `PostConflictError`/`PostNotFoundError` as
 * message-only (POST_UPDATE is a *modified*, legacy endpoint — errors.spec.md
 * §1 lets those keep `{error}` only); its `PostValidationError` branch has sent
 * `VALIDATION_ERROR` too since 2026-10-05. `PAGE_UPDATE` is a *new* endpoint, so
 * this route adds the required `code` on all three branches: `VALIDATION_ERROR`,
 * `SLUG_CONFLICT`, `ENTRY_NOT_FOUND`.
 *
 * Optimistic concurrency (2026-09-07, fable bugs audit C02) — this route forwards an optional
 * `expectedVersion` into `updatePost`, and maps the resulting conflict, exactly as
 * `posts/update.ts` has since `9c7d16bf`. It did not before: a Page and a Post are the same `posts`
 * row (this route's own "kind-blind update contract" note above), so the arm that shipped the guard
 * and the arm that did not were writing the same column under two different concurrency contracts,
 * and the Pages surface was the one silently applying stale writes. OBSERVABLE BEHAVIOR CHANGE,
 * deliberately, and identical in shape to the one the posts arm already made: a client that sends
 * `expectedVersion` and whose basis has been superseded now gets `409 VERSION_CONFLICT` where it
 * used to get `200` and erase the other operator's document; a client that sends a MALFORMED one
 * now gets `400 VALIDATION_ERROR` instead of having it silently ignored. A client that sends none
 * is unaffected — same last-write-wins behavior as before, pinned by a test.
 *
 * Still deliberately not forwarded: `templateChoice`/`overridesThemePage`. Pages have their own
 * theme-page flow (`update-html.ts`, `pages.ts`'s resolver); this note exists because the
 * "same `updatePost` feature call" claim above did not disclose those omissions and one of them
 * turned out to be a defect.
 *
 * `rejectOversizedJsonBody` (Security review SEC-snapshot-and-post-create-2026-07-28, Finding 1)
 * enforces api.spec.md §4's documented 1 MiB route-layer body cap ahead of the handler — the same
 * cap `pages/create.ts` applies, since §4 scopes it to the update endpoints too — so an oversized
 * request 413s before `updatePost`/the command gateway ever runs.
 */
export const registerAdminPageUpdateRoute: ContentRouteRegistrar = (app, deps) => {
  app.put(
    "/api/admin/v1/workspaces/:workspaceId/pages/:pageId",
    rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }),
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const pageId = String(req.params.pageId ?? "");
      const idempotencyKey = req.get("Idempotency-Key") || undefined;

      // Full pre-edit record, captured in captureInverse and reused verbatim by
      // rollback so the gateway's unit-of-work compensation (SPEC-001
      // REQ-01/EC-08/AC-17) restores the page exactly — version included — if the
      // change-set record fails to persist after updatePost applies.
      let priorPost: PostRecord | null = null;

      try {
        // Inside the try: requireAdminSession always sets res.locals.principal before this
        // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
        // outside try/catch (the request would otherwise hang instead of 500ing).
        const principal = getAuthedPrincipal(res);
        const { result } = await executeCommand({
          deps: {
            clock: deps.clock,
            idGen: deps.idGen,
            changeSets: deps.changeSets,
            outbox: deps.outbox,
            authorize: deps.authorize,
          },
          command: {
            workspaceId: deps.workspaceId,
            actor: { id: principal.id, kind: "user" },
            summary: `Update page ${pageId}`,
            idempotencyKey,
            permission: "content.write",
          },
          mutation: {
            entityType: "post",
            entityId: pageId,
            operation: "update",
            captureInverse: async () => {
              const existing = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id: pageId });
              if (existing?.kind !== "page") {
                // Missing id and kind-mismatch both 404 identically (no existence leak, api.spec.md §7).
                throw new PostNotFoundError(`page '${pageId}' was not found`);
              }
              priorPost = existing;
              return {
                title: priorPost.title,
                slug: priorPost.slug,
                bodyJson: priorPost.bodyJson,
                status: priorPost.status,
                // Scheduled publishing / featured image (2026-10-05) — `null` restores "none".
                publishAt: priorPost.publishAt ?? null,
                featuredMediaId: priorPost.featuredMediaId ?? null,
              };
            },
            execute: async () => {
              const body = parsePageUpdateBody(req.body);
              return updatePost({
                deps: {
                  repo: deps.postRepo,
                  clock: deps.clock,
                  outbox: deps.outbox,
                  beforeSaveHook: deps.pluginBeforeSaveHook,
                  slugChangeCapture: deps.slugChangeCapture,
                },
                input: {
                  workspaceId: deps.workspaceId,
                  id: pageId,
                  ...body,
                  // The same image check the `content_post_update` chat tool runs (2026-10-05): a video,
                  // unknown or trashed asset is a 400 here, and a media slug is stored as its id. Inside
                  // `execute`, after the gateway's `content.write` check, so an unauthorized caller
                  // cannot probe the media library through this field's error messages.
                  featuredMediaId: await resolveFeaturedMediaIdForWrite({
                    deps: { mediaRepo: deps.mediaRepo, mediaContentTypeStore: deps.mediaContentTypeStore },
                    input: { workspaceId: deps.workspaceId, featuredMediaId: body.featuredMediaId },
                  }),
                  actorId: principal.id,
                  analyticsSource: "admin",
                },
              });
            },
            captureEntityVersion: ({ result }) => result.post.version,
            rollback: async () => {
              if (!priorPost) return;
              await restorePostForward({
                deps: {
                  repo: deps.postRepo,
                  clock: deps.clock,
                  outbox: deps.outbox,
                  forgetRemoved: deps.forgetRemovedPost,
                },
                input: { prior: priorPost, actorId: principal.id },
              });
            },
          },
        });

        // SPEC-008 (ADR-PIPE-008 Decision §5) — drains the outbox so `updatePost`'s
        // `entry.published`/`entry.updated`/`entry.unpublished` event (if any) actually reaches
        // `bus.subscribe`d consumers, mirroring `posts/update.ts`'s identical inline `processOutbox` call.
        await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

        // Owner-action product event on the draft → published transition only (consent-gated port).
        res.json(toAdminPostResponse(result.post));
      } catch (err) {
        sendPageUpdateError(res, err);
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
/** Admin-only chart metadata and immutable bytes; installed/custom browser providers never enter this port. */
import type { Express } from "express";
import { CHART_TABLE_PROVIDER } from "@jini-ai/ui/charts";
import { ADMIN_ASSISTANT_PERMISSION } from "#src/assistant/index";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";
type ChartRouteDeps = Pick<RouteDeps, "workspaceId" | "authorize" | "pluginRuntimeReady" | "siteTitleReady" | "browserProviders" | "chartProviderSnapshot">;

/** Register the authenticated chart bootstrap and exact admitted-asset lookup.
 * No route reads files, accepts an asset URL, or grants browser admission itself.
 * @returns Void. Readiness/ledger failures produce the fixed admin 500 envelope.
 * @complexity O(p + a) per request for the admitted, compiled-in provider/asset list.
 * @example registerChartProviderRoutes({ app, deps });
 */
export function registerChartProviderRoutes(
  { app, deps }: { app: Express; deps: ChartRouteDeps }, _options: Record<string, never> = {},
): void {
  const base = "/api/admin/v1/workspaces/:workspaceId/chart-providers";
  // One guard covers metadata and assets, before either can disclose a provider or execute bytes.
  app.use(base, async (req, res, next) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" }); return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: ADMIN_ASSISTANT_PERMISSION, workspaceId: deps.workspaceId }))) return;
      await Promise.all([deps.pluginRuntimeReady, deps.siteTitleReady]);
      next();
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/plugins/chart-providers", code: "INTERNAL_ERROR" });
    }
  });
  app.get(base, async (_req, res) => {
    try {
      // A host without a chart snapshot has no provider to prefer: the admin draws the core table.
      const data = await deps.chartProviderSnapshot?.({}) ?? { generation: "core", siteProvider: CHART_TABLE_PROVIDER, providers: [] };
      res.set("Cache-Control", "no-store").json({ data });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/plugins/chart-providers", code: "INTERNAL_ERROR" });
    }
  });
  app.get(`${base}/assets/:pluginId/:version/:digest/:asset`, (req, res) => {
    const { pluginId, version, digest, asset: filename } = req.params;
    const providers = deps.browserProviders?.({}).providers.filter((provider) => provider.pluginId === pluginId && provider.version === version) ?? [];
    const asset = providers.flatMap((provider) => provider.assets).find((asset) => asset.digest === digest && asset.path.split("/").at(-1) === filename);
    if (!asset) { res.status(404).json({ error: "chart asset was not found" }); return; }
    res.set({ "Content-Type": asset.contentType, "X-Content-Type-Options": "nosniff", "Cache-Control": "private, max-age=31536000, immutable" });
    res.send(Buffer.from(asset.readBytes({})));
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { PLUGIN_PACKAGE_FILE_LIMITS, PluginPackagePathError } from "@jini-ai/plugins/host/node";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { Response } from "express";
import type { PluginsRouteRegistrar } from "./deps.js";

/** Maps this route's thrown error types onto the admin error envelope. The path error's own message
 *  names absolute server paths, so it is replaced with fixed text rather than echoed.
 *  @complexity O(1). */
function sendPluginFilesError(res: Response, err: unknown): void {
  if (err instanceof PluginPackagePathError) {
    res.status(400).json({ error: "plugin id or version is not a safe path", code: "PLUGIN_ID_INVALID" });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/plugins/files", code: "INTERNAL_ERROR" });
}

/**
 * @file `PLUGIN_FILES` — `GET /api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/files`
 * (2026-09-13). The admin Plugins screen's read-only package-files viewer: every file in ONE
 * discovered plugin's own directory, bounded and never following a symlink.
 *
 * Structured like `list.ts`/`uninstall.ts`: authorize, run discovery, call a pre-bound mechanism,
 * map its typed error. Gated on `admin.plugins.read` — the permission `PLUGINS_LIST` and the Agent
 * Plugins screen's `AGENT_PLUGINS_LIST` both use — and authorized BEFORE the id is looked up, so a
 * caller without it learns nothing about which plugin ids exist.
 *
 * The id must name a record in a fresh discovery pass (`PLUGIN_NOT_FOUND` otherwise), so no request
 * text is ever joined into a path directly. Which directory that record maps to, and the path
 * safety for it, live in `deps.readPluginPackageFiles` (`plugin-runtime.ts`) and
 * `Jini/packages/plugins/src/host/node/package-files.ts` — see those files' headers.
 *
 * Unlike the Agent Plugins viewer (a compile-time allowlist in the admin bundle, no route at all),
 * this reads the disk: a `.tovu-plugin` is dropped into the install directory at runtime, so no
 * build-time list could know its files.
 */
export const registerPluginFilesRoute: PluginsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/files", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pluginId = String(req.params.pluginId ?? "");

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.plugins.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const record = (await deps.discoverPlugins()).find((candidate) => candidate.id === pluginId);
      if (!record) {
        res.status(404).json({ error: "plugin was not found", code: "PLUGIN_NOT_FOUND" });
        return;
      }

      const { files, truncated } = await deps.readPluginPackageFiles(record);
      res.json({ pluginId, source: record.source, files, truncated, limits: PLUGIN_PACKAGE_FILE_LIMITS });
    } catch (err) {
      sendPluginFilesError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { PluginInstallError, type PluginInstallerPort } from "@jini-ai/plugins/host/node";
import { MAX_PLUGIN_ARCHIVE_BYTES } from "#src/features/plugin-runtime/install-archive";
import { raw, type Express, type Request, type Response } from "express";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { PluginsRouteDeps } from "./deps.js";
import { localPluginInstaller, type LocalInstallerDeps } from "./local-installer.js";

const conflicts = new Set(["PLUGIN_SHADOWS_BUILT_IN", "PLUGIN_ID_CONFLICT", "PLUGIN_IN_TRASH", "PLUGIN_ENABLED", "PLUGIN_VERSION_EXISTS", "PLUGIN_DOWNGRADE", "PLUGIN_CHANGED_SINCE_PREVIEW", "PLUGIN_INSTALL_BUSY"]);
const REVIEWED_DIGEST = /^sha256-[a-f0-9]{64}$/;
const INPUT_INVALID = "PLUGIN_INSTALL_INPUT_INVALID";

/** The deps the install routes read. */
export type PluginInstallRouteDeps = Pick<PluginsRouteDeps, "workspaceId" | "authorize" | "tracker"> & LocalInstallerDeps;

/** Which of the four install endpoints a request hit: ZIP upload or folder source, preview or install. */
interface InstallRoute { readonly zip: boolean; readonly preview: boolean }
/** A request refused with `{ code, error }` at `status`. */
interface Refused { readonly refusal: { readonly status: number; readonly code: string; readonly error: string } }
type ZipParser = ReturnType<typeof raw>;
type InstallOptions = Readonly<Record<string, unknown>>;
type InstallerInput = Parameters<PluginInstallerPort["preview"]>[0];
interface InstallContext { readonly deps: PluginInstallRouteDeps; readonly route: InstallRoute; readonly parseZip: ZipParser }

const refused = (status: number, code: string, error: string): Refused => ({ refusal: { status, code, error } });
const LOCAL_INSTALL_DISABLED = refused(403, "PLUGIN_LOCAL_INSTALL_DISABLED", "Local folder installs are disabled on this server.");
const OPTIONS_INVALID = refused(400, INPUT_INVALID, "Valid replacement options and the reviewed digest are required.");

function respondRefused(res: Response, { refusal }: Refused): void {
  res.status(refusal.status).json({ code: refusal.code, error: refusal.error });
}

/** `replace` may be absent, a JSON boolean (folder body) or "true"/"false" (ZIP query string). */
function validReplacement(replacement: unknown, zip: boolean): boolean {
  if (replacement === undefined) return true;
  return zip ? replacement === "true" || replacement === "false" : typeof replacement === "boolean";
}

/** A preview needs no digest; an install needs the sha256 digest the admin reviewed. */
function validDigest(expectedDigest: unknown, preview: boolean): boolean {
  return preview || (typeof expectedDigest === "string" && REVIEWED_DIGEST.test(expectedDigest));
}

function validOptions(options: InstallOptions | undefined, route: InstallRoute): options is InstallOptions {
  // `!options` is a wiring guard: `req.body` is undefined when the route is mounted without express.json().
  if (!options) return false;
  return validReplacement(options.replace, route.zip) && validDigest(options.expectedDigest, route.preview);
}

/** Anything but `{ kind: "folder", path: <non-blank string> }` is refused; the path goes on untrimmed. */
function readFolderSource(source: unknown): Refused | { sourceDir: string } {
  const folder = source as { kind?: unknown; path?: unknown } | null | undefined;
  if (folder?.kind !== "folder" || typeof folder.path !== "string" || !folder.path.trim()) return refused(400, INPUT_INVALID, "A folder source is required.");
  return { sourceDir: folder.path };
}

function zipParseRefusal(parseError: unknown): Refused {
  return (parseError as { type?: string }).type === "entity.too.large"
    ? refused(413, "PLUGIN_PACKAGE_TOO_LARGE", "ZIP exceeds the 32 MiB upload limit.")
    : refused(400, "PLUGIN_ARCHIVE_INVALID", "ZIP upload could not be read.");
}

async function readZipUpload(req: Request, res: Response, parseZip: ZipParser): Promise<Refused | { archive: Buffer }> {
  // req.is() is true only for a non-empty application/zip body, and raw() then always leaves
  // a Buffer in req.body, so the archive below needs no separate Buffer check.
  if (!req.is("application/zip")) return refused(400, INPUT_INVALID, "An application/zip upload is required.");
  const parseError = await new Promise<unknown>((resolve) => parseZip(req, res, (error?: unknown) => resolve(error)));
  if (parseError) return zipParseRefusal(parseError);
  return { archive: req.body as Buffer };
}

/** Validates the options, then reads the ZIP upload or folder source into the installer's input. */
async function readInstallInput(req: Request, res: Response, context: InstallContext): Promise<Refused | { input: InstallerInput; expectedDigest: unknown }> {
  // ZIP options ride the query string; folder options are the JSON body.
  const options: InstallOptions | undefined = context.route.zip ? req.query : req.body;
  if (!validOptions(options, context.route)) return OPTIONS_INVALID;
  const source = context.route.zip ? await readZipUpload(req, res, context.parseZip) : readFolderSource(options.source);
  if ("refusal" in source) return source;
  return { input: { ...source, replace: options.replace === true || options.replace === "true" }, expectedDigest: options.expectedDigest };
}

async function handleInstall(req: Request, res: Response, context: InstallContext): Promise<void> {
  const { deps, route } = context;
  const principal = getAuthedPrincipal(res);
  if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "admin.plugins.enable", workspaceId: deps.workspaceId }))) return;
  const installer = localPluginInstaller(deps);
  if (!installer) { respondRefused(res, LOCAL_INSTALL_DISABLED); return; }
  const read = await readInstallInput(req, res, context);
  if ("refusal" in read) { respondRefused(res, read); return; }
  // validDigest() admitted only a sha256 string on install (non-preview) routes.
  const result = route.preview
    ? await installer.preview(read.input)
    : await installer.install({ ...read.input, expectedDigest: read.expectedDigest as string });
  if (!route.preview) deps.tracker.capture({ name: "plugin_installed", userId: principal.id }, { properties: { pluginId: result.id, pluginKind: "cms", source: "admin" } });
  res.status(route.preview ? 200 : 201).json({ plugin: result });
}

function installErrorStatus(code: string): number {
  if (code === "PLUGIN_INSTALL_RECOVERY_REQUIRED") return 500;
  return conflicts.has(code) ? 409 : 400;
}

function respondInstallFailure(res: Response, error: unknown): void {
  if (error instanceof PluginInstallError) { res.status(installErrorStatus(error.code)).json({ code: error.code, error: error.message }); return; }
  sendAdminFailure({ res, error }, { operation: "routes/plugins/install", code: "INTERNAL_ERROR" });
}

/** Local sources are explicitly opt-in, even for admins. ZIP parsing follows authorization. */
export const registerPluginInstallRoutes = (app: Express, deps: PluginInstallRouteDeps): void => {
  const parseZip = raw({ type: "application/zip", limit: MAX_PLUGIN_ARCHIVE_BYTES, inflate: false });
  for (const [zip, preview] of [[false, true], [false, false], [true, true], [true, false]] as const) {
    const context: InstallContext = { deps, route: { zip, preview }, parseZip };
    app.post(`/api/admin/v1/workspaces/:workspaceId/plugins/install${zip ? "/zip" : ""}${preview ? "/preview" : ""}`, async (req, res) => {
      if (req.params.workspaceId !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
      try {
        await handleInstall(req, res, context);
      } catch (error) {
        if (!preview) deps.tracker.capture({ name: "operation_failed", userId: getAuthedPrincipal(res).id }, { properties: { operationKind: "plugin_install", reasonClass: error instanceof PluginInstallError ? "refused" : "internal", surface: "admin", retryable: false } });
        respondInstallFailure(res, error);
      }
    });
  }
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { toAdminPluginResponse } from "#src/server/inbound/admin-http/http/plugins";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { Express } from "express";
import type { PluginsRouteDeps } from "./deps.js";
import { localPluginInstaller, type LocalInstallerDeps } from "./local-installer.js";

/** The deps the list route reads; activation is only ever looked up, never written. */
export type PluginsListRouteDeps = Pick<PluginsRouteDeps, "workspaceId" | "authorize" | "discoverPlugins" | "listPluginConflicts"> &
  LocalInstallerDeps & { pluginActivationRepo: Pick<PluginsRouteDeps["pluginActivationRepo"], "getActivation"> };

/**
 * @file `PLUGINS_LIST` — `GET /api/admin/v1/workspaces/:workspaceId/plugins` (SPEC-005 REQ-10,
 * api.spec.md §1/§4/§5; C-016). A plain read — no gateway involvement (errors.spec.md §4:
 * `PLUGIN_NOT_FOUND` etc. are route-level guards on the OTHER endpoint, `PLUGIN_SET_ENABLED`).
 *
 * Discovery + integrity/`sdkRange` checks run server-side on every call (no refresh parameter,
 * api.spec.md §4) — `deps.discoverPlugins()` is a pre-bound closure that does exactly this.
 * `enabled` is projected per-record from `deps.pluginActivationRepo` via `toAdminPluginResponse()`
 * (discovery itself does not know activation state).
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-016). Route registration and handler body
 * are both real: authorizes `admin.plugins.read`, runs discovery, and projects each record through
 * `toAdminPluginResponse()` alongside its activation row. Verified against
 * `__tests__/integration/plugins-http.integration.test.ts`.
 */
export const registerPluginsListRoute = (app: Express, deps: PluginsListRouteDeps): void => {
  app.get("/api/admin/v1/workspaces/:workspaceId/plugins", async (req, res) => {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.plugins.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const discovery = await deps.discoverPlugins();
      // 2026-10-04: each row carries its name conflicts (refused, or would be if turned on).
      const conflicts = (await deps.listPluginConflicts?.()) ?? new Map();
      const plugins = await Promise.all(
        discovery.map(async (record) => {
          const activation = await deps.pluginActivationRepo.getActivation({
            workspaceId: deps.workspaceId,
            pluginId: record.id,
          });
          return toAdminPluginResponse(record, activation, { conflicts: conflicts.get(record.id) ?? [] });
        })
      );

      res.json({ plugins, installSources: localPluginInstaller(deps) ? ["folder", "zip"] : [] });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/plugins/list", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { PluginHookFailedError } from "@jini-ai/plugins/host";
import { pluginHookFailedBody } from "#src/server/inbound/admin-http/http/plugin-hook-error";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { Response } from "express";
import type { PluginsRouteRegistrar } from "./deps.js";

/** One previewable draft, as the admin editor sends it. */
interface PreviewDraft {
  readonly postId?: string;
  readonly title: string;
  readonly metaDescription?: string;
  readonly slug?: string;
  readonly bodyJson: Readonly<Record<string, unknown>>;
}

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isOptionalString = (value: unknown): boolean => value === undefined || typeof value === "string";

/** The body's draft, including the editor's unsaved meta description, or `null` when invalid.
 * @complexity O(1). */
function parsePreviewDraft(body: unknown): PreviewDraft | null {
  if (!isPlainObject(body)) return null;
  const { postId, title, slug, bodyJson, metaDescription } = body;
  if (typeof title !== "string" || !isPlainObject(bodyJson)) return null;
  if (!isOptionalString(postId) || !isOptionalString(slug) || !isOptionalString(metaDescription)) return null;
  return {
    title,
    bodyJson,
    ...(metaDescription === undefined ? {} : { metaDescription: metaDescription as string }),
    ...(postId === undefined ? {} : { postId: postId as string }),
    ...(slug === undefined ? {} : { slug: slug as string }),
  };
}

/** Maps this route's thrown errors onto the admin error envelope. A hook failure is the plugin's
 *  (422 — the draft could not be processed), in the save routes' `PLUGIN_HOOK_FAILED` envelope with
 *  fixed preview text — never the plugin's own error; anything else names no internals.
 *  @complexity O(1). */
function sendPluginPreviewError(res: Response, err: unknown): void {
  if (err instanceof PluginHookFailedError) {
    res.status(422).json(pluginHookFailedBody(err, { publicText: `a site plugin (${err.pluginId}) failed on this draft; nothing was saved` }));
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/plugins/preview", code: "INTERNAL_ERROR" });
}

/**
 * @file `PLUGIN_PREVIEW` — `POST /api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/preview`
 * (AW-7 Tier 2, 2026-10-04). Runs ONE enabled plugin's `content.entry.beforeSave` filter on a draft
 * and returns that plugin's validated fields, without saving anything: the post editor's "Analyze
 * now" (`apps/admin/src/features/content-analysis/`). Generic — any plugin with an attached filter.
 *
 * Structured like `files.ts`: authorize, run discovery, call a pre-bound mechanism, map its typed
 * error. Gated on `content.write`, the permission editing a post needs, and authorized BEFORE the id
 * is looked up so a caller without it learns nothing about which plugin ids exist.
 *
 * The mechanism is `deps.previewPluginBeforeSave` (`HookRegistry.previewBeforeSave`): same snapshot
 * and declared-field validation as a save, but a failure never counts toward quarantine, so an
 * editor trying drafts cannot switch a plugin off. A tier-2 plugin's filter runs in a fresh worker.
 * Workspace-scoped like every sibling route (the original design brief named an unscoped path).
 *
 * `PLUGIN_PREVIEW_STATUS` — `GET` on the same path (2026-10-05) — answers `{ pluginId, enabled }`
 * under the same `content.write` gate, so the editor can decide whether to show "Analyze now"
 * without the admin plugin list (`admin.plugins.read`, which a built-in editor lacks). `enabled` is
 * the activation row's, exactly as `PLUGINS_LIST` projects it.
 */
export const registerPluginPreviewRoute: PluginsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/preview", async (req, res) => {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pluginId = req.params.pluginId;

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "content.write",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      if (!(await deps.discoverPlugins()).some((candidate) => candidate.id === pluginId)) {
        res.status(404).json({ error: "plugin was not found", code: "PLUGIN_NOT_FOUND" });
        return;
      }

      const activation = await deps.pluginActivationRepo.getActivation({ workspaceId: deps.workspaceId, pluginId });
      res.json({ pluginId, enabled: activation?.enabled ?? false });
    } catch (err) {
      sendPluginPreviewError(res, err);
    }
  });

  app.post("/api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/preview", async (req, res) => {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pluginId = req.params.pluginId;

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "content.write",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const draft = parsePreviewDraft(req.body);
      if (!draft) {
        res.status(400).json({
          error: "title (string) and bodyJson (object) are required; postId, slug and metaDescription must be strings",
          code: "VALIDATION_ERROR",
        });
        return;
      }

      if (!(await deps.discoverPlugins()).some((candidate) => candidate.id === pluginId)) {
        res.status(404).json({ error: "plugin was not found", code: "PLUGIN_NOT_FOUND" });
        return;
      }

      const fields = await deps.previewPluginBeforeSave(pluginId, {
        id: draft.postId ?? "preview",
        workspaceId: deps.workspaceId,
        title: draft.title,
        ...(draft.metaDescription === undefined ? {} : { metaDescription: draft.metaDescription }),
        slug: draft.slug ?? "",
        status: "draft",
        bodyJson: draft.bodyJson,
        ext: {},
      });
      if (fields === null) {
        res.status(409).json({ error: "plugin is not enabled", code: "PLUGIN_NOT_ENABLED" });
        return;
      }
      res.json({ pluginId, fields });
    } catch (err) {
      sendPluginPreviewError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";
import type { PluginProviderSettingField } from "@jini-ai/plugins/host";

import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import type { ProviderConfigSource } from "#src/server/runtime/composition/provider-config-source";
import { declaredProviderSettingFields, saveProviderSettings } from "#src/server/runtime/composition/provider-settings-save";
import type { PluginsRouteDeps } from "./deps.js";

/**
 * @file `PLUGIN_PROVIDER_SETTINGS` — `GET`/`PUT /api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/provider-settings`
 * (provider wave 2 fix, 2026-10-26). The provider plugin's secure settings card: its manifest-declared
 * fields (`contributes.providers[].settings`), the saved public values, and for secret fields only
 * whether one is saved — a secret is write-only and never leaves the server. Saves go through
 * `ProviderConfigSource` (the project store when one is configured, else this site's vault), sealed.
 * A saved provider applies now through the same provider lifecycle as boot.
 *
 * Read needs `admin.plugins.read`; save needs `admin.plugins.enable` (configuring a provider decides
 * where this site's telemetry goes, the same trust as turning the plugin on). A blank secret keeps
 * the saved one while the public fields are unchanged; changing one (an endpoint, a host) needs the
 * saved secrets entered again, so a saved key can never be redirected to another server.
 * That save rule lives in `composition/provider-settings-save.ts`, shared with the assistant's key card.
 */

export interface ProviderSettingsRouteDeps extends Pick<PluginsRouteDeps, "workspaceId" | "authorize" | "discoverPlugins"> {
  tracker?: import('@jini-ai/diagnostics/observability').Tracker;
  providerConfig?: ProviderConfigSource;
  ownerPrincipalId?: Promise<string>;
  projectKeys?: import("#src/features/project-keys/service").ProjectKeysPort;
  providerAppliesAt?: (input: { pluginId: string }) => "now" | "restart" | "failed";
  reapplyProvider?: (input: { pluginId: string }) => Promise<import("@jini-ai/plugins/host").PluginProviderApplyResult>;
  /** Whether a key was saved the retired way (an API credential labelled `plugin:<id>`), read by label
   *  only, never decrypted. */
  legacyProviderCredential?: (required: { pluginId: string }) => Promise<boolean>;
}

const PATH = "/api/admin/v1/workspaces/:workspaceId/plugins/:pluginId/provider-settings";

/**
 * Wave 2 saved provider keys as API credentials labelled `plugin:<id>`; boot no longer reads them
 * (Codex fix-lane MED). Mapping them into the declared fields would need per-vendor knowledge in Tovu,
 * which the manifest-driven boot removed, so the card asks for the key again instead: shown while
 * nothing is saved the new way, gone after the first save. A failing check never breaks the card.
 */
async function hasLegacyCredential({ deps, pluginId, saved }: { deps: ProviderSettingsRouteDeps; pluginId: string; saved: unknown }): Promise<boolean> {
  if (saved || !deps.legacyProviderCredential) return false;
  return deps.legacyProviderCredential({ pluginId }).catch(() => false);
}

/** A public field's declared choices (`default`, `options`, `allowCustom`), passed to the card as declared. */
const choicesOf = ({ default: fallback, options, allowCustom }: PluginProviderSettingField) => ({
  ...(fallback === undefined ? {} : { default: fallback }), ...(options ? { options } : {}), ...(allowCustom ? { allowCustom: true as const } : {}),
});

function fieldPresentation({ field }: { field: PluginProviderSettingField }, _optional = {}) {
  return { ...(field.hint ? { hint: field.hint } : {}), ...(field.secret === true ? {} : choicesOf(field)) };
}

async function cardOf({ deps, config, pluginId, fields }: { deps: ProviderSettingsRouteDeps; config: ProviderConfigSource; pluginId: string; fields: readonly PluginProviderSettingField[] }) {
  const saved = await config.readSettings({ pluginId });
  return {
    pluginId, ...(await config.usage({ pluginId })), projectAvailable: config.scope === "project", appliesAt: deps.providerAppliesAt?.({ pluginId }) ?? "now",
    ...((await hasLegacyCredential({ deps, pluginId, saved })) ? { legacyCredential: true as const } : {}),
    ...(saved?.unreadable ? { unreadable: true as const } : {}),
    fields: fields.map((field) => {
      const secret = field.secret === true;
      const value = secret ? undefined : saved?.settings[field.name];
      return { name: field.name, label: field.label, ...fieldPresentation({ field }), secret, required: field.required === true,
        ...(field.requiredUnless ? { requiredUnless: field.requiredUnless } : {}),
        ...(field.requiredWhen ? { requiredWhen: field.requiredWhen } : {}),
        saved: secret ? (saved?.secretNames.includes(field.name) ?? false) : value !== undefined && value !== "", ...(value === undefined ? {} : { value }) };
    }),
  };
}

/** Shared guard: workspace, principal permission, plugin with declared settings, a configured store. */
async function resolveCard({ req, res, deps, permission }: { req: Request; res: Response; deps: ProviderSettingsRouteDeps; permission: string }) {
  if (String(req.params.workspaceId ?? "") !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return undefined; }
  const principal = getAuthedPrincipal(res);
  if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission, workspaceId: deps.workspaceId }))) return undefined;
  const pluginId = String(req.params.pluginId ?? "");
  const records = await deps.discoverPlugins();
  const fields = declaredProviderSettingFields({ records, pluginId });
  if (!fields) { res.status(404).json({ error: "this plugin declares no provider settings", code: "PLUGIN_NOT_FOUND" }); return undefined; }
  if (!deps.providerConfig) { res.status(503).json({ error: "provider settings are not available here", code: "PROVIDER_SETTINGS_UNAVAILABLE" }); return undefined; }
  const contracts = providerContracts({ records, pluginId });
  return { deps, pluginId, fields, config: deps.providerConfig,
    ...(deps.tracker ? { telemetry: { tracker: deps.tracker, contracts, userId: principal.id } } : {}) };
}

function providerContracts({ records, pluginId }: { records: Awaited<ReturnType<ProviderSettingsRouteDeps["discoverPlugins"]>>; pluginId: string }, _optional = {}) {
  return (records.find(record => record.id === pluginId)?.manifest?.contributes?.providers ?? []).map(provider => provider.contract);
}

function isProjectKeyUseInput(input: Record<string, unknown> | null, _optional = {}): input is { use: boolean } {
  return !!input && typeof input.use === "boolean" && !Object.keys(input).some(key => key !== "use");
}

const internalError = (res: Response, error: unknown) => sendAdminFailure({ res, error });

export function registerPluginProviderSettingsRoutes(app: Express, deps: ProviderSettingsRouteDeps): void {
  app.get(PATH, async (req, res) => {
    try {
      const card = await resolveCard({ req, res, deps, permission: "admin.plugins.read" });
      if (card) res.json(await cardOf(card));
    } catch (error) { internalError(res, error); }
  });
  app.put(PATH, async (req, res) => {
    try {
      const card = await resolveCard({ req, res, deps, permission: "admin.plugins.enable" });
      if (!card) return;
      const saved = await saveProviderSettings({ ...card, reapply: deps.reapplyProvider, values: (req.body as { values?: unknown } | null)?.values });
      if ("refusal" in saved) { res.status(saved.refusal.code === "PROVIDER_SETTINGS_UNAVAILABLE" ? 503 : 400).json(saved.refusal); return; }
      const attached = deps.projectKeys ? await deps.projectKeys.savedResult({ result: saved }) as typeof saved : saved;
      res.json({ ...(await cardOf(card)), appliesAt: attached.appliesAt, ...(attached.message ? { message: attached.message } : {}) });
    } catch (error) { internalError(res, error); }
  });
  registerProjectKeyUseRoute(app, deps);
}

/** Admin and chat share the same attachment owner and per-kind save permission. */
function registerProjectKeyUseRoute(app: Express, deps: ProviderSettingsRouteDeps): void {
  app.put("/api/admin/v1/workspaces/:workspaceId/project-keys/:keyId/use", async (req, res) => {
    try {
      if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
      const principal = getAuthedPrincipal(res);
      if (!rejectUnlessSessionCredential(res, { message: "Use the owner's session to approve or revoke a saved key for this site.", permission: "custom-credentials.write" })) return;
      if (principal.id !== await deps.ownerPrincipalId) { res.status(403).json({ error: "Sign in as the installation owner to change this site's saved key grants." }); return; }
      if (!deps.projectKeys) { res.status(503).json({ error: "This site has no project key store." }); return; }
      const input = req.body as Record<string, unknown> | null;
      if (!isProjectKeyUseInput(input)) { res.status(400).json({ error: "use must be true or false" }); return; }
      const keyId = String(req.params.keyId);
      if (!await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "custom-credentials.read", workspaceId: deps.workspaceId })) return;
      const permission = await deps.projectKeys.permissionFor({ keyId });
      if (!await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission, workspaceId: deps.workspaceId })) return;
      res.json(await deps.projectKeys.use({ keyId, use: input.use }));
    } catch (error) {
      if (error instanceof Error && error.name === "ToolInputError") { res.status(400).json({ error: error.message }); return; }
      internalError(res, error);
    }
  });
}

import { ToolAccessLoweringError } from '#src/contracts/core/tool-access-change';
import { lowerPluginToolAccess } from '#src/features/plugin-runtime/lower-tool-access';
import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import { executeCommand, ForbiddenError } from "@jini-ai/cms/core";
import { pluginCapabilitySet, PluginIncompatibleError, PluginInvalidError, PluginNotFoundError, setPluginEnabled, type PluginActivationRecord } from "@jini-ai/plugins/host";
import { PluginLoadError, type PluginDiscoveryRecord } from "@jini-ai/plugins/host/node";
import { PluginConflictError } from "@jini-ai/plugins/host";
import { PluginInstallError } from "@jini-ai/plugins/host/node";
import { toAdminPluginResponse } from "#src/server/inbound/admin-http/http/plugins";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { PluginsRouteDeps, PluginsRouteRegistrar } from "./deps.js";

/** OFF commits before the existing serving runtime stops affected answers. */
async function stopPluginAnswers(deps: PluginsRouteDeps, pluginId: string, enabled: boolean): Promise<void> {
  if (!enabled) await lowerPluginToolAccess({ pluginId, notifyRosterChanged: deps.notifyRosterChanged, ...(deps.providerFaces ? { providerFaces: deps.providerFaces } : {}) }, {});
}

/**
 * `executeCommand`'s `rollback` for this route: restores the captured prior activation row (or
 * deletes it, for a first-time enable/disable), then re-invokes the matching `onPluginEnabled`/
 * `onPluginDisabled` side effect so hook attachment stays consistent with the restored row.
 *
 * Declared as its own top-level function, not inline in the `mutation` object, so its two-branch
 * shape doesn't nest inside the route handler.
 *
 * @complexity O(1).
 */
async function rollbackPluginActivation(
  deps: Pick<PluginsRouteDeps, "pluginActivationRepo" | "onPluginEnabled" | "onPluginDisabled">,
  params: { workspaceId: string; pluginId: string; priorActivation: PluginActivationRecord | null }
): Promise<void> {
  const { workspaceId, pluginId, priorActivation } = params;
  if (priorActivation) {
    await deps.pluginActivationRepo.save(priorActivation);
  } else {
    await deps.pluginActivationRepo.deleteActivation({ workspaceId, pluginId });
  }
  if (priorActivation?.enabled) {
    await deps.onPluginEnabled(pluginId);
  } else {
    deps.onPluginDisabled(pluginId);
  }
}

/** Maps this route's thrown error types onto the admin error envelope.
 *  @complexity O(1). */
function sendSetPluginEnabledError(res: Response, err: unknown): void {
  if (err instanceof ToolAccessLoweringError) {
    res.status(503).json({ error: err.message, code: err.code });
    return;
  }
  if (err instanceof PluginInstallError) {
    res.status(409).json({ error: err.message, code: err.code });
    return;
  }
  if (err instanceof ForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof PluginNotFoundError) {
    res.status(404).json({ error: err.message, code: "PLUGIN_NOT_FOUND" });
    return;
  }
  if (err instanceof PluginIncompatibleError) {
    res.status(422).json({ error: err.message, code: "PLUGIN_INCOMPATIBLE" });
    return;
  }
  if (err instanceof PluginInvalidError) {
    res.status(422).json({ error: err.message, code: "PLUGIN_INVALID" });
    return;
  }
  // 2026-10-04: a name another plugin or core already holds — the operator's fix is to turn the
  // other plugin off, so this is a 409 with the structured clash, never a 500.
  if (err instanceof PluginConflictError) {
    res.status(409).json({ error: err.message, code: "PLUGIN_CONFLICT", details: { pluginId: err.pluginId, conflicts: err.conflicts } });
    return;
  }
  if (err instanceof PluginLoadError) {
    res.status(500).json({ error: err.message, code: "PLUGIN_LOAD_FAILED", details: { pluginId: err.pluginId, reason: err.reason } });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/plugins/set-enabled", code: "INTERNAL_ERROR" });
}

/**
 * @file `PLUGIN_SET_ENABLED` — `PATCH /api/admin/v1/workspaces/:workspaceId/plugins/:pluginId`
 * (SPEC-005 REQ-07/REQ-10, api.spec.md §1/§4/§5/§6; C-016).
 *
 * Mirrors `admin/posts/update.ts`'s `executeCommand`-wrapped shape (ADR API/Event Contract
 * Summary): `captureInverse` snapshots the prior `PluginActivationRecord` (or `null` — a plugin
 * enabled for the first time has no prior row), `execute` calls `setPluginEnabled()`. Route-level
 * guards run BEFORE the gateway (errors.spec.md §4): unknown id ⇒ 404 `PLUGIN_NOT_FOUND`; invalid/
 * incompatible ⇒ 422 `PLUGIN_INVALID`/`PLUGIN_INCOMPATIBLE` — these are exactly the typed errors
 * `setPluginEnabled()` throws, so this handler's catch block maps them, same as every other
 * gateway-wrapped route in this codebase maps its feature function's typed errors.
 *
 * Architectural role:
 * TDD-certified implementation (implementation outline C-016). Route registration and handler body
 * are both real: `execute` calls `setPluginEnabled()`; on a later gateway failure, `rollback`
 * restores the captured prior activation row (or deletes it, for a first-time enable/disable) via
 * `pluginActivationRepo`, then re-invokes the matching `onPluginEnabled`/`onPluginDisabled` side
 * effect so hook attachment stays consistent with the restored row. Verified against
 * `__tests__/integration/plugins-http.integration.test.ts`.
 */
export const registerPluginSetEnabledRoute: PluginsRouteRegistrar = (app, deps) => {
  app.patch("/api/admin/v1/workspaces/:workspaceId/plugins/:pluginId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pluginId = String(req.params.pluginId ?? "");
    // Validated, not coerced (api.spec.md: malformed body is 400): `Boolean("false")` is `true`, so
    // coercion let a malformed body ENABLE a plugin and run its enable hook. Same rule as
    // `agent-plugins/set-enabled.ts`.
    const enabled = (req.body as { enabled?: unknown } | undefined)?.enabled;
    if (typeof enabled !== "boolean") {
      res.status(400).json({ error: "'enabled' must be a boolean", code: "VALIDATION_ERROR" });
      return;
    }

    // Full pre-transition activation row, captured in captureInverse and reused verbatim by
    // rollback — mirrors `admin/posts/update.ts`'s `priorPost` shape exactly (ADR API/Event
    // Contract Summary: this route is thin, `executeCommand`-wrapped, same as that one).
    let priorActivation: PluginActivationRecord | null = null;

    try {
      const principal = getAuthedPrincipal(res);
      const discovery = await deps.discoverPlugins();
      const site = discovery.find((r) => r.id === pluginId && r.source === "site");

      const { result, changeSetId } = await executeCommand({
        deps: {
          clock: deps.clock,
          idGen: deps.idGen,
          changeSets: deps.changeSets,
          outbox: deps.outbox,
          authorize: deps.authorize,
        },
        command: {
          workspaceId: deps.workspaceId,
          actor: { id: principal.id, kind: "user" },
          summary: `Set plugin '${pluginId}' enabled=${enabled}`,
          permission: "admin.plugins.enable",
          // No `idempotencyKey`: an enable/disable is a target-state write, so the gateway can never
          // raise `DuplicateCommandError` for this route and there is no `DUPLICATE_COMMAND` arm to map.
        },
        mutation: {
          entityType: "plugin-activation",
          entityId: pluginId,
          operation: "update",
          captureInverse: async () => {
            priorActivation = await deps.pluginActivationRepo.getActivation({
              workspaceId: deps.workspaceId,
              pluginId,
            });
            // BR-05/REQ-07: the inverse is the PRIOR enabled value only — a plugin activation has
            // no other revertible field a restore would need (mirrors `presentation.ts`'s
            // single-field activation shape).
            return { enabled: priorActivation?.enabled ?? false };
          },
          execute: async () => {
            // The owner's own click is the approval later assistant re-seals are compared against,
            // so a code-only re-seal does not ask again. Inside `execute`, i.e. only after the
            // permission gate; recorded first, so a failed record leaves the plugin off.
            if (enabled && site?.manifest && deps.pluginSource) await deps.pluginSource.recordApproval({ id: pluginId, capabilities: pluginCapabilitySet({ manifest: site.manifest }) }, {});
            return setPluginEnabled({
              deps: {
                clock: deps.clock,
                repo: deps.pluginActivationRepo,
                discovery,
                onEnabled: deps.onPluginEnabled,
                onDisabled: deps.onPluginDisabled,
              },
              input: { workspaceId: deps.workspaceId, pluginId, enabled },
            });
          },
          rollback: () => rollbackPluginActivation(deps, { workspaceId: deps.workspaceId, pluginId, priorActivation }),
        },
      });

      await stopPluginAnswers(deps, pluginId, result.activation.enabled);

      // `setPluginEnabled` throws `PluginNotFoundError` for an id absent from this same `discovery`
      // snapshot, so reaching this line means the record is in it.
      const record = discovery.find((r) => r.id === pluginId) as PluginDiscoveryRecord;
      // The gateway has committed; retries that keep the same state do not count.
      if (((priorActivation as PluginActivationRecord | null)?.enabled ?? false) !== result.activation.enabled) deps.tracker.capture({ name: "plugin_toggled", userId: principal.id }, { properties: { pluginId: record.id, pluginKind: "cms", enabled: result.activation.enabled, source: "admin" } });
      res.json({
        plugin: toAdminPluginResponse(record, result.activation),
        changeSetId,
      });
    } catch (err) {
      sendSetPluginEnabledError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { PluginNotFoundError } from "@jini-ai/plugins/host";
import { PluginAlreadyInTrashError, PluginEnabledError, PluginNotUninstallableError, uninstallPlugin } from "@jini-ai/plugins/host";
import { PluginUninstallPathError } from "#src/server/runtime/composition/plugin-runtime";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { Response } from "express";
import type { PluginsRouteRegistrar } from "./deps.js";

/** Maps this route's thrown error types onto the admin error envelope.
 *  @complexity O(1). */
function sendPluginUninstallError(res: Response, err: unknown): void {
  if (err instanceof PluginNotFoundError) {
    res.status(404).json({ error: err.message, code: "PLUGIN_NOT_FOUND" });
    return;
  }

  if (err instanceof PluginNotUninstallableError) {
    res.status(422).json({ error: err.message, code: "PLUGIN_NOT_UNINSTALLABLE" });
    return;
  }

  if (err instanceof PluginEnabledError) {
    res.status(409).json({ error: err.message, code: "PLUGIN_ENABLED" });
    return;
  }

  if (err instanceof PluginAlreadyInTrashError) {
    res.status(409).json({ error: err.message, code: "PLUGIN_IN_TRASH" });
    return;
  }

  if (err instanceof PluginUninstallPathError) {
    res.status(400).json({ error: err.message, code: "PLUGIN_ID_INVALID" });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/plugins/uninstall", code: "INTERNAL_ERROR" });
}

/**
 * @file `PLUGIN_UNINSTALL` moves a site plugin to the 60-day Trash. The package directory is shared
 * by every workspace on this site, while the Trash row belongs to the workspace making the request.
 */
export const registerPluginUninstallRoute: PluginsRouteRegistrar = (app, deps) => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/plugins/:pluginId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const pluginId = String(req.params.pluginId ?? "");

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.plugins.enable",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const discovery = await deps.discoverPlugins();
      const result = await uninstallPlugin({
        deps: {
          repo: deps.pluginActivationRepo,
          discovery,
          remove: deps.removePlugin,
        },
        input: {
          pluginId,
          workspaceId: deps.workspaceId,
          at: new Date(deps.clock.nowMs()).toISOString(),
          actor: { principalId: principal.id },
        },
      });

      res.json({ pluginId, trashed: result.trashed });
    } catch (err) {
      sendPluginUninstallError(res, err);
    }
  });
};

import type { Response } from "express";

import type { JsonObject } from "@jini-ai/core/primitives";
import { getAdminPostByIdOrSlug, normalizePostAuthor, PostValidationError, type PostAutosaveSnapshot, type PostBodyFormat, type PostRepoPort } from "#src/features/post/index";
import { CONTENT_ENTRY_MAX_BODY_BYTES, rejectOversizedJsonBody } from "#src/server/inbound/shared/body-size-limit";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteDeps, ContentRouteRegistrar } from "../content/deps.js";

/**
 * @file Standing-draft autosave for Posts AND Pages (2026-09-06 dispatch) — one route file, kind-
 * blind, mounted only under `/posts/:postId/autosave` and reused by both admin editors exactly the
 * way `updatePost`/`deletePost` already are (see `apps/admin/src/lib/api.ts`'s own "Kind-blind like
 * getPost/updatePost/deletePost" comments) — a Page is a `posts` row like any other, so nothing
 * here needs to know which lens is asking.
 *
 * Deliberately NOT routed through `executeCommand` (SPEC-001's command gateway), unlike
 * `posts/update.ts`: an autosave tick is disposable operational scratch state, never a real edit —
 * it must not create a change-set row, fire the `content.entry.beforeSave` plugin hook, or bump
 * `version`/`updatedAt` (see `PostRepoPort.writeAutosave`'s own doc). Gated on the same
 * `content.write` permission `posts/update.ts` checks, since parking or discarding a draft is part
 * of the same "may this principal edit this content" capability as saving it for real.
 */
const REQUIRED_PERMISSION = "content.write";

/**
 * Resolves the URL's `:postId` segment to the row's real id — the admin's own Posts list links to
 * `/admin/posts/{slug}`, not `/admin/posts/{id}` (`apps/admin/src/features/posts/Posts.tsx`), so
 * this param is very often a slug, not the id `PostRepoPort` methods key off. Mirrors
 * `posts/update.ts`'s identical resolution exactly: falls back to the raw param on no match, which
 * every handler below already treats as a safe "no such row" no-op (`writeAutosave`/`readAutosave`/
 * `clearAutosave` — see `PostRepoPort`'s own doc), so no separate 404 branch is needed here.
 */
async function resolvePostId(repo: PostRepoPort, workspaceId: string, rawParam: string): Promise<string> {
  const resolved = await getAdminPostByIdOrSlug({ deps: { repo }, input: { workspaceId, idOrSlug: rawParam } }).catch(
    () => null
  );
  return resolved?.post.id ?? rawParam;
}

/** Mirrors `pages/update-html.ts`'s `allowedToWrite` — same permission, same 403 shape, extracted
 *  for the same complexity-ceiling reason. */
async function allowedToWrite(deps: ContentRouteDeps, res: Response): Promise<boolean> {
  const principal = getAuthedPrincipal(res);
  return authorizeOrRespond(res, deps.authorize, {
    principalId: principal.id,
    permission: REQUIRED_PERMISSION,
    workspaceId: deps.workspaceId,
  });
}

/** The fields common to both `bodyFormat` variants, validated but not yet paired with a payload. */
type AutosaveCommonFields = Pick<PostAutosaveSnapshot, "bodyFormat" | "title" | "slug" | "baseVersion">;

/**
 * Validates the four fields every autosave body carries regardless of `bodyFormat`. Split out of
 * `parseAutosaveBody` (2026-09-16, source-complexity-drift ceiling) so the bodyFormat-specific
 * payload check below has its own name instead of sharing one function's cyclomatic budget.
 * @complexity O(1).
 */
function parseAutosaveCommonFields(body: Record<string, unknown>): AutosaveCommonFields | null {
  const bodyFormat = body.bodyFormat as PostBodyFormat;
  if (bodyFormat !== "doc" && bodyFormat !== "html") return null;
  if (typeof body.title !== "string") return null;
  if (typeof body.slug !== "string") return null;
  if (typeof body.baseVersion !== "number" || !Number.isFinite(body.baseVersion)) return null;
  return { bodyFormat, title: body.title, slug: body.slug, baseVersion: body.baseVersion };
}

/**
 * Validates and extracts the one payload field `bodyFormat` requires: `bodyJson` for `"doc"`,
 * `bodyHtml` for `"html"`. Returns `null` (never throws) on any shape the `posts_body_format_shape`
 * CHECK constraint would also reject, so the route can 400 before ever reaching the repo.
 * @complexity O(1).
 */
function parseAutosaveContent(body: Record<string, unknown>, bodyFormat: PostBodyFormat): Pick<PostAutosaveSnapshot, "bodyJson" | "bodyHtml"> | null {
  if (bodyFormat === "doc") {
    if (typeof body.bodyJson !== "object" || body.bodyJson === null) return null;
    return { bodyJson: body.bodyJson as JsonObject };
  }
  if (typeof body.bodyHtml !== "string") return null;
  return { bodyHtml: body.bodyHtml };
}

/** Validates optional byline fields while preserving absent keys in the parked snapshot.
 * Author normalization remains owned by the shared post write validator. */
function parseAutosaveByline(
  { body }: { body: Record<string, unknown> },
  _options: Record<string, never> = {}
): Pick<PostAutosaveSnapshot, "author" | "showAuthor"> | null {
  if (body.author !== undefined && body.author !== null && typeof body.author !== "string") return null;
  if (body.showAuthor !== undefined && typeof body.showAuthor !== "boolean") return null;
  return {
    ...(body.author !== undefined ? { author: normalizePostAuthor({ author: body.author }) } : {}),
    ...(body.showAuthor !== undefined ? { showAuthor: body.showAuthor as boolean } : {}),
  };
}

/** This route's four writable PUT fields, read off an untyped body in one place — mirrors
 *  `posts/update.ts`'s `parsePostUpdateBody`. Returns `null` on any payload shape the
 *  `posts_body_format_shape` CHECK constraint would also reject, so the route can 400 before ever
 *  reaching the repo. Author validation throws PostValidationError with the shared write error.
 *  @complexity O(n) in author length — delegates to {@link parseAutosaveCommonFields} and
 *  {@link parseAutosaveContent}. */
function parseAutosaveBody(rawBody: unknown): Pick<PostAutosaveSnapshot, "bodyFormat" | "bodyJson" | "bodyHtml" | "title" | "slug" | "baseVersion" | "author" | "showAuthor"> | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const common = parseAutosaveCommonFields(body);
  if (!common) return null;
  const content = parseAutosaveContent(body, common.bodyFormat);
  if (!content) return null;
  const byline = parseAutosaveByline({ body });
  if (!byline) return null;
  return { ...common, ...content, ...byline };
}

/**
 * PUT `/api/admin/v1/workspaces/:workspaceId/posts/:postId/autosave` — parks a standing draft.
 *
 * Response is `{ applied: boolean }`, never a 409: `applied: false` (the row's `version` no longer
 * equals this snapshot's `baseVersion`, or the row is gone — see `PostRepoPort.writeAutosave`,
 * whose guard is a single conditional UPDATE) is an ordinary, expected outcome for a background
 * tick, not an error the operator needs to see. Nothing was written, and nothing on this side
 * changes as a result: a client that keeps PUTting the same `baseVersion` will keep being refused,
 * which is deterministic rather than transient.
 *
 * Acting on the flag is therefore entirely the client's job. From 2026-09-06,
 * `apps/admin/src/hooks/use-standing-draft-autosave.hooks.ts` stops scheduling further autosaves
 * for that basis and surfaces a `staleBasis` state; it deliberately does NOT drop the operator's
 * in-memory text. (An earlier version of this comment claimed the hook made the client "stop
 * treating its own in-memory edit as current" — the hook never did that, and by design still does
 * not; that would discard the very work the refusal is protecting.)
 *
 * GET on the same path reads the parked snapshot (`{ autosave: PostAutosaveSnapshot | null }`) —
 * the recovery-banner check on editor mount. DELETE clears it unconditionally (`{ ok: true }`) —
 * called after a real Save/Publish succeeds, and on an explicit operator Discard.
 */
export const registerAdminPostAutosaveRoute: ContentRouteRegistrar = (app, deps) => {
  const path = "/api/admin/v1/workspaces/:workspaceId/posts/:postId/autosave";

  app.put(path, rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }), async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    if (!(await allowedToWrite(deps, res))) return;

    let parsed: ReturnType<typeof parseAutosaveBody>;
    try {
      parsed = parseAutosaveBody(req.body);
    } catch (error) {
      if (!(error instanceof PostValidationError)) throw error;
      res.status(400).json({ error: error.message, code: "VALIDATION_ERROR" });
      return;
    }
    if (!parsed) {
      res.status(400).json({ error: "invalid autosave body", code: "VALIDATION_ERROR" });
      return;
    }

    const principal = getAuthedPrincipal(res);
    const snapshot: PostAutosaveSnapshot = {
      ...parsed,
      savedAt: deps.clock.nowIso(),
      savedByPrincipalId: principal.id,
    };
    const postId = await resolvePostId(deps.postRepo, deps.workspaceId, String(req.params.postId ?? ""));
    const result = await deps.postRepo.writeAutosave({ workspaceId: deps.workspaceId, id: postId, snapshot });
    res.json(result);
  });

  app.get(path, async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    if (!(await allowedToWrite(deps, res))) return;

    const postId = await resolvePostId(deps.postRepo, deps.workspaceId, String(req.params.postId ?? ""));
    const autosave = await deps.postRepo.readAutosave({ workspaceId: deps.workspaceId, id: postId });
    res.json({ autosave });
  });

  app.delete(path, async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    if (!(await allowedToWrite(deps, res))) return;

    const postId = await resolvePostId(deps.postRepo, deps.workspaceId, String(req.params.postId ?? ""));
    await deps.postRepo.clearAutosave({ workspaceId: deps.workspaceId, id: postId });
    res.json({ ok: true });
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { DuplicateCommandError, ForbiddenError, executeCommand } from "@jini-ai/cms/core";
import { processOutbox } from "#src/contracts/core/events/index";
import { createPost, PostConflictError, PostValidationError } from "#src/features/post/index";
import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import {
  CONTENT_ENTRY_MAX_BODY_BYTES,
  rejectOversizedJsonBody,
} from "#src/server/inbound/shared/body-size-limit";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { sendPluginHookFailedError } from "#src/server/inbound/admin-http/http/plugin-hook-error";
import type { Response } from "express";
import type { ContentRouteRegistrar } from "../content/deps.js";

/** Maps this route's thrown error types onto the admin error envelope.
 *  @complexity O(1). */
function sendPostCreateError(res: Response, err: unknown): void {
  if (sendPluginHookFailedError(res, err)) return;
  if (err instanceof ForbiddenError) {
    res.status(403).json({
      error: err.message,
      code: "FORBIDDEN",
      details: { permission: err.permission, reason: err.reason },
    });
    return;
  }

  if (err instanceof DuplicateCommandError) {
    res.status(409).json({ error: err.message, code: "DUPLICATE_COMMAND", changeSetId: err.changeSetId });
    return;
  }

  if (err instanceof PostValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }

  if (err instanceof PostConflictError) {
    res.status(409).json({ error: err.message, code: "SLUG_CONFLICT" });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/posts/create", code: "INTERNAL_ERROR" });
}

/**
 * POST a new blank draft post — routed through the command gateway (mirrors
 * the update route so post mutations stay consistently auditable/revertible).
 *
 * SPEC-006 REQ-05 wiring proof: the gateway now authorizes `content.write`
 * for the real authenticated principal (`getAuthedPrincipal`, set by
 * `requireAdminSession`) instead of the hardcoded `"user-local"` actor.
 *
 * SPEC-002 api.spec.md `POST_CREATE` §4 — `slug`/`bodyJson`/`status` are optional
 * body fields; forwarded to `createPost` only when present (`undefined` otherwise)
 * so its own default-when-absent behavior applies. `code` on the error branches
 * below mirrors `pages/update.ts` (`PAGE_UPDATE` is this endpoint's closest "new
 * endpoint" sibling — errors.spec.md guarantees `code` on new endpoints).
 *
 * `rejectOversizedJsonBody` (Security review SEC-snapshot-and-post-create-2026-07-28, Finding 1)
 * enforces api.spec.md §4's documented 1 MiB route-layer body cap ahead of the handler, so an
 * oversized request 413s before `createPost`/the command gateway ever runs.
 */
export const registerAdminPostCreateRoute: ContentRouteRegistrar = (app, deps) => {
  app.post(
    "/api/admin/v1/workspaces/:workspaceId/posts",
    rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }),
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const idempotencyKey = req.get("Idempotency-Key") || undefined;
      const postId = deps.idGen.newId();

      try {
        // Inside the try: requireAdminSession always sets res.locals.principal before this
        // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
        // outside try/catch (the request would otherwise hang instead of 500ing).
        const principal = getAuthedPrincipal(res);
        const { result } = await executeCommand({
          deps: {
            clock: deps.clock,
            idGen: deps.idGen,
            changeSets: deps.changeSets,
            outbox: deps.outbox,
            authorize: deps.authorize,
          },
          command: {
            workspaceId: deps.workspaceId,
            actor: { id: principal.id, kind: "user" },
            summary: "Create post",
            idempotencyKey,
            permission: "content.write",
          },
          mutation: {
            entityType: "post",
            entityId: postId,
            operation: "create",
            captureInverse: async () => null,
            execute: () => {
              // A body-less request reads every field as absent, exactly as `req.body?.x` did.
              const body = req.body ?? {};
              return createPost({
                deps: { repo: deps.postRepo, clock: deps.clock, beforeSaveHook: deps.pluginBeforeSaveHook, outbox: deps.outbox, authorAccounts: deps.userRepo },
                input: {
                  workspaceId: deps.workspaceId,
                  id: postId,
                  title: String(body.title ?? ""),
                  slug: body.slug !== undefined ? String(body.slug) : undefined,
                  bodyJson: body.bodyJson,
                  status: body.status,
                  author: body.author,
                  showAuthor: body.showAuthor,
                  // First Save sends the full editor snapshot; keep it in this atomic create.
                  templateChoice: body.templateChoice,
                  overridesThemePage: body.overridesThemePage,
                  hideCoverImageInBody: body.hideCoverImageInBody,
                  publishAt: body.publishAt,
                  featuredMediaId: body.featuredMediaId,
                  actorId: principal.id,
                  analyticsSource: "admin",
                },
              });
            },
            captureEntityVersion: ({ result }) => result.post.version,
          },
        });

        // A post created directly as `status: "published"` now enqueues `entry.published`
        // (`createPost`'s own `deps.outbox` doc) — drained here so SEO's sitemap-cache
        // invalidation subscriber sees it at once, mirroring `posts/update.ts`'s identical
        // inline `processOutbox` call (otherwise the background drainer in `serving-app.ts`
        // delivers it on its next pass).
        await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

        // Owner-action product event: consent-gated by the port; opaque principal id, no content.
        res.status(201).json(toAdminPostResponse(result.post));
      } catch (err) {
        sendPostCreateError(res, err);
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import { DuplicateCommandError, ForbiddenError, executeCommand } from "@jini-ai/cms/core";
import { processOutbox } from "#src/contracts/core/events/index";
import {
  PostConflictError,
  PostNotFoundError,
  deletePost,
  getAdminPostByIdOrSlug,
  restorePostForward,
  type PostRecord,
} from "#src/features/post/index";
import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteRegistrar } from "../content/deps.js";

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendPostDeleteError(res: Response, err: unknown): void {
  if (err instanceof ForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof DuplicateCommandError) {
    res.status(409).json({ error: err.message, code: "DUPLICATE_COMMAND", changeSetId: err.changeSetId });
    return;
  }
  if (err instanceof PostNotFoundError) {
    res.status(404).json({ error: err.message, code: "ENTRY_NOT_FOUND" });
    return;
  }
  // 2026-09-20: `deletePost` can now raise this when the row's version moved between its read and
  // its write — the same optimistic-concurrency rejection `posts/update.ts` already maps onto 409.
  // Before the Trash landed, a delete had no compare-and-set to lose, so there was nothing to map.
  if (err instanceof PostConflictError) {
    res.status(409).json({ error: err.message, code: "ENTRY_CONFLICT" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/posts/delete", code: "INTERNAL_ERROR" });
}

/**
 * DELETE post — routed through the command gateway exactly like `posts/update.ts`.
 *
 * SOFT delete: `deletePost` stamps a trash marker, it does not remove the row (see
 * `features/post/post.ts`'s `PostRecord.deletedAt` for the full rationale, and
 * `core/commands/appliers.ts`'s `postDeleteReverter` for the restore that marker makes possible).
 * So this route is genuinely revertible through the existing `POST /change-sets/:id/revert`
 * endpoint, which is the same recoverability guarantee every other gateway-routed write here has.
 *
 * Mirrors `posts/update.ts`'s shape deliberately, field for field: same `executeCommand` deps bag,
 * same `Idempotency-Key` handling, same `actor: { id: principal.id, kind: "user" }`, same
 * `content.write` permission (deleting content IS writing content — this codebase has no separate
 * `content.delete` permission, and inventing one here would create a permission no policy grants),
 * same `captureInverse`/`rollback` unit-of-work compensation, same inline `processOutbox` drain,
 * and the same success body (`toAdminPostResponse`) so a client sees the record it just trashed.
 *
 * Deliberately NOT mirrored from `posts/update.ts`: `rejectOversizedJsonBody`. A DELETE carries no
 * body to cap, so applying the 1 MiB guard would be ceremony against a request shape that cannot
 * trigger it.
 *
 * `operation: "delete"` (not `"update"`) is what routes a revert of this change set to
 * `postDeleteReverter` rather than `postUpdateReverter` — `ChangeSetOperation` already had the
 * `"delete"` member; this is its first real user.
 *
 * Error `code`s: this is a NEW endpoint, so it carries the `code` field errors.spec.md §1 requires
 * of new endpoints — matching `pages/update.ts`'s disclosed treatment rather than
 * `posts/update.ts`'s message-only legacy shape.
 */
export const registerAdminPostDeleteRoute: ContentRouteRegistrar = (app, deps) => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/posts/:postId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const rawParam = String(req.params.postId ?? "");
    // Admin URLs use the slug when one resolves (2026-08-10) — same resolve-up-front rationale as
    // `posts/update.ts`.
    const postId = (await getAdminPostByIdOrSlug({
      deps: { repo: deps.postRepo },
      input: { workspaceId: deps.workspaceId, idOrSlug: rawParam },
    }).catch(() => null))?.post.id ?? rawParam;
    const idempotencyKey = req.get("Idempotency-Key") || undefined;

    // Full pre-trash record, captured in captureInverse and reused verbatim by rollback so the
    // gateway's unit-of-work compensation restores the post exactly — trash marker and version
    // included — if the change-set record fails to persist after deletePost applies.
    let priorPost: PostRecord | null = null;

    try {
      const principal = getAuthedPrincipal(res);
      const { result } = await executeCommand({
        deps: {
          clock: deps.clock,
          idGen: deps.idGen,
          changeSets: deps.changeSets,
          outbox: deps.outbox,
          authorize: deps.authorize,
        },
        command: {
          workspaceId: deps.workspaceId,
          actor: { id: principal.id, kind: "user" },
          summary: `Delete post ${postId}`,
          idempotencyKey,
          permission: "content.write",
        },
        mutation: {
          entityType: "post",
          entityId: postId,
          operation: "delete",
          captureInverse: async () => {
            priorPost = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id: postId });
            if (!priorPost) return null; // execute() throws PostNotFoundError → 404 below
            // The whole inverse of a soft delete is "clear the marker" — see postDeleteReverter's
            // own doc for why capturing a second copy of the row's fields would be wrong.
            return { deletedAt: null };
          },
          execute: () =>
            deletePost({
              deps: { repo: deps.postRepo, clock: deps.clock, outbox: deps.outbox, remove: deps.removePost },
              input: { workspaceId: deps.workspaceId, id: postId, actorId: principal.id },
            }),
          captureEntityVersion: ({ result }) => result.post.version,
          rollback: async () => {
            if (!priorPost) return;
            // Compensates the post row, its revision ledger AND the Trash index row `deletePost`
            // wrote through the injected `remove` port — `forgetRemoved` drops that row inside the
            // same transaction as the restore, so an undone delete cannot leave a live post listed
            // in the Trash. See `restorePostForward`'s own doc.
            await restorePostForward({
              deps: {
                repo: deps.postRepo,
                clock: deps.clock,
                outbox: deps.outbox,
                forgetRemoved: deps.forgetRemovedPost,
              },
              input: { prior: priorPost, actorId: principal.id },
            });
          },
        },
      });

      // Drains deletePost's `entry.unpublished` event (emitted only when a PUBLISHED row is
      // trashed) to SEO's sitemap-cache invalidation subscriber at once — identical to the inline
      // drain `posts/update.ts` performs, ahead of the background drainer (`serving-app.ts`).
      await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

      res.json(toAdminPostResponse(result.post));
    } catch (err) {
      sendPostDeleteError(res, err);
    }
  });
};

