import { adminFailureResponse } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import express, { type RequestHandler } from "express";
import type { JsonObject } from "@jini-ai/core/primitives";

import { getAdminPostByIdOrSlug, PostNotFoundError } from "#src/features/post/index";
import { renderPostPreview, TemplatePreviewRenderError } from "./template-preview-render.js";
// Clone/draft/theme-branch rationale lives beside renderPostPreview in template-preview-render.ts.
import { getAuthedPrincipal } from "../../dev-auth.js";
import type { ContentRouteRegistrar } from "../content/deps.js";

const PLAIN_TEXT = "text/plain";

/**
 * @file Template-preview fix (2026-08-11, extended 2026-08-12) — `ADS-memory/reports/implementation/
 * 2026-08-11-template-preview-render-bug.md` has the original root-cause writeup. Short version: both
 * editors' Preview tab shows the real published page/post (`siteUrl`, full theme CSS/nav/footer) only
 * when `status === "published" && !dirty`; picking a DIFFERENT template than the one already saved
 * marks the row dirty (by design — it is an unsaved change), which used to fall the preview all the
 * way back to the raw, unstyled body with no template applied at all. That fallback also does not
 * read `templateChoice`, so switching between templates while dirty rendered byte-identical output —
 * "it doesn't re-render" was a symptom of the SAME cause as "it renders with no CSS", not two bugs.
 *
 * This route lets the editor preview the row through a PENDING (possibly unsaved) template choice AND
 * a PENDING body, reusing the exact render pipeline the public site uses (`renderViaTemplate`) rather
 * than a second, drift-prone implementation — the one thing it does differently from a normal page
 * load is override `templateChoice`/`bodyJson` on an in-memory clone of the fetched record before
 * rendering; nothing is written back to storage. Looked up by id via `getAdminPostByIdOrSlug` (any
 * status, unlike the public `getPublishedPostBySlug` the live-site iframe branch uses) rather than by
 * public slug — but the editors deliberately only ROUTE a `status === "published"` row through this
 * endpoint (see `PagePreview`/`PostPreview`'s own doc comments): a draft's own `{"type":"content"}`
 * slot still resolves through `resolveHtmlPageEmbeds`'s visibility-filtered "content" resolver
 * (`resolver-service.ts`'s guard 2), which returns nothing for an unpublished row, so a `GET`-only
 * request for a draft (no pending body attached — still all either editor currently sends for one,
 * as of this paragraph) shows styled chrome around an EMPTY body — confirmed live in this route's own
 * integration test (`admin-post-template-preview.test.ts`'s draft case). The id-based lookup stays
 * status-agnostic at THIS layer regardless: **a `POST` carrying the matching pending body (`bodyJson`
 * or, as of 2026-09-09, `bodyHtml` — see that paragraph below) bypasses this SAME visibility guard for
 * exactly that one already-authorized id**, which is what actually lets a draft preview its real,
 * unsaved content once a caller sends one — the admin UI widening to send one for a draft is tracked
 * separately from this route's own capability.
 *
 * **Pending body (2026-08-12)**: the owner's own reported bug — any content edit (not just a
 * template-picker change) sets `contentDirty`, which used to drop the preview all the way to the raw
 * `SrcDocSandbox` fallback with no theme CSS, because the DIRTY case had no way to hand this route the
 * operator's UNSAVED `bodyJson`. The naive alternative (point the dirty case at this route with only
 * `templateChoice` threaded, as originally built) renders the last-SAVED body — silently stale, worse
 * than the honest unstyled fallback it would replace. Fixed by accepting an optional `bodyJson` on
 * `POST` (see the handler below) and threading it through as
 * `ResolveHtmlPageEmbedsDeps.pendingContentOverride` (`Jini/packages/cms/src/widgets/resolver-service.ts`) — the ONE place
 * the current entity's own `{"type":"content"}` slot re-fetches by id
 * (`findPublishedPostById`/`features/post/post.ts`), silently discarding any in-memory-only override
 * that never reached that call. `GET` (unchanged, still template-choice-only) and `POST` (new, also
 * accepts a pending body) share this same handler — a `GET` request's `req.body` is always empty, so
 * `pendingBodyJson` is `undefined` on every pre-existing caller and that path is byte-for-byte
 * unchanged.
 *
 * **`bodyHtml` (2026-09-09, the `"html"`-format half of the same pending-body fix)**: `bodyJson` only
 * ever helps a `"doc"`-format post/Post — a Page written through the Pages admin editor is
 * `bodyFormat: "html"` and stores `bodyHtml`, not `bodyJson` (`features/post/post.ts`'s
 * `resolveUpdateBodyFields`, `repo.sqlite.ts`'s `toRecord`/inverse-column mapping). Overriding
 * `bodyJson` for an html-format row would do nothing — `renderViaTemplate`'s render path never reads
 * `bodyJson` for an html-format entity's own body (see `resolveHtmlFormatContentMarkers`'s own doc).
 * So this route ALSO accepts an optional `bodyHtml` form/JSON field, extracted by
 * {@link extractPendingBodyHtml} (a plain string — no `JSON.parse` needed, unlike `bodyJson`'s
 * TipTap-document shape) and threaded through as `renderViaTemplate`'s own `pendingBodyHtml`
 * parameter, which that function forwards to {@link resolveHtmlFormatContentMarkers}'s
 * `pendingHtmlOverride` — the equivalent bypass of that function's OWN `findPublishedPostById`
 * visibility guard, for the exact same reason and under the exact same "matches only the one id this
 * caller already fetched and authorized" scoping `pendingContentOverride` already uses for `bodyJson`.
 * The extracted renderer only builds this override when the FETCHED row's own `bodyFormat` is
 * `"html"` — an `bodyHtml` field sent for a `"doc"`-format post is ignored, never applied, since that
 * row has no `bodyHtml` column to preview in the first place.
 *
 * `POST`, not a widened `GET` query string, because a TipTap `bodyJson` document has no realistic
 * upper bound the way a `templateChoice` filename does. The admin client cannot simply point an
 * `<iframe src>` at a `POST` URL (this file's own `GET`-era doc, below, explains why the iframe needs
 * a REAL URL rather than `srcDoc` — root-relative `/theme-assets/...` paths); the real browser
 * mechanism for "POST a body, land on a real URL, inside a specific iframe" is a hidden `<form
 * method="post" target="{iframe name}">` submit — NOT `fetch()` (a `fetch` response is just a string in
 * JS; landing it in the iframe as a REAL document again means either `srcDoc` — the exact thing this
 * route exists to avoid — or a `blob:` URL, whose relative-URL resolution against `/theme-assets/...`
 * is unverified here and would need its own live check before relying on it).
 *
 * A plain HTML form POST always encodes as `application/x-www-form-urlencoded`, never
 * `application/json` — this route accepts BOTH: `app.ts`'s global `express.json({limit: "15mb"})`
 * handles a `fetch`-style JSON POST (if the admin-side implementation ever prefers that transport for
 * something other than the iframe itself), and this route ADDITIONALLY mounts its own
 * `express.urlencoded` on the `POST` registration only (scoped here, not globally in `app.ts`, since no
 * other route needs it) for the classic form-submit case — where `bodyJson` arrives as a
 * JSON-stringified STRING form field, not a parsed object, so {@link isJsonObject}'s check on the raw
 * value is followed by one `JSON.parse` attempt for exactly that shape (see the handler below).
 *
 * Mounted under `/api/admin/v1/workspaces/:workspaceId/posts/:postId/...`, the same URL family
 * `get-by-id.ts`/`update.ts` already use for both Posts and Pages (`PostEditor.tsx`'s own header:
 * "Shared between posts and pages via the same `/admin/posts/{id}` route") — `getAdminPostByIdOrSlug`
 * is kind-blind, so one route serves both editors' Preview tabs. Gated by the same global
 * `requireAdminSession` mount every other `/api/admin/*` route relies on (`app.ts`), so no extra
 * auth wiring is needed here beyond calling `getAuthedPrincipal` the same way `get-by-id.ts` does.
 *
 * Returns `text/html` directly rather than JSON — the client points an `<iframe src>`/form-target
 * straight at this URL (same reasoning `middleware/theme-page-preview.ts` gives for why a themed
 * preview has to be a real URL rather than posted into a `srcDoc` sandbox: the rendered HTML's asset
 * paths are root-relative to `/theme-assets/{themeId}/...`, which only resolves correctly when the
 * browser believes it's looking at a real page, not an inline document).
 */

/** Same minimal "is this a JSON object, not an array/primitive/null" shape check
 * `features/post/post.ts`'s own private `isJsonObject` and `Jini/packages/cms/src/widgets/resolver-service.ts`'s
 * `isPlainObject` use — kept as a separate local copy rather than importing either (neither is
 * exported, and this module already avoids reaching into `features/post`'s internals beyond its
 * published surface). Guards the POST body's `bodyJson` field: a malformed value (string, array,
 * `null`) is rejected here rather than handed to `renderViaTemplate`/`renderDocNode`, which expect an
 * actual TipTap document shape — same defensive shape check `updatePost`'s own `isJsonObject` applies
 * to a SAVED body, just re-applied here for a PENDING one (never persisted either way). */
function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Extracts a validated pending-body override from `req.body.bodyJson`, accepting it in either shape a
 * real caller can produce (see this file's header for why both transports are supported): already a
 * parsed object (`express.json()` — a `fetch`-style JSON POST), or a JSON-stringified STRING
 * (`express.urlencoded()` — a classic `<form>` submit, where every field is a string regardless of
 * what it encodes). A `JSON.parse` failure on the string form, or any other shape (number, boolean,
 * array, already-invalid parsed object), returns `undefined` — the same "malformed input degrades to
 * the saved-body render, never a 400/crash" contract this file's read-only-preview reasoning states
 * elsewhere, since this endpoint has nothing to reject a bad request FOR (it writes nothing).
 */
function extractPendingBodyJson(body: unknown): JsonObject | undefined {
  if (!isJsonObject(body)) return undefined;
  const raw = body.bodyJson;
  if (isJsonObject(raw)) return raw;
  if (typeof raw === "string") {
    try {
      const parsed: unknown = JSON.parse(raw);
      return isJsonObject(parsed) ? parsed : undefined;
    } catch {
      return undefined;
    }
  }
  return undefined;
}

/**
 * Extracts a validated pending-body override from `req.body.bodyHtml` — the `"html"`-format
 * counterpart to {@link extractPendingBodyJson}, above. Simpler than that one: a plain HTML string
 * arrives identically from either transport (`express.json()`'s parsed field or
 * `express.urlencoded()`'s form field are both already strings here — there is no JSON-stringified
 * intermediate shape to `JSON.parse`, unlike a TipTap document). Any non-string value (missing,
 * number, object, array) returns `undefined` — the same "malformed input degrades to the saved-body
 * render, never a 400/crash" contract {@link extractPendingBodyJson} follows, since this endpoint
 * writes nothing and so has nothing to reject a bad request FOR.
 */
function extractPendingBodyHtml(body: unknown): string | undefined {
  if (!isJsonObject(body)) return undefined;
  const raw = body.bodyHtml;
  return typeof raw === "string" ? raw : undefined;
}

/**
 * Tri-state query contract, matching `templateChoice`'s own tri-state (see `resolveTemplate`'s
 * doc): the key absent entirely means "never chosen" (`null`), present but empty
 * (`?templateChoice=`) means the explicit "No template chosen" opt-out (`""`), present with a
 * value means that template filename. The admin client always sends one of the first two shapes
 * explicitly — see `templatePreviewUrl` in `apps/admin/src/lib/api.ts`.
 *
 * @complexity O(1).
 */
function resolveOverrideTemplateChoice(rawTemplateChoice: unknown): string | null {
  return rawTemplateChoice === undefined ? null : String(rawTemplateChoice);
}

/** The preview is author-controlled HTML served from the admin origin. The editors' iframe already
 *  sandboxes it (`PAGE_PREVIEW_IFRAME_SANDBOX`, `apps/admin/src/features/pages/rules.ts`); this header
 *  applies the same flags when the URL is opened on its own, as a top-level tab. Never
 *  `allow-same-origin`: with it, a preview's script could call admin APIs with the session cookie. */
const PREVIEW_CSP = "sandbox allow-scripts allow-forms allow-popups";

export const registerAdminPostTemplatePreviewRoute: ContentRouteRegistrar = (app, deps) => {
  const handlePreviewRequest: RequestHandler = async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).type(PLAIN_TEXT).send("workspace was not found");
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "content.read",
        workspaceId: deps.workspaceId,
      });
      if (!authResult.allowed) {
        res.status(403).type(PLAIN_TEXT).send(`principal '${principal.id}' is not authorized for 'content.read'`);
        return;
      }

      const { post } = await getAdminPostByIdOrSlug({
        deps: { repo: deps.postRepo },
        input: { workspaceId: deps.workspaceId, idOrSlug: String(req.params.postId ?? "") },
      });

      const overrideTemplateChoice = resolveOverrideTemplateChoice(req.query.templateChoice);

      // Pending body override (2026-08-12) — POST-only. `req.body` is parsed by whichever of
      // `express.json()` (`app.ts`'s global mount) or this route's own `express.urlencoded()` (below)
      // matched the request's `Content-Type`; a `GET` request never carries a body, so `req.body` is
      // empty there and `pendingBodyJson` stays `undefined` — the exact "byte-identical to before this
      // existed" behavior this file's header promises for `GET`.
      const pendingBodyJson = extractPendingBodyJson(req.body);
      const pendingBodyHtml = extractPendingBodyHtml(req.body);
      const { html } = await renderPostPreview(deps, {
        post, templateChoice: overrideTemplateChoice,
        bodyJson: pendingBodyJson, bodyHtml: pendingBodyHtml,
      });

      // Never cached: re-requested on every template selection, and a cached response would show
      // the operator a stale template and read as "the picker did nothing" — the exact bug this
      // route exists to fix (mirrors `theme-page-preview.ts`'s identical no-store rule).
      res.set("Cache-Control", "no-store").set("Content-Security-Policy", PREVIEW_CSP).type("html").send(html);
    } catch (err) {
      if (err instanceof TemplatePreviewRenderError) {
        res.status(err.status).type(PLAIN_TEXT).send(err.message);
        return;
      }
      if (err instanceof PostNotFoundError) {
        res.status(404).type(PLAIN_TEXT).send(err.message);
        return;
      }
      const failure = adminFailureResponse({ error: err, tracker: res.locals.adminFailureTracker }, { message: "preview render failed" });
      res.status(failure.status).type(PLAIN_TEXT).send(failure.body.error);
    }
  };

  const path = "/api/admin/v1/workspaces/:workspaceId/posts/:postId/template-preview";
  app.get(path, handlePreviewRequest);
  // `express.urlencoded` scoped to this ONE route's POST registration (not a global `app.ts` mount —
  // no other route needs it) so a classic `<form method="post" target="{iframe}">` submit, which
  // browsers always encode as `application/x-www-form-urlencoded`, populates `req.body` too. A
  // `fetch`-style JSON POST still works unchanged via `app.ts`'s global `express.json()`; Express
  // dispatches to whichever parser matches the request's actual `Content-Type`, so mounting both here
  // is additive, never a double-parse of the same request.
  app.post(path, express.urlencoded({ extended: false, limit: "15mb" }), handlePreviewRequest);
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { DuplicateCommandError, ForbiddenError, executeCommand } from "@jini-ai/cms/core";
import { processOutbox } from "#src/contracts/core/events/index";
import {
  getAdminPostByIdOrSlug,
  parseExpectedVersion,
  PostConflictError,
  PostNotFoundError,
  PostValidationError,
  PostVersionConflictError,
  resolveFeaturedMediaIdForWrite,
  restorePostForward,
  updatePost,
  versionConflictEnvelope,
  type PostRecord,
  type UpdatePostInput,
} from "#src/features/post/index";
import type { Response } from "express";

import { toAdminPostResponse } from "#src/server/inbound/admin-http/http/posts";
import {
  CONTENT_ENTRY_MAX_BODY_BYTES,
  rejectOversizedJsonBody,
} from "#src/server/inbound/shared/body-size-limit";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { sendPluginHookFailedError } from "#src/server/inbound/admin-http/http/plugin-hook-error";
import type { ContentRouteRegistrar } from "../content/deps.js";

/** This route's seven writable PUT fields, read off an untyped body in one place.
 *  Return type is pinned to `UpdatePostInput` itself (minus the id fields the
 *  route supplies separately) rather than left inferred, so a field this route
 *  stops forwarding — or a shape change in `UpdatePostInput` — fails to compile
 *  here instead of surfacing downstream in `updatePost`.
 *  @complexity O(1). */
function parsePostUpdateBody(
  rawBody: unknown
): Pick<
  UpdatePostInput,
  "title" | "slug" | "bodyJson" | "status" | "templateChoice" | "overridesThemePage" | "expectedVersion" | "publishAt" | "featuredMediaId" | "author" | "showAuthor" | "hideCoverImageInBody" | "slugFromTitle"
> {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    title: String(body.title ?? ""),
    slug: String(body.slug ?? ""),
    bodyJson: body.bodyJson as UpdatePostInput["bodyJson"],
    status: body.status as UpdatePostInput["status"],
    templateChoice: body.templateChoice as UpdatePostInput["templateChoice"],
    overridesThemePage: body.overridesThemePage as UpdatePostInput["overridesThemePage"],
    // Omitted ⇒ unchanged, `null` ⇒ cleared; `updatePost` validates both (scheduled publishing /
    // featured image, 2026-10-05).
    publishAt: body.publishAt as UpdatePostInput["publishAt"],
    featuredMediaId: body.featuredMediaId as UpdatePostInput["featuredMediaId"],
    author: body.author as UpdatePostInput["author"],
    showAuthor: body.showAuthor as UpdatePostInput["showAuthor"],
    hideCoverImageInBody: body.hideCoverImageInBody as UpdatePostInput["hideCoverImageInBody"],
    slugFromTitle: body.slugFromTitle as UpdatePostInput["slugFromTitle"],
    // Validated, not cast — see `features/post/expected-version.ts`, which owns this rule for BOTH
    // arms that accept a basis (this route and the `content_post_update` agent tool). Every other
    // field above is either coerced (`title`/`slug`) or handed to `updatePost`'s own validation;
    // this one has no downstream validator at all, because `undefined` is a legitimate value there.
    expectedVersion: parseExpectedVersion(body.expectedVersion),
  };
}

/** Maps this route's thrown error types onto the admin error envelope.
 *  @complexity O(1). */
function sendPostUpdateError(res: Response, err: unknown): void {
  if (sendPluginHookFailedError(res, err)) return;
  if (err instanceof ForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof DuplicateCommandError) {
    res.status(409).json({ error: err.message, code: "DUPLICATE_COMMAND", changeSetId: err.changeSetId });
    return;
  }
  // `code` added 2026-10-05, matching POST /posts and PUT /pages: this was the one post/page write
  // whose validation 400 a client could only tell apart by parsing the message. Additive — `error`
  // is unchanged. The slug-uniqueness 409 and the 404 below stay code-less (see the 409 note).
  if (err instanceof PostValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  // BEFORE the `PostConflictError` branch below, because `PostVersionConflictError` extends it and
  // `instanceof` would otherwise be answered by the superclass first. Both are 409; the `code` is
  // what makes them tellable apart, which is the whole reason this branch exists — a slug collision
  // and "somebody else saved while you were editing" need opposite responses from the editor (fix
  // the slug and resend vs. do NOT resend, you are about to erase someone's work).
  //
  // The slug branch below is left exactly as it was, code-less, on purpose: adding a code there too
  // would be a second, unrequested wire-shape change, and "no code" is already a distinguishable
  // answer for the only two 409s `updatePost` can produce.
  if (err instanceof PostVersionConflictError) {
    // Body built by the shared boundary module, not spelled out here, so the `code` a client
    // branches on has exactly one definition across every arm that can produce this conflict.
    res.status(409).json(versionConflictEnvelope(err));
    return;
  }
  if (err instanceof PostConflictError) {
    res.status(409).json({ error: err.message });
    return;
  }
  if (err instanceof PostNotFoundError) {
    res.status(404).json({ error: err.message });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/posts/update", code: "INTERNAL_ERROR", message: "The post could not be saved." });
}

/**
 * PUT post — routed through the command gateway (SPEC-001 REQ-04).
 *
 * The gateway records an auditable, revertible change set around the existing
 * `updatePost` call. Success response shape is unchanged from before the gateway
 * (REQ-04); a reused `Idempotency-Key` is rejected with `DUPLICATE_COMMAND`.
 *
 * SPEC-006 REQ-05 wiring proof: the gateway now authorizes `content.write`
 * for the real authenticated principal instead of the hardcoded `"user-local"`
 * actor, and runs that check before the idempotency lookup (INV-04) — see
 * `executeCommand`.
 *
 * Optimistic concurrency (2026-09-06) — this route now forwards an optional `expectedVersion` from
 * the request body into `updatePost`. OBSERVABLE BEHAVIOR CHANGE, deliberately: a client that sends
 * it and whose basis has been superseded now gets `409 VERSION_CONFLICT` where the identical request
 * used to get `200` and silently erase the other operator's document. A client that does not send it
 * is unaffected — same last-write-wins behavior as before, pinned by a test.
 *
 * `rejectOversizedJsonBody` (Security review SEC-snapshot-and-post-create-2026-07-28, Finding 1)
 * enforces api.spec.md §4's documented 1 MiB route-layer body cap ahead of the handler — the same
 * cap `posts/create.ts` applies, since §4 scopes it to the update endpoints too — so an oversized
 * request 413s before `updatePost`/the command gateway ever runs.
 */
export const registerAdminPostUpdateRoute: ContentRouteRegistrar = (app, deps) => {
  app.put(
    "/api/admin/v1/workspaces/:workspaceId/posts/:postId",
    rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }),
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      const rawParam = String(req.params.postId ?? "");
      // Admin URLs use the slug when one resolves (2026-08-10) — resolve to the real stable id up
      // front, before the command gateway starts, so `entityId`/`captureInverse`/`updatePost` all
      // key off the same real id even when the URL's own slug is one of the fields being changed in
      // this very request. Falls back to the raw param on no match, which reaches the exact same
      // "not found" 404 path this route already had (captureInverse's own findById returns null).
      const postId = (await getAdminPostByIdOrSlug({
        deps: { repo: deps.postRepo },
        input: { workspaceId: deps.workspaceId, idOrSlug: rawParam },
      }).catch(() => null))?.post.id ?? rawParam;
      const idempotencyKey = req.get("Idempotency-Key") || undefined;

      // Full pre-edit record, captured in captureInverse and reused verbatim by
      // rollback so the gateway's unit-of-work compensation (SPEC-001
      // REQ-01/EC-08/AC-17) restores the post exactly — version included — if the
      // change-set record fails to persist after updatePost applies.
      let priorPost: PostRecord | null = null;

      try {
        // Inside the try: requireAdminSession always sets res.locals.principal before this
        // route runs, but Express 4 doesn't catch a synchronous throw from an async handler
        // outside try/catch (the request would otherwise hang instead of 500ing).
        const principal = getAuthedPrincipal(res);
        const { result } = await executeCommand({
          deps: {
            clock: deps.clock,
            idGen: deps.idGen,
            changeSets: deps.changeSets,
            outbox: deps.outbox,
            authorize: deps.authorize,
          },
          command: {
            workspaceId: deps.workspaceId,
            actor: { id: principal.id, kind: "user" },
            summary: `Update post ${postId}`,
            idempotencyKey,
            permission: "content.write",
          },
          mutation: {
            entityType: "post",
            entityId: postId,
            operation: "update",
            captureInverse: async () => {
              priorPost = await deps.postRepo.findById({ workspaceId: deps.workspaceId, id: postId });
              if (!priorPost) return null; // execute() throws PostNotFoundError → 404 below
              return {
                title: priorPost.title,
                slug: priorPost.slug,
                bodyJson: priorPost.bodyJson,
                status: priorPost.status,
                templateChoice: priorPost.templateChoice ?? null,
                // Tri-state (2026-08-15) — `?? null`, not `?? false`. This is the rollback inverse: if
                // the pre-edit row was genuinely "never decided" (`undefined`/`null`) and the edit that
                // just ran set an explicit `true`/`false`, a gateway rollback must restore "never
                // decided", not silently manufacture an explicit "theme page wins" the author never
                // chose. Coalescing to `false` here would be the exact same coercion bug this whole
                // change removes, just relocated to the one path that only runs on failure.
                overridesThemePage: priorPost.overridesThemePage ?? null,
                // Scheduled publishing / featured image (2026-10-05) — `null` restores "none".
                publishAt: priorPost.publishAt ?? null,
                featuredMediaId: priorPost.featuredMediaId ?? null,
                author: priorPost.author ?? null,
                showAuthor: priorPost.showAuthor ?? false,
                // SPEC-005 BR-08 (T024) — the pre-edit plugin `ext` bag travels in the pre-image
                // alongside the core fields, so one revert restores both together. Spread
                // conditionally: an entry with no `ext` yet must produce an inverse payload with
                // no `ext` key, which is what restores it to "namespace absent" (AC-17).
                ...(priorPost.ext !== undefined ? { ext: priorPost.ext } : {}),
              };
            },
            execute: async () => {
              const body = parsePostUpdateBody(req.body);
              return updatePost({
                deps: {
                  repo: deps.postRepo,
                  clock: deps.clock,
                  outbox: deps.outbox,
                  beforeSaveHook: deps.pluginBeforeSaveHook,
                  slugChangeCapture: deps.slugChangeCapture,
                },
                input: {
                  workspaceId: deps.workspaceId,
                  id: postId,
                  ...body,
                  // The same image check the `content_post_update` chat tool runs (2026-10-05): a video,
                  // unknown or trashed asset is a 400 here, and a media slug is stored as its id. Inside
                  // `execute`, after the gateway's `content.write` check, so an unauthorized caller
                  // cannot probe the media library through this field's error messages.
                  featuredMediaId: await resolveFeaturedMediaIdForWrite({
                    deps: { mediaRepo: deps.mediaRepo, mediaContentTypeStore: deps.mediaContentTypeStore },
                    input: { workspaceId: deps.workspaceId, featuredMediaId: body.featuredMediaId },
                  }),
                  actorId: principal.id,
                  analyticsSource: "admin",
                },
              });
            },
            captureEntityVersion: ({ result }) => result.post.version,
            rollback: async () => {
              if (!priorPost) return;
              await restorePostForward({
                deps: {
                  repo: deps.postRepo,
                  clock: deps.clock,
                  outbox: deps.outbox,
                  forgetRemoved: deps.forgetRemovedPost,
                },
                input: { prior: priorPost, actorId: principal.id },
              });
            },
          },
        });

        // SPEC-008 (ADR-PIPE-008 Decision §5) — drains the outbox so `updatePost`'s
        // `entry.published`/`entry.updated`/`entry.unpublished` event (if any) actually reaches
        // `bus.subscribe`d consumers (SEO's sitemap-cache invalidation) before the response, rather
        // than on the background drainer's next pass (`serving-app.ts`) — mirrors the
        // `/workspaces` route's identical inline `processOutbox` call.
        await processOutbox({ outbox: deps.outbox, bus: deps.bus, clock: deps.clock });

        // Owner-action product event on the draft → published transition only (consent-gated port).
        res.json(toAdminPostResponse(result.post));
      } catch (err) {
        sendPostUpdateError(res, err);
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import {
  getPresentationSettings,
  PresentationSettingsNotFoundError,
  type PresentationSettingsRecord,
} from "#src/features/presentation/index";
import { applicableThemeTemplates, findStoredTheme, validThemeIds, isPackageShippedTheme, type ThemeTemplateKind } from "#src/features/theme/index";
import { themeCardPreviewUrl } from "#src/features/theme/theme-preview-image";
import { themePreviewServiceForHost } from "#src/server/runtime/lifecycle/theme-preview-host";
import { registerAdminThemePreviewRoute } from "../themes/preview.js";
import { toAdminPresentationResponse } from "#src/server/inbound/admin-http/http/presentation";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteDeps, ContentRouteRegistrar } from "../content/deps.js";

function activeThemeResponseFields(
  { themes, settings, kind }: {
    themes: ContentRouteDeps["themes"];
    settings: PresentationSettingsRecord;
    kind?: ThemeTemplateKind;
  },
  _optional: Record<string, never> = {},
) {
  // Template-picker feature (2026-08-10, unified 2026-08-11) — the active theme's own declared
  // template list, so BOTH the Post editor's and the Pages editor's pickers always reflect
  // whichever theme is actually live right now (one shared field since the unified `content`
  // marker — see `AdminPresentation.activeThemeTemplates`'s own doc).
  // `findStoredTheme`, not an exact match: a stored retired id (`basic`, renamed `tovu-theme`)
  // still names the active theme, and the response reports the id the theme list shows.
  const activeTheme = findStoredTheme({ themes, id: settings.activeThemeId });
  // Editors request their kind; catalog callers omit it and retain the full list.
  const activeThemeTemplates = applicableThemeTemplates({ manifest: activeTheme?.manifest, kind });
  // Slug-collision override (2026-08-10) — every page id the active theme ships, so the editor
  // can warn when a post's own slug is currently claimed by one of the theme's own pages.
  const activeThemeStaticPageIds = activeTheme ? Object.keys(activeTheme.pages) : [];
  return {
    settings: activeTheme
      ? { ...settings, activeThemeId: activeTheme.manifest.id }
      : settings,
    activeThemeTemplates,
    activeThemeStaticPageIds,
  };
}

/**
 * GET presentation settings (active theme + available themes).
 *
 * Gated by the existing `theme.set` permission — there is no dedicated read permission for
 * presentation settings in the catalog, and `activeThemeId` is currently the only field this
 * resource has, so the same permission that gates changing it also gates reading it (same
 * single-permission-per-domain reasoning as `member.manage`). Disclosed explicitly in the
 * Programmer handoff since this reuses a write-shaped permission name for a read route.
 */
export const registerAdminPresentationGetRoute: ContentRouteRegistrar = (app, deps) => {
  // The image route behind every card URL this listing hands out, registered with it so the two
  // cannot be mounted apart.
  registerAdminThemePreviewRoute({ app, deps });
  app.get("/api/admin/v1/workspaces/:workspaceId/presentation", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const kind = req.query.kind;
      if (kind !== undefined && kind !== "post" && kind !== "page") {
        res.status(400).json({ error: "kind must be 'post' or 'page'" });
        return;
      }
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "theme.set",
        workspaceId: deps.workspaceId,
        entityType: "presentation",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'theme.set' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "theme.set", reason: authResult.reason },
        });
        return;
      }

      // **Deliberately NOT the write allowlist.** This list is echoed straight back to the client as
      // `AdminPresentation.availableThemeIds` and is what the admin's theme picker renders one card
      // per entry from — it is a READ CATALOGUE of themes an operator can pick, not a set of values
      // the API will accept.
      //
      // `patch-active-theme.ts` passes a DIFFERENT list through an identically-named field: its
      // `writableThemeIds` appends `NO_THEME_ID` so "turn the theme off" is a storable value. That
      // sentinel must never appear HERE — it would render as a blank card in the picker, with no
      // type error, no failing test and no gate to catch it. The two expressions used to be
      // character-for-character identical, which is exactly why this note exists on the side that
      // did not change: a reader reducing duplication in this directory sees two identical calls in
      // sibling files and no reason not to merge them. There is one, and it is this.
      const result = await getPresentationSettings({
        deps: { repo: deps.presentationRepo, availableThemeIds: validThemeIds(deps.themes) },
        input: { workspaceId: deps.workspaceId },
      });

      const { settings, activeThemeTemplates, activeThemeStaticPageIds } = activeThemeResponseFields({
        themes: deps.themes, settings: result.settings, kind,
      });
      // Card previews are captures of each theme's own render where this site can take them (see
      // `routes/themes/preview.ts`); elsewhere the shipped `screenshots/` file, as before.
      const capturesEnabled = deps.siteBinding !== undefined && themePreviewServiceForHost({ binding: deps.siteBinding }) !== undefined;
      // Themes admin screen (2026-08-10) — tier alongside id for every valid theme, so the Themes
      // screen can group cards by tier without a second round trip. Filtered to `status === "valid"`
      // to match `validThemeIds`'s own filter above (an invalid theme is not one an operator can pick).
      // `builtIn` (2026-10-10): a theme the package ships, which the card menu won't offer to delete.
      const availableThemes = deps.themes
        .filter((t) => t.status === "valid")
        .map((t) => ({ id: t.manifest.id, name: t.manifest.name, tier: t.manifest.tier, apiVersion: t.manifest.apiVersion,
          builtIn: isPackageShippedTheme({ manifest: t.manifest, packageThemesRoot: deps.packageThemesDir }),
          previewImageUrl: themeCardPreviewUrl({ theme: { dir: t.dir, id: t.manifest.id, tier: t.manifest.tier }, workspaceId: deps.workspaceId }, { capturesEnabled }) }));

      res.json(
        toAdminPresentationResponse({
          settings,
          availableThemeIds: result.availableThemeIds,
          availableThemes,
          activeThemeTemplates,
          activeThemeStaticPageIds,
        })
      );
    } catch (err) {
      if (err instanceof PresentationSettingsNotFoundError) {
        res.status(404).json({ error: err.message });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/presentation/get", code: "INTERNAL_ERROR" });
    }
  });
};

import { adminFailureResponse, type AdminFailurePorts } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import {
  PresentationSettingsNotFoundError,
  PresentationSettingsValidationError,
  setActiveTheme,
} from "#src/features/presentation/index";
import { findStoredTheme, validThemeIds, writableThemeIds, requestThemePreviewRefresh, ThemeStylingRequiredError } from "#src/features/theme/index";
import { toAdminPresentationResponse } from "#src/server/inbound/admin-http/http/presentation";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteRegistrar } from "../content/deps.js";

/**
 * PATCH the active theme.
 *
 * Gated by the existing `theme.set` permission, checked directly via `authorize()` — mirrors
 * `members/disable.ts`'s pattern since `setActiveTheme` is a direct feature call, not routed
 * through the SPEC-001 command gateway.
 */

/**
 * Reads the PATCH body's `activeThemeId`, defaulting to `""` for a missing/non-object body or a
 * missing field. `setActiveTheme`'s own `allowed.includes("")` check then turns that into a
 * `PresentationSettingsValidationError` naming the empty string, so a malformed body reads as "no
 * theme id" rather than a raw parse failure.
 *
 * Pulled out of the route handler purely to bring its cyclomatic complexity back under this repo's
 * gate — the `?.`/`??` here are two decision points genuinely independent of the handler's own
 * control flow (no nesting relationship), not a behavior change.
 */
function readActiveThemeId(body: unknown): string {
  return String((body as { activeThemeId?: unknown } | null)?.activeThemeId ?? "");
}

/**
 * Maps a caught error from `setActiveTheme` to its status/body. Pulled out of the route handler for
 * the same reason as {@link readActiveThemeId}: the error-category checks are independent decision
 * points that add to cyclomatic complexity without adding nesting, so moving them here is a pure
 * complexity-gate fix — still the same 400/404/500 statuses and bodies as before.
 */
function presentationPatchErrorResponse(err: unknown, options: AdminFailurePorts = {}): { status: number; body: { error: string } } {
  if (err instanceof PresentationSettingsValidationError || err instanceof ThemeStylingRequiredError) {
    return { status: 400, body: { error: err.message } };
  }
  if (err instanceof PresentationSettingsNotFoundError) {
    return { status: 404, body: { error: err.message } };
  }
  return adminFailureResponse({ error: err, tracker: options.tracker }, { operation: "routes/presentation/patch-active-theme" });
}

export const registerAdminPresentationPatchRoute: ContentRouteRegistrar = (app, deps) => {
  app.patch("/api/admin/v1/workspaces/:workspaceId/presentation", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "theme.set",
        workspaceId: deps.workspaceId,
        entityType: "presentation",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'theme.set' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "theme.set", reason: authResult.reason },
        });
        return;
      }

      const result = await setActiveTheme({
        deps: {
          repo: deps.presentationRepo,
          tracker: deps.tracker,
          clock: deps.clock,
          availableThemeIds: writableThemeIds(deps, { requestedThemeId: readActiveThemeId(req.body) }),
        },
        input: {
          workspaceId: deps.workspaceId,
          activeThemeId: readActiveThemeId(req.body),
        },
      }, { actorId: principal.id, source: "admin" });

      // Template-picker feature (2026-08-10, unified 2026-08-11) — recomputed from the NEWLY active
      // theme (not the one that was active before this PATCH), so switching themes immediately
      // updates what BOTH pickers offer, matching `get.ts`'s identical computation.
      const activeTheme = findStoredTheme({ themes: deps.themes, id: result.settings.activeThemeId });
      requestThemePreviewRefresh({ themesDir: deps.themesDir });
      const activeThemeTemplates = activeTheme?.manifest.templates ?? [];
      const activeThemeStaticPageIds = activeTheme ? Object.keys(activeTheme.pages) : [];
      // Themes admin screen (2026-08-10) — same computation as `get.ts`, so a theme switch's
      // response keeps the tab-grouping data in sync without a follow-up GET.
      const availableThemes = deps.themes
        .filter((t) => t.status === "valid")
        .map((t) => ({ id: t.manifest.id, name: t.manifest.name, tier: t.manifest.tier, apiVersion: t.manifest.apiVersion }));

      res.json(
        toAdminPresentationResponse({
          settings: result.settings,
          // `validThemeIds(deps.themes)`, NOT `result.availableThemeIds` — this ONE request carries
          // both lists, and they are not the same list. `result.availableThemeIds` is the write
          // allowlist echoed back by `setActiveTheme` (the caller-supplied set it validated
          // against), so it contains `NO_THEME_ID`; this field is the READ CATALOGUE the admin's
          // theme picker renders one card per entry from, exactly as in `get.ts`. Passing the
          // allowlist through would have put a blank card in the picker on the very request that
          // turns the theme off — i.e. only in the state where it is least likely to be noticed as
          // this route's doing. See `writableThemeIds`'s own doc (`features/theme/active-theme.ts`).
          availableThemeIds: validThemeIds(deps.themes),
          availableThemes,
          activeThemeTemplates,
          activeThemeStaticPageIds,
        })
      );
    } catch (err) {
      const { status, body } = presentationPatchErrorResponse(err, { tracker: res.locals?.adminFailureTracker });
      res.status(status).json(body);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { duplicateThemeIds, rescanThemes, validThemeIds } from "#src/features/theme/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { ContentRouteRegistrar } from "../content/deps.js";

/**
 * POST — re-run theme discovery against the themes directory.
 *
 * Exists because discovery is otherwise a boot-time snapshot (see `rescanThemes`), so a theme that
 * arrives on disk after startup is invisible until the process restarts. Two different things put
 * one there: an in-app action (copy an original), which should rescan
 * on its own without anyone asking, and an out-of-band change (git pull, our own CLI, a folder
 * dropped in by hand), which nothing can hook — that second case is what this route is for, and why
 * the admin needs a visible control rather than only an implicit refresh.
 *
 * Gated on `theme.set`, matching the GET and PATCH on this same resource: rescanning cannot change
 * what any theme contains, but it changes which themes an operator can activate, so it belongs with
 * the permission that governs the theme surface rather than being left ungated.
 *
 * Reports `added`/`removed` rather than a bare 204 — a rescan that found nothing looks exactly like a
 * rescan that never ran, and "I pressed it and nothing happened" is the whole failure this route is
 * meant to end.
 */
export const registerAdminThemeRescanRoute: ContentRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/themes/rescan", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "theme.set",
        workspaceId: deps.workspaceId,
        entityType: "presentation",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'theme.set' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "theme.set", reason: authResult.reason },
        });
        return;
      }

      const changed = rescanThemes({ themes: deps.themes, dir: deps.themesDir });

      res.json({
        added: changed.added,
        removed: changed.removed,
        total: changed.total,
        availableThemeIds: validThemeIds(deps.themes),
        // Two themes can claim the same id (ids are unique per folder, not globally), in which case
        // the site silently renders whichever sorts first. Reported here rather than swallowed,
        // because a rescan is exactly when a colliding theme most likely just arrived.
        duplicateIds: duplicateThemeIds(deps.themes),
      });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/presentation/rescan-themes", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { BackstopRefusal } from "#src/features/publish-content/backstop-policy";
import type { Request, Response } from "express";
import { nowIso } from "@jini-ai/core/primitives";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import { BACKSTOP_FORBIDDEN, mayUseBackstop, validateBackstopRequest, readBackstopMetadata, runAuditedBackstop } from "#src/features/publish-content/backstop-service";
import type { BackstopAuditPort, BackstopAuditRecord, BackstopInverse } from "#src/features/publish-content/backstop-audit";
import type { BackstopPorts, BackstopSelection, RawFilePort } from "#src/features/publish-content/backstop-ports";
import { contributeRawRowPublish, undoRawRow } from "#src/features/publish-content/raw-row-contributor";
import { contributeRawFilePublish, undoRawFile } from "#src/features/publish-content/raw-file-contributor";
import type { PackedEntity, PublishContentDeps, SkippedPackEntity } from "#src/features/publish-content/type-registry";
import { CONTENT_HASH_VERSION } from "#src/features/publish-content/content-hash";
import { entityKey } from "#src/features/publish-content/planner";
import { PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION } from "#src/features/publish-content/artifact-format";
import { createCompositePeerBlobSource } from "#src/features/publish-content/composite-blob-source";
import { computeBlobStorageKey } from "#src/features/media/index";
import { resolvePublishDestinationCredential } from "#src/features/publish-content/destination-credential";
import { pushBundleToPeer, confirmPeerImport, executePeerImport, type PeerCallDeps } from "#src/features/publish-content/peer-transport";
import type { PublishContentPeerRecord } from "#src/features/publish-content/peers";
import { toPublishContentDeps, type PublishContentRouteDeps, type PublishContentRouteRegistrar } from "./deps.js";
