import { respondWithError } from "./peer-transport.js";

/** Whether `actorId` may send by hand: the `publish.backstop` permission AND the owner or a
 *  built-in admin/owner role. @complexity O(r) role reads. */
async function mayActorUseBackstop(deps: PublishContentRouteDeps, actorId: string): Promise<boolean> {
  const allowed = await deps.authorize({ principalId: actorId, permission: "publish.backstop", workspaceId: deps.workspaceId });
  return allowed.allowed && mayUseBackstop({ actorId, ownerId: await deps.ownerPrincipalId, roles: { list: async () => {
    const links = await deps.principalRoleRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: actorId });
    const roles = await Promise.all(links.map((link) => deps.roleRepo.findById({ workspaceId: deps.workspaceId, id: link.roleId })));
    return roles.filter((role): role is NonNullable<typeof role> => role !== null);
  } } });
}

/** Session-only: neither an API key nor an assistant can perform the manual confirmation.
 *  @returns the actor id, or `null` once the 403 has been sent. */
async function backstopActorId(res: Response, deps: PublishContentRouteDeps): Promise<string | null> {
  if (!rejectUnlessSessionCredential(res, { message: BACKSTOP_FORBIDDEN, permission: "publish.backstop" })) return null;
  const id = getAuthedPrincipal(res).id;
  if (await mayActorUseBackstop(deps, id)) return id;
  res.status(403).json({ error: BACKSTOP_FORBIDDEN, code: "FORBIDDEN" });
  return null;
}

/** The audit port when its storage is installed, else `null`. @complexity O(1) plus one probe. */
async function readyAudit(audit: BackstopAuditPort | undefined): Promise<BackstopAuditPort | null> {
  return audit && (await audit.ready()) ? audit : null;
}

/** A destination-side run can be undone after a success, or after a failure that recorded inverses. */
function hasUndo(log: BackstopAuditRecord): boolean {
  return log.result === "success" || (log.result === "failure" && log.inverses.length > 0);
}

/** The checked request a send/plan acts on. */
interface BackstopTarget {
  peerId: string;
  destination: PublishContentPeerRecord;
  host: string;
  request: { reason: string; typedHost: string; selection: BackstopSelection };
}

/** Reads the peer, its live address and the operator's confirmation off a send/plan body.
 *  @complexity O(n) in the selected rows/files, plus one peer read. */
async function readBackstopTarget(body: Record<string, unknown>, deps: PublishContentRouteDeps): Promise<BackstopTarget | RouteRefusal> {
  const peerId = body.peerId;
  if (typeof peerId !== "string") return { status: 400, body: { error: "Choose a connected live site.", code: "VALIDATION_ERROR" } };
  const destination = await deps.publishContentPeerRepo.findById({ workspaceId: deps.workspaceId, id: peerId });
  if (!destination) return { status: 404, body: { error: "The connected live site was not found." } };
  const host = new URL(destination.baseUrl).host;
  // Checking is not the human confirmation. A supplied wrong host still fails, but the UI
  // leaves this field empty until the operator has seen the plan. Send always requires it.
  const checked = validateBackstopRequest({ body: body.action === "plan" && body.typedHost === undefined
    ? { ...body, typedHost: host } : body, destinationHost: host });
  if ("error" in checked) return { status: 400, body: { error: checked.error, code: "VALIDATION_ERROR" } };
  return { peerId, destination, host, request: checked.request };
}

/** Everything one send/plan request carries once its target is checked and audit is ready. */
interface BackstopRun {
  deps: PublishContentRouteDeps;
  actorId: string;
  target: BackstopTarget;
  audit: BackstopAuditPort;
  projection: PublishContentDeps;
  backstop: BackstopPorts;
}

/** The per-call transport bag for this run's peer, with its backstop-scoped credential. */
async function openBackstopPeer(deps: PublishContentRouteDeps, peerId: string): Promise<PeerCallDeps> {
  return { httpClient: deps.publishContentPeerHttpClient,
    publishHistory: { store: deps.publishHistoryStore, workspaceId: deps.workspaceId, clock: deps.clock }, credential: await resolvePublishDestinationCredential({ deps: {
    repo: deps.publishContentPeerRepo, sealer: deps.siteAssistantSecretSealer, keyring: deps.siteAssistantSecretKeyring, httpClient: deps.publishContentPeerHttpClient,
  }, input: { workspaceId: deps.workspaceId, id: peerId, backstop: true } }) };
}

/** The checked plan `send` redeems: this actor's own `planned` source log for the same
 *  destination, reason and peer. Anything else must be checked again. */
function isSendablePlan(log: BackstopAuditRecord | null, run: BackstopRun): log is BackstopAuditRecord {
  if (log === null || log.direction !== "source" || log.actorId !== run.actorId) return false;
  return log.destination === run.target.destination.baseUrl && log.result === "planned" &&
    log.reason === run.target.request.reason && log.details.peerId === run.target.peerId;
}

/** `send`: confirms and executes the plan a previous `plan` call recorded. */
async function sendCheckedPlan(res: Response, run: BackstopRun, logId: unknown): Promise<void> {
  const { deps, audit } = run;
  const log = typeof logId === "string" ? await audit.get({ workspaceId: deps.workspaceId, id: logId }) : null;
  if (!isSendablePlan(log, run)) {
    res.status(409).json({ error: "Check what would change again before sending." }); return;
  }
  const result = await runAuditedBackstop({ audit, record: log, work: async () => {
    const peer = await openBackstopPeer(deps, run.target.peerId);
    const plan = log.details.plan as Record<string, unknown>;
    const confirmation = await confirmPeerImport(peer, { planId: String(plan.planId), planHash: String(plan.planHash) });
    return executePeerImport(peer, { bundleId: String(log.details.bundleId), confirmationToken: confirmation.confirmationToken,
      overwriteEntityKeys: log.details.overwriteEntityKeys as string[] | undefined });
  } });
  res.json({ ...result, logId: log.id, destination: run.target.destination.baseUrl });
}

/** Packs the selected raw rows and files, and what each contributor had to skip. */
async function packSelection(run: BackstopRun): Promise<{ entities: PackedEntity[]; skipped: SkippedPackEntity[] }> {
  const entities: PackedEntity[] = [];
  const skipped: SkippedPackEntity[] = [];
  for (const contributor of [contributeRawRowPublish(), contributeRawFilePublish()]) {
    const handler = contributor.build({ ...run.projection, backstop: run.backstop });
    for await (const entity of handler.pack()) entities.push(entity);
    skipped.push(...await handler.listSkipped!());
  }
  return { entities, skipped };
}

/** `overwriteEntityKeys` may only name items this plan selected. @complexity O(k) in the keys. */
function overwriteKeysAreSelected(overwriteEntityKeys: unknown, entities: readonly PackedEntity[]): overwriteEntityKeys is string[] | undefined {
  if (overwriteEntityKeys === undefined) return true;
  const keys = new Set(entities.map((entity) => entityKey(entity.entityType, entity.id)));
  return Array.isArray(overwriteEntityKeys) && overwriteEntityKeys.every((key) => typeof key === "string" && keys.has(key));
}

/** `plan`: packs the selection, pushes it to the peer as a staged bundle, and records the
 *  peer's plan as this actor's `planned` source log for `send` to redeem. */
async function planSelection(res: Response, run: BackstopRun, overwriteEntityKeys: unknown): Promise<void> {
  const { deps, actorId, target, audit } = run;
  const { entities, skipped } = await packSelection(run);
  if (entities.length === 0) { res.json({ entities: [], skipped, logId: null }); return; }
  const metadata = { mode: "backstop" as const, reason: target.request.reason, sourceActor: actorId, destinationHost: target.host, gapLabels: [] };
  const carrying = entities.map((entity) => ({ ...entity, backstop: metadata }));
  const verifiedMetadata = readBackstopMetadata({ entities: carrying })!;
  const auditedEntities = entities.map((entity) => ({ ...entity, backstop: verifiedMetadata }));
  if (!overwriteKeysAreSelected(overwriteEntityKeys, entities)) {
    res.status(400).json({ error: "Only selected items can be overwritten.", code: "VALIDATION_ERROR" }); return;
  }
  const overwrite = overwriteEntityKeys === undefined ? {} : { overwriteEntityKeys };
  const record: BackstopAuditRecord = { id: deps.idGen.newId(), workspaceId: deps.workspaceId, direction: "source", actorId,
    destination: target.destination.baseUrl, reason: target.request.reason, at: nowIso({ clock: deps.clock }), gapLabels: verifiedMetadata.gapLabels,
    items: entities.map((e) => ({ entityType: e.entityType, id: e.id, afterHash: e.contentHash })), result: "pending", runId: null, details: {}, inverses: [] };
  const result = await runAuditedBackstop({ audit, record, successResult: "planned", work: async () => {
    const peer = await openBackstopPeer(deps, target.peerId);
    const pushed = await pushBundleToPeer({ ...peer, blobSource: createCompositePeerBlobSource({ blobStore: deps.blobStore, fileBlobIndex: deps.fileBlobIndex }),
      computeStorageKey: (sha256) => computeBlobStorageKey({ workspaceId: deps.workspaceId, sha256 }) }, {
      bundle: { artifactFormatVersion: PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION, hashVersion: CONTENT_HASH_VERSION,
        sourceLabel: deps.workspaceId, entities: auditedEntities, blobManifest: [...new Set(entities.flatMap((e) => e.requiredBlobs))], skipped },
      ...overwrite,
    });
    if (pushed.notSupportedByLive.length > 0) throw new BackstopRefusal({ message: "Live can't accept send by hand yet; update live and enable its backstop grant." });
    return { ...pushed, peerId: target.peerId, entities, skipped, ...overwrite };
  } });
  res.json({ ...result, logId: record.id });
}

/** `POST .../backstop`: the source side of send by hand (`plan`, then `send`). */
async function handleBackstopRequest(req: Request, res: Response, deps: PublishContentRouteDeps): Promise<void> {
  const actorId = await backstopActorId(res, deps); if (!actorId) return;
  const body = bodyRecord(req.body);
  const target = await readBackstopTarget(body, deps);
  if ("status" in target) { sendRefusal(res, target); return; }
  const projection = toPublishContentDeps(deps);
  const backstop = { ...projection.backstop!, selection: target.request.selection };
  const audit = await readyAudit(backstop.audit);
  if (!audit) { res.status(503).json({ error: "Send by hand needs its audit storage installed before it can send anything.", code: "BACKSTOP_NOT_INSTALLED" }); return; }
  const run: BackstopRun = { deps, actorId, target, audit, projection, backstop };
  if (body.action === "send") { await sendCheckedPlan(res, run, body.logId); return; }
  if (body.action !== "plan") { res.status(400).json({ error: "Choose Check what would change or Send to live." }); return; }
  await planSelection(res, run, body.overwriteEntityKeys);
}

/** Undoes one recorded inverse. A restored file's prior bytes are captured first and queued on
 *  `fileRollbacks`, so a later failure in the same transaction can put the file back.
 *  @returns the reason the item was left alone, or `null` once it is undone. */
async function undoInverse(
  { inverse, projection, files, fileRollbacks }: { inverse: BackstopInverse; projection: PublishContentDeps; files: RawFilePort; fileRollbacks: Array<() => Promise<void>> }
): Promise<string | null> {
  if (inverse.kind === "raw-row") return undoRawRow({ deps: projection, ...inverse });
  const beforeUndo = await files.capture({ relPath: inverse.entity.id });
  const reason = await undoRawFile({ deps: projection, ...inverse });
  if (!reason) fileRollbacks.push(() => files.restore({ inverse: beforeUndo }));
  return reason;
}

/** `POST .../runs/:runId/undo-backstop`: the destination side's one-click undo. */
async function handleUndoRequest(req: Request, res: Response, deps: PublishContentRouteDeps): Promise<void> {
  if (!(await backstopActorId(res, deps))) return;
  const projection = toPublishContentDeps(deps);
  // `files` is always present here: `PublishContentRouteDeps` requires `siteBinding`, which is
  // what `buildPublishBackstopPorts` builds the file port from.
  const { audit, rows, files } = projection.backstop!;
  if (!audit || !rows || !(await audit.ready())) { res.status(503).json({ error: "Send by hand needs its audit storage installed." }); return; }
  const log = await audit.get({ workspaceId: deps.workspaceId, id: String(req.params.runId) });
  if (!log || log.direction !== "destination" || !hasUndo(log)) { res.status(404).json({ error: "This send has no undo available." }); return; }
  const skipped: string[] = [];
  const fileRollbacks: Array<() => Promise<void>> = [];
  try {
    await rows.transaction({ work: async () => {
      for (const inverse of [...log.inverses].reverse()) {
        const reason = await undoInverse({ inverse, projection, files: files!, fileRollbacks });
        if (reason) skipped.push(reason);
      }
      await audit.save({ record: { ...log, result: "undone", details: { ...log.details, undoSkipped: skipped } } });
    } });
  } catch (error) {
    for (const rollback of fileRollbacks.reverse()) { await rollback(); }
    throw error;
  }
  res.json({ runId: log.runId, undone: log.inverses.length - skipped.length, skipped });
}

/** Session-only: neither an API key nor an assistant can perform the manual confirmation. */
export const registerPublishBackstopRoutes: PublishContentRouteRegistrar = (app, deps) => {
  const base = "/api/admin/v1/workspaces/:workspaceId/publish-content";
  app.get(`${base}/backstop/status`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if (!(await backstopActorId(res, deps))) return;
      const audit = await readyAudit(toPublishContentDeps(deps).backstop?.audit);
      res.json({ allowed: true, installed: audit !== null });
    } catch (error) { sendAdminFailure({ res, error }, { operation: "routes/publish-content/backstop", code: "INTERNAL_ERROR", message: "Manual publishing availability could not be read." }); }
  });
  app.get(`${base}/runs/:runId/backstop`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if (!(await backstopActorId(res, deps))) return;
      const audit = await readyAudit(toPublishContentDeps(deps).backstop?.audit);
      if (!audit) { res.status(503).json({ error: "Send by hand needs its audit storage installed.", code: "BACKSTOP_NOT_INSTALLED" }); return; }
      const log = await audit.get({ workspaceId: deps.workspaceId, id: String(req.params.runId) });
      if (!log || log.direction !== "destination") { res.status(404).json({ error: "This send was not found on this site." }); return; }
      res.json({ runId: log.runId, reason: log.reason, items: log.items.map(({ entityType, id }) => ({ entityType, id })), canUndo: hasUndo(log) });
    } catch (error) { sendAdminFailure({ res, error }, { operation: "routes/publish-content/backstop", code: "INTERNAL_ERROR", message: "This send could not be read." }); }
  });
  app.post(`${base}/backstop`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      await handleBackstopRequest(req, res, deps);
    } catch (error) {
      if (error instanceof BackstopRefusal) { res.status(409).json({ error: error.message }); return; }
      respondWithError(res, error, { message: "This send could not complete." });
    }
  });

  app.get(`${base}/backstop/gaps`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      const principal = getAuthedPrincipal(res);
      const allowed = await deps.authorize({ principalId: principal.id, permission: "publish_content.read", workspaceId: deps.workspaceId });
      if (!allowed.allowed) { res.status(403).json({ error: "Publishing history is not available to this account." }); return; }
      const audit = await readyAudit(toPublishContentDeps(deps).backstop?.audit);
      res.json({ gaps: audit ? await audit.gaps({ workspaceId: deps.workspaceId }) : [] });
    } catch (error) { sendAdminFailure({ res, error }, { operation: "routes/publish-content/backstop", code: "INTERNAL_ERROR", message: "Publishing history could not be read." }); }
  });

  app.post(`${base}/runs/:runId/undo-backstop`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      await handleUndoRequest(req, res, deps);
    } catch (error) {
      if (error instanceof BackstopRefusal) { res.status(409).json({ error: error.message }); return; }
      respondWithError(res, error, { message: "This send could not be undone." });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { isDocumentOnlyBlob } from "@jini-ai/cms/media";
import { computeBlobStorageKey } from "@jini-ai/cms/media";

import { isValidSha256Hex } from "#src/features/publish-content/blob-staging";
import { createCompositePeerBlobSource } from "#src/features/publish-content/composite-blob-source";
import { TOVU_MAX_UPLOAD_BYTES } from "#src/features/media/index";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

import type { PublishContentRouteRegistrar } from "./deps.js";

/**
 * `GET /api/admin/v1/workspaces/:workspaceId/publish-content/blobs/:sha` — the DOWNLOAD half of the
 * blob channel, added 2026-09-19 to close a live gap: the push direction could upload bytes
 * (`blob-put.ts`) and ask what was missing (`blobs-probe.ts`), but nothing could fetch bytes back,
 * so a PULLED media entity always failed closed as `blocked` (`features/publish-content/
 * peer-transport.ts`'s own "KNOWN GAP" note). This route is that missing verb, and nothing else —
 * it is deliberately additive, and the pull architecture around it is untouched.
 *
 * ## Authorization: `publish_content.read`, and why that is not weaker than the upload path
 *
 * `blob-put.ts` gates on `publish_content.apply`; this route gates on `publish_content.read`. That
 * is a deliberate direction call, not a relaxation:
 *
 * - **Same holder set today.** `features/publish-content/permissions.ts` grants BOTH permissions to
 *   exactly one built-in role (`admin`), plus the seeded owner's `*` wildcard. No principal can
 *   reach this route that could not already reach `blob-put.ts`, and `editor`/`viewer` reach
 *   neither.
 * - **Same exposure as the route that reveals the shas.** `export.ts` gates on
 *   `publish_content.read` and hands out `blobManifest` — the list of shas — to exactly this holder
 *   set. Gating the bytes on the same permission means the bytes are never reachable by a principal
 *   who could not have learned the sha in the first place.
 * - **`apply` here would be a real privilege escalation.** A pull-only peer credential calls
 *   `GET .../export` and then this route. If the download demanded `apply`, every pull-only key
 *   would have to hold the permission that lets it WRITE content into the source instance. Demanding
 *   a write permission for a read is stricter on paper and strictly worse in practice.
 *
 * ## The threat this route must not become
 *
 * Content-addressed storage means a leaked or guessed sha is a read capability IF knowing the hash
 * is sufficient. It is not sufficient here. Three things close it, in order:
 *
 * 1. The mount-path workspace guard — the same `!== deps.workspaceId` 404 every route in this
 *    directory opens with.
 * 2. A real permission check against the AUTHENTICATED principal (above). Knowing a sha — even
 *    having uploaded those very bytes under `publish_content.apply` — grants nothing;
 *    `__tests__/../publish-content-blob-get.test.ts` pins that case directly.
 * 3. The storage key is DERIVED, never accepted: `computeBlobStorageKey({workspaceId, sha256})`
 *    with this composition's own `workspaceId`. A caller supplies 64 hex characters and nothing
 *    else, so there is no path/traversal surface and no way to address another workspace's bytes.
 *
 * ## Why the response is base64 JSON rather than octet-stream, and why it buffers
 *
 * The only consumer is `peer-transport.ts`'s driver, which speaks through ADR-038's
 * `HttpClientPort` — a fully-materialized `{status, headers, bodyText}` response, not a stream. A
 * JSON body mirrors `blob-put.ts`'s own `dataBase64` request shape exactly, so the two directions
 * agree. Buffering is not a choice this route can avoid either: `BlobStorePort.get()` returns
 * `Promise<Uint8Array>` — the port exposes no streaming read, and every existing consumer
 * (`routes/media/original.ts`, `public-http/.../media-rendition.ts`) buffers the same way. Memory is
 * therefore bounded by {@link TOVU_MAX_UPLOAD_BYTES} per request, enforced below, which also keeps
 * the base64 body (≈4/3 of 50 MiB as of 2026-09-21, ≈66.7 MiB) under the peer policy's 96 MiB
 * `maxResponseBytes` cap (`PUBLISH_CONTENT_PEER_MAX_RESPONSE_BYTES`, raised from 64 MiB alongside it).
 *
 * ## Why this does not re-hash the bytes before sending
 *
 * The receiver does, and the receiver's check is the one that matters: `pullBlobsFromPeer` hashes
 * what arrived and refuses to store a mismatch. That covers a poisoned store, a corrupted transfer
 * AND a hostile peer, which a server-side check cannot. Hashing here too would double the CPU per
 * download to re-prove a property the only trust boundary already enforces.
 */
export const registerPublishContentBlobGetRoute: PublishContentRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/publish-content/blobs/:sha", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const sha256 = String(req.params.sha ?? "");
    if (!isValidSha256Hex(sha256)) {
      res.status(400).json({ error: "sha must be a lowercase 64-character hex sha256 digest" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "publish_content.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      // A peer's publish grant is not a Library read grant. A known document-only hash must
      // not bypass typed export's exclusion, even after purge; live media owners still travel.
      if (await isDocumentOnlyBlob({ deps: { mediaRepo: deps.mediaRepo, blobRepo: deps.assetBlobRepo }, input: { workspaceId: deps.workspaceId, sha256 } })) {
        res.status(404).set("Cache-Control", "private, no-store").json({ error: "blob was not found", code: "BLOB_NOT_FOUND" });
        return;
      }
      const storageKey = computeBlobStorageKey({ workspaceId: deps.workspaceId, sha256 });
      // S18 (S-F3) — checks the blob store first, falling back to `RouteDeps.fileBlobIndex` (a
      // file-tree type's `pack()` fill) for a blob that was never copied into the blob store. See
      // `composite-blob-source.ts`'s header for why bytes are re-hashed on the fallback path.
      const blobSource = createCompositePeerBlobSource({ blobStore: deps.blobStore, fileBlobIndex: deps.fileBlobIndex });
      if (!(await blobSource.exists({ sha256, storageKey }))) {
        res.status(404).json({ error: "blob was not found", code: "BLOB_NOT_FOUND" });
        return;
      }

      const bytes = await blobSource.get({ sha256, storageKey });
      if (bytes.byteLength > TOVU_MAX_UPLOAD_BYTES) {
        // Unreachable for anything this instance accepted (both `blob-put.ts` and the media upload
        // route enforce the same ceiling), so this is a bound on a store written by some other
        // means — never a silent 47 MB+ base64 response.
        res.status(413).json({ error: `blob exceeds the ${TOVU_MAX_UPLOAD_BYTES}-byte transfer limit`, code: "PAYLOAD_TOO_LARGE" });
        return;
      }

      res.status(200).json({ sha256, dataBase64: Buffer.from(bytes).toString("base64") });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/publish-content/blob-get", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { bytesMatchSha256, isValidSha256Hex } from "#src/features/publish-content/blob-staging";
import { TOVU_MAX_UPLOAD_BYTES } from "#src/features/media/index";
import { decodeStrictBase64 } from "#src/contracts/core/index";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

import type { PublishContentRouteRegistrar } from "./deps.js";

/**
 * @file Task 6 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 6.
 *
 * `PUT /api/admin/v1/workspaces/:workspaceId/publish-content/blobs/:sha` — uploads one blob's
 * bytes, deduplicated via the SAME real `BlobStorePort.putIfAbsent` every media upload already uses
 * (dispatching brief: "media is the easy half of this feature ... reuse it, do not write a second
 * dedupe path"). Request body is JSON with base64-encoded bytes (`dataBase64`), mirroring
 * `routes/media/upload.ts`'s own documented simplification (no multipart-parsing dependency in this
 * repo yet).
 *
 * ## The refusal this route exists to enforce
 *
 * `putIfAbsent` (`@jini-ai/cms/media`'s `blob-store.fs.ts`/`blob-store.memory.ts`) does NOT verify
 * that the bytes it receives actually hash to the `sha256` it is given — it only uses that string to
 * derive a storage key and writes a create-only object there (see `blob-staging.ts`'s own header for
 * the full trace). The sha IS the identity everywhere else in this feature (baselines,
 * `PackedEntity.requiredBlobs`, a bundle's `blobManifest`), so this route calls
 * {@link bytesMatchSha256} and returns `422` on a mismatch BEFORE ever calling `putIfAbsent` —
 * accepting mismatched bytes here would let a caller poison content-addressed storage.
 */

/** Decodes base64 upload bytes, or `null` if `dataBase64` is missing, not a string, or not valid
 *  base64 — mirrors `routes/media/upload.ts`'s own `decodeUploadBytes`. Delegates the actual
 *  decode to {@link decodeStrictBase64}: `Buffer.from(x, "base64")` alone never throws (it skips
 *  characters outside the alphabet instead of refusing them), so a bare try/catch around it can
 *  never fire — see that function's own header.
 *  @complexity O(n) in the encoded payload length. */
function decodeBlobBytes(rawBody: unknown): Uint8Array | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const dataBase64 = body.dataBase64;
  if (typeof dataBase64 !== "string" || !dataBase64) return null;
  return decodeStrictBase64(dataBase64);
}

export const registerPublishContentBlobPutRoute: PublishContentRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/publish-content/blobs/:sha", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const claimedSha256 = String(req.params.sha ?? "");
    if (!isValidSha256Hex(claimedSha256)) {
      res.status(400).json({ error: "sha must be a lowercase 64-character hex sha256 digest" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "publish_content.apply",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const bytes = decodeBlobBytes(req.body);
      if (!bytes) {
        res.status(400).json({ error: "dataBase64 is required and must be valid base64" });
        return;
      }
      if (bytes.length > TOVU_MAX_UPLOAD_BYTES) {
        res.status(413).json({ error: `blob exceeds the ${TOVU_MAX_UPLOAD_BYTES}-byte upload limit`, code: "PAYLOAD_TOO_LARGE" });
        return;
      }

      // The security property this route exists to hold — see this file's own header.
      // `putIfAbsent` trusts `claimedSha256` unconditionally; this check MUST run before it.
      if (!bytesMatchSha256({ bytes, claimedSha256 })) {
        res.status(422).json({ error: "the uploaded bytes do not hash to the claimed sha256", code: "SHA256_MISMATCH" });
        return;
      }

      const { written } = await deps.blobStore.putIfAbsent({ workspaceId: deps.workspaceId, sha256: claimedSha256, bytes });
      res.status(200).json({ sha256: claimedSha256, written });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/publish-content/blob-put", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { computeBlobStorageKey } from "@jini-ai/cms/media";

import { PUBLISH_CONTENT_BLOB_PROBE_MAX_SHAS, isValidSha256Hex } from "#src/features/publish-content/blob-staging";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { CONTENT_ENTRY_MAX_BODY_BYTES, rejectOversizedJsonBody } from "#src/server/inbound/shared/body-size-limit";

import type { PublishContentRouteRegistrar } from "./deps.js";

/**
 * @file Task 6 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 6.
 *
 * `POST /api/admin/v1/workspaces/:workspaceId/publish-content/blobs/probe` — "which of these shas
 * do you already have?" so a peer pushing a bundle only uploads what this instance is actually
 * missing (plan §4 task 6's own description). Read-only against the blob store (`exists()` only,
 * never `put*`); gated by `publish_content.apply` per the dispatching brief — this is part of the
 * write flow (a peer preparing to push), not the export/read side's `publish_content.read`.
 *
 * Request: `{ shas: string[] }`, each a lowercase 64-hex-char sha256 digest
 * (`blob-staging.ts`'s `isValidSha256Hex`). Response: `{ missing: string[] }` — the subset of
 * `shas` this instance does NOT already hold, in the order they were requested minus any removed as
 * duplicates-of-a-hit; the client uploads exactly this list via `PUT .../blobs/:sha`.
 */

/** Body-shape validation extracted from the handler for a single early-return gate: `shas` must be
 *  a non-empty array, within the resource-bounds cap, of strings that each look like a sha256 hex
 *  digest. Returns the validated array, or a human-readable error string to send as a 400.
 *  @complexity O(n) in the array length. */
function validateProbeShas(rawBody: unknown): { shas: string[] } | { error: string } {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  const shas = body.shas;
  if (!Array.isArray(shas) || shas.length === 0) {
    return { error: "shas must be a non-empty array of sha256 hex digests" };
  }
  if (shas.length > PUBLISH_CONTENT_BLOB_PROBE_MAX_SHAS) {
    return { error: `at most ${PUBLISH_CONTENT_BLOB_PROBE_MAX_SHAS} shas are allowed per request` };
  }
  for (const sha of shas) {
    if (typeof sha !== "string" || !isValidSha256Hex(sha)) {
      return { error: `'${String(sha)}' is not a valid lowercase sha256 hex digest` };
    }
  }
  return { shas: shas as string[] };
}

export const registerPublishContentBlobsProbeRoute: PublishContentRouteRegistrar = (app, deps) => {
  app.post(
    "/api/admin/v1/workspaces/:workspaceId/publish-content/blobs/probe",
    rejectOversizedJsonBody({ maxBytes: CONTENT_ENTRY_MAX_BODY_BYTES }),
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      try {
        const principal = getAuthedPrincipal(res);
        if (
          !(await authorizeOrRespond(res, deps.authorize, {
            principalId: principal.id,
            permission: "publish_content.apply",
            workspaceId: deps.workspaceId,
          }))
        )
          return;

        const validated = validateProbeShas(req.body);
        if ("error" in validated) {
          res.status(400).json({ error: validated.error });
          return;
        }

        const missing: string[] = [];
        for (const sha256 of validated.shas) {
          const storageKey = computeBlobStorageKey({ workspaceId: deps.workspaceId, sha256 });
          const present = await deps.blobStore.exists({ storageKey });
          if (!present) missing.push(sha256);
        }

        res.status(200).json({ missing });
      } catch (error) {
        sendAdminFailure({ res, error }, { operation: "routes/publish-content/blobs-probe", code: "INTERNAL_ERROR" });
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { stageBundle, PUBLISH_CONTENT_BUNDLE_MAX_BODY_BYTES } from "#src/features/publish-content/bundle-staging";
import { PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION } from "#src/features/publish-content/artifact-format";
import { buildPublishContentCatalog } from "#src/features/publish-content/type-registry";
import { backstopGrantAllows, isBackstopEntityType } from "#src/features/publish-trust/grant";
import { readBackstopMetadata } from "#src/features/publish-content/backstop-service";
import type { PackedEntity } from "#src/features/publish-content/type-registry";
import type { BackstopMetadata } from "#src/features/publish-content/backstop-audit";
import { getPublishTrustContext, type PublishTrustContext } from "#src/server/inbound/admin-http/publish-trust-auth";
import { rejectOversizedJsonBody } from "#src/server/inbound/shared/body-size-limit";
import { buildPublishBackstopPorts } from "#src/server/runtime/composition/publish-backstop-ports";

import { toPublishContentDeps, type PublishContentRouteDeps, type PublishContentRouteRegistrar } from "./deps.js";
import { authorizedPrincipalId, bodyRecord, rejectForeignWorkspace, sendRefusal, type RouteRefusal } from "./route-helpers.js";

/**
 * @file Task 6 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 6.
 *
 * `POST /api/admin/v1/workspaces/:workspaceId/publish-content/bundles` — stages a received bundle
 * (Task 4's export envelope: `{hashVersion, sourceLabel, entities, blobManifest}`, whether pushed by
 * a peer or fetched by this instance's own pull) in `publish_content_bundles`, so Task 7's gated
 * `plan()`/`execute()` has a stable, already-persisted input to hash and re-hash. Never writes any
 * OTHER table — see `bundle-staging.ts`'s `stageBundle` for what "staging" means.
 *
 * `expiresAt` is never read from the request body — `stageBundle` always computes it server-side
 * from `receivedAt` + a fixed TTL (`bundle-staging.ts`'s own header). `sourcePrincipalId` is always
 * this request's AUTHENTICATED principal, never a bundle-declared identity (plan §1.6 / §5 risk #9).
 */

/** An entity that passed {@link validateBundleBody}: an object with a non-empty string
 *  `entityType` and an integer `schemaVersion`. Every other field stays opaque. */
export type ValidatedBundleEntity = Record<string, unknown> & { entityType: string; schemaVersion: number };

/** A bundle envelope that passed {@link validateBundleBody}. */
export interface ValidatedBundle {
  artifactFormatVersion: number;
  hashVersion: number;
  sourceLabel: string | undefined;
  entities: ValidatedBundleEntity[];
  blobManifest: string[];
}

/** The version fields, in check order. @complexity O(1). */
function envelopeVersionError(body: Record<string, unknown>): string | undefined {
  if (!Number.isInteger(body.artifactFormatVersion)) return "artifactFormatVersion must be an integer";
  if (body.artifactFormatVersion !== PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION) {
    return (
      `unsupported artifactFormatVersion ${String(body.artifactFormatVersion)}; ` +
      `this instance supports ${PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION}`
    );
  }
  if (!Number.isInteger(body.hashVersion)) return "hashVersion must be an integer";
  return undefined;
}

/** One entity's envelope fields. @complexity O(1). */
function entityError(entity: unknown, index: number): string | undefined {
  if (typeof entity !== "object" || entity === null || Array.isArray(entity)) return `entities[${index}] must be an object`;
  const candidate = entity as Record<string, unknown>;
  if (typeof candidate.entityType !== "string" || candidate.entityType.length === 0) {
    return `entities[${index}].entityType must be a non-empty string`;
  }
  if (!Number.isInteger(candidate.schemaVersion)) return `entities[${index}].schemaVersion must be an integer`;
  return undefined;
}

/** `entities` itself, then each entry in order; the first refusal wins. @complexity O(n). */
function entitiesError(entities: unknown): string | undefined {
  if (!Array.isArray(entities)) return "entities must be an array";
  for (const [index, entity] of entities.entries()) {
    const error = entityError(entity, index);
    if (error) return error;
  }
  return undefined;
}

/** The fields checked after the entities. @complexity O(n) in `blobManifest.length`. */
function manifestAndLabelError(body: Record<string, unknown>): string | undefined {
  if (!Array.isArray(body.blobManifest) || body.blobManifest.some((sha) => typeof sha !== "string")) {
    return "blobManifest must be an array of strings";
  }
  if (body.sourceLabel !== undefined && typeof body.sourceLabel !== "string") return "sourceLabel must be a string when present";
  return undefined;
}

/** Body-shape validation extracted from the handler: `hashVersion` must be a finite integer,
 *  `entities` and `blobManifest` must be arrays (`blobManifest` additionally an array of strings —
 *  it is compared against blob sha256s downstream). This module never inspects an entity's own
 *  shape — that is `planImport`'s job (Task 5, already built); duplicating it here would just be a
 *  second, driftable copy of the same rule.
 *  @complexity O(n) in `blobManifest.length` (one type check per element). */
export function validateBundleBody(rawBody: unknown): ValidatedBundle | { error: string } {
  const body = bodyRecord(rawBody);
  const error = envelopeVersionError(body) ?? entitiesError(body.entities) ?? manifestAndLabelError(body);
  if (error) return { error };
  return {
    artifactFormatVersion: body.artifactFormatVersion as number,
    hashVersion: body.hashVersion as number,
    sourceLabel: body.sourceLabel as string | undefined,
    entities: body.entities as ValidatedBundleEntity[],
    blobManifest: body.blobManifest as string[],
  };
}

/** A registered type whose handler speaks another `schemaVersion` refuses the bundle; an
 *  unregistered type passes here and is left to `planImport`. @complexity O(n). */
function schemaVersionRefusal(deps: PublishContentRouteDeps, entities: readonly ValidatedBundleEntity[]): RouteRefusal | null {
  const catalog = buildPublishContentCatalog(toPublishContentDeps(deps));
  for (const entity of entities) {
    const handler = catalog.handlerByType.get(entity.entityType);
    if (handler && entity.schemaVersion !== handler.schemaVersion) {
      return {
        status: 400,
        body: {
          error:
            `unsupported schemaVersion ${String(entity.schemaVersion)} for entity type '${entity.entityType}'; ` +
            `this instance supports ${handler.schemaVersion}`,
        },
      };
    }
  }
  return null;
}

/**
 * The grant's entity-type allowlist, enforced at the door a publishing credential comes
 * through. A capability says "may publish"; `entityTypes` says WHAT, and without this the
 * second half of the grant would be decorative. The WHOLE bundle is refused rather than
 * filtered down to the allowed types, matching `grant.ts`'s own refuse-never-repair stance:
 * a source that sent a type it may not send has a wrong idea of what it is allowed to do,
 * and quietly dropping part of its bundle would leave it believing the publish succeeded
 * in full. An empty `entityTypes` allows nothing, which is the correct reading of a
 * permission nobody stated.
 * @complexity O(n · t) in entities and granted types.
 */
function grantRefusal(publishTrust: PublishTrustContext | null, entities: readonly ValidatedBundleEntity[]): RouteRefusal | null {
  if (entities.some(({ entityType }) => isBackstopEntityType({ entityType }) && !backstopGrantAllows({ grant: publishTrust, entityType }))) {
    return { status: 403, body: { error: "Send by hand requires the destination's backstop grant and raw entity type.",
      code: "FORBIDDEN", details: { permission: "publish_content.backstop", reason: "backstop_not_granted" } } };
  }
  // `validated.entities` is `unknown[]` on purpose (see `validateBundleBody`), so an entry
  // that does not declare a string `entityType` is refused rather than skipped: skipping it
  // would let `{}` walk straight past the allowlist and reach `planImport` unchecked.
  // `findIndex`, not `find`, because `find` reports a match by returning the element: a
  // matching `undefined` entry would be indistinguishable from "no match". Not reachable
  // over this route today — JSON has no `undefined`, so a parsed body cannot produce one,
  // and a deliberate break confirmed the tests below do not distinguish the two spellings.
  // Kept because it costs nothing and the next caller may not arrive through JSON.
  // Now structural instead: `validateBundleBody` types every entry as an object with a
  // non-empty string `entityType` and refuses anything else as a 400 before this runs, so an
  // entry with no declared type can no longer reach the allowlist at all, and `some` over the
  // declared types replaces the `findIndex` guard.
  if (publishTrust && entities.some(({ entityType }) => !publishTrust.entityTypes.includes(entityType))) {
    return {
      status: 403,
      body: {
        error: "this bundle carries an entity type outside the publishing grant",
        code: "FORBIDDEN",
        details: { permission: "publish_content.apply", reason: "entity_type_not_granted" },
      },
    };
  }
  return null;
}

/**
 * A manual send (raw rows/files): its send details must read, its confirmed address must be this
 * destination, and the audit storage must be installed. `null` for a bundle with no raw entity.
 * @complexity O(n) in entities, plus one audit-table probe.
 */
async function backstopRefusal(host: string | undefined, deps: PublishContentRouteDeps, entities: readonly ValidatedBundleEntity[]): Promise<RouteRefusal | null> {
  let metadata: BackstopMetadata | null;
  try {
    // Envelope validation leaves entity fields opaque; the planner checks their full
    // shape before any writes. This read validates only the manual-send metadata.
    metadata = readBackstopMetadata({ entities: entities as unknown as PackedEntity[] });
  } catch (error) {
    return { status: 400, body: { error: (error as Error).message } };
  }
  if (metadata === null) return null;
  if (metadata.destinationHost !== host) return { status: 400, body: { error: "The confirmed live address does not match this destination." } };
  if (!(await buildPublishBackstopPorts(deps).audit?.ready())) {
    return { status: 503, body: { error: "Send by hand needs its audit storage installed before it can send anything.", code: "BACKSTOP_NOT_INSTALLED" } };
  }
  return null;
}

export const registerPublishContentBundleCreateRoute: PublishContentRouteRegistrar = (app, deps) => {
  app.post(
    "/api/admin/v1/workspaces/:workspaceId/publish-content/bundles",
    rejectOversizedJsonBody({ maxBytes: PUBLISH_CONTENT_BUNDLE_MAX_BODY_BYTES }),
    async (req, res) => {
      if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;

      try {
        const principalId = await authorizedPrincipalId(res, deps, "publish_content.apply");
        if (principalId === null) return;

        const validated = validateBundleBody(req.body);
        if ("error" in validated) {
          res.status(400).json({ error: validated.error });
          return;
        }

        const refusal =
          schemaVersionRefusal(deps, validated.entities) ??
          grantRefusal(getPublishTrustContext(res), validated.entities) ??
          (await backstopRefusal(req.get("host"), deps, validated.entities));
        if (refusal) {
          sendRefusal(res, refusal);
          return;
        }

        const { bundleId, expiresAt } = await stageBundle(
          {
            workspaceId: deps.workspaceId,
            sourcePrincipalId: principalId,
            artifactFormatVersion: validated.artifactFormatVersion,
            hashVersion: validated.hashVersion,
            sourceLabel: validated.sourceLabel,
            entities: validated.entities,
            blobManifest: validated.blobManifest,
          },
          { repo: deps.publishContentBundleRepo, clock: deps.clock, idGen: deps.idGen }
        );

        res.status(201).json({ bundleId, expiresAt });
      } catch (error) {
        sendAdminFailure({ res, error }, { operation: "routes/publish-content/bundle-create", code: "INTERNAL_ERROR" });
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { buildPublishContentCatalog } from "#src/features/publish-content/type-registry";
import { backstopGrantAllows, isBackstopEntityType } from "#src/features/publish-trust/grant";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { getPublishTrustContext } from "#src/server/inbound/admin-http/publish-trust-auth";

import { toPublishContentDeps, type PublishContentRouteRegistrar } from "./deps.js";

/**
 * @file S-F1 of `ADS-memory/.local-artifacts/publish-files-plan-2026-09-24.md` §5/§6.
 *
 * `GET /api/admin/v1/workspaces/:workspaceId/publish-content/capabilities` — what THIS instance can
 * accept, asked BEFORE a peer stages a single entity. Without it, `bundle-create.ts` refuses the
 * WHOLE bundle the moment it carries any entity type outside the caller's grant (§5), which turns
 * every new type this codebase ever adds into a hard publish failure against an older destination
 * until that destination is redeployed. `peer-transport.ts`'s `pushBundleToPeer` calls this route
 * first, drops the types it names as unsupported, and reports them back as `notSupportedByLive`
 * instead — nothing is refused, and no blob is wasted uploading an entity that will not be sent.
 *
 * `entityTypes` is the intersection of two independent facts, both already checked separately
 * elsewhere in this directory and joined here into one answer:
 * - Every type THIS instance has a registered handler for (`buildPublishContentCatalog` — the same
 *   allowlist `export.ts`/`bundle-create.ts` already enforce).
 * - Every type the CALLING principal's publishing grant permits, when it authenticated through one
 *   (`getPublishTrustContext`). An explicitly-configured peer API key carries no such grant — the
 *   same "no grant present, so the allowlist check does not run" reading `bundle-create.ts` already
 *   gives that credential kind — so a caller of that kind sees every registered type unfiltered.
 *
 * A peer that predates this route answers the GET with an ordinary 404 from Express's own router;
 * nothing here has to special-case that absence. `peer-transport.ts`'s own probe reads a 404 as
 * "legacy `{post,page,media}`", the fixed set every pre-S-F1 destination accepted.
 */
export const registerPublishContentCapabilitiesRoute: PublishContentRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/publish-content/capabilities", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "publish_content.apply",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const catalog = buildPublishContentCatalog(toPublishContentDeps(deps));
      const registeredTypes = catalog.handlers.map((handler) => handler.entityType);

      // `null` (no publishing grant on this request — an explicitly-configured peer key) means
      // "every registered type", matching `bundle-create.ts`'s own reading of the same absence.
      const trust = getPublishTrustContext(res);
      const grantedTypes = trust?.entityTypes ?? null;
      const entityTypes =
        registeredTypes.filter((entityType) => isBackstopEntityType({ entityType })
          ? backstopGrantAllows({ grant: trust, entityType })
          : grantedTypes === null || grantedTypes.includes(entityType));

      const schemaVersions: Record<string, number> = {};
      for (const handler of catalog.handlers) {
        if (entityTypes.includes(handler.entityType)) schemaVersions[handler.entityType] = handler.schemaVersion;
      }

      // publish-overwrite-live-plan §4/S6 — unconditional, unlike `entityTypes`: it names a CODE
      // capability of this instance's import ceremony (whether `forcedEntityKeys`/`retires` are
      // understood at all), not a per-caller content-type grant, so no credential or handler
      // narrows it. `peer-transport.ts`'s probe (S7) reads its absence as `liveCanOverwrite: false`
      // — the same "older peer answers without a field it doesn't know" reading `entityTypes` itself
      // already relies on for a pre-S-F1 destination's plain 404.
      res.status(200).json({ entityTypes, schemaVersions, features: ["overwrite-live"] });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/publish-content/capabilities", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { normalizePeerBaseUrl } from "#src/features/publish-content/peer-url";
import {
  connectAndRecordDestination,
  disconnectAndForgetDestination,
} from "#src/features/publish-content/connect-destination";
import { selectConnectedDestination, type PublishContentPeerSummary } from "#src/features/publish-content/peers";
import { listPublishContentContributors } from "#src/features/publish-content/type-registry";
import {
  connectDestination,
  disconnectDestination,
  PublishTrustConnectError,
} from "#src/features/publish-trust/connect";
import { PublishTrustHandshakeError } from "#src/features/publish-trust/handshake-client";
import type { PublishTrustProvisioningPort } from "#src/features/publish-trust/provisioning";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

import type { PublishContentRouteDeps } from "./deps.js";

/**
 * @file The one action a person takes to make publishing work: "yes, that site is mine".
 * Design note: `ADS-memory/reports/2026-09-19-publish-zero-setup-auth-design.md`.
 *
 * ## Why the action lives here, behind the Publish button
 *
 * The owner has rejected the key ceremony five times, so the bar for this surface is that it
 * introduces NO concept. That rules out a settings screen: a settings screen is a place you have to
 * know to go to, and once you are there the page has to explain what it is for — which is the
 * vocabulary lesson the whole design exists to avoid. So the connect action hangs off the Publish
 * Content dialog instead, in the slot that used to read "No publish target is configured yet. Add
 * one in Settings first." The owner gets there by trying to do the thing they wanted, and the dead
 * end becomes the one question worth asking them.
 *
 * `GET` pre-fills the candidate from the deploy config the repo already carries, so in the common
 * case the dialog asks "Publish to <live site host>?" and the owner presses one button. That is the one
 * irreducible step: choosing which site is theirs, once.
 *
 * These are ordinary admin routes rather than UI-only logic so the same action is reachable from a
 * command or an assistant tool later without a second implementation of what connecting means.
 *
 * ## Nothing in any response here is secret
 *
 * `GET` returns an address, a label and two sentences. `POST /connect` returns the same plus what to
 * do next. No installation id, no public key, no generation, no capability list, no expiry — not
 * because they are secret (they are not; they live in committed config) but because naming them is
 * exactly the vocabulary this surface must not teach.
 */

/** What every response here is shaped as. Strings a person reads, never state to interpret. */
export interface PublishDestinationView {
  /** `true` once this computer's grant has been written for a site. */
  readonly connected: boolean;
  /** The connected site, as the publish list already models it. `null` when there is none. */
  readonly site: PublishContentPeerSummary | null;
  /** Read out of the repo's deploy config — what to offer when nothing is connected yet. */
  readonly candidateUrl: string | null;
  /** One sentence describing where things stand. */
  readonly message: string;
  /** One sentence naming what the owner does next, or `null` when nothing is pending. */
  readonly nextStep: string | null;
}

export interface PublishDestinationDeps {
  readonly provisioning: PublishTrustProvisioningPort;
  /** The address to offer, from the repo's committed deploy config. */
  readonly findCandidate: () => Promise<string | null>;
}

/** The site host, as a label a person recognises. The address is the identity; this is the name.
 *  @complexity O(n) in the URL length. */
function siteLabelFor(baseUrl: string): string {
  try {
    return new URL(baseUrl).host;
  } catch {
    return baseUrl;
  }
}

/**
 * The connected destination, if this install has one.
 *
 * "Connected" is a property of the peer list, not of the grant file: a grant can be present while
 * the row is gone (a repo cloned onto a second computer) and the row is what publishing needs. The
 * grant is re-derived by {@link connectDestination} whenever the owner connects again, which is why
 * making the row authoritative here costs nothing.
 *
 * @complexity O(n) in the workspace's peer count.
 */
async function connectedSite(deps: PublishContentRouteDeps): Promise<PublishContentPeerSummary | null> {
  const rows = await deps.publishContentPeerRepo.listByWorkspace({ workspaceId: deps.workspaceId });
  const match = selectConnectedDestination(rows);
  return match
    ? {
        id: match.id,
        label: match.label,
        baseUrl: match.baseUrl,
        remoteWorkspaceId: match.remoteWorkspaceId,
        masked: null,
        hasCredential: false,
      }
    : null;
}

/** Maps this file's own failures to a status and an owner-facing sentence. Every message passed
 *  through is already written for a person — see `handshake-client.ts`'s header.
 *  @complexity O(1). */
function respondWithError(res: { status(code: number): { json(body: unknown): void } }, err: unknown): void {
  if (err instanceof PublishTrustHandshakeError) {
    res.status(502).json({ error: err.message, code: "PUBLISH_TRUST_HANDSHAKE_FAILED" });
    return;
  }
  if (err instanceof PublishTrustConnectError) {
    res.status(500).json({ error: err.message, code: "PUBLISH_TRUST_NOT_SAVED" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/publish-content/destination", code: "INTERNAL_ERROR" });
}

/**
 * Registers `GET`, `POST /connect` and `POST /disconnect` under
 * `/api/admin/v1/workspaces/:workspaceId/publish-content/destination`.
 *
 * @complexity O(1) per request beyond each handler's own cost.
 */
export function registerPublishContentDestinationRoutes(
  app: Express,
  deps: PublishContentRouteDeps,
  own: PublishDestinationDeps
): void {
  const base = "/api/admin/v1/workspaces/:workspaceId/publish-content/destination";

  /** Mount-path 404 plus the `publish_content.apply` gate — connecting authorises future writes to
   *  a live site, so it is gated as a write, not as a read. */
  const guard = async (
    req: { params: Record<string, string | undefined> },
    res: Parameters<Parameters<typeof app.post>[1]>[1]
  ): Promise<boolean> => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return false;
    }
    const principal = getAuthedPrincipal(res);
    return authorizeOrRespond(res, deps.authorize, {
      principalId: principal.id,
      permission: "publish_content.apply",
      workspaceId: deps.workspaceId,
    });
  };

  app.get(base, async (req, res) => {
    try {
      if (!(await guard(req, res))) return;
      const site = await connectedSite(deps);
      if (site) {
        const view: PublishDestinationView = {
          connected: true,
          site,
          candidateUrl: null,
          message: `This computer publishes to ${site.label}.`,
          nextStep: null,
        };
        res.json(view);
        return;
      }

      const candidateUrl = await own.findCandidate();
      const view: PublishDestinationView = {
        connected: false,
        site: null,
        candidateUrl,
        // The empty state is a plain sentence, never an error code — a fresh install that has never
        // deployed is the ordinary first run, not a fault.
        message: candidateUrl
          ? `Publish to ${siteLabelFor(candidateUrl)}?`
          : "No live site is set up yet. Deploy this site once, then come back here.",
        nextStep: null,
      };
      res.json(view);
    } catch (err) {
      respondWithError(res, err);
    }
  });

  app.post(`${base}/connect`, async (req, res) => {
    try {
      if (!(await guard(req, res))) return;

      const supplied = (req.body ?? {}) as Record<string, unknown>;
      const raw = typeof supplied.siteUrl === "string" && supplied.siteUrl.trim() !== ""
        ? supplied.siteUrl
        : await own.findCandidate();
      if (raw === null) {
        res.status(400).json({
          error: "No live site is set up yet. Deploy this site once, then come back here.",
          code: "NO_DESTINATION",
        });
        return;
      }
      const normalized = normalizePeerBaseUrl(String(raw));
      if ("error" in normalized) {
        res.status(400).json({ error: "That does not look like a website address.", code: "VALIDATION_ERROR" });
        return;
      }

      // What this source may publish is its OWN registered types, not a list anyone chooses. An
      // empty grant can do nothing (`grant.ts`), so an install with no registered contributors is
      // refused here rather than connected into something that silently publishes nothing.
      const entityTypes = listPublishContentContributors().map((contributor) => contributor.entityType);
      if (entityTypes.length === 0) {
        res.status(409).json({ error: "This site has nothing that can be published yet.", code: "NO_PUBLISHABLE_TYPES" });
        return;
      }

      const trustDeps = {
        httpClient: deps.publishContentPeerHttpClient,
        keyring: deps.siteAssistantSecretKeyring,
        provisioning: own.provisioning,
        clock: deps.clock,
        workspaceId: deps.workspaceId,
      };
      const { site, grant } = await connectAndRecordDestination(
        {
          repo: deps.publishContentPeerRepo,
          clock: deps.clock,
          idGen: deps.idGen,
          connectGrant: (input) => connectDestination(trustDeps, input),
          reverseGrant: () => disconnectDestination(trustDeps),
        },
        { workspaceId: deps.workspaceId, baseUrl: normalized.baseUrl, entityTypes }
      );

      const view: PublishDestinationView = {
        connected: true,
        site,
        candidateUrl: null,
        message: `This computer publishes to ${site.label}.`,
        nextStep: grant.nextStep,
      };
      res.status(201).json(view);
    } catch (err) {
      respondWithError(res, err);
    }
  });

  app.post(`${base}/disconnect`, async (req, res) => {
    try {
      if (!(await guard(req, res))) return;
      const removed = await disconnectAndForgetDestination(
        {
          repo: deps.publishContentPeerRepo,
          clock: deps.clock,
          idGen: deps.idGen,
          reverseGrant: () =>
            disconnectDestination({
              keyring: deps.siteAssistantSecretKeyring,
              provisioning: own.provisioning,
              workspaceId: deps.workspaceId,
            }),
        },
        { workspaceId: deps.workspaceId }
      );
      const site = removed.site;

      const view: PublishDestinationView = {
        connected: false,
        site: null,
        candidateUrl: site?.baseUrl ?? (await own.findCandidate()),
        message: site ? `This computer no longer publishes to ${site.label}.` : "This computer was not publishing anywhere.",
        // Takes effect on the next deploy — the destination-side deny list is the immediate one,
        // and it is a separate action on the SITE, not on this computer.
        // `target` is always present: `disconnectAndForgetDestination` returns the reversal's own
        // (`GrantReverseResult.target`, never null), so only `changed` decides whether to show it.
        nextStep: removed.changed ? removed.target.nextStep : null,
      };
      res.json(view);
    } catch (err) {
      respondWithError(res, err);
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { getPublishTrustContext } from "#src/server/inbound/admin-http/publish-trust-auth";
import { CONTENT_HASH_VERSION } from "#src/features/publish-content/content-hash";
import { PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION } from "#src/features/publish-content/artifact-format";
import { packAuthorizedEntities } from "#src/features/publish-content/export-bundle";
import { toPublishContentDeps, type PublishContentRouteDeps, type PublishContentRouteRegistrar } from "./deps.js";
import { rejectForeignWorkspace } from "./route-helpers.js";

/**
 * @file Task 4 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §1.1/§4 task 4.
 *
 * `GET /api/admin/v1/workspaces/:workspaceId/publish-content/export` — read-only (never writes a
 * row), streams `{hashVersion, sourceLabel, entities[], blobManifest[]}`.
 *
 * ## The security property this route exists to hold (plan §3 rule 5, §5 risk #8)
 *
 * The type filter is an ALLOWLIST of registered publish-content types, never a deny-list: this
 * route never reads any table directly, and never enumerates "every table except the ones on some
 * excluded-list" — its ONLY source of entities is `listPublishContentContributors()` (Task 2),
 * called fresh at request time (never cached — see `type-registry.ts`'s own "fresh-read" rule). A
 * table added tomorrow with no contributor registered for it is therefore invisible to this route
 * BY CONSTRUCTION, not because someone remembered to add it to a deny-list. This is exactly the
 * property `__tests__/export.test.ts`'s "empty registry -> empty bundle, despite real DB content"
 * test pins directly, and `__tests__/export-no-leak.integration.test.ts` pins end-to-end against a
 * real SQLite db seeded with a canary row in every named sensitive table.
 *
 * ## Two DIFFERENT permission checks, not one
 *
 * 1. `publish_content.read` gates the route itself — a principal without it never reaches the
 *    registry loop at all (403, not a partial/empty 200 that could be mistaken for "nothing to
 *    export").
 * 2. Each registered type's OWN `permission` (plan §3: "the resource's OWN existing write
 *    permission", e.g. `content.write` for `post`/`page` — `PublishContentHandler.permission`)
 *    gates that ONE type's inclusion. A principal holding `publish_content.read` but not, say,
 *    `content.write` still gets a 200 — just with that type's entities silently omitted, never a
 *    500. This is what makes "a principal allowed posts but not media is refused media by
 *    construction" (plan §3) true for the export side, not just the apply side.
 *
 * ## Why this streams rather than buffers
 *
 * `PublishContentHandler.pack()` is an async generator specifically so a large collection never
 * has to be held in memory whole (`type-registry.ts`'s own doc: "Task 4's export route streams its
 * response body from this directly"). This handler writes the JSON envelope by hand
 * (`res.write()` per entity) rather than building an array and calling `res.json()` once, so memory
 * use stays bounded by one entity at a time regardless of corpus size.
 */

/**
 * Writes the export envelope by hand, one entity at a time (this file's header, "Why this streams
 * rather than buffers"), for a principal that has already passed the route-level gate.
 * @complexity O(n) in the packed entities; memory O(1) entities plus the blob-manifest set.
 */
async function streamExportBundle(res: Response, deps: PublishContentRouteDeps, principalId: string): Promise<void> {
  const workspace = await deps.workspaceRepo.findById({ id: deps.workspaceId });
  const sourceLabel = workspace?.name ?? deps.workspaceId;
  const publishContentDeps = toPublishContentDeps(deps);

  res.setHeader("content-type", "application/json");
  res.write(
    `{"artifactFormatVersion":${JSON.stringify(PUBLISH_CONTENT_ARTIFACT_FORMAT_VERSION)},` +
      `"hashVersion":${JSON.stringify(CONTENT_HASH_VERSION)},"sourceLabel":${JSON.stringify(sourceLabel)},"entities":[`
  );

  const requiredBlobs = new Set<string>();
  let separator = "";
  // The registry walk and the per-type gate (see this file's own header, "Two DIFFERENT
  // permission checks") live in `export-bundle.ts` so Task 10's push driver runs the IDENTICAL
  // loop rather than a second copy of it. A per-type denial omits that type and continues; it
  // never turns into a 500 or aborts the stream. This route keeps its own streaming write, which
  // is the one thing the two callers genuinely do differently.
  for await (const entity of packAuthorizedEntities({
    workspaceId: deps.workspaceId,
    principalId,
    authorize: deps.authorize,
    publishContentDeps,
  })) {
    res.write(separator + JSON.stringify(entity));
    separator = ",";
    for (const sha of entity.requiredBlobs) requiredBlobs.add(sha);
  }

  res.write(`],"blobManifest":${JSON.stringify(Array.from(requiredBlobs))}}`);
  res.end();
}

export const registerPublishContentExportRoute: PublishContentRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/publish-content/export", async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;

    try {
      const principal = getAuthedPrincipal(res);

      // A publishing credential is refused here, loudly, even though it holds
      // `publish_content.read`. The route-level gate is not the only check this handler applies:
      // `packAuthorizedEntities` below ALSO asks for each registered type's own write permission
      // (this file's header, "Two DIFFERENT permission checks"), and a per-type denial omits that
      // type and continues rather than failing. A publishing grant's capability set is closed and
      // cannot contain `content.write` (`features/publish-trust/grant.ts`), so every type would be
      // omitted and the caller would receive a well-formed bundle containing NOTHING — a silently
      // wrong answer, which is worse than a refusal. Pull-by-publishing-credential needs the
      // per-type gate to be answerable from the grant's `entityTypes`; until it is, this says so.
      if (getPublishTrustContext(res)) {
        res.status(403).json({
          error: "a publishing credential cannot export from this site",
          code: "FORBIDDEN",
          details: { permission: "publish_content.read", reason: "publish_trust_export_not_wired" },
        });
        return;
      }

      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "publish_content.read",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      await streamExportBundle(res, deps, principal.id);
    } catch (error) {
      // The envelope's opening brace may already be flushed by the time a contributor's pack()
      // throws mid-stream — a second `res.status().json()` on a headers-sent response would itself
      // throw, so this only sends a fresh error body when nothing has gone out yet, and otherwise
      // just ends the connection rather than emitting a byte stream a client could half-parse as
      // valid JSON.
      if (!res.headersSent) sendAdminFailure({ res, error }, { operation: "routes/publish-content/export", code: "INTERNAL_ERROR" });
      else res.end();
    }
  });
};

import type { Express, Response } from "express";

import {
  authorizeForHooks,
  confirm,
  execute,
  plan,
  type GatedMutationHooks,
} from "#src/contracts/core/gated-mutations/gateway";
import { buildConfirmOnlyHooks } from "#src/contracts/core/gated-mutations/composition";
