/**
 * @file Task 7 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §1.5/§4 task 7.
 *
 * `POST /api/admin/v1/workspaces/:workspaceId/publish-content/import/{plan,confirm,execute}` —
 * the gated import ceremony over a bundle already staged by Task 6's
 * `POST .../publish-content/bundles`. Mirrors `taxonomy/merge-term.ts`'s 3-endpoint-in-one-file
 * shape (the established precedent for a gated-mutation route triple in this codebase) and
 * `database/migrate-forward.ts`'s `costClass` pre-check at `/execute` — see `gated-hooks.ts`'s file
 * header for why that check lives here, wrapping `gatewayExecute()`, rather than inside
 * `hooks.executeMutation()` itself.
 *
 * `plan` and `execute` both take `{bundleId}` in the body — the SAME bundle must be named at both
 * steps, since `buildPublishContentImportHooks` closes over it fresh per request (mirrors
 * `merge-term.ts`'s `intoTermId` being required in both `plan` and `execute` bodies for the
 * identical reason: `computePlan()`/`executeMutation()` need to know what to recompute against).
 */
/**
 * publish-overwrite-live-plan §7: "Overwrite on live" ticks come only from a person's click — here,
 * a signed-in admin session, or a publishing instance relaying its own admin's click (its relay
 * refuses an API key the same way, `peer-transport.ts`'s `mayOverwrite`). An API key on this
 * instance is refused. Empty ticks ask for nothing and pass.
 *
 * @returns `true` when the request may proceed. On `false` the 403 has already been sent.
 * @complexity O(1).
 */
function mayOverwrite(res: Response, overwriteEntityKeys: readonly string[] | null): boolean {
  if (overwriteEntityKeys === null || overwriteEntityKeys.length === 0) return true;
  if (getAuthedCredentialKind(res) !== "api_key") return true;
  const body: CredentialKindForbiddenBody = {
    error: "'overwriteEntityKeys' can only be sent from a signed-in admin session or a publishing instance",
    code: "FORBIDDEN",
    details: { permission: "publish_content.apply", reason: "credential_kind_not_permitted" },
  };
  res.status(403).json(body);
  return false;
}

/** The confirm-only hooks the `confirm` step and `execute`'s authorization pre-check both use. */
function confirmOnlyHooks(workspaceId: string) {
  return buildConfirmOnlyHooks({
    domain: "publish_content.import",
    readPermission: "publish_content.read",
    mutatePermission: "publish_content.apply",
    scopeId: workspaceId,
  });
}

/** True when a plan carries manual-publish rows, whose values the preview would show.
 *  @complexity O(n) in the report's rows. */
function planCarriesRawRows(report: PublishContentReport): boolean {
  return !report.refused && report.rows.some((row) => row.entityType === "raw-row" || row.entityType === "raw-file");
}

/** Returned by `rawPlanPreview` once it has sent the 403. */
const RAW_VALUES_REFUSED = Symbol("raw-values-refused");

export const registerPublishContentImportRoutes: PublishContentRouteRegistrar = (app: Express, deps) => {
  function buildHooks(bundleId: string, actorId: string, res: Response, overwriteEntityKeys: readonly string[] | null) {
    const publishContentDeps = toPublishContentDeps(deps);
    return buildPublishContentImportHooks({
      workspaceId: deps.workspaceId,
      bundleId,
      actorId,
      clock: deps.clock,
      idGen: deps.idGen,
      // The apply loop authorizes each entity against its TYPE's own write permission. For a human
      // that is RBAC, unchanged. For a publishing credential it has to be the grant, or the
      // ceremony fails at execute — see `withPublishTrustContentAuthorize`'s own doc.
      publishContentDeps: withPublishTrustContentAuthorize(res, publishContentDeps, registeredPublishTypePermissions(publishContentDeps)),
      bundleRepo: deps.publishContentBundleRepo,
      baselineRepo: deps.publishContentBaselineRepo,
      blobStore: deps.blobStore,
      dbOps: deps.dbOps,
      restorePointsRepo: deps.restorePointsRepo,
      applyPort: deps.publishContentApplyPort,
      getSeedHash: deps.publishContentSeedHash,
      // publish-overwrite-live-plan §4/S6 — closed over fresh per request, exactly like `bundleId`
      // itself (this function's own doc), so a caller's ticks changing between plan/confirm and
      // execute changes the re-derived report and is caught by the existing PLAN_STALE mechanism
      // (`gated-hooks.ts`'s own doc on `forcedEntityKeys`), not by anything bespoke here.
      ...(overwriteEntityKeys === null ? {} : { forcedEntityKeys: new Set(overwriteEntityKeys) }),
    });
  }

  /** A read-capable account cannot turn the raw plan into a private-data reader. Both the
   *  separate capability and each explicitly granted raw type are checked by this port.
   *  @complexity O(t) sequential `authorize()` calls, one per distinct entity type; stops at the first denial. */
  async function mayReadRawValues(res: Response, principalId: string, report: PublishContentReport): Promise<boolean> {
    const projection = toPublishContentDeps(deps);
    const authorized = withPublishTrustContentAuthorize(res, { authorize: deps.authorize }, registeredPublishTypePermissions(projection));
    const types = [...new Set(report.rows.map((row) => row.entityType))];
    for (const publishType of types) {
      const allowed = await authorized.authorize({ principalId, permission: "publish.backstop", workspaceId: deps.workspaceId, publishType } as Parameters<typeof deps.authorize>[0]);
      if (!allowed.allowed) return false;
    }
    return true;
  }

  /**
   * The planner does not attach backstop metadata; the apply loop adds that to the durable
   * run later. Detect raw rows themselves so the first manual plan also has a value review.
   * @returns the preview, `undefined` when there is none to show, or {@link RAW_VALUES_REFUSED}
   *   once the 403 has been sent.
   */
  async function rawPlanPreview(res: Response, input: { principalId: string; bundleId: string; report: PublishContentReport }) {
    if (!planCarriesRawRows(input.report)) return undefined;
    if (!(await mayReadRawValues(res, input.principalId, input.report))) {
      res.status(403).json({ error: "Manual publishing values are not available to this account.", code: "FORBIDDEN" });
      return RAW_VALUES_REFUSED;
    }
    const backstop = toPublishContentDeps(deps).backstop;
    const staged = await deps.publishContentBundleRepo.findById({ workspaceId: deps.workspaceId, id: input.bundleId });
    if (!staged || !backstop) return undefined;
    const entities = JSON.parse(staged.entitiesJson) as PackedEntity[];
    readBackstopMetadata({ entities });
    return buildBackstopPreview({ entities, backstop, workspaceId: deps.workspaceId });
  }

  app.post("/api/admin/v1/workspaces/:workspaceId/publish-content/import/plan", async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      const principal = getAuthedPrincipal(res);
      const bundleId = req.body?.bundleId;
      if (typeof bundleId !== "string") {
        res.status(400).json({ error: "'bundleId' (string) is required", code: "VALIDATION_ERROR" });
        return;
      }
      const overwriteEntityKeys = acceptOverwriteEntityKeys(res, req.body.overwriteEntityKeys, mayOverwrite);
      if (overwriteEntityKeys === OVERWRITE_REFUSED) return;

      const hooks = buildHooks(bundleId, principal.id, res, overwriteEntityKeys);
      const result = await plan({
        deps: withPublishTrustAuthorize(res, deps.gatedMutations.gatewayDeps),
        principalId: principal.id,
        principalKind: gatedPrincipalKindFor(getAuthedCredentialKind(res)),
        hooks: hooks as unknown as GatedMutationHooks<unknown, unknown>,
      });

      const report = result.details as PublishContentReport;
      const backstopPreview = await rawPlanPreview(res, { principalId: principal.id, bundleId, report });
      if (backstopPreview === RAW_VALUES_REFUSED) return;
      res.json({
        ...result,
        details: toPublishContentReportDto(report),
        ...(backstopPreview === undefined ? {} : { backstopPreview }),
      });
    } catch (err) {
      sendRefusal(res, importErrorResponse(err, { tracker: res.locals?.adminFailureTracker }));
    }
  });

  app.post("/api/admin/v1/workspaces/:workspaceId/publish-content/import/confirm", async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      const principal = getAuthedPrincipal(res);
      const { planId, planHash } = bodyRecord(req.body);
      if (typeof planId !== "string" || typeof planHash !== "string") {
        res.status(400).json({ error: "'planId' and 'planHash' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const record = await confirm({
        deps: withPublishTrustAuthorize(res, deps.gatedMutations.gatewayDeps),
        principalId: principal.id,
        // Reports the credential that actually authenticated this request rather than the literal
        // `"user"` this used to pass for every caller: a session is a human, an api_key is a peer
        // push, and a `publish_key` is the zero-setup publishing handshake. No `agent`-kind
        // principal can reach this handler — nothing authenticates as an agent through the admin
        // HTTP gate — so the "agent cannot confirm" property is still proved directly against
        // `gateway.confirm()` in this feature's unit tests, not via HTTP (`gated-hooks.test.ts`).
        principalKind: gatedPrincipalKindFor(getAuthedCredentialKind(res)),
        hooks: confirmOnlyHooks(deps.workspaceId),
        planId,
        planHash,
      });

      res.json({ confirmationToken: record.confirmationToken });
    } catch (err) {
      sendRefusal(res, importErrorResponse(err, { tracker: res.locals?.adminFailureTracker }));
    }
  });

  app.post("/api/admin/v1/workspaces/:workspaceId/publish-content/import/execute", async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      const principal = getAuthedPrincipal(res);
      const body = bodyRecord(req.body);
      const { bundleId, confirmationToken } = body;
      if (typeof bundleId !== "string" || typeof confirmationToken !== "string") {
        res.status(400).json({ error: "'bundleId' and 'confirmationToken' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }
      const overwriteEntityKeys = acceptOverwriteEntityKeys(res, body.overwriteEntityKeys, mayOverwrite);
      if (overwriteEntityKeys === OVERWRITE_REFUSED) return;

      // Pre-check mirroring `database/migrate-forward.ts`'s AUD-001 fix: authorize BEFORE the
      // costClass refusal ever runs, so an authenticated-but-unauthorized caller cannot learn this
      // workspace's restore-point capability at all. `gateway.execute()`'s own fresh authorize()
      // (CIC U-001) remains the authoritative check and is unchanged by this.
      const preCheck = await authorizeForHooks(
        withPublishTrustAuthorize(res, deps.gatedMutations.gatewayDeps),
        confirmOnlyHooks(deps.workspaceId),
        { principalId: principal.id, permission: "publish_content.apply" }
      );
      if (!preCheck.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'publish_content.apply' (${preCheck.reason})`,
          code: "NOT_AUTHORIZED",
        });
        return;
      }

      const hooks = buildHooks(bundleId, principal.id, res, overwriteEntityKeys);
      const capabilities = await deps.dbOps.getCapabilities();
      const result = await executePublishContentImport({
        workspaceId: deps.workspaceId,
        costClass: capabilities.restorePoint.costClass,
        gatewayExecute: () =>
          execute({
            deps: withPublishTrustAuthorize(res, deps.gatedMutations.gatewayDeps),
            principalId: principal.id,
            principalKind: gatedPrincipalKindFor(getAuthedCredentialKind(res)),
            hooks: hooks as unknown as GatedMutationHooks<
              unknown,
              {
                restorePointId: string;
                runId: string;
                changeSetIds: readonly string[];
                retiredChangeSetIds: readonly string[];
                repointChangeSetIds: readonly string[];
                menuLinksUpdated: number;
                menuLinksNotUpdated: readonly string[];
                verificationProblems: readonly string[];
              }
            >,
            confirmationToken,
          }),
      });

      // The manual result must name apply-time skips rather than repeat the dry-run prediction;
      // `readBackstopApplyReport` keeps that audit read advisory (its own doc).
      const applyReport = await readBackstopApplyReport({ audit: toPublishContentDeps(deps).backstop?.audit, workspaceId: deps.workspaceId, runId: result.runId });
      res.json({ ...result, ...applyReport });
    } catch (err) {
      sendRefusal(res, importErrorResponse(err, { tracker: res.locals?.adminFailureTracker }));
    }
  });

  app.get("/api/admin/v1/workspaces/:workspaceId/publish-content/runs/:runId", async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if ((await authorizedPrincipalId(res, deps, "publish_content.read")) === null) return;

      const runId = req.params.runId;
      const status = await getPublishContentRunStatus(deps.publishContentRunRepo, {
        workspaceId: deps.workspaceId,
        runId,
      });
      if (!status) {
        res.status(404).json({ error: "publish-content run was not found", code: "RUN_NOT_FOUND" });
        return;
      }
      res.json(status);
    } catch (err) {
      sendRefusal(res, importErrorResponse(err, { tracker: res.locals?.adminFailureTracker }));
    }
  });
};

import type { PeerCallDeps } from "#src/features/publish-content/peer-transport";
import { planPublishToPeer } from "#src/features/publish-content/push-plan";
import type { Response } from "express";

import { pullAndStageFromPeer } from "#src/features/publish-content/pull";
// Pull ordering/identity rationale: features/publish-content/pull.ts; this route stops at staging.
import type { PublishScope } from "#src/features/publish-content/ui/contract";
import {
  confirmPeerImport,
  executePeerImport,
  PublishContentPeerTransportError,
} from "#src/features/publish-content/peer-transport";
import { resolvePublishDestinationCredential } from "#src/features/publish-content/destination-credential";
import {
  PublishContentPeerCredentialMissingError,
  PublishContentPeerNotFoundError,
  PublishContentPeerSecretStoreUnconfiguredError,
} from "#src/features/publish-content/peers";
import { PublishTrustHandshakeError } from "#src/features/publish-trust/handshake-client";
import {
  canPublishToLive,
  PUBLISH_FROM_LIVE_SITE_CODE,
  PUBLISH_FROM_LIVE_SITE_ERROR,
} from "#src/features/publish-content/live-site-policy";
import { rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";

import { toPublishContentDeps, type PublishContentRouteDeps, type PublishContentRouteRegistrar } from "./deps.js";
import {
  acceptOverwriteEntityKeys,
  authorizedPrincipalId,
  bodyRecord,
  mappedErrorResponse,
  OVERWRITE_REFUSED,
  rejectForeignWorkspace,
  routeParam,
  sendRefusal,
  type MappedErrorClass,
  type RouteParamsRequest,
} from "./route-helpers.js";

/**
 * @file Task 10 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §1.6/§4 task 10.
 *
 * The operator-facing half of the outbound leg, under
 * `/api/admin/v1/workspaces/:workspaceId/publish-content/peers/:peerId/...`:
 *
 * - `POST .../push/plan` → build a bundle here, upload the blobs the peer lacks, stage it there,
 *   return the PEER's gated plan.
 * - `POST .../push/confirm` → relay the operator's confirmation to the peer.
 * - `POST .../push/execute` → relay the redemption; the peer applies.
 * - `POST .../pull` → fetch the peer's export and stage it HERE, returning a local `bundleId` that
 *   this instance's own `/import/plan|confirm|execute` then drives. One importer, two directions.
 *
 * ## FROZEN CONTRACT: every route here takes a `peerId`
 *
 * Never a raw URL and never a credential from the client. The URL comes from the
 * `publish_content_peers` row, and the credential is resolved from that row for the lifetime of one
 * request (see the next section). A client that could supply a URL would turn these routes into an SSRF primitive
 * wearing an authorization check; a client that could supply a credential would make the sealed
 * column pointless.
 *
 * ## Where the safety properties live
 *
 * On a PUSH, they live on the DESTINATION: the peer runs its own `gated-mutations` gateway, so
 * `PLAN_STALE`, single-redemption tokens, `AGENT_CANNOT_CONFIRM` and the restore point are enforced
 * by the code that owns the data being written. This file only relays — it cannot assert a principal
 * kind over the wire, so it cannot weaken the agent-confirm guard even in principle.
 *
 * On a PULL, they live HERE, in the existing `/import/*` ceremony — which is exactly why this pull
 * route stops at staging rather than planning: adding a second entry point into `planImport` would
 * be a second place the gate could be forgotten.
 *
 * ## Two kinds of destination, resolved in one place
 *
 * `openPeer` no longer calls `resolvePeerCredential` directly. `destination-credential.ts` decides
 * whether this destination is an explicitly-configured peer (a sealed key, opened per request) or
 * one this install is CONNECTED to (nothing stored; a session token minted by proving possession of
 * the site key). Both arrive as the same `ResolvedPeerCredential`, so every route below is
 * unchanged and cannot tell them apart.
 *
 * ## The credential never appears in a response
 *
 * Nothing in this file reads `credential.apiKey`; it is passed straight into the transport driver,
 * which puts it in one `Authorization` header. Every error body below is built from a typed error
 * whose message is derived from the PEER's response, never from the request.
 */

/** The typed errors a peer action answers with their own message. */
const PEER_ACTION_ERRORS: readonly MappedErrorClass[] = [
  [PublishContentPeerNotFoundError, 404, "PEER_NOT_FOUND"],
  // A connected destination's handshake. 502 for the same reason a transport error is: this
  // instance is fine and the request was well-formed — the far side (or the path to it) is what
  // failed, and the message is already the sentence the owner needs to act on.
  [PublishTrustHandshakeError, 502, "PUBLISH_TRUST_HANDSHAKE_FAILED"],
  [PublishContentPeerCredentialMissingError, 409, "PEER_CREDENTIAL_MISSING"],
  [PublishContentPeerSecretStoreUnconfiguredError, 503, "SECRET_STORE_UNCONFIGURED"],
];

/** Answers a peer action's failure. Manual publishing (`backstop.ts`) reuses it, so a live-site
 *  failure reaches the owner there as the same actionable answer; `message` names its private 500.
 *  @complexity O(1). */
export function respondWithError(res: Response, err: unknown, { message }: { message?: string } = {}): void {
  if (err instanceof PublishContentPeerTransportError) {
    // 502: this instance is fine and the request was well-formed; the PEER (or the path to it) is
    // what failed. A 500 here would send an operator looking in the wrong server's logs — and for
    // `EGRESS_REFUSED` specifically, the message is the `devHostAllowlist` diagnosis, which is only
    // actionable if it reaches them intact.
    res.status(502).json({ error: err.message, code: err.code });
    return;
  }
  // The mapper needs the registered template to distinguish preparation from an uncertain send.
  // Concrete request paths and mounted base URLs can contain private IDs and never enter copy.
  sendRefusal(res, mappedErrorResponse(err, PEER_ACTION_ERRORS, {
    tracker: res.locals?.adminFailureTracker, message, method: res.req?.method,
    route: typeof res.req?.route?.path === "string" ? res.req.route.path : undefined,
    discloseDetails: !res.req || !!res.locals?.principal,
  }));
}

/** The per-request transport bag: the guarded client plus the opened credential.
 *  @complexity O(1) plus one repo read and one AEAD open. */
async function openPeer(deps: PublishContentRouteDeps, peerId: string): Promise<PeerCallDeps> {
  const credential = await resolvePublishDestinationCredential({
    deps: {
      repo: deps.publishContentPeerRepo,
      sealer: deps.siteAssistantSecretSealer,
      keyring: deps.siteAssistantSecretKeyring,
      httpClient: deps.publishContentPeerHttpClient,
    },
    input: { workspaceId: deps.workspaceId, id: peerId },
  });
  return { credential, httpClient: deps.publishContentPeerHttpClient,
    publishHistory: { store: deps.publishHistoryStore, workspaceId: deps.workspaceId, clock: deps.clock } };
}

/** Distinguishes "the body carried a malformed selection" (a 400) from "the body carried none"
 *  (`null`, publish everything) — two outcomes a bare `null` return could not tell apart. */
const INVALID_SELECTION = Symbol("invalid-selection");

/**
 * Reads `push/plan`'s optional per-row selection: the `entityKey` strings
 * (`planner.ts`'s `${entityType}:${entityId}`) the operator left checked in the dialog.
 *
 * Absent means "publish everything", which is what every caller before the checkbox column sent and
 * what the dialog still sends when nothing was unchecked — the common path stays a bodyless POST.
 * An empty ARRAY is a real, different answer ("the operator unchecked everything") and is honoured
 * as such: it stages an empty bundle and plans to zero rows rather than quietly publishing the lot.
 *
 * @complexity O(n) in the submitted key count.
 */
function readSelectedEntityKeys(body: unknown): readonly string[] | null | typeof INVALID_SELECTION {
  const raw = bodyRecord(body);
  if (raw.selectedEntityKeys === undefined || raw.selectedEntityKeys === null) return null;
  if (!Array.isArray(raw.selectedEntityKeys)) return INVALID_SELECTION;
  if (!raw.selectedEntityKeys.every((key): key is string => typeof key === "string")) return INVALID_SELECTION;
  return raw.selectedEntityKeys;
}

/** `scope`'s per-field cap, matching `readOverwriteEntityKeys`'s 1000-entry bound (`route-helpers.ts`). */
const MAX_SCOPE_ARRAY_LENGTH = 1000;

/** @complexity O(1). */
function isNonEmptyStringArrayField(value: unknown): value is readonly string[] {
  return Array.isArray(value) && value.length > 0 && value.length <= MAX_SCOPE_ARRAY_LENGTH && value.every((v) => typeof v === "string");
}

/**
 * Reads `push/plan`'s optional `scope` (`plan-publish-sections-2026-09-25.md` §1) — the section (or
 * section-plus-rows) this plan is about, applied BEFORE `selectedEntityKeys` narrows further (this
 * file's own `push/plan` handler). Absent/`null` means "publish everything", the same "absent, not an
 * empty real answer" contract every other optional array field on this route reads by.
 *
 * A present `entityTypes` or `entityKeys` must be a non-empty array of strings (at most
 * {@link MAX_SCOPE_ARRAY_LENGTH} entries): an empty array is refused rather than silently treated as
 * "everything" or "nothing", since `selectedEntityKeys` already uses an empty array for "nothing" and
 * a caller sending `scope: {entityTypes: []}` almost certainly meant something else.
 *
 * @returns `{scope: null}` when the body carries no `scope`, `{scope}` (the validated
 *   {@link PublishScope}) when it is well-formed, or `{invalidField}` naming which field was wrong
 *   (`"scope"` itself when it is not an object or names neither field — never read as "everything").
 * @complexity O(n) in the submitted array lengths.
 */
function readPublishScope(body: unknown): { scope: PublishScope | null } | { invalidField: ScopeInvalidField } {
  const raw = bodyRecord(body);
  if (raw.scope === undefined || raw.scope === null) return { scope: null };
  if (typeof raw.scope !== "object" || Array.isArray(raw.scope)) return { invalidField: "scope" };
  const scopeBody = raw.scope as Record<string, unknown>;
  // A present scope naming neither field (`{}`, or a typo like `{types: [...]}`) would otherwise
  // narrow nothing — silently widening a one-section dialog to "publish everything". Refused.
  if (scopeBody.entityTypes === undefined && scopeBody.entityKeys === undefined) return { invalidField: "scope" };
  const invalidField = SCOPE_FIELDS.find((field) => scopeBody[field] !== undefined && !isNonEmptyStringArrayField(scopeBody[field]));
  return invalidField ? { invalidField } : { scope: presentScopeFields(scopeBody) };
}

const SCOPE_FIELDS = ["entityTypes", "entityKeys"] as const;
type ScopeInvalidField = "scope" | (typeof SCOPE_FIELDS)[number];

/** The scope fields the body carries, each already validated by {@link readPublishScope}.
 *  @complexity O(1) — two fixed fields. */
function presentScopeFields(scopeBody: Record<string, unknown>): PublishScope {
  return Object.fromEntries(SCOPE_FIELDS.filter((field) => scopeBody[field] !== undefined).map((field) => [field, scopeBody[field]]));
}

/** The 400 message for a malformed `scope`. @complexity O(1). */
function scopeErrorMessage(invalidField: ScopeInvalidField): string {
  return invalidField === "scope"
    ? "'scope' must be an object with 'entityTypes' and/or 'entityKeys'"
    : `'scope.${invalidField}' must be a non-empty array of strings`;
}

/**
 * Reads `push/plan`'s two narrowing fields: `selectedEntityKeys` first, then `scope`.
 * @returns the 400 message for the first malformed one, or both read values.
 * @complexity O(n) in the submitted array lengths.
 */
function readPushPlanNarrowing(body: unknown): { error: string } | { scope: PublishScope | null; selectedEntityKeys: readonly string[] | null } {
  const selectedEntityKeys = readSelectedEntityKeys(body);
  if (selectedEntityKeys === INVALID_SELECTION) return { error: "'selectedEntityKeys' must be an array of strings" };
  const scopeResult = readPublishScope(body);
  if ("invalidField" in scopeResult) return { error: scopeErrorMessage(scopeResult.invalidField) };
  return { scope: scopeResult.scope, selectedEntityKeys };
}

/**
 * publish-overwrite-live-plan §7: "Overwrite on live" ticks come only from a person's click. On
 * this relay that means a signed-in admin session; an API key (a script, or a model holding one) is
 * refused. The destination can't tell the difference — it only ever sees this instance's
 * publishing credential — so this is the one place the rule can hold for a push. Empty ticks ask
 * for nothing and pass.
 *
 * @returns `true` when the request may proceed. On `false` the 403 has already been sent.
 * @complexity O(1).
 */
function mayOverwrite(res: Response, overwriteEntityKeys: readonly string[] | null): boolean {
  if (overwriteEntityKeys === null || overwriteEntityKeys.length === 0) return true;
  return rejectUnlessSessionCredential(res, {
    message: "'overwriteEntityKeys' can only be sent from a signed-in admin session",
    permission: "publish_content.apply",
  });
}

export const registerPublishContentPeerTransportRoutes: PublishContentRouteRegistrar = (app, deps) => {
  const base = "/api/admin/v1/workspaces/:workspaceId/publish-content/peers/:peerId";

  /** Every route here shares the same preamble: mount-path 404, authenticated principal, and the
   *  `publish_content.apply` gate. Factored so a new peer action cannot accidentally ship without
   *  one of the three. Returns the principal id, or `null` when a response has already been sent. */
  const guard = async (req: RouteParamsRequest, res: Response): Promise<string | null> => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return null;
    return authorizedPrincipalId(res, deps, "publish_content.apply");
  };

  /** The push routes' extra preamble: the live site is the publish destination, so it never pushes
   *  (`live-site-policy.ts`). Runs before {@link guard} — nothing about the caller changes the answer. */
  const pushGuard: typeof guard = async (req, res) => {
    if (!canPublishToLive()) {
      res.status(403).json({ error: PUBLISH_FROM_LIVE_SITE_ERROR, code: PUBLISH_FROM_LIVE_SITE_CODE });
      return null;
    }
    return guard(req, res);
  };

  app.post(`${base}/push/plan`, async (req, res) => {
    try {
      const principalId = await pushGuard(req, res);
      if (principalId === null) return;

      const narrowing = readPushPlanNarrowing(req.body);
      if ("error" in narrowing) {
        res.status(400).json({ error: narrowing.error, code: "VALIDATION_ERROR" });
        return;
      }
      const overwriteEntityKeys = acceptOverwriteEntityKeys(res, bodyRecord(req.body).overwriteEntityKeys, mayOverwrite);
      if (overwriteEntityKeys === OVERWRITE_REFUSED) return;

      const peer = await openPeer(deps, routeParam(req, "peerId"));
      res.json(await planPublishToPeer({
        deps: { ...deps, publishContentDeps: toPublishContentDeps(deps) },
        peer,
        principalId,
      }, { scope: narrowing.scope, selectedEntityKeys: narrowing.selectedEntityKeys, overwriteEntityKeys }));
    } catch (err) {
      respondWithError(res, err);
    }
  });

  app.post(`${base}/push/confirm`, async (req, res) => {
    try {
      const principalId = await pushGuard(req, res);
      if (principalId === null) return;

      const { planId, planHash } = bodyRecord(req.body);
      if (typeof planId !== "string" || typeof planHash !== "string") {
        res.status(400).json({ error: "'planId' and 'planHash' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const peer = await openPeer(deps, routeParam(req, "peerId"));
      res.json(await confirmPeerImport(peer, { planId, planHash }));
    } catch (err) {
      respondWithError(res, err);
    }
  });

  app.post(`${base}/push/execute`, async (req, res) => {
    try {
      const principalId = await pushGuard(req, res);
      if (principalId === null) return;

      const body = bodyRecord(req.body);
      const { bundleId, confirmationToken } = body;
      if (typeof bundleId !== "string" || typeof confirmationToken !== "string") {
        res.status(400).json({ error: "'bundleId' and 'confirmationToken' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }
      const overwriteEntityKeys = acceptOverwriteEntityKeys(res, body.overwriteEntityKeys, mayOverwrite);
      if (overwriteEntityKeys === OVERWRITE_REFUSED) return;

      const peer = await openPeer(deps, routeParam(req, "peerId"));
      res.json(
        await executePeerImport(peer, {
          bundleId,
          confirmationToken,
          ...(overwriteEntityKeys === null ? {} : { overwriteEntityKeys }),
        })
      );
    } catch (err) {
      respondWithError(res, err);
    }
  });

  app.post(`${base}/pull`, async (req, res) => {
    try {
      const principalId = await guard(req, res);
      if (principalId === null) return;

      res.status(201).json(await pullAndStageFromPeer(deps, {
        peerId: routeParam(req, "peerId"),
        principalId,
      }));
    } catch (err) {
      respondWithError(res, err);
    }
  });
};

import type { Response } from "express";
import {
  createPublishContentPeer,
  deletePublishContentPeer,
  listPublishContentPeers,
  PublishContentPeerDuplicateLabelError,
  PublishContentPeerNotFoundError,
  PublishContentPeerSecretStoreUnconfiguredError,
  PublishContentPeerValidationError,
  updatePublishContentPeer,
} from "#src/features/publish-content/peers";
import type { PublishContentRouteRegistrar } from "./deps.js";
import {
  authorizedPrincipalId,
  bodyRecord,
  mappedErrorResponse,
  rejectForeignWorkspace,
  routeParam,
  sendRefusal,
  type MappedErrorClass,
} from "./route-helpers.js";

/**
 * @file Task 10 of the publish-content (Publish Content) feature —
 * `ADS-memory/reports/2026-09-18-publish-feature-implementation-plan.md` §4 task 10.
 *
 * CRUD for `publish_content_peers` under
 * `/api/admin/v1/workspaces/:workspaceId/publish-content/peers`.
 *
 * ## FROZEN CONTRACT (Task 10's dispatch — the admin UI is built against it)
 *
 * `GET .../peers` answers `{peers: [{id, label, baseUrl, remoteWorkspaceId, masked, hasCredential}]}`.
 * `masked` and `hasCredential` are the ONLY credential-shaped fields that ever leave the server —
 * no `sealedCiphertext`, `sealedNonce`, `sealedKeyId` or `sealedAlg` in any response body, log line
 * or error message, ever. That is enforced by construction rather than by review: every body below
 * is built from `PublishContentPeerSummary` (`features/publish-content/peers.ts`), a type with no
 * field capable of carrying sealed material, and this file never touches a
 * `PublishContentPeerRecord`.
 *
 * ## Permissions
 *
 * `publish_content.read` to list; `publish_content.apply` to create, update or delete. Deliberately
 * NOT `content.read`/`content.write`: those are a broader pre-existing pair, and reusing them here
 * would silently widen who can point this workspace's content at an external URL.
 */

/** Maps this feature's typed store errors to HTTP. Every case is a specific status — a validation
 *  refusal must never read as a server fault, and a duplicate label must never read as a validation
 *  error the operator can fix by retyping the same value. A raw driver error falls through to the
 *  approved request wording rather than being echoed (`mappedErrorResponse`). */
const PEER_ERRORS: readonly MappedErrorClass[] = [
  [PublishContentPeerValidationError, 400, "VALIDATION_ERROR"],
  [PublishContentPeerDuplicateLabelError, 409, "DUPLICATE_LABEL"],
  [PublishContentPeerNotFoundError, 404, "PEER_NOT_FOUND"],
  // The site key is unset/misconfigured. Operator-actionable and NOT a leak: the message names the
  // configuration failure, never the plaintext that failed to seal.
  [PublishContentPeerSecretStoreUnconfiguredError, 503, "SECRET_STORE_UNCONFIGURED"],
];

/** Preserve typed refusals while unexpected failures use the safe registered template and
 * authenticated-principal disclosure policy. Concrete paths and submitted values never enter copy.
 * @complexity O(bounded route tokens) for formatting; existing diagnostic sinks are unchanged.
 */
function respondToPeerFailure({ res, error }: { res: Response; error: unknown }): void {
  sendRefusal(res, mappedErrorResponse(error, PEER_ERRORS, {
    tracker: res.locals?.adminFailureTracker, method: res.req?.method,
    route: typeof res.req?.route?.path === "string" ? res.req.route.path : undefined,
    discloseDetails: !res.req || !!res.locals?.principal,
  }));
}

/** The write-side dependency bag, assembled once per handler from this module's route deps.
 *  @complexity O(1). */
function toWriteDeps(deps: Parameters<PublishContentRouteRegistrar>[1]) {
  return {
    repo: deps.publishContentPeerRepo,
    sealer: deps.siteAssistantSecretSealer,
    keyring: deps.siteAssistantSecretKeyring,
    clock: deps.clock,
    idGen: deps.idGen,
  };
}

const PEER_FIELDS = ["label", "baseUrl", "remoteWorkspaceId", "apiKey"] as const;

/** Keys are forwarded only when PRESENT — an absent key means "leave this field alone", which
 *  is what lets the UI rename a peer without re-collecting its credential. Spreading
 *  `undefined` in instead would make every PATCH a full replace.
 *  @complexity O(1) — four fixed fields. */
function presentPeerFields(body: Record<string, unknown>): Partial<Record<(typeof PEER_FIELDS)[number], unknown>> {
  return Object.fromEntries(PEER_FIELDS.filter((field) => field in body).map((field) => [field, body[field]]));
}

export const registerPublishContentPeerRoutes: PublishContentRouteRegistrar = (app, deps) => {
  const base = "/api/admin/v1/workspaces/:workspaceId/publish-content/peers";

  app.get(base, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if ((await authorizedPrincipalId(res, deps, "publish_content.read")) === null) return;
      const peers = await listPublishContentPeers({ repo: deps.publishContentPeerRepo }, { workspaceId: deps.workspaceId });
      res.json({ peers });
    } catch (err) {
      respondToPeerFailure({ res, error: err });
    }
  });

  app.post(base, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if ((await authorizedPrincipalId(res, deps, "publish_content.apply")) === null) return;
      const body = bodyRecord(req.body);
      const peer = await createPublishContentPeer(toWriteDeps(deps), {
        workspaceId: deps.workspaceId,
        label: body.label,
        baseUrl: body.baseUrl,
        remoteWorkspaceId: body.remoteWorkspaceId,
        apiKey: body.apiKey,
      });
      res.status(201).json({ peer });
    } catch (err) {
      respondToPeerFailure({ res, error: err });
    }
  });

  app.patch(`${base}/:peerId`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if ((await authorizedPrincipalId(res, deps, "publish_content.apply")) === null) return;
      const peer = await updatePublishContentPeer(toWriteDeps(deps), {
        workspaceId: deps.workspaceId,
        id: routeParam(req, "peerId"),
        ...presentPeerFields(bodyRecord(req.body)),
      });
      res.json({ peer });
    } catch (err) {
      respondToPeerFailure({ res, error: err });
    }
  });

  app.delete(`${base}/:peerId`, async (req, res) => {
    if (rejectForeignWorkspace(req, res, deps.workspaceId)) return;
    try {
      if ((await authorizedPrincipalId(res, deps, "publish_content.apply")) === null) return;
      // Idempotent 204, matching this codebase's other credential DELETE routes: deleting an
      // already-absent peer is a success, not a 404.
      await deletePublishContentPeer({ repo: deps.publishContentPeerRepo }, {
        workspaceId: deps.workspaceId,
        id: routeParam(req, "peerId"),
      });
      res.status(204).end();
    } catch (err) {
      respondToPeerFailure({ res, error: err });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { resolveDeepLinkContext, type DatabaseContextEnvelope } from "#src/features/recovery/deep-link";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
