import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { acquireOperationLock, releaseOperationLock } from "#src/contracts/core/operation-lock";
import { authorizeForHooks, confirm, execute, plan } from "#src/contracts/core/gated-mutations/gateway";
import { confirmRestore, executeRestore, planRestore } from "#src/features/recovery/recovery-orchestrator";
import { buildConfirmOnlyHooks } from "#src/contracts/core/gated-mutations/composition";
import { buildRestoreHooks, toRecoveryResult, type RecoveryErrorPayload } from "#src/features/recovery/gated-hooks";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

const RESTORE_PERMISSION = "backup.restore";

/**
 * @file SPEC-019 C-301/C-302/C-303 — `POST /api/admin/v1/recovery/restore/{plan,confirm,execute}`
 * (ADR-045 §3's restore ceremony). Gated by `backup.read` (`plan`/`confirm`) / `backup.restore`
 * (`execute`, enforced inside `gateway.ts`'s own fixed check-sequence). Mirrors
 * `routes/admin/taxonomy/merge-term.ts`'s 3-endpoint shape, composed directly over
 * `features/recovery/recovery-orchestrator.ts`'s already-built `planRestore`/`confirmRestore`/
 * `executeRestore` wrappers (this file supplies the `Result`-wrapped gateway binding + the real
 * `core/operation-lock.ts` primitive those wrappers were built to receive from a composition root
 * — see `features/recovery/gated-hooks.ts`'s `buildRestoreHooks` doc comment for the disclosed scope
 * boundary: the ceremony's token/authorize/lock plumbing is fully real, the final physical
 * `content.db` file replacement is not).
 */
/** HTTP status per gateway error code — a lookup table rather than a switch so a new code (a
 *  sixth 409, say) is one more row, not one more branch. */
const STATUS_BY_RECOVERY_ERROR_CODE: Readonly<Record<string, number>> = {
  NOT_AUTHORIZED: 403,
  AGENT_CANNOT_CONFIRM: 403,
  ACTOR_CLASS_MISMATCH: 403,
  VALIDATION_ERROR: 400,
  RESTORE_POINT_NOT_FOUND: 404,
  COST_CLASS_UNAVAILABLE: 409,
  PLAN_STALE: 409,
  TOKEN_EXPIRED: 409,
  TOKEN_ALREADY_REDEEMED: 409,
  RESTORE_OPERATION_IN_FLIGHT: 409,
};

function statusForCode(code: string): number {
  return STATUS_BY_RECOVERY_ERROR_CODE[code] ?? 500;
}

/** Exported for its own unit test: `RecoveryErrorPayload.message` is optional by contract, but every
 *  producer reachable from these three routes today (`toRecoveryResult`'s classifier and the
 *  orchestrator's own short-circuits) always sets one -- so the `?? error.code` fallback is only
 *  observable by handing this a contract-valid, message-less payload directly. */
export function sendRecoveryError(res: import("express").Response, error: RecoveryErrorPayload): void {
  const status = statusForCode(error.code);
  if (status === 500) { sendAdminFailure({ res, error: new Error(error.message ?? error.code) }, { operation: "routes/recovery/restore", code: error.code }); return; }
  res.status(status).json({ error: error.message ?? error.code, code: error.code });
}

/** The one 500 shape all three ceremony routes share for anything thrown outside the gateway's own
 *  `Result` wrapping (a missing session principal, a throwing `dbOps`/`authorize` port). */
function sendInternalError(res: import("express").Response, err: unknown): void {
  sendAdminFailure({ res, error: err }, { operation: "routes/recovery/restore", code: "INTERNAL_ERROR" });
}

export function registerAdminRecoveryRestoreRoutes(app: Express, deps: RouteDeps): void {
  app.post("/api/admin/v1/recovery/restore/plan", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const restorePointId = req.body?.restorePointId;
      if (typeof restorePointId !== "string") {
        res.status(400).json({ error: "'restorePointId' (string) is required", code: "VALIDATION_ERROR" });
        return;
      }

      const result = await planRestore({
        deps: {
          dbOps: {
            getCapabilities: async () => {
              const capabilities = await deps.dbOps.getCapabilities();
              return { costClass: capabilities.restorePoint.costClass, restorePointKind: capabilities.restorePoint.kind };
            },
          },
          gateway: {
            plan: (input) =>
              toRecoveryResult({ run: () =>
                plan({
                  deps: deps.gatedMutations.gatewayDeps,
                  principalId: input.principalId,
                  principalKind: input.principalKind,
                  hooks: buildRestoreHooks({
                    workspaceId: deps.workspaceId,
                    actorId: principal.id,
                    restorePointId: input.restorePointId,
                    clock: deps.clock,
                    idGen: deps.idGen,
                    restorePointsRepo: deps.restorePointsRepo,
                    databaseLedgerRepo: deps.databaseLedgerRepo,
                    dbOps: deps.dbOps,
                    migrationRunsRepo: deps.migrationRunsRepo,
                    siteStatus: deps.siteStatusRepo,
                  }) as never,
                }) }, {}
              ),
          },
        },
        input: { principalId: principal.id, principalKind: "user", restorePointId },
      });

      if (!result.ok) {
        sendRecoveryError(res, result.error);
        return;
      }
      res.json(result.value);
    } catch (err) {
      sendInternalError(res, err);
    }
  });

  app.post("/api/admin/v1/recovery/restore/confirm", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const { planId, planHash, disclosureAcknowledged } = req.body ?? {};
      if (typeof planId !== "string" || typeof planHash !== "string") {
        res.status(400).json({ error: "'planId' and 'planHash' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const result = await confirmRestore({
        deps: {
          gateway: {
            confirm: (input) =>
              toRecoveryResult({ run: async () => {
                const hooks = buildConfirmOnlyHooks({
                  domain: RESTORE_PERMISSION,
                  readPermission: "backup.read",
                  mutatePermission: RESTORE_PERMISSION,
                  scopeId: deps.workspaceId,
                  scopeKind: "instance",
                });
                const record = await confirm({
                  deps: deps.gatedMutations.gatewayDeps,
                  principalId: principal.id,
                  principalKind: "user",
                  hooks,
                  planId: input.planId,
                  planHash: input.planHash,
                });
                return { confirmationToken: record.confirmationToken };
              } }, {}),
          },
        },
        input: { principalId: principal.id, principalKind: "user", planId, planHash, disclosureAcknowledged: disclosureAcknowledged === true },
      });

      if (!result.ok) {
        sendRecoveryError(res, result.error);
        return;
      }
      res.json(result.value);
    } catch (err) {
      sendInternalError(res, err);
    }
  });

  app.post("/api/admin/v1/recovery/restore/execute", async (req, res) => {
    try {
      const principal = getAuthedPrincipal(res);

      // Audit finding AUD-001 (2026-07-16, external audit TM-20260716-full-session-001):
      // executeRestore acquires the shared cross-domain operation lock strictly before
      // gatewayExecute() runs -- that ordering exists for mutation-failure/lock-leak safety, not
      // authorization, so an unauthorized-but-authenticated caller could still reach and briefly
      // hold the lock before the gateway's own authorize() rejected them, contending with a
      // concurrent authorized restore. Authorize inline, before any lock acquisition; the
      // gateway's fresh authorize() re-check at execute time (CIC U-001) remains the authoritative
      // check and is unchanged by this.
      //
      // Routed through `authorizeForHooks` (not a hardcoded `deps.authorize` workspace-scoped
      // call) with `scopeKind: "instance"` -- `backup.restore`'s real scope, per
      // `features/recovery/gated-hooks.ts`'s `buildRestoreHooks` doc comment -- so this pre-check
      // agrees with what `execute()`'s own internal check will decide. A hardcoded workspace-scoped
      // check here would let a workspace-scoped-but-not-instance-authorized caller pass this gate,
      // briefly hold the lock, and only then be rejected deeper inside `execute()` -- reopening the
      // very race AUD-001 closed, one layer up.
      const authResult = await authorizeForHooks(
        deps.gatedMutations.gatewayDeps,
        buildConfirmOnlyHooks({
          domain: RESTORE_PERMISSION,
          readPermission: "backup.read",
          mutatePermission: RESTORE_PERMISSION,
          scopeId: deps.workspaceId,
          scopeKind: "instance",
        }),
        { principalId: principal.id, permission: RESTORE_PERMISSION }
      );
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'backup.restore' (${authResult.reason})`,
          code: "NOT_AUTHORIZED",
          details: { permission: RESTORE_PERMISSION, reason: authResult.reason },
        });
        return;
      }

      const { confirmationToken, restorePointId } = req.body ?? {};
      if (typeof confirmationToken !== "string" || typeof restorePointId !== "string") {
        res.status(400).json({ error: "'confirmationToken' and 'restorePointId' (strings) are required", code: "VALIDATION_ERROR" });
        return;
      }

      const hooks = buildRestoreHooks({
        workspaceId: deps.workspaceId,
        actorId: principal.id,
        restorePointId,
        clock: deps.clock,
        idGen: deps.idGen,
        restorePointsRepo: deps.restorePointsRepo,
        databaseLedgerRepo: deps.databaseLedgerRepo,
        dbOps: deps.dbOps,
        migrationRunsRepo: deps.migrationRunsRepo,
        siteStatus: deps.siteStatusRepo,
      });

      const result = await executeRestore({
        deps: {
          gateway: {
            execute: (input) =>
              toRecoveryResult({ run: async () => {
                return execute({
                  deps: deps.gatedMutations.gatewayDeps,
                  principalId: principal.id,
                  principalKind: "user",
                  hooks: hooks as never,
                  confirmationToken: input.confirmationToken,
                });
              } }, {}),
          },
          operationLock: { acquireOperationLock, releaseOperationLock },
          clock: deps.clock,
        },
        input: { principalId: principal.id, principalKind: "user", confirmationToken, siteId: deps.workspaceId },
      });

      if (!result.ok) {
        sendRecoveryError(res, result.error);
        return;
      }
      res.json(result.value);
    } catch (err) {
      sendInternalError(res, err);
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { isOperationInFlight } from "#src/contracts/core/operation-lock";
import { resolveDegradedBanner } from "#src/features/recovery/ui/degraded-banners";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { DatabaseRecoveryRouteDeps } from "../database-recovery/deps.js";

/**
 * @file design-spec.md §4.2/§4.4/§4.8 — `GET /api/admin/v1/recovery/status` (the capability/status
 * bar + the single highest-precedence degraded banner, ADR-045 §4). Gated by `backup.read`.
 *
 * `resolveDegradedBanner` itself is pure/no-I/O (`degraded-banners.ts`'s own file header) — this
 * route's only job is assembling its `capabilities` input from real (or, where disclosed below,
 * honestly-stubbed) sources:
 *  - `costClass`: real, from `deps.dbOps.getCapabilities()` (`db/sqlite/db-ops.ts`'s
 *    `SqliteDbOpsAdapter` in the running server).
 *  - `pendingMigration`/`migrationInterrupted`: real read of `deps.siteStatusRepo`. ADR-041/043/
 *    044/045 re-audit (2026-07-16, TM-adr041-043-044-045-audit-001, Finding 2 fix):
 *    `features/database/boot/*`'s reconciliation functions are now invoked by
 *    `server/runtime/boot/bootstrap.ts`'s `database-migration-reconciliation` boot module before the site opens
 *    to traffic, so this now reflects a REAL crash-interrupted-migration determination, not an
 *    always-`false` stub.
 *  - `operationInFlight`: real, from `core/operation-lock`'s `isOperationInFlight` read-only peek.
 *    ADR-041/043/044/045 re-audit (2026-07-16, TM-adr041-043-044-045-audit-001, Finding 3):
 *    the lock itself was already live in both gated ceremonies' `execute` routes before this fix
 *    (`migrate-forward.ts`/`restore.ts` both call the real `acquireOperationLock`/
 *    `releaseOperationLock`) — this route's own hardcoded `false` was the only actual gap, a
 *    display-only stub. `isOperationInFlight` closes it without changing the mutual-exclusion
 *    mechanism itself.
 *  - `watermarkBaselineAvailable`: `false`, matching `disclosure.ts` route's own honest stub.
 */
export function registerAdminRecoveryStatusRoute(app: Express, deps: DatabaseRecoveryRouteDeps): void {
  app.get("/api/admin/v1/recovery/status", async (_req, res) => {
    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "backup.read",
        workspaceId: deps.workspaceId,
        entityType: "restore-point",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'backup.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "backup.read", reason: authResult.reason },
        });
        return;
      }

      const capabilities = await deps.dbOps.getCapabilities();
      const siteStatus = await deps.siteStatusRepo.get(deps.workspaceId);

      const banner = resolveDegradedBanner({
        capabilities: {
          costClass: capabilities.restorePoint.costClass,
          operationInFlight: isOperationInFlight({ siteId: deps.workspaceId }, {}),
          pendingMigration: siteStatus === "PENDING_MIGRATION",
          migrationInterrupted: siteStatus === "BLOCKED_PENDING_RECOVERY",
          watermarkBaselineAvailable: false,
        },
      });

      res.json({ costClass: capabilities.restorePoint.costClass, banner });
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/recovery/status", code: "INTERNAL_ERROR" });
    }
  });
}

import { createRedirect, type RedirectMatchType, type RedirectStatusCode } from "@jini-ai/cms/redirects";
import { toAdminRedirectResponse, type RedirectRouteRegistrar } from "#src/server/inbound/admin-http/http/redirects";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { REDIRECT_WRITE_ERROR_MAPPINGS, respondToRedirectError } from "./shared.js";

const VALID_MATCH_TYPES = new Set(["exact", "prefix", "wildcard", "regex"]);
const VALID_STATUS_CODES = new Set([301, 302, 307, 308]);

/** This route's five body fields, validated and read off an untyped body in one place, or the 400
 *  message for the first violation.
 *  @complexity O(1). */
function parseRedirectCreateBody(rawBody: unknown):
  | {
      ok: true;
      matchType: RedirectMatchType;
      fromPattern: string;
      toTarget: string;
      statusCode: RedirectStatusCode;
      override: boolean | undefined;
      priority: number | undefined;
    }
  | { ok: false; error: string } {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  if (!VALID_MATCH_TYPES.has(body.matchType as string)) {
    return { ok: false, error: "matchType must be one of exact/prefix/wildcard/regex" };
  }
  if (typeof body.fromPattern !== "string" || typeof body.toTarget !== "string") {
    return { ok: false, error: "fromPattern and toTarget are required strings" };
  }
  if (!VALID_STATUS_CODES.has(body.statusCode as number)) {
    return { ok: false, error: "statusCode must be one of 301/302/307/308" };
  }
  return {
    ok: true,
    matchType: body.matchType as RedirectMatchType,
    fromPattern: body.fromPattern,
    toTarget: body.toTarget,
    statusCode: body.statusCode as RedirectStatusCode,
    override: typeof body.override === "boolean" ? body.override : undefined,
    priority: typeof body.priority === "number" ? body.priority : undefined,
  };
}

/**
 * POST a new manual redirect rule (api.spec.md `CREATE_REDIRECT`). Gated by
 * `admin.redirects.manage`. `matchType:'regex'` is a valid request shape per
 * api.spec.md but is always rejected by the chokepoint (REQ-22) — mapped to
 * `REDIRECT_VALIDATION_ERROR` here, same as any other chokepoint validation
 * failure, not a route-level shape rejection.
 */
export const registerAdminRedirectCreateRoute: RedirectRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/redirects", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const parsedBody = parseRedirectCreateBody(req.body);
    if (!parsedBody.ok) {
      res.status(400).json({ error: parsedBody.error, code: "VALIDATION_ERROR" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "admin.redirects.manage",
        workspaceId: deps.workspaceId,
        entityType: "redirect",
      });
      if (!authorized) return;

      const { record } = await createRedirect({
        deps: deps.redirectsWriteDeps,
        input: {
          workspaceId: deps.workspaceId,
          matchType: parsedBody.matchType,
          fromPattern: parsedBody.fromPattern,
          toTarget: parsedBody.toTarget,
          statusCode: parsedBody.statusCode,
          override: parsedBody.override,
          priority: parsedBody.priority,
          actorId: principal.id,
        },
      });

      res.status(201).json(toAdminRedirectResponse(record));
    } catch (err) {
      respondToRedirectError(res, err, REDIRECT_WRITE_ERROR_MAPPINGS);
    }
  });
};

