import type { SeoRouteRegistrar } from "./deps.js";

/** PUT (partial) workspace-level `seo.*` settings (SPEC-008 api.spec.md `SEO_PUT_SETTINGS`, tasks.md T047). */
export const registerAdminSeoPutSettingsRoute: SeoRouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/seo/settings", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      await deps.seoReady;
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "admin.seo.manage",
        workspaceId: deps.workspaceId,
        entityType: "seo-settings",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'admin.seo.manage' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "admin.seo.manage", reason: authResult.reason },
        });
        return;
      }

      const settings = await setSeoSettings(
        {
          settingsRepo: deps.settingsRepo,
          clock: deps.clock,
          ids: deps.idGen,
          authorize: deps.authorize,
          principals: deps.principalRepo,
          invalidateSitemap: deps.sitemapService.invalidateSitemapCache,
          media: deps.seoDeps.media,
        },
        { workspaceId: deps.workspaceId, patch: req.body ?? {}, callerPrincipalId: principal.id }
      );
      res.json({ data: settings });
    } catch (err) {
      if (err instanceof SeoSettingsValidationError) {
        res.status(400).json({ error: err.message, code: "SEO_SETTINGS_VALIDATION_ERROR" });
        return;
      }
      sendAdminFailure({ res, error: err }, { operation: "routes/seo/put-settings", code: "INTERNAL_ERROR" });
    }
  });
};

/**
 * @file `GET /api/admin/v1/workspaces/:workspaceId/settings/events` — a Server-Sent Events stream
 * that tells an open admin tab when settings it can read have changed, so it re-reads without a
 * page reload.
 *
 * ## Why polling the revision ledger rather than an in-process emitter
 *
 * The writes this must observe do not all happen here. `settings_set_ui_preference` executes in the
 * agent daemon (`assistant/agent-daemon-server.ts`), a separate OS process with its own connection
 * to the same SQLite file, and an in-process event emitter in this server would never hear it —
 * the same boundary that made the per-layer value cache unfixable (see `features/settings/
 * settings.ts`'s cache header).
 *
 * `setting_revisions.seq` is a monotonic AUTOINCREMENT in that shared file, written inside the same
 * transaction as every value and definition change (INV-01). Polling it therefore observes every
 * writer — this process, the daemon, a future background job — with no IPC, no broker, and no
 * coordination to get wrong. The cost is two indexed lookups per tick: the ledger head, then one
 * `seq > ?` page.
 *
 * ## The ledger is global; this stream is not
 *
 * One file holds every workspace's revisions, so `seq` is a position in a shared sequence rather
 * than in this workspace's own history. Both places that treat it as a coordinate have to account
 * for that, and both used to get it wrong in the same way: the page query took `limit` rows
 * globally and filtered afterwards in JS, so a busy tenant's writes crowded out a quiet one's, and
 * the resume cursor accepted any client-supplied `Last-Event-ID` without bounding it to the ledger.
 * The query is now workspace-predicated (see `features/settings/ports.ts`) and the cursor is
 * clamped to the head below. Disclosure was never the issue and is unchanged — `change-feed.ts`
 * remains the only thing that decides what a subscriber is told.
 *
 * ## Why this does not reintroduce the polling it replaces
 *
 * A tab could poll `/settings/effective` itself. It would cost one request per namespace per
 * interval per tab (six namespaces for the settings dialog alone), each resolving up to three
 * layers, and it would still be seconds stale. This is one connection per tab and one indexed
 * lookup per tick regardless of namespace count, and it sends nothing at all when nothing changed.
 *
 * ## Disclosure
 *
 * Frames carry namespace NAMES only, never values, and only for revisions
 * `features/settings/change-feed.ts` deems visible to the subscribing principal. A client re-reads
 * through the ordinary authorized `getSettingsEffective` path, so this endpoint cannot become a
 * way to obtain a value the caller could not already fetch. `settings.read` gates the subscription
 * itself, matching `get-effective.ts`.
 *
 * ### The emitted id is a global position, and that is an accepted decision
 *
 * `seq` is one AUTOINCREMENT shared by every workspace, so even a workspace's OWN revision is
 * stamped with a global number: one write in `ws-a` after fifty in `ws-b` emits `id: 51`. A
 * subscriber can difference the ids of its own consecutive events and infer roughly how many
 * settings writes happened platform-wide in between.
 *
 * Accepted rather than fixed. What leaks is a coarse aggregate write-count — no values, no
 * identities, nothing attributable to a particular tenant, and only for administrative settings
 * changes. Closing it needs either a per-workspace counter, which is a schema change on the write
 * path every writer shares (this process and the agent daemon both), or an opaque encrypted cursor,
 * which adds a key whose rotation would make reconnecting tabs silently skip the writes they
 * missed while still looking healthy. Both cost more than the disclosure is worth.
 *
 * **Revisit if** the ledger starts carrying higher-frequency or more attributable events than
 * administrative settings changes — the inference gets sharper as write volume rises.
 *
 * What is NOT accepted is emitting the global ledger HEAD, which `cursor` is advanced to below.
 * That would publish the platform-wide position on every frame, precisely and without the
 * subscriber writing anything. `__tests__/routes/settings-events-id-disclosure.test.ts` holds that
 * line, using a neighbour that writes AFTER this workspace does — the only arrangement in which
 * the two numbers differ.
 */

import { authorizeChangeFeed } from "./preview-feed-access.js";
import { createThemePreviewFeed, readThemePreviewRefresh } from "#src/features/theme/index";
import {
  collectChangedNamespaces,
  type ChangeFeedViewer,
  type ChangeFeedBatch,
} from "#src/features/settings/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { Express, Request, Response } from "express";
import type { SettingsRouteDeps } from "./deps.js";

type IntervalHandle = ReturnType<typeof setInterval>;

/** Interval scheduling for the feed's three timers; injectable so tests drive ticks themselves. */
type FeedTimers = {
  scheduleInterval?: (work: () => void, ms: number) => IntervalHandle;
  clearScheduledInterval?: (timer: IntervalHandle) => void;
};

/** The slice of the settings route deps this feed reads: the ledger's three revision reads, the
 *  authorizer, readiness, the themes folder for preview frames, and optional injected timers. */
export type SettingsEventsDeps = Pick<SettingsRouteDeps, "workspaceId" | "authorize" | "settingsReady" | "themesDir"> & {
  settingsRepo: Pick<SettingsRouteDeps["settingsRepo"], "maxRevisionSeq" | "listRevisionsSince" | "findDefinitionBySettingId">;
  feedTimers?: FeedTimers;
};

type ChangeFeedAccess = Awaited<ReturnType<typeof authorizeChangeFeed>>;

/** Who was admitted to the stream and which channels they may receive. */
type Admission = { principal: { id: string }; access: ChangeFeedAccess; includePreview: boolean };

/** How often the ledger is checked. Fast enough that a change feels immediate, slow enough that an
 *  idle tab costs ~1 indexed lookup/sec. */
const POLL_INTERVAL_MS = 1_000;

/** Comment frames keep proxies and load balancers from reaping an idle connection. */
const KEEPALIVE_INTERVAL_MS = 25_000;

/**
 * How often an open stream re-checks that its principal is still allowed to read
 * settings.
 *
 * A long-lived SSE connection outlives the single `authorize()` call that opened
 * it, so revoking a principal's `settings.read` did not stop the change
 * notifications already flowing to their open tab — the grant was effectively
 * pinned for as long as they kept the connection. Re-checking on a slow interval
 * rather than per tick keeps the cost near zero (one authorize per 30s per
 * stream, versus one per second) while bounding the revocation window.
 */
const REAUTHORIZE_INTERVAL_MS = 30_000;

/** Ledger rows examined per tick. Bounds a client resuming after a long absence — the remainder is
 *  drained on the following ticks rather than loaded at once. */
const REVISION_PAGE_SIZE = 200;

/**
 * Response headers for this SSE stream's opening `writeHead()`, minus `Connection` on an HTTP/2
 * request. Node's http2 compatibility layer throws `ERR_HTTP2_INVALID_CONNECTION_HEADER` the moment
 * a `connection` header reaches `writeHead()` — HTTP/2 has no per-hop connection semantics for it to
 * describe. Dropping it there costs nothing real: `keep-alive` was never anything but HTTP/1.1's
 * already-default behavior for a persistent connection, so omitting the header changes no observable
 * behavior for an HTTP/1.1 client, only stops a header HTTP/2 cannot accept from being sent to one.
 *
 * @param req - the originating request; only `httpVersionMajor` is read.
 * @complexity O(1).
 */
function sseWriteHeadHeaders(req: Request): Record<string, string> {
  return {
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache, no-transform",
    ...(req.httpVersionMajor < 2 ? { Connection: "keep-alive" } : {}),
    // Defeats nginx response buffering, which otherwise holds frames until the buffer fills —
    // indistinguishable from the feed being broken.
    "X-Accel-Buffering": "no",
  };
}

/**
 * The timers this stream schedules on, falling back to the globals.
 * @complexity O(1).
 */
function resolveFeedTimers(feedTimers: FeedTimers | undefined): Required<FeedTimers> {
  const { scheduleInterval = setInterval, clearScheduledInterval = clearInterval } = feedTimers ?? {};
  return { scheduleInterval, clearScheduledInterval };
}

/**
 * Admission for one subscription: 404 for another workspace, 401 when settings are not ready or
 * nobody is authenticated, 403 when neither the settings nor the theme-preview channel is granted.
 * Writes the refusal itself and returns null; otherwise returns who was admitted to what.
 * @complexity O(1) plus one or two authorizer calls.
 */
async function admitSubscriber(required: { req: Request; res: Response; deps: SettingsEventsDeps }): Promise<Admission | null> {
  const { req, res, deps } = required;
  if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
    res.status(404).json({ error: "workspace was not found" });
    return null;
  }

  let principal: { id: string };
  try {
    await deps.settingsReady;
    principal = getAuthedPrincipal(res);
  } catch {
    res.status(401).json({ error: "unauthenticated", code: "UNAUTHENTICATED" });
    return null;
  }

  const includePreview = req.query.themePreview === "1";
  const access = await authorizeChangeFeed({ authorize: deps.authorize, principalId: principal.id, workspaceId: deps.workspaceId, includePreview });
  if (!access.settings && !access.preview) {
    res.status(403).json({
      error: `principal '${principal.id}' is not authorized for 'settings.read' (${access.reason})`,
      code: "FORBIDDEN",
      details: { permission: "settings.read", reason: access.reason },
    });
    return null;
  }
  return { principal, access, includePreview };
}

/**
 * Resume point. `Last-Event-ID` is set by the browser automatically on `EventSource`'s own
 * reconnect, so a dropped connection replays the writes missed in the gap instead of silently
 * skipping them. A fresh subscriber starts at the current head — it has just loaded its values,
 * so replaying history would only make it re-read what it already has. Explicit tab handoff
 * or visibility reconnect uses afterRevision because a new EventSource cannot set headers.
 * Native Last-Event-ID takes precedence after that new source automatically reconnects.
 *
 * It is nonetheless client-supplied input naming a position in a ledger shared by every
 * workspace, so it is clamped INTO the ledger. An id past the head would otherwise park the
 * cursor in the future, and `seq > cursor` would then match nothing for as long as the tab
 * stayed open — a feed that is silently and permanently dead while still looking connected.
 *
 * @complexity O(1).
 */
function resumeCursor(required: { req: Request; head: number }): number {
  const { req, head } = required;
  const resumeFrom = Number(req.headers["last-event-id"] ??
    (typeof req.query.afterRevision === "string" ? req.query.afterRevision : undefined));
  return Number.isFinite(resumeFrom) && resumeFrom >= 0 ? Math.min(resumeFrom, head) : head;
}

/**
 * Runs an admitted, already-opened stream: polls the ledger, emits settings and theme-preview
 * frames, keeps the connection alive, re-authorizes, and tears its timers down on close.
 * @complexity O(1) setup; per tick, as `collectChangedNamespaces` over one page of at most
 *   `REVISION_PAGE_SIZE` revisions, with one definition lookup per new settingId.
 */
function runChangeFeed(required: Admission & {
  req: Request; res: Response; deps: SettingsEventsDeps; timers: Required<FeedTimers>; cursor: number;
}): void {
  const { req, res, deps, principal, includePreview } = required;
  const { scheduleInterval, clearScheduledInterval } = required.timers;
  let { access, cursor } = required;
  const viewer: ChangeFeedViewer = { workspaceId: deps.workspaceId, principalId: principal.id };

  /** The last id written to the wire — workspace-scoped, unlike `cursor`. See where it is emitted. */
  let lastEmittedId = cursor;

  /** Namespace per settingId, cached for the connection's life: a settingId's namespace changes
   *  only via `renameDefinition`, which appends its own revision and so re-notifies anyway. */
  const namespaceBySettingId = new Map<string, string | null>();
  const resolveNamespace = async (settingId: string): Promise<string | null> => {
    const cached = namespaceBySettingId.get(settingId);
    if (cached !== undefined) return cached;
    const definition = await deps.settingsRepo.findDefinitionBySettingId({ settingId });
    const namespace = definition?.namespace ?? null;
    namespaceBySettingId.set(settingId, namespace);
    return namespace;
  };

  // One tiny site-local marker bridges saves from the separate agent-daemon process.
  // Theme events have their own type and never advance the settings ledger's Last-Event-ID.
  const previewFeed = createThemePreviewFeed({
    read: () => deps.themesDir ? readThemePreviewRefresh({ themesDir: deps.themesDir }) : null,
    emit: (frame) => res.write(`event: theme-preview-refresh\ndata: ${JSON.stringify(frame)}\n\n`),
  }, { resumeRevision: typeof req.query.themeRevision === "string" ? req.query.themeRevision : undefined });
  let closed = false;
  /** True while a `tick` is mid-flight — see the guard at the top of `tick`. */
  let ticking = false;
  const close = (): void => {
    if (closed) return;
    closed = true;
    clearScheduledInterval(pollTimer);
    clearScheduledInterval(keepaliveTimer);
    clearScheduledInterval(reauthorizeTimer);
  };

  /**
   * Re-runs the same authorization that opened the stream, and ends it the
   * moment that stops holding or cannot be confirmed.
   *
   * Fail closed on errors: a later channel check may throw after settings.read was denied,
   * leaving the cached grant unchanged. Closing also suppresses any poll already in flight.
   */
  const reauthorize = async (): Promise<void> => {
    if (closed) return;
    try {
      access = await authorizeChangeFeed({ authorize: deps.authorize, principalId: principal.id, workspaceId: deps.workspaceId, includePreview });
      // Each channel is authorized independently; a theme-only subscriber never gets namespaces.
      if (closed || access.settings || access.preview) return;
    } catch (error) {
      console.error("[settings] change feed re-authorization failed", error);
    }
    close();
    res.end();
  };

  /** Write one visible batch, checking the current grant again after the ledger reads. */
  const emitSettingsChange = (batch: ChangeFeedBatch, _optional: Record<string, never> = {}): void => {
    if (closed || !access.settings || batch.namespaces.length === 0) return;

    // Emit the WORKSPACE-scoped position, not the internal `cursor`.
    //
    // `cursor` is advanced to the global ledger head so this connection can
    // skip past other tenants' rows, but the id is the one part of the frame
    // a subscriber can read. Emitting the global head would let a tab watch
    // its own event ids jump and count another workspace's write volume — a
    // metadata channel that only exists because the ledger is shared. The
    // workspace-scoped `batch.cursor` is a valid resume point: reconnecting
    // from it re-examines rows already examined, which the workspace
    // predicate makes cheap, and cannot skip anything.
    lastEmittedId = Math.max(lastEmittedId, batch.cursor);
    res.write(`id: ${lastEmittedId}\n`);
    res.write("event: settings-changed\n");
    res.write(`data: ${JSON.stringify({ namespaces: batch.namespaces })}\n\n`);
  };

  /**
   * One poll. Never throws: a transient read failure must not tear down a subscription the client
   * would then reconnect anyway, and `cursor` is left untouched so the same window is re-examined
   * on the next tick rather than skipped.
   */
  const tick = async (): Promise<void> => {
    if (closed || ticking) return;
    // `setInterval` does not await an async callback, and one tick does two
    // repo round trips plus a definition lookup per visible revision. A tick
    // slower than the poll interval would otherwise have the next one start
    // mid-await: both read the same `cursor`, both query the same window, both
    // can emit the same frame, and the `cursor` write becomes a lost update.
    ticking = true;
    try {
      if (!closed && access.preview) previewFeed();
      if (!access.settings) return;
      // Read the head BEFORE the page, so every row counted by it was already durable when the
      // query below ran. Reading it after would let a concurrent write inflate the head past rows
      // the query never had a chance to see, and the cursor advance would skip them.
      const ledgerHead = await deps.settingsRepo.maxRevisionSeq();
      const revisions = await deps.settingsRepo.listRevisionsSince({
        sinceSeq: cursor,
        limit: REVISION_PAGE_SIZE,
        workspaceId: deps.workspaceId,
      });

      const batch = await collectChangedNamespaces({
        revisions, viewer, resolveNamespace: ({ settingId }) => resolveNamespace(settingId),
      });
      // Advance even when nothing was visible, so writes this viewer cannot see are examined once
      // rather than on every tick forever.
      //
      // A SHORT page is what makes that true now that the query is workspace-filtered: fewer than
      // `REVISION_PAGE_SIZE` rows means the predicate ran out of matches before it ran out of
      // ledger, so everything up to `ledgerHead` has been examined and can be skipped past.
      // Advancing only to `batch.cursor` would leave the cursor parked behind a busy neighbour's
      // rows and re-walk them on every tick for the life of the connection.
      const examined = revisions.length < REVISION_PAGE_SIZE ? ledgerHead : batch.cursor;
      cursor = Math.max(cursor, examined, batch.cursor);
      emitSettingsChange(batch);
    } catch (error) {
      console.error("[settings] change feed poll failed", error);
    } finally {
      ticking = false;
    }
  };

  const pollTimer = scheduleInterval(() => void tick(), POLL_INTERVAL_MS);
  const keepaliveTimer = scheduleInterval(() => {
    if (!closed) res.write(": keepalive\n\n");
  }, KEEPALIVE_INTERVAL_MS);
  const reauthorizeTimer = scheduleInterval(() => void reauthorize(), REAUTHORIZE_INTERVAL_MS);

  // `close` fires on tab close, navigation, and `EventSource.close()` alike. Without this the
  // timers outlive the response and every reconnect leaks another pair.
  req.on("close", close);
  res.on("close", close);

  // An opening comment flushes headers immediately, so the client's `onopen` fires now rather
  // than whenever the first real change happens to arrive.
  res.write(": connected\n\n");
}

export const registerAdminSettingsEventsRoute = (app: Express, deps: SettingsEventsDeps): void => {
  app.get("/api/admin/v1/workspaces/:workspaceId/settings/events", async (req, res) => {
    // Resolved per request, not at registration: a test that swaps the global timers after the
    // route is registered must still be the one this stream schedules on.
    const timers = resolveFeedTimers(deps.feedTimers);
    const admission = await admitSubscriber({ req, res, deps });
    if (!admission) return;

    res.writeHead(200, sseWriteHeadHeaders(req));
    const cursor = resumeCursor({ req, head: await deps.settingsRepo.maxRevisionSeq() });
    runChangeFeed({ ...admission, req, res, deps, timers, cursor });
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import {
  buildSiteProfile,
  MAX_PAGE_ITEMS,
  SITE_PROFILE_SECTION_NAMES,
  toSiteProfileDeps,
  type SiteProfileSectionName,
} from "#src/features/site-inspection/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file `GET /api/admin/v1/workspaces/:workspaceId/site/profile` — the admin frontend's door to the
 * SAME `buildSiteProfile()` the `site_get_profile` agent tool calls.
 *
 * This route exists because `apps/admin` is a browser bundle and cannot invoke an agent tool. It is
 * the reason the aggregation lives in a shared service rather than inside a tool handler: without
 * it, the frontend would need a second implementation, and this codebase has already produced
 * exactly that divergence once (two independently-maintained `settings_get_effective`
 * implementations that drifted on principal handling).
 *
 * ---------------------------------------------------------------------------
 * Why this route does NOT `authorize()` before calling the service
 * ---------------------------------------------------------------------------
 * Every other read route in `routes/admin/` opens with a single `deps.authorize(...)` and 403s on
 * denial. This one deliberately does not, and the difference is the point of the feature.
 *
 * `buildSiteProfile` makes FIVE authorization decisions — one per section, each against the
 * permission that section's own domain already enforces — and marks a denied section `forbidden`
 * rather than failing the whole response. A blanket check here would either refuse a caller who is
 * entitled to four of the five sections, or (the realistic accident) read as "this route is
 * authorized" and invite a future maintainer to drop the per-section gates, which is precisely the
 * privilege-escalation bypass this design exists to prevent.
 *
 * The route is still authenticated: `requireAdminSession` is mounted on `/api/admin`
 * (`server/modules/core.ts`), so `getAuthedPrincipal(res)` always resolves a real principal, and
 * that principal is what every section is authorized as. A principal with no grants gets a
 * well-formed 200 in which every section is `forbidden` — which discloses nothing it could not
 * learn by calling the five underlying admin routes and being refused by each.
 *
 * Response shape and secret-safety are the service's, not this file's: nothing is projected,
 * filtered or redacted here. That is what makes `check:openapi-secret-leaks`'s real-server scan
 * over this route's body meaningful evidence for the agent tool too — both adapters return the same
 * object from the same builder.
 *
 * Workspace-id 404 and the `entityType` convention follow `system/deployment-overview.ts` and
 * `system/module-status.ts` exactly.
 */

/**
 * The exact slice of `RouteDeps` this route needs. `Pick` rather than the whole bag, matching
 * `AdminDeploymentOverviewDeps`'s precedent — and notably NOT including `createSiteApp`, since this
 * route never renders a published page.
 */
export type AdminSiteProfileDeps = Pick<
  RouteDeps,
  | "workspaceId"
  | "authorize"
  | "clock"
  | "postRepo"
  | "themes"
  | "presentationRepo"
  | "settingsRepo"
  | "getEffective"
  | "contentTypeRepo"
  | "pluginActivationRepo"
  | "discoverPlugins"
>;

/** Raised for a malformed query string, so the route can answer 400 with the offending rule named
 *  rather than silently coercing an unparseable value into a default. */
class SiteProfileQueryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SiteProfileQueryError";
  }
}

/**
 * Flattens `raw` (a query-string value Express hands back as a string or an array of strings when
 * `?sections=` is repeated) into a comma-split, trimmed, non-empty name list.
 *
 * @throws {SiteProfileQueryError} If any part of `raw` is not a string.
 * @complexity O(S) in the requested-section count.
 */
function splitRequestedSectionNames(raw: unknown): string[] {
  const parts = Array.isArray(raw) ? raw : [raw];
  const names: string[] = [];
  for (const part of parts) {
    if (typeof part !== "string") {
      throw new SiteProfileQueryError("sections must be a comma-separated string of section names");
    }
    for (const name of part.split(",")) {
      const trimmed = name.trim();
      if (trimmed !== "") names.push(trimmed);
    }
  }
  return names;
}

/**
 * Rejects any name outside the closed section vocabulary rather than dropping it: a caller that
 * asked for `secrets` and got a response with no `secrets` key could not tell "no such section"
 * from "that section was empty".
 *
 * @throws {SiteProfileQueryError} On the first unknown name.
 * @complexity O(S) in the requested-section count.
 */
function assertKnownSectionNames(names: string[]): asserts names is SiteProfileSectionName[] {
  const known = new Set<string>(SITE_PROFILE_SECTION_NAMES);
  for (const name of names) {
    if (!known.has(name)) {
      throw new SiteProfileQueryError(
        `unknown section '${name}' — valid sections are: ${SITE_PROFILE_SECTION_NAMES.join(", ")}`,
      );
    }
  }
}

/**
 * Parses `?sections=pages,theme` into the closed section vocabulary.
 *
 * Express parses a repeated `?sections=a&sections=b` into an array, so both spellings are accepted
 * and normalized here rather than forcing the frontend to pick one.
 *
 * @param raw - `req.query.sections`, whatever Express produced for it.
 * @returns The requested names, or `undefined` when the caller did not scope the request.
 * @throws {SiteProfileQueryError} On a non-string/array value or an unknown section name.
 * @complexity O(S) in the requested-section count.
 * @example parseSections("pages,theme"); // => ["pages", "theme"]
 */
export function parseSections(raw: unknown): SiteProfileSectionName[] | undefined {
  if (raw === undefined) return undefined;
  const names = splitRequestedSectionNames(raw);
  if (names.length === 0) return undefined;
  assertKnownSectionNames(names);
  return names;
}

/**
 * Parses `?pageLimit=25` into a positive integer.
 *
 * Out-of-range values are REJECTED here rather than silently clamped, even though
 * `buildSiteProfile` would clamp them anyway: an admin UI that sent `pageLimit=5000` and quietly
 * received 200 rows would have no signal that its request was not honored.
 *
 * @param raw - `req.query.pageLimit`.
 * @returns The parsed limit, or `undefined` when absent.
 * @throws {SiteProfileQueryError} When present but not an integer in `[1, MAX_PAGE_ITEMS]`.
 * @complexity O(1).
 * @example parsePageLimit("25"); // => 25
 */
export function parsePageLimit(raw: unknown): number | undefined {
  if (raw === undefined) return undefined;
  if (typeof raw !== "string") throw new SiteProfileQueryError("pageLimit must be a single integer value");
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed < 1 || parsed > MAX_PAGE_ITEMS) {
    throw new SiteProfileQueryError(`pageLimit must be an integer between 1 and ${MAX_PAGE_ITEMS}, got '${raw}'`);
  }
  return parsed;
}

export function registerAdminSiteProfileRoute(app: Express, deps: AdminSiteProfileDeps): void {
  app.get("/api/admin/v1/workspaces/:workspaceId/site/profile", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);

      let sections: SiteProfileSectionName[] | undefined;
      let pageLimit: number | undefined;
      try {
        sections = parseSections(req.query.sections);
        pageLimit = parsePageLimit(req.query.pageLimit);
      } catch (err) {
        if (err instanceof SiteProfileQueryError) {
          res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
          return;
        }
        throw err;
      }

      // No blanket authorize() — see this file's header. Every section is authorized inside
      // `buildSiteProfile` against its own domain's permission, as THIS principal.
      const profile = await buildSiteProfile(toSiteProfileDeps(deps), { principalId: principal.id }, { sections, pageLimit });
      res.status(200).json(profile);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/site/profile", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
/** Authenticated CMS lifecycle routes. Deployment/binding gates precede all filesystem/process effects. */
import type { Express, Request, Response } from "express";
import { authorizeOrRespond } from "../../authorize-guard.js";
import { getAuthedPrincipal } from "../../dev-auth.js";
import type { RouteDeps } from "#src/server/routes/types";
import { resolveSiteSwitchBase } from "#src/features/sites/index";
import { LocalSiteError, type LocalSiteSupervisorPort, trashSite, restoreSite, permanentlyDeleteTrashedSite, siteTrashName } from "#src/platform/site-dir/index";

export interface LocalSitesRouteDeps extends Pick<RouteDeps, "workspaceId" | "authorize" | "siteBinding"> {
  localSiteSupervisor?: LocalSiteSupervisorPort;
  afterTrash?: (required: { base: string; name: string }) => void;
  isSiteSwitcherEnabled: () => boolean;
  siteTrash?: { trash: typeof trashSite; restore: typeof restoreSite; remove: typeof permanentlyDeleteTrashedSite };
}
const STATUS: Record<string, number> = { VALIDATION_ERROR: 400, SITE_CONFIRM_REQUIRED: 400,
  SITE_NOT_FOUND: 404, SITE_SERVING: 409, SITE_RUNNING: 409, SITE_RUNNING_ELSEWHERE: 409, SITE_LIMIT: 409,
  SITE_ALREADY_EXISTS: 409, SITE_PATH_UNSAFE: 409, SITE_STOP_FAILED: 409 };
const PREFIX = "/api/admin/v1/workspaces/:workspaceId/system/sites";

function respondToLifecycleError({ res, error }: { res: Response; error: unknown }, _options = {}): void {
  if (!(error instanceof LocalSiteError)) { sendAdminFailure({ res, error }); return; }
  const code = error.code;
  // Never serialize an effect's raw error: child/connection errors can contain credentials.
  res.status(STATUS[code] ?? 500).json({ code, error: code });
}

function lifecycleHandler(deps: LocalSitesRouteDeps, action: (req: Request, base: string, supervisor: LocalSiteSupervisorPort) => Promise<unknown>) {
  return async (req: Request, res: Response) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
    const gate = resolveSiteSwitchBase({ binding: deps.siteBinding, switchingEnabled: deps.isSiteSwitcherEnabled() });
    if (!gate.ok) { res.status(gate.code === "SITE_SWITCHING_DISABLED" ? 403 : 409).json(gate); return; }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id,
        permission: "system.write", workspaceId: deps.workspaceId, entityType: "site-registry" }))) return;
      if (!deps.localSiteSupervisor) { res.status(409).json({ code: "SITE_HOST_UNAVAILABLE", error: "local site host is unavailable" }); return; }
      const result = await action(req, gate.switcherBase, deps.localSiteSupervisor);
      res.status(200).json(result ?? { ok: true });
    } catch (error) {
      respondToLifecycleError({ res, error });
    }
  };
}

/** Register only handlers; host lifetime belongs to the serving composition. @complexity O(1). */
export function registerLocalSitesRoutes({ app, deps }: { app: Express; deps: LocalSitesRouteDeps }, _options = {}): void {
  const trash = deps.siteTrash ?? { trash: trashSite, restore: restoreSite, remove: permanentlyDeleteTrashedSite };
  app.post(`${PREFIX}/:name/start`, lifecycleHandler(deps, (req, _base, supervisor) => supervisor.start({ name: String(req.params.name ?? "") })));
  app.post(`${PREFIX}/:name/stop`, lifecycleHandler(deps, (req, _base, supervisor) => supervisor.stop({ name: String(req.params.name ?? "") })));
  app.post(`${PREFIX}/:name/trash`, lifecycleHandler(deps, async (req, base, supervisor) => {
    if (req.body?.confirmed !== true) throw new LocalSiteError("SITE_CONFIRM_REQUIRED");
    const name = String(req.params.name ?? "");
    return supervisor.withStoppedSite({ name, task: async () => {
      const site = trash.trash({ base, name });
      deps.afterTrash?.({ base, name });
      return { site };
    } });
  }));
  app.post(`${PREFIX}/trash/:id/restore`, lifecycleHandler(deps, async (req, base, supervisor) => {
    const id = String(req.params.id ?? "");
    return supervisor.withStoppedSite({ name: siteTrashName({ id }), task: async () => { trash.restore({ base, id }); } });
  }));
  app.post(`${PREFIX}/trash/:id/delete`, lifecycleHandler(deps, async (req, base, supervisor) => {
    if (req.body?.checked !== true || req.body?.confirmed !== true) throw new LocalSiteError("SITE_CONFIRM_REQUIRED");
    const id = String(req.params.id ?? "");
    return supervisor.withStoppedSite({ name: siteTrashName({ id }), task: async () => {
      trash.remove({ base, id, checked: req.body?.checked === true, confirmed: req.body?.confirmed === true });
    } });
  }));
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
/** Admin Sites card previews: which running sites can be captured, and the image route.
 * The capture policy lives in `features/sites/site-preview/site-preview-service.ts`. */
import type { Express, Request } from "express";
import type { TLSSocket } from "node:tls";
import { authorizeOrRespond } from "../../authorize-guard.js";
import { getAuthedPrincipal } from "../../dev-auth.js";
import type { RouteDeps } from "#src/server/routes/types";
import { SITE_PREVIEW_CONTENT_TYPE, type SitePreviewService, type SitePreviewTarget } from "#src/features/sites/index";

const PREFIX = "/api/admin/v1/workspaces/:workspaceId/system/sites";

/** The fields of a local-site supervisor entry (`LocalSiteState`) a capture target needs. */
export interface PreviewableLocalSite {
  name: string;
  status: string;
  pid: number | null;
  adminUrl: string | null;
}

/**
 * Capture targets for every site with a live address: each RUNNING local site at its own public
 * root (derived from the supervisor's loopback `adminUrl`), plus the site this process serves at
 * the scheme and port this request actually arrived on — the socket's, not a forwarded header's,
 * so a proxy in front (Vite's dev proxy) cannot point the capture anywhere else.
 * @complexity O(n) in the local-site count.
 */
export function sitePreviewTargets(
  { servingName, localSites }: { servingName: string; localSites: readonly PreviewableLocalSite[] },
  { serving }: { serving?: { scheme: "http" | "https"; port: number; pid: number } } = {},
): SitePreviewTarget[] {
  const targets: SitePreviewTarget[] = [];
  if (serving) targets.push({ name: servingName, url: `${serving.scheme}://localhost:${serving.port}/`, lifecycle: `serving:${serving.pid}` });
  for (const site of localSites) {
    if (site.status !== "running" || site.adminUrl === null || site.pid === null || site.name === servingName) continue;
    targets.push({ name: site.name, url: new URL("/", site.adminUrl).href, lifecycle: `pid:${site.pid}` });
  }
  return targets;
}

/** This server's own listening scheme and port, from the request's socket; `undefined` without one.
 * @complexity O(1). */
export function servingAddressOf({ req }: { req: Pick<Request, "socket"> }, { pid = process.pid }: { pid?: number } = {}) {
  const socket = req.socket as (TLSSocket & { localPort?: number }) | undefined;
  if (!socket?.localPort) return undefined;
  return { scheme: socket.encrypted ? "https" as const : "http" as const, port: socket.localPort, pid };
}

export interface SitePreviewRouteDeps extends Pick<RouteDeps, "workspaceId" | "authorize"> {
  sitePreviews?: SitePreviewService;
}

/**
 * `GET .../system/sites/:name/preview` — the stored capture, or 404. The admin requests it as
 * `?v=<version>` from the listing's `previewVersions`, so the bytes behind one URL never change and
 * the browser may keep them indefinitely; a new capture is a new URL.
 * @complexity O(n) in the image size (one file read).
 */
export function registerSitePreviewRoutes({ app, deps }: { app: Express; deps: SitePreviewRouteDeps }, _optional = {}): void {
  app.get(`${PREFIX}/:name/preview`, async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id,
        permission: "system.read", workspaceId: deps.workspaceId, entityType: "site-registry" }))) return;
      const bytes = deps.sitePreviews?.read({ name: String(req.params.name ?? "") }) ?? null;
      if (bytes === null) { res.status(404).json({ code: "SITE_PREVIEW_NOT_FOUND", error: "no preview" }); return; }
      res.status(200).set({
        "Content-Type": SITE_PREVIEW_CONTENT_TYPE,
        "Cache-Control": "private, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
      }).send(bytes);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/sites/site-previews", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
/** Local creation-home setting, authorized at the same boundary as Sites mutations. */
import fs from "node:fs";
import path from "node:path";
import type { Express, Request, Response } from "express";
import { authorizeOrRespond } from "../../authorize-guard.js";
import { getAuthedPrincipal } from "../../dev-auth.js";
import { isSiteSwitcherEnabled, type SitesWorkspace } from "#src/platform/site-dir/index";
import type { AuthorizeFn } from "@jini-ai/cms/core";
import type { UUID } from "@jini-ai/core/primitives";
import { DirectoryUserConfigRefusal, validateDirectoryUserConfig } from "@jini-ai/platform/fs";

type SettingsDeps = {
  workspaceId: UUID;
  authorize: AuthorizeFn;
  isSiteSwitcherEnabled?: typeof isSiteSwitcherEnabled;
};

function admitSettingsRequest({ req, res, deps }: { req: Request; res: Response; deps: SettingsDeps }, _options = {}): boolean {
  if (String(req.params.workspaceId ?? "") !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return false; }
  if (!(deps.isSiteSwitcherEnabled ?? isSiteSwitcherEnabled)()) { res.status(403).json({ error: "Local sites management is disabled." }); return false; }
  return true;
}

export function registerSitesHomeRoutes({ app, deps, workspace }: { app: Express; deps: SettingsDeps; workspace: SitesWorkspace }, _options = {}): void {
  const configRoute = "/api/admin/v1/workspaces/:workspaceId/system/sites/config";
  for (const method of ["get", "put"] as const) app[method](configRoute, async (req, res) => {
    if (!admitSettingsRequest({ req, res, deps })) return;
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: method === "get" ? "system.read" : "system.write", workspaceId: deps.workspaceId, entityType: "site-registry" }))) return;
      if (method === "get") { res.json(workspace.config({})); return; }
      try {
        // Validate the shape before inspecting paths; malformed input is a refusal, not an I/O error.
        if (req.body?.sitesHome !== undefined) parseSettingsDirectory({ directory: req.body.sitesHome });
        const patch = validateDirectoryUserConfig({ value: req.body });
        validateSettingsDirectories({ patch });
        res.json(workspace.updateConfig({ patch }));
      }
      catch (error) {
        if (error instanceof DirectoryUserConfigRefusal) { res.status(400).json({ error: error.message }); return; }
        sendAdminFailure({ res, error }, { operation: "routes/sites/sites-home", code: "INTERNAL_ERROR", message: "Could not save sites settings." });
      }
    } catch (error) { sendAdminFailure({ res, error }, { operation: "routes/sites/sites-home", code: "INTERNAL_ERROR", message: "Could not read sites settings." }); }
  });
  app.put("/api/admin/v1/workspaces/:workspaceId/system/sites/home", async (req, res) => {
    if (!admitSettingsRequest({ req, res, deps })) return;
    try {
      const principal = getAuthedPrincipal(res);
      if (!(await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "system.write", workspaceId: deps.workspaceId, entityType: "site-registry" }))) return;
      const selected = req.body?.path;
      try {
        if (selected === undefined) throw new DirectoryUserConfigRefusal({ message: "Choose an absolute folder path for sites settings." });
        validateSettingsDirectories({ patch: { sitesHome: selected } });
      }
      catch (error) {
        if (error instanceof DirectoryUserConfigRefusal) { res.status(400).json({ error: error.message }); return; }
        throw error;
      }
      const home = workspace.setHome({ path: selected });
      res.json({ home });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/sites/sites-home", code: "INTERNAL_ERROR", message: "Could not save sites home." });
    }
  });
}

function validateSettingsDirectories({ patch }: { patch: { sitesHome?: unknown; siteRoots?: readonly string[] } }, _options = {}): void {
  for (const [directory, required] of [
    ...(patch.sitesHome !== undefined ? [[patch.sitesHome, false] as const] : []),
    ...(patch.siteRoots ?? []).map((root) => [root, true] as const),
  ]) {
    validateSettingsDirectory({ directory: parseSettingsDirectory({ directory }), required });
  }
}

function parseSettingsDirectory({ directory }: { directory: unknown }, _options = {}): string {
  if (typeof directory !== "string" || !directory.trim() || !path.isAbsolute(directory) || directory.includes("\0")) throw new DirectoryUserConfigRefusal({ message: "Choose an absolute folder path for sites settings." });
  return directory;
}

/** Both HTTP settings routes use absolute paths; roots must exist, and a new home needs its
 * parent mounted. A missing volume must never become a newly-created boot-disk directory.
 * @complexity O(1) stat probes per directory.
 */
function validateSettingsDirectory({ directory, required }: { directory: string; required: boolean }, _options = {}): void {
  try {
    if (!fs.statSync(directory).isDirectory()) throw new DirectoryUserConfigRefusal({ message: "Sites folder must be a directory." });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    if (required || !fs.existsSync(path.dirname(directory))) throw new DirectoryUserConfigRefusal({ message: `Sites folder is unavailable: ${directory}. Mount it or choose an existing local folder.` });
  }
}

/** Warm children delegate Sites management to the original dev host, never own another pool. */
import type { Express } from 'express';
import { requestLoopbackHttp } from '@jini-ai/platform/net';
import type { SiteBinding } from '#src/platform/site-dir/index';
import { resolveCheckoutRoot } from '#src/platform/site-dir/product-root';
import { resolveDevTls, resolveDevTlsCertPaths } from '#src/server/runtime/boot/dev-tls';

/** Preserve the child's actual serving binding in a host-owned listing. O(sites) time/space. */
export function warmSiteListing({ snapshot, binding }: { snapshot: Record<string, unknown>; binding: SiteBinding }, _options = {}) {
  const sites = Array.isArray(snapshot.sites) ? snapshot.sites as Array<{ name: string }> : [];
  return { ...snapshot, currentSite: { ...binding, listed: sites.some(site => site.name === binding.name) },
    sites: sites.map(site => ({ ...site, active: site.name === binding.name })) };
}

/** Relay only this resource after the ordinary admin session gate. Forward the original cookies,
 * so the host still authenticates/authorizes its own port-keyed session; no session is copied or
 * minted for a different site. The child subsequently authenticates on its own port as usual.
 * @returns True when this child delegates management; false for the host and every non-dev boot.
 * @complexity O(response bytes), bounded to 1 MiB and 55 seconds by the local HTTP adapter.
 */
export function registerWarmSiteControl({ app, binding, workspaceId }: { app: Express; binding: SiteBinding; workspaceId: string },
  { env = process.env }: { env?: NodeJS.ProcessEnv } = {}): boolean {
  const origin = env.TOVU_DEV_WARM_CONTROL_URL;
  const hostWorkspace = env.TOVU_DEV_WARM_CONTROL_WORKSPACE;
  if (env.TOVU_DEV_WARM_SITES !== '1' || !origin || !hostWorkspace) return false;
  const tls = resolveDevTls(resolveDevTlsCertPaths(resolveCheckoutRoot()), { env });
  const prefix = `/api/admin/v1/workspaces/${encodeURIComponent(workspaceId)}/system/sites`;
  app.use(prefix, async (req, res) => {
    try {
      const suffix = req.originalUrl.slice(prefix.length);
      const target = `${origin}/api/admin/v1/workspaces/${encodeURIComponent(hostWorkspace)}/system/sites${suffix}`;
      const reply = await requestLoopbackHttp({ url: target, method: req.method,
        headers: { cookie: req.headers.cookie ?? '', 'content-type': 'application/json' },
        ...(req.body === undefined ? {} : { body: JSON.stringify(req.body) }),
      }, { certificate: tls.credentials?.cert, timeoutMs: 55_000 });
      // Set-Cookie is intentionally not relayed: those are the host's credentials, never this
      // child's. Session renewal remains at each origin's ordinary auth endpoints.
      if (/\/preview(?:\?|$)/.test(suffix) && reply.status === 200) {
        res.status(200).type(reply.contentType ?? 'image/png').send(reply.body);
        return;
      }
      const snapshot = JSON.parse(reply.body.toString('utf8')) as Record<string, unknown>;
      res.status(reply.status).json(req.method === 'GET' && (suffix === '' || suffix.startsWith('?'))
        ? warmSiteListing({ snapshot, binding }) : snapshot);
    } catch {
      console.warn('tovu dev: warm site management host is unavailable.');
      res.status(503).json({ error: 'The dev site manager is unavailable. Return to the original dev server.' });
    }
  });
  return true;
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import path from "node:path";
import { loadInstalledSkillToolSources } from "#src/features/skills/tool-registrations";
import { PLUGIN_PACKAGE_FILE_LIMITS, readPluginPackageFiles } from "@jini-ai/plugins/host/node";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { SkillsRouteRegistrar } from "./deps.js";

/** Read-only sibling of plugin files: resolve an installed id before joining any path. */
export const registerSkillFilesRoute: SkillsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/skills/:toolId/files", async (req, res) => {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    const { toolId } = req.params;
    try {
      const principal = getAuthedPrincipal(res);
      if (!await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id, permission: "admin.assistant.use", workspaceId: deps.workspaceId,
      })) return;

      const sources = await loadInstalledSkillToolSources({ ...deps, workspaceId: deps.workspaceId, includeDisabled: true });
      const skill = sources.find(source => source.id === toolId);
      if (!skill?.directory) {
        res.status(404).json({ error: "Skill was not found or is disabled.", code: "NOT_FOUND" });
        return;
      }
      const containerDir = deps.skillLayout.forWorkspace(deps.workspaceId).root;
      // The directory comes from discovery, never request text. The shared reader enforces
      // realpath containment, no symlink following, and the same count/byte caps as Plugins.
      const { files, truncated } = await readPluginPackageFiles({
        input: { rootDir: path.join(containerDir, skill.directory), containerDir },
      });
      // Install records are server bookkeeping, including copies in nested skill folders.
      const visibleFiles = files.filter(file => path.posix.basename(file.relativePath) !== ".tovu-install.json");
      res.json({ toolId, files: visibleFiles, truncated, limits: PLUGIN_PACKAGE_FILE_LIMITS });
    } catch (error) {
      // Path errors can contain private server paths; match the plugin files refusal.
      sendAdminFailure({ res, error }, { operation: "routes/skills/files", code: "INTERNAL_ERROR" });
    }
  });
};

import { ToolInputError } from "@jini-ai/core";
import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { createHash } from "node:crypto";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { listManagedSkills } from "#src/features/skills/install-service";
import type { SkillsRouteRegistrar } from "./deps.js";

/**
 * @file C-001 `GET /api/admin/v1/workspaces/:workspaceId/skills` — implementation-outline.md
 * (skills-composer-typeahead), §Q1/§Contract Map.
 *
 * A plain read, same path grammar/workspace guard/authorize-then-project shape as
 * `routes/admin/plugins/list.ts`'s `PLUGINS_LIST`. Reads `<site>/skills/` fresh on every request via
 * `loadInstalledSkillToolSources` — the SAME function the agent daemon calls once at boot
 * (`agent-daemon-server.ts:887`) to register `skill_*` tools, while the agent registries refresh before discovery and execution. Permission is
 * `admin.assistant.use` (D-3): the same permission the skill tools themselves declare
 * (`tool-registrations.ts:333`), granted to the seeded owner's wildcard policy.
 *
 * Unexpected discovery failures are logged with a public error ID. Raw filesystem or provider
 * exceptions must never be returned verbatim.
 */
export const registerSkillsListRoute: SkillsRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/skills", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "admin.assistant.use",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const body = JSON.stringify({ skills: await listManagedSkills(deps) });
      const etag = `W/"${createHash("sha256").update(body).digest("base64url")}"`;
      res.set({ "Cache-Control": "private, no-cache", ETag: etag });
      res.vary("Cookie");
      // Not Express's req.fresh: fetch adds `Cache-Control: no-cache` to any request that carries
      // If-None-Match (Fetch spec), and `fresh` reads that as a reload, so it would never send 304.
      if (req.get("If-None-Match")?.split(",").some(tag => tag.trim() === etag)) {
        res.status(304).end();
        return;
      }
      res.type("json").send(body);
    } catch (error) {
      // C-001 requires the named duplicate folders; only the discovery owner marks this safe.
      if (error instanceof ToolInputError) { res.status(500).json({ error: error.message, code: "INTERNAL_ERROR" }); return; }
      sendAdminFailure({ res, error }, { operation: "routes/skills/list", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { SkillInstallInput } from "@jini-ai/agentic/skills/install";
import type { Request, Response } from "express";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { installSkill, setSkillEnabled, uninstallSkill, SkillInputError } from "#src/features/skills/install-service";
import { loadInstalledSkillToolSources, buildSkillToolRegistrations } from "#src/features/skills/tool-registrations";
import type { SkillsRouteRegistrar } from "./deps.js";
import type { ApplyExtensionApprovalPolicy } from "#src/contracts/headless/assistant-tool-approval-policy";

function hasUploadedSkillFiles(fields: Record<string, unknown>, _options = {}): fields is Record<string, unknown> & { files: { path: string; contentBase64: string }[] } {
  return Array.isArray(fields.files) && fields.files.every(f => {
    if (!f || typeof f !== "object") return false;
    return typeof f.path === "string" && typeof f.contentBase64 === "string"
      && Object.keys(f).every(key => ["path", "contentBase64"].includes(key));
  });
}

function installationInput(body: unknown, workspaceId: string): SkillInstallInput {
  if (!body || typeof body !== "object" || Array.isArray(body)) throw new SkillInputError({ message: "Choose exactly one source: GitHub URL, files, or ZIP." });
  const fields = body as Record<string, unknown>;
  if (fields.confirmed !== true) throw new SkillInputError({ message: "Confirm the skill installation first." });
  const sources = ["githubUrl", "files", "archiveBase64"].filter(key => fields[key] !== undefined);
  if (sources.length !== 1 || Object.keys(fields).some(key => !["confirmed", "githubUrl", "files", "archiveBase64"].includes(key))) throw new SkillInputError({ message: "Choose exactly one source: GitHub URL, files, or ZIP." });
  if (typeof fields.githubUrl === "string") return { workspaceId, githubUrl: fields.githubUrl };
  if (typeof fields.archiveBase64 === "string") return { workspaceId, archiveBase64: fields.archiveBase64 };
  if (hasUploadedSkillFiles(fields)) return { workspaceId, files: fields.files };
  throw new SkillInputError({ message: "Skill source has invalid fields." });
}

/** Session-gated routes; one validator/service owns every installation transport. */
export const registerSkillsManagementRoutes = (
  app: Parameters<SkillsRouteRegistrar>[0],
  deps: Parameters<SkillsRouteRegistrar>[1] & { withExtensionApprovalPolicy: ApplyExtensionApprovalPolicy },
): void => {
  const base = "/api/admin/v1/workspaces/:workspaceId/skills";
  const guarded = (work: (req: Request, res: Response) => Promise<void>) => async (req: Request, res: Response) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return; }
    try {
      const principal = getAuthedPrincipal(res);
      if (!await authorizeOrRespond(res, deps.authorize, { principalId: principal.id, permission: "admin.assistant.use", workspaceId: deps.workspaceId })) return;
      await work(req, res);
    } catch (error) {
      if (error instanceof SkillInputError) res.status(400).json({ error: error.message, code: "VALIDATION_ERROR" });
      else {  sendAdminFailure({ res, error }, { operation: "routes/skills/manage", code: "INTERNAL_ERROR", message: "Could not change skills. Try again." }); }
    }
  };
  app.post(base, guarded(async (req, res) => {
    const skill = await installSkill({ ...installationInput(req.body, deps.workspaceId), skillLayout: deps.skillLayout, siteBinding: deps.siteBinding });
    res.status(201).json({ skill });
  }));
  app.patch(`${base}/:toolId`, guarded(async (req, res) => {
    if (!req.body || typeof req.body.enabled !== "boolean" || Object.keys(req.body).some(key => key !== "enabled")) throw new SkillInputError({ message: "enabled must be a boolean." });
    await setSkillEnabled({ skillLayout: deps.skillLayout, siteBinding: deps.siteBinding, workspaceId: deps.workspaceId, toolId: String(req.params.toolId), enabled: req.body.enabled });
    res.json({ updated: true });
  }));
  app.delete(`${base}/:toolId`, guarded(async (req, res) => {
    await uninstallSkill({ skillLayout: deps.skillLayout, siteBinding: deps.siteBinding, workspaceId: deps.workspaceId, toolId: String(req.params.toolId) });
    res.json({ removed: true });
  }));
  app.get(`${base}/:toolId/guidance`, guarded(async (req, res) => {
    const sources = await loadInstalledSkillToolSources(deps);
    const source = sources.find(s => s.id === req.params.toolId);
    if (!source) { res.status(404).json({ error: "Skill was not found or is disabled.", code: "NOT_FOUND" }); return; }
    const [registration] = buildSkillToolRegistrations({ sources: [source], withExtensionApprovalPolicy: deps.withExtensionApprovalPolicy });
    // The selected skill's read-only handler and the browser share exactly the same payload.
    res.json(await registration!.handler({ executionId: "skill-preview", principal: { id: getAuthedPrincipal(res).id }, run: { id: "skill-preview" }, input: {}, signal: new AbortController().signal }));
  }));
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { restartAssistantDaemon as restartAssistantDaemonReal, type RestartAssistantDaemonResult } from "#src/server/runtime/lifecycle/daemon-supervisor";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin "Restart assistant" action — `POST /api/admin/v1/workspaces/:workspaceId/system/
 * assistant-daemon/restart`, the manual recovery seam for the locally-spawned agent daemon
 * (`src/assistant/daemon-supervisor.ts`). Sibling to the on-demand recovery wired into
 * `server/modules/assistant.ts`'s daemon-proxy code (`respondIfDaemonKnownFailed` now calls
 * `ensureAssistantDaemonStarted()` automatically on every known-failed request) — this route exists
 * for the case an operator wants to force it NOW rather than wait for the next request to trigger
 * it, or wants to recover a daemon whose crash-loop cap has already tripped (on-demand recovery
 * covers that too, but only once a request happens to arrive).
 *
 * `system.write`-gated, matching `dockerfile-source.ts`'s `PUT` route: this is a mutation on system
 * process state, not a read.
 *
 * ## What this route does NOT do
 *
 * `restartAssistantDaemon()` (`daemon-supervisor.ts`) is synchronous and returns as soon as the
 * restart has been INITIATED — it does not, and structurally cannot, wait for the new daemon
 * process to become healthy, because no "daemon became healthy" signal exists anywhere in this
 * codebase (see that function's own header). So this route's response means "a restart was
 * accepted", never "the assistant is back up". Reporting anything stronger — "restarted
 * successfully" as if that implied health — would be exactly the lying-comment failure mode a past
 * defect in this repo was caused by. Live status after the click is the caller's job, by polling
 * the existing `GET /readyz` (unauthenticated, already carries `assistantDaemonKnownFailed: true`
 * once a fresh failure latches) or `GET .../system/module-status` (`system.read`-gated, full detail,
 * `readiness-state.ts`'s `recordAssistantDaemonFailure` already folds the daemon's own failures into
 * that same snapshot) — this route intentionally returns neither.
 *
 * `restartAssistantDaemon()` refuses with `{ok: false, reason: "shutting down"}` only while THIS
 * Tovu process is itself tearing down (`daemon-supervisor.ts`'s `terminating` flag, set once by
 * `shutdown()` and never cleared) — a crash-loop cap having tripped does NOT refuse a manual
 * restart; that is the whole point of this seam existing separately from automatic respawn. Every
 * refusal reason is relayed to the caller verbatim, never translated into a generic error.
 */
export type AdminAssistantDaemonDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & {
  /**
   * Defaults to the real `restartAssistantDaemon` (`src/assistant`, backed by
   * `daemon-supervisor.ts`'s process-wide singleton). Injectable so a route test can prove both the
   * `{ok: true}` and `{ok: false, reason}` response shapes directly — the real implementation's
   * `{ok: true}` branch only occurs once a daemon process has actually been spawned this boot
   * (`startAssistantDaemon()`), which a route-level test has no business doing.
   */
  restartAssistantDaemon?: () => RestartAssistantDaemonResult;
};

export function registerAdminAssistantDaemonRoutes(app: Express, deps: AdminAssistantDaemonDeps): void {
  const restartAssistantDaemon = deps.restartAssistantDaemon ?? restartAssistantDaemonReal;

  app.post("/api/admin/v1/workspaces/:workspaceId/system/assistant-daemon/restart", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.write",
        workspaceId: deps.workspaceId,
        entityType: "assistant-daemon",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.write' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.write", reason: authResult.reason },
        });
        return;
      }

      const result = restartAssistantDaemon();
      if (!result.ok) {
        // 409, not 500: this is an ordinary "cannot do that right now" business-rule refusal (the
        // process is shutting down), the same status `publish-site.ts` uses for its own "a publish
        // is already running" refusal — never a server fault.
        res.status(409).json({ ok: false, reason: result.reason, code: "ASSISTANT_DAEMON_RESTART_REFUSED" });
        return;
      }
      res.status(200).json({ ok: true });
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/assistant-daemon", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { redactSecrets } from "@jini-ai/core";
import type { Express, Request, Response } from "express";

import { ADMIN_BROWSER_TELEMETRY_PER_PRINCIPAL, createRateLimiter, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import { getAuthedCredentialKind, getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file `POST /api/admin/v1/telemetry` — the admin browser's errors and page views, relayed to the
 * same neutral ports server code uses. The optional browser analytics contribution independently
 * follows metrics consent. Errors go to `observability.reportError` (whichever observability provider plugins are
 * installed + enabled + configured, else the no-op); page views go to `tracker.capture`
 * as `admin_pageview`, which `withProductAnalyticsGuards` drops unless the operator's telemetry
 * consent is on. Site attribution is added by the provider host, not here.
 *
 * Privacy: the body is a closed shape (unknown keys are refused, every string is capped), the
 * route is reduced to a template (query/fragment cut, id-like segments become `:id`), and message,
 * stack and component stack lose URL queries and pass core's secret/PII redaction before leaving.
 * Browser sessions only: a machine credential has no browser to report from.
 */

export type AdminBrowserTelemetryDeps = Pick<RouteDeps, "clock" | "tracker">;

export type BrowserTelemetryEvent =
  | { type: "error"; message: string; stack: string; componentStack?: string; route: string }
  | { type: "pageview"; route: string };

type Parsed = { ok: true; event: BrowserTelemetryEvent } | { ok: false; status: 400 | 413; error: string };

/** The whole request; the session body parser allows far more, so this route sets its own ceiling. */
export const MAX_TELEMETRY_BODY_BYTES = 16 * 1024;
const CAPS = { message: 1_000, stack: 8_000, componentStack: 4_000, route: 200 } as const;
const KEYS = { error: ["type", "message", "stack", "componentStack", "route"], pageview: ["type", "route"] } as const;
const REQUIRED = { error: ["message", "stack", "route"], pageview: ["route"] } as const;

const ROUTE_SHAPE = /^\/admin(?:\/[A-Za-z0-9:_.~-]*)*$/;
// Segments that name a record rather than a screen: numbers, UUIDs, hex ids, long mixed tokens.
const STRUCTURED_ID_SEGMENT = /^(?:\d+|[a-f\d]{8}-[a-f\d-]{27}|[a-f\d]{12,})$/i;
const MIXED_ID_SEGMENT = /^(?=[^/]*\d)[a-z\d_.~-]{16,}$/i;
// A URL's query or fragment inside free text (a stack frame, a fetch error); the URL itself and a
// stack frame's trailing `:line:col` stay. Both runs are bounded, so a long run costs linear time.
const URL_QUERY = /(\b[a-z][a-z0-9+.-]*:\/\/[^\s?#()'"]{0,2048})[?#][^\s()'"]{0,8192}?((?::\d+){0,2})(?=[\s()'"]|$)/gi;

/**
 * Reduces a browser route to its template: query and fragment cut, id-like segments `:id`.
 * @returns The template, or `null` when it is not an admin path.
 * @complexity O(n) in the route length (capped by the caller).
 */
export function toRouteTemplate(raw: string): string | null {
  const path = raw.split(/[?#]/, 1)[0] ?? "";
  if (!ROUTE_SHAPE.test(path)) return null;
  return path.split("/").map((segment) => ((STRUCTURED_ID_SEGMENT.test(segment) || MIXED_ID_SEGMENT.test(segment)) ? ":id" : segment)).join("/");
}

/** Cuts URL queries/fragments, then core redaction (keys, tokens, e-mails, phones). @complexity O(n). */
export function scrubTelemetryText(text: string): string {
  return redactSecrets({ input: text.replace(URL_QUERY, "$1$2") });
}

function checkFields(body: Record<string, unknown>, type: "error" | "pageview"): Parsed | null {
  const allowed: readonly string[] = KEYS[type];
  const unknown = Object.keys(body).find((key) => !allowed.includes(key));
  if (unknown) return { ok: false, status: 400, error: `unknown field '${unknown}'` };
  const missing = REQUIRED[type].find((key) => body[key] === undefined);
  if (missing) return { ok: false, status: 400, error: `missing field '${missing}'` };
  for (const key of allowed.slice(1)) {
    const value = body[key];
    if (value === undefined) continue;
    if (typeof value !== "string") return { ok: false, status: 400, error: `'${key}' must be a string` };
    if (value.length > CAPS[key as keyof typeof CAPS]) return { ok: false, status: 413, error: `'${key}' is too long` };
  }
  return null;
}

/**
 * Validates and sanitizes one request body into the event that may be forwarded.
 * @complexity O(n) in the (capped) body size.
 */
export function parseBrowserTelemetry(body: unknown): Parsed {
  if (typeof body !== "object" || body === null || Array.isArray(body)) return { ok: false, status: 400, error: "body must be an object" };
  const record = body as Record<string, unknown>;
  if (record.type !== "error" && record.type !== "pageview") return { ok: false, status: 400, error: "type must be 'error' or 'pageview'" };
  const invalid = checkFields(record, record.type);
  if (invalid) return invalid;
  const route = toRouteTemplate(record.route as string);
  if (route === null) return { ok: false, status: 400, error: "route must be an admin path" };
  return { ok: true, event: record.type === "pageview" ? { type: "pageview", route } : toErrorEvent(record, route) };
}

/** The error event with every free-text field scrubbed; fields were already checked to be strings. */
function toErrorEvent(record: Record<string, unknown>, route: string): BrowserTelemetryEvent {
  const componentStack = record.componentStack ? scrubTelemetryText(record.componentStack as string) : "";
  return { type: "error", route, message: scrubTelemetryText(record.message as string), stack: scrubTelemetryText(record.stack as string), ...(componentStack ? { componentStack } : {}) };
}

/** An `Error` carrying the browser's (already scrubbed) message and stack, not this route's. */
function toReportedError(event: Extract<BrowserTelemetryEvent, { type: "error" }>): Error {
  const error = new Error(event.message);
  error.name = "AdminBrowserError";
  error.stack = event.stack || `${error.name}: ${event.message}`;
  return error;
}

/** Hands one sanitized event to its port. Ports never throw by contract; this never awaits them. */
export function forwardBrowserTelemetry(deps: AdminBrowserTelemetryDeps, { event, principalId }: { event: BrowserTelemetryEvent; principalId: string }): void {
  if (event.type === "pageview") {
    deps.tracker.capture({ name: "admin_pageview", userId: principalId }, { properties: { route: event.route } });
    return;
  }
  const attributes = { source: "admin-browser", route: event.route, ...(event.componentStack ? { componentStack: event.componentStack } : {}) };
  deps.tracker.error({ error: toReportedError(event) }, { context: { operation: "admin.browser.error", attributes } });
}

/** This route's own per-principal budget (a browser with a render loop must not flood a vendor). */
export function createBrowserTelemetryLimiter(deps: Pick<RouteDeps, "clock">): RateLimiter {
  return createRateLimiter({ profile: ADMIN_BROWSER_TELEMETRY_PER_PRINCIPAL, clock: deps.clock });
}

async function admit(limiter: RateLimiter, req: Request, res: Response): Promise<string | null> {
  if (getAuthedCredentialKind(res) !== "session") {
    res.status(403).json({ error: "browser telemetry requires a signed-in session", code: "FORBIDDEN" });
    return null;
  }
  // Early rejection only: the authenticated dispatcher enforces decoded streamed bytes first.
  if (Number(req.headers["content-length"] ?? 0) > MAX_TELEMETRY_BODY_BYTES) {
    res.status(413).json({ error: "telemetry body is too large", code: "PAYLOAD_TOO_LARGE" });
    return null;
  }
  const principalId = getAuthedPrincipal(res).id;
  const result = await limiter.check({ key: principalId });
  if (result.allowed) return principalId;
  res.setHeader("Retry-After", String(result.retryAfterSeconds));
  res.status(429).json({ error: "too many telemetry events", code: "RATE_LIMIT_EXCEEDED" });
  return null;
}

/**
 * Registers `POST /api/admin/v1/telemetry` (behind `requireAdminSession`, like all of `/api/admin`).
 * @complexity O(n) in the capped body; one limiter check.
 */
export function registerAdminBrowserTelemetryRoute(app: Express, deps: AdminBrowserTelemetryDeps, limiter: RateLimiter = createBrowserTelemetryLimiter(deps)): void {
  app.post("/api/admin/v1/telemetry", async (req, res) => {
    try {
      const principalId = await admit(limiter, req, res);
      if (principalId === null) return;
      const parsed = parseBrowserTelemetry(req.body);
      if (!parsed.ok) {
        res.status(parsed.status).json({ error: parsed.error, code: parsed.status === 413 ? "PAYLOAD_TOO_LARGE" : "INVALID_INPUT" });
        return;
      }
      forwardBrowserTelemetry(deps, { event: parsed.event, principalId });
      res.status(204).end();
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/system/browser-telemetry", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "../../dev-auth.js";
import { authorizeOrRespond } from "../../authorize-guard.js";
import { isLocalAdminRequest } from "../../local-admin-request.js";
import { ToolInputError } from "@jini-ai/core";
import type { RouteDeps } from "#src/server/routes/types";

type Deps = Pick<RouteDeps, "workspaceId" | "ownerPrincipalId" | "authorize" | "gatedMutations" | "projectKeys">;
const BASE = "/api/admin/v1/workspaces/:workspaceId/system/credential-copy";

async function authorizedCopy({ res, deps, actorId, permission = "system.write" }: { res: Response; deps: Deps; actorId: string; permission?: string }, _options = {}): Promise<boolean> {
  if (!await authorizeOrRespond(res, deps.authorize, { principalId: actorId, permission, workspaceId: deps.workspaceId })) return false;
  const instance = deps.gatedMutations.gatewayDeps.authorizeInstance;
  if (instance && !(await instance({ principalId: actorId, permission })).allowed) {
    res.status(403).json({ reasonCode: "owner-only" }); return false;
  }
  return true;
}

/** Every verb requires the seeded owner's session, existing RBAC and optional instance admission. */
async function admitted({ req, res, deps }: { req: Request; res: Response; deps: Deps }, _options = {}): Promise<boolean> {
  res.setHeader("Cache-Control", "no-store");
  if (!rejectUnlessSessionCredential(res, { message: "Use the owner's session to use saved keys.", permission: "system.write" })) return false;
  if (req.params.workspaceId !== deps.workspaceId) { res.status(404).json({ error: "workspace was not found" }); return false; }
  const actorId = getAuthedPrincipal(res).id;
  if (actorId !== await deps.ownerPrincipalId) { res.status(403).json({ reasonCode: "owner-only" }); return false; }
  if (!await authorizedCopy({ res, deps, actorId })) return false;
  if (!deps.projectKeys || !isLocalAdminRequest({ req })) {
    res.status(403).json({ reasonCode: "local-host-only" }); return false;
  }
  return true;
}

function validCopyIds({ ids }: { ids: unknown }, _options = {}): boolean {
  return Array.isArray(ids) && ids.length >= 1 && ids.length <= 100 &&
    ids.every((id: unknown) => typeof id === "string" && id.length > 0 && id.length <= 512 && !/[\x00-\x1f\x7f]/.test(id));
}

/** Owner-only browser picker; one approval submits one reference to this server-bound site. */
export function registerAdminCredentialCopyRoutes({ app, deps }: { app: Express; deps: Deps }, _options = {}): void {
  const handle = (action: (req: Request, res: Response) => Promise<void>) => async (req: Request, res: Response) => {
    try {
      if (await admitted({ req, res, deps })) await action(req, res);
    } catch (error) {
      // Never serialize raw driver/crypto exceptions; logs receive only the shared redacted diagnostic.
      if (error instanceof ToolInputError) res.status(409).json({ reasonCode: "saved-key-refused", message: error.message });
      else sendAdminFailure({ res, error }, { operation: "routes/system/credential-copy", code: "INTERNAL_ERROR", field: "message", message: "Using the saved key failed. Reopen Shared Keys and choose the key again.", details: { reasonCode: "copy-failed" } });
    }
  };
  app.get(BASE, handle(async (_req, res) => {
    const rows = await deps.projectKeys!.listChoices({});
    res.json({ sources: [{ siteId: "shared-keys", name: "Shared Keys", keys: rows.map(row => ({
      kind: row.kind, id: row.keyId, label: row.name, provider: null, worksFor: [],
      ...(row.siteName ? { siteName: row.siteName } : {}), ...(row.locked ? { locked: row.locked } : {}),
    })) }] });
  }));
  app.post(BASE, handle(async (req, res) => {
    const body = req.body;
    const isObject = body && typeof body === "object" && !Array.isArray(body);
    const validKeys = isObject && !Object.keys(body).some(key => !["sourceSiteId", "ids", "overwrite"].includes(key));
    const validSource = validKeys && body.sourceSiteId === "shared-keys";
    if (!validSource || !validCopyIds({ ids: body.ids }) || body.ids.length !== 1 || body.overwrite !== false) {
      res.status(400).json({ reasonCode: "invalid-request" }); return;
    }
    const keyId = body.ids[0] as string;
    const permission = await deps.projectKeys!.permissionFor({ keyId });
    if (!await authorizedCopy({ res, deps, actorId: getAuthedPrincipal(res).id, permission })) return;
    const used = await deps.projectKeys!.use({ keyId, use: true });
    res.json({ results: [{ kind: "reference", id: used.keyId, status: "granted" }] });
  }));
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { ToolInputError } from "@jini-ai/core";
import { invalidatePublishCredentialCompatibility } from "#src/features/deployments/publish-credentials/index";
import type { Express, Request, Response } from "express";

import {
  createCustomCredential,
  describeCredential,
  CustomCredentialDuplicateLabelError,
  CustomCredentialConcurrentModificationError,
  CustomCredentialNotFoundError,
  CustomCredentialSecretStoreUnconfiguredError,
  CustomCredentialValidationError,
  deleteCustomCredential,
  listCustomCredentialInventory,
  updateCustomCredential,
  type UpdateCustomCredentialInput,
  type CustomCredentialSummary,
} from "#src/features/custom-credentials/index";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin Access Tokens page's "Add custom provider" CRUD backend.
 *
 * Registers `GET`/`POST` on the collection and `PUT`/`DELETE` on a single credential set, all under
 * `/api/admin/v1/workspaces/:workspaceId/system/custom/credentials`. Deliberately a THIN HTTP
 * adapter over `features/custom-credentials/store.ts` — every validation, uniqueness, and shape
 * rule already lives there; this route's only job is: check auth, shape the request into
 * `store.ts`'s input types, map its thrown errors to HTTP status codes, and return
 * `CustomCredentialSummary` — never the sealed connection, never a token, never a username.
 * Structurally mirrors `source-control-credentials.ts` byte-for-byte.
 *
 * `custom-credentials.write`-gated on every verb, a NEW dot-namespaced permission (not reused from
 * either sibling feature) — matches the established per-feature permission convention
 * `source-control-credentials.ts`'s own header traces; the seeded owner's wildcard grant authorizes
 * it immediately with no seed edit required.
 *
 * See `CredentialsDeps` in `server/routes/types.ts` for why each route picks only its own repo.
 */
export type AdminCustomCredentialsDeps = Pick<
  RouteDeps,
  "workspaceId" | "authorize" | "clock" | "idGen" | "customCredentialSetRepo" | "siteAssistantSecretSealer" | "siteAssistantSecretKeyring"
> & Partial<Pick<RouteDeps, "loadDeployTargets" | "publishCredentialVerificationCache" | "projectKeys" | "ownerPrincipalId">>;

const PERMISSION = "custom-credentials.write";
const ENTITY_TYPE = "custom-credentials";

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/system/custom/credentials";

/** Every error this route can produce, shaped once so each handler below stays a thin dispatch —
 *  mirrors `source-control-credentials.ts`'s own `sendStoreError`. */
function sendStoreError(res: Response, err: unknown): void {
  if (err instanceof ToolInputError) { res.status(409).json({ error: "KEY_IN_USE", detail: err.message }); return; }
  if (err instanceof CustomCredentialValidationError) {
    res.status(400).json({ error: "VALIDATION", detail: err.message });
    return;
  }
  if (err instanceof CustomCredentialConcurrentModificationError) {
    res.status(409).json({ error: "CONCURRENT_MODIFICATION", detail: err.message });
    return;
  }
  if (err instanceof CustomCredentialDuplicateLabelError) {
    res.status(409).json({ error: "DUPLICATE_LABEL", detail: err.message });
    return;
  }
  if (err instanceof CustomCredentialNotFoundError) {
    res.status(404).json({ error: "NOT_FOUND", detail: err.message });
    return;
  }
  if (err instanceof CustomCredentialSecretStoreUnconfiguredError) {
    res.status(503).json({ error: "SECRET_STORE_UNCONFIGURED", detail: err.message });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/system/custom-credentials", code: "INTERNAL_ERROR" });
}

/**
 * Builds the PUT body into `updateCustomCredential`'s partial-update input — each field is forwarded
 * only when the request actually supplied that key (an omitted key must leave the stored value
 * alone; see `UpdateCustomCredentialInput`'s own per-field "omitted = unchanged" doc). Extracted from
 * the PUT handler below: six independent `!== undefined` checks inlined into one object literal
 * pushed that handler's cyclomatic complexity to 10 against the repo's ceiling of 9 — this helper's
 * own complexity is a flat 7 (one per checked field, no nesting), comfortably under the gate.
 */
function buildUpdateCredentialInput(workspaceId: string, id: string, body: Record<string, unknown>): UpdateCustomCredentialInput {
  return {
    workspaceId,
    id,
    ...(body.label !== undefined ? { label: body.label } : {}),
    ...(body.category !== undefined ? { category: body.category } : {}),
    ...(body.baseUrl !== undefined ? { baseUrl: body.baseUrl } : {}),
    ...(body.additionalHosts !== undefined ? { additionalHosts: body.additionalHosts } : {}),
    ...(body.worksFor !== undefined ? { worksFor: body.worksFor } : {}),
    ...(body.connection !== undefined ? { connection: body.connection } : {}),
    // Independent of `connection` (2026-09-01) — `body.username` travels through even on a
    // request that carries no `connection` at all. `null` (an explicit clear) survives this
    // check exactly like a string does; only an actually-absent JSON key reads as `undefined`
    // and gets skipped, same "omitted key vs. present null" distinction `store.ts`'s own
    // `UpdateCustomCredentialInput.username` doc relies on.
    ...(body.username !== undefined ? { username: body.username } : {}),
  };
}

/** The site's Access Tokens add action is its explicit yes; other sites still need their own yes. */
async function attachAddedProjectKey({ credential, keys }: { credential: CustomCredentialSummary; keys: AdminCustomCredentialsDeps["projectKeys"] }, _optional = {}) {
  if (credential.scope !== "project" || !keys) return credential;
  const usage = await keys.use({ keyId: credential.id, use: true });
  return { ...credential, usedBy: usage.usedBy, usedByThisSite: usage.usedByThisSite };
}

function optionalCreateFields({ body }: { body: Record<string, unknown> }, _optional = {}) {
  return {
    ...(body.additionalHosts !== undefined ? { additionalHosts: body.additionalHosts } : {}),
    ...(body.worksFor !== undefined ? { worksFor: body.worksFor } : {}),
    // "site" = only for this site; omitted = the project store when one is attached (store.ts).
    ...(body.scope !== undefined ? { scope: body.scope } : {}),
  };
}

export function registerAdminCustomCredentialsRoutes(app: Express, deps: AdminCustomCredentialsDeps): void {
  const readDeps = { repo: deps.customCredentialSetRepo, sealer: deps.siteAssistantSecretSealer };
  const writeDeps = {
    repo: deps.customCredentialSetRepo,
    sealer: deps.siteAssistantSecretSealer,
    keyring: deps.siteAssistantSecretKeyring,
    clock: deps.clock,
    idGen: deps.idGen,
  };

  /** Shared workspace-path-param + `custom-credentials.write` authorization check every verb below
   *  performs first — mirrors `source-control-credentials.ts`'s own `rejectUnlessAuthorized`.
   *  Returns `true` and has already written the response iff the caller should stop. */
  async function rejectUnlessAuthorized(req: Request, res: Response): Promise<boolean> {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return true;
    }
    const principal = getAuthedPrincipal(res);
    const authResult = await deps.authorize({
      principalId: principal.id,
      permission: PERMISSION,
      workspaceId: deps.workspaceId,
      entityType: ENTITY_TYPE,
    });
    if (!authResult.allowed) {
      res.status(403).json({
        error: `principal '${principal.id}' is not authorized for '${PERMISSION}' (${authResult.reason})`,
        code: "FORBIDDEN",
        details: { permission: PERMISSION, reason: authResult.reason },
      });
      return true;
    }
    return false;
  }

  app.get(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    if (deps.projectKeys) {
      if (!rejectUnlessSessionCredential(res, { message: "Use the owner's session to view Shared Keys.", permission: PERMISSION })) return;
      if (getAuthedPrincipal(res).id !== await deps.ownerPrincipalId) { res.status(403).json({ error: "Sign in as the installation owner to view Shared Keys." }); return; }
    }
    try {
      const [inventory, keys] = await Promise.all([
        listCustomCredentialInventory({ deps: readDeps, workspaceId: deps.workspaceId }),
        deps.projectKeys?.list({}) ?? Promise.resolve([]),
      ]);
      const usage = new Map(keys.map(key => [key.keyId, key]));
      const credentials = inventory.map(credential => {
        if (credential.scope !== "project") return credential;
        const key = usage.get(credential.id);
        return { ...credential, usedBy: key?.usedBy ?? [], usedByThisSite: key?.usedByThisSite ?? false };
      });
      res.status(200).json({ credentials, ...(deps.projectKeys ? { projectKeysAvailable: true } : {}) });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.post(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const registry = deps.loadDeployTargets && deps.publishCredentialVerificationCache ? await deps.loadDeployTargets(deps.workspaceId) : undefined;
      const credential = await createCustomCredential(writeDeps, {
        workspaceId: deps.workspaceId,
        label: body.label,
        category: body.category,
        baseUrl: body.baseUrl,
        connection: body.connection,
        ...optionalCreateFields({ body }),
      });
      if (registry && deps.publishCredentialVerificationCache) invalidatePublishCredentialCompatibility({ workspaceId: deps.workspaceId, registry, cache: deps.publishCredentialVerificationCache, after: credential });
      res.status(201).json({ credential: await attachAddedProjectKey({ credential, keys: deps.projectKeys }) });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.put(`${BASE_PATH}/:id`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const registry = deps.loadDeployTargets && deps.publishCredentialVerificationCache ? await deps.loadDeployTargets(deps.workspaceId) : undefined;
      const before = await describeCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      const ownerSession = res.locals.authCredentialKind === "session" && getAuthedPrincipal(res).id === await deps.ownerPrincipalId;
      const credential = await updateCustomCredential({ ...writeDeps, allowSharedKeyReplacement: ownerSession }, buildUpdateCredentialInput(deps.workspaceId, req.params.id, body));
      if (before && body.worksFor !== undefined && registry && deps.publishCredentialVerificationCache) invalidatePublishCredentialCompatibility({ workspaceId: deps.workspaceId, registry, cache: deps.publishCredentialVerificationCache, before, after: credential });
      res.status(200).json({ credential });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.delete(`${BASE_PATH}/:id`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      // Idempotent — `deleteCustomCredential`/`CustomCredentialSetRepoPort.delete` are both no-ops
      // (not errors) for a missing row, matching this route's own documented 204-always contract.
      const registry = deps.loadDeployTargets && deps.publishCredentialVerificationCache ? await deps.loadDeployTargets(deps.workspaceId) : undefined;
      const before = await describeCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      await deleteCustomCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      if (before && registry && deps.publishCredentialVerificationCache) invalidatePublishCredentialCompatibility({ workspaceId: deps.workspaceId, registry, cache: deps.publishCredentialVerificationCache, before });
      res.status(204).end();
    } catch (err) {
      sendStoreError(res, err);
    }
  });
}

import { startupSecretEnvironment } from '#src/server/runtime/boot/startup-secrets';
import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { homedir } from "node:os";
import { siteKeySources } from "#src/features/webhooks/index";
import type { Express } from "express";

import { resolveRuntimeMode } from "#src/contracts/core/runtime-mode";
import { DEFAULT_OWNER_PASSWORD } from "#src/features/identity/wiring";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { isAssistantDaemonKnownFailed } from "#src/server/runtime/lifecycle/readiness-state";
import { inspectSiteKeyMaterial, type SiteKeyStatus } from "#src/features/webhooks/index";
import { resolveSiteKeySources } from "./site-key.js";
import type { RouteDeps, SiteStoragePaths } from "#src/server/routes/types";

/**
 * @file Admin Deployment panel → Overview tab backend.
 *
 * Registers `GET /api/admin/v1/workspaces/:workspaceId/system/deployment-overview` — a read-only
 * snapshot of how THIS instance is currently running, for the self-hosted-developer audience the
 * Deployment panel now targets. Every field here is a direct read of a value this process already
 * computed at boot or can compute for free; nothing is measured, inferred, or fabricated.
 *
 * Mirrors `module-status.ts`'s shape exactly (workspace-id 404 check → `system.read` authorize →
 * 403-on-denial), reusing the same permission — this is one more system-status read, not a new kind
 * of capability. `entityType: "deployment-status"` follows `recent-hits.ts`'s precedent of a
 * route-specific descriptive string rather than a shared literal across unrelated resources.
 *
 * ## Site-key plan §A3b — site-aware site-key row
 *
 * The `TOVU_SITE_KEY` row resolves THIS site's own ordered source list
 * ({@link resolveSiteKeySources}, `site-key.ts`) instead of `inspectSiteKeyMaterial()`'s
 * module-level env-then-legacy-default precedence — the same seam the site key tab's own
 * `GET`/`reveal`/`generate` verbs already use, so a site with a resolvable per-site key file
 * (`~/.tovu/site-keys/<siteKeyId>.hex`) reports it as active here too, not only on that tab. A site
 * with no readable `.site-meta.json` (or production, which has no per-site file at all) falls back
 * to exactly today's behavior.
 */
export type AdminDeploymentOverviewDeps = Pick<
  RouteDeps,
  "workspaceId" | "authorize" | "identityReady" | "ownerPrincipalId" | "userRepo" | "passwordHasher" | "siteBinding" | "siteStoragePaths"
>;

/** One required-for-production env var's presence, never its value. */
export interface DeploymentEnvVarStatus {
  name: string;
  set: boolean;
  /** site key row only: where the keyring's material came from. `set` there means "usable site key",
   *  so a valid generated key file counts, and malformed env/file material does not. */
  source?: SiteKeyStatus["source"];
  /** site key row only, present iff material was found but the keyring would reject it. */
  invalid?: true;
}

export interface DeploymentOverviewSnapshot {
  /** `resolveRuntimeMode()`'s own two-value type — deliberately not "development": Tovu's actual
   *  runtime-mode signal is `"production" | "local"` (`core/runtime-mode.ts`), and echoing that
   *  exact vocabulary here is more honest than translating it to a pair the UI never really has. */
  mode: "production" | "local";
  /**
   * The boot-time production readiness gate (`production-readiness-gate.ts`) is "entirely inert
   * outside production mode" by its own doc comment, and in production mode a failing gate exits
   * the process before it ever starts listening (`index.ts`'s `runBootGateOrExit`) — so a request
   * reaching this route in production mode is itself proof the gate passed. `applicable: false`
   * in local mode is the honest "this check does not run here" state, not a hidden pass.
   */
  productionReadinessGate: { applicable: boolean; passed: boolean };
  /**
   * Whether the seeded owner account is still on the publicly-documented default password — read
   * from the owner's STORED hash ({@link isOwnerOnDefaultPassword}), not from `TOVU_ADMIN_PASSWORD`.
   * Computed unconditionally (not gated on production mode) since it is a real, useful warning in
   * local mode too.
   */
  defaultOwnerPasswordUnsafe: boolean;
  /**
   * Whether the locally-spawned agent daemon is KNOWN to have failed (`readiness-state.ts`). This
   * is a negative signal only — "not known-failed" can also mean "never spawned" (e.g. pure BYOK
   * setups never start it), so the UI must not read `!daemonKnownFailed` as "confirmed alive".
   */
  daemonKnownFailed: boolean;
  /** `RouteDeps.siteStoragePaths.contentDbPath` — the path this process's composition root opened. */
  dbPath: string;
  /** `RouteDeps.siteStoragePaths.mediaUploadsDir` — the same path the blob store writes under. */
  uploadsDir: string;
  /** Presence only, per required env var — never a value. */
  envVars: DeploymentEnvVarStatus[];
}

/** The four env vars the brief calls out — order here is display order. */
const REQUIRED_ENV_VAR_NAMES = [
  "TOVU_ADMIN_PASSWORD",
  "TOVU_ADMIN_USER",
  "TOVU_SITE_KEY",
  "JINI_AGENT_DAEMON_PORT",
] as const;

/** The site key row, from what `EnvOrFileKeyring` would actually resolve — the env var OR a generated
 *  key file, validated — rather than the env var's bare presence. @complexity O(1). */
function siteKeyEnvVarStatus(siteKey: SiteKeyStatus): DeploymentEnvVarStatus {
  return {
    name: "TOVU_SITE_KEY",
    set: siteKey.active,
    source: siteKey.source,
    ...(siteKey.invalid ? { invalid: true as const } : {}),
  };
}

function envVarStatus(name: (typeof REQUIRED_ENV_VAR_NAMES)[number], siteKey: SiteKeyStatus): DeploymentEnvVarStatus {
  return name === "TOVU_SITE_KEY" ? siteKeyEnvVarStatus(siteKey) : { name, set: Boolean(startupSecretEnvironment({ env: process.env })[name]) };
}

/**
 * Builds the snapshot from live process state. Exported separately from the route registrar so a
 * test can call it directly without spinning up Express.
 *
 * @param input.defaultOwnerPasswordUnsafe the one field that needs the database, resolved by the
 *   caller ({@link isOwnerOnDefaultPassword}) so this stays synchronous.
 * @param input.siteKey test seam; defaults to a live {@link inspectSiteKeyMaterial} read.
 * @param input.storagePaths the booted site's paths (`RouteDeps.siteStoragePaths`). Injected, never
 *   re-derived here: this used to call `defaultContentDbPath()`/`mediaUploadsDir()`, which read
 *   `TOVU_CONTENT_DB`/`siteDir()` — the env/cwd site, not necessarily the one this process serves
 *   once several local sites run side by side (hardwiring audit #19).
 * @complexity O(1) — fixed-size env var list, no iteration over caller-controlled data.
 */
export function buildDeploymentOverviewSnapshot(input: {
  defaultOwnerPasswordUnsafe: boolean;
  storagePaths: Pick<SiteStoragePaths, "contentDbPath" | "mediaUploadsDir">;
  siteKey?: SiteKeyStatus;
}): DeploymentOverviewSnapshot {
  const mode = resolveRuntimeMode();
  const siteKey = input.siteKey ?? inspectSiteKeyMaterial({ sources: siteKeySources({ mode, env: process.env, home: homedir(), cwd: process.cwd() }) });
  return {
    mode,
    productionReadinessGate: { applicable: mode === "production", passed: mode === "production" },
    defaultOwnerPasswordUnsafe: input.defaultOwnerPasswordUnsafe,
    daemonKnownFailed: isAssistantDaemonKnownFailed(),
    dbPath: input.storagePaths.contentDbPath,
    uploadsDir: input.storagePaths.mediaUploadsDir,
    envVars: REQUIRED_ENV_VAR_NAMES.map((name) => envVarStatus(name, siteKey)),
  };
}

/**
 * Whether the seeded owner's stored password still verifies against `DEFAULT_OWNER_PASSWORD`.
 *
 * Read from the database because `TOVU_ADMIN_PASSWORD` only says what a FIRST boot would seed:
 * seeding never rotates an existing owner, so the env var and the stored credential drift apart the
 * moment either changes. Both directions were wrong in practice — the desktop app now passes a
 * random `TOVU_ADMIN_PASSWORD` into every spawn (LAN-bind plan, 2026-09-23), so a site it created
 * before that fix, still on the default, read as "changed"; and an owner who changed their password
 * in the admin UI with the env var unset read as "still the default" forever.
 *
 * @returns `false` when there is no owner user row to check (nothing can sign in with the default).
 * @complexity O(1) — one user lookup and one argon2id verify (tens of ms, by design of the hash).
 */
async function isOwnerOnDefaultPassword(deps: AdminDeploymentOverviewDeps): Promise<boolean> {
  await deps.identityReady;
  const principalId = await deps.ownerPrincipalId;
  const owner = await deps.userRepo.findByPrincipalId({ workspaceId: deps.workspaceId, principalId });
  if (!owner) return false;
  return deps.passwordHasher.verify({ hash: owner.passwordHash, password: DEFAULT_OWNER_PASSWORD });
}

export function registerAdminDeploymentOverviewRoute(app: Express, deps: AdminDeploymentOverviewDeps): void {
  app.get("/api/admin/v1/workspaces/:workspaceId/system/deployment-overview", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: "deployment-status",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.read", reason: authResult.reason },
        });
        return;
      }

      // Site-key plan §A3b: resolve THIS site's own source order (the same
      // `resolveSiteKeySources` seam `site-key.ts`'s GET/reveal/generate verbs use) rather than
      // `buildDeploymentOverviewSnapshot`'s bare-default `inspectSiteKeyMaterial()`, so a site with a
      // resolvable per-site key file reports it here too, not just on the site key tab.
      const { sources } = resolveSiteKeySources(deps);
      res.status(200).json(
        buildDeploymentOverviewSnapshot({
          defaultOwnerPasswordUnsafe: await isOwnerOnDefaultPassword(deps),
          storagePaths: deps.siteStoragePaths,
          siteKey: inspectSiteKeyMaterial({ sources }),
        })
      );
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/deployment-overview", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import {
  readDockerfileSource,
  writeDockerfileSourceWithIfMatch,
  type DockerfileSourceSnapshot,
} from "#src/features/deployments/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

export type { DockerfileSourceSnapshot };
// Re-exported for callers/tests that import the read function from this route file's previous
// public surface — the implementation itself now lives in `features/deployments/dockerfile.ts` (see
// this file's header for why), and this route is one of that function's two callers.
export { readDockerfileSource };

/**
 * @file Admin Deployment panel → Dockerfile tab backend.
 *
 * Registers `GET`/`PUT /api/admin/v1/workspaces/:workspaceId/system/dockerfile` — reads and writes
 * the repo-root `Dockerfile`'s contents.
 *
 * 2026-08-15: this tab is now editable, not read-only — both a human in the admin and the
 * `deployment_get_dockerfile`/`deployment_set_dockerfile` agent tools (`features/deployments/
 * tool-registrations.ts`) can read and write the same file. The actual `fs` read/write moved to
 * `features/deployments/dockerfile.ts` so both callers share one path-resolution rule instead of
 * each hardcoding `join(process.cwd(), "Dockerfile")` independently — see that file's header for the
 * full path-safety argument (short version: neither function accepts a path argument at all, so
 * there is no path input to sanitize in the first place). `PUT` is `system.write`-gated, distinct
 * from `GET`'s `system.read` — writing a build file is not a read, mirroring
 * `export-site.ts`'s `system.export` vs `system.read` split for the identical reason (a mutation
 * needs its own permission string, never folded into a `*.read` grant).
 *
 * Writing the Dockerfile does not build, validate, or deploy anything — this route only replaces
 * the file's bytes on disk. Nothing here shells out to `docker build`, and the response never
 * implies otherwise.
 *
 * ## 2026-08-15 — `If-Match`/`ETag` optimistic concurrency (Terra audit finding C5)
 *
 * `GET` sets a real `ETag` response header (`dockerfile.ts`'s `DockerfileSourceSnapshot.etag`) on
 * every response, including the "does not exist" case. `PUT` now REQUIRES a matching `If-Match`
 * request header — see {@link writeDockerfileSourceWithIfMatch}'s own doc for the full decision
 * record (strict, not permissive) and the residual race window it honestly does not close. A `PUT`
 * with no `If-Match` at all is `400`, not treated as an unconditional write; a `PUT` whose `If-Match`
 * no longer names the file's current contents is `412 Precondition Failed`, with the CURRENT
 * `{exists, contents}` in the body so the caller can diff and reconcile instead of retrying blind.
 * The JSON response body deliberately stays `{exists, contents}` on every status — the etag travels
 * ONLY via the `ETag`/`If-Match` headers, not duplicated into the body, so there is exactly one wire
 * representation of "what etag is this" rather than two that could drift.
 */
export type AdminDockerfileSourceDeps = Pick<RouteDeps, "workspaceId" | "authorize">;

/** Validates the write request's JSON body. Never throws — every malformed shape maps to a
 *  `{ error }` result the route turns into a `400`, mirroring `export-site.ts`'s
 *  `parseTriggerRequestBody`. `contents` is the ONLY field this route reads from the BODY — there is
 *  no path field to validate because {@link writeDockerfileSourceWithIfMatch} accepts none, and the
 *  write's other required input, `If-Match`, is a HEADER (checked separately below, before this
 *  parser ever runs) rather than a body field. */
function parseWriteRequestBody(body: unknown): { ok: true; contents: string } | { ok: false; error: string } {
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    return { ok: false, error: "request body must be a JSON object" };
  }
  const raw = body as Record<string, unknown>;
  if (typeof raw.contents !== "string") {
    return { ok: false, error: "'contents' (string) is required" };
  }
  return { ok: true, contents: raw.contents };
}

/** The wire body both `GET` and a successful `PUT` return — deliberately just `{exists, contents}`,
 *  never the domain snapshot's `etag` field; see this file's header for why the etag travels only
 *  via the `ETag` header. */
function toResponseBody(snapshot: DockerfileSourceSnapshot): { exists: boolean; contents: string | null } {
  return { exists: snapshot.exists, contents: snapshot.contents };
}

export function registerAdminDockerfileSourceRoute(app: Express, deps: AdminDockerfileSourceDeps): void {
  app.get("/api/admin/v1/workspaces/:workspaceId/system/dockerfile", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: "dockerfile-source",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.read", reason: authResult.reason },
        });
        return;
      }

      const snapshot = readDockerfileSource();
      res.setHeader("ETag", snapshot.etag);
      res.status(200).json(toResponseBody(snapshot));
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/dockerfile-source", code: "INTERNAL_ERROR" });
    }
  });

  app.put("/api/admin/v1/workspaces/:workspaceId/system/dockerfile", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.write",
        workspaceId: deps.workspaceId,
        entityType: "dockerfile-source",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.write' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.write", reason: authResult.reason },
        });
        return;
      }

      // Precondition check BEFORE body parsing — an `If-Match` header is a precondition on the
      // REQUEST, distinct from whether the BODY it guards happens to be well-formed. Checking it
      // first means a missing-header failure is never masked by (or mistaken for) a body-shape
      // failure — see this file's header for the strict-vs-permissive decision this header enforces.
      const ifMatch = req.get("If-Match");
      if (!ifMatch) {
        res.status(400).json({
          error:
            "the 'If-Match' header is required on PUT — GET this same URL first (its response carries an 'ETag' header with the file's current value), then send that value back as 'If-Match' to prove your write is based on the current contents, not a stale copy. This is deliberate (Terra audit finding C5, 2026-08-15): an unconditional write here would let a human editing this tab and the AI assistant's deployment_set_dockerfile tool silently overwrite each other with no warning to either.",
        });
        return;
      }

      const parsedBody = parseWriteRequestBody(req.body);
      if (!parsedBody.ok) {
        res.status(400).json({ error: parsedBody.error });
        return;
      }

      const result = writeDockerfileSourceWithIfMatch(parsedBody.contents, ifMatch);
      if (!result.ok) {
        res.setHeader("ETag", result.current.etag);
        res.status(412).json({
          error:
            "the Dockerfile changed on the server since your 'If-Match' value was read — someone else (or the AI assistant) saved a different version in between. The response body's 'current' field is what's actually on disk right now; reconcile your intended change against it and retry with the 'ETag' header on THIS response.",
          code: "DOCKERFILE_CONFLICT",
          current: toResponseBody(result.current),
        });
        return;
      }

      res.setHeader("ETag", result.snapshot.etag);
      res.status(200).json(toResponseBody(result.snapshot));
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/dockerfile-source", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import {
  getExportRunSnapshot,
  startExportRun,
  type ExportRunCounts,
  type ExportRunSnapshot,
  type ExportRunStatus,
} from "#src/features/deployments/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

export type { ExportRunCounts, ExportRunSnapshot, ExportRunStatus };

/**
 * @file Admin Deployment panel → Static Site tab backend.
 *
 * Registers TWO routes wrapping `src/features/site-export/site-exporter.ts`'s `exportSite` — the same engine
 * `tovu export` already drives, in-process, never shelled out to (a route running inside this same
 * process can call it directly; `exportSite` boots its OWN short-lived HTTP listener on port 0 to
 * fetch every route, so there is no self-request deadlock).
 *
 * TRIGGER + STATUS, not a synchronous request/response: a real export is
 * "seconds to minutes" (this feature's own build-session findings doc) — one HTTP request per
 * route/asset, serially, by design (`site-exporter.ts`'s own complexity note: fidelity over
 * throughput). Holding a single HTTP connection open for that whole span is the wrong shape for a
 * single-container product with no separate worker process to hand it to, and a hard client-side
 * timeout would just turn an in-progress export into an orphaned background write with no way to
 * learn its outcome. So `POST .../system/export` starts the run and returns `202` immediately with
 * a snapshot; `GET .../system/export` polls the same snapshot. A single process-local mutable slot
 * (mirrors `readiness-state.ts`'s exact "process-local holder" shape) rather than a job table: this
 * composition root serves exactly one workspace per process (`RouteDeps.workspaceId` is a single
 * value, not a repo — every route in this codebase already assumes that), so "one export at a
 * time" is the correct concurrency model, not an arbitrary limitation. A second trigger while one
 * is running gets `409`, never a silently queued or silently dropped request.
 *
 * `system.export`-gated for the trigger, distinct from the `system.read` the status poll and every
 * other route in this directory use — triggering writes a folder of files to disk, which is not a
 * read, the same reasoning that gives `database.migrate`/`backup.restore`/`theme.set` their own
 * write-class permission strings instead of reusing a `*.read` grant.
 *
 * `--out`/`--workspace` are NOT client-controllable fields on the request body: `startExportRun`
 * (`export-run.ts`) reads `RouteDeps.exportOutputRootDir` — the same `TOVU_EXPORT_DIR`
 * env-then-default value `cli/commands/export.ts`'s `resolveExportOutputDir` falls back to when its
 * own CLI-only `--out` flag is absent, both ultimately resolved once by the composition root
 * (`server/deps.ts`'s `resolveExportOutputRootDir`) — rather than accepting a caller-supplied path —
 * the brief's own instruction ("do not invent a new location") doubles as a path-injection guard:
 * nothing here ever builds a filesystem path out of request input.
 *
 * 2026-08-15: the process-local run state and the actual `exportSite` call moved out to
 * `features/deployments/export-run.ts` — this file now only translates HTTP
 * request/response shape around `startExportRun`/`getExportRunSnapshot`. The move exists so the new
 * `deployment_trigger_export`/`deployment_get_export_status` agent tools (`features/deployments/
 * tool-registrations.ts`) can trigger and poll the SAME run this route does — the assistant's own
 * `tool-registrations.ts` files may never import from `src/server/**` (see that file's header for
 * the full reasoning and the one disclosed gap: the standalone agent daemon process does not share
 * this process's in-memory run state).
 */
export type AdminExportSiteDeps = RouteDeps;

/** `'clean' must be a boolean` when present and not a boolean; `null` when the field is absent,
 *  `undefined`, or already a boolean. */
function validateCleanField(raw: Record<string, unknown>): string | null {
  if ("clean" in raw && raw.clean !== undefined && typeof raw.clean !== "boolean") {
    return "'clean' must be a boolean";
  }
  return null;
}

/** `'basePath' must be a string` when present and not a string; `null` when the field is absent,
 *  `undefined`, or already a string. */
function validateBasePathField(raw: Record<string, unknown>): string | null {
  if ("basePath" in raw && raw.basePath !== undefined && typeof raw.basePath !== "string") {
    return "'basePath' must be a string";
  }
  return null;
}

/** A non-blank string `basePath`, or `undefined` — blank/absent/non-string all collapse to
 *  "omit the field" so `parseTriggerRequestBody`'s spread never adds a useless empty value. */
function normalizeBasePath(raw: Record<string, unknown>): string | undefined {
  return typeof raw.basePath === "string" && raw.basePath.trim() !== "" ? raw.basePath : undefined;
}

/** Validates the trigger request's optional JSON body. Never throws — every malformed shape maps
 *  to a `{ error }` result the route turns into a `400`, per secure-input-handling discipline for
 *  a request body this route hands straight into a filesystem-writing operation's options. */
function parseTriggerRequestBody(body: unknown): { ok: true; clean: boolean; basePath?: string } | { ok: false; error: string } {
  if (body === undefined || body === null) return { ok: true, clean: false };
  if (typeof body !== "object" || Array.isArray(body)) return { ok: false, error: "request body must be a JSON object" };

  const raw = body as Record<string, unknown>;
  const cleanError = validateCleanField(raw);
  if (cleanError) return { ok: false, error: cleanError };
  const basePathError = validateBasePathField(raw);
  if (basePathError) return { ok: false, error: basePathError };

  const basePath = normalizeBasePath(raw);
  return { ok: true, clean: raw.clean === true, ...(basePath !== undefined ? { basePath } : {}) };
}

export function registerAdminExportSiteRoutes(app: Express, deps: AdminExportSiteDeps): void {
  app.post("/api/admin/v1/workspaces/:workspaceId/system/export", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.export",
        workspaceId: deps.workspaceId,
        entityType: "site-export",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.export' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.export", reason: authResult.reason },
        });
        return;
      }

      // No `await` between this check and `startExportRun` below — this whole block runs as one
      // synchronous stretch of the event loop, so two concurrent POSTs cannot both observe "idle".
      // `deployment_trigger_export` (`features/deployments/tool-registrations.ts`) follows the
      // identical no-await-in-between shape against the same `getExportRunSnapshot`/`startExportRun`
      // pair, sharing this exact single-flight guarantee whenever it runs in this same process (see
      // `export-run.ts`'s file header for the one case where it does not: a separate OS process).
      if (getExportRunSnapshot().status === "running") {
        res.status(409).json({ error: "an export is already running", run: getExportRunSnapshot() });
        return;
      }

      const parsedBody = parseTriggerRequestBody(req.body);
      if (!parsedBody.ok) {
        res.status(400).json({ error: parsedBody.error });
        return;
      }

      const snapshot = startExportRun({ routeDeps: deps, runExportSite: deps.runExportSite, clean: parsedBody.clean }, { basePath: parsedBody.basePath,
        productEvent: { tracker: deps.tracker, userId: principal.id, operationId: deps.idGen.newId(), source: "admin" } });
      res.status(202).json(snapshot);
    } catch (err) {
      // `startExportRun` itself is not awaited (the run continues in the background, polled via
      // `GET` below), so a failure inside the run it starts can never reach this catch — only a
      // failure BEFORE that point can, e.g. `deps.authorize` itself throwing.

      sendAdminFailure({ res, error: err }, { operation: "routes/system/export-site", code: "INTERNAL_ERROR" });
    }
  });

  app.get("/api/admin/v1/workspaces/:workspaceId/system/export", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: "site-export",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.read", reason: authResult.reason },
        });
        return;
      }

      res.status(200).json(getExportRunSnapshot());
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/export-site", code: "INTERNAL_ERROR" });
    }
  });
}

