import type { Express, Request, Response } from "express";
import { ToolInputError } from "@jini-ai/core";

import { getMailActivity, listMailActivity, MailActivityForbiddenError, MailActivityUnavailableError, readMailActivityId, readMailActivityQuery } from "#src/features/mail-status/activity";
import type { MailDeliveryToolDeps } from "#src/features/mail-status/delivery-tool-registrations";
import { readMailFeedbackSetup } from "#src/features/mail-status/feedback-setup";
import { MAIL_STATUS_PERMISSION } from "#src/features/mail-status/permissions";
import {
  listMailSuppressions, MailSuppressionsUnavailableError, planMailSuppressionRemoval, readMailSuppressionQuery, readMailSuppressionRemoval, runMailSuppressionRemoval,
} from "#src/features/mail-status/suppressions";
import { mailUseReadinessDepsFrom, readMailUseReadiness } from "#src/features/mail-status/use-readiness";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

/**
 * @file The Email page's **What uses email** and **Recent sends and failures** (email phase 4):
 * thin adapters over the operations `mail_get_readiness`, `mail_list_activity` and
 * `mail_get_activity` run (`features/mail-status/{use-readiness,activity}.ts`).
 *
 * - `GET  .../system/mail-uses` (admin.forms.manage) -> `{ checkedAt, uses: MailUseRow[] }`.
 * - `GET  .../system/mail-activity?outcome=&use=&recipient=&limit=&cursor=` (mail.activity.read
 *   for full recipients; admin.forms.manage alone gets masked rows) -> `MailActivityPage`.
 * - `GET  .../system/mail-activity/:activityId` (mail.activity.read) -> `MailActivityDetail`, 404
 *   when no such send exists here.
 *
 *
 * Phase 5 (same file, same envelopes; operations in `features/mail-status/{suppressions,feedback-setup}.ts`):
 *
 * - `GET  .../system/mail-suppressions?search=&scope=&reason=&limit=&cursor=` (mail.activity.read)
 *   -> `{ items: [{ address, scope, reason, createdAt }], nextCursor, empty }`.
 * - `POST .../system/mail-suppressions/remove` (mail.suppressions.manage) body
 *   `{ address, scope: "all"|"bulk", reason, confirmed?: true }`. Without `confirmed: true` it only
 *   previews: `{ removed: false, confirmationRequired: true, plan }` (what was blocked, why, and
 *   the warnings). With it: `{ removed, removal? }`, the reason recorded in the removal audit. Every
 *   removal is a fresh confirmation; nothing about it is remembered.
 * - `GET  .../system/mail-feedback` (admin.forms.manage) -> `MailFeedbackSetupReport`.
 *
 * 400 for malformed input, 403 without the permission, 503 when this root has no activity or
 * suppression repo.
 */
export type AdminMailActivityDeps = MailDeliveryToolDeps;

const BASE = "/api/admin/v1/workspaces/:workspaceId/system";

function forbidden(res: Response, permission: string, reason: string): void {
  res.status(403).json({ error: `not authorized for '${permission}' (${reason})`, code: "FORBIDDEN", details: { permission, reason } });
}

/** The Email page's status permission (uses, feedback setup); answers the 403 itself. */
async function statusAllowed({ deps, principalId, res }: { deps: AdminMailActivityDeps; principalId: string; res: Response }, _optional: Record<string, never> = {}): Promise<boolean> {
  const auth = await deps.authorize({ principalId, permission: MAIL_STATUS_PERMISSION, workspaceId: deps.workspaceId, entityType: "mail" });
  if (!auth.allowed) forbidden(res, MAIL_STATUS_PERMISSION, auth.reason);
  return auth.allowed;
}

/** One error ladder for every route here; anything unexpected is a 500 without its text. */
function fail(res: Response, err: unknown): void {
  if (err instanceof ToolInputError) {
    res.status(400).json({ error: err.message, code: "INVALID_INPUT" });
  } else if (err instanceof MailActivityForbiddenError) {
    forbidden(res, err.permission, "no_grant");
  } else if (err instanceof MailActivityUnavailableError || err instanceof MailSuppressionsUnavailableError) {
    res.status(503).json({ error: err.message, code: "MAIL_ACTIVITY_UNAVAILABLE" });
  } else {

    sendAdminFailure({ res, error: err }, { operation: "routes/system/mail-activity", code: "INTERNAL_ERROR" });
  }
}

function handle({ deps, run }: { deps: AdminMailActivityDeps; run: (req: Request, res: Response, principalId: string) => Promise<void> }, _optional: Record<string, never> = {}) {
  return async (req: Request, res: Response) => {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      await run(req, res, getAuthedPrincipal(res).id);
    } catch (err) {
      fail(res, err);
    }
  };
}

/**
 * Register the readiness and activity routes.
 * @complexity One readiness pass or one activity read per request.
 * @example registerAdminMailActivityRoutes(app, routeDeps)
 */
export function registerAdminMailActivityRoutes(app: Express, deps: AdminMailActivityDeps): void {
  app.get(`${BASE}/mail-uses`, handle({ deps, run: async (_req, res, principalId) => {
    if (await statusAllowed({ deps, principalId, res })) res.json(await readMailUseReadiness(mailUseReadinessDepsFrom(deps)));
  } }));
  app.get(`${BASE}/mail-activity`, handle({ deps, run: async (req, res, principalId) => {
    const query = readMailActivityQuery({ input: req.query as Record<string, unknown> });
    res.json(await listMailActivity({ ...{ principalId, query }, deps: deps }));
  } }));
  app.get(`${BASE}/mail-activity/:activityId`, handle({ deps, run: async (req, res, principalId) => {
    const found = await getMailActivity({ ...{ principalId, activityId: readMailActivityId({ value: req.params.activityId }) }, deps: deps });
    if (found) res.json(found);
    else res.status(404).json({ error: "no such email send", code: "NOT_FOUND" });
  } }));
  app.get(`${BASE}/mail-suppressions`, handle({ deps, run: async (req, res, principalId) => {
    res.json(await listMailSuppressions({ ...{ principalId, query: readMailSuppressionQuery({ input: req.query as Record<string, unknown> }) }, deps: deps }));
  } }));
  app.post(`${BASE}/mail-suppressions/remove`, handle({ deps, run: async (req, res, principalId) => {
    const body = (req.body && typeof req.body === "object" && !Array.isArray(req.body) ? req.body : {}) as Record<string, unknown>;
    const plan = await planMailSuppressionRemoval({ ...{ principalId, input: readMailSuppressionRemoval({ input: body }) }, deps: deps });
    if (body.confirmed !== true) {
      res.json({ removed: false, confirmationRequired: true, plan });
      return;
    }
    if (body.revision !== plan.revision) throw new ToolInputError({ message: "Suppression changed or no reviewed revision was supplied. Review and confirm the current suppression." });
    res.json(await runMailSuppressionRemoval({ ...{ principalId, plan }, deps: deps }));
  } }));
  app.get(`${BASE}/mail-feedback`, handle({ deps, run: async (_req, res, principalId) => {
    if (await statusAllowed({ deps, principalId, res })) res.json(await readMailFeedbackSetup(deps));
  } }));
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";

import { mailDnsPorts, readMailDnsStatus, verifyMailDnsStatus, type DnsChangeToolDeps, type MailDnsStatus } from "#src/features/domain-dns/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";

/**
 * @file The Email page's **Sender and DNS** section, over the same operations as `mail_dns_status`
 * and `mail_dns_verify` (`features/domain-dns/mail-dns-status.ts`):
 * - `GET  /api/admin/v1/workspaces/:workspaceId/system/mail-dns` (`deployments.read`): provider
 *   verdict, copyable rows and one unsaved record-by-record check.
 * - `POST /api/admin/v1/workspaces/:workspaceId/system/mail-dns/verify` (`deployments.publish`):
 *   **Check again**, saved as the sender domain's tracking state.
 * Both answer 200 with a `MailDnsStatus` whose `state` names why a table is absent (no sender,
 * no provider, verification unavailable for this provider, ...); only an unexpected fault is a 500.
 * Neither changes DNS.
 */
export interface AdminMailDnsDeps {
  workspaceId: string;
  /** The DNS change deps the `dns_*` tools use, built for this workspace by the composition root. */
  dns: DnsChangeToolDeps;
}

type Operation = (required: Record<string, never>, ports: ReturnType<typeof mailDnsPorts>) => Promise<MailDnsStatus>;

/** One authorized call of `operation`, with the mail-status route's 404/403/500 shapes. */
function handler(deps: AdminMailDnsDeps, permission: string, operation: Operation) {
  return async (req: Request, res: Response): Promise<void> => {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      const auth = await deps.dns.authorize({ principalId: principal.id, permission, workspaceId: deps.workspaceId, entityType: "domain-dns" });
      if (!auth.allowed) {
        res.status(403).json({ error: `principal '${principal.id}' is not authorized for '${permission}' (${auth.reason})`, code: "FORBIDDEN", details: { permission, reason: auth.reason } });
        return;
      }
      res.status(200).json(await operation({}, mailDnsPorts(deps.dns)));
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/mail-dns", code: "INTERNAL_ERROR" });
    }
  };
}

/**
 * Register the two mail DNS routes.
 * @complexity O(1) registration; each request is one operation run.
 * @example registerAdminMailDnsRoutes(app, { workspaceId, dns })
 */
export function registerAdminMailDnsRoutes(app: Express, deps: AdminMailDnsDeps): void {
  app.get("/api/admin/v1/workspaces/:workspaceId/system/mail-dns", handler(deps, "deployments.read", readMailDnsStatus));
  app.post("/api/admin/v1/workspaces/:workspaceId/system/mail-dns/verify", handler(deps, "deployments.publish", verifyMailDnsStatus));
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";

import {
  CustomCredentialDuplicateLabelError,
  CustomCredentialNotFoundError,
  CustomCredentialSecretStoreUnconfiguredError,
  CustomCredentialValidationError,
} from "#src/features/custom-credentials/index";
import {
  activateMailProvider,
  MailProviderOperationError,
  planMailProviderCredential,
  readMailProviderConfigurations,
  saveMailProviderCredential,
  type MailProviderCredentialInput,
  type MailProviderOperationCode,
} from "#src/features/mail-status/provider-operations";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin mail provider actions beside `./mail-status.ts` (email phase 2, 2026-10-22). Thin
 * HTTP adapters over `features/mail-status/provider-operations.ts`, the same operations the
 * assistant's `mail_list_providers`, `mail_configure_provider` and `mail_set_provider` call:
 *
 * - `GET  …/system/mail-providers` — the safe configuration DTO (`admin.forms.manage`, like status).
 * - `GET  …/system/mail-providers/:providerId/credential` — what saving its key takes (label,
 *   category, default endpoint, create vs rotate). `custom-credentials.write`.
 * - `PUT  …/system/mail-providers/:providerId/credential` — body `{token?, username?, baseUrl?}`:
 *   creates or rotates the key in the custom-credentials store WITHOUT activating the provider; the
 *   next send already uses it. `custom-credentials.write`. Never echoes a secret.
 * - `POST …/system/mail-providers/:providerId/activate` — switches BOTH lanes after re-checking the
 *   provider; the click is the person's explicit confirmation. `settings.workspace.write`.
 */
export type AdminMailProviderDeps = Pick<RouteDeps, "workspaceId" | "authorize" | "clock" | "idGen" | "customCredentialSetRepo" | "siteAssistantSecretSealer" | "siteAssistantSecretKeyring" | "ownerPrincipalId">
  & Partial<Pick<RouteDeps, "mailProviderControl" | "projectKeys">>;

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/system/mail-providers";

const OPERATION_STATUS: Readonly<Record<MailProviderOperationCode, number>> = {
  MAIL_PROVIDER_CONTROL_UNAVAILABLE: 503, MAIL_PROVIDER_NOT_FOUND: 404, MAIL_PROVIDER_KEYLESS: 409, MAIL_PROVIDER_REFUSED: 409, MAIL_PROVIDER_INPUT: 400, MAIL_PROVIDER_CHANGED: 409,
};

/** Store errors keep the custom-credentials route's codes. */
const STORE_ERRORS: readonly [new (...args: never[]) => Error, number, string][] = [
  [CustomCredentialValidationError, 400, "VALIDATION"],
  [CustomCredentialDuplicateLabelError, 409, "DUPLICATE_LABEL"],
  [CustomCredentialNotFoundError, 404, "NOT_FOUND"],
  [CustomCredentialSecretStoreUnconfiguredError, 503, "SECRET_STORE_UNCONFIGURED"],
];

/** Maps a refusal to its status; anything else is a logged 500 without the error's text. */
function sendError(res: Response, err: unknown): void {
  if (err instanceof MailProviderOperationError) {
    res.status(OPERATION_STATUS[err.code]).json({ error: err.message, code: err.code });
    return;
  }
  const known = STORE_ERRORS.find(([type]) => err instanceof type);
  if (known) {
    res.status(known[1]).json({ error: known[2], code: known[2] });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/system/mail-providers", code: "INTERNAL_ERROR" });
}

/** The body's credential parts; any non-string part is refused rather than coerced. */
function readCredentialInput(body: unknown): MailProviderCredentialInput {
  const record = (typeof body === "object" && body !== null && !Array.isArray(body) ? body : {}) as Record<string, unknown>;
  const input: Record<string, string> = {};
  for (const key of ["token", "username", "baseUrl"] as const) {
    if (record[key] === undefined) continue;
    if (typeof record[key] !== "string") throw new MailProviderOperationError({ code: "MAIL_PROVIDER_INPUT", message: `${key} must be a string.` });
    input[key] = record[key] as string;
  }
  return input;
}

export function registerAdminMailProviderRoutes(app: Express, deps: AdminMailProviderDeps): void {
  const credentials = { repo: deps.customCredentialSetRepo, sealer: deps.siteAssistantSecretSealer, keyring: deps.siteAssistantSecretKeyring, clock: deps.clock, idGen: deps.idGen };

  /** Workspace match + per-action permission; writes the response and returns null when the caller must stop. */
  async function authorized(req: Request, res: Response, permission: string): Promise<string | null> {
    if (req.params.workspaceId !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return null;
    }
    const principal = getAuthedPrincipal(res);
    const result = await deps.authorize({ principalId: principal.id, permission, workspaceId: deps.workspaceId, entityType: "mail" });
    if (result.allowed) return principal.id;
    res.status(403).json({ error: `principal '${principal.id}' is not authorized for '${permission}' (${result.reason})`, code: "FORBIDDEN", details: { permission, reason: result.reason } });
    return null;
  }

  /** One route: authorize, run, answer 200 with the result or the mapped refusal. */
  const route = (permission: string, run: (required: { req: Request; res: Response; principalId: string }) => Promise<unknown>) => async (req: Request, res: Response) => {
    try {
      const principalId = await authorized(req, res, permission);
      if (principalId === null) return;
      res.status(200).json(await run({ req, res, principalId }));
    } catch (err) {
      sendError(res, err);
    }
  };
  const providerId = (req: Request): string => String(req.params.providerId);

  app.get(BASE_PATH, route("admin.forms.manage", () => readMailProviderConfigurations({ control: deps.mailProviderControl })));
  app.get(`${BASE_PATH}/:providerId/credential`, route("custom-credentials.write", ({ req }) =>
    planMailProviderCredential({ control: deps.mailProviderControl, providerId: providerId(req) })));
  app.put(`${BASE_PATH}/:providerId/credential`, route("custom-credentials.write", async ({ req, res, principalId }) => {
    // Match the custom-credentials route: only the owner's human session can replace a shared key.
    const ownerSession = res.locals.authCredentialKind === "session" && principalId === await deps.ownerPrincipalId;
    return { provider: await saveMailProviderCredential({ control: deps.mailProviderControl,
      credentials: { ...credentials, allowSharedKeyReplacement: ownerSession }, workspaceId: deps.workspaceId,
      providerId: providerId(req), input: readCredentialInput(req.body) }, { projectKeys: deps.projectKeys }) };
  }));
  app.post(`${BASE_PATH}/:providerId/activate`, route("settings.workspace.write", ({ req, principalId }) =>
    activateMailProvider({ control: deps.mailProviderControl, providerId: providerId(req), principalId })));
}

