/**
 * @file Admin Deployment panel → Static Site tab's credential CRUD backend.
 *
 * Registers `GET`/`POST` on the collection and `PUT`/`DELETE` on a single credential set, all under
 * `/api/admin/v1/workspaces/:workspaceId/system/publish/credentials`. This is deliberately a THIN
 * HTTP adapter over `publish-credentials/store.ts` — every validation, uniqueness, and default-slot
 * rule already lives there (see that file's own header); this route's only job is: check auth, shape
 * the request into `store.ts`'s input types, map its thrown errors to HTTP status codes, and return
 * `PublishCredentialSummary` — never the sealed connection, never a token, never `accountId`. That
 * "read model never carries a secret field" guarantee is enforced by `PublishCredentialSummary`'s own
 * shape (`types.ts`), not by anything this route does — there is no field here that COULD leak one.
 *
 * `system.publish`-gated on every verb, matching `publish-site.ts`'s reasoning for its own trigger/
 * status routes: a saved connection's `label`/`providerId`/`isDefault` is itself operationally
 * sensitive (which external accounts this workspace can publish to), so this gets the same
 * single-permission gate as the fact of a live publish, not the softer `system.read` the state-less
 * `/publish/preview` route uses.
 *
 * 2026-08-16 — this is now the ONE place `verifyPublishCredential` (`static-publish/verify.ts`) is
 * ever called from a human action, per that module's own "never agent-facing" contract: `POST`/`PUT`
 * verify the just-saved connection best-effort (awaited, included in the response — the "did what I
 * just typed work" moment) without gating the save itself on the outcome (a rejected credential can
 * still be saved and fixed later — this route only reports what it found, it does not decide the
 * save is invalid because the provider disagrees), and a new `POST .../:id/verify` lets a human
 * re-check a stale or never-verified result without re-saving. Both write ONLY the cached,
 * non-secret `{ok, message, checkedAt}` result — never anything that could leak a credential value.
 *
 * Also 2026-08-16 (migration `0044`): `verifyAfterSave` additionally heals `publish_credential_sets
 * .account_label` (`publish-credentials/store.ts`'s `healAccountLabel`) whenever a verify comes back
 * `"valid"` with an `accountLabel` — this is the ONE write path allowed to populate that column (see
 * `store.ts`'s own header for why `createPublishCredential`/`updatePublishCredential` deliberately do
 * not: this route is human-gated, `create`/`update` are not, sharing a write path with an agent-facing
 * s3-compatible credential save). This is what makes the fix for "verification lived in
 * `InMemoryPublishCredentialVerificationCache` only, so a routine server restart silently reverted a
 * working, previously-verified credential to no known account" durable: `deployment_get_static_publish
 * _capabilities` can now read a real DB column that survives a restart, instead of only ever reading a
 * process-memory cache that does not.
 *
 * Also 2026-08-16 (same night, second pass): `POST`/`PUT` above already heal a row's account label the
 * moment it is saved — but only if THAT verify attempt succeeds. A row whose first auto-verify failed
 * (provider unreachable at save time), or one saved before this wiring existed at all, stayed
 * `account_label: null` forever unless a human found and clicked the per-row `POST .../:id/verify`
 * action — the reported bug: the assistant's `deployment_get_static_publish_capabilities` tool had no
 * account to default a repository-backed publish's `owner` to, and correctly refused to guess one, but a
 * non-technical owner had no reason to know a "Verify" button existed to fix it. `GET` below now also
 * calls {@link accountLabelHealScheduler}`.triggerFor` after every list read, for any row this list
 * call itself found still `null` on a provider that can ever yield a label
 * (`idsNeedingAccountLabelHeal`, `static-publish/verify.ts`'s `canYieldAccountLabel`) — fire-and-forget,
 * never awaited, never able to affect this (or any) response. This is deliberately the ONLY new trigger
 * point: `static-publish/verify.ts`'s own header is categorical that only a human-gated caller may ever
 * invoke a provider probe, and `publish-agent-tools.ts`'s capabilities handler reads this same table
 * via `listPublishCredentials` directly — putting a probe inside that shared, decrypt-free read
 * function (or anywhere reachable from it) would put a live outbound request on the agent's own path,
 * which is exactly what that boundary exists to prevent. This GET handler is human-gated (the admin
 * Deployment → Static Site tab loading its own list) and reuses `verifyAfterSave` verbatim as the
 * scheduler's `heal` callback, so a self-heal shares the exact same probe/cache/DB-write behavior a
 * human clicking "Verify" already gets — nothing new is added to WHAT a heal does, only WHEN it can
 * additionally fire. See `account-label-heal-scheduler.ts`'s own header for the fire-and-forget/
 * in-flight-dedupe contract that keeps this off the hot path and safe under `62ca21c7`'s guard.
 *
 * See `CredentialsDeps` in `server/routes/types.ts` for why each route picks only its own repo.
 */
export type AdminPublishCredentialsDeps = Pick<
  RouteDeps,
  | "projectKeys"
  | "workspaceId"
  | "authorize"
  | "clock"
  | "idGen"
  | "vendorCredentialSetRepo"

  | "contentKernel"
  | "siteAssistantSecretSealer"
  | "siteAssistantSecretKeyring"
  | "publishExecutionMode"
  | "publishCredentialVerificationCache"
  | "loadDeployTargets"
  | "observability"
>;

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/system/publish/credentials";

/** Only a project-bound create starts non-default (attached next); a site row, including every
 * create where no project store is open, keeps Jini's first-row auto-default. */
function initialPublishDefault({ body, deps }: { body: Record<string, unknown>; deps: AdminPublishCredentialsDeps }, _optional = {}): unknown {
  return body.isDefault ?? (body.scope !== "site" && deps.vendorCredentialSetRepo.project ? false : undefined);
}

function credentialUpdateFields({ body }: { body: Record<string, unknown> }, _optional = {}): Omit<UpdatePublishCredentialInput, "workspaceId" | "id"> {
  return {
    ...(body.label !== undefined ? { label: body.label } : {}),
    ...(body.connection !== undefined ? { connection: body.connection } : {}),
    ...(body.isDefault !== undefined ? { isDefault: body.isDefault } : {}),
    ...(body.worksFor !== undefined ? { worksFor: body.worksFor } : {}),
  };
}

/** Every error this route can produce, shaped once so each handler below stays a thin dispatch.
 *  Mirrors `publish-site.ts`'s inline `{error}`/`{error, code, details}` shapes for the same
 *  permission failure; the four typed store-error branches are new to this route and have no
 *  precedent to match.
 *
 *  2026-08-16 — the untyped fallback used to be `throw err`, re-throwing out of the caller's own
 *  `catch` block instead of responding. That is not a guard, it just moves the same unhandled
 *  rejection one frame up: found live when `GET`/`DELETE` below had no `try`/`catch` at all (an
 *  AST scan over every `app.<verb>()` handler in `src/server/routes/**` caught it), and the SAME
 *  scan showed `POST`/`PUT`/`POST .../:id/verify` already had a `try { ... } catch (err) {
 *  sendStoreError(res, err); }` shape that LOOKED guarded but was not — any error outside the four
 *  typed ones above still escaped every one of those handlers too. Every caller below now gets a
 *  real response for an error this function does not recognize, instead of a hung request. */
function sendStoreError({ res, err }: { res: Response; err: unknown }, _options = {}): void {
  if (err instanceof ToolInputError) { res.status(409).json({ error: "KEY_IN_USE", detail: err.message }); return; }
  if (err instanceof PublishCredentialValidationError) {
    res.status(400).json({ error: "VALIDATION", detail: err.message });
    return;
  }
  if (err instanceof PublishCredentialDuplicateLabelError) {
    res.status(409).json({ error: "DUPLICATE_LABEL", detail: err.message });
    return;
  }
  if (err instanceof PublishCredentialNotFoundError) {
    res.status(404).json({ error: "NOT_FOUND", detail: err.message });
    return;
  }
  if (err instanceof PublishCredentialSecretStoreUnconfiguredError) {
    res.status(503).json({ error: "SECRET_STORE_UNCONFIGURED", detail: err.message });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/system/publish-credentials", code: "INTERNAL_ERROR" });
}

export function registerAdminPublishCredentialsRoutes(app: Express, deps: AdminPublishCredentialsDeps): void {
  const readDeps = { sealer: deps.siteAssistantSecretSealer, repo: deps.vendorCredentialSetRepo, loadDeployTargets: deps.loadDeployTargets };
  const writeDeps = {
    repo: deps.vendorCredentialSetRepo,
    sealer: deps.siteAssistantSecretSealer,
    keyring: deps.siteAssistantSecretKeyring,
    clock: deps.clock,
    idGen: deps.idGen,
    loadDeployTargets: deps.loadDeployTargets,
  };
  /** Verifies ONE specific row (the one this route just touched) against its real provider. The
   *  PROVIDER-PROBE layer never throws — `verify.ts`'s per-provider checkers fold every network
   *  failure into `"unreachable"` rather than throwing (see that file's own header), so a transient
   *  network blip can never turn a successful save into a 500. That guarantee does NOT extend to the
   *  DECRYPT step underneath it: `verifyPublishCredentialById` calls `resolveForPublish`
   *  (`publish-credentials/store.ts`), which throws `PublishCredentialSecretStoreUnconfiguredError`
   *  when the stored secret cannot be decrypted (a missing site key, or a tampered/corrupt row)
   *  — the SAME "surface, don't swallow" contract that module documents for itself. Every caller of
   *  this function below MUST run through a `try`/`catch` that maps the result via `sendStoreError`.
   *
   *  Found live (2026-08-16): this was NOT true for `POST .../:id/verify` below until this fix — it
   *  had no try/catch at all, so a missing site key took down the WHOLE server process (Express 4
   *  does not catch an async handler's own rejection, and nothing else in `src/` was catching it at
   *  the process level either), not just that one request. An earlier version of THIS comment
   *  claimed `verifyAfterSave` "never throws" without qualifying which layer that applied to — do
   *  not repeat that mistake; the provider-probe layer's guarantee and the decrypt layer's contract
   *  are two different things.
   *
   *  Returns `null` only if the row vanished between the write this handler just performed and this
   *  call — treated the same as "nothing to report" by every caller below, never surfaced as an
   *  error for what was otherwise a successful save.
   *
   *  Also heals `account_label` (`store.ts`'s `healAccountLabel`) whenever the result carries one —
   *  see this file's own header. Deliberately checked via `result.accountLabel !== undefined` rather
   *  than truthiness: an empty string is not a real account login/username (`verify.ts`'s own
   *  extractors never produce one — see their doc comments), but the distinction is cheap to keep
   *  exact rather than relying on that invariant holding forever. The heal is fire-and-forget from
   *  this function's own caller's point of view (awaited here, but its failure must not turn a
   *  successful verify into a failed response) — a targeted single-column write against a row this
   *  same request just confirmed exists has no realistic failure mode short of the DB itself being
   *  down, at which point the save/verify response the caller already has is still honest. */
  async function verifyAfterSave(id: string): Promise<PublishCredentialVerificationResult | undefined> {
    const result = await verifyPublishCredentialById(
      {
        repo: deps.vendorCredentialSetRepo,
        sealer: deps.siteAssistantSecretSealer,
        cache: deps.publishCredentialVerificationCache,
        clock: deps.clock,
        loadDeployTargets: deps.loadDeployTargets,
        observability: deps.observability,
      },
      { workspaceId: deps.workspaceId, id }
    );
    if (result?.accountLabel !== undefined) {
      await healAccountLabel({ repo: deps.vendorCredentialSetRepo }, { workspaceId: deps.workspaceId, id, accountLabel: result.accountLabel });
    }
    return result ?? undefined;
  }

  /** Built ONCE per route registration, like `verifyAfterSave` itself — its in-flight dedupe only
   *  works if it survives between requests. `heal` is `verifyAfterSave` verbatim: a background self-
   *  heal does exactly what a human clicking "Verify" already does, through the same function, never a
   *  parallel code path that could drift from it. See this file's own header ("second pass") and
   *  `account-label-heal-scheduler.ts`'s header for the full reasoning. */
  const accountLabelHealScheduler = createAccountLabelHealScheduler({ heal: verifyAfterSave });

  /** Hands the scheduler every listed row still missing an account label whose host can produce one
   *  (the host's declared `yieldsAccountLabel`). Runs after the response is sent, so a registry load
   *  failure is logged and swallowed: it must never reach the request that triggered it. */
  async function triggerAccountLabelHeal(credentials: readonly PublishCredentialSummary[]): Promise<void> {
    try {
      const registry = await deps.loadDeployTargets(deps.workspaceId);
      accountLabelHealScheduler.triggerFor(idsNeedingAccountLabelHeal(credentials, (providerId) => canYieldAccountLabel(registry, providerId)));
    } catch (err) {
      console.error("[publish-credentials] account-label heal skipped: deploy targets could not be loaded", err);
    }
  }

  /** Shared workspace-path-param + `system.publish` authorization check every verb below performs
   *  first — same two-step `publish-site.ts` already repeats per-route; extracted here since this
   *  file has four verbs instead of that file's two. Returns `true` and has already written the
   *  response iff the caller should stop. */
  async function rejectUnlessAuthorized(req: Request, res: Response): Promise<boolean> {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return true;
    }
    const principal = getAuthedPrincipal(res);
    const authResult = await deps.authorize({
      principalId: principal.id,
      permission: "system.publish",
      workspaceId: deps.workspaceId,
      entityType: "site-publish",
    });
    if (!authResult.allowed) {
      res.status(403).json({
        error: `principal '${principal.id}' is not authorized for 'system.publish' (${authResult.reason})`,
        code: "FORBIDDEN",
        details: { permission: "system.publish", reason: authResult.reason },
      });
      return true;
    }
    return false;
  }

  app.get(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      const credentials: PublishCredentialSummary[] = await listPublishCredentials(readDeps, { workspaceId: deps.workspaceId });
      res.status(200).json({ credentials, executionMode: deps.publishExecutionMode });
      // Fires AFTER the response is already sent, and only for rows THIS call itself found still
      // `null` — never awaited, never able to change or delay what the caller above just received.
      // `accountLabelHealScheduler.triggerFor` is documented to never throw or reject, even if `heal`
      // misbehaves (`account-label-heal-scheduler.ts`'s own tests cover that directly) — see this
      // file's header for why this is the one new trigger point and why it must stay exactly this
      // narrow.
      void triggerAccountLabelHeal(credentials);
    } catch (err) {
      sendStoreError({ res, err });
    }
  });

  app.post(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const registry = await deps.loadDeployTargets(deps.workspaceId);
      const credential = await createPublishCredential(writeDeps, {
        workspaceId: deps.workspaceId,
        label: body.label,
        connection: body.connection,
        isDefault: initialPublishDefault({ body, deps }),
        worksFor: body.worksFor,
        // "site" = only for this site; omitted = the project store when one is attached.
        scope: body.scope,
      });
      if (credential.scope === "project") await deps.projectKeys?.use({ keyId: credential.id, use: true });
      invalidatePublishCredentialCompatibility({ workspaceId: deps.workspaceId, registry, cache: deps.publishCredentialVerificationCache, after: credential });
      // Only when `connection` was actually supplied — matches `updatePublishCredential`'s own
      // "connection omitted => nothing changed to verify" reasoning below. `createPublishCredential`
      // always requires a connection, so this is always true here; kept as an explicit check (rather
      // than an unconditional call) so both handlers read the same way.
      const verification = body.connection !== undefined ? await verifyAfterSave(credential.id) : undefined;
      res.status(201).json({ credential, ...(verification ? { verification } : {}) });
    } catch (err) {
      sendStoreError({ res, err });
    }
  });

  app.put(`${BASE_PATH}/:id`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const registry = await deps.loadDeployTargets(deps.workspaceId);
      const before = await describeCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      const credential = await updatePublishCredential(writeDeps, {
        workspaceId: deps.workspaceId,
        id: req.params.id,
        ...credentialUpdateFields({ body }),
      });
      if (before && body.worksFor !== undefined) invalidatePublishCredentialCompatibility({ workspaceId: deps.workspaceId, registry, cache: deps.publishCredentialVerificationCache, before, after: credential });
      // A label-only/isDefault-only rename verifies nothing new — the connection (and therefore
      // whatever a previous verification already found) is unchanged, so re-checking here would
      // just repeat the same network call for no new information.
      const verification = body.connection !== undefined ? await verifyAfterSave(credential.id) : undefined;
      res.status(200).json({ credential, ...(verification ? { verification } : {}) });
    } catch (err) {
      sendStoreError({ res, err });
    }
  });

  app.post(`${BASE_PATH}/:id/verify`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      const existing = await describeCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      if (!existing) {
        res.status(404).json({ error: "NOT_FOUND", detail: `no publish credential '${req.params.id}' in this workspace` });
        return;
      }
      const verification = await verifyAfterSave(existing.id);
      res.status(200).json({ verification });
    } catch (err) {
      // `describeCredential` itself never decrypts (this file's own header) and cannot land here —
      // this catch exists for `verifyAfterSave`'s decrypt step (see that function's own doc above:
      // it is NOT covered by the provider-probe layer's "never throws" guarantee). Mirrors the
      // `POST`/`PUT` handlers' identical `try { ... } catch (err) { sendStoreError(res, err); }`
      // shape just below/above — this route was the one place that pattern was missing.
      sendStoreError({ res, err });
    }
  });

  app.delete(`${BASE_PATH}/:id`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      // Idempotent — `deletePublishCredential`/`VendorCredentialSetRepoPort.delete` are both no-ops
      // (not errors) for a missing row, matching this route's own documented 204-always contract.
      // A THROWN error here is a different case (e.g. the repo itself is unreachable) — not the
      // idempotent-missing-row path above, so it still needs a response, not a silent no-op.
      const registry = await deps.loadDeployTargets(deps.workspaceId);
      const before = await describeCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      await deletePublishCredential({ ...readDeps, transaction: deps.contentKernel }, { workspaceId: deps.workspaceId, id: req.params.id });
      if (before) invalidatePublishCredentialCompatibility({ workspaceId: deps.workspaceId, registry, cache: deps.publishCredentialVerificationCache, before });
      res.status(204).end();
    } catch (err) {
      sendStoreError({ res, err });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { deploymentRefusal } from '#src/features/consent/service';
import { listPublishContentPeers } from "#src/features/publish-content/peers";
import { getPublishTrustContext, publishTrustAuthorizeFor } from "#src/server/inbound/admin-http/publish-trust-auth";
import type { Express } from "express";
import { ToolInputError } from "@jini-ai/core";

import {
  inspectStaticPublish,
  composePublishCredentialSource,
  getPublishRunSnapshot,
  listPublishDestinations,
  missingRequiredFieldMessage,
  planStaticPublish,
  readStaticPublishConfig,
  startPublishRun,
  unknownTargetMessage,
  type StaticPublishConfig,
  type PublishCredentialSource,
} from "#src/features/deployments/static-publish/index";
import type {
  DeployTargetCredentialSpec,
  DeployTargetRegistry,
  LoadedDeployTarget,
} from "#src/features/deployments/contracts";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

const WORKSPACE_NOT_FOUND = "workspace was not found";
const SITE_PUBLISH_ENTITY = "site-publish";

/**
 * @file Admin Deployment panel → publish-to-a-static-host backend.
 *
 * Registers TWO routes, deliberately mirroring `./export-site.ts`'s own trigger+status shape
 * almost exactly (see that file's header for the full reasoning this route inherits): a publish
 * runs a fresh in-process export (see `static-publish/adapter.ts`'s `publishStaticSite`) and then
 * blocks on an external provider's own build/deploy pipeline — a host's build or deployment poll,
 * up to roughly a minute — so `POST .../system/publish` starts the run and
 * returns `202` immediately with a snapshot; `GET .../system/publish` polls the same snapshot. The
 * single process-local mutable slot backing both lives in `static-publish/publish-run.ts` (2026-08-16,
 * Terra audit finding #1 — see that file's header for the full "who shares this slot and why" story),
 * NOT in this file — a plain export's own slot (`export-site.ts`'s `currentRun`, in `export-run.ts`)
 * stays independent (a plain export and a publish are different operations that may legitimately need
 * independent status), but THIS route's own slot is now shared with `deployment_execute_static_publish`
 * (`publish-agent-tools.ts`), which used to call `publishStaticSite` directly with nothing to check at
 * all — the actual gap the finding was about.
 *
 * `system.publish`-gated for BOTH the trigger and the status poll — deliberately NOT split into a
 * `system.publish`/`system.read` pair the way `export-site.ts` splits trigger/status. Reasoning: a
 * completed publish's status snapshot names the exact external `url` this workspace's content is
 * now live at (`StaticPublishOutcome`'s `url` field) and, on a validation failure, can echo back the
 * caller-supplied `owner`/`repo`/`teamId`. Export's status is comparatively inert (counts and local
 * file paths); publish's status is itself operationally sensitive information about a live external
 * resource, so it gets the stricter, single-permission gate.
 *
 * Request body for the trigger: `{ target, projectName: string, credentialId?, ...configFields }` —
 * `target` is any id this workspace's deploy registry knows (`RouteDeps.loadDeployTargets`), and the
 * other fields read are exactly the ones that target's descriptor declares.
 *
 * `credentialId` (2026-09-20, terra review finding 1 — Critical) BINDS the publish to the saved
 * connection the operator chose, instead of letting the server pick whichever row is `is_default`
 * when the POST lands: selecting connection B and clicking Publish while B's promotion was still in
 * flight published the site to A's account. It is OPTIONAL, and deliberately so — the
 * `deployment_execute_static_publish` agent tool has no chosen connection, and a self-hosted install
 * whose credentials come from `GITHUB_TOKEN`/`VERCEL_TOKEN`/... has no connection ids at all. Those
 * callers keep the DEFAULT lookup, explicitly (`static-publish/credentials.ts`'s
 * `createDbPublishCredentialSource`); an id that is supplied is validated against this workspace and
 * this target by that same module, and refuses rather than falling back. Every other field is judged
 * by `static-publish/adapter.ts`'s `planStaticPublish` — the same call `publishStaticSite` makes —
 * so there is exactly one place a config is judged valid or not.
 *
 * A THIRD route, `GET .../system/publish/preview`, was added 2026-08-15 alongside the admin UI's
 * Static Site tab publish card. `deployment_preview_static_publish` (`publish-agent-tools.ts`)
 * already gives the ASSISTANT this exact read — target validity, the computed base path, and
 * whether a credential is configured (a boolean only, never the token) — but that tool is reached
 * over the agent-tool transport, not an HTTP route a browser session can call, and the admin UI has
 * no other way to answer "would this publish work?" before spending a real trigger+run on the
 * question. This route reuses the SAME `planStaticPublish` the tool calls, plus this file's own
 * `credentialSource`, so a preview here and a preview from the assistant can never disagree.
 * `system.read`-gated, matching every other GET in this directory (`export-site.ts`,
 * `deployment-overview.ts`) — it performs zero remote mutations; provider inspections may issue authenticated reads.
 *
 * A FOURTH, `GET .../system/publish-targets` (`system.read`), lists the registry's targets (id,
 * label, config field specs) so the admin UI can render the publish card from descriptors.
 * `GET .../system/publish/destinations` (`system.read`) derives saved destinations from successful
 * history for this site's workspace. It never resolves credentials; only POST executes a publish.
 */
export type AdminPublishSiteDeps = RouteDeps;

// `PublishRunStatus`/`PublishRunSnapshot` used to be declared here, backing a PRIVATE module-scope
// `currentRun` this file alone could see or update. Both now live in `static-publish/publish-run.ts`,
// and this route reads/writes the run through that module's `getPublishRunSnapshot`/`startPublishRun`
// instead of a local variable — see this file's header for why (Terra audit finding #1:
// `deployment_execute_static_publish` had no equivalent slot to check at all).

/** No longer a module-scope constant (2026-08-15): `createEnvPublishCredentialSource` is now bound
 *  to one workspace at construction time (Terra's finding — it used to accept and ignore
 *  `workspaceId`), and `composePublishCredentialSource` layers the encrypted DB-backed source on top
 *  per the install's `PublishExecutionMode`. Both need `deps`, which is only available inside
 *  {@link registerAdminPublishSiteRoutes} — see that function's own first lines for where this is now
 *  built. */

/**
 * Parses and shape-validates the trigger request body's TARGET-INDEPENDENT fields. Never throws —
 * every malformed shape maps to a `{ok:false, error}` result this route turns into a `400`, matching
 * `export-site.ts`'s own `parseTriggerRequestBody` discipline. Which config fields `target` takes,
 * and whether their values are valid, is judged by the registry (`readStaticPublishConfig` +
 * `planStaticPublish`), so a caller only ever gets one canonical rejection for the same bad value.
 */
function parsePublishRequestBody(
  body: unknown
): { ok: true; raw: Record<string, unknown>; targetId: string; projectName: string; credentialId?: string } | { ok: false; error: string } {
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    return { ok: false, error: "request body must be a JSON object" };
  }
  const raw = body as Record<string, unknown>;

  if (typeof raw.projectName !== "string" || raw.projectName.trim() === "") {
    return { ok: false, error: "'projectName' (non-empty string) is required" };
  }

  // Shape only, same discipline as every other field here — whether this id names a connection this
  // workspace actually owns, for this target, is judged exactly once, by the credential source
  // (`static-publish/credentials.ts`). Optional because the agent tool and env-var installs have no
  // connection id to send; see this file's header for the full backward-compatibility contract.
  if (!validOptionalCredential({ value: raw.credentialId })) {
    return { ok: false, error: "'credentialId' must be a non-empty string when present" };
  }

  if (typeof raw.target !== "string" || raw.target.trim() === "") {
    return { ok: false, error: "'target' (non-empty string) is required" };
  }
  return {
    ok: true,
    raw,
    targetId: raw.target,
    projectName: raw.projectName,
    ...(typeof raw.credentialId === "string" ? { credentialId: raw.credentialId } : {}),
  };
}

function validOptionalCredential({ value }: { value: unknown }, _options = {}): boolean {
  return value === undefined || (typeof value === "string" && value.trim() !== "");
}

/**
 * Resolves `targetId` in this workspace's registry and reads its descriptor-declared config fields
 * from `raw`. Registry refusals (a module that did not load) are logged, never returned.
 * @returns The target and config, or a refusal naming the unknown target / the non-string field.
 * @complexity One registry load plus O(f) declared fields.
 */
async function readTargetConfig(
  deps: AdminPublishSiteDeps,
  targetId: string,
  raw: Record<string, unknown>,
  blankAsAbsent: boolean
): Promise<{ ok: true; registry: DeployTargetRegistry; target: LoadedDeployTarget; config: StaticPublishConfig } | { ok: false; error: string }> {
  const registry = await deps.loadDeployTargets(deps.workspaceId);
  for (const refusal of registry.refusals) console.warn(`[publish-site] ${refusal}`);
  const target = registry.get(targetId);
  if (target === undefined) return { ok: false, error: unknownTargetMessage(registry, targetId) };
  const read = readStaticPublishConfig(target, raw, { blankAsAbsent });
  if (!read.ok) return { ok: false, error: read.message };
  return { ok: true, registry, target, config: read.config };
}

/** A target's saved-credential form, as the admin renders it: the vendor's display name, the field
 *  specs (secret fields flagged, never a value), the form's help and token page, and which field is
 *  the token. Never the vendor id. @complexity O(1). */
function publicCredentialSpec(spec: DeployTargetCredentialSpec): {
  vendorLabel?: string;
  help?: string;
  userHelp?: string;
  tokenPageUrl?: string;
  tokenField: string;
  fields: DeployTargetCredentialSpec["fields"];
} {
  return {
    ...(spec.vendorLabel !== undefined ? { vendorLabel: spec.vendorLabel } : {}),
    ...(spec.help !== undefined ? { help: spec.help } : {}),
    ...(spec.userHelp !== undefined ? { userHelp: spec.userHelp } : {}),
    ...(spec.tokenPageUrl !== undefined ? { tokenPageUrl: spec.tokenPageUrl } : {}),
    tokenField: spec.tokenField,
    fields: spec.fields,
  };
}

function credentialChoice({ value }: { value: unknown }, _options = {}): { credentialId?: string } {
  if (value === undefined) return {};
  if (typeof value !== "string" || !value.trim()) throw new ToolInputError({ message: "credentialId must be a non-empty string naming the selected connection. Reload and choose it again." });
  return { credentialId: value };
}

/** The HTTP projection calls the same authenticated inspection used by the chat preview. */
async function httpPublishPreview(required: {
  deps: AdminPublishSiteDeps; credentialSource: PublishCredentialSource; registry: DeployTargetRegistry;
  config: StaticPublishConfig; query: Record<string, unknown>;
}, _options = {}) {
  const { deps, credentialSource, registry, config, query } = required;
  const plan = planStaticPublish(registry, config);
  const credential = await credentialSource.isConfigured({ workspaceId: deps.workspaceId, target: config.target });
  const inspected = plan.ok && credential.configured ? await inspectStaticPublish({
    deps: { credentialSource, loadDeployTargets: deps.loadDeployTargets, tracker: deps.tracker, observability: deps.observability, formDestination: deps.formDestination },
    input: { workspaceId: deps.workspaceId, config, projectName: typeof query.projectName === "string" ? query.projectName : "", ...credentialChoice({ value: query.credentialId }) },
  }) : {};
  return { target: config.target, valid: plan.ok, validationError: plan.ok ? null : plan.message,
    basePath: plan.ok ? (plan.basePath ?? null) : null, credentialsConfigured: credential.configured,
    credentialGuidance: credential.configured ? null : credential.reason,
    providerInspection: inspected.inspection };
}

async function readPublishTriggerConfig(required: {
  deps: AdminPublishSiteDeps; targetId: string; raw: Record<string, unknown>;
}, _options = {}): Promise<{ ok: true; config: StaticPublishConfig } | { ok: false; status: number; body: Record<string, unknown> }> {
  const { deps, targetId, raw } = required;
  // Fails fast, before flipping the shared run slot to "running" or touching the
  // filesystem/network at all, on a config `publishStaticSite` would reject anyway — the same
  // `planStaticPublish` verdict `publishStaticSite` reaches internally — so a caller who only sends
  // a malformed config never sees a "running" snapshot at all.
  const read = await readTargetConfig(deps, targetId, raw, false);
  if (!read.ok) return { ok: false, status: 400, body: { error: read.error } };
  const plan = planStaticPublish(read.registry, read.config);
  if (!plan.ok) return { ok: false, status: 400, body: { error: plan.message } };
  if (read.config.customDomain) {
    return { ok: false, status: 409, body: { code: "DOMAIN_CONFIRMATION_REQUIRED", error: "Review and confirm the exact domain changes through deployment_execute_static_publish in chat. This HTTP request cannot stand in for that human confirmation." } };
  }
  return { ok: true, config: read.config };
}

export function registerAdminPublishSiteRoutes(app: Express, deps: AdminPublishSiteDeps): void {
  // Built once per `registerAdminPublishSiteRoutes` call (this route file's own registration is
  // itself a once-per-process composition step), bound to `deps.workspaceId` — see
  // `static-publish/credentials.ts`'s `composePublishCredentialSource` header for the DB-first,
  // env-fallback-only-when-self-hosted composition this now performs.
  const credentialSource = composePublishCredentialSource({
    workspaceId: deps.workspaceId,
    executionMode: deps.publishExecutionMode,
    dbDeps: { repo: deps.vendorCredentialSetRepo, sealer: deps.siteAssistantSecretSealer, loadDeployTargets: deps.loadDeployTargets },
  });

  app.post("/api/admin/v1/workspaces/:workspaceId/system/publish", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: WORKSPACE_NOT_FOUND });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.publish",
        workspaceId: deps.workspaceId,
        entityType: SITE_PUBLISH_ENTITY,
      });
      if (!authorized) { deps.tracker.capture({ name: "site_publish_blocked", userId: principal.id }, { properties: { reasonClass: "auth", source: "admin" } }); return; }

      const parsed = parsePublishRequestBody(req.body);
      if (!parsed.ok) {
        deps.tracker.capture({ name: "site_publish_blocked", userId: principal.id }, { properties: { reasonClass: "config", source: "admin" } });
        res.status(400).json({ error: parsed.error });
        return;
      }

      const read = await readPublishTriggerConfig({ deps, targetId: parsed.targetId, raw: parsed.raw });
      if (!read.ok) {
        deps.tracker.capture({ name: "site_publish_blocked", userId: principal.id }, { properties: { reasonClass: "config", source: "admin" } });
        res.status(read.status).json(read.body);
        return;
      }

      const consent = deps.siteConsent
        ? await deps.siteConsent.deploymentCheck({ principalId: principal.id, permission: 'system.publish' })
        : deploymentRefusal({ problems: [{ code: 'CONSENT_UNAVAILABLE', message: 'Cookie consent readiness is unavailable. No publish was started.' }] });
      if (consent) { deps.tracker.capture({ name: "site_publish_blocked", userId: principal.id }, { properties: { reasonClass: "consent", source: "admin" } }); res.status(409).json(consent); return; }

      // No `await` between this check and `startPublishRun` below — same single-synchronous-stretch
      // reasoning `export-site.ts`'s own trigger route documents, so two concurrent POSTs cannot both
      // observe "idle". This is now ALSO the same guard `deployment_execute_static_publish`
      // (`publish-agent-tools.ts`) checks before its own confirmed publish call — both read/write the
      // ONE shared slot in `static-publish/publish-run.ts`, so a concurrent trigger from either caller
      // is refused, not raced (Terra audit finding #1).
      if (getPublishRunSnapshot().status === "running") {
        deps.tracker.capture({ name: "site_publish_blocked", userId: principal.id }, { properties: { reasonClass: "busy", source: "admin" } });
        res.status(409).json({ error: "a publish is already running", run: getPublishRunSnapshot() });
        return;
      }

      // Deliberately not awaited — see this file's header for why the response returns before the
      // publish finishes. `startPublishRun` itself keeps the shared slot in sync as the publish
      // settles, so a poller can never observe a stale "running" snapshot after the promise has
      // actually settled.
      const snapshot = startPublishRun(
        { credentialSource, loadDeployTargets: deps.loadDeployTargets, tracker: deps.tracker, observability: deps.observability, formDestination: deps.formDestination, publicPageSecurityHeaders: deps.publicPageSecurityHeaders, pluginExportHosts: deps.pluginExportHosts },
        {
          productEvent: { userId: principal.id, source: "admin" },
          workspaceId: deps.workspaceId,
          publishOutputRootDir: deps.publishOutputRootDir,
          idGen: deps.idGen,
          exportSiteBound: deps.exportSiteBound,
          config: read.config,
          projectName: parsed.projectName,
          // The connection the operator actually chose in the Static Site tab. Never defaulted here:
          // an absent id means "this caller has no chosen connection", which the credential source
          // answers with its own default lookup — see `parsePublishRequestBody` above.
          ...credentialChoice({ value: parsed.credentialId }),
        },
        deps.clock,
        deps.publishHistoryStore,
      );

      res.status(202).json(snapshot);
    } catch (err) {
      // Everything above `startPublishRun` (auth check, snapshot read, body parsing) runs
      // synchronously-awaited in this one try; `startPublishRun` itself is deliberately NOT awaited
      // (see its own call site comment) so a failure inside the run it starts can never reach this
      // catch — only a failure BEFORE that point can, e.g. `deps.authorize` itself throwing.

      sendAdminFailure({ res, error: err }, { operation: "routes/system/publish-site", code: "INTERNAL_ERROR" });
    }
  });

  app.get("/api/admin/v1/workspaces/:workspaceId/system/publish", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: WORKSPACE_NOT_FOUND });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.publish",
        workspaceId: deps.workspaceId,
        entityType: SITE_PUBLISH_ENTITY,
      });
      if (!authorized) return;

      res.status(200).json(getPublishRunSnapshot());
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/publish-site", code: "INTERNAL_ERROR" });
    }
  });

  app.get("/api/admin/v1/workspaces/:workspaceId/system/publish/preview", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: WORKSPACE_NOT_FOUND });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: SITE_PUBLISH_ENTITY,
      });
      if (!authorized) return;

      const query = req.query as Record<string, unknown>;
      if (typeof query.target !== "string" || query.target.trim() === "") {
        res.status(400).json({ error: "'target' query param (non-empty string) is required" });
        return;
      }
      const read = await readTargetConfig(deps, query.target, query, true);
      if (!read.ok) {
        res.status(400).json({ error: read.error });
        return;
      }
      // A required field that is absent is a malformed request (400); a present-but-invalid value is
      // an answer (200, `valid:false`) — the distinction the admin card renders.
      const missing = missingRequiredFieldMessage(read.target, read.config);
      if (missing !== null) {
        res.status(400).json({ error: missing });
        return;
      }

      // Same reads `deployment_preview_static_publish`'s handler performs (this file's header) — the
      // registry's plan (config check + base path) and local credential readiness. No export runs.
      // Authenticated provider inspection is separate from `isConfigured()` (2026-08-15 split, see
      // `static-publish/types.ts`'s `PublishCredentialSource` header) — a preview must never resolve a
      // real credential just to read a boolean off it.
      res.status(200).json(await httpPublishPreview({ deps, credentialSource, registry: read.registry, config: read.config, query }));
    } catch (err) {
      // `credentialSource.isConfigured` is the one awaited call here that can reach a real backing
      // store (DB-backed source, per this file's header) — a failure there used to escape this
      // handler entirely (no `try`/`catch` at all; found by an AST scan over every `app.<verb>()`
      // handler in `src/server/routes/**`).
      if (err instanceof ToolInputError) {
        res.status(400).json({ error: err.message, code: "PROVIDER_INSPECTION_FAILED" });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/system/publish-site", code: "INTERNAL_ERROR" });
    }
  });

  // Listing is read-only: execution still goes through the system.publish-gated POST above.
  app.get("/api/admin/v1/workspaces/:workspaceId/system/publish/destinations", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: WORKSPACE_NOT_FOUND });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: SITE_PUBLISH_ENTITY,
      });
      if (!authorized) return;
      const registry = await deps.loadDeployTargets(deps.workspaceId);
      // Omit peer identities as well as peer rows without the additional permission.
      const trust = getPublishTrustContext(res);
      const peerAuthorization = await (trust ? publishTrustAuthorizeFor(trust) : deps.authorize)({
        principalId: principal.id, permission: "publish_content.read", workspaceId: deps.workspaceId,
      });
      let peers: Awaited<ReturnType<typeof listPublishContentPeers>> = [];
      if (peerAuthorization.allowed) peers = await listPublishContentPeers({ repo: deps.publishContentPeerRepo }, { workspaceId: deps.workspaceId });
      res.status(200).json(await listPublishDestinations({
        workspaceId: deps.workspaceId,
        historyStore: deps.publishHistoryStore,
        registry,
        peers,
      }));
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/publish-site", code: "INTERNAL_ERROR" });
    }
  });

  // The registry's targets, for the admin publish card to render from descriptors (deploy plan T7).
  // Ids, labels, config field specs, the saved-credential form's field specs and the translations of
  // that text (`i18n`) only: a module path, a vendor id or a refusal reason stays server-side.
  app.get("/api/admin/v1/workspaces/:workspaceId/system/publish-targets", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: WORKSPACE_NOT_FOUND });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: SITE_PUBLISH_ENTITY,
      });
      if (!authorized) return;

      const registry = await deps.loadDeployTargets(deps.workspaceId);
      for (const refusal of registry.refusals) console.warn(`[publish-site] ${refusal}`);
      res.status(200).json({
        targets: registry.list().map(({ descriptor }) => ({
          id: descriptor.id,
          label: descriptor.label,
          defaultForNewDestination: registry.get(descriptor.id)?.module.defaultForNewDestination === true,
          authenticatedPreview: registry.get(descriptor.id)?.module.preview !== undefined,
          configFields: descriptor.configFields,
          ...(descriptor.projectName !== undefined ? { projectName: descriptor.projectName } : {}),
          ...(descriptor.credential !== undefined ? { credential: publicCredentialSpec(descriptor.credential) } : {}),
          ...(descriptor.i18n !== undefined ? { i18n: descriptor.i18n } : {}),
        })),
      });
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/publish-site", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from "express";

import { processServerLogSource } from "#src/features/server-logs/process-source";
import { parseServerLogFilters, readServerLogs, ServerLogFilterError, type ServerLogSourcePort } from "#src/features/server-logs/read-server-logs";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file `GET /api/admin/v1/workspaces/:workspaceId/system/server-logs` — recent captured server log
 * lines (gap A-04). Query: `level`, `sinceIso`, `contains`, `limit`, the same filters and the same
 * `readServerLogs` call as the `system_read_server_logs` chat tool. Same workspace-404 -> authorize
 * -> 403 shape as `observability-status.ts`.
 */
export type AdminServerLogsDeps = Pick<RouteDeps, "workspaceId" | "authorize">;

function queryRecord(query: Record<string, unknown>): Record<string, unknown> {
  // Express parses `?level=a&level=b` into an array; keep the first so validation sees one value.
  return Object.fromEntries(Object.entries(query).map(([key, value]) => [key, Array.isArray(value) ? value[0] : value]));
}

export function registerAdminServerLogsRoute(app: Express, deps: AdminServerLogsDeps, optional: { logs?: ServerLogSourcePort } = {}): void {
  const logs = optional.logs ?? processServerLogSource;
  app.get("/api/admin/v1/workspaces/:workspaceId/system/server-logs", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authResult = await deps.authorize({
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: "server-logs",
      });
      if (!authResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'system.read' (${authResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "system.read", reason: authResult.reason },
        });
        return;
      }

      const filters = parseServerLogFilters({ raw: queryRecord(req.query as Record<string, unknown>) });
      res.status(200).json(readServerLogs({ logs }, filters));
    } catch (err) {
      if (err instanceof ServerLogFilterError) {
        res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/system/server-logs", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express, Request, Response } from "express";
import { ForbiddenError } from "@jini-ai/cms/core";
import { ToolInputError } from "@jini-ai/core";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { getPublishTrustContext } from "#src/server/inbound/admin-http/publish-trust-auth";
import { CustomCredentialValidationError } from "#src/features/custom-credentials/index";
import { planSiteBackup, pushSiteBackup, type SiteBackupCall, type SiteBackupToolDeps } from "#src/features/site-backup/backup-service";

/**
 * @file The admin Git backup screen's two calls, `POST …/site-backups/plan` and `POST …/site-backups/push`.
 * Both run `backup-service.ts` — the same code path as `site_backup_plan`/`site_backup_push` — so the
 * permissions (`site-backup.push` AND `custom-credentials.write`, checked inside the service), the
 * private-repository rule and every refusal are the assistant's. A refusal answers 200 with the
 * service's own `{ planned|pushed: false, code, message }`, which the screen shows as is.
 */

/** How long one push POST waits on its job before answering progress. The screen re-posts the same
 *  planId at once, so this is the poll interval; re-posting waits on the SAME job (`push-jobs.ts`). */
export const PUSH_POLL_WAIT_MS = 1500;

/** The service's thrown errors as HTTP. Validation and permission errors carry no secret (see
 *  `tool-registrations.ts`'s model-facing rules); anything else gets a fixed line, never its text. */
function fail(res: Response, error: unknown): void {
  if (error instanceof ForbiddenError) { res.status(403).json({ code: "FORBIDDEN", message: "You do not have permission to back up this site." }); return; }
  if (error instanceof CustomCredentialValidationError || error instanceof ToolInputError) { res.status(400).json({ code: "INVALID_INPUT", message: error.message }); return; }
  sendAdminFailure({ res, error }, { operation: "routes/system/site-backups", code: "BACKUP_FAILED", field: "message", message: "Git backup failed. Try again." });
}

/**
 * Mounts the two routes under the admin session gate.
 * @complexity O(1) per request besides the service's own cost.
 */
export function registerAdminSiteBackupRoutes(required: { app: Express; deps: SiteBackupToolDeps }, _optional: Record<string, never> = {}): void {
  const { app, deps } = required;
  const root = "/api/admin/v1/workspaces/:workspaceId/site-backups";
  // A backup holds the whole database, so neither answer may be cached; a connected-computer
  // (publish-trust) session is refused outright, as on the share routes' admin operations.
  const gate = (req: Request, res: Response): SiteBackupCall | null => {
    res.set({ "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" });
    if (String(req.params.workspaceId) !== deps.workspaceId) { res.sendStatus(404); return null; }
    if (getPublishTrustContext(res)) { res.sendStatus(403); return null; }
    // Never aborted: a stopped wait stops the job (`push-jobs.ts`), and a closed tab must not cancel
    // a half-uploaded backup — the job finishes on its own, still one commit.
    return { input: req.body ?? {}, principal: { id: getAuthedPrincipal(res).id }, signal: new AbortController().signal };
  };
  app.post(`${root}/plan`, async (req, res) => {
    try { const call = gate(req, res); if (call) res.json(await planSiteBackup({ deps, call })); }
    catch (error) { fail(res, error); }
  });
  app.post(`${root}/push`, async (req, res) => {
    try { const call = gate(req, res); if (call) res.json(await pushSiteBackup({ deps, call }, { waitMs: PUSH_POLL_WAIT_MS })); }
    catch (error) { fail(res, error); }
  });
}

import express, { type Express, type Request, type Response } from "express";
import type { RouteDeps } from "#src/server/routes/types";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { parseSiteImportInput } from "#src/features/site-backup/import-backend";
import { SHARE_LIMITS, SiteShareRefusal } from "#src/features/site-backup/share-policy";
import { formatByteSize } from "#src/features/site-backup/sources";
import { sendAdminFailure } from "./site-share-errors.js";

type Deps = Pick<RouteDeps, "workspaceId" | "authorize" | "siteImportBackend" | "tracker">;

/** Each import boundary reports its own step while keeping provider diagnostics private. */
function importStep({ req }: { req: Request }, _options = {}): string {
  const suffix = String(req.route?.path ?? "").split("site-imports")[1] ?? "";
  const steps: Readonly<Record<string, string>> = { "GET ": "Import history", "POST ": "Archive verification", "POST /uploads": "ZIP upload", "GET /:importId/owner": "Import owner setup", "POST /:importId/owner": "Imported site creation" };
  return steps[`${req.method} ${suffix}`] ?? "Site import";
}

/** Upload stall limits: a whole-upload deadline and a per-socket idle timeout, either of which
 * destroys the request so a stalled client cannot hold the single upload lane. */
const UPLOAD_DEADLINE_MS = 120_000;
const UPLOAD_IDLE_MS = 30_000;

/** Authenticated uploads/history and principal-bound password setup, shared with tools.
 * GET returns the setup contract for the separately-owned UI; no source markup enters admin.
 * `uploadDeadlineMs`/`uploadIdleMs` default to the production stall limits; tests shorten them.
 * @complexity O(body bytes), bounded raw parsing AFTER authorization and concurrency admission.
 */
export function registerAdminSiteImportRoutes(
  required: { app: Express; deps: Deps },
  { uploadDeadlineMs = UPLOAD_DEADLINE_MS, uploadIdleMs = UPLOAD_IDLE_MS }: { uploadDeadlineMs?: number; uploadIdleMs?: number } = {},
): void {
  const { app, deps } = required;
  const root = "/api/admin/v1/workspaces/:workspaceId/site-imports";
  let uploadBusy = false;
  const fail = (res: Response, error: unknown, req: Request) => {
    const step = importStep({ req });
    if (error instanceof SiteShareRefusal) {
      res.status(error.code === "NOT_FOUND" ? 404 : 400).json({ code: error.code, message: `${step} failed: ${error.message}` });
      return;
    }
    // entity.too.large carries the parser's configured byte limit, independent of the step label.
    const { type, limit } = (error ?? {}) as { type?: string; limit: number };
    const tooLarge = type === "entity.too.large";
    // Parser refusals are bad uploads; a backend failure is an internal incident, never a 400.
    const parserMessages = new Map([
      ["encoding.unsupported", "send an uncompressed request body."],
      ["entity.parse.failed", "the request body could not be parsed."],
      ["request.aborted", "the request ended before the complete body arrived."],
      ["request.size.invalid", "the body size does not match the Content-Length header."],
    ]);
    const parserMessage = parserMessages.get(type ?? "");
    if (tooLarge || parserMessage) {
      res.status(tooLarge ? 413 : 400).json({ code: tooLarge ? "LIMIT_EXCEEDED" : "IMPORT_FAILED",
        message: `${step} failed: ${tooLarge ? `the request is over the ${formatByteSize(limit)} limit for this step.` : parserMessage}` });
      return;
    }
    sendAdminFailure({ res, error, tracker: deps.tracker }, { operation: `site-import:${step}`, code: "IMPORT_FAILED", message: `${step} failed. No existing site was changed.`, field: "message" });
  };
  const gate = async (req: Request, res: Response, permission: string) => {
    res.set({ "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "X-Robots-Tag": "noindex, nofollow", "Referrer-Policy": "no-referrer" });
    if (req.params.workspaceId !== deps.workspaceId) { res.status(404).json({ code: "NOT_FOUND", message: `${importStep({ req })} failed: this workspace is not available.` }); return false; }
    if (!await authorizeOrRespond(res, deps.authorize, { principalId: getAuthedPrincipal(res).id, workspaceId: deps.workspaceId, permission, entityType: "site-registry" })) return false;
    if (!deps.siteImportBackend) { res.status(503).json({ code: "UNAVAILABLE", message: `${importStep({ req })} requires local site creation and a configured sites home.` }); return false; }
    return true;
  };
  const requestSignal = (req: Request, res: Response) => {
    const controller = new AbortController();
    req.once("aborted", () => controller.abort());
    res.once("close", () => { if (!res.writableEnded) controller.abort(); });
    return controller.signal;
  };
  app.get(root, async (req, res) => {
    try { if (await gate(req, res, "system.read")) res.json({ imports: await deps.siteImportBackend!.list({ principalId: getAuthedPrincipal(res).id }) }); }
    catch (error) { fail(res, error, req); }
  });
  app.post(root, async (req, res) => {
    try {
      if (!await gate(req, res, "system.write")) return;
      const input = parseSiteImportInput({ input: req.body });
      const principalId = getAuthedPrincipal(res).id;
      const imported = await deps.siteImportBackend!.importBackup({ ...input, principalId }, { signal: requestSignal(req, res) });
      res.json(imported);
    } catch (error) { fail(res, error, req); }
  });
  app.post(root + "/uploads", async (req, res, next) => {
    try {
      if (!await gate(req, res, "system.write")) return;
      if (uploadBusy) { res.status(409).json({ code: "BUSY", message: "Another ZIP upload is running." }); return; }
      uploadBusy = true;
      const deadline = setTimeout(() => req.destroy(), uploadDeadlineMs);
      deadline.unref();
      req.setTimeout(uploadIdleMs, () => req.destroy());
      res.once("close", () => { clearTimeout(deadline); uploadBusy = false; });
      next();
    } catch (error) { fail(res, error, req); }
  }, (req, res, next) => {
    express.raw({ type: "application/zip", limit: SHARE_LIMITS.maxArchiveBytes, inflate: false })(req, res, error => { if (error) fail(res, error, req); else next(); });
  }, async (req, res) => {
    try {
      if (!Buffer.isBuffer(req.body)) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Upload raw application/zip bytes, not a filesystem path or base64 JSON." });
      res.status(201).json(await deps.siteImportBackend!.upload({ principalId: getAuthedPrincipal(res).id, archive: req.body }));
    } catch (error) { fail(res, error, req); }
  });
  const ownerGate = async (req: Request, res: Response) => {
    if (!rejectUnlessSessionCredential(res, { message: "Open owner setup in your signed-in browser; passwords are never submitted through an agent tool.", permission: "system.write" })) return false;
    if (!await gate(req, res, "system.write")) return false;
    deps.siteImportBackend!.get({ principalId: getAuthedPrincipal(res).id, importId: String(req.params.importId) });
    return true;
  };
  app.get(root + "/:importId/owner", async (req, res) => {
    try {
      if (!await ownerGate(req, res)) return;
      const imported = deps.siteImportBackend!.get({ principalId: getAuthedPrincipal(res).id, importId: String(req.params.importId) });
      res.json({ ...imported, ownerSetup: { method: "POST", field: "adminPassword", username: "admin", sessionRequired: true, ...(imported.hasEncryptedKeys ? { savedKeysPasswordField: "savedKeysPassword" } : {}) } });
    } catch (error) { fail(res, error, req); }
  });
  app.post(root + "/:importId/owner", async (req, res, next) => {
    try {
      if (!await ownerGate(req, res)) return;
      // Exact Origin prevents a sibling origin choosing a password with the owner's session.
      if (req.get("origin") !== req.protocol + "://" + req.get("host")) { res.status(403).json({ code: "FORBIDDEN", message: "Import owner setup failed: submit this form from the same signed-in Tovu site." }); return; }
      next();
    } catch (error) { fail(res, error, req); }
  }, (req, res, next) => {
    express.urlencoded({ extended: false, limit: "8kb" })(req, res, error => {
      if (error) fail(res, error, req);
      else next();
    });
  }, async (req, res) => {
    try {
      if (!req.body || Object.keys(req.body).some(key => !["adminPassword", "savedKeysPassword"].includes(key))) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Only the new owner password and optional saved keys password are accepted." });
      res.json(await deps.siteImportBackend!.completeOwner({ principalId: getAuthedPrincipal(res).id, importId: String(req.params.importId), adminPassword: req.body.adminPassword, ...(req.body.savedKeysPassword === undefined ? {} : { savedKeysPassword: req.body.savedKeysPassword }) }, { signal: requestSignal(req, res) }));
    } catch (error) { fail(res, error, req); }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

import type { Express, Request, Response } from "express";

import type { UUID } from "@jini-ai/core/primitives";

import {
  fingerprintSiteKeyHex,
  generateFileSiteKey,
  inspectSiteKeyMaterial,
  parseSiteKeyHex,
  revealSiteKeyMaterial,
  SiteKeyFileAlreadyExistsError,
  type SiteKeyStatus,
} from "#src/features/webhooks/index";
import {
  readSiteMetaJson,
  resolveSiteKeyFingerprint,
  siteKeyFilePathFrom,
  siteKeySourcesForSiteDir,
  type SiteKeySource,
} from "#src/features/webhooks/index";
import { hasKeyDependentData } from "#src/platform/db/key-dependent-data";
import { findSiteKeyDependentData, STORAGE_SECRET_FILENAME } from "#src/platform/site-dir/index";
import { SITE_KEY_MANAGE_PERMISSION } from "#src/features/identity/site-key-permission";
import { resolveRuntimeMode } from "#src/contracts/core/runtime-mode";
import type { SiteKeyState } from "#src/contracts/core/site-key-state";
import { createNodeAtomicFilesystem, writeJsonFileAtomic } from "@jini-ai/platform/fs";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin Secrets panel → Site key tab's backend: `GET`, `POST .../generate`, and
 * `POST .../reveal`, under `/api/admin/v1/workspaces/:workspaceId/system/site-key`.
 *
 * ## What this manages
 *
 * The generated-file half of `EnvOrFileKeyring`'s site-key resolution (`features/webhooks/
 * keyring.env.ts`) — the file at `defaultSiteKeyFilePath()` a keyring constructed with
 * `allowFileFallback: true` falls back to when `TOVU_SITE_KEY` is unset.
 *
 * ## 2026-09-09 durability fix — this now genuinely works in production, with one disclosed gap
 *
 * Until this fix, a generated file could never help production: the boot gate checked only the
 * env var, the default path resolved under the container's ephemeral rootfs (wiped every
 * redeploy), and `siteAssistantSecretKeyring` refused to read a file at all. All three are fixed:
 * `defaultSiteKeyFilePath()` is mode-aware (the durable data-volume-backed `<cwd>/sites/.tovu/
 * integrations-site-key.hex` in production), `hasMissingSiteKey`
 * (`runtime/boot/boot-readiness-gate.ts`) now accepts a valid file too, and
 * `siteAssistantSecretKeyring` (`composition/deps.ts`) now reads (but never auto-generates) one.
 *
 * The one remaining, DISCLOSED gap: `newsletterKeyring` (webhook signing, newsletter unsubscribe
 * tokens) still requires the env var in production — its `allowFileFallback: runtimeMode !==
 * "production"` construction is deliberately UNCHANGED (a committed regression test pins it, and
 * this pass's dispatch scoped the production fix to the credential-sealing keyring specifically).
 * So: generating a key here in production DOES now protect every real stored credential (BYOK,
 * publish/source-control/custom creds, media-provider secrets), but does NOT cover webhook
 * signing / newsletter tokens unless the env var is also set. `SiteKeyTab.tsx`'s scope notice
 * states this split plainly rather than claiming uniform coverage.
 *
 * ## The accepted security tradeoff — read this before "fixing" the asymmetry away
 *
 * A generated key file now lives on the SAME data volume as `content.db`. Someone who obtains a
 * volume snapshot/backup gets both the ciphertext and the key that opens it — the "leaked backup
 * alone is not enough" defense ADR-058 §9 described no longer holds once a file exists. This is an
 * OWNER-APPROVED, DOCUMENTED cost of making the install self-contained (no host `secrets set`
 * required), not an oversight. See `composition/deps.ts`'s `siteAssistantSecretKeyring`
 * construction comment and `ADS-memory/reports/2026-09-09-security-site-key.md` for the full
 * writeup.
 *
 * ## Visibility — reveal, not just fingerprint
 *
 * `POST .../reveal` returns the raw key value (whichever source is currently active). This is a
 * deliberate supersession of an earlier, narrower "fingerprint-only, shown once at creation" brief
 * — the owner's own words: "i want that token to be visible to admins or else when it breaks they
 * have no idea whats going on." `GET` (status) NEVER includes the value; reveal is its own
 * explicit, separately-permission-gated action a caller must invoke on purpose. No audit-log
 * write on reveal — no general-purpose sensitive-read audit mechanism exists anywhere in this
 * codebase to hook into (checked; not built here per the dispatch's own "if none exists, do not
 * build one" instruction).
 *
 * `admin.security.site-key.manage`-gated on every verb (`features/identity/
 * site-key-permission.ts`) — a narrower trust boundary than ordinary content admin, since this
 * is the one screen that can both mint AND reveal the key protecting every other credential.
 *
 * ## Last-resort recovery (2026-09-29, design 2026-09-14 §4.3/§4.6)
 *
 * For a locked site (`missing-with-data`, `mismatch`): `POST .../import` ("Paste your old token")
 * installs a pasted token only after it opens a real sealed value (or `.storage-secret.json`, or
 * matches the stamp), and first moves anything saved under the key in place meanwhile onto it, so
 * nothing is stranded. `GET .../start-fresh` previews "Start fresh" (what goes, which webhooks get a
 * new signing secret); `POST .../start-fresh` with `{confirm: "START FRESH"}` takes a restore point,
 * removes only what the kept (or new) key cannot open, and installs that key. Neither echoes the key.
 *
 * `POST .../generate` never overwrites or rotates, and never mints over sealed data (2026-09-29): it
 * runs the site-key writer boot runs (`site-key-ensure.ts`'s `ensureSiteKeyForSite`, injected by the
 * composition root so this file never imports it). A working key is reported as `already-active`; a
 * missing per-site key is adopted from whichever source still holds the key `.site-meta.json` names
 * (`recovered`); a key is minted only for a site with no sealed data (`created`); otherwise 409 with
 * a stable code and nothing written — see {@link generateSiteKey}. A real rotate/replace flow is
 * intentionally NOT built here.
 *
 * ## Site-key plan §A3b — site-aware sources
 *
 * Every verb now resolves this SITE's own ordered source list ({@link resolveSiteKeySources}:
 * `site-key-sources.ts`'s `siteKeySourcesForSiteDir`, keyed off `deps.siteBinding.dir`'s
 * `.site-meta.json` — the same composed helper `site-backup/tool-registrations.ts`'s
 * `unreadableCredentialMessage` reuses, so the two site-aware callers can never drift apart)
 * instead of the module-level env-then-legacy-default precedence `inspectSiteKeyMaterial`'s own
 * defaults still use. In local mode with a resolvable `siteKeyId` this prefers the per-site file
 * (`~/.tovu/site-keys/<id>.hex`, A.1) over the legacy shared file, and `generate` fills THAT
 * per-site file rather than the one legacy path. Production, which has no per-site file at all,
 * keeps the env-var/volume-file behavior (`siteKeySources` drops the per-site candidate there).
 *
 * `GET`'s response also carries a `state` field derived from the resolved status — the full
 * site-key-plan §A.6 5-state set ({@link SiteKeyState}: `"active" | "missing" |
 * "missing-with-data" | "mismatch" | "invalid"`), computed by {@link siteKeyState}.
 *
 * ## 2026-09-14 hardening — session-only, `no-store`
 *
 * Every verb, including `GET` status, now refuses an `api_key` credential
 * (`rejectUnlessSessionCredential` in `dev-auth.ts`, shared with `routes/api-keys/deps.ts`'s
 * `rejectApiKeyCredential`) before the workspace/permission checks run. `SITE_KEY_MANAGE_PERMISSION`
 * can be reached by any policy holding `admin.integrations.manage` (see that permission's own file
 * header) and by any API key whose issuance snapshot carries it; without this gate, a leaked API key
 * could reveal the value that decrypts every other stored credential. Reveal and generate responses
 * also now set `Cache-Control: no-store`, since both carry the raw key value.
 */
export type AdminSiteKeyDeps = Pick<
  RouteDeps,
  "workspaceId" | "authorize" | "siteBinding" | "contentKernel" | "dbOps" | "restorePointsRepo" | "idGen" | "clock" | "webhookSubscriptionRepo"
>;

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/system/site-key";

/**
 * This site's own ordered source list, plus the file `generate` should target — computed fresh
 * per request (never cached) so every verb agrees about which sources and which target file are
 * THIS site's own, not the legacy global default. Exported so it can be unit-tested directly
 * against a temp `siteBinding.dir` without standing up Express/HTTP.
 *
 * @param env - defaults to `process.env`; test-injected so a suite never depends on real env vars.
 * @complexity O(1) `.site-meta.json` read plus `siteKeySources`' fixed-size ordering.
 */
export function resolveSiteKeySources(
  deps: Pick<AdminSiteKeyDeps, "siteBinding">,
  env: NodeJS.ProcessEnv = process.env
): { sources: SiteKeySource[]; keyFilePath: string | undefined } {
  const mode = resolveRuntimeMode({ env });
  const sources = siteKeySourcesForSiteDir({ siteDir: deps.siteBinding.dir, mode, env, home: homedir(), cwd: process.cwd() });
  return { sources, keyFilePath: siteKeyFilePathFrom(sources) };
}

export interface SiteKeyStateInput {
  readonly active: boolean;
  readonly invalid?: boolean;
  readonly reason?: string;
  /** The currently-resolved key material's own fingerprint (only meaningful when `active`). */
  readonly fingerprint?: string;
  /** `.site-meta.json`'s stamped `siteKeyFingerprint` ({@link resolveSiteKeyFingerprint}) —
   *  `undefined` when nothing has been stamped yet (never treated as a mismatch). */
  readonly metaFingerprint?: string;
  /** Whether this site's store holds data only a site key could decrypt or verify
   *  ({@link siteHasKeyDependentData}) — only meaningful when neither `active` nor `invalid`. */
  readonly hasKeyDependentData: boolean;
}

/**
 * `GET`'s `state` banner field (site-key plan §A.6), derived from an already-computed
 * {@link SiteKeyStatus} plus the two site-key-plan-specific inputs {@link SiteKeyStateInput}
 * carries beyond it.
 *
 * `invalid` wins outright — a source was found but fails hex validation, regardless of what a
 * stale `.site-meta.json` stamp or a `content.db` scan would otherwise say. Otherwise: `active`
 * with a stamped fingerprint that disagrees with the resolved key's own fingerprint is `mismatch`
 * (the physical key file was substituted after the stamp was written); `active` with no stamp yet,
 * or a stamp that agrees, is plain `active`. Not active: `missing-with-data` when this site's
 * store holds key-dependent data (a materially more urgent banner — something the operator
 * saved is stuck behind a key that no longer resolves), otherwise plain `missing`.
 *
 * @complexity O(1) — a fixed sequence of comparisons over already-computed inputs; no I/O.
 */
export function siteKeyState(input: SiteKeyStateInput): SiteKeyState {
  if (input.invalid) return "invalid";
  if (input.active) {
    return input.metaFingerprint !== undefined && input.metaFingerprint !== input.fingerprint
      ? "mismatch"
      : "active";
  }
  return input.hasKeyDependentData ? "missing-with-data" : "missing";
}

/** {@link siteKeyState}'s `hasKeyDependentData` input for the GET handler, on every storage kind
 *  (ADR-067). A sealed `.storage-secret.json` counts. Otherwise the running site's own open store
 *  (`deps.contentKernel`) is scanned — a PGlite data dir this process owns cannot be opened a second
 *  time — and only without one does this fall back to `findSiteKeyDependentData`, the same scan
 *  `ensureSiteKey` runs at boot. A failed scan counts as "has data", as that function's does.
 *
 * @complexity O(1) `existsSync` plus one {@link hasKeyDependentData} scan.
 */
async function siteHasKeyDependentData(deps: AdminSiteKeyDeps): Promise<boolean> {
  const siteDir = deps.siteBinding.dir;
  if (existsSync(join(siteDir, STORAGE_SECRET_FILENAME))) return true;
  if (deps.contentKernel === undefined) return findSiteKeyDependentData(siteDir);
  try {
    return await hasKeyDependentData(deps.contentKernel);
  } catch {
    return true;
  }
}

/**
 * Re-stamps `.site-meta.json`'s `siteKeyFingerprint` to `fingerprint` after production `generate`
 * mints a new key (site-key plan §A.6; locally `ensureSiteKey` stamps its own) — mirrors `ensureSiteKey`'s own `withFingerprintReconciliation`
 * "present and equal → nothing written" case (`site-key-ensure.ts`): a missing `.site-meta.json`
 * (no commit marker at all — a legacy or unrepaired site) is left alone rather than fabricated, and
 * an already-matching stamp is left untouched rather than rewritten for no reason. Every other
 * field in the object survives unchanged (the atomic write spreads the parsed object first).
 *
 * @complexity O(1) — one read, at most one atomic write.
 */
function stampSiteKeyFingerprint(siteDir: string, fingerprint: string): void {
  const meta = readSiteMetaJson(siteDir);
  if (meta === undefined || meta.siteKeyFingerprint === fingerprint) return;
  writeJsonFileAtomic({ filePath: join(siteDir, ".site-meta.json"), data: { ...meta, siteKeyFingerprint: fingerprint }, fs: createNodeAtomicFilesystem({}, {}) }, {});
}

/** Shared workspace-path-param + permission check every verb below performs first — same
 *  two-step shape `publish-credentials.ts`'s `rejectUnlessAuthorized` uses. Returns `true` (and
 *  has already written the response) iff the caller should stop. */
async function rejectUnlessAuthorized(req: Request, res: Response, deps: AdminSiteKeyDeps): Promise<boolean> {
  // Checked first, before the workspace/permission checks below, so an api_key caller — even one
  // whose snapshot holds SITE_KEY_MANAGE_PERMISSION — learns nothing beyond "this credential type
  // is not permitted here." Same rule and same shared guard `routes/api-keys/deps.ts`'s
  // `rejectApiKeyCredential` uses for api-key issuance/revocation: the value this route family
  // guards (the key that decrypts every other stored credential) must stay reachable only by a real
  // admin session, never by a machine credential a leaked key could replay.
  if (
    !rejectUnlessSessionCredential(res, {
      message: "api-key credentials may not read or manage the site key; use an admin session",
      permission: SITE_KEY_MANAGE_PERMISSION,
    })
  ) {
    return true;
  }
  if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
    res.status(404).json({ error: "workspace was not found" });
    return true;
  }
  const principal = getAuthedPrincipal(res);
  return !(await authorizeOrRespond(res, deps.authorize, {
    principalId: principal.id,
    permission: SITE_KEY_MANAGE_PERMISSION,
    workspaceId: deps.workspaceId,
  }));
}

export function registerAdminSiteKeyRoutes(app: Express, deps: AdminSiteKeyDeps, siteKey: SiteKeyKeyWriter): void {
  app.get(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps)) return;
    const { sources } = resolveSiteKeySources(deps);
    const status = inspectSiteKeyMaterial({ sources });
    const state = siteKeyState({
      active: status.active,
      invalid: status.invalid,
      reason: status.reason,
      fingerprint: status.fingerprint,
      metaFingerprint: status.active ? resolveSiteKeyFingerprint({ siteDir: deps.siteBinding.dir }) : undefined,
      hasKeyDependentData:
        !status.active && !status.invalid ? await siteHasKeyDependentData(deps) : false,
    });
    res.status(200).json({ ...status, state, runtimeMode: resolveRuntimeMode() });
  });

  app.post(`${BASE_PATH}/reveal`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps)) return;
    const { sources } = resolveSiteKeySources(deps);
    const reveal = revealSiteKeyMaterial({ sources });
    // The raw key value goes out in this body — never let a shared/browser cache retain it.
    res.set("Cache-Control", "no-store");
    res.status(200).json({ ...reveal, runtimeMode: resolveRuntimeMode() });
  });

  app.post(`${BASE_PATH}/generate`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps)) return;
    try {
      const result = await generateSiteKey(deps, siteKey);
      // The raw key is never in this body (sol finding 3-2, 2026-09-16): the admin controller
      // (`use-site-key.hooks.ts`'s `generate()`) reads only fingerprint/keyFilePath/runtimeMode.
      // Reveal (above) stays the one, explicit place this route family discloses the value.
      res.set("Cache-Control", "no-store");
      res.status(result.status).json({ ...result.body, runtimeMode: resolveRuntimeMode() });
    } catch (err) {
      if (err instanceof SiteKeyFileAlreadyExistsError) {
        res.status(409).json({ error: "ALREADY_EXISTS", detail: err.message });
        return;
      }

      sendAdminFailure({ res, error: err }, { operation: "routes/system/site-key", code: "INTERNAL_ERROR" });
    }
  });

  app.post(`${BASE_PATH}/import`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps)) return;
    await respondWithRecovery(res, () => importSiteKey(deps, siteKey, { siteKey: (req.body as { siteKey?: unknown } | undefined)?.siteKey, actorId: getAuthedPrincipal(res).id }));
  });

  app.get(`${BASE_PATH}/start-fresh`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps)) return;
    await respondWithRecovery(res, () => previewStartFresh(deps, siteKey));
  });

  app.post(`${BASE_PATH}/start-fresh`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res, deps)) return;
    const confirm = (req.body as { confirm?: unknown } | undefined)?.confirm;
    await respondWithRecovery(res, () => startFresh(deps, siteKey, { confirm, actorId: getAuthedPrincipal(res).id }));
  });
}

/** Sends a recovery result `no-store` (the request carried a token; never let a cache keep either). */
async function respondWithRecovery(res: Response, run: () => Promise<RouteResult>): Promise<void> {
  res.set("Cache-Control", "no-store");
  try {
    const result = await run();
    res.status(result.status).json({ ...result.body, runtimeMode: resolveRuntimeMode() });
  } catch (err) {
    sendAdminFailure({ res, error: err }, { operation: "routes/system/site-key", code: "INTERNAL_ERROR" });
  }
}

/** The site-key writer's result, as far as `generate` reads it — `site-key-ensure.ts`'s
 *  `EnsureSiteKeyResult`, restated structurally because nothing under `server/inbound/**` may import
 *  that module (`no-site-key-ensure-import.boundary.test.ts`). */
export interface SiteKeyEnsureOutcome {
  readonly action: "noop" | "adopt" | "mint" | "refuse" | "invalid" | "mismatch" | "production-noop";
  readonly perSiteFilePath?: string;
  readonly fingerprint?: string;
}

/** How many of the site's sealed values open under a key held in memory, and whether its
 *  `.storage-secret.json` does — `composition/site-key-recovery.ts`'s `checkKey`, restated. */
export interface SiteKeyKeyCheck {
  readonly sealed: number;
  readonly opens: number;
  readonly storageSecret: "absent" | "opens" | "locked";
  readonly metadataOnly?: number;
  readonly legacy?: number;
}

/** The site's store plus a candidate key, as the recovery helpers take it. */
export interface SiteKeyStoreInput {
  readonly siteDir: string;
  readonly contentKernel?: AdminSiteKeyDeps["contentKernel"];
  readonly hex: string;
}

/** `site-key-ensure.ts`'s `installSiteKey` result, restated structurally (see {@link SiteKeyEnsureOutcome}). */
export type SiteKeyInstallOutcome =
  | { readonly outcome: "installed"; readonly keyFilePath: string; readonly fingerprint: string }
  | { readonly outcome: "env-key-set" };

/** What the key verbs need from the composition root: `site-key-ensure.ts`'s writers (boot's
 *  `ensureSiteKeyForSite`, recovery's `installSiteKey`/`mintSiteKeyHex`) and the sealed-value checks
 *  in `composition/site-key-recovery.ts`. `undefined` from the writers means no `siteKeyId`
 *  resolves for the site. */
export interface SiteKeyKeyWriter {
  readonly ensureSiteKeyForSite: (input: {
    siteDir: string;
    findSiteKeyDependentData: (siteDir: string) => Promise<boolean>;
  }) => Promise<SiteKeyEnsureOutcome | undefined>;
  readonly checkKey: (input: SiteKeyStoreInput) => Promise<SiteKeyKeyCheck>;
  readonly discardNotOpening: (input: SiteKeyStoreInput) => Promise<{ discarded: number; kept: number }>;
  readonly resealFrom: (input: SiteKeyStoreInput & { previousHex: string }) => Promise<{ resealed: number; unreadable: number }>;
  readonly installSiteKey: (input: { siteDir: string; hex: string }) => SiteKeyInstallOutcome | undefined;
  readonly mintSiteKeyHex: () => string;
}

type GenerateOutcome = "already-active" | "recovered" | "created";

interface RouteResult {
  readonly status: number;
  readonly body: Record<string, unknown>;
}

type GenerateResult = RouteResult;

/** Plain-words refusals — the key the site's data needs is not here, so nothing is written. */
const REFUSALS = {
  KEY_DEPENDENT_DATA:
    "This site has saved credentials locked with a site key that is not on this computer. A new site key could not open them, so none was created. Put the original site key back to unlock them.",
  KEY_MISMATCH:
    "The site key on this computer is not the one this site's saved credentials were locked with, so nothing was changed. Put the original site key back to unlock them.",
  KEY_INVALID: "A site key is set on this computer but is not a valid key, so nothing was changed. Fix or remove it, then try again.",
  SITE_META_UNREADABLE: "This site's .site-meta.json cannot be read. Repair this site first; no site key was written.",
  SITE_KEY_INVALID: "That is not a site key. A site key is 64 characters of 0-9 and a-f.",
  SITE_KEY_DOES_NOT_OPEN: "That site key does not open this site's saved credentials. Nothing was changed.",
  ENV_KEY_SET: "A different site key is set in this server's environment and overrides the key file, so nothing was changed. Change it there instead.",
  RESTORE_POINT_UNAVAILABLE: "A restore point can't be made for this site's database right now, so nothing was changed.",
  STORAGE_SECRET_LOCKED:
    "This site's database connection is locked with the old site key, and starting fresh can't replace it. Paste your old site key instead. Nothing was changed.",
  CONFIRMATION_REQUIRED: "Type START FRESH to confirm. Nothing was changed.",
} as const;

function refusal(code: keyof typeof REFUSALS, status = 409): RouteResult {
  return { status, body: { error: code, detail: REFUSALS[code] } };
}

function success(outcome: GenerateOutcome, fingerprint: string, keyFilePath: string): GenerateResult {
  return { status: outcome === "created" ? 201 : 200, body: { outcome, fingerprint, keyFilePath } };
}

/**
 * `POST .../generate`: makes sure this site has the RIGHT key, never a second one. Runs the same
 * rules boot runs (`ensureSiteKeyForSite`): a working per-site key that matches the stamp is left
 * alone (`already-active`); a missing per-site key is filled from whichever source holds the key the
 * site's data was sealed with (`recovered`); a new key is minted only when the site has no sealed
 * data (`created`). With sealed data and no matching key it refuses (409) and writes nothing — the
 * stamp in `.site-meta.json` is the only record of which key the data needs.
 *
 * Production has no per-site file (site-key plan §A.1), so there the route keeps its env/volume-file
 * behavior, with the same two guards: an active key is reported, not replaced, and no key is minted
 * over sealed data.
 *
 * @throws {SiteKeyFileAlreadyExistsError} production only, when the volume file appears mid-request.
 * @complexity O(1) file reads plus at most one key-dependent-data scan.
 */
async function generateSiteKey(deps: AdminSiteKeyDeps, siteKey: SiteKeyKeyWriter): Promise<GenerateResult> {
  const hasData = (): Promise<boolean> => siteHasKeyDependentData(deps);
  const mode = resolveRuntimeMode();
  // Refuse before the shared writer derives metadata, which re-reads an existing corrupt file.
  if (mode !== "production" && existsSync(join(deps.siteBinding.dir, ".site-meta.json")) && readSiteMetaJson(deps.siteBinding.dir) === undefined) {
    return refusal("SITE_META_UNREADABLE");
  }
  const ensured = await siteKey.ensureSiteKeyForSite({ siteDir: deps.siteBinding.dir, findSiteKeyDependentData: hasData });
  if (mode === "production" || ensured?.action === "production-noop") return generateProductionSiteKey(deps, hasData);
  if (ensured === undefined) return refusal("SITE_META_UNREADABLE");
  return ensuredSiteKeyResult({ ensured: { ...ensured, action: ensured.action } });
}

function ensuredSiteKeyResult({ ensured }: { ensured: SiteKeyEnsureOutcome & { action: Exclude<SiteKeyEnsureOutcome["action"], "production-noop"> } }, _options = {}): GenerateResult {
  const { action, fingerprint, perSiteFilePath } = ensured;
  switch (action) {
    case "noop":
    case "adopt":
    case "mint":
      if (fingerprint === undefined || perSiteFilePath === undefined) throw new Error(`site key '${action}' carried no fingerprint or path`);
      return success(({ noop: "already-active", adopt: "recovered", mint: "created" } as const)[action], fingerprint, perSiteFilePath);
    case "refuse":
      return refusal("KEY_DEPENDENT_DATA");
    case "mismatch":
      return refusal("KEY_MISMATCH");
    case "invalid":
      return refusal("KEY_INVALID");
    // Preserve the undefined fallback for runtime inputs outside this exhaustive union.
    default: return undefined as never;
  }
}

/** {@link generateSiteKey}'s production branch: the env var or the durable-volume file.
 *  @complexity O(1) file reads plus at most one key-dependent-data scan. */
async function generateProductionSiteKey(deps: AdminSiteKeyDeps, hasData: () => Promise<boolean>): Promise<GenerateResult> {
  const { sources, keyFilePath } = resolveSiteKeySources(deps);
  const status = inspectSiteKeyMaterial({ sources });
  if (status.active && status.fingerprint !== undefined) return success("already-active", status.fingerprint, status.keyFilePath);
  if (status.invalid) return refusal("KEY_INVALID");
  if (await hasData()) return refusal("KEY_DEPENDENT_DATA");
  if (keyFilePath === undefined) return refusal("SITE_META_UNREADABLE");
  const generated = generateFileSiteKey({ keyFilePath });
  stampSiteKeyFingerprint(deps.siteBinding.dir, generated.fingerprint);
  return success("created", generated.fingerprint, generated.keyFilePath);
}

/** Takes and records a restore point before recovery changes the database (pattern:
 *  `features/database/gated-hooks.ts`'s migrate-forward). `undefined` when this site's database
 *  cannot take one. @complexity O(1) plus one capture and one save. */
async function takeRestorePoint(deps: AdminSiteKeyDeps, actorId: string, trigger: string): Promise<string | undefined> {
  const capabilities = await deps.dbOps.getCapabilities();
  if (capabilities.restorePoint.costClass === "unavailable") return undefined;
  const captured = await deps.dbOps.captureRestorePoint({ scopeId: deps.workspaceId });
  const restorePointId = deps.idGen.newId();
  await deps.restorePointsRepo.save({
    restorePointId,
    idempotencyKey: restorePointId,
    trigger,
    createdAt: deps.clock.nowIso(),
    createdBy: actorId,
    costClass: capabilities.restorePoint.costClass,
    kind: capabilities.restorePoint.kind,
    watermarkAtCapture: captured.watermarkAtCapture,
    artifactRef: captured.artifactRef,
  });
  return restorePointId;
}

function keyOpensSite(required: { check: SiteKeyKeyCheck; siteDir: string; fingerprint: string }, _options = {}): boolean {
  const { check, siteDir, fingerprint } = required;
  return check.opens > 0 || check.storageSecret === "opens" || resolveSiteKeyFingerprint({ siteDir }) === fingerprint;
}

async function resealForImport(required: {
  deps: AdminSiteKeyDeps; siteKey: SiteKeyKeyWriter; store: SiteKeyStoreInput;
  current: { hex?: string; fingerprint?: string }; fingerprint: string; check: SiteKeyKeyCheck; actorId: string;
}, _options = {}): Promise<RouteResult | { restorePointId?: string; resealed: number }> {
  const { deps, siteKey, store, current, fingerprint, check, actorId } = required;
  if ((current.hex !== undefined && current.fingerprint !== fingerprint) || (check.legacy ?? 0) > 0) {
    const restorePointId = await takeRestorePoint(deps, actorId, "site-key-import");
    if (restorePointId === undefined) return refusal("RESTORE_POINT_UNAVAILABLE");
    const { resealed } = await siteKey.resealFrom({ ...store, previousHex: current.hex ?? store.hex });
    return { restorePointId, resealed };
  }
  return { resealed: 0 };
}

/**
 * `POST .../import` — "Paste your old token". The token is installed only once it is proven to be
 * this site's: it opens at least one sealed value or the sealed connection string, or it is the key
 * `.site-meta.json` is stamped with. Values saved meanwhile under the key currently in place are
 * moved onto the token first (after a restore point), so switching strands nothing. When no other
 * key is in place nothing in the database changes, so no restore point is needed.
 *
 * @complexity one sealed-value scan, plus one re-seal pass when another key is in place.
 */
async function importSiteKey(deps: AdminSiteKeyDeps, siteKey: SiteKeyKeyWriter, input: { siteKey: unknown; actorId: string }): Promise<RouteResult> {
  const parsed = parseSiteKeyHex(typeof input.siteKey === "string" ? input.siteKey : "");
  if (!parsed.ok) return refusal("SITE_KEY_INVALID", 400);
  const siteDir = deps.siteBinding.dir;
  const fingerprint = fingerprintSiteKeyHex(parsed.hex);
  const current = revealSiteKeyMaterial({ sources: resolveSiteKeySources(deps).sources });
  if (current.source === "env" && current.fingerprint !== fingerprint) return refusal("ENV_KEY_SET");
  const store = { siteDir, contentKernel: deps.contentKernel, hex: parsed.hex };
  const check = await siteKey.checkKey(store);
  const proven = keyOpensSite({ check, siteDir, fingerprint });
  if (!proven) return refusal("SITE_KEY_DOES_NOT_OPEN");

  const recovery = await resealForImport({ deps, siteKey, store, current, fingerprint, check, actorId: input.actorId });
  if ("status" in recovery) return recovery;
  const { restorePointId, resealed } = recovery;
  const installed = siteKey.installSiteKey({ siteDir, hex: parsed.hex });
  if (installed === undefined) return refusal("SITE_META_UNREADABLE");
  if (installed.outcome === "env-key-set") return refusal("ENV_KEY_SET");
  return { status: 200, body: { outcome: "unlocked", fingerprint, keyFilePath: installed.keyFilePath, resealed, restorePointId } };
}

interface AffectedWebhook {
  readonly label: string;
  readonly targetUrl: string;
}

interface StartFreshPlan {
  readonly hex: string;
  readonly check: SiteKeyKeyCheck;
  readonly affectedWebhooks: readonly AffectedWebhook[];
}

/** The key "Start fresh" ends with (the working key in place, else a new one), what it opens, and
 *  which webhooks' signing secrets change (all of them unless that key is the stamped one). A
 *  refusal when an env var holds an unusable key (it would outrank anything written).
 *  @complexity one sealed-value scan plus one webhook list. */
async function planStartFresh(deps: AdminSiteKeyDeps, siteKey: SiteKeyKeyWriter): Promise<StartFreshPlan | RouteResult> {
  const current = revealSiteKeyMaterial({ sources: resolveSiteKeySources(deps).sources });
  if (current.source === "env" && current.hex === undefined) return refusal("ENV_KEY_SET");
  const hex = current.hex ?? siteKey.mintSiteKeyHex();
  const check = await siteKey.checkKey({ siteDir: deps.siteBinding.dir, contentKernel: deps.contentKernel, hex });
  if (check.storageSecret === "locked") return refusal("STORAGE_SECRET_LOCKED");
  const keepsSecrets = resolveSiteKeyFingerprint({ siteDir: deps.siteBinding.dir }) === fingerprintSiteKeyHex(hex);
  const webhooks = keepsSecrets ? [] : await deps.webhookSubscriptionRepo.listByWorkspace({ workspaceId: deps.workspaceId as UUID });
  return { hex, check, affectedWebhooks: webhooks.map((webhook) => ({ label: webhook.label, targetUrl: webhook.targetUrl })) };
}

function isRouteResult(value: StartFreshPlan | RouteResult): value is RouteResult {
  return "status" in value;
}

/** The confirm step's plain sentence. @complexity O(W) in the affected webhooks. */
export function startFreshDetail(removes: number, affectedWebhooks: readonly AffectedWebhook[]): string {
  const noun = removes === 1 ? "credential" : "credentials";
  const removal = removes === 0
    ? "Every saved credential can be unlocked; nothing will be removed."
    : `${removes} saved ${noun} can't be unlocked and will be removed.`;
  if (affectedWebhooks.length === 0) return removal;
  const names = affectedWebhooks.map((webhook) => `${webhook.label} (${webhook.targetUrl})`).join(", ");
  return `${removal} These webhooks get a new signing secret, so update their receivers: ${names}.`;
}

/** `GET .../start-fresh` — what confirming would do. Changes nothing. */
async function previewStartFresh(deps: AdminSiteKeyDeps, siteKey: SiteKeyKeyWriter): Promise<RouteResult> {
  const plan = await planStartFresh(deps, siteKey);
  if (isRouteResult(plan)) return plan;
  const removes = plan.check.sealed - plan.check.opens;
  return { status: 200, body: { removes, metadataOnly: plan.check.metadataOnly ?? 0, affectedWebhooks: plan.affectedWebhooks, detail: startFreshDetail(removes, plan.affectedWebhooks) } };
}

/**
 * `POST .../start-fresh` with `{confirm: "START FRESH"}` — the last resort when the old token is
 * gone. Keeps the working key in place (or mints one), takes a restore point, removes only the
 * sealed values that key cannot open, and installs it as this site's key. The response names the
 * webhooks whose signing secrets changed.
 *
 * @complexity one sealed-value scan for the plan, one for the discard.
 */
async function startFresh(deps: AdminSiteKeyDeps, siteKey: SiteKeyKeyWriter, input: { confirm: unknown; actorId: string }): Promise<RouteResult> {
  if (input.confirm !== "START FRESH") return refusal("CONFIRMATION_REQUIRED", 400);
  const plan = await planStartFresh(deps, siteKey);
  if (isRouteResult(plan)) return plan;
  const restorePointId = await takeRestorePoint(deps, input.actorId, "site-key-start-fresh");
  if (restorePointId === undefined) return refusal("RESTORE_POINT_UNAVAILABLE");
  const { discarded, kept } = await siteKey.discardNotOpening({ siteDir: deps.siteBinding.dir, contentKernel: deps.contentKernel, hex: plan.hex });
  const installed = siteKey.installSiteKey({ siteDir: deps.siteBinding.dir, hex: plan.hex });
  if (installed === undefined) return refusal("SITE_META_UNREADABLE");
  if (installed.outcome === "env-key-set") return refusal("ENV_KEY_SET");
  return {
    status: 200,
    body: { outcome: "started-fresh", fingerprint: installed.fingerprint, keyFilePath: installed.keyFilePath, discarded, kept, restorePointId, affectedWebhooks: plan.affectedWebhooks },
  };
}

import type { Request, RequestHandler, Response } from "express";
import type { SiteShareBackend } from "#src/features/site-backup/share-backend";
import type { Tracker } from "@jini-ai/diagnostics/observability";
import { sendSiteShareFailure } from "./site-share-errors.js";
import { getAuthedPrincipal, rejectUnlessSessionCredential } from "#src/server/inbound/admin-http/dev-auth";
import { getPublishTrustContext } from "#src/server/inbound/admin-http/publish-trust-auth";
import { isSameOriginAdminWrite } from "#src/features/agent-plugins/admin-surfaces/same-origin";

interface SavedKeysOwnerDeps {
  workspaceId: string;
  ownerPrincipalId: PromiseLike<string> | string;
}
/** Shared by opt-in export and explicit reveal. Owner identity is stronger than general backup
 * permission; a connected-computer, tool or API credential must never reveal an archive password.
 * @complexity O(1) checks, before any share lookup or secret open.
 */
export async function requireSavedKeysOwnerSession(required: { req: Request; res: Response; deps: SavedKeysOwnerDeps }, _optional: Record<string, never> = {}): Promise<boolean> {
  const { req, res, deps } = required;
  res.set({ "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer" });
  if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ code: "NOT_FOUND", message: "Saved keys access failed: this workspace is not available." }); return false; }
  if (!rejectUnlessSessionCredential(res, { message: "Use the site owner's signed-in browser for saved keys.", permission: "site-backup.push" })) return false;
  if (getPublishTrustContext(res) || getAuthedPrincipal(res).id !== await deps.ownerPrincipalId) { res.status(403).json({ code: "FORBIDDEN", message: "Saved keys access requires the site owner’s signed-in browser on this Tovu site." }); return false; }
  const sameOrigin = isSameOriginAdminWrite({ origin: req.get("origin"), host: req.get("host"), fetchSite: req.get("sec-fetch-site") });
  if (!sameOrigin || req.get("origin") !== req.protocol + "://" + req.get("host")) { res.status(403).json({ code: "FORBIDDEN", message: "Saved keys access requires the site owner’s signed-in browser on this Tovu site." }); return false; }
  return true;
}

/** Register on POST …/site-shares/:shareId/password after the existing session middleware.
 * The backend owns record/workspace lookup and password opening; this boundary adds browser-only
 * owner and CSRF checks. Every outcome, including denial, remains non-cacheable.
 * @example app.post(`${root}/:shareId/password`, createSiteSharePasswordHandler({ deps }));
 */
export function createSiteSharePasswordHandler(required: { deps: SavedKeysOwnerDeps & { siteShareBackend?: Pick<SiteShareBackend, "revealPassword">; tracker?: Pick<Tracker, "error"> } }, _optional: Record<string, never> = {}): RequestHandler {
  return async (req, res) => {
    try {
      if (!await requireSavedKeysOwnerSession({ req, res, deps: required.deps })) return;
      const backend = required.deps.siteShareBackend;
      if (!backend) { res.status(503).json({ code: "UNAVAILABLE", message: "Export password lookup failed: saved keys are unavailable." }); return; }
      res.json(await backend.revealPassword({ principalId: getAuthedPrincipal(res).id, shareId: String(req.params.shareId) }));
    } catch (error) {
      sendSiteShareFailure({ res, error, tracker: required.deps.tracker }, { password: true });
    }
  };
}

import { createSiteSharePasswordHandler } from "./site-share-password.js";
import { sendSiteShareFailure } from "./site-share-errors.js";
import express, { type Express, type Request, type Response } from "express";
import type { RouteDeps } from "#src/server/routes/types";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { getPublishTrustContext, publishTrustAuthorizeFor } from "#src/server/inbound/admin-http/publish-trust-auth";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { parseStaticExportInput } from "#src/features/site-backup/static-export-selection";
import { SHARE_LIMITS, SiteShareRefusal } from "#src/features/site-backup/share-policy";
import { SHARE_TOKEN, SHARE_FILE } from "#src/features/site-backup/share-registry";
import { SHARE_DOWNLOAD_HEADERS, receiveSiteShareArtifact } from "#src/features/site-backup/share-service";

export function readShareInput({ body }: { body: unknown }, _options = {}): { jobId?: string } {
  const raw = body ?? {};
  if (typeof raw !== "object" || raw === null || Array.isArray(raw) || Object.keys(raw).some(key => key !== "jobId")) {
    throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Exports no longer include saved keys. Start an export with {}, or poll with jobId only." });
  }
  const jobId = shareInputJob({ value: (raw as Record<string, unknown>).jobId });
  return jobId ? { jobId } : {};
}

function shareInputJob(required: { value: unknown }, _options = {}): string | undefined {
  const jobId = required.value;
  if (jobId !== undefined && (typeof jobId !== "string" || !/^[0-9a-f-]{36}$/.test(jobId))) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "jobId must be a share job id." });
  return jobId as string | undefined;
}

/** Fixed route labels keep refusals and unexpected incidents specific without exposing input. */
function shareStep({ req }: { req: Request }, _options = {}): string {
  const suffix = String(req.route?.path ?? "").split("site-shares")[1] ?? "";
  const steps: Readonly<Record<string, string>> = {
    "GET ": "Export history", "POST ": "Export creation", "GET /static/options": "Static export options",
    "POST /static": "Static export creation", "POST /:shareId/acknowledge": "Export acknowledgement",
    "GET /:shareId/download": "Export download", "DELETE /:shareId": "Export revocation",
    "PUT /artifacts/:token/:file": "Share artifact upload", "DELETE /artifacts/:token/:file": "Share artifact deletion",
  };
  return steps[`${req.method} ${suffix}`] ?? "Site sharing";
}

/** Authenticated management and ZIP-only download. Mounted under the existing admin session gate. */
export function registerAdminSiteShareRoutes(required: { app: Express; deps: RouteDeps }, _optional: Record<string, never> = {}): void {
  const { app, deps } = required;
  const root = "/api/admin/v1/workspaces/:workspaceId/site-shares";
  const gate = async (req: Request, res: Response, artifact = false) => {
    res.set({ "Cache-Control": "no-store" });
    const step = shareStep({ req });
    if (String(req.params.workspaceId) !== deps.workspaceId) { res.status(404).json({ code: "NOT_FOUND", message: `${step} failed: this workspace is not available.` }); return false; }
    const trust = getPublishTrustContext(res);
    // Only the two artifact routes admit connected-computer sessions; admin operations keep RBAC.
    if (trust && !artifact) { res.status(403).json({ code: "FORBIDDEN", message: `${step} requires an authorized admin session.` }); return false; }
    if (!await authorizeOrRespond(res, trust ? publishTrustAuthorizeFor(trust) : deps.authorize, { principalId: getAuthedPrincipal(res).id, workspaceId: deps.workspaceId, permission: trust ? "publish_content.apply" : "site-backup.push", entityType: "site-backup" })) return false;
    if (!deps.siteShareBackend) { res.status(503).json({ code: "UNAVAILABLE", message: `${step} requires a site folder and private artifact storage.` }); return false; }
    return true;
  };
  const fail = (res: Response, error: unknown, req: Request) => sendSiteShareFailure({ res, error, tracker: deps.tracker }, { step: shareStep({ req }) });
  app.get(root, async (req, res) => {
    try { if (await gate(req, res)) res.json({ shares: await deps.siteShareBackend!.list({}) }); }
    catch (error) { fail(res, error, req); }
  });
  app.post(root, async (req, res) => {
    try {
      if (!await gate(req, res)) return;
      const input = readShareInput({ body: req.body });
      res.json(await deps.siteShareBackend!.create({ principalId: getAuthedPrincipal(res).id, signal: new AbortController().signal, ...input }));
    } catch (error) { fail(res, error, req); }
  });
  app.get(`${root}/static/options`, async (req, res) => {
    try { if (await gate(req, res)) res.json(await deps.siteShareBackend!.staticOptions({})); }
    catch (error) { fail(res, error, req); }
  });
  app.post(`${root}/static`, async (req, res) => {
    try {
      if (!await gate(req, res)) return;
      const input = parseStaticExportInput({ input: req.body === undefined ? {} : req.body });
      res.json(await deps.siteShareBackend!.create({ principalId: getAuthedPrincipal(res).id, signal: new AbortController().signal, format: "static", ...input }));
    } catch (error) { fail(res, error, req); }
  });
  app.post(`${root}/:shareId/password`, createSiteSharePasswordHandler({ deps }));
  app.post(`${root}/:shareId/acknowledge`, async (req, res) => {
    try {
      if (!await gate(req, res)) return;
      res.json(await deps.siteShareBackend!.acknowledge({ shareId: String(req.params.shareId) }));
    } catch (error) { fail(res, error, req); }
  });
  app.get(`${root}/:shareId/download`, async (req, res) => {
    try {
      if (!await gate(req, res)) return;
      const registry = deps.siteShareBackend!.registry;
      const row = await registry.get({ shareId: String(req.params.shareId), site: deps.workspaceId });
      if (!row || row.status === "revoked") { res.status(404).json({ code: "NOT_FOUND", message: "Export download failed: this export is missing or was revoked." }); return; }
      if (row.needsAcknowledgement) {
        res.status(409).json({ code: "ACKNOWLEDGE_CREDENTIALS", message: "This export may contain credentials. Review the warnings and acknowledge that you understand before downloading.", credentialWarnings: row.credentialWarnings ?? [] });
        return;
      }
      res.set({ ...SHARE_DOWNLOAD_HEADERS, "Content-Disposition": `attachment; filename="${row.file}"` });
      res.sendFile(`${row.shareId}.tovu.zip`, { root: registry.directory, dotfiles: "deny", cacheControl: false, lastModified: false }, error => {
        if (!error) return;
        if (res.headersSent) { res.destroy(); return; }
        res.removeHeader("Content-Disposition");
        res.type("application/json");
        if ((error as NodeJS.ErrnoException).code === "ENOENT") {
          res.status(404).json({ code: "NOT_FOUND", message: "Export download failed: the ZIP is missing from storage. Create a new export." });
          return;
        }
        fail(res, error, req);
      });
    } catch (error) { fail(res, error, req); }
  });
  app.delete(`${root}/:shareId`, async (req, res) => {
    try { if (await gate(req, res)) res.json(await deps.siteShareBackend!.revoke({ shareId: String(req.params.shareId) })); }
    catch (error) { fail(res, error, req); }
  });
  // Raw ZIP parsing runs AFTER authentication and authorization. A base64 JSON upload would
  // inflate a 300 MiB cap and duplicate the full buffer before we could validate it.
  app.put(`${root}/artifacts/:token/:file`, async (req, res, next) => {
    try { if (await gate(req, res, true)) next(); }
    catch (error) { fail(res, error, req); }
  }, (req, res, next) => {
    express.raw({ type: "application/zip", limit: SHARE_LIMITS.maxArchiveBytes, inflate: false })(req, res, error => {
      if (error) fail(res, error, req);
      else next();
    });
  }, async (req, res) => {
    try {
      const token = String(req.params.token), file = String(req.params.file);
      const validIdentity = SHARE_TOKEN.test(token) && SHARE_FILE.test(file);
      const validArchive = validIdentity && Buffer.isBuffer(req.body) && req.body.length >= 4 && req.body.readUInt32LE(0) === 0x04034b50;
      if (!validArchive) throw new SiteShareRefusal({ code: "INVALID_INPUT", message: "Expected a .tovu.zip artifact with a 16-letter token and application/zip body." });
      const registry = deps.siteShareBackend!.registry;
      // Tokens are never reused, including revoked uploads. A replay may not resurrect access.
      const row = await receiveSiteShareArtifact({ registry, site: deps.workspaceId, token, file, archive: req.body });
      res.status(201).json({ shareId: row.shareId, bytes: row.bytes, sha256: row.sha256 });
    } catch (error) { fail(res, error, req); }
  });
  app.delete(`${root}/artifacts/:token/:file`, async (req, res) => {
    try {
      if (!await gate(req, res, true)) return;
      const registry = deps.siteShareBackend!.registry;
      const row = (await registry.list({ site: deps.workspaceId })).find(row => row.token === req.params.token && row.file === req.params.file);
      if (!row) { res.status(404).json({ code: "NOT_FOUND", message: "Share artifact deletion failed: this export was not found." }); return; }
      await registry.disable({ shareId: row.shareId, site: deps.workspaceId });
      await registry.deleteArtifact({ shareId: row.shareId });
      res.sendStatus(204);
    } catch (error) { fail(res, error, req); }
  });
}

