} from "#src/features/sites/index";
import type {
  checkAgentPluginAccessToken as checkAgentPluginAccessTokenReal,
} from "#src/features/agent-plugins/token-sign-in";
import { sealPendingAgentPluginTokensForNewSite as sealPendingAgentPluginTokensReal } from "#src/server/runtime/composition/pending-agent-plugin-tokens";
import { authorizeOrRespond } from "#src/server/inbound/admin-http/authorize-guard";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin "Sites" screen backend (2026-09-04 sites-switcher decision,
 * `ADS-memory/reports/2026-09-04-sites-switcher-decision.md`) — lets a developer running Tovu
 * locally see the sites under `sites/<name>/`, create a new one, and activate one to switch
 * themes/pages/posts/database without the desktop app (Tovu-Runner already does this natively).
 *
 * Three routes, `system.read`/`system.write`-gated like every sibling in this directory
 * (`deployment-overview.ts`, `assistant-daemon.ts`) — reusing those two existing permissions
 * rather than inventing a third, since Create/Activate are exactly the kind of system-process-
 * affecting write `assistant-daemon.ts`'s restart route already gates on `system.write`, and List
 * is exactly the kind of read-only operational snapshot `deployment-overview.ts` gates on
 * `system.read`.
 *
 * `GET .../system/sites` — List. NOT gated on the capability flag (see `site-switcher-enabled.ts`):
 * touches no boot binding, so there is no risk in always answering it; its response CARRIES the
 * flag's value (`switchingEnabled`) so the UI can decide whether to render the "Sites" nav item, a
 * disabled Create button, etc. without a second round trip.
 *
 * List's response also carries the two facts a UI needs to avoid CLAIMING A SWITCH THAT HAS NOT
 * HAPPENED (2026-09-05, admin Sites screen). Neither is derivable from `sites[]`:
 *
 * - `currentSite` — what this process is bound to RIGHT NOW, read from `deps.siteBinding`
 *   (`RouteDeps.siteBinding`, resolved ONCE by the composition root at boot — 2026-09-06, replacing
 *   a per-request `describeSiteBinding()` call that silently disagreed with the real served site
 *   whenever `tovu serve <dir>` resolved it from an explicit install-dir argument instead of
 *   `{cwd, env}`; see that field's own doc), plus `listed`: whether that directory is a REGISTERED
 *   site, i.e. one `tovu serve` would accept. It legitimately may not be — `listSites` skips any
 *   directory without a valid `.site-meta.json` commit marker, and this repo's own live
 *   `sites/tovu-dev` carries neither marker file, so it was being served while `listSites` returned
 *   nothing and the screen rendered "All sites 0" (2026-09-05).
 *   `currentSite.dirOverridden` reports the `TOVU_SITE_DIR` precedence trap — see {@link
 *   SiteBinding.dirOverridden}: with it set, an activate is inert and the UI must say so.
 *   `currentSite.switcherCompatible` (`false` only for an install-dir boot) is what Create/Activate
 *   below actually gate on — see {@link SiteBinding.switcherCompatible} and
 *   `sendSiteBindingNotSwitchable`.
 * - `persistedSiteName` — the pending `TOVU_SITE` choice a previous activate left in `.env`
 *   (`readPersistedActiveSite`), so "serving A, B queued for the next restart" survives a page
 *   reload rather than living only in the activate response the reload threw away.
 *
 * Every read and write here (List's `sites[]`/`persistedSiteName`, Create's target, Activate's
 * lookup and `.env` write) is rooted at `deps.siteBinding` through `switcherBaseForBinding` — never
 * at `process.cwd()`, which once listed, created and activated in whatever tree the process was
 * standing in. An install-dir boot has no switcher tree: List shows only the served site and
 * `persistedSiteName: null`.
 *
 * `sites[]` is therefore `includeServingSite`'s composition, not `listSites`'s raw output: the
 * served directory always has a row, and every row carries `registration`. `registration:
 * "unregistered"` is the served-but-not-a-real-site case, and it is what lets one card say both
 * "this is active" and "`tovu serve` would refuse this folder" instead of the screen having to
 * choose. `listed` keeps its ORIGINAL meaning under that change — it is now read off the served
 * row's own `registration` rather than from row presence, which is the same predicate as before
 * (a row is `registered` exactly when `listSites` produced it) but stays correct now that presence
 * alone no longer implies it.
 *
 * Create and Activate are thin callers (2026-10-05): the logic lives in `features/sites/site-admin.ts`
 * (`resolveSiteSwitchBase`, `createSiteForOwner`, `activateSite`), the SAME functions the assistant's
 * `sites_create_site` / `sites_switch_site` tools call. This file only authorizes and maps refusals to
 * HTTP statuses.
 *
 * `POST .../system/sites` — Create. Refuses `SITE_SWITCHING_DISABLED` when the flag is off,
 * checked BEFORE `authorize()` (a deployment-wide gate, independent of the caller's own
 * permissions — no reason to spend an authorize() call on an operation that will be refused
 * either way). Delegates to `site-registry.ts`'s `createSite`, itself a thin wrapper over the SAME
 * `initSite` `tovu init` calls — so a site created here and one created by the CLI are identical.
 *
 * `GET .../system/sites/:name/preview` (2026-10-08) — a card's screenshot (`../sites/site-previews.ts`).
 * List carries `previewVersions` (`{ [name]: mtime }`) and enqueues due captures without waiting
 * on them; only with local site management on, so a production deployment never launches Chromium.
 *
 * `POST .../system/sites/:name/activate` — Activate. Same flag gate as Create. Persists the
 * choice (`active-site.ts`'s `persistActiveSite`) and returns explicit restart instructions —
 * it does NOT kill, signal, or re-exec any process (standing rule: no admin API terminates the
 * server on a click). The response's `restartRequired`/`restartInstructions` fields exist so the
 * UI never has to hardcode that prose itself.
 *
 * `GET .../system/sites/token-sign-in-plugins` (2026-09-29) — the BUNDLED Agent Plugins (what the new
 * site's first boot seeds, not this site's installs) that take a pasted access token (`tovuTokenAuth`),
 * so the create form can offer "connect it now". Create also
 * takes an optional `agentPluginTokens: { [pluginId]: token }`: each is checked against the plugin's
 * probe URL first (a rejected one refuses the create, nothing made), then sealed with the NEW site's
 * key into its folder and applied on that site's first boot
 * (`composition/pending-agent-plugin-tokens.ts`). Leaving it out creates the site exactly as before.
 */
export type AdminSitesDeps = Pick<RouteDeps, "workspaceId" | "authorize" | "siteBinding" | "createSite"> & {
  tracker?: RouteDeps["tracker"];
  sitesWorkspace?: SitesWorkspace;
  localSiteSupervisor?: LocalSitesRouteDeps["localSiteSupervisor"];
  siteTrash?: LocalSitesRouteDeps["siteTrash"];
  listSiteTrash?: typeof listSiteTrash;
  /** Card preview captures (`site-preview-host.ts`); a test injects a fake, `null` turns them off. */
  sitePreviews?: SitePreviewService | null;
  /** The guarded outbound client a token check probes through. Absent, a given token is refused as
   *  not checkable rather than saved unchecked. */
  customCredentialsHttpClient?: RouteDeps["customCredentialsHttpClient"];
  checkAgentPluginAccessToken?: typeof checkAgentPluginAccessTokenReal;
  sealPendingAgentPluginTokens?: typeof sealPendingAgentPluginTokensReal;
  listTokenSignInPlugins?: (workspaceId: string) => ReturnType<typeof listNewSiteAgentPluginTokenSignInPlugins>;
  /** Injectable so a route test proves both branches without touching the real filesystem or
   *  `sites/`. Each defaults to the real `site-dir`/`site-switcher-enabled` implementation. */
  listSites?: (optional?: Parameters<typeof listSitesReal>[0]) => readonly SiteListEntry[];
  persistActiveSite?: typeof persistActiveSiteReal;
  readSiteRunning?: typeof readSiteRunning;
  isSiteSwitcherEnabled?: typeof isSiteSwitcherEnabledReal;
  readPersistedActiveSite?: typeof readPersistedActiveSiteReal;
  /** The `npm run dev` restart channel for Activate's `restartNow`. Defaults to
   *  `devRestartPortFromEnv({ delayMs: 0 })` (`null` outside `dev.mjs`); a test passes a fake or `null`. */
  devRestart?: DevRestartPort | null;
};

/** HTTP status for each refusal code the shared feature functions return. 403 for the
 *  deployment-wide flag; 409 for the per-boot binding fact and an occupied name (see
 *  `features/sites/site-admin.ts` for why the binding is 409, not 403). */
const REFUSAL_STATUS: Record<SiteAdminRefusalCode, number> = {
  SITE_SWITCHING_DISABLED: 403,
  SITE_BINDING_NOT_SWITCHABLE: 409,
  VALIDATION_ERROR: 400,
  SITE_ALREADY_EXISTS: 409,
  SITE_NOT_FOUND: 404,
  SITE_ALREADY_RUNNING: 409,
  AGENT_PLUGIN_TOKEN_INVALID: 400,
  AGENT_PLUGIN_TOKEN_REFUSED: 400,
  AGENT_PLUGIN_TOKEN_UNSUPPORTED: 400,
};

/** Sends a refusal as the `{error, code}` body every mutating route below shares (plus `pluginId`
 *  for a refused access token). */
function sendRefusal(res: Response, refusal: SiteAdminRefusal): void {
  const { ok: _ok, ...body } = refusal;
  res.status(REFUSAL_STATUS[refusal.code]).json(body);
}

/** Extracts and validates the create-site request's `name` field. Returns the string on success,
 *  or the refusal the route should send verbatim, so the create handler's own branching stays at
 *  "is this valid or not" rather than re-deriving the wire format inline.
 *  @complexity O(1) time/space; cyclomatic 3, cognitive 2. */
function parseCreateSiteName(body: unknown): { ok: true; name: string } | SiteAdminRefusal {
  const record = body as Record<string, unknown> | null | undefined;
  const name = typeof record?.name === "string" ? record.name : undefined;
  if (name === undefined) {
    return { ok: false, error: "'name' (string) is required", code: "VALIDATION_ERROR" };
  }
  return { ok: true, name };
}

/** Resolved route ports reused while assembling the HTTP listing. */
type ListingContext = {
  req: Request;
  deps: AdminSitesDeps;
  listSites: NonNullable<AdminSitesDeps["listSites"]>;
  isSiteSwitcherEnabled: NonNullable<AdminSitesDeps["isSiteSwitcherEnabled"]>;
  readPersistedActiveSite: NonNullable<AdminSitesDeps["readPersistedActiveSite"]>;
  localSiteSupervisor: AdminSitesDeps["localSiteSupervisor"];
  devRestart: DevRestartPort | null;
  sitePreviews: SitePreviewService | undefined;
  sitesWorkspace: SitesWorkspace;
};

/** Build the HTTP snapshot from the served binding. Port failures reach the route's 500 handler.
 * @complexity O(sites + local sites) time/space, plus the existing filesystem/service reads. */
function siteListing({ req, deps, listSites, isSiteSwitcherEnabled, readPersistedActiveSite,
  localSiteSupervisor, devRestart, sitePreviews, sitesWorkspace }: ListingContext, _options = {}) {
  // Every read below is rooted at the SERVED binding, never `process.cwd()` — see
  // `switcherBaseForBinding`'s own doc for the wrong-tree bug the cwd default caused.
  const binding = deps.siteBinding;
  const registered: readonly SiteListEntry[] = listSitesForBinding({ binding }, { listSites });
  const switcherBase = switcherBaseForBinding(binding);
  const sites: ServingSiteListEntry[] = includeServingSite({ sites: registered, binding });
  const serving = sites.find((site) => site.dir === binding.dir);
  const localSites = isSiteSwitcherEnabled() ? localSiteSupervisor?.list() ?? [] : [];
  const previewVersions = listingPreviewVersions({ req, sites, binding, localSites, sitePreviews, isSiteSwitcherEnabled });
  return {
    sitesHome: isSiteSwitcherEnabled() ? sitesWorkspace.home({}) : undefined,
    // What a new site's admin gets when the create form's password is left blank — resolved by the
    // same function the create path seeds with, so the shown value cannot drift from the seeded one.
    // Sent only where this boot can create sites, and only to a caller already holding
    // `system.read`; the admin bundle itself never contains it (`default-credential-exposure.ts`).
    // Owner, 2026-10-22: show the starter password so a new site can be signed into.
    starterAdminPassword: isSiteSwitcherEnabled() ? resolveNewSiteAdminPassword({}) : undefined,
    switchingEnabled: isSiteSwitcherEnabled(),
    ...listingManagement({ deps, localSiteSupervisor, switcherBase, devRestart, binding, isSiteSwitcherEnabled, localSites }),
    sites: sites.map((site) => {
      if (!site.running) return site;
      const { pid, port, app, started, scheme } = site.running;
      return { ...site, running: { pid, port, app, started, scheme } };
    }),
    previewVersions,
    currentSite: { ...binding, listed: serving?.registration === "registered" },
    // An install-dir boot has no switcher `.env`: whatever sits in the cwd's belongs to another tree.
    persistedSiteName: switcherBase === null ? null : readPersistedActiveSite({ cwd: switcherBase }),
  };
}

/** Enqueue previews only for local management; captures never delay the response.
 * @complexity O(sites + local sites) time/space through the existing preview service. */
function listingPreviewVersions({ req, sites, binding, localSites, sitePreviews, isSiteSwitcherEnabled }: {
  req: Request; sites: ServingSiteListEntry[]; binding: AdminSitesDeps["siteBinding"];
  localSites: ReturnType<NonNullable<AdminSitesDeps["localSiteSupervisor"]>["list"]>;
  sitePreviews: SitePreviewService | undefined;
  isSiteSwitcherEnabled: ListingContext["isSiteSwitcherEnabled"];
}, _options = {}) {
  // Reads capture mtimes and only ENQUEUES due captures — never awaited here (see the service).
  return sitePreviews && isSiteSwitcherEnabled()
    ? sitePreviews.versions({ sites, targets: sitePreviewTargets({ servingName: binding.name, localSites }, { serving: servingAddressOf({ req }) }) })
    : {};
}

/** Whether this boot can restart onto another site. @complexity O(1) time/space. */
function canSwitchListingSite({ isSiteSwitcherEnabled, devRestart, binding, switcherBase }: {
  isSiteSwitcherEnabled: ListingContext["isSiteSwitcherEnabled"]; devRestart: DevRestartPort | null;
  binding: AdminSitesDeps["siteBinding"]; switcherBase: string | null;
}, _options = {}) {
  if (!isSiteSwitcherEnabled() || devRestart === null || devRestart.canSwitchSite === false) return false;
  return !binding.dirOverridden && switcherBase !== null;
}

/** HTTP management capabilities and Trash snapshot; failures propagate to the listing route.
 * @complexity O(trash entries) time/space through the injected trash reader. */
function listingManagement({ deps, localSiteSupervisor, switcherBase, devRestart, binding, isSiteSwitcherEnabled, localSites }: {
  deps: AdminSitesDeps; localSiteSupervisor: AdminSitesDeps["localSiteSupervisor"];
  localSites: ReturnType<NonNullable<AdminSitesDeps["localSiteSupervisor"]>["list"]>;
  switcherBase: string | null; devRestart: DevRestartPort | null; binding: AdminSitesDeps["siteBinding"];
  isSiteSwitcherEnabled: ListingContext["isSiteSwitcherEnabled"];
}, _options = {}) {
  return {
    localManagementEnabled: isSiteSwitcherEnabled() && localSiteSupervisor !== undefined && switcherBase !== null,
    canSwitchNow: process.env.TOVU_DEV_WARM_SITES === "1" && isSiteSwitcherEnabled() && localSiteSupervisor !== undefined && switcherBase !== null
      || canSwitchListingSite({ isSiteSwitcherEnabled, devRestart, binding, switcherBase }),
    localSites,
    trash: isSiteSwitcherEnabled() && switcherBase !== null && localSiteSupervisor
      ? (deps.listSiteTrash ?? listSiteTrash)({ base: switcherBase }) : [],
  };
}

/** Forward raw create fields to their feature owner; validation and errors stay there.
 * @complexity O(1) adapter overhead; creation/token costs belong to createSiteForOwner. */
function createSiteFromRequest({ body, deps, switcherBase, name, actorId }: {
  body: unknown; deps: AdminSitesDeps; switcherBase: string; name: string; actorId: string;
}, _options = {}) {
  return createSiteForOwner(
    {
      workspaceId: deps.workspaceId,
      actorId, source: "admin",
      switcherBase,
      name,
      adminPassword: (body as Record<string, unknown> | null | undefined)?.adminPassword,
      agentPluginTokens: (body as Record<string, unknown> | null | undefined)?.agentPluginTokens,
    },
    {
      bundledSourceRoot: bundledAgentPluginsDir(),
      credentials: deps.customCredentialsHttpClient && composePluginCredentials({ httpClient: deps.customCredentialsHttpClient }),
      tracker: deps.tracker,
      createSite: deps.createSite,
      customCredentialsHttpClient: deps.customCredentialsHttpClient,
      checkAgentPluginAccessToken: deps.checkAgentPluginAccessToken,
      sealPendingAgentPluginTokens: deps.sealPendingAgentPluginTokens ?? sealPendingAgentPluginTokensReal,
    },
  );
}

export function registerAdminSitesRoutes(app: Express, deps: AdminSitesDeps): void {
  const sitesWorkspace = deps.sitesWorkspace ?? createSitesWorkspace({});
  registerSitesHomeRoutes({ app, deps, workspace: sitesWorkspace });
  if (registerWarmSiteControl({ app, binding: deps.siteBinding, workspaceId: deps.workspaceId })) return;
  const listSites = deps.listSites ?? listSitesReal;
  const isSiteSwitcherEnabled = deps.isSiteSwitcherEnabled ?? isSiteSwitcherEnabledReal;
  const readPersistedActiveSite = deps.readPersistedActiveSite ?? readPersistedActiveSiteReal;
  const localSiteSupervisor = deps.localSiteSupervisor ?? localSiteSupervisorForHost({ binding: deps.siteBinding, workspaceId: deps.workspaceId });
  const warmServer = warmSiteServerForHost({ binding: deps.siteBinding, workspaceId: deps.workspaceId });
  if (warmServer && process.env.TOVU_DEV_WARM_CONTROL_TOKEN) {
    app.post("/internal/dev-warm-site", async (req, res) => {
      if (req.headers["x-tovu-warm-control"] !== process.env.TOVU_DEV_WARM_CONTROL_TOKEN) { res.sendStatus(404); return; }
      try {
        if (typeof req.body?.name !== "string") { res.sendStatus(400); return; }
        res.json({ url: await warmServer({ name: req.body.name }) });
      } catch (error) {
        const code = error instanceof Error && "code" in error ? String(error.code) : "SITE_START_FAILED";
        res.status(409).json({ code });
      }
    });
  }
  // HTTP sends its JSON response before the timer fires; only chat needs a reply grace period.
  const devRestart = deps.devRestart === undefined ? devRestartPortFromEnv({ delayMs: 0 }) : deps.devRestart;
  const sitePreviews = deps.sitePreviews === undefined ? sitePreviewServiceForHost({ binding: deps.siteBinding }) : deps.sitePreviews ?? undefined;
  registerSitePreviewRoutes({ app, deps: { workspaceId: deps.workspaceId, authorize: deps.authorize, sitePreviews } });
  registerLocalSitesRoutes({ app, deps: { ...deps, localSiteSupervisor, isSiteSwitcherEnabled,
    afterTrash({ base, name }) {
      // A next-launch default must not silently recreate the folder just moved to Trash.
      if (readPersistedActiveSite({ cwd: base }) === name) {
        (deps.persistActiveSite ?? persistActiveSiteReal)({ name: deps.siteBinding.name }, { cwd: base });
      }
    },
  } });

  app.get("/api/admin/v1/workspaces/:workspaceId/system/sites", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: "site-registry",
      });
      if (!authorized) return;

      res.status(200).json(siteListing({ req, deps, listSites, isSiteSwitcherEnabled,
        readPersistedActiveSite, localSiteSupervisor, devRestart, sitePreviews, sitesWorkspace }));
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/sites", code: "INTERNAL_ERROR" });
    }
  });

  app.get("/api/admin/v1/workspaces/:workspaceId/system/sites/token-sign-in-plugins", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.read",
        workspaceId: deps.workspaceId,
        entityType: "site-registry",
      });
      if (!authorized) return;
      const plugins = await (deps.listTokenSignInPlugins ?? (() => listNewSiteAgentPluginTokenSignInPlugins({ bundledSourceRoot: bundledAgentPluginsDir() })))(deps.workspaceId);
      res.status(200).json({ plugins });
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/sites", code: "INTERNAL_ERROR" });
    }
  });

  app.post("/api/admin/v1/workspaces/:workspaceId/system/sites", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    // The flag, then the binding — both checked before spending an authorize() call on an
    // operation this boot cannot fulfill regardless of who is asking (see `resolveSiteSwitchBase`).
    const gate = resolveSiteSwitchBase({ binding: deps.siteBinding, switchingEnabled: isSiteSwitcherEnabled() });
    if (!gate.ok) {
      sendRefusal(res, gate);
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.write",
        workspaceId: deps.workspaceId,
        entityType: "site-registry",
      });
      if (!authorized) return;

      const parsed = parseCreateSiteName(req.body);
      if (!parsed.ok) {
        sendRefusal(res, parsed);
        return;
      }

      const created = await createSiteFromRequest({ body: req.body, deps, switcherBase: gate.switcherBase, name: parsed.name, actorId: principal.id });
      if (!created.ok) {
        sendRefusal(res, created);
        return;
      }
      res.status(201).json({ site: created.site, agentPluginTokens: created.agentPluginTokens });
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/sites", code: "INTERNAL_ERROR" });
    }
  });

  app.post("/api/admin/v1/workspaces/:workspaceId/system/sites/:name/activate", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    // See the Create route's identical gate: the served tree's base, never `process.cwd()`.
    const gate = resolveSiteSwitchBase({ binding: deps.siteBinding, switchingEnabled: isSiteSwitcherEnabled() });
    if (!gate.ok) {
      sendRefusal(res, gate);
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const authorized = await authorizeOrRespond(res, deps.authorize, {
        principalId: principal.id,
        permission: "system.write",
        workspaceId: deps.workspaceId,
        entityType: "site-registry",
      });
      if (!authorized) return;

      // `restartNow: true` (2026-10-05, OD-S1) asks the `npm run dev` supervisor to restart onto the
      // new site; without it, Activate behaves exactly as before (persist + instructions).
      const restartNow = (req.body as Record<string, unknown> | null | undefined)?.restartNow === true;
      const activated = await activateSiteWithWarmServer(
        { switcherBase: gate.switcherBase, name: String(req.params.name ?? ""), currentSiteName: deps.siteBinding.name, restartNow, dirOverridden: deps.siteBinding.dirOverridden },
        { listSites, persistActiveSite: deps.persistActiveSite, devRestart, readSiteRunning: deps.readSiteRunning, workspace: sitesWorkspace, warmServer },
      );
      if (!activated.ok) {
        sendRefusal(res, activated);
        return;
      }
      res.status(200).json(activated);
    } catch (err) {
      sendAdminFailure({ res, error: err }, { operation: "routes/system/sites", code: "INTERNAL_ERROR" });
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { ToolInputError } from "@jini-ai/core";
import type { Express, Request, Response } from "express";

import {
  createSourceControlCredential,
  deleteSourceControlCredential,
  listSourceControlCredentials,
  SourceControlCredentialDuplicateLabelError,
  SourceControlCredentialNotFoundError,
  SourceControlCredentialSecretStoreUnconfiguredError,
  SourceControlCredentialValidationError,
  updateSourceControlCredential,
  type SourceControlCredentialSummary,
} from "#src/features/source-control/index";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";

/**
 * @file Admin Source Control page's credential CRUD backend.
 *
 * Registers `GET`/`POST` on the collection and `PUT`/`DELETE` on a single credential set, all under
 * `/api/admin/v1/workspaces/:workspaceId/system/source-control/credentials`, plus `GET
 * .../system/source-control/providers` (the plugin-declared hosts and their credential forms). Deliberately a THIN
 * HTTP adapter over `features/source-control/store.ts` — every validation, uniqueness, and
 * default-slot rule already lives there; this route's only job is: check auth, shape the request
 * into `store.ts`'s input types, map its thrown errors to HTTP status codes, and return
 * `SourceControlCredentialSummary` — never the sealed connection, never a token, never a username.
 *
 * `source-control.credentials.write`-gated on every verb, NOT `system.publish` — the permission
 * `publish-credentials.ts` uses for its own structurally-identical route. Reusing `system.publish`
 * here would be wrong semantics: this page connects a plugin-provided source-control IDENTITY,
 * which is separate from a publish target and never triggers a publish. The saved identity
 * carries authentication only, with no commit history, sync, or versioning. A saved connection's existence and label
 * are themselves operationally sensitive (which external accounts this workspace can reach with a
 * write-scoped credential) — the same "gate the read same as the write" reasoning
 * `publish-credentials.ts`'s own header gives for its single-permission-on-every-verb shape, which
 * this route mirrors with its own dedicated permission string instead. Matches the established
 * per-feature permission convention `deployments.read`/`deployments.credentials.write` and
 * `analytics.read`/`backup.read`/`comments.read` already set (`routes/admin/deployments/list.ts`'s
 * own header traces the precedent): a NEW dot-namespaced permission, not a reused one, and the
 * seeded owner's wildcard grant authorizes it immediately with no seed edit required.
 *
 * See `CredentialsDeps` in `server/routes/types.ts` for why each route picks only its own repo.
 */
export type AdminSourceControlCredentialsDeps = Pick<
  RouteDeps,
  "projectKeys" | "workspaceId" | "authorize" | "clock" | "idGen" | "sourceControlCredentialSetRepo" | "siteAssistantSecretSealer" | "siteAssistantSecretKeyring" | "loadSourceControlProviders" | "observability"
>;

const PERMISSION = "source-control.credentials.write";
const ENTITY_TYPE = "source-control";

const BASE_PATH = "/api/admin/v1/workspaces/:workspaceId/system/source-control/credentials";
/** The git hosts this workspace's enabled Agent Plugins provide, with each one's credential form. */
const PROVIDERS_PATH = "/api/admin/v1/workspaces/:workspaceId/system/source-control/providers";

/** Every error this route can produce, shaped once so each handler below stays a thin dispatch.
 *  Mirrors `publish-credentials.ts`'s own `sendStoreError`, including its 2026-08-16 fix: the
 *  untyped fallback responds `500` instead of `throw err`. A re-throw here escapes the caller's own
 *  `catch (err) { sendStoreError(res, err); }` too — that shape only LOOKS guarded; see
 *  `publish-credentials.ts`'s own doc comment on this same function for the fuller story (found via
 *  an AST scan over every `app.<verb>()` handler in `src/server/routes/**`, which is also how this
 *  file's `GET`/`DELETE` were found with no `try`/`catch` at all). */
function sendStoreError(res: Response, err: unknown): void {
  if (err instanceof ToolInputError) { res.status(409).json({ error: "KEY_IN_USE", detail: err.message }); return; }
  if (err instanceof SourceControlCredentialValidationError) {
    res.status(400).json({ error: "VALIDATION", detail: err.message });
    return;
  }
  if (err instanceof SourceControlCredentialDuplicateLabelError) {
    res.status(409).json({ error: "DUPLICATE_LABEL", detail: err.message });
    return;
  }
  if (err instanceof SourceControlCredentialNotFoundError) {
    res.status(404).json({ error: "NOT_FOUND", detail: err.message });
    return;
  }
  if (err instanceof SourceControlCredentialSecretStoreUnconfiguredError) {
    res.status(503).json({ error: "SECRET_STORE_UNCONFIGURED", detail: err.message });
    return;
  }

  sendAdminFailure({ res, error: err }, { operation: "routes/system/source-control-credentials", code: "INTERNAL_ERROR" });
}

export function registerAdminSourceControlCredentialsRoutes(app: Express, deps: AdminSourceControlCredentialsDeps): void {
  const readDeps = { repo: deps.sourceControlCredentialSetRepo, sealer: deps.siteAssistantSecretSealer };
  const writeDeps = {
    repo: deps.sourceControlCredentialSetRepo,
    sealer: deps.siteAssistantSecretSealer,
    keyring: deps.siteAssistantSecretKeyring,
    clock: deps.clock,
    idGen: deps.idGen,
    observability: deps.observability,
    loadSourceControlProviders: deps.loadSourceControlProviders,
  };

  /** Shared workspace-path-param + `source-control.credentials.write` authorization check every
   *  verb below performs first — mirrors `publish-credentials.ts`'s own
   *  `rejectUnlessAuthorized`. Returns `true` and has already written the response iff the caller
   *  should stop. */
  async function rejectUnlessAuthorized(req: Request, res: Response): Promise<boolean> {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return true;
    }
    const principal = getAuthedPrincipal(res);
    const authResult = await deps.authorize({
      principalId: principal.id,
      permission: PERMISSION,
      workspaceId: deps.workspaceId,
      entityType: ENTITY_TYPE,
    });
    if (!authResult.allowed) {
      res.status(403).json({
        error: `principal '${principal.id}' is not authorized for '${PERMISSION}' (${authResult.reason})`,
        code: "FORBIDDEN",
        details: { permission: PERMISSION, reason: authResult.reason },
      });
      return true;
    }
    return false;
  }

  // The hosts the page renders a row for, from the plugins (the way `publish-targets` lists deploy
  // hosts): id, label, the declared credential form and its translations (`i18n`). `switchedOff` names each host an installed
  // but switched-off plugin declares, so the page can say which plugin to turn back on. Plugin load
  // refusals go to the server log, never the response.
  app.get(PROVIDERS_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      const registry = await deps.loadSourceControlProviders(deps.workspaceId);
      for (const refusal of registry.refusals) console.warn(`[source-control-providers] ${refusal}`);
      res.status(200).json({
        providers: registry.list().map(({ descriptor }) => ({
          id: descriptor.id,
          label: descriptor.label,
          ...(descriptor.credential !== undefined ? { credential: descriptor.credential } : {}),
          ...(descriptor.i18n !== undefined ? { i18n: descriptor.i18n } : {}),
        })),
        switchedOff: [...(registry.switchedOff ?? [])].map(([id, pluginId]) => ({ id, pluginId })),
      });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.get(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      const credentials: SourceControlCredentialSummary[] = await listSourceControlCredentials(readDeps, { workspaceId: deps.workspaceId });
      res.status(200).json({ credentials });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.post(BASE_PATH, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const credential = await createSourceControlCredential({ deps: writeDeps, input: {
        workspaceId: deps.workspaceId,
        label: body.label,
        connection: body.connection,
        // Only a project-bound create starts non-default (attached next); a site row, including every
        // create where no project store is open, keeps Jini's first-row auto-default.
        isDefault: body.isDefault ?? (body.scope !== "site" && deps.sourceControlCredentialSetRepo.project ? false : undefined),
        // "site" = only for this site; omitted = the project store when one is attached.
        scope: body.scope,
      } });
      if (credential.scope === "project") await deps.projectKeys?.use({ keyId: credential.id, use: true });
      res.status(201).json({ credential });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.put(`${BASE_PATH}/:id`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    const body = (req.body ?? {}) as Record<string, unknown>;
    try {
      const credential = await updateSourceControlCredential({ deps: writeDeps, input: {
        workspaceId: deps.workspaceId,
        id: req.params.id,
        ...(body.label !== undefined ? { label: body.label } : {}),
        ...(body.connection !== undefined ? { connection: body.connection } : {}),
        ...(body.isDefault !== undefined ? { isDefault: body.isDefault } : {}),
      } });
      res.status(200).json({ credential });
    } catch (err) {
      sendStoreError(res, err);
    }
  });

  app.delete(`${BASE_PATH}/:id`, async (req, res) => {
    if (await rejectUnlessAuthorized(req, res)) return;
    try {
      // Idempotent — `deleteSourceControlCredential`/`SourceControlCredentialSetRepoPort.delete` are
      // both no-ops (not errors) for a missing row, matching this route's own documented 204-always
      // contract. A THROWN error here (e.g. the repo itself is unreachable) is a different case,
      // still needs a response, not a silent no-op.
      await deleteSourceControlCredential(readDeps, { workspaceId: deps.workspaceId, id: req.params.id });
      res.status(204).end();
    } catch (err) {
      sendStoreError(res, err);
    }
  });
}

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Express } from 'express';
import { getAuthedPrincipal } from '#src/server/inbound/admin-http/dev-auth';
import type { ToolGapsToolDeps } from '#src/assistant/host-ports';

/** Owner-only Observability filter over the existing tool audit store. No mutation endpoint. */
