import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import { IdentityForbiddenError, IdentityNotFoundError, IdentityValidationError, OwnerRequiredError } from "@jini-ai/user-management";
import { trashUser, SelfDeleteError } from "#src/features/identity/delete-user-service";
import { UserDeleteUnsupportedError } from "#src/features/identity/user-purge-types";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { identityServiceDepsFrom, type UsersRouteDeps, type UsersRouteRegistrar } from "./deps.js";

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendUserDeleteError(res: Response, err: unknown): void {
  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof SelfDeleteError) {
    res.status(409).json({ error: err.message, code: "SELF_DELETE" });
    return;
  }
  if (err instanceof OwnerRequiredError) {
    res.status(409).json({ error: err.message, code: "OWNER_REQUIRED" });
    return;
  }
  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  if (err instanceof UserDeleteUnsupportedError) {
    res.status(501).json({ error: err.message, code: "NOT_SUPPORTED" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/delete", code: "INTERNAL_ERROR" });
}

/**
 * DELETE users/:principalId — moves a user to the Trash (delete-user plan v2, decisions 4/5/7, and
 * the OWNER DECISION 2026-09-24 that supersedes decision 1). Gated by the caller being the owner or
 * holding the built-in `admin` role; refuses the caller's own principal (`SELF_DELETE`), the seeded
 * owner or the workspace's last active owner-`*` principal (`OWNER_REQUIRED`); a target already in
 * the Trash is an idempotent 204; 501s when the composition root has no Trash wiring
 * (`NOT_SUPPORTED`, the in-memory identity store) — see `delete-user-service.ts`'s `trashUser` for
 * the full rule set. Permanent deletion happens only through the Trash's own purge, never here.
 */
export const registerAdminUserDeleteRoute: UsersRouteRegistrar = (app, deps: UsersRouteDeps) => {
  app.delete("/api/admin/v1/workspaces/:workspaceId/users/:principalId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const caller = getAuthedPrincipal(res);
      const seededOwnerPrincipalId = await deps.ownerPrincipalId;

      await trashUser({
        deps: { identity: identityServiceDepsFrom(deps), removeUser: deps.removeUser, isInTrash: deps.isInTrash },
        input: {
          workspaceId: deps.workspaceId,
          callerPrincipalId: caller.id,
          principalId: String(req.params.principalId ?? ""),
          seededOwnerPrincipalId,
        },
      });

      res.status(204).send();
    } catch (err) {
      sendUserDeleteError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { assertUserAccountAction, SelfDeleteError } from "#src/features/identity/delete-user-service";
import type { Response } from "express";

import { IdentityForbiddenError, IdentityNotFoundError, IdentityValidationError, OwnerRequiredError } from "@jini-ai/user-management";
import { disablePrincipal } from "@jini-ai/user-management/server";
import { toAdminUserResponse } from "#src/server/inbound/admin-http/http/users";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { identityServiceDepsFrom, type UsersRouteDeps, type UsersRouteRegistrar } from "./deps.js";

/**
 * Loads the paired `UserRecord` and role/policy links for `principal` and builds the admin
 * response shape. `disablePrincipal` returns only the updated `PrincipalRecord` — every
 * `kind='user'` principal has a paired `UserRecord` by construction (CREATE_USER's atomicity
 * guarantee), so the missing-user throw here is defensive, not an expected runtime path.
 *
 * @complexity O(1) plus two repo reads.
 */
async function assembleDisabledUserResponse(
  deps: UsersRouteDeps,
  principal: Parameters<typeof toAdminUserResponse>[0]["principal"]
) {
  const user = await deps.userRepo.findByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id });
  if (!user) throw new IdentityNotFoundError({ message: `user '${principal.id}' was not found` });
  const [roleLinks, policyLinks] = await Promise.all([
    deps.principalRoleRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id }),
    deps.principalPolicyRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id }),
  ]);
  return toAdminUserResponse({
    principal,
    user,
    roleIds: roleLinks.map((link) => link.roleId),
    policyIds: policyLinks.map((link) => link.policyId),
  });
}

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendUserDisableError(res: Response, err: unknown): void {
  if (err instanceof SelfDeleteError) {
    res.status(409).json({ error: err.message, code: "SELF_DELETE" });
    return;
  }
  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof OwnerRequiredError) {
    res.status(409).json({ error: err.message, code: "OWNER_REQUIRED" });
    return;
  }
  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/disable", code: "INTERNAL_ERROR" });
}

/**
 * POST users/:principalId/disable — `DISABLE_PRINCIPAL` (SPEC-006 0.6.0, REQ-11, first HTTP route
 * for a transition specified since v0.5.0). Gated by `user.manage`; refuses the seeded owner
 * unconditionally and refuses any disable that would drop the active owner-`*` count to zero
 * (INV-08) — see `identity/admin-crud-service.ts`'s `disablePrincipal` for the full contract.
 *
 * `disablePrincipal` returns only the updated `PrincipalRecord` — `toAdminUserResponse` also needs
 * the paired `UserRecord` (every `kind='user'` principal has one by construction, CREATE_USER's
 * atomicity guarantee, so the second lookup below is defensive, not an expected runtime path).
 */
export const registerAdminUserDisableRoute: UsersRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/users/:principalId/disable", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const caller = getAuthedPrincipal(res);
      const seededOwnerPrincipalId = await deps.ownerPrincipalId;
      const principalId = String(req.params.principalId ?? "");

      const { principal } = await deps.transactions.run({ workspaceId: deps.workspaceId, execute: async () => {
        const serviceDeps = identityServiceDepsFrom(deps);
        await assertUserAccountAction({ deps: serviceDeps, workspaceId: deps.workspaceId, principalId, action: "disable" },
          { callerPrincipalId: caller.id, seededOwnerPrincipalId });
        return disablePrincipal({
          deps: serviceDeps,
          input: {
            workspaceId: deps.workspaceId,
            callerPrincipalId: caller.id,
            principalId,
            seededOwnerPrincipalId,
          },
        });
      } });

      res.json({ user: await assembleDisabledUserResponse(deps, principal) });
    } catch (err) {
      sendUserDisableError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import { IdentityForbiddenError, IdentityNotFoundError, IdentityValidationError, OwnerRequiredError } from "@jini-ai/user-management";
import { assertCallerHasAnyPermission, enablePrincipal } from "@jini-ai/user-management/server";
import { toAdminUserResponse } from "#src/server/inbound/admin-http/http/users";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { UserInTrashError } from "#src/features/identity/delete-user-service";
import { identityServiceDepsFrom, type UsersRouteRegistrar } from "./deps.js";

function sendUserEnableError({ res, err }: { res: Response; err: unknown }, _options = {}): void {
  if (err instanceof UserInTrashError) {
    res.status(409).json({ error: err.message, code: "USER_IN_TRASH" });
    return;
  }

  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({
      error: err.message,
      code: "FORBIDDEN",
      details: { permission: err.permission, reason: err.reason },
    });
    return;
  }

  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }

  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }

  if (err instanceof OwnerRequiredError) {
    res.status(409).json({ error: err.message, code: "OWNER_REQUIRED" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/enable", code: "INTERNAL_ERROR" });
}

/**
 * POST users/:principalId/enable — `ENABLE_PRINCIPAL` (SPEC-006 0.6.0, REQ-15) — the symmetric
 * re-activation `DISABLE_PRINCIPAL` never had a counterpart for. Gated by `user.manage`; target
 * must be `kind='user'` (EC-14). See `disable.ts`'s doc for why the paired-user lookup below is
 * defensive, not an expected runtime path.
 */
export const registerAdminUserEnableRoute: UsersRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/users/:principalId/enable", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const caller = getAuthedPrincipal(res);
      const principalId = String(req.params.principalId ?? "");

      // Trash membership is private too: use the identity owner's gate before looking it up.
      const serviceDeps = identityServiceDepsFrom(deps);
      await assertCallerHasAnyPermission({ deps: serviceDeps, workspaceId: deps.workspaceId,
        callerPrincipalId: caller.id, permissions: ["user.manage"] });

      // OWNER DECISION 2026-09-24 (delete-user plan v2, decision 7) — refuse BEFORE the transition:
      // re-activating a trashed principal would leave an ACTIVE user still indexed for purge.
      if (await deps.isInTrash(principalId)) {
        throw new UserInTrashError("this user is in the Trash; restore them first");
      }

      const { principal } = await enablePrincipal({
        deps: serviceDeps,
        input: {
          workspaceId: deps.workspaceId,
          callerPrincipalId: caller.id,
          principalId,
        },
      });

      const user = await deps.userRepo.findByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id });
      if (!user) throw new IdentityNotFoundError({ message: `user '${principal.id}' was not found` });
      const [roleLinks, policyLinks] = await Promise.all([
        deps.principalRoleRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id }),
        deps.principalPolicyRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id }),
      ]);

      res.json({
        user: toAdminUserResponse({
          principal,
          user,
          roleIds: roleLinks.map((link) => link.roleId),
          policyIds: policyLinks.map((link) => link.policyId),
        }),
      });
    } catch (err) {
      sendUserEnableError({ res, err });
    }
  });
};

