import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { toAdminUserResponse } from "#src/server/inbound/admin-http/http/users";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { identityServiceDepsFrom, type UsersRouteRegistrar } from "./deps.js";
import { userAccountProtection } from "#src/features/identity/delete-user-service";

/**
 * GET users — list a workspace's human (`kind='user'`) principals for the
 * admin UI. No dedicated `listUsers` business-logic function exists in
 * `src/identity` (that library exports grant-writing mutations, not
 * read-side wrappers) — this route calls the repo ports directly, mirroring
 * `routes/admin/members/list.ts`'s reasoning.
 *
 * Non-human principals (`system`, `agent`, `api_key` — including the
 * disabled legacy `user-local` seed row) are filtered out: this screen is
 * "Users" (human operators), not the full principal roster.
 *
 * Gated by `user.manage`/`member.manage` (either) for this read-only roster;
 * operator creation separately requires `user.manage`. No separate `user.read` permission exists in the catalog. 2026-07-16
 * authz sweep: this route previously had zero permission check beyond session auth, letting any
 * authenticated admin session read the full user roster regardless of role.
 */
export const registerAdminUserListRoute: UsersRouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/users", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const [userManageResult, memberManageResult] = await Promise.all([
        deps.authorize({ principalId: principal.id, permission: "user.manage", workspaceId: deps.workspaceId }),
        deps.authorize({ principalId: principal.id, permission: "member.manage", workspaceId: deps.workspaceId }),
      ]);
      if (!userManageResult.allowed && !memberManageResult.allowed) {
        res.status(403).json({
          error: `principal '${principal.id}' is not authorized for 'user.manage' or 'member.manage' (${userManageResult.reason})`,
          code: "FORBIDDEN",
          details: { permission: "user.manage", reason: userManageResult.reason },
        });
        return;
      }

      const principals = await deps.principalRepo.list({ workspaceId: deps.workspaceId });
      const nonTrashedHumanPrincipals = (
        await Promise.all(
          principals
            .filter((principal) => principal.kind === "user")
            .map(async (principal) => ({
              principal,
              // OWNER DECISION 2026-09-24 (delete-user plan v2, decision 7's list side): a user
              // trashed via DELETE_USER is `status:'disabled'` plus a `trashed_items` row — this
              // screen must not list them as an ordinary disabled user, since restoring them here
              // means EnablePrincipal, not the Trash's own restore. An intentionally-disabled user
              // (never trashed) has no `trashed_items` row and stays listed.
              trashed: principal.status === "disabled" && (await deps.isInTrash(principal.id)),
            }))
        )
      )
        .filter((entry) => !entry.trashed)
        .map((entry) => entry.principal);
      const humanPrincipals = nonTrashedHumanPrincipals;
      const seededOwnerPrincipalId = await deps.ownerPrincipalId;

      // O(n) repo round trips, n = human principal count. Unbounded by a caller-controlled
      // collection (this is an operator-managed roster, not member/content scale — the same
      // assumption `identity/INFO.md` and `resolveEffectivePermissions` already make) — no cap
      // needed this pass; a future pagination pass would mirror `MemberRepoPort.list`'s
      // afterId/limit shape if this workspace's operator count ever grows unexpectedly large.
      const users = await Promise.all(
        humanPrincipals.map(async (principal) => {
          const userRow = await deps.userRepo.findByPrincipalId({
            workspaceId: deps.workspaceId,
            principalId: principal.id,
          });
          // Every kind='user' principal has a paired users row by construction
          // (CREATE_USER/SEED_FIRST_BOOT's atomicity guarantee) — this null
          // check is defensive, not an expected runtime path.
          if (!userRow) return null;

          const [roleLinks, policyLinks] = await Promise.all([
            deps.principalRoleRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id }),
            deps.principalPolicyRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId: principal.id }),
          ]);

          const protection = await userAccountProtection({ deps: identityServiceDepsFrom(deps), workspaceId: deps.workspaceId, principalId: principal.id });
          // The bootstrap owner is still found by login at reboot; offer rename only when safe.
          return { ...protection, canRename: principal.id !== seededOwnerPrincipalId, ...toAdminUserResponse({
            principal,
            user: userRow,
            roleIds: roleLinks.map((link) => link.roleId),
            policyIds: policyLinks.map((link) => link.policyId),
          }) };
        })
      );

      res.json({ users: users.filter((user): user is NonNullable<typeof user> => user !== null) });
    } catch (error) {
      sendAdminFailure({ res, error }, { operation: "routes/users/list", code: "INTERNAL_ERROR" });
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { assertActiveOwnerFloor, principalHoldsOwnerWildcard } from "#src/features/identity/delete-user-service";
import type { Response } from "express";

import { IdentityForbiddenError, IdentityNotFoundError, IdentityValidationError, OwnerRequiredError } from "@jini-ai/user-management";
import { removePolicyPermission } from "@jini-ai/user-management/server";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { identityServiceDepsFrom, type UsersRouteRegistrar } from "./deps.js";

/** Maps this route's thrown error types onto the admin error envelope — the same mapping
 *  `delete-policy.ts` uses, minus `IdentityConflictError`: `removePolicyPermission` has no
 *  reference guard to violate (a permission row is a leaf, nothing points at it).
 *  @complexity O(1). */
function sendRemovePolicyPermissionError(res: Response, err: unknown): void {
  if (err instanceof OwnerRequiredError) {
    res.status(409).json({ error: err.message, code: "OWNER_REQUIRED" });
    return;
  }
  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({
      error: err.message,
      code: "FORBIDDEN",
      details: { permission: err.permission, reason: err.reason },
    });
    return;
  }
  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/remove-policy-permission", code: "INTERNAL_ERROR" });
}

/**
 * DELETE policies/:policyId/permissions/:policyPermissionId — `REMOVE_POLICY_PERMISSION` (OQ-10),
 * the inverse of `write-policy-permission.ts` and the route that closes the gap `Roles.tsx`'s own
 * header comment flagged: until now a policy's permission set was append-only, and the only way to
 * shrink it was `DELETE_POLICY` + recreate — which INV-09 refuses outright the moment any role or
 * principal references the policy.
 *
 * Gated by `role.manage`, exactly as the ADD route is. A built-in or frozen parent policy is
 * refused `VALIDATION_ERROR` (INV-06/AC-26); a permission id that is absent — or that belongs to a
 * different policy — is `RESOURCE_NOT_FOUND`, never a silent no-op success (the service proves
 * membership from the policy's own rows before deleting).
 *
 * Returns 204, matching `delete-policy.ts`'s convention for a delete with nothing to echo back.
 */
export const registerAdminPolicyPermissionRemoveRoute: UsersRouteRegistrar = (app, deps) => {
  app.delete(
    "/api/admin/v1/workspaces/:workspaceId/policies/:policyId/permissions/:policyPermissionId",
    async (req, res) => {
      if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }

      try {
        const caller = getAuthedPrincipal(res);

        const serviceDeps = identityServiceDepsFrom(deps);
        await deps.transactions.run({ workspaceId: deps.workspaceId, execute: async () => {
          const rows = await deps.policyPermissionRepo.listByPolicyId({ workspaceId: deps.workspaceId, policyId: String(req.params.policyId ?? "") });
          const removed = rows.find(row => row.id === String(req.params.policyPermissionId ?? ""));
          if (removed?.permission === "*" && removed.resourceType == null && removed.constraintJson == null
              && !await principalHoldsOwnerWildcard({ deps: serviceDeps, workspaceId: deps.workspaceId, principalId: caller.id })) {
            throw new OwnerRequiredError({ message: "only an owner can modify an owner principal" });
          }
          await removePolicyPermission({
            deps: serviceDeps,
            input: {
              workspaceId: deps.workspaceId,
              callerPrincipalId: caller.id,
              policyId: String(req.params.policyId ?? ""),
              policyPermissionId: String(req.params.policyPermissionId ?? ""),
            },
          });
          await assertActiveOwnerFloor({ deps: serviceDeps, workspaceId: deps.workspaceId });
        } });

        res.status(204).send();
      } catch (err) {
        sendRemovePolicyPermissionError(res, err);
      }
    }
  );
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import { assertUserAccountAction, SelfDeleteError } from "#src/features/identity/delete-user-service";
import type { Response } from "express";

import { IdentityForbiddenError, IdentityNotFoundError, IdentityValidationError, OwnerRequiredError } from "@jini-ai/user-management";
import { resetUserPassword } from "@jini-ai/user-management/server";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { UserInTrashError } from "#src/features/identity/delete-user-service";
import { identityServiceDepsFrom, type UsersRouteRegistrar } from "./deps.js";

/** Maps this route's thrown error types onto the admin error envelope. Exported for direct-invoke
 *  coverage: `assertUserAccountAction` deliberately exempts `reset-password` from its self-target
 *  refusal (the owner may reset its own password), so no current service path raises
 *  `SelfDeleteError` here — the mapping stays as defence-in-depth should that exemption change.
 *  @complexity O(1). */
export function sendResetPasswordError(res: Response, err: unknown): void {
  if (err instanceof UserInTrashError) {
    res.status(409).json({ error: err.message, code: "USER_IN_TRASH" });
    return;
  }
  if (err instanceof SelfDeleteError) {
    res.status(409).json({ error: err.message, code: "SELF_DELETE" });
    return;
  }
  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof OwnerRequiredError) {
    res.status(409).json({ error: err.message, code: "OWNER_REQUIRED" });
    return;
  }
  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/reset-password", code: "INTERNAL_ERROR" });
}

/**
 * POST users/:principalId/reset-password — `RESET_USER_PASSWORD` (SPEC-006 0.6.0, REQ-17). Gated
 * by **`user.manage`** only (stricter than `UPDATE_USER`). No response body — the raw new password
 * is never echoed back (INV-05); revokes every one of the target's active sessions (AC-29). Refuses
 * a THIRD-PARTY caller resetting the seeded owner's password (REQ-11/REQ-13) — the owner may still
 * reset its own — see `identity/admin-crud-service.ts`'s `resetUserPassword` for the full contract;
 * `seededOwnerPrincipalId` is resolved here exactly as `disable.ts` resolves it for
 * `DISABLE_PRINCIPAL`.
 */
export const registerAdminUserResetPasswordRoute: UsersRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/users/:principalId/reset-password", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const caller = getAuthedPrincipal(res);
      const seededOwnerPrincipalId = await deps.ownerPrincipalId;
      const principalId = String(req.params.principalId ?? "");

      // OWNER DECISION 2026-09-24 (delete-user plan v2, decision 7) — refuse BEFORE the transition;
      // see `enable.ts`'s identical guard for why.
      if (await deps.isInTrash(principalId)) {
        throw new UserInTrashError("this user is in the Trash; restore them first");
      }

      const body = (req.body ?? {}) as Record<string, unknown>;
      await deps.transactions.run({ workspaceId: deps.workspaceId, execute: async () => {
        const serviceDeps = identityServiceDepsFrom(deps);
        await assertUserAccountAction({ deps: serviceDeps, workspaceId: deps.workspaceId, principalId, action: "reset-password" },
          { callerPrincipalId: caller.id, seededOwnerPrincipalId });
        return resetUserPassword({
          deps: serviceDeps,
          input: {
            workspaceId: deps.workspaceId,
            callerPrincipalId: caller.id,
            principalId,
            password: String(body.password ?? ""),
            seededOwnerPrincipalId,
          },
        });
      } });

      res.status(204).send();
    } catch (err) {
      sendResetPasswordError(res, err);
    }
  });
};

