import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Response } from "express";

import { IdentityConflictError, IdentityValidationError, IdentityForbiddenError, IdentityNotFoundError, OwnerRequiredError } from "@jini-ai/user-management";
import { updateUser } from "@jini-ai/user-management/server";
import { toAdminUserResponse } from "#src/server/inbound/admin-http/http/users";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { UserInTrashError } from "#src/features/identity/delete-user-service";
import { identityServiceDepsFrom, type UsersRouteDeps, type UsersRouteRegistrar } from "./deps.js";

/** This route's writable PATCH fields — `undefined` means "leave unchanged" — read off an
 *  untyped body in one place. @complexity O(1). */
function parseUserUpdateBody(rawBody: unknown): { email: string | undefined; username: string | undefined } {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  if (body.username !== undefined && typeof body.username !== "string") {
    throw new IdentityValidationError({ message: "username must be a string" });
  }
  return { email: body.email !== undefined ? String(body.email) : undefined, username: body.username as string | undefined };
}

/**
 * Loads the principal record plus role/policy links for `principalId` and builds the admin
 * response shape. `updateUser` returns only the updated `UserRecord`; the response also needs the
 * paired `PrincipalRecord`, so this re-fetches it — a missing principal here is defensive, not an
 * expected runtime path (the same id `updateUser` itself just succeeded against).
 *
 * @complexity O(1) plus three repo reads.
 */
async function assembleUpdatedUserResponse(deps: UsersRouteDeps, principalId: string, user: Parameters<typeof toAdminUserResponse>[0]["user"]) {
  const principal = await deps.principalRepo.findById({ workspaceId: deps.workspaceId, id: principalId });
  if (!principal) throw new IdentityNotFoundError({ message: `principal '${principalId}' was not found` });
  const [roleLinks, policyLinks] = await Promise.all([
    deps.principalRoleRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId }),
    deps.principalPolicyRepo.listByPrincipalId({ workspaceId: deps.workspaceId, principalId }),
  ]);
  return toAdminUserResponse({
    principal,
    user,
    roleIds: roleLinks.map((link) => link.roleId),
    policyIds: policyLinks.map((link) => link.policyId),
  });
}

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendUserUpdateError(res: Response, err: unknown): void {
  if (err instanceof IdentityConflictError) {
    res.status(409).json({ error: err.message, code: err.code ?? "RESOURCE_CONFLICT", details: { field: "username" } });
    return;
  }
  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof UserInTrashError) {
    res.status(409).json({ error: err.message, code: "USER_IN_TRASH" });
    return;
  }
  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({ error: err.message, code: "FORBIDDEN", details: { permission: err.permission, reason: err.reason } });
    return;
  }
  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  if (err instanceof OwnerRequiredError) {
    res.status(409).json({ error: err.message, code: "OWNER_REQUIRED" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/update", code: "INTERNAL_ERROR" });
}

/**
 * PATCH users/:principalId — `UPDATE_USER` (SPEC-006 0.6.0, REQ-16). Gated by `user.manage`;
 * existing self-profile edits also accept `member.manage`. Only owners may edit owner targets.
 * Username changes require `user.manage`; other unknown fields, including password, stay ignored.
 */
export const registerAdminUserUpdateRoute: UsersRouteRegistrar = (app, deps) => {
  app.patch("/api/admin/v1/workspaces/:workspaceId/users/:principalId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const caller = getAuthedPrincipal(res);
      const principalId = String(req.params.principalId ?? "");

      // OWNER DECISION 2026-09-24 (delete-user plan v2, decision 7) — refuse BEFORE the transition;
      // see `enable.ts`'s identical guard for why.
      if (await deps.isInTrash(principalId)) {
        throw new UserInTrashError("this user is in the Trash; restore them first");
      }

      const serviceDeps = identityServiceDepsFrom(deps);
      const { email, username } = parseUserUpdateBody(req.body);
      const { user } = await deps.transactions.run({
        workspaceId: deps.workspaceId,
        execute: async () => {
          // Jini's email setter clears an omitted value. HTTP PATCH retains an omitted field;
          // read and write in the same identity transaction so a competing edit cannot be lost.
          const current = email === undefined
            ? await deps.userRepo.findByPrincipalId({ workspaceId: deps.workspaceId, principalId })
            : undefined;
          return updateUser({
            deps: serviceDeps,
            input: { workspaceId: deps.workspaceId, callerPrincipalId: caller.id, principalId },
          }, { email: email === undefined ? current?.email : email, username });
        },
      });

      res.json({ user: await assembleUpdatedUserResponse(deps, principalId, user) });
    } catch (err) {
      sendUserUpdateError(res, err);
    }
  });
};

import { sendAdminFailure } from "#src/server/inbound/admin-http/routes/system/site-share-errors";
import type { Request, Response } from "express";

import { GrantExceedsIssuerError, IdentityForbiddenError, IdentityNotFoundError, IdentityValidationError, PermissionUnknownError } from "@jini-ai/user-management";
import { writePolicyPermission } from "@jini-ai/user-management/server";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import { identityServiceDepsFrom, type UsersRouteDeps, type UsersRouteRegistrar } from "./deps.js";

/** Maps `writePolicyPermission`'s thrown error types onto the admin error envelope. `req` is needed
 *  only for `PermissionUnknownError`'s `details.permission` echo.
 *  @complexity O(1). */
function sendWritePolicyPermissionError(res: Response, req: Request, err: unknown): void {
  if (err instanceof IdentityForbiddenError) {
    res.status(403).json({
      error: err.message,
      code: "FORBIDDEN",
      details: { permission: err.permission, reason: err.reason },
    });
    return;
  }
  if (err instanceof GrantExceedsIssuerError) {
    res.status(403).json({
      error: err.message,
      code: "GRANT_EXCEEDS_ISSUER",
      details: { offendingPermissions: err.offendingPermissions },
    });
    return;
  }
  if (err instanceof PermissionUnknownError) {
    res.status(400).json({ error: err.message, code: "PERMISSION_UNKNOWN", details: { permission: req.body?.permission } });
    return;
  }
  if (err instanceof IdentityValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof IdentityNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/users/write-policy-permission", code: "INTERNAL_ERROR" });
}

/** Coerce the HTTP payload while leaving grant validation to the identity service. */
function writeRequestedPolicyPermission(
  { deps, callerPrincipalId, policyId, body }: {
    deps: UsersRouteDeps;
    callerPrincipalId: string;
    policyId: unknown;
    body: Record<string, unknown>;
  },
  _options = {},
) {
  return writePolicyPermission({
    deps: identityServiceDepsFrom(deps),
    input: {
      workspaceId: deps.workspaceId,
      callerPrincipalId,
      policyId: String(policyId ?? ""),
      permission: String(body.permission ?? ""),
    },
  }, {
    resourceType: body.resourceType !== undefined ? String(body.resourceType) : undefined,
    constraintJson: body.constraintJson !== undefined ? String(body.constraintJson) : undefined,
  });
}

/**
 * POST policies/:policyId/permissions — `WRITE_POLICY_PERMISSION` (SPEC-006 0.6.0, INV-07 — first
 * HTTP route for a transition specified since v0.5.3, AC-32). Gated by `role.manage`; refuses an
 * unregistered permission (`PERMISSION_UNKNOWN`), a built-in or frozen parent policy
 * (`VALIDATION_ERROR`, INV-06/AC-26), or a permission the caller does not hold unconstrained
 * (`GRANT_EXCEEDS_ISSUER`, INV-07/AC-24).
 */
export const registerAdminPolicyWritePermissionRoute: UsersRouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/policies/:policyId/permissions", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const caller = getAuthedPrincipal(res);
      const body = (req.body ?? {}) as Record<string, unknown>;
      if (body.permission === "publish.backstop" || body.permission === "publish_content.backstop") {
        res.status(403).json({ error: "Manual publishing is reserved for the owner and built-in admins; it cannot be granted to another role.", code: "FORBIDDEN" });
        return;
      }

      const { policyPermission } = await writeRequestedPolicyPermission({
        deps, callerPrincipalId: caller.id, policyId: req.params.policyId, body,
      });

      res.status(201).json({ policyPermission });
    } catch (err) {
      sendWritePolicyPermissionError(res, req, err);
    }
  });
};

import { toWhereUsedResponse } from "@jini-ai/cms/widgets";
import type { Response } from "express";

import { buildWidgetsDeps, buildWidgetsRegionDeps } from "#src/features/widgets/deps";
import { parseWidgetAreaPayload, parseWidgetInstancePayload } from "@jini-ai/cms/widgets";
import { insertWidgetEmbed, removeWidgetEmbed } from "@jini-ai/cms/widgets";
import { mutateWidgetAreaPlacements } from "@jini-ai/cms/widgets";
import { createWidgetInstance } from "@jini-ai/cms/widgets";
import { WidgetAreaNotFoundError } from "@jini-ai/cms/widgets";
import { WIDGET_CONTENT_TYPE } from "@jini-ai/cms/widgets";
import type { WidgetPlacementNode, WidgetTypeKey } from "@jini-ai/cms/widgets";
import {
  mapWidgetErrorToResponse,
  requireWidgetsPermissionOrRespond,
  toAdminWidgetResponse,
  widgetErrorToResponse,
} from "#src/server/inbound/admin-http/http/widgets";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps, RouteRegistrar } from "#src/server/routes/types";

/**
 * @file The `widgets.place` / `widgets.create` / `widgets.remove` / `widgets.diagnose` AI tool
 * surface (SPEC-043 REQ-35/44, ADR-047 §5). Thin gateway clients — every call maps 1:1 to the SAME
 * C-005/C-006/C-007 domain functions the human admin routes use, gated by the SAME `widgets.*`
 * permission check (INV-07: an agent's effective permission is always `grant ∩ delegator`,
 * unchanged by this feature). No bespoke AI-agent transport is invented here — REQ-35's "distinct,
 * explicit gateway operations" requirement is about `place` vs `create` being two DISTINCT,
 * unambiguous operations (never one "add widget" call that could mean either), not about a
 * separate wire protocol from the ordinary admin HTTP surface; ADR-047 §5 phrases these as "thin
 * gateway/tool clients, the same shape as ADR-029 §8's `navigation.update`," which is itself an
 * ordinary admin route.
 *
 * Each tool call is ONE atomic operation (unlike the human UI's two-step "create, then place"
 * flow over separate routes) — an agent tool call for "place this widget in the footer" should not
 * require two round-trips.
 */

type PlaceTarget =
  | { readonly kind: "region"; readonly regionKey: string; readonly baseVersion: number }
  | { readonly kind: "embed"; readonly hostEntryId: string; readonly baseVersion: number };

/** Appends `widgetEntryId` to a region's CURRENT placement list (loaded fresh) and writes the
 * whole list back, per REQ-15's whole-document discipline — never a partial patch. */
async function placeIntoRegion(deps: RouteDeps, workspaceId: string, actor: { principalId: string; kind: string }, regionKey: string, baseVersion: number, widgetEntryId: string) {
  const binding = await deps.widgetBindingRepo.findByRegion({ workspaceId, regionKey });
  // Round-2 external-audit fix (2026-07-21, agy + Opus 4.8, independently converged): a bare Error
  // isn't recognized by widgetErrorToResponse, so an unbound region 500'd instead of the same 404
  // WIDGETS_AREA_NOT_FOUND region-mutate-placements.ts already returns for this exact condition.
  if (!binding) throw new WidgetAreaNotFoundError({ message: `region '${regionKey}' is not bound` });
  const areaEntry = await deps.entryRepo.findById({ workspaceId, id: binding.areaEntryId });
  if (!areaEntry) throw new WidgetAreaNotFoundError({ message: `region area entry for '${regionKey}' was not found` });
  const currentPlacements = parseWidgetAreaPayload({ fieldsJson: areaEntry.fieldsJson }).doc.placements;
  const nextPlacements: WidgetPlacementNode[] = [...currentPlacements, { placementId: deps.idGen.newId(), widgetEntryId, enabled: true }];

  return mutateWidgetAreaPlacements({
    deps: buildWidgetsRegionDeps(deps),
    input: { workspaceId, actor, areaEntryId: binding.areaEntryId, baseVersion, placements: nextPlacements },
  });
}

async function placeTarget(deps: RouteDeps, workspaceId: string, actor: { principalId: string; kind: string }, target: PlaceTarget, widgetEntryId: string) {
  if (target.kind === "region") {
    return placeIntoRegion(deps, workspaceId, actor, target.regionKey, target.baseVersion, widgetEntryId);
  }
  return insertWidgetEmbed({
    deps: buildWidgetsDeps(deps),
    input: { workspaceId, actor, hostEntryId: target.hostEntryId, baseVersion: target.baseVersion, widgetEntryId },
  });
}

function readTarget(body: Record<string, unknown>): PlaceTarget | null {
  const target = body.target as Record<string, unknown> | undefined;
  if (!target || typeof target.baseVersion !== "number") return null;
  if (target.kind === "region" && typeof target.regionKey === "string") {
    return { kind: "region", regionKey: target.regionKey, baseVersion: target.baseVersion };
  }
  if (target.kind === "embed" && typeof target.hostEntryId === "string") {
    return { kind: "embed", hostEntryId: target.hostEntryId, baseVersion: target.baseVersion };
  }
  return null;
}

function respondBadTarget(res: Response): void {
  res.status(400).json({
    error: "target must be { kind: 'region', regionKey, baseVersion } or { kind: 'embed', hostEntryId, baseVersion }",
    code: "VALIDATION_ERROR",
  });
}

/** This tool's validated body shape: a resolved `target` plus the new instance's fields.
 *  `widgetType` is cast, not validated, against the real `WidgetTypeKey` union here — same as the
 *  inline code this replaces, `createWidgetInstance` (`getWidgetTypeRegistration`) is what rejects
 *  an unregistered type at runtime, with its own `WidgetTypeUnregisteredError`. */
type CreateToolInput = { target: PlaceTarget; widgetType: WidgetTypeKey; title: string; config: Record<string, unknown> };

/**
 * Parses+validates `widgets.create`'s body in one place — target resolution (via `readTarget`),
 * `widgetType`/`title` presence, and the `config` object-or-default normalization all collapse into
 * one null-means-invalid result instead of three separate inline checks.
 *
 * @complexity O(1).
 */
function parseCreateToolInput(body: Record<string, unknown>): CreateToolInput | null {
  const target = readTarget(body);
  if (!target || typeof body.widgetType !== "string" || typeof body.title !== "string") return null;
  return {
    target,
    widgetType: body.widgetType as WidgetTypeKey,
    title: body.title,
    config: typeof body.config === "object" && body.config !== null ? (body.config as Record<string, unknown>) : {},
  };
}

/** Removes an embed-hosted placement — thin pass-through to `removeWidgetEmbed`, kept symmetric
 *  with `removeRegionPlacement` below. @complexity O(1). */
async function removeEmbedPlacement(
  deps: RouteDeps,
  workspaceId: string,
  actor: { principalId: string; kind: string },
  target: Extract<PlaceTarget, { kind: "embed" }>,
  placementId: string
) {
  return removeWidgetEmbed({
    deps: buildWidgetsDeps(deps),
    input: { workspaceId, actor, hostEntryId: target.hostEntryId, baseVersion: target.baseVersion, placementId },
  });
}

/** Removes a region-bound placement by loading the CURRENT placement list and writing it back
 *  without `placementId`, matching `placeIntoRegion`'s whole-document discipline (REQ-15).
 *  @complexity O(placements in the region). */
async function removeRegionPlacement(
  deps: RouteDeps,
  workspaceId: string,
  actor: { principalId: string; kind: string },
  target: Extract<PlaceTarget, { kind: "region" }>,
  placementId: string
) {
  const binding = await deps.widgetBindingRepo.findByRegion({ workspaceId, regionKey: target.regionKey });
  if (!binding) throw new WidgetAreaNotFoundError({ message: `region '${target.regionKey}' is not bound` });
  const areaEntry = await deps.entryRepo.findById({ workspaceId, id: binding.areaEntryId });
  if (!areaEntry) throw new WidgetAreaNotFoundError({ message: `region area entry for '${target.regionKey}' was not found` });
  const nextPlacements = parseWidgetAreaPayload({ fieldsJson: areaEntry.fieldsJson }).doc.placements.filter((p) => p.placementId !== placementId);
  return mutateWidgetAreaPlacements({
    deps: buildWidgetsRegionDeps(deps),
    input: { workspaceId, actor, areaEntryId: binding.areaEntryId, baseVersion: target.baseVersion, placements: nextPlacements },
  });
}

/** Dispatches to the embed or region removal path — mirrors `placeTarget`'s own dispatch shape.
 *  @complexity O(1) plus whichever branch's own cost. */
async function removePlacement(
  deps: RouteDeps,
  workspaceId: string,
  actor: { principalId: string; kind: string },
  target: PlaceTarget,
  placementId: string
) {
  if (target.kind === "embed") {
    return removeEmbedPlacement(deps, workspaceId, actor, target, placementId);
  }
  return removeRegionPlacement(deps, workspaceId, actor, target, placementId);
}

/** Resolves `widgets.diagnose`'s exists/status pair for an already-fetched entry — a bare
 *  `Awaited<ReturnType<...findById>>` type keeps this tied to the repo port's own return shape
 *  rather than a hand-rolled interface. @complexity O(1). */
function resolveWidgetStatus(entry: Awaited<ReturnType<RouteDeps["entryRepo"]["findById"]>>): {
  exists: boolean;
  status: string | null;
} {
  const isWidget = Boolean(entry) && entry?.type === WIDGET_CONTENT_TYPE;
  if (!isWidget || !entry) return { exists: isWidget, status: null };
  // Fable adversarial-review fix (2026-07-21, Finding B): diagnosing a real entry id that is NOT a
  // widget instance (wrong content type, or a widget row with a malformed payload) used to 500 via
  // an uncaught `parseWidgetInstancePayload` throw — `getWidgetInstance` already guards the same
  // case with an `entry.type` check; this mirrors it instead of parsing blind.
  try {
    return { exists: true, status: parseWidgetInstancePayload({ fieldsJson: entry.fieldsJson }).status };
  } catch {
    return { exists: true, status: null };
  }
}

/** `widgets.place` — reference an EXISTING widget instance into a target. Distinct from
 * `widgets.create` (REQ-35, AC-25): this call never creates a new instance. */
const registerPlaceTool: RouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/widgets/tools/place", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    const body = req.body ?? {};
    const target = readTarget(body);
    if (!target || typeof body.widgetInstanceId !== "string") {
      respondBadTarget(res);
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const result = await placeTarget(deps, deps.workspaceId, { principalId: principal.id, kind: "user" }, target, body.widgetInstanceId);
      res.status(200).json({ tool: "widgets.place", result });
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

/** `widgets.create` — create a NEW widget instance and place it in one call. Distinct from
 * `widgets.place` (REQ-35, AC-25). */
const registerCreateTool: RouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/widgets/tools/create", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    const body = req.body ?? {};
    const parsed = parseCreateToolInput(body);
    if (!parsed) {
      respondBadTarget(res);
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const actor = { principalId: principal.id, kind: "user" };
      const { instance } = await createWidgetInstance({
        deps: buildWidgetsDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          actor,
          widgetType: parsed.widgetType,
          title: parsed.title,
          config: parsed.config,
        },
      });

      try {
        const placeResult = await placeTarget(deps, deps.workspaceId, actor, parsed.target, instance.id);
        res.status(201).json({ tool: "widgets.create", widget: toAdminWidgetResponse(instance).widget, result: placeResult });
      } catch (placeErr) {
        // Finding D (Fable adversarial-review fix, 2026-07-21): placement failing AFTER the
        // instance was already created must not silently drop the created id — the instance is
        // real and persisted regardless of whether placement succeeded. Without this, a caller
        // (especially a retrying AI agent) sees only an error, has no way to know the instance
        // already exists, and mints a duplicate via a second `widgets.create` call instead of
        // retrying placement with `widgets.place`.
        const { status, body: errorBody } = widgetErrorToResponse(placeErr, { tracker: res.locals?.adminFailureTracker });
        res.status(status).json({ tool: "widgets.create", widget: toAdminWidgetResponse(instance).widget, placementFailed: true, ...errorBody });
      }
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

/** `widgets.remove` — remove a PLACEMENT (region entry or embed node), never the widget instance
 * itself (that's `widgets.delete`/`.delete.force` via the ordinary CRUD routes). */
const registerRemoveTool: RouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/widgets/tools/remove", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    const body = req.body ?? {};
    const target = readTarget(body);
    if (!target || typeof body.placementId !== "string") {
      respondBadTarget(res);
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const actor = { principalId: principal.id, kind: "user" };
      const result = await removePlacement(deps, deps.workspaceId, actor, target, body.placementId);
      res.status(200).json({ tool: "widgets.remove", result });
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

/** `widgets.diagnose` — read-only: where-used + broken-reference state for one instance, sourced
 * entirely from the already-queryable `entry_refs` index (ADR-047 §5: "a broken widget reference
 * is already a queryable, first-class state, not new detection logic to build"). */
const registerDiagnoseTool: RouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/widgets/tools/diagnose/:widgetInstanceId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }
    try {
      const principal = await requireWidgetsPermissionOrRespond(deps.authorize, deps.workspaceId, "widgets.read", res);
      if (!principal) return;

      const widgetInstanceId = String(req.params.widgetInstanceId);
      const entry = await deps.entryRepo.findById({ workspaceId: deps.workspaceId, id: widgetInstanceId });
      const { exists, status } = resolveWidgetStatus(entry);
      const refs = await deps.entryRefsRepo.findByTarget({ workspaceId: deps.workspaceId, targetKind: "entry", targetId: widgetInstanceId });
      res.status(200).json({
        tool: "widgets.diagnose",
        exists,
        status,
        whereUsed: toWhereUsedResponse({ refs }, {}),
      });
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

export const registerAdminWidgetAgentToolsRoutes: RouteRegistrar = (app, deps) => {
  registerPlaceTool(app, deps);
  registerCreateTool(app, deps);
  registerRemoveTool(app, deps);
  registerDiagnoseTool(app, deps);
};

import { buildWidgetsDeps } from "#src/features/widgets/deps";
import { createWidgetInstance } from "@jini-ai/cms/widgets";
import { mapWidgetErrorToResponse, toAdminWidgetResponse } from "#src/server/inbound/admin-http/http/widgets";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { WidgetTypeKey } from "@jini-ai/cms/widgets";
import type { RouteRegistrar } from "#src/server/routes/types";

/** This route's validated POST body shape, or `null` when `widgetType`/`title` failed validation.
 *  `widgetType` is cast, not validated, against the real `WidgetTypeKey` union here —
 *  `createWidgetInstance` (`getWidgetTypeRegistration`) is what rejects an unregistered type at
 *  runtime. @complexity O(1). */
function parseWidgetCreateBody(rawBody: unknown): {
  widgetType: WidgetTypeKey;
  title: string;
  config: Record<string, unknown>;
  slug: string | undefined;
} | null {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  if (typeof body.widgetType !== "string" || typeof body.title !== "string") return null;
  return {
    widgetType: body.widgetType as WidgetTypeKey,
    title: body.title,
    config: typeof body.config === "object" && body.config !== null ? (body.config as Record<string, unknown>) : {},
    slug: typeof body.slug === "string" ? body.slug : undefined,
  };
}

/**
 * POST a new widget instance (SPEC-043 REQ-01/02/03), `widgets.create`-gated (enforced inside
 * `createWidgetInstance` itself — REQ-40 requires the SAME gate for human and AI-originated calls,
 * so the domain function owns the check, not this route). Backs both `ui.spec.md`'s
 * `WidgetInstanceEditorScreen` create flow and the `widgets.create` half of `WidgetPickerDialog`'s
 * "create new" path (REQ-33/35).
 */
export const registerAdminWidgetCreateRoute: RouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/widgets", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const parsedBody = parseWidgetCreateBody(req.body);
    if (!parsedBody) {
      res.status(400).json({ error: "widgetType and title are required strings", code: "VALIDATION_ERROR" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const { instance } = await createWidgetInstance({
        deps: buildWidgetsDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          actor: { principalId: principal.id },
          ...parsedBody,
        },
      });
      res.status(201).json(toAdminWidgetResponse(instance));
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

import { buildWidgetsDeps } from "#src/features/widgets/deps";
import { insertWidgetEmbed } from "@jini-ai/cms/widgets";
import { mapWidgetErrorToResponse } from "#src/server/inbound/admin-http/http/widgets";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteRegistrar } from "#src/server/routes/types";

/**
 * POST insert a `widgetEmbed` node into a host entry's body (SPEC-043 REQ-44/45, ADR-047 Debate
 * Fold-In Amendment 6) — the server-side, no-live-editor-required mutation path. `widgets.place`-gated.
 */
export const registerAdminWidgetEmbedInsertRoute: RouteRegistrar = (app, deps) => {
  app.post("/api/admin/v1/workspaces/:workspaceId/entries/:hostEntryId/widget-embeds", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const body = req.body ?? {};
    if (typeof body.baseVersion !== "number" || typeof body.widgetEntryId !== "string") {
      res.status(400).json({ error: "baseVersion and widgetEntryId are required", code: "VALIDATION_ERROR" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
