import { parseWidgetAreaPayload, parseWidgetInstancePayload, toWidgetAreaEntry } from "@jini-ai/cms/widgets";
import { WIDGET_AREA_CONTENT_TYPE, WIDGET_CONTENT_TYPE } from "@jini-ai/cms/widgets";
import { mapWidgetErrorToResponse, requireWidgetsPermissionOrRespond, toAdminWidgetAreaResponse } from "#src/server/inbound/admin-http/http/widgets";
import type { RouteRegistrar } from "#src/server/routes/types";

/**
 * GET one region's area entry, with each placement's `widgetTitle`/`widgetType` resolved —
 * `ui.spec.md` §3.7's `RegionPlacementEditorScreen` loaded state ("an operator must be able to
 * identify what's placed without a second lookup", §5).
 */
export const registerAdminWidgetRegionGetRoute: RouteRegistrar = (app, deps) => {
  app.get("/api/admin/v1/workspaces/:workspaceId/widgets/regions/:regionKey", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = await requireWidgetsPermissionOrRespond(deps.authorize, deps.workspaceId, "widgets.read", res);
      if (!principal) return;

      const binding = await deps.widgetBindingRepo.findByRegion({ workspaceId: deps.workspaceId, regionKey: String(req.params.regionKey) });
      if (!binding) {
        res.status(404).json({ error: `region '${req.params.regionKey}' is not bound`, code: "WIDGETS_AREA_NOT_FOUND" });
        return;
      }
      const areaEntry = await deps.entryRepo.findById({ workspaceId: deps.workspaceId, id: binding.areaEntryId });
      if (!areaEntry || areaEntry.type !== WIDGET_AREA_CONTENT_TYPE) {
        res.status(404).json({ error: `region area entry was not found`, code: "WIDGETS_AREA_NOT_FOUND" });
        return;
      }

      const area = toWidgetAreaEntry({ entry: areaEntry });
      const doc = parseWidgetAreaPayload({ fieldsJson: areaEntry.fieldsJson }).doc;
      const placements = await Promise.all(
        doc.placements.map(async (placement) => {
          const widget = await deps.entryRepo.findById({ workspaceId: deps.workspaceId, id: placement.widgetEntryId });
          const payload = widget && widget.type === WIDGET_CONTENT_TYPE ? parseWidgetInstancePayload({ fieldsJson: widget.fieldsJson }) : null;
          return {
            ...placement,
            widgetTitle: widget?.title ?? null,
            widgetType: payload?.widgetType ?? null,
            broken: !widget || !payload || payload.status !== "active",
          };
        })
      );

      res.status(200).json({ ...toAdminWidgetAreaResponse(area), placements });
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

import type { JsonObject } from "@jini-ai/core/primitives";
import { buildWidgetsRegionDeps } from "#src/features/widgets/deps";
import { mutateWidgetAreaPlacements } from "@jini-ai/cms/widgets";
import type { WidgetPlacementNode } from "@jini-ai/cms/widgets";
import { mapWidgetErrorToResponse, toAdminWidgetAreaResponse } from "#src/server/inbound/admin-http/http/widgets";
import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteRegistrar } from "#src/server/routes/types";

function isPlacementShape(value: unknown): value is { placementId: string; widgetEntryId: string; enabled: boolean; content?: JsonObject } {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  if (typeof v.placementId !== "string" || typeof v.widgetEntryId !== "string" || typeof v.enabled !== "boolean") return false;
  return v.content === undefined || (typeof v.content === "object" && v.content !== null && !Array.isArray(v.content));
}

/**
 * Fable adversarial-review fix (2026-07-21, Finding H): the route previously only checked
 * `Array.isArray(body.placements)` — each element's shape was never validated, so client-supplied
 * duplicate `placementId`s and arbitrary extra properties passed straight through into the stored
 * area doc verbatim. Validates every element's shape, rejects duplicate `placementId`s (it is meant
 * to be a stable, unique locator — `entry_refs`' `fieldPath` and reorder/diagnostics all address a
 * placement by it), and returns a NORMALIZED array (the three reference fields and optional content) so nothing
 * extra a client sends ends up persisted. Returns `null` on any violation.
 */
export function parseWidgetRegionPlacements({ raw }: { raw: readonly unknown[] }, _optional: Record<string, never> = {}): WidgetPlacementNode[] | null {
  const placements: WidgetPlacementNode[] = [];
  const seenIds = new Set<string>();
  for (const item of raw) {
    if (!isPlacementShape(item)) return null;
    if (seenIds.has(item.placementId)) return null;
    seenIds.add(item.placementId);
    placements.push({ placementId: item.placementId, widgetEntryId: item.widgetEntryId, enabled: item.enabled, ...(item.content !== undefined ? { content: item.content } : {}) });
  }
  return placements;
}

/**
 * PUT a region's whole placement list (SPEC-043 REQ-15/16), `widgets.place`-gated. Always a
 * whole-document, version-guarded write (INV-03) — never a per-placement patch endpoint, matching
 * `ui.spec.md` §4.6/§4.7's single `onSave` event over the full `placements` array.
 */
export const registerAdminWidgetRegionMutatePlacementsRoute: RouteRegistrar = (app, deps) => {
  app.put("/api/admin/v1/workspaces/:workspaceId/widgets/regions/:regionKey", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    const body = req.body ?? {};
    if (typeof body.baseVersion !== "number" || !Array.isArray(body.placements)) {
      res.status(400).json({ error: "baseVersion and placements[] are required", code: "VALIDATION_ERROR" });
      return;
    }
    const placements = parseWidgetRegionPlacements({ raw: body.placements });
    if (!placements) {
      res.status(400).json({
        error: "each placement must be { placementId: string, widgetEntryId: string, enabled: boolean }, with no duplicate placementId",
        code: "VALIDATION_ERROR",
      });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      const binding = await deps.widgetBindingRepo.findByRegion({ workspaceId: deps.workspaceId, regionKey: String(req.params.regionKey) });
      if (!binding) {
        res.status(404).json({ error: `region '${req.params.regionKey}' is not bound`, code: "WIDGETS_AREA_NOT_FOUND" });
        return;
      }

      const { areaEntry } = await mutateWidgetAreaPlacements({
        deps: buildWidgetsRegionDeps(deps),
        input: {
          workspaceId: deps.workspaceId,
          actor: { principalId: principal.id },
          areaEntryId: binding.areaEntryId,
          baseVersion: body.baseVersion,
          placements,
        },
      });
      res.status(200).json(toAdminWidgetAreaResponse(areaEntry));
    } catch (err) {
      mapWidgetErrorToResponse(err, res);
    }
  });
};

