/** This route's two writable PATCH fields — `undefined` means "leave unchanged" — read off an
 *  untyped body in one place. @complexity O(1). */
function parseWorkspaceUpdateBody(rawBody: unknown): { name: string | undefined; slug: string | undefined } {
  const body = (rawBody ?? {}) as Record<string, unknown>;
  return {
    name: body.name !== undefined ? String(body.name) : undefined,
    slug: body.slug !== undefined ? String(body.slug) : undefined,
  };
}

/** Maps this route's thrown error types onto the admin error envelope. @complexity O(1). */
function sendWorkspaceUpdateError(res: Response, err: unknown): void {
  if (err instanceof WorkspaceValidationError) {
    res.status(400).json({ error: err.message, code: "VALIDATION_ERROR" });
    return;
  }
  if (err instanceof WorkspaceConflictError) {
    res.status(409).json({ error: err.message, code: "RESOURCE_CONFLICT", details: { field: "slug" } });
    return;
  }
  if (err instanceof WorkspaceNotFoundError) {
    res.status(404).json({ error: err.message, code: "RESOURCE_NOT_FOUND" });
    return;
  }
  sendAdminFailure({ res, error: err }, { operation: "routes/workspace/update", code: "INTERNAL_ERROR" });
}

/**
 * PATCH workspaces/:workspaceId — `UPDATE_WORKSPACE` (SPEC-044 REQ-04, AC-05). `:workspaceId` must
 * equal the caller's own workspace (INV-04, checked before authorization, same as `get.ts`). Gated
 * by `workspace.manage`.
 */
export const registerAdminWorkspaceUpdateRoute: WorkspaceRouteRegistrar = (app, deps) => {
  app.patch("/api/admin/v1/workspaces/:workspaceId", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const principal = getAuthedPrincipal(res);
      if (
        !(await authorizeOrRespond(res, deps.authorize, {
          principalId: principal.id,
          permission: "workspace.manage",
          workspaceId: deps.workspaceId,
        }))
      )
        return;

      const { workspace } = await updateWorkspace({
        deps: { repo: deps.workspaceRepo },
        input: {
          id: deps.workspaceId,
          ...parseWorkspaceUpdateBody(req.body),
        },
      });

      res.json({ workspace: toAdminWorkspaceResponse(workspace) });
    } catch (err) {
      sendWorkspaceUpdateError(res, err);
    }
  });
};

import { createRequire } from "node:module";

// ESM has no ambient `require`; `node:sea` is loaded conditionally below (it
// throws outside a single-executable build) and `seaApi()` must stay
// synchronous, so a local `require` is synthesized rather than switching to
// dynamic `import()`.
const require = createRequire(import.meta.url);

export interface SeaApi {
  isSea(): boolean;
  getAsset(key: string): ArrayBuffer;
}

/**
 * @file Single-executable-build (`node:sea`) detection, shared by `admin-static.ts` (serving
 * SEA-embedded assets) and `admin-dev-proxy.ts` (never proxying to Vite from inside a packaged
 * build). Split out of `admin-static.ts` on 2026-09-16 to break the import cycle those two files
 * previously formed: `admin-static.ts` imported `createAdminDevProxyRequestHandler` from
 * `admin-dev-proxy.ts`, which imported `isSeaRuntime` back from `admin-static.ts`. Neither file
 * owns this predicate more than the other, so it now lives here instead of inside either one.
 */

/** Loads node:sea when running inside a single-executable build. */
export function seaApi(): SeaApi | null {
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const sea = require("node:sea") as SeaApi;
    return sea.isSea() ? sea : null;
  } catch {
    return null;
  }
}

/**
 * Whether this process is a packaged single-executable build. `admin-static.ts` and
 * `admin-dev-proxy.ts` both apply the same "SEA always wins" precedence and neither needs its own
 * copy of {@link seaApi}'s try/require dance.
 */
export function isSeaRuntime(): boolean {
  return seaApi() !== null;
}

