import type { Express, Request, Response } from "express";

/**
 * @file `POST /api/federation/reload` — re-admits federated MCP connections an operator authorized
 * AFTER this daemon process already booted, without a restart. See
 * `assistant/mcp-federation/reload.ts` for the coordinator this route is a thin HTTP wrapper over,
 * and that file's own header for the R5 guarantee this route cannot violate: it only ever widens the
 * admitted set with connections that have NEVER been admitted before; an edit to an already-admitted
 * connection is invisible to it, exactly as it was before this route existed.
 *
 * Authenticated by the SAME mechanism as every other route in this process — `agent-daemon-
 * server.ts` mounts `requireAgentDaemonToken()` globally, as the very first `app.use`, before any
 * route (including this one) is registered, and this path is never added to that gate's
 * `exemptPaths`. See `federation-admissions-route.ts`'s identical note, and `daemon-auth.ts`.
 *
 * Failure stays VISIBLE, never silent, per the feature's own hard requirement: a rejection from
 * `deps.reload()` is logged here (this process's own stderr — the channel every other failure in
 * this file's siblings already uses) and reported to the caller as a real, non-200 status, so a
 * caller that awaits this route (today: the public OAuth callback and the admin PUT route, both in
 * the main web server process) can decide whether to surface it, rather than the reload silently
 * doing nothing while the operator is told their connection succeeded. `GET
 * /api/federation/admissions` and its manual restart button (`external-mcp-admissions-rules.ts`)
 * remain the escape hatch either way — this route never removes or downgrades a connection that was
 * already admitted, so a failed reload attempt leaves an operator no worse off than "the new
 * connection needs the same restart it would have needed before this route existed."
 */

export const FEDERATION_RELOAD_PATH = "/api/federation/reload";

export interface FederationReloadRouteDeps {
  /** The coordinator's own `reload()` — see `mcp-federation/reload.ts`. Injected rather than
   *  constructed here so this route stays a pure Express adapter, testable without a real
   *  `ToolRegistry` or a real external MCP connection. */
  readonly reload: () => Promise<{ readonly newlyAdmittedConnectionIds: readonly string[] }>;
}

/**
 * Mounts the reload route.
 *
 * @complexity O(1) plus whatever `deps.reload()` costs (documented on
 * `FederationReloadCoordinator.reload`).
 * @overallScore 100
 */
export function registerFederationReloadRoute(app: Express, deps: FederationReloadRouteDeps): void {
  app.post(FEDERATION_RELOAD_PATH, async (_req: Request, res: Response) => {
    try {
      const result = await deps.reload();
      res.status(200).json({ ok: true, newlyAdmittedConnectionIds: result.newlyAdmittedConnectionIds });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`[agent-daemon] mcp-federation: reload failed — ${message}`);
      res.status(500).json({ ok: false, error: "federation reload failed" });
    }
  });
}

import type { Express } from 'express';
import { z } from 'zod';
import type { ToolAccessChange, ToolAccessStopResult } from '@jini-ai/daemon';

export const TOOL_ACCESS_LOWERING_PATH = '/api/tool-access/lower';
const ids = z.array(z.string().min(1).max(128)).max(32).optional();
const changeSchema = z.object({ agentIds: ids, serverIds: ids, pluginIds: ids }).strict()
  .refine(value => [value.agentIds, value.serverIds, value.pluginIds].some(values => values && values.length > 0));

/** The full daemon bearer gate is mounted by the scope before this route; run credentials cannot
 * call this path. Input never selects a site or principal, only launch snapshots in this scope.
 * @complexity O(n) validated IDs, with a 1 KiB control payload cap and no polling.
 */
export function registerToolAccessLoweringRoute({ app, lower }: {
  app: Pick<Express, 'post'>;
  lower: (required: ToolAccessChange) => Promise<ToolAccessStopResult>;
}, _optional = {}): void {
  app.post(TOOL_ACCESS_LOWERING_PATH, async (req, res) => {
    const parsed = changeSchema.safeParse(req.body);
    if (!parsed.success || Buffer.byteLength(JSON.stringify(req.body)) > 1024) {
      res.status(400).json({ error: 'Tool access changes require agent, server, or plugin IDs in a control payload at most 1 KiB.' }); return;
    }
    try {
      const result = await lower(parsed.data);
      res.status(result.failedRunIds.length === 0 ? 200 : 503).json({ ok: result.failedRunIds.length === 0, ...result });
    } catch {
      res.status(503).json({ ok: false, error: "Couldn't stop affected answers after tool access changed." });
    }
  });
}

import { Liquid, Hash, type TagToken, type Context, type FS } from "liquidjs";

import type { JsonObject } from "@jini-ai/core/primitives";
import { DEFAULT_SITE_TIME_ZONE, normalizeTimeZone } from "@jini-ai/cms/widgets/date-label";
import { lintLiquidTemplate } from "#src/features/theme/liquid-allowlist";
import {
  buildTemplateRenderData,
  renderBlockSeam,
  RENDER_CTX_KEY,
  type SiteRenderContext,
} from "./render.js";
import type { LiquidWorkerInput, LiquidWorkerResult } from "./liquid-sandbox.js";

/**
 * @file The Liquid engine and the render logic `liquid-worker.ts` runs (ADR-020 Tier 2). Split out
 * of the worker entry so the logic is importable: the entry only checks it is inside a
 * `worker_threads` Worker and posts this module's result back, while the V8 coverage of the worker
 * thread itself is suppressed by design (`worker-sandbox.test.ts`). Only ever loaded on the main
 * thread by tests; production loads it inside the isolated worker via `liquid-worker.ts`.
 *
 * Purpose:
 * Owns the Liquid engine construction, the `render_block` custom tag (the
 * seam back into Tovu's trusted component registry — `COMPONENTS`, imported
 * from `render.ts`), and the render-time data shaping that used to live in
 * `render.ts`'s in-process `renderLiquidBody`. Runs a second, defensive
 * allowlist check (`lintLiquidTemplate`) immediately before rendering, in
 * case a template changed on disk after `loadTheme()` validated it.
 *
 * Filesystem hardening: LiquidJS's *default* engine config is not
 * filesystem-inert — verified empirically, `new Liquid()` with no explicit
 * `fs` option reads real files relative to `root: ["."]`. The tag allowlist
 * (`lintLiquidTemplate`) already blocks the only tags that can trigger a
 * file read (`include`/`render`/`layout`/`block`), but this engine is also
 * constructed with an explicit `fs` adapter whose every method reports "not
 * found" — a second, redundant guarantee that holds even if the allowlist
 * had a gap.
 */

/** Reports every path as absent; every LiquidJS `fs` read goes through this and fails closed. */
export const NO_ACCESS_FS: FS = {
  exists: async () => false,
  existsSync: () => false,
  readFile: async (filepath: string) => {
    throw new Error(`filesystem access disabled for theme templates: ${filepath}`);
  },
  readFileSync: (filepath: string) => {
    throw new Error(`filesystem access disabled for theme templates: ${filepath}`);
  },
  resolve: (_dir: string, file: string) => file,
  dirname: () => "",
  sep: "/",
};

/** `{% render_block %}` — the seam back into Tovu's trusted component registry, registered on every engine. */
const RENDER_BLOCK_TAG = {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  parse(this: any, token: TagToken) {
    this.hash = new Hash(token.args);
  },
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  *render(this: any, ctx: Context): Generator<unknown, string, unknown> {
    const props = (yield this.hash.render(ctx)) as JsonObject;
    const siteCtx = ctx.getSync([RENDER_CTX_KEY]) as SiteRenderContext | undefined;
    if (!siteCtx) return `<!-- render_block: no site context -->`;

    // SPEC-043/ADR-047 §2a W-004: `{% render_block region: "footer" %}` — a theme-declared widget
    // region, resolved over the SAME seam as `component:` (ADR-047 §2a: "no new Liquid capability
    // required" — a region is a `render_block` call over a resolved, ordered widget list instead of
    // a single component). `renderBlockSeam` (render.ts) owns that resolution and is shared with the
    // Handlebars tier's own `render_block` helper.
    return renderBlockSeam(siteCtx, props);
  },
};

/**
 * One engine for the site zone `timeZone` (an already-normalized IANA name). LiquidJS reads the
 * `| date:` filter's zone from the ENGINE's `timezoneOffset` option, never from a per-render option,
 * so the zone is fixed at construction (Bug D follow-up, 2026-10-22). Without it the filter formatted
 * in the process's own zone (UTC in every deployment), so a post a Los Angeles site published at
 * 11pm showed the next day.
 */
function createLiquidEngine({ timeZone }: { timeZone: string }, _optional: Record<string, never> = {}): Liquid {
  const engine = new Liquid({
    outputEscape: "escape",
    strictVariables: false,
    strictFilters: false,
    jsTruthy: true,
    cache: false,
    fs: NO_ACCESS_FS,
    // AW-5a C6 hardening follow-up (2026-07-16 audit finding, Fable): LiquidJS's own DoS knobs
    // (`memoryLimit`/`renderLimit`/`parseLimit`) had no defaults set, so an unbounded numeric range
    // (e.g. `(1..999999999)`) could allocate a large array *within* the worker's V8 heap
    // (`resourceLimits.maxOldGenerationSizeMb: 64`) before that ceiling ever triggers — a low-severity
    // sandbox bypass the process-crash fix's `worker_threads` isolation already contained (a runaway
    // render only OOM-kills its own disposable worker), but this closes it at the LiquidJS layer too,
    // as defense-in-depth ahead of ever reaching the V8-level ceiling.
    memoryLimit: 5_000_000,
    renderLimit: 5_000,
    parseLimit: 1_000_000,
    timezoneOffset: timeZone,
  });
  engine.registerTag("render_block", RENDER_BLOCK_TAG);
  return engine;
}

/** Engines by normalized zone. A render's zone is its own engine's construction option, so one
 * site's zone can never leak into another site's render. Bounded by the valid IANA names
 * `normalizeTimeZone` lets through; in production each spawn-per-render worker builds just one. */
const enginesByZone = new Map<string, Liquid>();

/** The engine for `ctx`'s site zone (UTC when absent or invalid), built on first use. */
function liquidEngineFor({ ctx }: { ctx: SiteRenderContext }, _optional: Record<string, never> = {}): Liquid {
  const timeZone = normalizeTimeZone({ timeZone: ctx.timeZone ?? DEFAULT_SITE_TIME_ZONE });
  const cached = enginesByZone.get(timeZone);
  if (cached) return cached;
  const engine = createLiquidEngine({ timeZone });
  enginesByZone.set(timeZone, engine);
  return engine;
}

/** The shared cross-tier data contract (`render.ts`'s `buildTemplateRenderData`) plus the private
 * context handle the `render_block` tag reads back out of the render scope. */
function buildLiquidData(ctx: SiteRenderContext): Record<string, unknown> {
  return { ...buildTemplateRenderData(ctx), [RENDER_CTX_KEY]: ctx };
}

function isLiquidWorkerInput(value: unknown): value is LiquidWorkerInput {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { source?: unknown }).source === "string" &&
    typeof (value as { ctx?: unknown }).ctx === "object"
  );
}

/**
 * Run one sandboxed Liquid render from the worker's `workerData`. Pure apart from the module-level
 * engine: never touches `parentPort`, so `liquid-worker.ts` stays a thin message shim and this
 * logic is importable (and measurable) in-process.
 * @param input.workerData The structured-clone payload the sandbox sent; validated here, not trusted.
 * @returns The reply the worker posts back: rendered HTML, or a controlled error message.
 * @complexity O(n) in template size plus the render itself (bounded by the engine's DoS limits).
 */
export function runLiquidRender({ workerData }: { workerData: unknown }): LiquidWorkerResult {
  if (!isLiquidWorkerInput(workerData)) {
    return { ok: false, error: "liquid-worker received malformed workerData" };
  }
  const { source, ctx } = workerData;

  // Defensive re-check (belt-and-suspenders): `loadTheme()` already linted
  // this source at discovery time; re-lint unconditionally here in case the
  // file changed on disk since. No worker payload may bypass this boundary.
  const violations = lintLiquidTemplate(source);
  if (violations.length > 0) {
    return { ok: false, error: `disallowed Liquid usage: ${violations.join("; ")}` };
  }

  try {
    const html = liquidEngineFor({ ctx }).parseAndRenderSync(source, buildLiquidData(ctx));
    return { ok: true, html };
  } catch (err) {
    return { ok: false, error: (err as Error).message };
  }
}

import { publishVisitorPage } from '#src/features/theme/visitor-publication';
import type { Express, Request, Response, NextFunction } from 'express';
import { injectPublishedWebMcp } from '#src/features/webmcp/published-html';

/** A single response seam covers static-theme, templated and HTML-format pages,
 * product pages and the local app used by static export. No route renderer needs
 * a WebMCP dependency. Requests for assets/admin/APIs never read this policy. */
export function applyPublishedWebMcp(
  { app, readEnabled, allowsVisitorPublication, workspaceId }: { app: Express; workspaceId?: string; readEnabled: () => Promise<boolean>; allowsVisitorPublication?: (args: { path: string }) => Promise<boolean> },
  _optional: Record<string, never> = {},
): void {
  app.use(async (req: Request, res: Response, next: NextFunction) => {
    // Both theme mounts serve a theme's raw files (the preview one by revision): never a published page.
    if (!['GET', 'HEAD'].includes(req.method) || /^\/(?:admin|api|theme-assets|theme-preview-assets|assets)(?:\/|$)/.test(req.path)) {
      next(); return;
    }
    let enabled = false;
    // The export marker is scoped to the crawl request, just like the visitor-chat opt-out.
    // Disable before injection; the same owner also removes native form-tool annotations.
    try { enabled = req.get('x-tovu-static-export') !== '1' && await readEnabled(); } catch { /* Policy read failure disables tools, not the page. */ }
    const send = res.send;
    res.send = function (body: unknown): Response {
      const type = String(res.getHeader('content-type') ?? '');
      if (typeof body === 'string' && res.statusCode < 400) {
        const htmlType = type.includes('text/html') || (!type && /^\s*(?:<!doctype html|<html\b)/i.test(body));
        if (htmlType) {
          body = injectPublishedWebMcp({ html: body, enabled });
          // Most HTML (and all assets/API responses) needs no publication lookup. Defer the
          // authoritative content read until the rendered document actually contains the widget.
          if (allowsVisitorPublication && req.get('x-tovu-static-export') !== '1' && (body as string).includes('tovu-site-assistant-root')) {
            const html = body as string;
            void allowsVisitorPublication({ path: req.path }).catch(() => false).then(allowed => {
              const published = allowed ? publishVisitorPage({ html, path: req.path, workspaceId }) : html;
              send.call(this, published);
            }).catch(next);
            return this;
          }
        }
      }
      return send.call(this, body);
    };
    next();
  });
}

import type { DocumentAssets } from '@jini-ai/cms/presentation';
import type { DeclaredScript } from '@jini-ai/cookie-consent';
import { renderScriptAssets } from '@jini-ai/cookie-consent/render';
import type { ConsentConfig } from '@jini-ai/cookie-consent';
/** Public declared-script assets, published context, receipts and plugin admission.
 * Documents receive asset contributions during construction; public responses are never scanned. */
import { createHash, randomBytes } from 'node:crypto';
import * as fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import express, { type Express, type Request, type Response } from 'express';
import { CONSENT_COOKIE, OPTIONAL, REGION_COOKIE, type ConsentState, type Optional, type RawContribution, type RegionResolver } from '@jini-ai/cookie-consent';
import { DEFAULT_MAX_AGE_MS, parseStored } from '@jini-ai/cookie-consent/policy';
import { renderBanner } from '@jini-ai/cookie-consent/render';
import { handleReceipt, readConsent, resolveRegion, type ConsentRecord } from '@jini-ai/cookie-consent/server';
import { consentRateLimitKey, createConsentFileRecords, createNodeConsentFiles } from '@jini-ai/cookie-consent/node';
import { createNodeAtomicFilesystem, writeJsonFileAtomic } from '@jini-ai/platform/fs';
import { createRateLimiter, resolveClientIp } from '#src/contracts/core/rate-limit/rate-limit';
import type { SiteCookieConsentDeps, ConsentPluginHttp, ConsentPluginContribution } from '#src/contracts/headless/index';
import { NO_THEME_ID, resolveActiveTheme } from '#src/features/theme/active-theme';
import { siteBannerMode, toSiteCookieConsent } from '#src/features/consent/cookie-consent';
import type { RouteDeps } from '#src/server/routes/types';
import { isStaticExportRequest } from '../routes/site/pages.js';
import { CONSENT_RECEIPTS_DIR_NAME, CONSENT_SAVE_PROFILE, readSiteConsentPolicy, resolveSiteConsentOrigin } from './site-consent.js';

export type { SiteCookieConsentDeps, ConsentPluginHttp, ConsentPluginContribution } from '#src/contracts/headless/index';

export const CONSENT_ENDPOINT = '/_consent';
const PLUGIN_BASE = `${CONSENT_ENDPOINT}/p`;
/** A dot segment or an encoded separator never reaches a plugin handler, whatever the plugin does with paths. */
const UNSAFE_PLUGIN_PATH = /(?:^|\/)\.\.?(?:\/|$)|%2e|%2f|%5c|\\/i;

/** Read the client bundle once; the hash makes its URL immutable (and lets static exports copy it). */
function loadClient(_required = {}, { resolve = createRequire(import.meta.url).resolve }: { resolve?: (id: string) => string } = {}) {
  try {
    const body = fs.readFileSync(resolve('@jini-ai/cookie-consent/client.min.js'));
    const hash = createHash('sha256').update(body).digest('hex').slice(0, 12);
    return { body, src: `${CONSENT_ENDPOINT}/client-${hash}.min.js` };
  } catch {
    console.warn('[consent] The cookie preferences client could not be loaded. Its browser route is disabled.');
    return undefined;
  }
}

/** Express → web Request on the site's PUBLIC origin, so handleReceipt's origin check is meaningful. */
function toWebRequest({ req, body }: { req: Request; body: Buffer }, _optional = {}): globalThis.Request {
  const headers = new Headers();
  for (const name of ['origin', 'content-type', 'content-length', 'cookie', 'sec-gpc', 'dnt']) {
    const value = req.get(name);
    if (value !== undefined) headers.set(name, value);
  }
  return new globalThis.Request(new URL(req.originalUrl, resolveSiteConsentOrigin({ request: req })), { method: req.method, headers, body: new Uint8Array(body) });
}

/** Adapters of the analytics plugins attached to this site, mounted under one path each.
 * A plugin that throws or is not configured contributes nothing. @complexity O(plugins). */
export function siteConsentPlugins({ deps }: { deps: RouteDeps }, _optional = {}): readonly ConsentPluginContribution[] {
  return deps.consentAdapters?.({ base: PLUGIN_BASE }) ?? [];
}

/** Region persistence is only reached for an enabled consent banner, never anonymous analytics. */
function setRegionCookie({ req, res, hint }: { req: Request; res: Response; hint: 'us' | 'strict' }, _optional = {}): void {
  const current = req.get('cookie')?.match(new RegExp(`(?:^|;\\s*)${REGION_COOKIE}=([^;]*)`))?.[1];
  const secure = req.secure || resolveSiteConsentOrigin({ request: req }).startsWith('https:');
  if (hint === 'us' && current !== 'us') res.cookie(REGION_COOKIE, 'us', { path: '/', sameSite: 'lax', secure, maxAge: 86_400_000 });
  if (hint === 'strict' && current !== undefined) res.clearCookie(REGION_COOKIE, { path: '/' });
}

/** Only this engine retires the old host-only HttpOnly cookie; its receipt id proves no new categories. */
function clearLegacyCookie({ req, res }: { req: Request; res: Response }, _optional = {}): void {
  if (/(?:^|;\s*)jini_consent=/.test(req.get('cookie') ?? '')) res.clearCookie('jini_consent', { path: '/', httpOnly: true, sameSite: 'lax' });
}

/** The site's receipt files: the same directory the old engine and readiness's storage check use. */
function siteReceiptStore({ deps }: { deps: RouteDeps }, _optional = {}) {
  return createConsentFileRecords({ directory: path.join(deps.siteBinding.dir, CONSENT_RECEIPTS_DIR_NAME), files: createNodeConsentFiles({
    atomicWrite: async ({ filePath, data }, { createParent, mode, refuseSymlink }) => {
      if (createParent) await fs.promises.mkdir(path.dirname(filePath), { recursive: true, mode: 0o700 });
      writeJsonFileAtomic({ filePath, data, fs: createNodeAtomicFilesystem({}, {}) }, { mode, refuseSymlink });
    } }) });
}

/** Mount the receipt endpoint (with Tovu's rate limit and the site's file store). */
function mountReceipts({ app, deps }: { app: Express; deps: RouteDeps }, _optional = {}): void {
  const limiter = createRateLimiter({ profile: CONSENT_SAVE_PROFILE, clock: deps.clock });
  const store = siteReceiptStore({ deps });
  app.post(CONSENT_ENDPOINT, express.raw({ type: () => true, limit: '4kb' }), async (req, res) => {
    try {
      const config = await readSiteConsentPolicy({ deps });
      const response = await handleReceipt({ request: toWebRequest({ req, body: Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0) }), ports: {
        store, policy: () => config.policyVersion, now: () => deps.clock.nowMs(),
        // Receipt ids must be unguessable; the site's time-ordered id generator is not.
        ids: () => randomBytes(24).toString('base64url'),
      } }, { regionMode: config.regionMode === 'opt-in' ? 'opt-in' : 'auto',
        allow: async () => (await limiter.check({ key: consentRateLimitKey({ address: resolveClientIp(req) }) })).allowed });
      res.status(response.status).set(Object.fromEntries(response.headers)).send(await response.text());
    } catch { console.error('[consent] save failed'); res.status(503).set('Cache-Control', 'no-store').json({ error: 'Your choice could not be saved. Try again.' }); }
  });
}

/** Plugin assets and collectors. A collector POST is accepted only from this site and only while the
 * visitor's stored choice allows that adapter's category. @complexity O(plugins) per request. */
function mountPluginHttp({ app, deps }: { app: Express; deps: RouteDeps }, _optional = {}): void {
  const limiter = createRateLimiter({ profile: { windowSeconds: 60, max: 120, burst: 20 }, clock: deps.clock });
  app.use(PLUGIN_BASE, express.raw({ type: () => true, limit: '256kb' }), async (req, res, next) => {
    const full = PLUGIN_BASE + req.path;
    const plugin = pluginFor({ deps, full });
    if (!plugin) { next(); return; }
    try {
      const decision = req.method === 'GET' ? undefined : await collectorDecision({ req, deps, adapter: plugin.adapter, limiter });
      if (decision?.status) { res.status(decision.status).end(); return; }
      const result = await plugin.http.handle({ ...pluginRequest({ req, full, plugin }), ...(decision && { analyticsLevel: decision.analyticsLevel }) });
      if (result.contentType) res.setHeader('Content-Type', result.contentType);
      res.setHeader('Cache-Control', req.method === 'GET' && result.cacheControl ? result.cacheControl : 'private, no-store');
      res.status(result.status).end(result.body);
    } catch { res.status(502).end(); }
  });
}

/** Normalize the host request without forwarding visitor headers or trusting its identity. */
function pluginRequest({ req, full, plugin }: { req: Request; full: string; plugin: { http: ConsentPluginHttp } }, _optional = {}): Parameters<ConsentPluginHttp['handle']>[0] {
  return { method: req.method, path: full.slice(plugin.http.path.length),
    body: Buffer.isBuffer(req.body) ? req.body : new Uint8Array(), contentType: req.get('content-type') ?? 'application/octet-stream' };
}

/** The active plugin mounted over this path; none for a path with a dot segment or encoded separator. */
function pluginFor({ deps, full }: { deps: RouteDeps; full: string }, _optional = {}): (ConsentPluginContribution & { http: ConsentPluginHttp }) | undefined {
  if (UNSAFE_PLUGIN_PATH.test(full)) return undefined;
  return siteConsentPlugins({ deps }).find((item): item is ConsentPluginContribution & { http: ConsentPluginHttp } => Boolean(item.http && full.startsWith(item.http.path + '/')));
}

/** Same-origin/category/rate decision plus the server-owned analytics level. Anonymous delivery needs
 * an adapter declaring support. A category that is not optional (even 'necessary') is read as marketing,
 * the strictest. @complexity O(cookie header) plus one policy read. */
async function collectorDecision(
  { req, deps, adapter, limiter }: { req: Request; deps: RouteDeps; adapter: RawContribution; limiter: ReturnType<typeof createRateLimiter> },
  _optional = {},
): Promise<{ status: 403 | 429 | null; analyticsLevel: ConsentState['analyticsLevel'] }> {
  const denied = { status: 403, analyticsLevel: 'none' } as const;
  if (req.get('origin') !== resolveSiteConsentOrigin({ request: req })) return denied;
  const category: Optional = (OPTIONAL as readonly unknown[]).includes(adapter.category) ? adapter.category as Optional : 'marketing';
  const state = await readSiteVisitorConsent({ deps, req });
  const allowed = category === 'analytics' && state.analyticsLevel === 'anonymous' ? adapter.supportsAnonymous === true : state.allowed[category];
  if (!allowed) return denied;
  // The receipts' key (an IPv6 /64), so rotating addresses inside one network shares one budget.
  return { status: (await limiter.check({ key: consentRateLimitKey({ address: resolveClientIp(req) }) })).allowed ? null : 429, analyticsLevel: state.analyticsLevel };
}

/** The server gate: what this visitor may run right now (GPC/DNT applied, durable rule: an
 * unconfirmed grant is not allowed). A failed policy read allows nothing. @complexity O(cookie header). */
export async function readSiteVisitorConsent({ deps, req }: { deps: RouteDeps; req: Request }, _optional = {}) {
  try {
    const snapshot = await documentPolicy({ consent: deps.cookieConsent });
    if (unavailableDocumentPolicy({ consent: deps.cookieConsent, config: snapshot })) return readConsent({ cookieHeader: '', policy: '', regionMode: 'opt-in' });
    if (snapshot && siteBannerMode({ config: snapshot }) === 'off') return readConsent({ cookieHeader: '', policy: snapshot.policyVersion, regionMode: 'opt-in' }, {
      ...requestPrivacy({ deps, req }), anonymous: true,
    });
    const config = snapshot ?? await readSiteConsentPolicy({ deps });
    return readConsent({ cookieHeader: req.get('cookie'), policy: config.policyVersion, regionMode: config.regionMode === 'opt-in' ? 'opt-in' : 'auto' }, {
      ...requestPrivacy({ deps, req }), anonymous: siteBannerMode({ config }) === 'off',
    });
  } catch {
    return readConsent({ cookieHeader: '', policy: '', regionMode: 'opt-in' });
  }
}

/** The published policy id visitors are asked under now. @complexity O(1) reads. */
async function readSiteConsentPolicyVersion({ deps }: { deps: RouteDeps }, _optional = {}): Promise<string> {
  return (await readSiteConsentPolicy({ deps })).policyVersion;
}

/** Detached delivery recheck, the old engine's rule: the receipt is still active (a later choice retires
 * it), names the current policy, grants analytics without GPC and is within the choice lifetime. A forged
 * or withdrawn receipt id never delivers. @complexity O(1): one policy read and one receipt read. */
export async function siteReceiptAllowsAnalytics({ deps, proof }: { deps: RouteDeps; proof: { receiptId: string; policyVersion: string } }, _optional = {}): Promise<boolean> {
  const snapshot = await documentPolicy({ consent: deps.cookieConsent });
  if (unavailableDocumentPolicy({ consent: deps.cookieConsent, config: snapshot })) return false;
  if (snapshot && siteBannerMode({ config: snapshot }) === 'off') return false;
  const policy = snapshot?.policyVersion ?? await readSiteConsentPolicyVersion({ deps });
  if (proof.policyVersion !== policy) return false;
  const record = (await siteReceiptStore({ deps }).read?.({ id: proof.receiptId }) ?? null) as Partial<ConsentRecord> | null;
  return activeAnalyticsRecord({ record, policy, nowMs: deps.clock.nowMs() });
}

function activeAnalyticsRecord({ record, policy, nowMs }: { record: Partial<ConsentRecord> | null; policy: string; nowMs: number }, _optional = {}): boolean {
  if (!record || record.policyVersion !== policy || record.gpc !== false) return false;
  return record.choices?.analytics === true && nowMs - Date.parse(String(record.timestamp)) <= DEFAULT_MAX_AGE_MS;
}

/** The old engine's analytics proof shape (receipt id + policy), from the new cookie. Undefined unless
 * analytics is allowed and a server receipt exists. @complexity O(cookie header). */
export async function readSiteAnalyticsProof({ deps, req }: { deps: RouteDeps; req: Request }, _optional = {}): Promise<{ receiptId: string; policyVersion: string } | undefined> {
  const state = await readSiteVisitorConsent({ deps, req });
  if (state.analyticsLevel !== 'full') return undefined;
  const raw = req.get('cookie')?.match(new RegExp(`(?:^|;\\s*)${CONSENT_COOKIE}=([^;]*)`))?.[1];
  let receiptId: string | undefined;
  try { receiptId = parseStored({ raw: raw === undefined ? null : decodeURIComponent(raw) })?.r; } catch { receiptId = undefined; }
  return receiptId ? { receiptId, policyVersion: state.policy } : undefined;
}

/** One published construction snapshot per site (per consent deps), shared by every app built over
 * them: an export, an inspection or a theme override never resets what live visitors are served.
 * Refreshed by publication. No per-page reads. */
type DocumentState = {
  policy?: ConsentConfig;
  pending?: Promise<void>;
  scripts: Promise<readonly DeclaredScript[]>;
  client?: { body: Buffer; src: string };
  nextReadAt: number;
  now: () => number;
  refresh?: () => Promise<void>;
};
const documentStates = new WeakMap<SiteCookieConsentDeps, DocumentState>();
const EXTENSION_SRC = '/_consent/extensions.min.js';
export const CONSENT_LOADER_SRC = '/_consent/load.js';

/** A mounted site's failed snapshot must not fall back to another immediate store read. */
function unavailableDocumentPolicy({ consent, config }: { consent?: SiteCookieConsentDeps; config: ConsentConfig | null }): boolean {
  return Boolean(consent && documentStates.has(consent) && !config);
}

/** The declaration owner is independent of policy availability, so ordinary scripts can still run. */
async function documentDeclarations({ consent }: { consent?: SiteCookieConsentDeps }): Promise<readonly DeclaredScript[]> {
  if (!consent) return [];
  return await documentStates.get(consent)?.scripts ?? [];
}

/** One read per minute per mounted site, including a retry after an unavailable publication. */
async function documentPolicy({ consent }: { consent?: SiteCookieConsentDeps }): Promise<ConsentConfig | null> {
  const state = consent && documentStates.get(consent);
  if (!state) return null;
  if (state.now() >= state.nextReadAt) void state.refresh?.().catch(() => undefined);
  if (state.policy) return state.policy;
  await briefPendingRead({ state });
  return state.policy ?? null;
}

/** Wait at most 250 ms for a read in flight; with none, resolve at once. A late success still lands. */
async function briefPendingRead({ state }: { state: DocumentState }): Promise<void> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try { await Promise.race([state.pending?.catch(() => undefined), new Promise(resolve => { timer = setTimeout(resolve, 250); })]); }
  finally { clearTimeout(timer); }
}

/** Document construction consumes data, never a completed response body. */
export async function siteConsentDocumentAssets({ deps, request, scripts, static: staticDocument }: { deps: Pick<RouteDeps, 'cookieConsent' | 'consentAdapters'>; request: Request; scripts: readonly DeclaredScript[]; static?: true }, _optional = {}): Promise<DocumentAssets> {
  const consent = deps.cookieConsent;
  const config = await documentPolicy({ consent });
  if (staticDocument) return staticDocumentAssets({ config, request, scripts, consent });
  const allScripts = [...scripts, ...await documentDeclarations({ consent })];
  if (request.res?.locals.tovuRenderThemeIdOverride) return { head: renderScriptAssets({ scripts: allScripts.filter(script => script.consent === undefined) }), body: '' };
  if (!config || !consent) return { head: renderScriptAssets({ scripts: allScripts.filter(script => script.consent === undefined) }), body: '' };
  if (siteBannerMode({ config }) === 'off') return { head: renderScriptAssets({ scripts: allScripts }), body: '' };
  return renderDocumentConsent({ deps, request, consent, config, scripts: allScripts });
}

/** Static documents share managed shells' cached publication; off-mode declarations need no consent runtime.
 * @complexity O(declared scripts) time/space when off; reuses the cached declaration Promise without I/O. */
async function staticDocumentAssets({ config, request, scripts, consent }: {
  config: ConsentConfig | null; request: Request; scripts: readonly DeclaredScript[]; consent?: SiteCookieConsentDeps;
}): Promise<DocumentAssets> {
  if (!config || request.res?.locals.tovuRenderThemeIdOverride) return { head: '', body: '' };
  if (siteBannerMode({ config }) === 'off') {
    const allScripts = [...scripts, ...await documentDeclarations({ consent })];
    return { head: renderScriptAssets({ scripts: allScripts }), body: '' };
  }
  return { head: `<script src="${CONSENT_LOADER_SRC}" defer data-jini-consent-loader></script>`, body: '' };
}

/** Render the shared banner and client assets once a usable snapshot has been selected. */
async function renderDocumentConsent({ deps, request, consent, config, scripts }: {
  deps: Pick<RouteDeps, 'cookieConsent' | 'consentAdapters'>; request: Request; consent: SiteCookieConsentDeps;
  config: ConsentConfig; scripts: readonly DeclaredScript[];
}): Promise<DocumentAssets> {
  const live = !isStaticExportRequest(request);
  const plugins = await documentPlugins({ deps, live });
  const { banner, options } = toSiteCookieConsent({ config, policy: config.policyVersion }, { plugins });
  const rendered = renderBanner({ ...banner, client: { ...banner.client, scripts, ...(live ? { context: `${CONSENT_ENDPOINT}/context` } : {}) } }, {
    ...options, clientSrc: documentStates.get(consent)?.client?.src, extensionSrc: EXTENSION_SRC,
    evidence: live ? { mode: 'durable', endpoint: CONSENT_ENDPOINT } : { mode: 'local' },
  });
  return { head: rendered.head, body: rendered.body + '<a class="jini-consent-settings" href="#privacy-choices" data-consent-open>Cookie settings</a>' };
}

/** JSON declaration URLs are invisible to an HTML crawler. No live collectors enter an export. */
export async function siteConsentExportAssets({ deps }: { deps: Pick<RouteDeps, 'cookieConsent'> }, _optional = {}): Promise<readonly string[]> {
  const config = await documentPolicy({ consent: deps.cookieConsent });
  const declared = await documentDeclarations({ consent: deps.cookieConsent });
  const local = declared.filter(script => script.src.startsWith('/') && (config || script.consent === undefined)).map(script => script.src);
  if (!config || siteBannerMode({ config }) === 'off') return local;
  return [...(documentStates.get(deps.cookieConsent!)?.client ? [documentStates.get(deps.cookieConsent!)!.client!.src] : []), EXTENSION_SRC, ...local];
}

/** Public context shares the site's publication retry window and keeps visitor state out of HTML caches. */
function mountContext({ app, consent }: { app: Express; consent: SiteCookieConsentDeps }, _optional = {}): void {
  app.get(`${CONSENT_ENDPOINT}/context`, async (req, res) => {
    res.set('Cache-Control', 'private, no-store');
    try {
      const config = await documentPolicy({ consent });
      if (!config) throw new Error('Cookie preferences are not available.');
      const enabled = siteBannerMode({ config }) !== 'off';
      if (enabled) {
        const hint = await resolveRegion({ resolvers: await consent.regionResolvers(), request: { header: name => req.get(name) ?? null, ip: req.ip ?? null } });
        setRegionCookie({ req, res, hint });
        clearLegacyCookie({ req, res });
      }
      res.json({ enabled, policy: config.policyVersion, regionMode: config.regionMode === 'opt-in' ? 'opt-in' : 'auto' });
    } catch { console.error('[consent] public context unavailable'); res.status(503).json({ error: 'Cookie preferences could not be loaded. Wait a minute, then reload to try again.' }); }
  });
}

/** Authored static documents load the same construction assets as managed shells. No page bytes
 * are inspected or changed; the browser installs only this server-owned contribution. */
function mountStaticThemeLoader({ app, deps }: { app: Express; deps: RouteDeps }): void {
  app.get(CONSENT_LOADER_SRC, async (req, res) => {
    try {
    const theme = deps.resolveActiveThemeId ? resolveActiveTheme(deps, await deps.resolveActiveThemeId()) : null;
    const scripts = theme && theme !== NO_THEME_ID ? theme.manifest.scripts ?? [] : [];
    const assets = await siteConsentDocumentAssets({ deps, request: req, scripts });
    const markup = JSON.stringify(assets.head + assets.body);
    res.type('text/javascript').set('Cache-Control', 'public, max-age=60').set('Vary', 'X-Tovu-Static-Export').send(`(()=>{
      if(document.getElementById('jini-consent-config'))return;
      const template=document.createElement('template');template.innerHTML=${markup};
      ${isStaticExportRequest(req) ? String.raw`// Only this server-owned contribution is rebased, never the authored document.
      const base=document.currentScript?new URL('..',document.currentScript.src).pathname.replace(/\/$/,''):'';
      const prefix=value=>typeof value==='string'&&/^\/(?!\/)/.test(value)?base+value:value;
      for(const node of template.content.querySelectorAll('[src],[href]')){
        for(const attr of ['src','href'])if(node.hasAttribute(attr))node.setAttribute(attr,prefix(node.getAttribute(attr)));}
      const config=template.content.querySelector('#jini-consent-config');
      if(config)config.textContent=JSON.stringify(JSON.parse(config.textContent),(key,value)=>key==='src'?prefix(value):value);` : ''}
      const scripts=[];
      for(const node of [...template.content.childNodes]){
        if(node.nodeName==='SCRIPT'&&node.getAttribute('src'))scripts.push(node);
        else document.body.append(node);
      }
      for(const node of scripts){const script=document.createElement('script');
        for(const attr of node.attributes)script.setAttribute(attr.name,attr.value);
        script.async=false;document.body.append(script);}
    })();`);
    } catch {
      console.error('[consent] static loader unavailable');
      res.status(503).type('text/javascript').set('Cache-Control', 'no-store').send('/* Cookie preferences could not be loaded. Wait a minute, then reload to try again. */');
    }
  });
}

/** Read the policy and plugin declarations together. Each keeps its last good value on failure.
 * @complexity O(1): one policy read and one declaration load at a time. */
function refreshDocumentState({ state, deps, consent }: { state: DocumentState; deps: RouteDeps; consent: SiteCookieConsentDeps }): Promise<void> {
  if (state.pending) return state.pending;
  state.nextReadAt = state.now() + 60_000;
  const policy = readSiteConsentPolicy({ deps }).then(config => { state.policy = config; }, error => {
    console.warn('[consent] Cookie preferences could not refresh. The last loaded preferences remain in use; a later request will try again.');
    throw error;
  });
  const lastGoodScripts = state.scripts;
  state.scripts = (consent.scriptDeclarations?.() ?? Promise.resolve({ scripts: [] })).then(loaded => loaded.scripts, () => {
    console.warn('[consent] Plugin scripts could not refresh. The last loaded scripts remain in use; a later request will try again.');
    return lastGoodScripts;
  });
  state.pending = Promise.allSettled([policy, state.scripts]).then(([read]) => {
    if (read.status === 'rejected') throw read.reason;
  }).finally(() => { state.pending = undefined; });
  return state.pending;
}

/** The site's snapshot, created by its first app build; later builds add routes and read nothing. */
function siteDocumentState({ deps, consent, client }: { deps: RouteDeps; consent: SiteCookieConsentDeps; client: () => DocumentState['client'] }): DocumentState {
  const existing = documentStates.get(consent);
  if (existing) return existing;
  const state: DocumentState = { client: client(), scripts: Promise.resolve([]), nextReadAt: Infinity, now: () => deps.clock.nowMs() };
  documentStates.set(consent, state);
  const refresh = () => refreshDocumentState({ state, deps, consent });
  consent.refresh = refresh;
  state.refresh = refresh;
  consent.embedConsentOff = () => Boolean(state.policy && siteBannerMode({ config: state.policy }) === 'off');
  consent.exportAssets = () => siteConsentExportAssets({ deps });
  // Answered for one export run, before it renders. A good policy is never cleared, so no later page
  // can lose its banner when this finds one; a run starts from a fresh read, as it always has.
  consent.exportWarning = async () => {
    void refresh().catch(() => undefined);
    await briefPendingRead({ state });
    return state.policy ? undefined : 'Cookie preferences could not be loaded. This published copy has no cookie banner.';
  };
  void refresh().catch(() => undefined);
  return state;
}

/** Routes and a construction-time snapshot only; no page-response capture or cookie work. */
export function applySiteCookieConsent({ app, deps, consent }: { app: Express; deps: RouteDeps; consent: SiteCookieConsentDeps }, { client: suppliedClient }: { client?: { body: Buffer; src: string } } = {}): void {
  const { client } = siteDocumentState({ deps, consent, client: () => suppliedClient ?? loadClient() });
  app.use(async (req, res, next) => {
    // Resolve the cached publication before widget rendering; consent-off pages have no activation runtime.
    await documentPolicy({ consent });
    res.locals.siteConsentAssets = (required: { scripts: readonly DeclaredScript[]; static?: true }) => siteConsentDocumentAssets({ deps, request: req, ...required });
    next();
  });
  if (client) app.get(client.src, (_req, res) => { res.type('text/javascript').set('Cache-Control', 'public, max-age=31536000, immutable').send(client.body); });
  const resolve = createRequire(import.meta.url).resolve;
  try {
    const extension = fs.readFileSync(path.join(path.dirname(resolve('@jini-ai/cookie-consent/client.min.js')), 'extensions.min.js'));
    app.get(EXTENSION_SRC, (_req, res) => { res.type('text/javascript').set('Cache-Control', 'public, max-age=60').send(extension); });
  } catch { console.warn('[consent] The cookie preferences extensions could not be loaded. Their browser route is disabled.'); }
  mountStaticThemeLoader({ app, deps });
  mountContext({ app, consent });
  mountReceipts({ app, deps });
  mountPluginHttp({ app, deps });
}

async function documentPlugins({ deps, live }: { deps: Pick<RouteDeps, 'cookieConsent' | 'consentAdapters'>; live: boolean }): Promise<readonly RawContribution[]> {
  if (!live) return [];
  return [...deps.consentAdapters?.({ base: PLUGIN_BASE }).map(item => item.adapter) ?? [], ...await deps.cookieConsent?.browserPlugins?.() ?? []];
}

function requestPrivacy({ deps, req }: { deps: RouteDeps; req: Request }) {
  return { secGpc: req.get('sec-gpc') ?? null, dnt: req.get('dnt') ?? null, nowMs: deps.clock.nowMs() };
}

import type { Express, NextFunction, Request, Response } from "express";

import type { SiteStatusPort } from "#src/features/database/boot/reconcile-interrupted-migration";

/**
 * @file ADR-041/043/044/045 re-audit (2026-07-16, TM-adr041-043-044-045-audit-001, round-2
 * external audit, codex finding `R2-F2-BLOCK-NOT-ENFORCED`) — closes the residual half of
 * Finding 2. `bootstrap.ts`'s `database-migration-reconciliation` module (Finding 2's round-2 fix)
 * correctly DETECTS a crash-interrupted migration and flips `siteStatusRepo` to
 * `BLOCKED_PENDING_RECOVERY`, but detection alone does not satisfy ADR-041 §3's "blocking normal
 * site open until resolved" — nothing previously consumed that status to actually refuse a
 * request. `index.ts` only gates `app.listen()` on `bootResult.ok`, and the reconciliation module
 * treats a detected interruption as a successful `prepare()` (correctly — see below), so the
 * socket opened to full normal traffic regardless of `siteStatus`. This middleware is the missing
 * enforcement point.
 *
 * Scope of the block, per ADR-041 §3's own language ("routes to Recovery, blocking normal site
 * open") and its `PENDING_MIGRATION` precedent ("admin reachable, public serving refused"): while
 * `siteStatus === "BLOCKED_PENDING_RECOVERY"`, every request is refused EXCEPT the allowlisted
 * paths below, which stay reachable so an operator can authenticate and use Recovery to actually
 * resolve the interruption. This deliberately does NOT abort boot / refuse to `listen()` (the
 * external auditor's alternative suggestion) — the ADR's own text requires Recovery to remain
 * reachable, and process-level abort would lock operators out of the only path to fix it.
 *
 * Disclosed, accepted-risk gap (external audit, codex finding `R3-F2-CORS-PRECEDES-GATE`,
 * explicitly classified non-blocking): `applyDevCors` is mounted before this gate in `app.ts` and
 * terminates every `OPTIONS` preflight with a bare 204 before this middleware runs, so preflight
 * requests are never gated. This has no invariant impact — `OPTIONS` never reaches a real handler
 * or mutates state; the actual method that follows a preflight (`GET`/`POST`/etc.) DOES pass
 * through this gate normally. Not fixed here: reordering risks stripping CORS headers off this
 * gate's own 503 responses, which would make them an opaque failure to a cross-origin admin SPA.
 */
const ALWAYS_ALLOWED_EXACT_PATHS = new Set(["/healthz", "/readyz", "/admin"]);

const ALWAYS_ALLOWED_PREFIXES = [
  "/api/admin/v1/auth/", // login/logout/me
  "/api/admin/v1/recovery/", // the entire Recovery API surface
  "/admin/", // built admin SPA assets/sub-routes. Trailing slash is load-bearing: it must NOT
  // match a public slug like /admin-news or /administrator (round-3 fix, codex finding
  // R3-F1-ADMIN-PREFIX-PUBLIC-BYPASS — the original bare "/admin" prefix was not
  // path-segment bounded and let such slugs bypass the block via the site's GET /:slug catch-all).
];

function isAlwaysAllowed(path: string): boolean {
  if (ALWAYS_ALLOWED_EXACT_PATHS.has(path)) return true;
  return ALWAYS_ALLOWED_PREFIXES.some((prefix) => path.startsWith(prefix));
}

/** Mounts the recovery gate; status-store failures go to Express's error handler via `next`.
 * @complexity O(1) per request, with at most one status-store read.
 */
export function applySiteServingGate(app: Express, deps: { siteStatusRepo: SiteStatusPort; workspaceId: string }): void {
  app.use(async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (isAlwaysAllowed(req.path)) {
        next();
        return;
      }

      const status = await deps.siteStatusRepo.get(deps.workspaceId);
      if (status !== "BLOCKED_PENDING_RECOVERY") {
        next();
        return;
      }

      res.status(503).json({
        error: "this site is blocked pending recovery from an interrupted migration — see /api/admin/v1/recovery/status",
        code: "SITE_BLOCKED_PENDING_RECOVERY",
      });
    } catch (error) {
      // Express 4 does not observe rejected promises from async middleware.
      next(error);
    }
  });
}

import type { Express, Request, Response } from "express";

import { findTheme, renderStaticPage, renderStaticPartial, type DiscoveredTheme } from "#src/features/theme/index";
import { listPublishedPosts } from "#src/features/post/index";
import { authorizeThemeSetPermission } from "../../admin-http/routes/themes/explore.js";
import { requireAdminSession } from "../../admin-http/dev-auth.js";
import type { RouteDeps } from "#src/server/routes/types";
import { renderSite, type SiteProduct } from "../http/site/render.js";
import {
  resolveWidgetsForRender,
  resolveMediaTransformVersionsForRender,
  resolveMediaAssetMetadataForRender,
  resolveHtmlEmbedsForRender,
  resolveSiteTitleForRender,
  resolveSiteTimeZoneForRender,
} from "../routes/site/pages.js";

const PLAIN_TEXT = "text/plain";
/** Previews render apart from the site's own origin. Theme fonts already allow any origin, so they still look right. */
const PREVIEW_SANDBOX = "sandbox allow-scripts allow-forms";

/**
 * @file Serves any static theme's page, fully rendered, at `/theme-explore/{themeId}/{pageId}` — the
 * admin Explore screen's preview iframe. Also serves a theme's PARTIALS (`nav`, `footer`, `sidebar`,
 * …) standalone at `/theme-explore/{themeId}/partial/{partialId}`, a sibling route rather than a
 * branch of the page route: partial ids and page ids are different namespaces (a theme could
 * legitimately have a page and a partial that happen to share a name), and a distinct URL shape says
 * so instead of relying on a lookup order to disambiguate.
 *
 * Rendered through the real loader (`renderStaticPage`), not a prebuilt copy: markers resolved,
 * design tokens inlined, asset paths rewritten to `/theme-assets/{themeId}/`. That last part is why
 * this has to be a real URL on the SITE origin rather than HTML posted into a `srcDoc` iframe — a
 * `srcDoc` document resolves those relative asset paths against the ADMIN's origin, where nothing
 * serves them, so every stylesheet 404s and the preview is a wall of unstyled text.
 *
 * Distinct from `theme-preview-static.ts`, which serves each theme's prebuilt `preview/` folder from
 * `build-preview.mjs`. That one is a spike predating static-tier rendering being wired at all, and
 * its header still says so; this is the real path and that one should be retired.
 *
 * The two STATIC-tier routes above are ungated, matching `theme-static-assets.ts`'s existing posture:
 * a theme's pages and CSS are already served to anonymous visitors by the site itself, and
 * `express.static` there already exposes each theme's `pages/*.html` directly. Rendering a page
 * nobody activated reveals nothing the theme files do not, and the admin's own auth cannot reach an
 * iframe pointed at the site origin anyway.
 *
 * The TEMPLATED-tier route below (2026-08-12, `.liquid` Preview-tab fix) is GATED, deliberately NOT
 * following that same ungated reasoning even though it lives in this same file and serves a
 * structurally similar purpose. That reasoning rests on several conditions holding simultaneously
 * (only published content ever flows in, products are always empty, the render pipeline's own
 * escaping never changes) — conditions that are correct today but are each independently a decision
 * someone could change later without revisiting this file. Every OTHER route on this resource
 * (`routes/admin/themes/explore.ts`) is gated on `theme.set`; an ungated new route would be the one
 * anomaly a future reader has to re-derive the justification for. Gating it costs one line
 * (`requireAdminSession` + the same `authorizeThemeSetPermission` check `explore.ts` already shares
 * across its own routes) and removes the whole question.
 *
 * Reads `deps.themes` directly rather than through a `getThemes()` indirection: `rescanThemes`
 * (`features/theme/theme.ts`) mutates that array IN PLACE (`themes.length = 0; themes.push(...)`),
 * never replaces the reference, so a theme downloaded after boot is previewable without a restart
 * exactly the same way a plain field read would be.
 */

/**
 * The lookup + tier check the two STATIC-tier routes below need before they can render anything:
 * find the theme, 404 if it doesn't exist, 422 if it isn't `static` tier. Returns the theme on
 * success, or `null` after already writing the error response — the caller's job is just to `return`
 * in that case, same shape `findTheme` itself uses for "not found".
 */
function resolveStaticTheme(
  res: Response,
  required: { themes: DiscoveredTheme[]; themeId: string }
): DiscoveredTheme | null {
  const { themes, themeId } = required;
  const theme = findTheme({ themes, id: themeId });
  if (!theme) {
    res.status(404).type(PLAIN_TEXT).send(`theme '${themeId}' was not found`);
    return null;
  }
  if (theme.manifest.tier !== "static") {
    res
      .status(422)
      .type(PLAIN_TEXT)
      .send(`theme '${themeId}' is a '${theme.manifest.tier}' theme; only static themes preview this way`);
    return null;
  }
  return theme;
}

/**
 * Reverse of `theme.ts`'s `resolveLiquidTemplateId` — the `SiteRenderContext` shape (a posts list, a
 * single post, a products list, a single product) a given `.liquid` template FILE was authored
 * against, derived from the file's OWN name. `resolveLiquidTemplateId` answers a different question
 * ("which file does the live site fall back to for this route", preferring `post` over `entry` when a
 * theme ships both) — the wrong one here, since Explore is asking "what does THIS SPECIFIC file
 * expect", for a file the forward resolver might not even pick for its own nominal route. This only
 * decides the CONTEXT shape; `renderSite`'s own `liquidTemplateIdOverride` (separately) is what makes
 * sure the exact file selected is the one actually rendered, not whichever one the forward resolver
 * would have preferred.
 *
 * @complexity O(1).
 */
function liquidTemplateContextRoute(templateId: string): "home" | "post" | "products" | "product" | null {
  if (templateId === "home") return "home";
  if (templateId === "products") return "products";
  if (templateId === "product") return "product";
  if (templateId === "post" || templateId === "entry") return "post";
  return null;
}

/**
 * The lookup + tier + template-existence + route-shape checks the TEMPLATED-tier route needs
 * before it can render anything: find the theme, 404 if missing, 422 if not `templated` tier, 404
 * if `templateId` names no real `.liquid` file, 422 if that file's name maps to no recognized
 * `SiteRenderContext` shape. Returns the resolved `{theme, route}` on success, or `null` after
 * already writing the error response — same "caller just returns" contract as
 * {@link resolveStaticTheme}.
 */
function resolveTemplatedPreviewTarget(
  res: Response,
  required: { themes: DiscoveredTheme[]; themeId: string; templateId: string }
): { theme: DiscoveredTheme; route: "home" | "post" | "products" | "product" } | null {
  const { themes, themeId, templateId } = required;
  const theme = findTheme({ themes, id: themeId });
  if (!theme) {
    res.status(404).type(PLAIN_TEXT).send(`theme '${themeId}' was not found`);
    return null;
  }
  if (theme.manifest.tier !== "templated") {
    res
      .status(422)
      .type(PLAIN_TEXT)
      .send(`theme '${themeId}' is a '${theme.manifest.tier}' theme; only templated themes preview this way`);
    return null;
  }
  if (theme.liquidTemplates[templateId] === undefined) {
    res.status(404).type(PLAIN_TEXT).send(`template '${templateId}' was not found in theme '${themeId}'`);
    return null;
  }
  const route = liquidTemplateContextRoute(templateId);
  if (!route) {
    res
      .status(422)
      .type(PLAIN_TEXT)
      .send(`template '${templateId}' has no recognized route shape and cannot be previewed here`);
    return null;
  }
  return { theme, route };
}

export function registerThemePagePreview(app: Express, deps: RouteDeps): void {
  app.get("/theme-explore/:themeId/:pageId", (req: Request, res: Response) => {
    const themeId = String(req.params.themeId ?? "");
    const pageId = String(req.params.pageId ?? "");

    const theme = resolveStaticTheme(res, { themes: deps.themes, themeId });
    if (!theme) return;

    const html = renderStaticPage({ theme, pageId });
    if (html === null) {
      res.status(404).type(PLAIN_TEXT).send(`page '${pageId}' was not found in theme '${themeId}'`);
      return;
    }

    // Never cached: the Explore screen re-requests this immediately after every save, and a cached
    // response would show the operator their pre-save markup and read as "the save did not work".
    res.set("Cache-Control", "no-store").set("Content-Security-Policy", PREVIEW_SANDBOX).type("text/html").send(html);
  });

  // Partials (`nav`, `footer`, `sidebar`, …) previewed standalone — see this file's header for why
  // this is a sibling route rather than a fallback inside the page route above.
  app.get("/theme-explore/:themeId/partial/:partialId", (req: Request, res: Response) => {
    const themeId = String(req.params.themeId ?? "");
    const partialId = String(req.params.partialId ?? "");

    const theme = resolveStaticTheme(res, { themes: deps.themes, themeId });
    if (!theme) return;

    const html = renderStaticPartial({ theme, partialId });
    if (html === null) {
      res.status(404).type(PLAIN_TEXT).send(`partial '${partialId}' was not found in theme '${themeId}'`);
      return;
    }

    res.set("Cache-Control", "no-store").set("Content-Security-Policy", PREVIEW_SANDBOX).type("text/html").send(html);
  });

  // Templated (`.liquid`) theme preview — see this file's header for why this route, unlike its two
  // siblings above, is gated. `requireAdminSession` is applied as route-scoped middleware (not a
  // blanket mount over this whole file) so the two static-tier routes above stay exactly as ungated
  // as they always were.
  app.get(
    "/theme-explore/:themeId/template/:templateId",
    requireAdminSession(deps),
    async (req: Request, res: Response) => {
      try {
        if (!(await authorizeThemeSetPermission(deps, res))) return;

        const themeId = String(req.params.themeId ?? "");
        const templateId = String(req.params.templateId ?? "");

        const target = resolveTemplatedPreviewTarget(res, { themes: deps.themes, themeId, templateId });
        if (!target) return;
        const { theme, route } = target;

        // Real content, no fixtures: the same `listPublishedPosts` the live site itself renders from
        // (`routes/site/pages.ts`) — never a draft, matching the visibility bar the ungated static
        // routes above already rely on. A workspace with no published posts yet renders with `post`
        // left `undefined`, which is an honest, correct preview state (an empty entry page), not a
        // failure to seed data.
        const { posts } = await listPublishedPosts({ deps: { repo: deps.postRepo }, input: { workspaceId: deps.workspaceId } });
        const post = route === "post" ? posts[0] : undefined;

        // Products stay hard-coded empty — a deliberate containment, not an unfinished wiring gap.
        // `fashion-modern/templates/product.liquid:118` still contains a bare
        // `{{ product.description | raw }}`, inert TODAY only because `description` is never a key on
        // `SiteProduct` (`storefront.ts`/`render.ts`'s `siteProductRenderShape` both build explicit
        // field lists with no `description` — see the 2026-08-13 security pass, Note on priority #4).
        // Wiring a real `commerceProductRepo`/`store` into THIS route is exactly the kind of change
        // that could someday put `description` back on this object without anyone touching that
        // template line — do not "finish" this by adding one without re-verifying that `| raw` stays
        // inert first. A workspace with real commerce products configured will show them on the live
        // site but NOT in this preview — a disclosed, deliberate divergence, not a bug.
        const products: SiteProduct[] = [];
        const product = route === "product" ? products[0] : undefined;

        const [widgets, mediaTransformVersions, mediaAssetMetadata, pageHtmlEmbeds] = await Promise.all([
          resolveWidgetsForRender(deps, theme, post),
          resolveMediaTransformVersionsForRender(deps),
          resolveMediaAssetMetadataForRender(deps, post),
          resolveHtmlEmbedsForRender(deps, post),
        ]);

        const html = await renderSite({
          theme,
          route,
          siteTitle: await resolveSiteTitleForRender(deps),
          timeZone: await resolveSiteTimeZoneForRender(deps),
          posts,
          post,
          products,
          product,
          widgets,
          mediaTransformVersions,
          mediaAssetMetadata,
          pageHtmlEmbeds,
          // The exact file the operator selected, not whichever one `resolveLiquidTemplateId` would
          // have preferred for `route` — see `liquidTemplateContextRoute`'s own doc.
          liquidTemplateIdOverride: templateId,
        });

        // Never cached, same reasoning as the two static-tier routes above.
        res.set("Cache-Control", "no-store").type("html").send(html);
      } catch {
        res.status(500).type(PLAIN_TEXT).send("preview render failed");
      }
    }
  );
}

import type { Express, RequestHandler } from "express";
import { requestThemePreviewRefresh } from "#src/features/theme/preview-refresh";
import { syncThemeRoster } from "#src/features/theme/theme-roster-sync";
import { requireAdminSession, getAuthedPrincipal } from "../../admin-http/dev-auth.js";
import type { RouteDeps } from "#src/server/routes/types";

/** Unique asset directory also versions relative CSS imports, url() assets and JS module imports. */
export function freshThemePreviewHtml(
  { html, revision }: { html: string; revision: string },
  _optional: Record<string, never> = {},
): string {
  return html.replaceAll("/theme-assets/", `/theme-preview-assets/${encodeURIComponent(revision)}/`);
}

/**
 * A query token opts into authenticated preview rendering; ordinary public caching is untouched.
 *
 * `syncThemes` runs ahead of EVERY request except a theme asset's — public pages, the admin API
 * (the Themes screen lists the roster; the active-theme PATCH validates against it) and previews
 * alike — and must be a cheap no-op when nothing changed (`syncThemeRoster`). It used to run for
 * public GETs only and to re-load just the themes this process already had, which is how a theme the
 * agent daemon created and activated stayed unknown here until a manual Rescan (2026-10-08). Asset
 * requests skip it: a page load fans out into dozens of them, and the page request ahead of them has
 * already synced.
 */
export function createThemePreviewMiddleware(
  { authenticate, syncThemes, rememberRevision }: { authenticate: RequestHandler; syncThemes: () => void; rememberRevision?: (required: { revision: string }, optional: {}) => void },
  _optional: Record<string, never> = {},
): RequestHandler {
  return (req, res, next) => {
    const isAsset = /^\/(?:theme-assets|theme-preview-assets)(?:\/|$)/.test(req.path ?? "");
    const revision = req.query.__tovu_preview;
    if (typeof revision !== "string" || !/^[\w-]{1,100}$/.test(revision)) {
      try {
        // The outer desktop guest uses public URLs. Daemon writes must update its render maps too,
        // while visitor caching and the asset response bytes keep their ordinary public behavior.
        if (!isAsset) syncThemes();
      } catch (error) { next(error); return; }
      next();
      return;
    }
    authenticate(req, res, (error?: unknown) => {
      if (error) {
        next(error);
        return;
      }
      try {
        // The daemon and external editors do not update this process's boot-time source maps.
        if (!isAsset) syncThemes();
        rememberRevision?.({ revision }, {});
        res.locals ??= {};
        res.locals.themePreviewRevision = revision;
        const send = res.send.bind(res);
        res.send = (body: unknown) => {
          // Public routes set their cache policy later; force preview policy at the final send.
          res.set("Cache-Control", "no-store");
          return send(typeof body === "string" && !isAsset ? freshThemePreviewHtml({ html: body, revision }) : body);
        };
        next();
      } catch (error) {
        next(error);
      }
    });
  };
}

export function registerThemePreviewRefresh(
  { app, deps }: { app: Express; deps: RouteDeps },
  _optional: Record<string, never> = {},
): (required: { revision: string }, optional?: {}) => boolean {
  // Asset loads from sandboxed previews may omit cookies (fonts use anonymous CORS). The
  // authenticated document establishes the namespace; only that namespace rewrites public CSS.
  const authenticatedRevisions = new Set<string>();
  app.use(
    createThemePreviewMiddleware({
      authenticate: requireAdminSession(deps),
      rememberRevision: ({ revision }) => {
        authenticatedRevisions.add(revision);
        if (authenticatedRevisions.size > 512) authenticatedRevisions.delete(authenticatedRevisions.values().next().value!);
      },
      syncThemes: () => {
        syncThemeRoster({ themes: deps.themes, themesDir: deps.themesDir });
      },
    }),
  );
  app.post(
    "/api/admin/v1/workspaces/:workspaceId/themes/preview-reload",
    requireAdminSession(deps),
    async (req, res) => {
      if (String(req.params.workspaceId) !== deps.workspaceId) {
        res.status(404).json({ error: "workspace was not found" });
        return;
      }
      const principal = getAuthedPrincipal(res);
      const auth = await deps.authorize({
        principalId: principal.id,
        workspaceId: deps.workspaceId,
        permission: "theme.set",
        entityType: "theme",
      });
      if (!auth.allowed) {
        res.status(403).json({ error: "not authorized for 'theme.set'" });
        return;
      }
      try {
        res.json(requestThemePreviewRefresh({ themesDir: deps.themesDir }));
      } catch {
        res.status(500).json({ error: "preview reload failed" });
      }
    },
  );
  return ({ revision }) => authenticatedRevisions.has(revision);
}

import type { Express, Request, Response } from "express";
import { parse as parseCookie } from "cookie";
import { resolveWorkspaceOrigin, toAbsoluteUrl } from "@jini-ai/cms/seo";
import { resolveActiveThemeId } from "#src/features/presentation/active-theme-id";
import { resolveActiveTheme } from "#src/features/theme/active-theme";
import { readPreviewSwitcher, choosePreviewTheme } from "#src/features/theme/preview-switcher";
import { decoratePreviewPage } from "#src/features/theme/preview-switcher-html";
import type { RouteDeps } from "#src/server/routes/types";
import { setRequestRenderTheme } from "./render-theme-override.js";

const COOKIE = "tovu_theme_preview";
const EXCLUDED = /^\/(?:admin|api|theme-assets|theme-explore|theme-preview|m|site-chat|agent-icons|assets)(?:\/|$)/;

function isPageRequest({ request }: { request: Request }, _options = {}): boolean {
  return ["GET", "HEAD"].includes(request.method) && !EXCLUDED.test(request.path);
}

type PreviewPage = Omit<Parameters<typeof decoratePreviewPage>[0], "html">;

function queryValue({ request }: { request: Request }, _options = {}): string | undefined {
  return request.query.theme === undefined ? undefined : String(request.query.theme);
}

function requestChoice({ request, config, activeThemeId }: {
  request: Request; config: PreviewPage["config"]; activeThemeId: string;
}, _options = {}) {
  const delivery = request.get("x-tovu-static-export") === "1" ? "static" as const : "live" as const;
  const variant = delivery === "static" ? /^\/_themes\/([A-Za-z0-9_-]+)(\/.*)?$/.exec(request.path) : null;
  const choice = choosePreviewTheme({ config, activeThemeId, query: variant?.[1] ?? queryValue({ request }),
    cookie: delivery === "live" ? parseCookie(request.headers.cookie ?? "")[COOKIE] : undefined });
  return { delivery, variant, choice };
}

function stripVariantPrefix({ request, path }: { request: Request; path: string }, _options = {}): void {
  const queryStart = request.url.indexOf("?");
  request.url = path + (queryStart === -1 ? "" : request.url.slice(queryStart));
}

async function preparePreviewPage({ request, response, deps }: { request: Request; response: Response; deps: RouteDeps }, _options = {}): Promise<PreviewPage | undefined> {
  // The preview reader handles missing defaults; a title pin must never block a public page.
  const active = resolveActiveTheme(deps, await resolveActiveThemeId(deps));
  if (!active || typeof active === "string") return undefined;
  const activeThemeId = active.manifest.id;
  const config = await readPreviewSwitcher({ ...deps, activeThemeId });
  if (!config.enabled) return undefined;
  const { delivery, variant, choice } = requestChoice({ request, config, activeThemeId });
  if (variant && !config.themes.some(theme => theme.themeId === variant[1])) {
    response.sendStatus(404); return undefined;
  }
  if (variant) stripVariantPrefix({ request, path: variant[2] ?? "/" });
  setRequestRenderTheme({ response, themeId: choice.themeId });
  persistChoice({ request, response, choice, delivery });
  const origin = await resolveWorkspaceOrigin({ originRegistry: deps.originRegistry, workspaceId: deps.workspaceId, runtimeMode: deps.seoDeps.runtimeMode }, {});
  return { config, activeThemeId, currentThemeId: choice.themeId, path: request.path,
    origin: origin ? toAbsoluteUrl({ origin, path: "/" }, {}) : undefined, preview: choice.preview, delivery };
}

/** Public preview adapter: choices stay in res.locals; the real page/product routes still render.
 * The send seam covers every theme tier and export without a new renderer. */
export function applyThemePreviewSwitcher({ app, deps }: { app: Express; deps: RouteDeps }, _options = {}): void {
  app.use(async (req, res, next) => {
    if (!isPageRequest({ request: req })) return next();
    try {
      const page = await preparePreviewPage({ request: req, response: res, deps });
      if (res.headersSent) return undefined;
      if (page) decorateResponse({ response: res, page });
      next();
    } catch (error) { next(error); }
    return undefined;
  });
}

function decorateResponse({ response, page }: { response: Response; page: PreviewPage }, _options = {}): void {
  const send = response.send;
  response.send = function (body: unknown): Response {
    if (typeof body === "string" && String(response.getHeader("content-type")).includes("text/html")) {
      response.vary("Cookie");
      if (page.preview) response.set("Cache-Control", "private, no-store");
      body = decoratePreviewPage({ ...page, html: body });
    }
    return send.call(this, body);
  };
}

function persistChoice({ request, response, choice, delivery }: {
  request: Request; response: Response; choice: ReturnType<typeof choosePreviewTheme>; delivery: "live" | "static";
}, _options = {}): void {
  if (delivery === "static") return;
  const options = { path: "/", httpOnly: true, sameSite: "lax" as const, secure: request.secure };
  if (choice.reset) response.clearCookie(COOKIE, options);
  else {
    if (choice.cookie !== undefined) response.cookie(COOKIE, choice.cookie, options);
  }
}

/** Public declarative export assets; templates and undeclared files are never served. */
import type { Express, Response } from "express";
import type { Clock } from "@jini-ai/core/primitives";
import { ADMIN_SURFACE_FILES_PER_IP, createRateLimiter, resolveClientIp, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import type { TovuAgentPluginLifecycle } from "#src/features/agent-plugins/lifecycle";
import { createPluginExportSource, PLUGIN_EXPORT_FILES_PREFIX, type PluginExportSource } from "#src/features/agent-plugins/exports/source";

interface ExportFilesDeps {
  readonly workspaceId: string;
  readonly clock: Clock;
  readonly agentPluginLifecycle: TovuAgentPluginLifecycle;
}

/** The only public export file kinds: stylesheet, PNG/SVG artwork and declared scripts. */
const EXPORT_FILE_TYPES: Readonly<Record<string, string>> = { ".css": "text/css; charset=utf-8", ".png": "image/png", ".svg": "image/svg+xml", ".js": "text/javascript; charset=utf-8" };

/** Fixed refusal never exposes containment errors or local package paths. */
function notFound({ res }: { res: Response }, _options = {}): void {
  res.status(404).set({ "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }).type("text/plain").send("Not found");
}

/** Match URL ids/path against declarations before any file read; no URL path is joined to disk.
 * @complexity O(p + e + a) catalog, export and declared asset scans, then one contained read.
 */
async function resolveFile(required: { source: PluginExportSource; workspaceId: string; pluginId: string; component: string; path: string }, _options = {}) {
  const packages = await required.source.list({ workspaceId: required.workspaceId });
  const owners = packages.filter(item => item.enabled && item.plugin.pluginId === required.pluginId);
  if (owners.length !== 1) return undefined;
  const owner = owners[0]!;
  const entry = Object.entries(owner.exports).find(([name]) => name === required.component)?.[1];
  if (!entry) return undefined;
  // A remote script is declared by URL and loaded from its own host; only package files are served here.
  const scripts = (entry.scripts ?? []).filter(script => !script.startsWith("https://"));
  const declared = [entry.styles, ...Object.values(entry.assets ?? {}), ...scripts];
  const type = EXPORT_FILE_TYPES[required.path.slice(required.path.lastIndexOf(".")).toLowerCase()];
  // An unknown extension (e.g. a declared .html) is refused, never served under an image type.
  // JavaScript is served only from `scripts`; a .js path declared under assets is still refused.
  if (!type || !declared.includes(required.path) || (type.startsWith("text/javascript") && !scripts.includes(required.path))) return undefined;
  const body = await required.source.readAsset({ plugin: owner.plugin, filename: required.path });
  return { body, type };
}

/** Rate-limit before catalog I/O. SVG is an inert image even when navigated to directly.
 * @complexity One lifecycle catalog scan and one declared file read per allowed request.
 */
export function registerPluginExportFilesRoute(required: { app: Express; deps: ExportFilesDeps }, options: { source?: PluginExportSource; limiter?: RateLimiter } = {}): void {
  const { app, deps } = required;
  const source = options.source ?? createPluginExportSource({ lifecycle: deps.agentPluginLifecycle });
  const limiter = options.limiter ?? createRateLimiter({ profile: ADMIN_SURFACE_FILES_PER_IP, clock: deps.clock });
  app.get(`${PLUGIN_EXPORT_FILES_PREFIX}/:pluginId/:component/*`, async (req, res) => {
    try {
      const limit = await limiter.check({ key: resolveClientIp(req) });
      if (!limit.allowed) {
        res.status(429).set({ "Retry-After": String(limit.retryAfterSeconds), "Cache-Control": "no-store" }).send("Too many requests");
        return undefined;
      }
      const file = await resolveFile({ source, workspaceId: deps.workspaceId, pluginId: String(req.params.pluginId),
        component: String(req.params.component), path: String((req.params as Record<string, string>)[0]) });
      if (!file) return notFound({ res });
      res.status(200).set({ "Content-Type": file.type, "X-Content-Type-Options": "nosniff",
        "Content-Security-Policy": "default-src 'none'; sandbox", "Referrer-Policy": "no-referrer",
        "Cache-Control": "public, max-age=60" }).send(typeof file.body === "string" ? file.body : Buffer.from(file.body));
    } catch {
      notFound({ res });
    }
    return undefined;
  });
}

import type { Express } from "express";
import type { Clock } from "@jini-ai/core/primitives";
import { ADMIN_SURFACE_FILES_PER_IP, createRateLimiter, resolveClientIp, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";

import {
  createAgentPluginAdminSurfaceSource,
  findAdminSurface,
  readSurfaceFile,
  ADMIN_SURFACE_FILES_PREFIX,
  type AdminSurfaceSource,
} from "#src/features/agent-plugins/admin-surfaces/surfaces";
import type { TovuAgentPluginLifecycle } from "#src/features/agent-plugins/lifecycle";

/**
 * @file `AGENT_PLUGIN_SURFACE_FILE` — `GET /api/agent-plugin-surfaces/v1/:pluginId/:surfaceId/<path>`:
 * the static files of one plugin-owned admin surface, which the admin page renders in an
 * `<iframe sandbox="allow-scripts">`.
 *
 * Why PUBLIC (not behind `requireAdminSession`): the frame runs in an opaque origin, so its module
 * scripts are cross-origin CORS fetches that carry no cookie; an authenticated route would break
 * every surface. What makes that safe: only surfaces Jini's loader admitted (active plugin, the
 * build's own shipped digest) are served; only the surface's declared `entry` and `files` are read,
 * through the lifecycle's contained read (symlinks resolved, nothing outside the package root);
 * every response carries Jini's isolation headers (strict CSP with `sandbox allow-scripts` and
 * `frame-ancestors 'self'`, `nosniff`, `no-referrer`). Surface files are plugin code that ships in
 * the build, never secrets: start data reaches the frame only through the authenticated bootstrap.
 *
 * Request ids and the path are only compared with declared values, never joined into a path here.
 * The existing http-kit limiter charges each client IP before any contribution load or file read.
 */

export interface AdminSurfaceFilesRouteDeps {
  readonly clock: Clock;
  readonly workspaceId: string;
  readonly agentPluginLifecycle: Pick<TovuAgentPluginLifecycle, "loadPluginContributions" | "readTrustedPluginFile">;
  /** Test seam; defaults to the lifecycle-backed source. */
  readonly adminSurfaceSource?: AdminSurfaceSource;
}

function notFound(res: import("express").Response): void {
  res.status(404).set({ "Content-Type": "text/plain; charset=utf-8", "X-Content-Type-Options": "nosniff", "Cache-Control": "no-store" }).send("Not found");
}

/** Mount public static files with a per-route limiter; denied calls do no plugin I/O.
 * @complexity O(p + s) admitted plugin/surface scan per allowed request; limiter state is window-bounded.
 */
export function registerAdminSurfaceFilesRoute(app: Express, deps: AdminSurfaceFilesRouteDeps, options: { readonly limiter?: RateLimiter } = {}): void {
  const limiter = options.limiter ?? createRateLimiter({ profile: ADMIN_SURFACE_FILES_PER_IP, clock: deps.clock });
  const source = deps.adminSurfaceSource ?? createAgentPluginAdminSurfaceSource({ lifecycle: deps.agentPluginLifecycle });
  // No param fallbacks: Express sets both named params of a matched route, and the `*` tail as a
  // string ("" for an empty tail), pinned in the routes integration test.
  app.get(`${ADMIN_SURFACE_FILES_PREFIX}/:pluginId/:surfaceId/*`, async (req, res) => {
    try {
      const limit = await limiter.check({ key: resolveClientIp(req) });
      if (!limit.allowed) {
        res.status(429).set({ "Retry-After": String(limit.retryAfterSeconds), "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }).type("text/plain").send("Too many requests");
        return undefined;
      }
      const surface = await findAdminSurface({ source, workspaceId: deps.workspaceId, pluginId: String(req.params.pluginId), surfaceId: String(req.params.surfaceId) });
      const file = surface ? await readSurfaceFile({ source, surface, path: String((req.params as Record<string, string>)[0]) }) : undefined;
      if (!file?.ok) return notFound(res);
      res.status(200).set(file.headers).send(file.body);
    } catch {
      // A containment refusal or read fault names server paths; never echoed.
      notFound(res);
    }
    return undefined;
  });
}

import type { Express, Request } from "express";

import { ApiConnectionError } from "@jini-ai/integrations/api-connections";
import type { RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { API_CONNECTION_OAUTH_CALLBACK_PATH, type ApiConnectionHost } from "#src/features/api-connections/host";
import { clearedBrowserBindingCookie, readBrowserBinding } from "#src/features/api-connections/browser-binding";
import { renderOAuthCallbackPage, type OAuthCallbackFailureReason } from "../oauth/callback-page.js";
import { resolvePublicOrigin } from "../oauth/public-origin.js";

/**
 * @file The PUBLIC OAuth callback for plugin-declared API connections (hosted runtime). Separate from
 * the external-MCP callback on purpose: a different lifecycle (Jini api-connections), one fixed path
 * every provider registers once.
 *
 * Session-less for the reason `external-mcp/oauth-callback.ts` documents (`tovu_session` is
 * `SameSite=Strict`; the provider's redirect is a cross-site navigation). What authenticates the
 * request is the single-use, expiring attempt its `state` names, bound to workspace, actor, plugin
 * connection, scopes, this exact callback URL and the starting browser (the `SameSite=Lax` binding
 * cookie the host sign-in link set, read here and cleared once used), plus the provider's one-time code. The attempt is
 * peeked only to route the request to its connection; Jini consumes it and checks every binding.
 *
 * After a successful exchange, the plugin's declared callback fields (never the code or state) are
 * left in the host's consume-once inbox for that plugin's admin-surface handler.
 *
 * Nothing from the request or the provider reaches the page: failures map onto the shared page's
 * closed reason vocabulary by error CODE, and full detail goes to the server log only.
 */

export const API_CONNECTION_CALLBACK_MESSAGE_TYPE = "tovu:api-connection-connected";
const MAX_STATE_LENGTH = 512;

export interface ApiConnectionOAuthCallbackRouteDeps {
  readonly host: ApiConnectionHost;
  readonly callbackLimiter: RateLimiter;
  /** Injectable for tests; production logs to the console. */
  readonly log?: (line: string) => void;
}

/** Only string query values, as the provider sent them; Jini picks the OAuth names and declared fields. */
function stringParams(query: Record<string, unknown>): Record<string, string> {
  return Object.fromEntries(Object.entries(query).filter((entry): entry is [string, string] => typeof entry[1] === "string"));
}

/** Code-only classification: never reads `message`, so no provider text can be rendered. @complexity O(1). */
function classify(error: unknown): OAuthCallbackFailureReason {
  if (!(error instanceof ApiConnectionError)) return "exchange_failed";
  if (error.code === "invalid-attempt" || error.code === "attempt-superseded") return "state_expired";
  if (error.code === "access-denied") return "provider_denied";
  // A same-account switch would share the live grant; the person needs "reconnect", not a retry.
  if (error.code === "account-unchanged") return "account_unchanged";
  return "exchange_failed";
}

function send(res: Parameters<Parameters<Express["get"]>[1]>[1], status: number, reason?: OAuthCallbackFailureReason): void {
  res.status(status).set("Cache-Control", "no-store").type("html")
    .send(renderOAuthCallbackPage(reason ? { ok: false, reason, messageType: API_CONNECTION_CALLBACK_MESSAGE_TYPE } : { ok: true, messageType: API_CONNECTION_CALLBACK_MESSAGE_TYPE }));
}

/** The exact URL this request arrived on, as the attempt recorded it. */
function callbackUrl(req: Request): string {
  return `${resolvePublicOrigin(req)}${API_CONNECTION_OAUTH_CALLBACK_PATH}`;
}

/** The attempt's connection in this workspace, or null; the attempt itself is not consumed here. */
async function routeAttempt(host: ApiConnectionHost, state: string) {
  const attempt = await host.records.peekAttempt({ state });
  if (!attempt || attempt.workspaceId !== host.workspaceId) return null;
  const connection = (await host.listConnections({ pluginId: attempt.pluginId })).find((candidate) => candidate.descriptor.connectionId === attempt.connectionId);
  return connection ? { attempt, connection } : null;
}

/**
 * Only after a successful exchange: the plugin's declared callback fields wait in the host's inbox
 * for that plugin's surface handler, keyed by the attempt's own workspace, plugin and connection and
 * by the service's attempt id (what the surface was given, never the state), so no other plugin or
 * second read gets them.
 */
function depositCallbackFields(host: ApiConnectionHost, input: { readonly attempt: { readonly workspaceId: string; readonly pluginId: string; readonly connectionId: string }; readonly attemptId: string; readonly fields: Readonly<Record<string, string>> }): void {
  if (Object.keys(input.fields).length === 0) return;
  const { workspaceId, pluginId, connectionId } = input.attempt;
  host.callbackInbox.deposit({ workspaceId, pluginId, connectionId, attemptId: input.attemptId, fields: input.fields });
}

/** Codes are closed vocabularies; messages and causes may carry provider text and stay out of logs. */
function safeErrorLabel(error: unknown): string {
  if (!(error instanceof Error)) return "unknown";
  const code = (error as { code?: unknown }).code;
  return `${error.name} ${typeof code === "string" ? code : "unknown"}`;
}

/**
 * Mounts `GET {API_CONNECTION_OAUTH_CALLBACK_PATH}`.
 * @complexity O(1) per request plus one bounded token exchange and one contribution load.
 */
export function registerApiConnectionOAuthCallbackRoute(app: Express, deps: ApiConnectionOAuthCallbackRouteDeps): void {
  const log = deps.log ?? ((line: string) => { console.error(line); }); // eslint-disable-line no-console
  app.get(API_CONNECTION_OAUTH_CALLBACK_PATH, async (req, res) => {
    // First: the route is anonymous and each hit can cost an outbound token exchange.
    if (!(await deps.callbackLimiter.check({ key: resolveClientIp(req) })).allowed) return send(res, 429, "rate_limited");
    const params = stringParams(req.query as Record<string, unknown>);
    const state = params.state ?? "";
    // The browser that started the sign-in carries this (`browser-binding.ts`); any other browser
    // carries none, and Jini refuses the attempt.
    const browserBinding = readBrowserBinding({ cookieHeader: req.get("cookie") });
    if (state === "" || state.length > MAX_STATE_LENGTH) return send(res, 400, "no_state");
    try {
      const routed = await routeAttempt(deps.host, state);
      // Unknown, used, foreign-workspace or no-longer-declared: the same answer for each.
      if (!routed) return send(res, 400, "state_expired");
      const { attempt, connection } = routed;
      // `complete` consumes the attempt whatever it decides, so the binding is spent either way.
      res.append("Set-Cookie", clearedBrowserBindingCookie());
      const done = await deps.host.serviceFor({ connection }).complete({ workspaceId: attempt.workspaceId, actorId: attempt.actorId, redirectUri: callbackUrl(req), callbackParams: params, browserBinding });
      depositCallbackFields(deps.host, { attempt, attemptId: done.attemptId, fields: done.callbackFields });
      return send(res, 200);
    } catch (error) {
      log(`api-connection oauth callback failed: ${safeErrorLabel(error)}`);
      return send(res, 400, classify(error));
    }
  });
}

/** Member HTTP boundary only: identity and scope come from the host; Jini owns orders and money. */
import type { IRouter, Request, Response } from "express";
import { CommerceCheckoutValidationError, CommerceOrderNotFoundError, CommercePriceNotFoundError,
  CommerceProductNotFoundError, commerceBuyerStatus, toCommerceBuyerOrder, type CommerceOrderView } from "@jini-ai/commerce";
import { escapeHtml } from "#src/platform/html/escape";
import { resolveMemberSession } from "#src/features/members/access-resolver";
import { MemberLoginError } from "#src/features/member-login/index";
import { createRateLimiter, OUTBOUND_CALL_PER_IP, resolveClientIp, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import type { RouteDeps } from "#src/server/routes/types";
import { uniqueMemberCookie } from "../members/oidc-deps.js";
import { isSameOriginCommentPost } from "../site/comments-submit.js";
import { resolveProtocol } from "../oauth/public-origin.js";

/** Narrow structural port; no credential, provider or ledger mutation capability crosses HTTP. */
export interface CommerceHttpPort {
  forRequest?(): CommerceHttpPort;
  status(): Promise<{ active: boolean; ready: boolean; reason: string | null }>;
  activate(): Promise<{ active: boolean; ready: boolean; reason: string | null }>;
  checkoutOrigin(): Promise<string | null>;
  createOrder(input: { memberId: string; priceId: string; quantity?: number }): Promise<unknown>;
  pay(input: { memberId: string; orderId: string }): Promise<unknown>;
  readOrder(input: { memberId: string; orderId: string }): Promise<unknown>;
}
export type CommerceHttpDeps = Pick<RouteDeps, "workspaceId" | "clock" | "memberRepo" | "memberSessionRepo"> & {
  commerce?: CommerceHttpPort;
  renderCommercePage?: (required: { req: Request; res: Response; title: string; body: string }) => Promise<string>;
};

const ORDERS = "/api/commerce/v1/workspaces/:workspaceId/orders";
const identifier = (value: unknown): value is string => typeof value === "string" && value.length > 0 && value.length <= 256;
type RequestContext = { req: Request; res: Response; deps: CommerceHttpDeps; limiter: RateLimiter; page?: boolean };

/** Resolve only the member cookie, including revocation; operator cookies cannot purchase. O(1) reads. */
async function buyer({ req, deps }: Pick<RequestContext, "req" | "deps">): Promise<string | null> {
  let sessionToken: string | undefined;
  try { sessionToken = uniqueMemberCookie({ req, name: "tovu_member_session" }); }
  catch (error) {
    if (error instanceof MemberLoginError) return null;
    throw error;
  }
  const session = await resolveMemberSession({ sessions: deps.memberSessionRepo, workspaceId: deps.workspaceId,
    sessionToken, nowIso: deps.clock.nowIso() });
  if (!session) return null;
  const member = await deps.memberRepo.findById({ workspaceId: deps.workspaceId, id: session.memberId });
  if (!member || member.status !== "active") return null;
  if (member.credentialsRevokedAt && session.createdAt < member.credentialsRevokedAt) return null;
  return member.id;
}

/** A mutation shares one host configuration snapshot; read-only ledger reads need none. O(1). */
function requestCommerce({ req, deps }: Pick<RequestContext, "req" | "deps">): CommerceHttpPort | undefined {
  return req.method === "POST" ? (deps.commerce?.forRequest?.() ?? deps.commerce) : deps.commerce;
}

/** Deny before effects on foreign scope, off/unavailable commerce, failed auth or rate budget. O(1) I/O. */
async function admit(context: RequestContext): Promise<{ memberId: string; commerce: CommerceHttpPort } | null> {
  const { req, res, deps, limiter } = context;
  res.set("Cache-Control", "no-store");
  if (req.params.workspaceId && req.params.workspaceId !== deps.workspaceId) {
    await reject(context, 404, "This shop was not found.", "SHOP_NOT_FOUND"); return null;
  }
  const commerce = requestCommerce({ req, deps });
  if (!commerce) { await reject(context, 503, "Checkout is not enabled for this shop.", "COMMERCE_UNAVAILABLE"); return null; }
  const limit = await limiter.check({ key: resolveClientIp(req) });
  if (!limit.allowed) {
    res.set("Retry-After", String(limit.retryAfterSeconds));
    await reject(context, 429, "Too many checkout requests. Please wait a minute and try again.", "RATE_LIMIT_EXCEEDED"); return null;
  }
  const memberId = await buyer(context);
  if (!memberId) { await reject(context, 401, "Sign in as a shop member to view or pay for your order.", "MEMBER_SIGN_IN_REQUIRED"); return null; }
  if (req.method === "POST" && !await admitWrite({ req, res, commerce })) return null;
  return { memberId, commerce };
}

/** A host theme wraps escaped buyer content; minimal hosts still receive a complete HTML page. O(n) body bytes. */
async function buyerPage({ req, res, deps }: Pick<RequestContext, "req" | "res" | "deps">,
  { status, title, message, order }: { status: number; title: string; message: string; order?: { id: string; status: string } }): Promise<void> {
  const orderMarkup = order ? `<p>Order <span>${escapeHtml(order.id)}</span></p>` : "";
  const state = order ? ` data-order-status="${escapeHtml(order.status)}"` : "";
  const body = `<section class="wrap commerce-order"${state}><h1>${escapeHtml(title)}</h1><p role="status">${escapeHtml(message)}</p>${orderMarkup}<p><a class="button" href="/products">Back to shop</a></p></section>`;
  const html = deps.renderCommercePage ? await deps.renderCommercePage({ req, res, title, body })
    : `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(title)}</title></head><body><main>${body}</main></body></html>`;
  res.status(status).set("Cache-Control", "no-store").type("html").send(html);
}

async function reject(context: RequestContext, status: number, error: string, code: string): Promise<void> {
  if (context.page) { await buyerPage(context, { status, title: "Check your order", message: error }); return; }
  context.res.status(status).json({ error, code });
}

/** Only ready checkout accepts mutations, with the existing site origin policy. O(1). */
async function admitWrite({ req, res, commerce }: { req: Request; res: Response; commerce: CommerceHttpPort }): Promise<boolean> {
  if (!isSameOriginCommentPost({ request: req })) {
    res.status(403).json({ error: "Open this shop to complete your purchase.", code: "SAME_ORIGIN_REQUIRED" }); return false;
  }
  const origin = await commerce.checkoutOrigin();
  if (!origin) { unavailable(res); return false; }
  const requestOrigin = req.get("origin") ?? `${resolveProtocol(req)}://${req.get("host")}`;
  if (requestOrigin !== origin) {
    res.status(403).json({ error: "Open the deployed shop to complete your purchase. The desktop app manages the catalog.",
      code: "DEPLOYED_SHOP_REQUIRED", checkoutOrigin: origin }); return false;
  }
  const status = await commerce.activate();
  if (status.ready) return true;
  unavailable(res, status.reason ?? undefined);
  return false;
}

function unavailable(res: Response, reason = "Checkout is not enabled for this shop."): void {
  res.status(503).json({ error: reason, code: "COMMERCE_UNAVAILABLE" });
}

/** Allow only catalog choice and bounded quantity; prices/account/mode/identity are server-owned. O(k) keys. */
function orderInput(body: unknown): { priceId: string; quantity?: number } | null {
  if (!body || typeof body !== "object" || Array.isArray(body)) return null;
  const value = body as Record<string, unknown>;
  if (!Object.keys(value).every(key => key === "priceId" || key === "quantity") || !identifier(value.priceId)) return null;
  if (value.quantity === undefined) return { priceId: value.priceId };
  if (!validQuantity(value.quantity)) return null;
  return { priceId: value.priceId, quantity: value.quantity };
}

function validQuantity(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1 && value <= 100;
}

function emptyObject(value: unknown): boolean {
  return value !== null && typeof value === "object" && !Array.isArray(value) && Object.keys(value).length === 0;
}

/** Known domain refusals are actionable; infrastructure failures never expose exception text. O(1). */
function failure({ res, error }: { res: Response; error: unknown }): void {
  if (error instanceof CommerceOrderNotFoundError || error instanceof CommercePriceNotFoundError || error instanceof CommerceProductNotFoundError) {
    res.status(404).json({ error: "This order or catalog item is unavailable for your account.", code: "COMMERCE_NOT_FOUND" }); return;
  }
  if (error instanceof CommerceCheckoutValidationError) {
    res.status(400).json({ error: error.message, code: "CHECKOUT_INVALID" }); return;
  }
  if (error instanceof Error && "code" in error && error.code === "COMMERCE_UNAVAILABLE") { unavailable(res, error.message); return; }
  res.status(503).json({ error: "The shop could not check your order. Retry this same order shortly; its payment status may still be updating.", code: "CHECKOUT_RETRY" });
}

/** Purchase/resume and read-only return routes. One limiter per mounted app, never per request.
 * @complexity O(1) setup and bounded point I/O per request; domain effects are delegated to Jini.
 */
export function registerCommerceRoutes({ app, deps }: { app: IRouter; deps: CommerceHttpDeps }, _optional = {}): void {
  const limiter = createRateLimiter({ profile: OUTBOUND_CALL_PER_IP, clock: deps.clock });
  app.post(ORDERS, async (req, res) => {
    try {
      const input = orderInput(req.body);
      if (!input) { res.status(400).json({ error: "Choose a price and a whole quantity from 1 to 100.", code: "CHECKOUT_INVALID" }); return; }
      const admitted = await admit({ req, res, deps, limiter }); if (!admitted) return;
      res.status(201).json(await admitted.commerce.createOrder({ memberId: admitted.memberId, ...input }));
    } catch (error) { failure({ res, error }); }
  });
  app.post(`${ORDERS}/:orderId/pay`, async (req, res) => {
    try {
      if (!identifier(req.params.orderId) || !emptyObject(req.body)) {
        res.status(400).json({ error: "Pay an existing order with an empty request body.", code: "CHECKOUT_INVALID" }); return;
      }
      const admitted = await admit({ req, res, deps, limiter }); if (!admitted) return;
      const view = await admitted.commerce.pay({ memberId: admitted.memberId, orderId: req.params.orderId }) as CommerceOrderView;
      const buyerView = toCommerceBuyerOrder({ view });
      res.json({ ...buyerView, payment: buyerView.payment ? { ...buyerView.payment, next: view.payment?.next } : null,
        intent: view.intent ? { ok: view.intent.ok, ...("error" in view.intent ? { error: view.intent.error } : {}) } : null });
    } catch (error) { failure({ res, error }); }
  });
  const read = async (req: Request, res: Response): Promise<void> => {
    try {
      const orderId = req.params.orderId ?? req.query.orderId;
      if (!identifier(orderId)) { res.status(400).json({ error: "Open your saved order link to check its payment status.", code: "ORDER_ID_REQUIRED" }); return; }
      const admitted = await admit({ req, res, deps, limiter }); if (!admitted) return;
      res.json(toCommerceBuyerOrder({ view: await admitted.commerce.readOrder({ memberId: admitted.memberId, orderId }) as CommerceOrderView }));
    } catch (error) { failure({ res, error }); }
  };
  app.get(`${ORDERS}/:orderId`, read);
  const page = async (req: Request, res: Response): Promise<void> => {
    const context = { req, res, deps, limiter, page: true };
    try {
      const orderId = req.query.orderId;
      if (!identifier(orderId)) { await reject(context, 400, "Open your saved order link to check its payment status.", "ORDER_ID_REQUIRED"); return; }
      const admitted = await admit(context); if (!admitted) return;
      const view = toCommerceBuyerOrder({ view: await admitted.commerce.readOrder({ memberId: admitted.memberId, orderId }) as CommerceOrderView });
      await buyerPage(context, { status: 200, ...commerceBuyerStatus({ view }), order: view.order });
    } catch (error) {
      const missing = error instanceof CommerceOrderNotFoundError;
      await reject(context, missing ? 404 : 503, missing ? "This order is unavailable for your account." : "The shop could not check your order. Retry this same order shortly; its payment status may still be updating.", missing ? "COMMERCE_NOT_FOUND" : "CHECKOUT_RETRY");
    }
  };
  app.get("/commerce/return", page);
  app.get("/commerce/cancel", page);
}

import { readRequestCookie } from "#src/server/http/request-cookie";
import type { Request } from "express";

import { getPublishedPostBySlug, PostNotFoundError } from "#src/features/post/post";
import { getPresentationSettings, PresentationSettingsNotFoundError } from "@jini-ai/cms/presentation";
import { DefaultMemberAccessResolver, resolvePostMemberAccess } from "#src/features/members/access-resolver";
import type { MemberAccessResolver } from "#src/features/members/index";
import { toContentPostResponse } from "#src/server/inbound/public-http/http/content/posts";
import type { RouteDeps, RouteRegistrar } from "#src/server/routes/types";
import { MEMBER_SESSION_COOKIE } from "../../../http/members.js";



/** No cookie-parser middleware is mounted. The shared reader preserves anonymous access
 * for direct handler tests with bare params and no headers, without duplicating pages.ts. */

/** Same `MemberAccessResolver` construction as `routes/site/pages.ts`'s own `createMemberAccessResolver`
 *  (ADR-030 §4) -- built per request from the three member repo ports already on `RouteDeps`, never a
 *  module-level singleton, for the same "tests inject their own in-memory repos per composition" reason
 *  that file's own doc gives. */
function createMemberAccessResolver(deps: RouteDeps): MemberAccessResolver {
  return new DefaultMemberAccessResolver({
    sessions: deps.memberSessionRepo,
    subscriptions: deps.memberSubscriptionRepo,
    tiers: deps.memberTierRepo,
  });
}

export const registerContentPostGetRoute: RouteRegistrar = (app, deps) => {
  app.get("/api/content/v1/workspaces/:workspaceId/posts/:slug", async (req, res) => {
    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
      res.status(404).json({ error: "workspace was not found" });
      return;
    }

    try {
      const slug = String(req.params.slug ?? "");
      const memberAccessResolver = createMemberAccessResolver(deps);
      const [{ post }, { settings }, memberContext] = await Promise.all([
        getPublishedPostBySlug({
          deps: { repo: deps.postRepo },
          input: { workspaceId: deps.workspaceId, slug },
        }),
        getPresentationSettings({
          deps: { repo: deps.presentationRepo },
          input: { workspaceId: deps.workspaceId },
        }),
        memberAccessResolver.resolveContext({
          workspaceId: deps.workspaceId,
          sessionToken: readRequestCookie({ request: req, name: MEMBER_SESSION_COOKIE }),
          nowIso: new Date().toISOString(),
        }),
      ]);

      // ADR-030 §4 gate, matching `routes/site/pages.ts`'s `GET /:slug` single-post gate: a denied
      // caller gets the SAME `PostNotFoundError`-shaped 404 a nonexistent slug already gets below, so
      // a gated post is indistinguishable from one that doesn't exist -- no separate 403/teaser
      // response that would itself leak "a post exists at this slug, but you can't read it."
      const decision = memberAccessResolver.decide({
        access: resolvePostMemberAccess(post.memberAccessJson),
        context: memberContext,
      });
      if (!decision.allowed) {
        throw new PostNotFoundError(`post '${slug}' was not found`);
      }

      // SECURITY FIX (2026-09-05, Gemini audit finding #7): this response depends on the caller's
      // OWN member session cookie (the gate decision above is per-visitor), so a shared cache in
      // front of the origin must never store and replay it to a later, different caller. Matches
      // the convention every other gated route in this codebase already uses for exactly this
      // reason -- `routes/site/pages.ts`'s `CACHE_CONTROL_PRIVATE_MEMBER_RESPONSE` and
      // `routes/site/media-rendition.ts`'s gated branch both send the identical `private, no-store`.
      res.set("Cache-Control", "private, no-store").json(toContentPostResponse({ post, activeThemeId: settings.activeThemeId }));
    } catch (err) {
      if (err instanceof PostNotFoundError || err instanceof PresentationSettingsNotFoundError) {
        res.status(404).json({ error: err.message });
        return;
      }

      res.status(500).json({ error: "internal error" });
    }
  });
};

import type { Express } from "express";
import { clearedBrowserBindingCookie, readBrowserBinding, EXTERNAL_MCP_BROWSER_BINDING } from '#src/features/api-connections/browser-binding';

import { ExternalMcpValidationError } from "../../../../../features/external-mcp/external-mcp-store.js";
import { notifyExternalMcpRosterChanged } from "../../../../../assistant/index.js";
import type { ExternalMcpOAuthService } from "../../../../../features/external-mcp/contracts.js";
import { OAuthError } from "@jini-ai/oauth";
import type { RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE, renderOAuthCallbackPage, type OAuthCallbackFailureReason } from "../oauth/callback-page.js";
import { EXTERNAL_MCP_OAUTH_CALLBACK_PATH, externalMcpOAuthCallbackUrl } from "./oauth-callback-url.js";

/**
 * @file The PUBLIC external-MCP OAuth callback — a route that is not behind `requireAdminSession`
 * (the same reasoning the since-removed Composio connector callback carried).
 *
 * Short version: `tovu_session` is `SameSite=Strict`, the provider redirects the operator's browser
 * here from its own origin, that is a cross-site top-level navigation, and the browser sends NO
 * cookie. An authenticated callback would reject every real handshake. The cookie policy is correct
 * and stays untouched.
 *
 * What authenticates the request instead is the OAuth `state`, sealed with the site key and bound
 * to workspace, server, provider, exact redirect URI, starting-browser proof and expiry. The
 * authenticated host sign-in GET sets a callback-scoped SameSite=Lax cookie; forwarding the
 * provider URL alone cannot complete sign-in. The encrypted verifier can cross
 * processes without a pending row. The provider's single-use code prevents replay within the TTL;
 * token exchange remains a server-side POST and plaintext credentials never reach the browser.
 *
 * ## Everything on this request is untrusted
 *
 * `state`, `code` and `error` arrive from a third party. They are narrowed to strings here and
 * validated (length, authentication, expiry and binding) in `oauth/authorization-code.ts` before any of
 * them reaches a token endpoint. Nothing from the request reaches the response body — see
 * `routes/oauth/callback-page.ts`.
 *
 * ## The full failure is logged, never rendered
 *
 * A completion failure can carry provider request detail, and this page is reachable by anyone who
 * can guess a URL. The full reason — including anything `OAuthError.message` or a provider's own
 * response carries — goes to the server log only. {@link classifyCallbackFailure} below is the one
 * place that failure is translated into something safe to send back, and it reads only a closed
 * union (`OAuthError.code`) or an error's class identity — never `.message`, never
 * `OAuthError.providerErrorCode`. The browser gets one of a small, fixed set of Tovu-authored reasons
 * (`OAuthCallbackFailureReason`), never a word of what the provider actually said.
 *
 * ## Federation hot-reload trigger (2026-09-11; fanned out to every runtime 2026-09-24)
 *
 * This is the PRIMARY operator-authorized event federation hot-reload fires on: once
 * `completeAuthorizationCallback` durably persists a completed sign-in, `notifyExternalMcpRosterChanged`
 * tells every registered federation runtime (the agent daemon, over HTTP; BYOK, in-process) to admit it
 * without a restart — see `external-mcp-roster-change.ts`'s own doc for the fan-out and
 * `mcp-federation/reload.ts` for why this is safe to call for ANY completed OAuth connection, not only
 * a first-time one (an already-admitted connectionId is a no-op, never a re-admission).
 *
 * Why THIS route is the right trigger, rather than `external-mcp-oauth.ts`'s
 * `completeAuthorizationCallback` itself: that file is the OAuth service shared by both this public
 * callback and the admin-facing device/redirect-connect routes, and it has no HTTP client of its own
 * — reaching across processes to the daemon is an HTTP-layer concern, which is exactly what THIS
 * file already is (it is the one place in the callback's call stack that is a route handler, not a
 * service method). Triggered only on the SUCCESS path, after the response-affecting work is done —
 * see the call site below for why a reload failure must never turn an otherwise-successful OAuth
 * connection into a page reporting failure to the operator.
 *
 * What authorizes this trigger, given the route itself carries no session: the SAME `state` this
 * route already requires to reach `completeAuthorizationCallback` at all (this file's own header,
 * above) — encrypted state minted by the admin-session-gated connect route or an authorized
 * assistant tool, followed by the provider's single-use code exchange. A remote MCP server or
 * an unauthenticated caller cannot manufacture a valid `state`, so by the time this trigger fires, an
 * starting browser also proved possession of its binding cookie, so an admin session is already
 * the reason this code path is running at all — the same "operator-
 * authorized" property `beginConnect`'s own gate establishes, just observed one hop later.
 */

export interface ExternalMcpOAuthCallbackRouteDeps {
  readonly oauth: ExternalMcpOAuthService;
  readonly callbackLimiter: RateLimiter;
}

/** The three query fields this callback reads, narrowed once at the edge. Anything else a provider
 *  appends is ignored rather than rejected — providers add their own bookkeeping parameters, and
 *  refusing them would break real handshakes. */
function parseCallbackQuery(query: Record<string, unknown>): { state: string; code?: string; error?: string } {
  return {
    state: typeof query.state === "string" ? query.state : "",
    ...(typeof query.code === "string" && query.code.length > 0 ? { code: query.code } : {}),
    ...(typeof query.error === "string" && query.error.length > 0 ? { error: query.error } : {}),
  };
}

/**
 * Classifies a caught completion failure into the closed, Tovu-authored reason vocabulary the
 * callback page renders.
 *
 * This is the whole security boundary for this route: it reads only `error.code` — a closed union,
 * `OAuthErrorCode` — or the error's class identity, and NEVER `error.message` or
 * `OAuthError.providerErrorCode`, either of which can carry a provider's own response text verbatim
 * (see Jini's `packages/oauth/src/errors.ts`'s header). Whatever this function returns is
 * safe to render and safe to put in the `postMessage` payload, because it can only ever be one of
 * the fixed strings in {@link OAuthCallbackFailureReason} — nothing it reads from `error` can
 * reach the return value directly.
 *
 * `OAUTH_INVALID_STATE` covers malformed, tampered, expired, or wrongly-bound state alike (see
 * `authorization-code.ts`'s `completeAuthorizationCode` doc) — `"state_expired"` is the one reason
 * name from the vocabulary that fits all of those, and is distinct from `"no_state"`, which the route
 * itself reports before ever calling the service (the query carried no `state` at all). Any
 * `OAuthError` code this function does not special-case, and any error that is not an `OAuthError` or
 * an `ExternalMcpValidationError` at all, becomes `"exchange_failed"` — the same generic reason a
 * caller that never classifies gets by default (`callback-page.ts`'s `renderOAuthCallbackPage`).
 *
 * @complexity O(1).
 */
function classifyCallbackFailure(error: unknown): OAuthCallbackFailureReason {
  if (error instanceof ExternalMcpValidationError) return "server_unknown";
  if (error instanceof OAuthError) {
    if (error.code === "OAUTH_INVALID_STATE") return "state_expired";
    if (error.code === "OAUTH_ACCESS_DENIED") return "provider_denied";
    return "exchange_failed";
  }
  return "exchange_failed";
}

/**
 * Mounts `GET {EXTERNAL_MCP_OAUTH_CALLBACK_PATH}/:serverId`.
 *
 * @complexity O(1) per request, plus one bounded token exchange.
 */
export function registerExternalMcpOAuthCallbackRoute(app: Express, deps: ExternalMcpOAuthCallbackRouteDeps): void {
  app.get(`${EXTERNAL_MCP_OAUTH_CALLBACK_PATH}/:serverId`, async (req, res) => {
    res.set({ 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer' });
    // In front of everything: the route is anonymous and each hit
    // can cost an outbound token exchange.
    if (!(await deps.callbackLimiter.check({ key: resolveClientIp(req) })).allowed) {
      res.status(429).type("html").send(renderOAuthCallbackPage({ ok: false, reason: "rate_limited", messageType: EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE }));
      return;
    }

    const params = parseCallbackQuery(req.query as Record<string, unknown>);
    if (params.state === "") {
      // No state means this was not reached by a redirect the provider issued. Nothing to complete.
      res.status(400).type("html").send(renderOAuthCallbackPage({ ok: false, reason: "no_state", messageType: EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE }));
      return;
    }

    const browserBinding = readBrowserBinding({ cookieHeader: req.get('cookie') }, EXTERNAL_MCP_BROWSER_BINDING);
    res.append('Set-Cookie', clearedBrowserBindingCookie({}, EXTERNAL_MCP_BROWSER_BINDING));
    if (browserBinding === '') {
      res.status(400).type('html').send(renderOAuthCallbackPage({ ok: false, reason: 'browser_mismatch', messageType: EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE }));
      return;
    }

    try {
      const serverId = String(req.params.serverId ?? "");
      await deps.oauth.completeAuthorizationCallback({ serverId, redirectUri: externalMcpOAuthCallbackUrl(req, serverId), params, browserBinding });
      // The seal-and-persist is already awaited inside `completeAuthorizationCallback`, so by the
      // time this responds the token is durable — the operator's next action is to close the window,
      // and reporting success over a write still in flight would report a connection that is one
      // restart from vanishing.
      //
      // Awaited (bounded to 5s — see `notifyExternalMcpRosterChanged`'s own `waitMs` default), but its
      // OUTCOME never changes this response: the OAuth connection above already succeeded and is
      // durable regardless of whether any registered runtime is reachable or its reload pass admits
      // the connection cleanly. Awaiting rather than firing-and-forgetting is what lets the operator
      // return to the chat and find the tool already usable in the common case, instead of only on
      // their NEXT turn — see this file's own header for the full trigger argument.
      await notifyExternalMcpRosterChanged();
      res.status(200).type("html").send(renderOAuthCallbackPage({ ok: true, messageType: EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE }));
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(`external-mcp oauth callback failed: ${error instanceof Error ? error.message : String(error)}`);
      res.status(400).type("html").send(
        renderOAuthCallbackPage({ ok: false, reason: classifyCallbackFailure(error), messageType: EXTERNAL_MCP_CALLBACK_MESSAGE_TYPE }),
      );
    }
  });
}

import express, { type Express, type NextFunction, type Request, type Response } from "express";
import type { MailFeedbackRoute } from "#src/features/mail/index";

/**
 * @file Mounts `POST /hooks/mail/:providerId` (provider bounce/complaint webhooks; unauthenticated,
 * the provider's signature is the credential). Must be registered BEFORE the app-level public JSON
 * parser: once body-parser has read a request a later raw parser is a no-op, and the signature is
 * over the exact bytes. Any content type is read raw, capped at the route's own body limit.
 */
export const MAIL_FEEDBACK_PATH = "/hooks/mail/:providerId";

/** Responds to the raw parser's own refusals (oversized, aborted) the way the ingest would. */
function rawBody(route: MailFeedbackRoute) {
  const parse = express.raw({ type: () => true, limit: route.maxBodyBytes });
  return (req: Request, res: Response, next: NextFunction): void => {
    parse(req, res, (error?: unknown) => {
      if (error === undefined) {
        next();
        return;
      }
      const tooLarge = (error as { type?: unknown }).type === "entity.too.large";
      res.status(tooLarge ? 413 : 400).json({ ok: false, error: tooLarge ? "body too large" : "unreadable body" });
    });
  };
}

/** @example registerMailFeedbackRoute({ app, route: createMailFeedbackRoute(deps) }) */
export function registerMailFeedbackRoute({ app, route }: { app: Express; route: MailFeedbackRoute }, _optional: Record<string, never> = {}): void {
  app.post(MAIL_FEEDBACK_PATH, rawBody(route), async (req: Request<{ providerId: string }>, res: Response) => {
    try {
      // No body at all leaves `req.body` as `{}`; an empty buffer is what the signature saw.
      const body = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
      const result = await route.handle({ providerId: req.params.providerId, rawBody: new Uint8Array(body), headers: req.headers });
      res.status(result.status).json(result.body);
    } catch {
      // Never echo internals to an unauthenticated caller; the provider retries a 5xx.
      res.status(500).json({ ok: false, error: "feedback could not be recorded" });
    }
  });
}

import { captureMemberSignedIn, observeMemberSignInFailure } from "./analytics.js";
import type { Express, Response } from "express";
import { completeSignIn, MemberAuthError, MemberReauthenticationRequiredError, MemberValidationError, type MemberSignInInput } from "#src/features/members/index";
import { MEMBER_SESSION_COOKIE, toPublicMemberResponse } from "../../http/members.js";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { checkMemberPost, checkMemberRequestLimits, memberStringBody, toPublicMembersWriteServiceDeps, type MemberPublicRouteDeps } from "./deps.js";

/**
 * ADR-030 §3: a DISTINCT cookie name from the admin `tovu_session` (which
 * lives in `inbound/admin-http/dev-auth.ts` and is never read/written here — see
 * ADR-PIPE-013 INV-NEW-01 / Enforcement, "no route in either family may read
 * the other's cookie"). `SameSite=Lax`, not `Strict`: the member arrives via
 * a top-level navigation from an email client, exactly the case
 * `SameSite=Strict` would break.
 *
 * Exported (2026-09-02 member-gating dispatch) so the public site's read-path gate
 * (`routes/site/pages.ts`) reads the SAME literal this route sets, rather than a second
 * hand-copied string that could silently drift from it.
 */
export { MEMBER_SESSION_COOKIE } from "../../http/members.js";
const MEMBER_COOKIE_OPTIONS = { httpOnly: true, path: "/", sameSite: "lax", secure: true } as const;

/** The sole member cookie setter, shared by password and challenge completion. O(1). */
export function setMemberSessionCookie({ res, rawToken, expiresAtIso }: {
  res: Response; rawToken: string; expiresAtIso: string;
}, _options = {}): void {
  const maxAge = Math.max(0, new Date(expiresAtIso).getTime() - Date.now());
  res.cookie(MEMBER_SESSION_COOKIE, rawToken, { ...MEMBER_COOKIE_OPTIONS, maxAge });
}

/** Clear exactly the attributes used to set the cookie, so sign-out removes it reliably. O(1). */
export function clearMemberSessionCookie({ res }: { res: Response }, _options = {}): void {
  res.clearCookie(MEMBER_SESSION_COOKIE, MEMBER_COOKIE_OPTIONS);
}

/** Credential failures share one body across password, link, code and reset; no exception text leaks. */
export function sendMemberAuthError({ res, error }: { res: Response; error: unknown }, options: { reset?: boolean } = {}): void {
  if (error instanceof MemberReauthenticationRequiredError) {
    res.status(401).json({ error: "sign in again to set a password", code: "REAUTHENTICATION_REQUIRED" });
    return;
  }
  if (error instanceof MemberAuthError) {
    res.status(401).json({ error: "invalid credentials", code: "INVALID_CREDENTIALS" });
    return;
  }
  if (options.reset && error instanceof MemberValidationError) {
    res.status(400).json({ error: error.message });
    return;
  }
  res.status(500).json({ error: "internal error" });
}

/** Exactly one credential form, with no missing/empty handle passed to the repository. O(1). */
export function completionCredential({ body, workspaceId }: { body: unknown; workspaceId: string }, _options = {}): MemberSignInInput | null {
  const token = memberStringBody({ body, kind: "token" });
  if (token?.token) return { workspaceId, token: token.token };
  const { challengeId, code } = memberStringBody({ body, kind: "code" }) ?? {};
  if (challengeId && code !== undefined && /^\d{6}$/.test(code)) return { workspaceId, challengeId, code };
  return null;
}

/**
 * @file `POST /api/members/v1/workspaces/:workspaceId/sign-in/complete` — the PUBLIC
 * complete-sign-in route (ADR-PIPE-013 Decision §2-3, C-013).
 *
 * Deliberately unauthenticated (no `requireAdminSession`, no `authorize()`) and gated by the
 * lighter `MAGIC_LINK_COMPLETE_ATTEMPT` per-IP profile. That limit is defense-in-depth: the
 * 256-bit raw link token makes brute force infeasible, and a six-digit code is bounded by the
 * per-challenge attempt reservation in `consumeMemberChallenge`, not by this IP counter.
 *
 * INV-NEW-01 (cookie isolation): sets ONLY `tovu_member_session`, never reads or writes
 * `tovu_session` (the admin cookie) — a request carrying only a `tovu_session` cookie (no token)
 * is still rejected by this route; the admin cookie has zero effect here.
 */

/** Complete a purpose-bound link/code challenge and set only the member session cookie. O(1) I/O. */
export function registerPublicMemberCompleteSignInRoute(app: Express, deps: MemberPublicRouteDeps): void {
  app.post("/api/members/v1/workspaces/:workspaceId/sign-in/complete", async (req, res) => {
    observeMemberSignInFailure({ deps: deps, request: req, response: res, method: "challenge" });
    try {
      if (!checkMemberPost({ req, res, deps })) return;
      const credential = completionCredential({ body: req.body, workspaceId: deps.workspaceId });
      if (!credential) { res.status(400).json({ error: "expected token or challengeId and six-digit code strings" }); return; }
      if (!await checkMemberRequestLimits({ req, res, deps, ipLimiter: deps.magicLinkCompleteAttemptLimiter })) return;
      const result = await completeSignIn({ deps: toPublicMembersWriteServiceDeps(deps, { request: req }),
        input: { ...credential, userAgent: req.get("user-agent"), ip: resolveClientIp(req) } });
      setMemberSessionCookie({ res, rawToken: result.rawSessionToken, expiresAtIso: result.session.expiresAt });
      captureMemberSignedIn({ deps: deps, request: req, result: result, method: "challenge", workspaceId: deps.workspaceId });
      res.json({ member: toPublicMemberResponse(result.member) });
    } catch (error) { sendMemberAuthError({ res, error }); }
  });
}

import type { Express } from "express";
import { prepareMemberChallenge } from "#src/features/members/index";
import { checkMemberPost, checkMemberRequestLimits, memberStringBody, toPublicMembersWriteServiceDeps, type MemberPublicRouteDeps } from "./deps.js";
import { reportMemberDeliveryFailure, respondToSignInError } from "./sign-in.js";

/** Link-only reset requests share the magic-link counters and detached delivery owner. O(1) setup I/O. */
export function registerPublicMemberForgotPasswordRoute(app: Express, deps: MemberPublicRouteDeps): void {
  app.post("/api/members/v1/workspaces/:workspaceId/forgot-password", async (req, res) => {
    try {
      if (!checkMemberPost({ req, res, deps })) return;
      const body = memberStringBody({ body: req.body, kind: "forgotPassword" });
      if (!body) { res.status(400).json({ error: "expected email string" }); return; }
      if (!await checkMemberRequestLimits({ req, res, deps, email: body.email,
        emailLimiter: deps.magicLinkPerEmailLimiter, ipLimiter: deps.magicLinkPerIpLimiter })) return;
      const prepared = await prepareMemberChallenge({ deps: toPublicMembersWriteServiceDeps(deps), purpose: "password_reset",
        input: { workspaceId: deps.workspaceId, email: body.email } });
      res.json({ accepted: true });
      // Per-address lookup and mail latency must never delay public acceptance.
      setImmediate(() => { void prepared.deliver().catch(reportMemberDeliveryFailure); });
    } catch (error) { respondToSignInError({ error, res }); }
  });
}

import type { Express } from "express";
import { nowIso } from "@jini-ai/core/primitives";
import { createMemberAccessResolver } from "#src/features/members/index";
import { toPublicMemberResponse } from "../../http/members.js";
import { checkMemberWorkspace, type MemberPublicRouteDeps } from "./deps.js";
import { sendMemberAuthError, MEMBER_SESSION_COOKIE } from "./complete-sign-in.js";
import { MemberLoginError } from "#src/features/member-login/index";
import { uniqueMemberCookie, sendMemberOidcError, type MemberOidcRouteDeps } from "./oidc-deps.js";

/** Never cache identity; resolver validates sessions, then the member row enforces current status. */
export function registerPublicMemberMeRoute(app: Express, deps: MemberPublicRouteDeps, options: { login?: MemberOidcRouteDeps } = {}): void {
  const resolver = createMemberAccessResolver({ deps });
  app.get("/api/members/v1/workspaces/:workspaceId/me", async (req, res) => {
    res.setHeader("Cache-Control", "no-store");
    try {
      if (!checkMemberWorkspace({ req, res, deps })) return;
      const context = await resolver.resolveContext({ workspaceId: deps.workspaceId, nowIso: nowIso({ clock: deps.clock }),
        sessionToken: uniqueMemberCookie({ req, name: MEMBER_SESSION_COOKIE }) });
      const member = context.memberId ? await deps.memberRepo.findById({ workspaceId: deps.workspaceId, id: context.memberId }) : null;
      const visible = member && (member.status === "active" || member.status === "pending") ? member : null;
      const identities = visible ? await publicMemberIdentities({ memberId: visible.id, deps: options.login }) : [];
      res.json({ member: visible ? toPublicMemberResponse(visible) : null, identities });
    } catch (error) {
      if (error instanceof MemberLoginError) { sendMemberOidcError({ res, error }); return; }
      sendMemberAuthError({ res, error });
    }
  });
}

/** Expose labels/IDs only, including a disconnected provider so members can still unlink it.
 * Subjects, issuer, timestamps and unlinked markers stay internal. O(p) member providers.
 */
async function publicMemberIdentities({ memberId, deps }: { memberId: string; deps?: MemberOidcRouteDeps }, _options = {}) {
  if (!deps) return [];
  const identities = await deps.links.identities.listByMember({ workspaceId: deps.members.workspaceId, memberId });
  const linked = identities.filter(identity => !identity.unlinkedAt);
  if (!linked.length) return [];
  // Provider availability must not prevent account access/unlink after a plugin is disabled.
  const providers = await deps.listProviders({ workspaceId: deps.members.workspaceId }).catch(() => []);
  const labels = new Map(providers.map(provider => [provider.id, provider.label]));
  return linked.map(identity => ({ providerId: identity.providerId, label: labels.get(identity.providerId) ?? identity.providerId }));
}

import { captureMemberSignedIn, observeMemberSignInFailure } from "./analytics.js";
import { captureVisitorEvent } from "../../visitor-analytics.js";
import type { Express, Request, Response } from "express";
import { completeOidcLogin, memberLoginCallbackUrl, requestLoginEmailProof, resolveFederatedIdentity,
  sealLoginEmailContinuation, MemberLoginError, type CompletedOidcLogin, type LoginContext } from "#src/features/member-login/index";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { checkMemberRequestLimits, checkMemberWorkspace, toPublicMembersWriteServiceDeps } from "./deps.js";
import { setMemberSessionCookie } from "./complete-sign-in.js";
import { MEMBER_OIDC_PATH, MEMBER_OIDC_BINDING_COOKIE, memberOidcContext, memberOidcCookie,
  memberOidcHeaders, memberOidcProviderId, MemberOidcCancelled, redirectMemberOidcError, uniqueMemberCookie,
  type MemberOidcRouteDeps } from "./oidc-deps.js";

/** Query parser rejects repeated/object values before OAuth can receive ambiguous credentials.
 * Provider denial takes the same fixed error path, after clearing the browser cookie; Cancel
 * (`access_denied`) only picks a kinder message. O(k) keys.
 */
export function callbackParams({ req }: { req: Request }, _options = {}) {
  const { code, state, error } = req.query;
  if (error === "access_denied") throw new MemberOidcCancelled();
  if (error !== undefined || typeof code !== "string" || typeof state !== "string") throw new MemberLoginError({ code: "LOGIN_INVALID" });
  if (!code || code.length > 4096 || !state || state.length > 16384) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  return { code, state };
}

/** The shared member delivery limits for this top-level browser page. The API routes answer a
 * refusal with 429 JSON; here the one-time code is already spent, so a refusal becomes the fixed
 * sign-in error redirect instead (the route's catch), and the limiter's own response is discarded.
 * @throws {MemberLoginError} LOGIN_UNAVAILABLE when a limit refuses. @complexity O(1) limiter checks.
 */
async function assertEmailContinuationLimits(required: {
  req: Request; deps: MemberOidcRouteDeps; email: string;
}, _options = {}): Promise<void> {
  const { req, deps, email } = required;
  const discarded = { setHeader: () => discarded, status: () => discarded, json: () => discarded };
  const allowed = await checkMemberRequestLimits({ req, res: discarded as unknown as Response, deps: deps.members, email,
    emailLimiter: deps.members.magicLinkPerEmailLimiter, ipLimiter: deps.members.magicLinkPerIpLimiter });
  if (!allowed) throw new MemberLoginError({ code: "LOGIN_UNAVAILABLE" });
}

/** Keep validated identity sealed and browser-bound while the existing challenge owner proves
 * a non-authoritative mailbox. Fragment data is removed by U1 before rendering; no OAuth tokens.
 * @complexity O(1) seal/challenge issuance, with shared IP/email delivery limits before mail.
 */
async function continueByEmail(required: {
  req: Request; res: Response; deps: MemberOidcRouteDeps; input: LoginContext;
  login: CompletedOidcLogin; browserBinding: string; callbackUrl: string; email: string;
}, _options = {}): Promise<void> {
  const { req, res, deps, input, login, browserBinding, callbackUrl, email } = required;
  await assertEmailContinuationLimits({ req, deps, email });
  const continuation = await sealLoginEmailContinuation({ deps: deps.protocol, input: { ...input, browserBinding }, login });
  const proof = await requestLoginEmailProof({ deps: deps.links, input: { workspaceId: input.workspaceId, email } });
  memberOidcCookie({ res, callbackUrl, kind: "proof", binding: browserBinding });
  const fragment = new URLSearchParams({ oidc: input.providerId, challengeId: proof.challengeId, continuation });
  res.redirect(303, `/signin#${fragment}`);
}

/** Top-level callback clears proof on success, denial and malformed input, then calls S2 only.
 * Returns a fixed /account redirect, the sealed email continuation or /signin#oidcError=<CODE>;
 * logs no request material.
 * @complexity O(1) protocol/transaction calls; S2 owns bounded exchange and indexed persistence.
 */
export function registerMemberOidcCallbackRoute({ app, deps }: { app: Express; deps: MemberOidcRouteDeps }, _options = {}): void {
  app.get(`${MEMBER_OIDC_PATH}/callback`, async (req, res) => {
    memberOidcHeaders({ res });
    observeMemberSignInFailure({ deps: deps.members, request: req, response: res, method: "oidc" });
    try {
      if (!checkMemberWorkspace({ req, res, deps: deps.members })) return;
      // Clear before reading the untrusted cookie/query, including duplicate-cookie refusal.
      const callbackUrl = await callbackAddress({ req, deps });
      memberOidcCookie({ res, callbackUrl, kind: "callback" });
      if (!await checkMemberRequestLimits({ req, res, deps: deps.members, ipLimiter: deps.members.magicLinkCompleteAttemptLimiter })) return;
      const input = await memberOidcContext({ req, deps: deps.members });
      const browserBinding = uniqueMemberCookie({ req, name: MEMBER_OIDC_BINDING_COOKIE }) ?? "";
      const login = await completeOidcLogin({ deps: deps.protocol, input: { ...input, browserBinding, params: callbackParams({ req }) } });
      const linked = await resolveFederatedIdentity({ deps: { ...deps.links, onMemberCreated: toPublicMembersWriteServiceDeps(deps.members, { request: req }).onMemberCreated }, input: { workspaceId: input.workspaceId,
        identity: login.identity, startedAt: login.startedAt, connectMemberId: login.connectMemberId,
        userAgent: req.get("user-agent"), ip: resolveClientIp(req) } });
      if (linked.kind === "email_verification_required") {
        await continueByEmail({ req, res, deps, input, login, browserBinding, callbackUrl, email: linked.email });
        return;
      }
      memberOidcCookie({ res, callbackUrl, kind: "proof" });
      setMemberSessionCookie({ res, rawToken: linked.result.rawSessionToken, expiresAtIso: linked.result.session.expiresAt });
      captureMemberSignedIn({ deps: deps.members, request: req, result: linked.result, method: "oidc", workspaceId: deps.members.workspaceId });
      res.redirect(303, "/account");
    } catch (error) { void captureVisitorEvent({ deps: deps.members, request: req, name: "member_sign_in_failed", properties: { method: "oidc", realm: "member", reasonClass: "authentication_failed" } }); redirectMemberOidcError({ res, error }); }
  });
}

/** Compute cookie scope independently of member authentication so even a stale connect clears it.
 * @complexity O(1), one canonical-origin lookup; workspace already checked by the caller.
 */
export async function callbackAddress({ req, deps }: { req: Request; deps: MemberOidcRouteDeps }, _options = {}): Promise<string> {
  return memberLoginCallbackUrl({ origin: deps.protocol.origin, workspaceId: deps.members.workspaceId, providerId: memberOidcProviderId({ req }) });
}

import { observeMemberSignInFailure } from "./analytics.js";
import { captureVisitorEvent } from "../../visitor-analytics.js";
import type { Express } from "express";
import { beginOidcLogin, memberLoginCallbackUrl, MemberLoginError } from "#src/features/member-login/index";
import { checkMemberRequestLimits, checkMemberWorkspace } from "./deps.js";
import { MEMBER_OIDC_PATH, memberOidcContext, memberOidcCookie, memberOidcHeaders,
  redirectMemberOidcError, sendMemberOidcError, type MemberOidcRouteDeps } from "./oidc-deps.js";

/** Safe provider metadata only; configuration/pins and credentials never leave the server.
 * @complexity O(p*c), p admitted providers, c credential metadata rows; bounded bundled catalog.
 */
export function registerMemberLoginProvidersRoute({ app, deps }: { app: Express; deps: MemberOidcRouteDeps }, _options = {}): void {
  app.get("/api/members/v1/workspaces/:workspaceId/login-providers", async (req, res) => {
    memberOidcHeaders({ res });
    try {
      if (!checkMemberWorkspace({ req, res, deps: deps.members })) return;
      const providers = await deps.listProviders({ workspaceId: deps.members.workspaceId });
      res.json({ providers: providers.map(provider => ({ id: provider.id, label: provider.label })) });
    } catch (error) { sendMemberOidcError({ res, error }); }
  });
}

/** Plain-link entry point. Independent browser proof stays out of the authorization URL. A
 * refusal (cross-site, provider unavailable) sends the person back to /signin with its code.
 * @complexity O(1) limited protocol start; protocol owner bounds all external work.
 */
export function registerMemberOidcStartRoute({ app, deps }: { app: Express; deps: MemberOidcRouteDeps }, _options = {}): void {
  app.get(`${MEMBER_OIDC_PATH}/start`, async (req, res) => {
    memberOidcHeaders({ res });
    observeMemberSignInFailure({ deps: deps.members, request: req, response: res, method: "oidc" });
    try {
      if (!checkMemberWorkspace({ req, res, deps: deps.members })) return;
      if (!await checkMemberRequestLimits({ req, res, deps: deps.members, ipLimiter: deps.members.passwordSignInPerIpLimiter })) return;
      // A GET start reads the Lax member cookie as connect intent, and Google redirects silently
      // once consent exists: a cross-site page could otherwise relink an unlinked account or
      // create a member. Same-origin links and typed URLs still pass; old browsers omit the header.
      if (req.get("sec-fetch-site") === "cross-site") throw new MemberLoginError({ code: "LOGIN_INVALID" });
      const input = await memberOidcContext({ req, deps: deps.members });
      const callbackUrl = await memberLoginCallbackUrl({ origin: deps.protocol.origin, ...input });
      const result = await beginOidcLogin({ deps: deps.protocol, input });
      memberOidcCookie({ res, callbackUrl, kind: "callback", binding: result.browserBinding });
      void captureVisitorEvent({ deps: deps.members, request: req, name: "member_sign_in_requested", properties: { method: "oidc", realm: "member" } });
      res.redirect(303, result.authorizationUrl);
    } catch (error) { void captureVisitorEvent({ deps: deps.members, request: req, name: "member_sign_in_failed", properties: { method: "oidc", realm: "member", reasonClass: "authentication_failed" } }); redirectMemberOidcError({ res, error }); }
  });
}

import { captureMemberSignedIn, observeMemberSignInFailure } from "./analytics.js";
import type { Express } from "express";
import { MemberLoginError, openLoginEmailContinuation, resolveFederatedIdentity } from "#src/features/member-login/index";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { toPublicMemberResponse } from "../../http/members.js";
import { checkMemberPost, checkMemberRequestLimits, toPublicMembersWriteServiceDeps } from "./deps.js";
import { setMemberSessionCookie } from "./complete-sign-in.js";
import { callbackAddress } from "./oidc-callback.js";
import { MEMBER_OIDC_PATH, MEMBER_OIDC_PROOF_COOKIE, memberOidcContext, memberOidcCookie,
  memberOidcHeaders, sendMemberOidcError, uniqueMemberCookie, type MemberOidcRouteDeps } from "./oidc-deps.js";

/** Strict JSON DTO; callers cannot inject claims, intent or proof booleans. O(k) body keys. */
export function proofBody({ body }: { body: unknown }, _options = {}): { continuation: string; challengeId: string; code: string } {
  if (!body || typeof body !== "object" || Array.isArray(body)) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  const record = body as Record<string, unknown>;
  if (Object.keys(record).length !== 3 || !Object.keys(record).every(key => ["continuation", "challengeId", "code"].includes(key))) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  const continuation = proofString({ value: record.continuation, maxLength: 8192 });
  const challengeId = proofString({ value: record.challengeId, maxLength: 255 });
  if (typeof record.code !== "string" || !/^\d{6}$/.test(record.code)) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  return { continuation, challengeId, code: record.code };
}

/** Bound opaque handles before cryptography or challenge repository work. O(1). */
export function proofString({ value, maxLength }: { value: unknown; maxLength: number }, _options = {}): string {
  if (typeof value !== "string" || !value || value.length > maxLength) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  return value;
}

/** Browser-bound emailed-code continuation. A wrong code retains its challenge attempt budget
 * in S2, and keeps this cookie for a bounded retry; success clears it. No identity comes from JSON.
 * @complexity O(1) sealed open and challenge/link calls; body capped by the existing member guard.
 */
export function registerMemberOidcVerifyEmailRoute({ app, deps }: { app: Express; deps: MemberOidcRouteDeps }, _options = {}): void {
  app.post(`${MEMBER_OIDC_PATH}/verify-email`, async (req, res) => {
    memberOidcHeaders({ res });
    observeMemberSignInFailure({ deps: deps.members, request: req, response: res, method: "oidc" });
    try {
      if (!checkMemberPost({ req, res, deps: deps.members })) return;
      if (!await checkMemberRequestLimits({ req, res, deps: deps.members, ipLimiter: deps.members.magicLinkCompleteAttemptLimiter })) return;
      const body = proofBody({ body: req.body });
      const input = await memberOidcContext({ req, deps: deps.members });
      const browserBinding = uniqueMemberCookie({ req, name: MEMBER_OIDC_PROOF_COOKIE }) ?? "";
      const login = await openLoginEmailContinuation({ deps: deps.protocol, input: { ...input, browserBinding, continuation: body.continuation } });
      const linked = await resolveFederatedIdentity({ deps: { ...deps.links, onMemberCreated: toPublicMembersWriteServiceDeps(deps.members, { request: req }).onMemberCreated }, input: { workspaceId: input.workspaceId,
        identity: login.identity, startedAt: login.startedAt, connectMemberId: login.connectMemberId,
        emailProof: { challengeId: body.challengeId, code: body.code }, userAgent: req.get("user-agent"), ip: resolveClientIp(req) } });
      if (linked.kind !== "signed_in") throw new MemberLoginError({ code: "LOGIN_INVALID" });
      memberOidcCookie({ res, callbackUrl: await callbackAddress({ req, deps }), kind: "proof" });
      setMemberSessionCookie({ res, rawToken: linked.result.rawSessionToken, expiresAtIso: linked.result.session.expiresAt });
      captureMemberSignedIn({ deps: deps.members, request: req, result: linked.result, method: "oidc", workspaceId: deps.members.workspaceId });
      res.json({ member: toPublicMemberResponse(linked.result.member), returnPath: "/account" });
    } catch (error) { sendMemberOidcError({ res, error }); }
  });
}

