import type { Express } from "express";
import { nowIso } from "@jini-ai/core/primitives";
import { MemberAuthError, resolveMemberSession, setMemberPassword } from "#src/features/members/index";
import { readRequestCookie } from "#src/server/http/request-cookie";
import { checkMemberPost, checkMemberRequestLimits, memberStringBody, toPublicMembersWriteServiceDeps, type MemberPublicRouteDeps } from "./deps.js";
import { MEMBER_SESSION_COOKIE, sendMemberAuthError } from "./complete-sign-in.js";

/** Member self-service; share /me's session check and charge both strict counters before Argon2.
 * @complexity O(n + s) in password size n and affected sessions s; service owns the write lifecycle.
 */
export function registerPublicMemberSetPasswordRoute(app: Express, deps: MemberPublicRouteDeps): void {
  app.post("/api/members/v1/workspaces/:workspaceId/password/set", async (req, res) => {
    try {
      if (!checkMemberPost({ req, res, deps })) return;
      const body = memberStringBody({ body: req.body, kind: "setPassword" });
      if (!body) { res.status(400).json({ error: "expected password and optional currentPassword strings" }); return; }
      const sessionToken = readRequestCookie({ request: req, name: MEMBER_SESSION_COOKIE });
      const session = await resolveMemberSession({ sessions: deps.memberSessionRepo, workspaceId: deps.workspaceId,
        sessionToken, nowIso: nowIso({ clock: deps.clock }) });
      if (!session) throw new MemberAuthError("INVALID_CREDENTIALS");
      if (!await checkMemberRequestLimits({ req, res, deps, ipLimiter: deps.passwordSignInPerIpLimiter,
        identity: { key: session.memberId, limiter: deps.passwordSetPerMemberLimiter } })) return;
      res.json(await setMemberPassword({ deps: toPublicMembersWriteServiceDeps(deps), input: {
        workspaceId: deps.workspaceId, sessionToken, password: body.password, currentPassword: body.currentPassword,
      } }));
    } catch (error) { sendMemberAuthError({ res, error }, { reset: true }); }
  });
}

import { observeMemberSignInFailure } from "./analytics.js";
import { captureVisitorEvent } from "../../visitor-analytics.js";
import type { Express, Response } from "express";
import { SenderIdentityNotConfiguredError } from "#src/platform/mail/index";
import { MemberAuthError, MemberSignInUnavailableError, MemberValidationError, prepareMemberChallenge } from "#src/features/members/index";
import { sendMemberAuthError } from "./complete-sign-in.js";
import { checkMemberPost, checkMemberRequestLimits, memberStringBody, toPublicMembersWriteServiceDeps, type MemberPublicRouteDeps } from "./deps.js";

/**
 * @file `POST /api/members/v1/workspaces/:workspaceId/sign-in` — the PUBLIC, visitor-initiated
 * sign-in-request route (ADR-PIPE-013 Decision §2-3, C-012).
 *
 * Deliberately unauthenticated (no `requireAdminSession`, no `authorize()` — this route family
 * must never import either, see ADR-PIPE-013 Enforcement) and rate-limited on BOTH axes before any
 * token is minted:
 *  - `MAGIC_LINK_PER_EMAIL` (keyed by the normalized target email) — bounds spam to one inbox
 *    regardless of source IP.
 *  - `MAGIC_LINK_PER_IP` (keyed by `resolveClientIp`) — bounds a single attacker's ability to
 *    enumerate many emails.
 * Both checks must pass (W-002/W-003) — this is the primary target of ADR-030 OQ-8's hard
 * pre-launch precondition; checking only one of the two would reopen the enumeration/abuse
 * surface. INV-06 (anti-enumeration) is preserved: the public response is
 * `{accepted:true, challengeId}` regardless of the address or mailer result; site-wide setup
 * failures are checked before member lookup; a `429` here is a volume signal (this email/IP was
 * queried too often), never an existence signal.
 */

/** Public acceptance is independent of address lookup and mail latency. Setup failures remain 503.
 * @complexity O(1) setup I/O; address-dependent work runs detached after the response.
 */
export function registerPublicMemberSignInRequestRoute(app: Express, deps: MemberPublicRouteDeps): void {
  app.post("/api/members/v1/workspaces/:workspaceId/sign-in", async (req, res) => {
    observeMemberSignInFailure({ deps: deps, request: req, response: res, method: "challenge" });
    try {
      if (!checkMemberPost({ req, res, deps })) return;
      const body = memberStringBody({ body: req.body, kind: "signIn" });
      if (!body) { res.status(400).json({ error: "expected email and optional redirectPath strings" }); return; }
      // Empty emails have no valid counter key; preserve the service's validation response.
      if (!body.email.trim()) { res.status(400).json({ error: `'${body.email}' is not a valid email address` }); return; }
      if (!await checkMemberRequestLimits({ req, res, deps, email: body.email,
        emailLimiter: deps.magicLinkPerEmailLimiter, ipLimiter: deps.magicLinkPerIpLimiter })) return;
      const prepared = await prepareMemberChallenge({ deps: toPublicMembersWriteServiceDeps(deps, { request: req }), purpose: "signin",
        input: { workspaceId: deps.workspaceId, email: body.email, redirectPath: body.redirectPath } });
      void captureVisitorEvent({ deps: deps, request: req, name: "member_sign_in_requested", properties: { method: "challenge", realm: "member" } });
      res.json({ accepted: true, challengeId: prepared.challengeId });
      // Do not await per-address I/O or reflect its outcome in this anti-enumeration response.
      setImmediate(() => { void prepared.deliver().catch(reportMemberDeliveryFailure); });
    } catch (error) { respondToSignInError({ error, res }); }
  });
}

/** Detached failures are observable without logging addresses, bearer tokens or provider details. */
export function reportMemberDeliveryFailure(_error: unknown): void {
  console.error("Member authentication delivery failed after acceptance");
}

/** Setup errors are site-wide; validation is independent of account existence.
 * Per-address delivery outcomes never enter this error path: they use generic acceptance.
 * @complexity O(1); writes one response, without logging credentials or provider detail.
 */
export function respondToSignInError({ error, res }: { error: unknown; res: Response }, _options = {}): void {
  if (error instanceof MemberAuthError) { sendMemberAuthError({ res, error }); return; }
  if (error instanceof MemberSignInUnavailableError || error instanceof SenderIdentityNotConfiguredError) {
    res.status(503).json({ error: error instanceof SenderIdentityNotConfiguredError
      ? "Member sign-in is unavailable: email is not set up for this site." : error.message, code: "MEMBER_SIGN_IN_UNAVAILABLE" });
    return;
  }
  if (error instanceof MemberValidationError) { res.status(400).json({ error: error.message }); return; }
  res.status(500).json({ error: "internal error" });
}

import type { Express } from "express";
import { nowIso } from "@jini-ai/core/primitives";
import { NodeSessionTokens } from "@jini-ai/user-management/server";
import { readRequestCookie } from "#src/server/http/request-cookie";
import { checkMemberPost, type MemberPublicRouteDeps } from "./deps.js";
import { sendMemberAuthError, clearMemberSessionCookie, MEMBER_SESSION_COOKIE } from "./complete-sign-in.js";

/** Revoke only the member session; an absent/already-revoked cookie still succeeds. O(1) I/O. */
export function registerPublicMemberSignOutRoute(app: Express, deps: MemberPublicRouteDeps): void {
  const tokens = new NodeSessionTokens({});
  app.post("/api/members/v1/workspaces/:workspaceId/sign-out", async (req, res) => {
    try {
      if (!checkMemberPost({ req, res, deps })) return;
      const rawToken = readRequestCookie({ request: req, name: MEMBER_SESSION_COOKIE });
      const session = rawToken ? await deps.memberSessionRepo.findByTokenHash({ workspaceId: deps.workspaceId,
        tokenHash: tokens.hashToken({ rawToken }) }) : null;
      if (session && !session.revokedAt) await deps.memberSessionRepo.revoke({ workspaceId: deps.workspaceId,
        id: session.id, revokedAt: nowIso({ clock: deps.clock }) });
      clearMemberSessionCookie({ res });
      res.status(204).end();
    } catch (error) { sendMemberAuthError({ res, error }); }
  });
}

import type { Express, Request } from "express";
import { nowIso } from "@jini-ai/core/primitives";
import { MemberLoginError } from "#src/features/member-login/index";
import { prepareMemberChallenge, type MemberRecord } from "#src/features/members/index";
import { issueMemberSession } from "#src/features/members/index";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { checkMemberPost, checkMemberRequestLimits } from "./deps.js";
import { setMemberSessionCookie } from "./complete-sign-in.js";
import { currentOidcMember, memberOidcHeaders, memberOidcProviderId, sendMemberOidcError, type MemberOidcRouteDeps } from "./oidc-deps.js";

/** Require a password or the existing mail owner's complete readiness check. Preparing never
 * persists/sends until deliver() is called; deliberately discard it here to avoid a second mail
 * availability policy that drifts from sign-in. O(1), bounded sender/status/origin reads.
 */
async function requireAlternativeSignIn({ deps, member }: { deps: MemberOidcRouteDeps; member: MemberRecord }, _options = {}): Promise<void> {
  const password = await deps.members.memberRepo.findPasswordHash({ workspaceId: deps.members.workspaceId, memberId: member.id });
  // The password owner refuses pending members even when an operator provisioned a hash.
  if (password && member.status === "active") return;
  if (!member.emailVerifiedAt) throw new MemberLoginError({ code: "LOGIN_BLOCKED" });
  try {
    await prepareMemberChallenge({ deps: deps.links, input: { workspaceId: deps.members.workspaceId, email: member.email }, purpose: "signin" });
  } catch { throw new MemberLoginError({ code: "LOGIN_BLOCKED" }); }
}

/** Unlink and revoke/reissue under the same locks and kernel as S2 link/Trash. Re-read session
 * after acquiring locks so concurrent unlink/disable cannot leave a replacement session usable.
 * @complexity O(s) revoked sessions; constant indexed identity/member reads, one transaction.
 */
export async function unlinkMemberIdentity({ req, deps }: { req: Request; deps: MemberOidcRouteDeps }, _options = {}) {
  const current = await currentOidcMember({ req, deps: deps.members });
  if (!current) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  const providerId = memberOidcProviderId({ req });
  return deps.links.transaction(async () => {
    await deps.links.lockKey(`members:external-identities:${deps.members.workspaceId}`);
    await deps.links.lockKey(`trash:member:${deps.members.workspaceId}:${current.member.id}`);
    return unlinkLocked({ req, deps, providerId });
  });
}

/** Locked lifecycle step; a marker prevents anonymous auto-link even for an outstanding redirect.
 * @complexity O(s) sessions, one identity lookup/update and one member save.
 */
async function unlinkLocked({ req, deps, providerId }: { req: Request; deps: MemberOidcRouteDeps; providerId: string }, _options = {}) {
  const current = await currentOidcMember({ req, deps: deps.members });
  if (!current) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  const now = nowIso({ clock: deps.members.clock });
  const age = Date.parse(now) - Date.parse(current.session.createdAt);
  if (!(age >= 0 && age <= 900000)) throw new MemberLoginError({ code: "LOGIN_BLOCKED" });
  const input = { workspaceId: deps.members.workspaceId, memberId: current.member.id, providerId };
  const identity = await deps.links.identities.findByMemberAndProvider(input);
  if (!identity || identity.unlinkedAt) throw new MemberLoginError({ code: "LOGIN_INVALID" });
  await requireAlternativeSignIn({ deps, member: current.member });
  await deps.links.identities.unlink({ ...input, unlinkedAt: now });
  await deps.members.memberSessionRepo.revokeAllForMember({ workspaceId: input.workspaceId, memberId: input.memberId, revokedAt: now });
  const member = { ...current.member, credentialsRevokedAt: now, updatedAt: now, version: current.member.version + 1 };
  await deps.members.memberRepo.save(member);
  return issueMemberSession({ deps: deps.links, member, nowIso: now }, { userAgent: req.get("user-agent"), ip: resolveClientIp(req) });
}

/** Fresh member self-service only, same-origin JSON and the existing strict IP/member counters.
 * @complexity O(s) affected sessions; transactional helper owns all persistence.
 */
export function registerMemberUnlinkIdentityRoute({ app, deps }: { app: Express; deps: MemberOidcRouteDeps }, _options = {}): void {
  app.post("/api/members/v1/workspaces/:workspaceId/identities/:providerId/unlink", async (req, res) => {
    memberOidcHeaders({ res });
    try {
      if (!checkMemberPost({ req, res, deps: deps.members })) return;
      if (!req.body || typeof req.body !== "object" || Array.isArray(req.body) || Object.keys(req.body).length) {
        throw new MemberLoginError({ code: "LOGIN_INVALID" });
      }
      const current = await currentOidcMember({ req, deps: deps.members });
      if (!current) throw new MemberLoginError({ code: "LOGIN_INVALID" });
      if (!await checkMemberRequestLimits({ req, res, deps: deps.members, ipLimiter: deps.members.passwordSignInPerIpLimiter,
        identity: { key: current.member.id, limiter: deps.members.passwordSetPerMemberLimiter } })) return;
      const result = await unlinkMemberIdentity({ req, deps });
      setMemberSessionCookie({ res, rawToken: result.rawSessionToken, expiresAtIso: result.session.expiresAt });
      res.json({ ok: true });
    } catch (error) { sendMemberOidcError({ res, error }); }
  });
}

/** Thin HTTP binding for the existing plugin host. A live Router per request generation avoids
 * Express stack surgery: disabled/reloaded handlers have no route entry to dispatch to. */
import express, { type Express, type RequestHandler, type ErrorRequestHandler, type Response } from 'express';
import type { PluginAuthContext, PluginContributionsSnapshot, PluginRouteResult } from '@jini-ai/plugins/host';
import type { RouteDeps } from '../../../routes/types.js';
import { authorizeOrRespond } from '../../admin-http/authorize-guard.js';
import { requireAdminSession } from '../../admin-http/dev-auth.js';
import { DefaultMemberAccessResolver } from '../../../../features/members/access-resolver.js';
import { MEMBER_SESSION_COOKIE } from '../http/members.js';
import { readRequestCookie } from '../../../http/request-cookie.js';
import { PUBLIC_JSON_BODY_LIMIT, respondToOversizedBody } from '../../shared/json-body-parsers.js';

export interface PluginRouteAuthPorts { readonly member: RequestHandler; readonly admin: RequestHandler }
/** Uses the same operator gate and distinct member cookie resolver as core routes; a member
 * credential never counts as an operator credential. No plugin receives raw tokens or repos. */
export function createPluginRouteAuthPorts({ deps }: { deps: RouteDeps }, _optional: Record<string, never> = {}): PluginRouteAuthPorts {
  const resolver = new DefaultMemberAccessResolver({ sessions: deps.memberSessionRepo, subscriptions: deps.memberSubscriptionRepo, tiers: deps.memberTierRepo });
  const operatorSession = requireAdminSession(deps);
  return {
    // The session gate admits operators, including users with no grants. Arbitrary in-process
    // plugin execution needs the same operator permission as plugin tools, not just a cookie.
    admin: (req, res, next) => operatorSession(req, res, error => {
      if (error) { next(error); return; }
      void authorizeOrRespond(res, deps.authorize, { principalId: res.locals.principal.id,
        permission: 'admin.plugins.enable', workspaceId: deps.workspaceId,
        entityType: 'plugin', entityId: res.locals.pluginOwnerId,
      }).then(allowed => { if (allowed) next(); }).catch(next);
    }),
    member: async (req, res, next) => {
      try {
        const context = await resolver.resolveContext({ workspaceId: deps.workspaceId, sessionToken: readRequestCookie({ request: req, name: MEMBER_SESSION_COOKIE }), nowIso: deps.clock.nowIso() });
        if (!context.isAuthenticated || !context.memberId) { res.status(401).json({ code: 'UNAUTHENTICATED' }); return; }
        // Session resolution alone must not resurrect a suspended/trashed member.
        const member = await deps.memberRepo.findById({ workspaceId: deps.workspaceId, id: context.memberId });
        if (!member || member.status !== 'active') { res.status(401).json({ code: 'UNAUTHENTICATED' }); return; }
        res.locals.pluginMemberId = context.memberId;
        next();
      } catch (error) { next(error); }
    },
  };
}
type PluginRoute = PluginContributionsSnapshot['routes'][number];
type PluginRouteDeps = Pick<RouteDeps, 'workspaceId' | 'pluginContributions' | 'pluginActivationRepo'>;
type PluginRouteErrorReporter = (required: { pluginId: string; error: unknown }, optional?: Record<string, never>) => void;

const respondNotFound = (res: Response): void => { res.status(404).json({ code: 'NOT_FOUND' }); };
const warnPluginRouteFailure: PluginRouteErrorReporter = failure => console.warn(`[plugins] Plugin '${failure.pluginId}' route failed`, failure.error);

/** Whether the durable activation row says the plugin is enabled right now. */
async function isPluginActivated({ deps, pluginId }: { deps: PluginRouteDeps; pluginId: string }): Promise<boolean> {
  const row = await deps.pluginActivationRepo.getActivation({ workspaceId: deps.workspaceId, pluginId });
  return Boolean(row?.enabled);
}

/** Whether this exact snapshot is still the live generation (a reload or disable retires it). */
function isLiveGeneration({ deps, snapshot }: { deps: PluginRouteDeps; snapshot: PluginContributionsSnapshot }): boolean {
  return Boolean(deps.pluginContributions?.list({}).includes(snapshot));
}

/** The principal the access level's auth port resolved; public routes carry none. */
function principalFor({ access, locals }: { access: PluginRoute['access']; locals: Response['locals'] }): Pick<PluginAuthContext, 'principalId'> {
  if (access === 'admin') return { principalId: locals.principal?.id };
  if (access === 'member') return { principalId: locals.pluginMemberId };
  return {};
}

function sendPluginRouteResult({ res, result }: { res: Response; result: PluginRouteResult | void }): void {
  res.set('Cache-Control', 'no-store');
  if (result === undefined) { res.status(204).end(); return; }
  res.status(result.status ?? 200).json(result.body ?? null);
}

/** Gate before auth and body parsing: a disabled plugin's route answers 404 without reading anything. */
const requireActivatedPlugin = (deps: PluginRouteDeps, snapshot: PluginContributionsSnapshot): RequestHandler => async (_req, res, next) => {
  try {
    if (!(await isPluginActivated({ deps, pluginId: snapshot.pluginId }))) { respondNotFound(res); return; }
    res.locals.pluginOwnerId = snapshot.pluginId;
    next();
  } catch (error) { next(error); }
};

const invokePluginRoute = (
  { deps, snapshot, route }: { deps: PluginRouteDeps; snapshot: PluginContributionsSnapshot; route: PluginRoute },
  { onError }: { onError: PluginRouteErrorReporter },
): RequestHandler => async (req, res) => {
  try {
    if (!(await isPluginActivated({ deps, pluginId: snapshot.pluginId })) || !isLiveGeneration({ deps, snapshot })) { respondNotFound(res); return; }
    const context: PluginAuthContext = { access: route.access, workspaceId: deps.workspaceId, ...principalFor({ access: route.access, locals: res.locals }) };
    const result = await route.handler({ pluginId: snapshot.pluginId, sdk: snapshot.sdk, auth: context, body: req.body, params: req.params as Record<string, string>, query: req.query }, {});
    // A disable/reload while the handler awaited must not emit a retired generation's result.
    if (!isLiveGeneration({ deps, snapshot }) || !(await isPluginActivated({ deps, pluginId: snapshot.pluginId }))) { respondNotFound(res); return; }
    sendPluginRouteResult({ res, result });
  } catch (error) {
    onError({ pluginId: snapshot.pluginId, error }, {});
    res.status(500).json({ code: 'PLUGIN_ROUTE_FAILED' });
  }
};

const passThrough: RequestHandler = (_req, _res, next) => next();

const pluginRouteErrors: ErrorRequestHandler = (error, _req, res, next) => {
  if (res.headersSent) { next(error); return; }
  const invalidBody = error?.type === 'entity.parse.failed';
  res.status(invalidBody ? 400 : 500).json({ code: invalidBody ? 'INVALID_BODY' : 'PLUGIN_ROUTE_FAILED' });
};

/** All bodies, including authenticated ones, use the small public cap. The admin middleware
 * owns credential resolution; its parser also selects this cap for the /api/p mount.
 * Auth and a durable activation check precede reading any body. Handler errors are redacted. */
export function registerPluginContributionRoutes(
  { app, deps, auth }: { app: Express; deps: PluginRouteDeps; auth: PluginRouteAuthPorts },
  optional: { onError?: PluginRouteErrorReporter } = {},
): void {
  const parsers = [
    express.json({ limit: PUBLIC_JSON_BODY_LIMIT }),
    express.urlencoded({ limit: PUBLIC_JSON_BODY_LIMIT, extended: false, parameterLimit: 256 }),
    express.text({ limit: PUBLIC_JSON_BODY_LIMIT, type: 'text/*' }),
    express.raw({ limit: PUBLIC_JSON_BODY_LIMIT, type: 'application/octet-stream' }),
  ];
  const onError = optional.onError ?? warnPluginRouteFailure;
  const buildRouter = () => {
    const router = express.Router();
    for (const snapshot of deps.pluginContributions?.list({}) ?? []) {
      for (const route of snapshot.routes) {
        const guard = route.access === 'public' ? passThrough : auth[route.access];
        router.route(`/${snapshot.pluginId}${route.path}`)[route.method.toLowerCase() as 'get'](requireActivatedPlugin(deps, snapshot), guard, ...parsers, invokePluginRoute({ deps, snapshot, route }, { onError }));
      }
    }
    router.use((_req, response) => respondNotFound(response));
    return router;
  };
  app.use('/api/p', (req, res, next) => buildRouter()(req, res, next));
  app.use('/api/p', respondToOversizedBody);
  app.use('/api/p', pluginRouteErrors);
}

import type { Express, Request, Response } from "express";

import { createRateLimiter, resolveClientIp, type RateLimitProfile } from "#src/contracts/core/rate-limit/rate-limit";
import {
  issuePublishChallenge,
  verifyChallengeResponse,
  type PublishChallengeResponse,
  type PublishChallengeStorePort,
} from "#src/features/publish-trust/challenge";
import { isGrantActive } from "#src/features/publish-trust/grant";
import { findGrantForSource, type PublishTrustResolution } from "#src/features/publish-trust/provisioning";
import { mintPublishSession } from "#src/features/publish-trust/session";
import type { KeyringPort } from "#src/features/webhooks/index";

/**
 * @file Zero-setup publishing auth — the destination's three unauthenticated handshake routes.
 * Design note: `ADS-memory/reports/2026-09-19-publish-zero-setup-auth-design.md`.
 *
 * These sit OUTSIDE `/api/admin`, and therefore outside `requireAdminSession`, because a source
 * that has not yet proved anything has no credential to present. That is the whole point: the user
 * never mints, copies or pastes one.
 *
 * ## What `GET .../identity` discloses, and why that is acceptable
 *
 * Three fields, to anyone who asks:
 *
 * - `installationId` — derived from this install's site key through HKDF. It is not a secret and
 *   was never treated as one: it is published inside the grant, which lives in committed deploy
 *   config by design. It is one-way — it identifies this install without revealing the key it came
 *   from — and possessing it grants nothing, because every credential is checked by signature.
 * - `workspaceId` — already present in the path of every admin URL this site serves.
 * - `origin` — the caller just connected to it.
 *
 * So the route reveals nothing a caller did not already have or could not already see. What it
 * deliberately does NOT reveal is anything about the grant: not whether one is configured, not the
 * source installation it names, and not its public keys. Without that, the route cannot be used to
 * enumerate who is allowed to publish here, or to tell a site that has been paired from one that
 * has not. It exists for exactly one reason — so the source learns this destination's identity
 * without a human reading a workspace id off a screen and typing it somewhere.
 *
 * A destination restored from a backup derives a DIFFERENT installation id (its site key changed),
 * and the source is expected to notice that change loudly rather than publish into a stranger.
 *
 * ## Flood resistance
 *
 * `challenge` mints state for an unauthenticated caller, so it is rate limited per client IP and
 * the store sweeps expired records on every write. `session` is limited on the same key: it runs an
 * Ed25519 verification, which is cheap but not free, and an unbounded caller should not be able to
 * choose how much of it this process does.
 */

/** Per-IP ceiling for the two state-changing handshake routes. Generous next to a real publish
 *  (one challenge plus one session per publish), tight next to a flood. */
const PUBLISH_TRUST_HANDSHAKE_PER_IP: RateLimitProfile = {
  windowSeconds: 60,
  max: 30,
  burst: 10,
};

/** The flat refusal every handshake rejection sends. Identical wording in every case on purpose:
 *  "unknown nonce" and "expired nonce" must not be distinguishable, and neither must "no grant
 *  configured" and "a grant that is not yours". The real reason goes to the server's own log. */
const HANDSHAKE_REFUSAL = { error: "the publishing handshake was refused", code: "UNAUTHENTICATED" } as const;

/** What every handshake route answers when this install has no usable site key, so it has no
 *  installation id to state or sign against. Says nothing about any grant, like `/identity`. */
const NO_SITE_KEY = {
  error: "This site has no usable Site key yet, so it cannot accept publishes. Set one up on this site first.",
  code: "SECRET_STORE_UNCONFIGURED",
} as const;

/** Any other failure. Fixed text: the real error goes to the server log only. */
const HANDSHAKE_FAILED = { error: "the publishing handshake failed", code: "INTERNAL_ERROR" } as const;

/** Everything the handshake needs. `targetInstallationId` is this install's own derived id,
 *  resolved once at composition rather than per request. */
export interface PublishTrustHandshakeDeps {
  readonly keyring: KeyringPort;
  readonly workspaceId: string;
  readonly clock: { nowIso(): string };
  readonly idGen: { newId(): string };
  readonly challengeStore: PublishChallengeStorePort;
  readonly targetInstallationId: Promise<string>;
  /** The grants this install currently accepts. Any state but `configured` carries none. */
  readonly grants: () => Promise<PublishTrustResolution>;
}

/** This site's own origin as the caller reached it. Built from the request rather than configured,
 *  so a site behind one hostname in dev and another in production needs no second setting.
 *  @complexity O(1). */
function originOf(req: Request): string {
  const host = req.get("host") ?? "";
  return host === "" ? "" : `${req.protocol}://${host}`;
}

/**
 * Narrows an untrusted request body to the challenge-response shape.
 *
 * Shape only — nothing here is a trust decision. `verifyChallengeResponse` re-checks every field
 * against the grant and the signature, and is fail-closed on all of them; this exists so a body
 * with a wrong-typed field produces a refusal rather than reaching the verifier as `undefined`.
 *
 * @complexity O(1).
 */
function asChallengeResponse(body: unknown): PublishChallengeResponse | null {
  if (typeof body !== "object" || body === null) return null;
  const candidate = body as Record<string, unknown>;
  if (typeof candidate.nonce !== "string") return null;
  if (typeof candidate.sourceInstallationId !== "string") return null;
  if (typeof candidate.generation !== "number" || !Number.isInteger(candidate.generation)) return null;
  if (!Array.isArray(candidate.capabilities) || candidate.capabilities.some((c) => typeof c !== "string")) return null;
  if (typeof candidate.signatureB64u !== "string") return null;
  return {
    nonce: candidate.nonce,
    sourceInstallationId: candidate.sourceInstallationId,
    generation: candidate.generation,
    capabilities: candidate.capabilities as readonly string[],
    signatureB64u: candidate.signatureB64u,
  };
}

/**
 * Registers `GET /identity`, `POST /challenge` and `POST /session` under `/api/publish-trust/v1`.
 *
 * @complexity O(1) per request — see each handler.
 */
export function registerPublishTrustHandshakeRoutes(app: Express, deps: PublishTrustHandshakeDeps): void {
  const limiter = createRateLimiter({
    profile: PUBLISH_TRUST_HANDSHAKE_PER_IP,
    clock: { nowMs: () => Date.parse(deps.clock.nowIso()) },
  });

  /** True when this caller is within its per-IP ceiling; on `false` the 429 has already been sent. */
  async function withinRateLimit(req: Request, res: Response): Promise<boolean> {
    const result = await limiter.check({ key: resolveClientIp(req) });
    if (result.allowed) return true;
    res.setHeader("Retry-After", String(result.retryAfterSeconds));
    res.status(429).json({
      error: "too many publishing handshake attempts",
      code: "RATE_LIMIT_EXCEEDED",
      details: { retryAfterSeconds: result.retryAfterSeconds },
    });
    return false;
  }

  /** This install's id, or `null` after sending the 503 when the site key is missing. */
  async function installationIdOrRefuse(res: Response): Promise<string | null> {
    const id = await deps.targetInstallationId.catch(() => null);
    if (id === null) res.status(503).json(NO_SITE_KEY);
    return id;
  }

  /** Express 4 does not catch a rejected async handler: the caller would hang and the process
   *  would log an unhandled rejection. Every handler here answers instead. */
  function answered(handler: (req: Request, res: Response) => Promise<void>) {
    return async (req: Request, res: Response): Promise<void> => {
      try {
        await handler(req, res);
      } catch (err) {
        console.error(`[publish-trust] handshake ${req.method} ${req.path} failed:`, err);
        res.status(500).json(HANDSHAKE_FAILED);
      }
    };
  }

  app.get("/api/publish-trust/v1/identity", answered(async (req, res) => {
    const installationId = await installationIdOrRefuse(res);
    if (installationId === null) return;
    res.json({
      installationId,
      workspaceId: deps.workspaceId,
      origin: originOf(req),
    });
  }));

  app.post("/api/publish-trust/v1/challenge", answered(async (req, res) => {
    if (!(await withinRateLimit(req, res))) return;

    const targetInstallationId = await installationIdOrRefuse(res);
    if (targetInstallationId === null) return;
    const record = await issuePublishChallenge({
      store: deps.challengeStore,
      clock: deps.clock,
      idGen: deps.idGen,
      targetInstallationId,
    });

    // The audience travels with the nonce so the source can build the canonical string without a
    // second round trip. It is not a secret and is the same value `/identity` already states.
    res.json({
      nonce: record.nonce,
      targetInstallationId: record.targetInstallationId,
      expiresAt: record.expiresAtIso,
    });
  }));

  app.post("/api/publish-trust/v1/session", answered(async (req, res) => {
    if (!(await withinRateLimit(req, res))) return;

    const response = asChallengeResponse(req.body);
    if (!response) {
      res.status(401).json(HANDSHAKE_REFUSAL);
      return;
    }

    // Before the grant lookup: a keyless site answers 503 whatever the source, so the status cannot
    // tell a prober which installation ids hold a grant.
    const targetInstallationId = await installationIdOrRefuse(res);
    if (targetInstallationId === null) return;

    const grant = findGrantForSource(await deps.grants(), response.sourceInstallationId);
    // An absent grant is the ordinary state of a site nobody has paired with, not an error. It is
    // answered with the same refusal as a bad signature so this route cannot be used to ask
    // "has anyone provisioned publishing here yet?" — nor, by naming installation ids one at a
    // time, "is THIS publisher allowed here?".
    if (!grant || !isGrantActive(grant, deps.clock.nowIso())) {
      res.status(401).json(HANDSHAKE_REFUSAL);
      return;
    }

    const verification = await verifyChallengeResponse(
      { store: deps.challengeStore, clock: deps.clock },
      { grant, targetInstallationId, response }
    );
    if (!verification.ok) {
      res.status(401).json(HANDSHAKE_REFUSAL);
      return;
    }

    const { token, payload } = await mintPublishSession(
      { keyring: deps.keyring, workspaceId: deps.workspaceId, clock: deps.clock },
      {
        sourceInstallationId: verification.verified.sourceInstallationId,
        targetInstallationId,
        capabilities: verification.verified.capabilities,
        generation: verification.verified.generation,
      }
    );

    res.json({ token, expiresAt: payload.expiresAtIso, capabilities: payload.capabilities });
  }));
}

import type { Express } from "express";
import { SHARE_DOWNLOAD_HEADERS } from "#src/features/site-backup/share-service";
import type { SiteShareRegistry } from "#src/features/site-backup/share-registry";

/**
 * Possession of the 16-letter (~91-bit) token authorizes exactly one attachment. Mount before request
 * tracking/page analytics: neither a successful token nor a guessed token belongs in telemetry.
 * All other methods/shapes in this reserved namespace terminate here, including without storage.
 */
export function registerPublicShareRoutes(required: { app: Express; registry?: SiteShareRegistry }, _optional: Record<string, never> = {}): void {
  required.app.get("/_share/:token/:file", async (req, res) => {
    res.set({ ...SHARE_DOWNLOAD_HEADERS });
    try {
      const row = await required.registry?.findToken({ token: String(req.params.token), file: String(req.params.file) });
      if (!row || row.storage?.provider !== undefined && row.storage.provider !== "tovu-server") { res.sendStatus(404); return; }
      res.set("Content-Disposition", `attachment; filename="${row.file}"`);
      res.sendFile(`${row.shareId}.tovu.zip`, { root: required.registry!.directory, cacheControl: false, lastModified: false, acceptRanges: false, dotfiles: "deny" }, (error) => {
        if (error && !res.headersSent) res.sendStatus(404);
        else {
          if (error) res.destroy();
        }
      });
    } catch { if (!res.headersSent) res.sendStatus(404); }
  });
  required.app.use("/_share", (_req, res) => { res.set({ ...SHARE_DOWNLOAD_HEADERS }).sendStatus(404); });
}

import { captureVisitorEvent } from "../../visitor-analytics.js";
import type { Express, Request } from "express";

import type { JsonObject } from "@jini-ai/core/primitives";
import { createAnalyticsForwardLimiter, ingestHit } from "@jini-ai/analytics";
import { createAnalyticsIngestBinding, type AnalyticsIngestRouteDeps as IngestDeps } from "#src/features/analytics/index";
import type { IngestBeacon, IngestContext } from "#src/features/analytics/index";

type AnalyticsIngestRouteDeps = IngestDeps<Request>;

/**
 * @file Public ingest beacon route for the `analytics` library (ADR-035 §5).
 *
 * Purpose:
 * Registers `POST /_analytics/e` — the unauthenticated, first-party beacon endpoint a site's
 * pages call via `navigator.sendBeacon`. This is intentionally a SITE route (mirrors
 * `routes/site/pages.ts`), not an admin route: no session is required or checked here, by design
 * (ADR-035 §5 — the beacon must work for anonymous visitors).
 *
 * How it relates to the project:
 * - Delegates normalization/policy logic to @jini-ai/analytics and owns the HTTP boundary: parsing the untrusted request body into an `IngestBeacon`, and
 *   pulling `ip`/`userAgent`/`acceptLanguage` off the request into an `IngestContext`.
 * - The response is ALWAYS `204 No Content`, regardless of `ingestHit`'s `{ accepted, reason }`
 *   result, and regardless of whether `ingestHit` itself throws. Leaking accept/reject (or a
 *   distinct error status) back to an anonymous caller would turn the beacon into an oracle for
 *   probing a site's exclusion rules, DNT/GPC handling, or PII-shape validation — the ADR's
 *   fire-and-forget beacon contract exists specifically to prevent that.
 */

/** Bounded input length caps applied at the HTTP boundary (secure-input-handling: untrusted body). */
const MAX_HOST_LENGTH = 253; // max valid DNS hostname length
const MAX_PATH_LENGTH = 2048;
const MAX_REFERRER_LENGTH = 2048;
const MAX_EVENT_NAME_LENGTH = 200;

/** Truncates an untrusted string field to a bounded length; non-strings coerce to `""`. */
function boundedString(value: unknown, maxLength: number): string {
  const str = typeof value === "string" ? value : "";
  return str.slice(0, maxLength);
}

/** True only for a plain JSON object (not an array, not `null`) — guards `eventProps`. */
function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Parses the untrusted POST body into an `IngestBeacon`. Every field is defensively coerced and
 * length-bounded — this body comes from an anonymous, unauthenticated client.
 *
 * @complexity O(1) (plus the bounded string truncation above).
 * @overallScore 100/100
 */
function parseBeacon(body: unknown, fallbackHost: string): IngestBeacon {
  const raw = (body ?? {}) as Record<string, unknown>;
  const host = boundedString(raw.host, MAX_HOST_LENGTH) || fallbackHost;
  const referrer = typeof raw.referrer === "string" ? boundedString(raw.referrer, MAX_REFERRER_LENGTH) : null;
  const kind = raw.kind === "event" ? "event" : "pageview";
  const eventName =
    kind === "event" && typeof raw.eventName === "string"
      ? boundedString(raw.eventName, MAX_EVENT_NAME_LENGTH)
      : undefined;

  return {
    host,
    path: boundedString(raw.path, MAX_PATH_LENGTH),
    referrer,
    kind,
    eventName,
    eventProps: isJsonObject(raw.eventProps) ? raw.eventProps : undefined,
    dnt: raw.dnt === true,
    gpc: raw.gpc === true,
  };
}

/** Builds the transient per-request context `ingestHit` consumes and then discards (no PII persisted). */
function buildContext(req: Request, receivedAt: string): IngestContext {
  return {
    ip: req.ip ?? req.socket.remoteAddress ?? "",
    userAgent: req.get("user-agent") ?? "",
    acceptLanguage: req.get("accept-language") ?? null,
    receivedAt,
  };
}

/** The browser contribution owns vendor pageviews when present; private routes never emit them.
 * @complexity O(1), no mutation or network. */
function shouldCaptureVisitorPageview({ deps, beacon }: { deps: AnalyticsIngestRouteDeps; beacon: IngestBeacon }, _optional = {}): boolean {
  return !(deps.browserAnalytics?.({ surface: 'site' }) ?? []).length && beacon.kind === "pageview" && !/^\/(admin|_preview|preview)(\/|$)/.test(beacon.path);
}

/**
 * Registers the public analytics beacon route with host clock, configuration and sink ports.
 * The binding adapter supplies Jini's required policy/salt context and converts port/hook arguments.
 * createApp wires this public route separately from admin RouteDeps.
 */
export function registerAnalyticsIngestRoute(app: Express, deps: AnalyticsIngestRouteDeps): void {
  // One cap per route for every request's vendor calls: a beacon flood sheds vendor calls, never local hits.
  const limiter = createAnalyticsForwardLimiter();
  app.post("/_analytics/e", async (req, res) => {
    // Browser headers are authoritative even if the body omits or contradicts its privacy signal.
    if (req.get("dnt") === "1" || req.get("sec-gpc") === "1") { res.status(204).end(); return; }
    const receivedAt = new Date(deps.clock.nowMs()).toISOString();
    const beacon = parseBeacon(req.body, req.hostname ?? "");
    const context = buildContext(req, receivedAt);

    try {
      // Never throws (fails toward no vendor); resolved before ingest because consent is per request.
      const forwarders = deps.forwarders ? await deps.forwarders({ request: req }) : [];
      const binding = createAnalyticsIngestBinding({ deps }, { forwarders, limiter });
      const outcome = await ingestHit({ input: { beacon, context }, deps: binding.deps }, binding.optional);
      if (outcome.accepted && shouldCaptureVisitorPageview({ deps, beacon })) {
        void captureVisitorEvent({ deps, request: req, name: "site_pageview", properties: { routeTemplate: "/:path" } });
      }
    } catch {
      // Never let an ingest-side failure surface to the public beacon caller — see file header.
    }

    // Always 204, regardless of accept/reject or failure above (ADR-035 §5 — no oracle).
    res.status(204).end();
  });
}

import type { Express } from "express";
import { ADMIN_ASSISTANT_PERMISSION } from "#src/assistant/index";
import { getAuthedCredentialKind, getAuthedPrincipal, requireAdminSession } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";
import { renderSiteChatComparisonFrame, renderSiteChatComparisonPage } from "./chat-comparison-html.js";

/**
 * Development sandbox only. Each document requires the existing browser-session and permission
 * gates; iframe URLs are never a way around the parent page's access check. The public assistant
 * endpoint retains its own master switch, credentials and rate limits.
 */
export function registerSiteChatComparisonRoutes({ app, deps }: { app: Express; deps: RouteDeps },
  options: { production?: boolean } = {}): void {
  const base = "/__compare/site-chat";
  app.use(base, (_req, res, next) => {
    res.set("Cache-Control", "private, no-store");
    // Check on every request too: a server that changes environment must not retain this surface.
    if (options.production ?? process.env.NODE_ENV === "production") { res.sendStatus(404); return; }
    next();
  }, requireAdminSession(deps), async (_req, res, next) => {
    try {
      if (getAuthedCredentialKind(res) !== "session") { res.sendStatus(403); return; }
      const principal = getAuthedPrincipal(res);
      const permission = await deps.authorize({
        principalId: principal.id, permission: ADMIN_ASSISTANT_PERMISSION,
        workspaceId: deps.workspaceId, entityType: "assistant-settings",
      });
      if (!permission.allowed) { res.sendStatus(403); return; }
      next();
    } catch (error) { next(error); }
  });
  app.get(base, (_req, res) => res.type("html").send(renderSiteChatComparisonPage({})));
  for (const variant of ["react", "vanilla"] as const) {
    app.get(`${base}/${variant}`, (_req, res) => res.type("html").send(renderSiteChatComparisonFrame({ variant })));
  }
}

import { captureVisitorEvent } from "../../visitor-analytics.js";
import type { VisitorAnalyticsDeps } from "../../visitor-analytics.js";
import { urlencoded, type Express, type RequestHandler } from "express";
import type { CommentsProviderRegistry } from '@jini-ai/capability-providers/comments';
import type { CommentIngressPolicy } from "@jini-ai/cms/comments";
import { createCommentSubmitHandler } from "@jini-ai/cms/comments/express";
import { resolveClientIp, type RateLimiter } from "#src/contracts/core/rate-limit/rate-limit";
import { resolveProtocol, resolvePublicOrigin } from "../oauth/public-origin.js";

/**
 * @file ADR-031 §4 (SPEC-033) — the public, unauthenticated comment submission route. The ONLY
 * route a hostile visitor can reach into the Comments plugin; everything downstream of this file
 * is `CommentIngressPolicy` (rate-limit, honeypot, sanitize, spam-classify — see `Jini/packages/cms/src/comments/ingress.ts`).
 *
 * `authorIpHash` is computed HERE, at the HTTP boundary, from the raw request IP — the raw IP
 * itself is never passed into `ingressContext` or stored (mirrors `analytics/ingest.ts`'s
 * discard-raw-IP-at-the-boundary discipline).
 *
 * The salt is resolved once by the composition root (`resolveCommentsIpHashSalt`,
 * `features/comments/ip-hash-salt.ts`) and injected here. This route used to read
 * `COMMENTS_IP_SALT` itself and fall back to a public `"dev-only-insecure-salt"` constant —
 * see that resolver's header for why the fallback is now derived from the site key instead.
 */
export interface CommentsSubmitDeps extends VisitorAnalyticsDeps {
  ingressPolicy: CommentIngressPolicy;
  workspaceId: string;
  /** A separate HTTP budget; the ingress policy retains its own submission limiter. */
  rateLimiter: Pick<RateLimiter, "check">;
  /** The composition root's resolved IP-hash salt. A promise because the site-key derivation is
   *  async while route registration is not; requests wait for it (it settles during boot). */
  ipHashSalt: Promise<string>;
  providers?: CommentsProviderRegistry;
}

/** Only local paths can be used for the no-JS PRG response; never trust a Referer redirect. */
export function commentFormReturnTo({ value }: { value: unknown }, _options = {}): string {
  if (typeof value !== 'string' || !value.startsWith('/') || value.startsWith('//') || /[\\\r\n]/.test(value)) return '/';
  const url = new URL(value, 'https://comments.invalid');
  return url.origin === 'https://comments.invalid' ? url.pathname + url.search : '/';
}

/** Dispatches a public submission to the site's ACTIVE stored provider. No provider, or an embedded
 * one (the vendor owns its own form), is the same generic refusal as any other ingress rejection.
 * @complexity O(1) plus the provider's ingress work. */
function providerIngress({ providers, siteId }: { providers: CommentsProviderRegistry; siteId: string }, _options = {}): CommentIngressPolicyLike {
  return { submit: async submission => {
    const { adapter } = await providers.active({ siteId });
    if (!adapter || adapter.kind !== 'stored') return { ok: false, reason: 'comments-disabled' };
    const result = await adapter.submission.submit({ siteId, entryId: submission.entryId, parentId: submission.parentId,
      authorName: submission.authorName, authorEmail: submission.authorEmail, authorUrl: submission.authorUrl, bodyRaw: submission.bodyRaw,
      authorIpHash: String(submission.ingressContext.authorIpHash), honeypotValue: String(submission.ingressContext.honeypotValue) });
    return result.ok ? { ok: true, comment: { id: result.id, status: result.status } } : result;
  } };
}
type CommentIngressPolicyLike = Parameters<typeof createCommentSubmitHandler>[0]['ingressPolicy'];

/** CSRF gate. A browser always sends `Origin` on a POST, so a cross-site page (including a no-JS form
 * on another origin, or an opaque `null` origin) is refused. A missing `Origin` is allowed ONLY for a
 * JSON body: a cross-site page cannot send `application/json` without a CORS preflight this route never
 * answers, so that request is a non-browser client, which no Origin check could stop anyway (the
 * honeypot, spam check and both rate limits are what bound those). The scheme honors
 * `X-Forwarded-Proto` like the OAuth callback origin does: an attacker cannot set that header on a
 * victim's browser request, and without it every HTTPS visitor behind a TLS-terminating proxy that
 * lacks a `trust proxy` hop count would be refused. A misconfigured TOVU_PUBLIC_URL throws (a 500), loudly.
 * @complexity O(1). */
export function isSameOriginCommentPost({ request }: { request: Parameters<RequestHandler>[0] }, _options = {}): boolean {
  const origin = request.get('origin');
  if (origin === undefined) return request.is('application/json') === 'application/json';
  // The configured public origin (TOVU_PUBLIC_URL) also counts, for proxies that rewrite Host.
  return origin === `${resolveProtocol(request)}://${request.get('host')}` || origin === resolvePublicOrigin(request);
}

/** Mounts Jini's handler with the site's ingress, request budget, salt and proxy policy.
 * @throws TypeError at registration when `deps.ipHashSalt` is missing; any other missing/invalid
 *   handler dependency (Jini's TypeError) surfaces as a 500 through `next(error)` on the first
 *   request, once the salt promise has settled.
 * @complexity O(1) route setup; request work belongs to the Jini handler.
 */
export function registerCommentsSubmitRoute(app: Express, deps: CommentsSubmitDeps): void {
  // Named refusal rather than "Cannot read properties of undefined (reading 'then')", which is
  // what a caller missing this dependency produced on 2026-10-08.
  if (typeof deps.ipHashSalt?.then !== "function") {
    throw new TypeError("registerCommentsSubmitRoute requires deps.ipHashSalt (a Promise<string> from resolveCommentsIpHashSalt at the composition root)");
  }
  const handler = deps.ipHashSalt.then((ipHashSalt) => createCommentSubmitHandler({
    ingressPolicy: { submit: async submission => {
      const owner = deps.providers ? providerIngress({ providers: deps.providers, siteId: deps.workspaceId }) : deps.ingressPolicy;
      return owner.submit(submission);
    } },
    workspaceId: deps.workspaceId,
    ipHashSalt,
    rateLimiter: deps.rateLimiter,
    clientIp: ({ request }) => resolveClientIp(request),
  }, { onAccepted: ({ request, submission, comment }) => captureVisitorEvent({ deps, request, name: "comment_submitted", properties: {
    entryId: submission.entryId, moderationState: ["pending", "approved", "spam"].includes(comment.status) ? comment.status : "other",
  } }), formRedirect: ({ request }) => request.is('application/x-www-form-urlencoded')
    ? commentFormReturnTo({ value: request.body?.returnTo }) : undefined }));
  // Observed here so a construction failure is not an unhandled rejection at boot; each request
  // below re-awaits the same promise and hands that failure to Express's error path instead.
  handler.catch(() => undefined);
  const submit: RequestHandler = async (request, response, next) => {
    if (!isSameOriginCommentPost({ request })) {
      response.status(403).json({ error: 'A same-origin comment submission is required' });
      return undefined;
    }
    let built: RequestHandler;
    try {
      built = await handler;
    } catch (error) {
      next(error);
      return undefined;
    }
    return built(request, response, next);
  };
  app.post("/api/site/comments", urlencoded({ extended: false, limit: '32kb', parameterLimit: 16 }), submit);
}

