import type { Request, Response, RequestHandler } from 'express';
import type { Clock } from '@jini-ai/core/primitives';
import { admitFormRequest } from '@jini-ai/cms/forms';
import { createRateLimiter, resolveClientIp } from '#src/contracts/core/rate-limit/rate-limit';

/** Host policy: 5 attempts/minute/source across forms and 30 multipart requests/minute/site, before parsing up to
 * 12 MiB. This bounds admitted multipart input to 360 MiB/minute/process even with rotating IPs.
 * @returns Middleware with isolated injected-clock counters; parsing runs only after admission.
 * @complexity O(1) counters per request, bounded by the site budget; no added database I/O. */
export function createFormsAdmissionMiddleware({ workspaceId, clock }: { workspaceId: string; clock: Clock },
  { onHtmlRefusal }: { onHtmlRefusal?: (required: { request: Request; response: Response; retryAfterSeconds: number }) => void | Promise<void> } = {},
): RequestHandler {
  const site = createRateLimiter({ profile: { windowSeconds: 60, max: 30, burst: 0 }, clock });
  const source = createRateLimiter({ profile: { windowSeconds: 60, max: 5, burst: 0 }, clock });
  return async (request, response, next) => {
    try {
      const result = await admitFormRequest({ workspaceId, sourceIp: resolveClientIp(request), site, source }, { multipart: /^\s*multipart\/form-data\s*(?:;|$)/i.test(request.headers['content-type'] ?? '') });
      if (result.allowed) { next(); return; }
      response.set('Retry-After', String(result.retryAfterSeconds));
      if (onHtmlRefusal && (request.headers.accept ?? "").includes("text/html")) { await onHtmlRefusal({ request, response, retryAfterSeconds: result.retryAfterSeconds }); return; }
      response.status(429).json({ code: 'FORMS_RATE_LIMIT_EXCEEDED', error: `Too many form requests. Wait ${result.retryAfterSeconds} seconds, then send the form again.` });
    } catch (error) { next(error); }
  };
}

/** Express adapter for public form submissions; platform owns bounded multipart decoding.
 * Publish/adopt that export before releasing this adapter: the live server must not import an unbuilt symbol. */
import type { RequestHandler } from "express";
import { parseFormMultipart } from "@jini-ai/platform/http/multipart";
export { parseFormMultipart } from "@jini-ai/platform/http/multipart";

/** Express middleware runs after the route-scoped, size-bounded raw parser; malformed input is 400. */
export const parseFormMultipartMiddleware: RequestHandler = async (req, res, next) => {
  // req.is() only matches when a multipart content-type header is present.
  const contentType = req.is("multipart/form-data") && req.get("content-type");
  if (!contentType) { next(); return; }
  try { req.body = await parseFormMultipart({ bytes: req.body, contentType }); next(); }
  catch (error) { res.status(error instanceof RangeError ? 413 : 400).json({ code: "FORMS_SUBMISSION_VALIDATION_ERROR", error: "invalid or oversized multipart form" }); }
};

import { createFormsAdmissionMiddleware } from "./forms-admission.js";
import { captureVisitorEvent, visitorAnalyticsProvenance } from "../../visitor-analytics.js";
import { FormSubmissionValidationError, FormSchemaChangedError, FormAttachmentSpaceError, FormRateLimitExceededError, FormDefinitionNotFoundError, FormSubmissionTooFastError, type SubmissionAttempts } from "@jini-ai/cms/forms";
import type { VisitorAnalyticsDeps } from "../../visitor-analytics.js";
import { parseFormMultipartMiddleware } from "./forms-multipart.js";
import { RESERVED_SEGMENTS } from "#src/platform/routing/index";
import express, { type Express } from "express";
import { createFormSubmitHandler, type CreateFormSubmitHandlerRequired } from "@jini-ai/cms/forms/express";
import { submitForm, type SubmitFormDeps } from "#src/features/forms/index";
import { siteRelativeTargetReason } from "@jini-ai/cms/redirects";
import { resolveClientIp } from "#src/contracts/core/rate-limit/rate-limit";
import { isHttpsRequest } from "../oauth/public-origin.js";
import { clearFormSubmissionResultQueryParams, encodeFormSubmissionResultQuery,
  encodeFormFlashCookieValue, FORM_FLASH_COOKIE_NAME } from "../../http/site/render.js";

/**
 * @file Public submission route for `forms` (SPEC-010 `FORMS_POST_SUBMIT`, REQ-05).
 *
 * Mirrors `routes/site/analytics-ingest.ts`'s public-route shape: no session required, registered
 * before the site `/:slug` catch-all (see `server/app.ts`'s wiring). Reuses `resolveClientIp`
 * (`core/rate-limit/rate-limit.ts`) rather than re-deriving IP resolution — all real validation
 * happens inside `submitForm` (C-008); this file owns only the HTTP boundary.
 *
 * A native `<form>` POST navigates the browser to whatever this route returns — the ORIGINAL bug
 * here (2026-08-31 fix) was that every branch replied with raw JSON, which a JS-disabled visitor saw
 * as a literal `{"status":"accepted"}` screen instead of their page. `wantsHtmlResponse` splits the
 * two audiences this endpoint actually has by content negotiation: a fetch/XHR/API caller (this
 * file's own existing tests, none of which set an `Accept` header, land here) keeps the untouched
 * JSON contract; a real browser form submission (`Accept: text/html,...`) gets a Post/Redirect/Get
 * 303 back to the page that hosted the form, with the outcome threaded through the query string via
 * {@link encodeFormSubmissionResultQuery} — `routes/site/pages.ts` decodes and splices it back into
 * that page (`http/site/render.ts`'s `injectFormSubmissionResultIntoHtml`) on the way back down.
 *
 * A validation failure ALSO sets the `tovu_form_flash` cookie ({@link setFormFlashCookieForValidationFailure})
 * so the OTHER fields the visitor already typed survive that same round trip instead of coming back
 * wiped (2026-08-31 fix) — see `http/site/form-render.ts`'s "Validation flash cookie" section for why
 * this travels via a cookie rather than the query string.
 */

export interface RegisterFormsSubmitRouteDeps extends VisitorAnalyticsDeps {
  workspaceId: string;
  submitForm: SubmitFormDeps;
  formSubmissionAttempts?: SubmissionAttempts;
}

/** Registers `POST /forms/:slug/submit`. Must be registered BEFORE the site `/:slug` catch-all.
 *
 * `express.urlencoded` is mounted on THIS route's own POST registration (not a global `app.ts`
 * mount — same scoping precedent as `template-preview.ts`'s `POST` handler) because a real,
 * JavaScript-disabled `<form method="post">` — the exact case this file's Post/Redirect/Get fix
 * exists for — always encodes its body as `application/x-www-form-urlencoded`, which `app.ts`'s
 * blanket `express.json()` cannot parse; without this, every field on a genuine browser submission
 * would silently arrive as missing, failing REQUIRED-field validation on every real, non-JS
 * submission regardless of the redirect fix. A `fetch`/JSON caller (every pre-existing test in this
 * file) is unaffected — Express dispatches to whichever parser matches the request's actual
 * `Content-Type`, so mounting both here is additive, never a double-parse of the same request. */
export function registerFormsSubmitRoute(app: Express, deps: RegisterFormsSubmitRouteDeps): void {
  const resultDeps: Omit<CreateFormSubmitHandlerRequired, "submit"> = {
    workspaceId: deps.workspaceId,
    definitionRepo: deps.submitForm.definitionRepo,
    resolveClientIp,
    isHttpsRequest,
    resultCodec: {
      encodeResultQuery: encodeFormSubmissionResultQuery,
      clearResultQueryParams: clearFormSubmissionResultQueryParams,
      encodeFlashCookie: encodeFormFlashCookieValue,
      flashCookieName: FORM_FLASH_COOKIE_NAME,
    },
    targetRefusalReason: target => siteRelativeTargetReason({ target, reservedSegments: RESERVED_SEGMENTS }, {}),
  };
  const admission = createFormsAdmissionMiddleware({ workspaceId: deps.workspaceId, clock: deps.submitForm.clock }, {
    // Refuse before parsing, while retaining the same safe native-form result negotiation.
    onHtmlRefusal: ({ request, response, retryAfterSeconds }) => createFormSubmitHandler({
      ...resultDeps,
      submit: async () => { throw new FormRateLimitExceededError({ message: `Too many form requests. Wait ${retryAfterSeconds} seconds, then send the form again.`, retryAfterSeconds }); },
    }, {})(request, response),
  });
  app.post("/forms/:slug/submit", admission, express.urlencoded({ extended: false, limit: "1mb", parameterLimit: 2002 }), express.raw({ type: "multipart/form-data", limit: "12mb" }), parseFormMultipartMiddleware, (request, response) => createFormSubmitHandler({
    ...resultDeps,
    submit: async ({ input }) => {
      const analyticsProvenance = await visitorAnalyticsProvenance({ deps, request });
      try { return await submitForm({ deps: deps.submitForm, input }, { analyticsProvenance, attempts: deps.formSubmissionAttempts }); }
      catch (error) {
        // The timing refusal is bot screening, not a failed human conversion attempt.
        if (!(error instanceof FormSubmissionTooFastError)) {
          void captureVisitorEvent({ deps, request, name: "form_submit_failed", properties: formFailureProperties({ error }) });
        }
        throw error;
      }
    },
  }, {})(request, response));
}

/** Keep refusal reasons bounded; field names, answers, slugs and exception messages stay local.
 * @complexity O(1). */
function formFailureProperties({ error }: { error: unknown }, _optional = {}): Record<string, string | number> {
  if (error instanceof FormSubmissionValidationError) return { reason: "validation", invalidFieldCount: error.fieldErrors.length };
  if (error instanceof FormSchemaChangedError) return { reason: "schema_changed", invalidFieldCount: 0 };
  if (error instanceof FormAttachmentSpaceError) return { reason: "attachment_space", invalidFieldCount: 0 };
  if (error instanceof FormRateLimitExceededError) return { reason: "rate_limited", invalidFieldCount: 0 };
  if (error instanceof FormDefinitionNotFoundError) return { reason: "unavailable", invalidFieldCount: 0 };
  return { reason: "internal", invalidFieldCount: 0 };
}

import { computeIndexableEntries, type IndexableEntry } from "@jini-ai/cms/seo";
import { resolveSiteTitle } from "#src/features/settings/index";
import { seoForRequest } from "../../http/site/seo-render-context.js";
import type { SeoRouteRegistrar } from "#src/server/inbound/admin-http/routes/seo/deps";

/**
 * @file `GET /llms.txt` — public, unauthenticated (owner decision TM-TOVU-2026-08-31, per
 * `development/docs/ai-first-docs-checklist.md` "Do now" item 1). Follows the llmstxt.org
 * convention: an H1 title, a one-line blockquote summary, then H2-labeled sections of
 * `- [title](url): description` links — a machine-readable index a coding-agent tool (Cursor,
 * Claude Code, Windsurf, Copilot, Cline, Aider) can fetch in one request to learn the shape of the
 * whole site before reading further. Registered ahead of the site's `/:slug` catch-all, same as
 * `registerSeoRobotsRoute`/`registerSeoSitemapRoute` (`robots.ts`/`sitemap.ts` in this
 * directory) — see `modules/seo.ts`'s file header for the ordering requirement.
 *
 * 2026-09-04 rewrite: the checklist originally scoped this to a hand-curated `CURATED_DOCS` list
 * (Phase 2 note: "needs an explicit 'which pages count as docs' tag or convention — not built
 * yet"). That list drifted the moment a page was published, renamed, or unpublished outside it, so
 * this now derives the index from `computeIndexableEntries` (`Jini/packages/cms/src/seo/sitemap.ts`) — the same
 * publish/visibility/`noindex` filter `sitemap.xml` is built from (INV-04/05) — instead of
 * maintaining a second, hand-authored notion of "which pages count." Every published, publicly
 * visible, non-`noindex` post/page is listed; a members/paid/tiers-gated or draft page can never
 * leak here, same guarantee `sitemap.xml` gives. This is a deliberate, disclosed behavior change,
 * not silent drift — see `__tests__/llms.route.test.ts`'s file header for what it replaces.
 */

const CACHE_CONTROL_PUBLIC_PAGE = "public, max-age=60, stale-while-revalidate=300";

/**
 * Pure render: `IndexableEntry[]` -> the CommonMark body (llmstxt.org shape, see file header).
 * Sorted by resolved title — display order only, orthogonal to `computeIndexableEntries`'
 * inclusion/visibility rules — so the index reads as a stable, human-scannable list rather than
 * database insertion order. A page with no resolved description (no override, no site default, no
 * derivable excerpt — `SeoMeta.description` is optional) is still listed, just without the
 * trailing `: description` — never a fabricated one.
 *
 * @complexity O(n log n) in `entries.length` (the sort); the render itself is O(n).
 */
function renderLlmsTxt({ entries, title, description }: { entries: readonly IndexableEntry[]; title: string; description?: string }, _options = {}): string {
  const sorted = [...entries].sort((a, b) => a.meta.title.localeCompare(b.meta.title));
  const lines = [`# ${title.replace(/\s+/g, " ")}`, ""];
  if (description) lines.push(`> ${description.replace(/\s+/g, " ")}`, "");
  lines.push("## Pages", "");
  for (const entry of sorted) {
    const description = entry.meta.description ? `: ${entry.meta.description}` : "";
    lines.push(`- [${entry.meta.title}](${entry.meta.canonical})${description}`);
  }
  return `${lines.join("\n")}\n`;
}

export const registerLlmsTxtRoute: SeoRouteRegistrar = (app, deps) => {
  app.get("/llms.txt", async (req, res) => {
    try {
      await deps.seoReady;
      const entries = await computeIndexableEntries({
        // Share sitemap/feed's serving origin; the exporter rewrites it for its destination.
        deps: seoForRequest({ req, deps: deps.seoDeps }),
        input: { workspaceId: deps.workspaceId },
      }, {});
      const title = await resolveSiteTitle(
        { settingsRepo: deps.settingsRepo, preservationStore: deps.siteTitlePreservationStore, workspaceRepo: deps.workspaceRepo, siteDisplayName: deps.siteDisplayName },
        { workspaceId: deps.workspaceId },
      );
      const { defaultDescription: description } = await deps.seoDeps.settings.getSeoSettings({ workspaceId: deps.workspaceId });
      res.set("Cache-Control", CACHE_CONTROL_PUBLIC_PAGE).type("text/markdown").send(renderLlmsTxt({ entries, title, ...(description ? { description } : {}) }));
    } catch {
      res.status(500).type("text/plain").send("internal error");
    }
  });
};

import { getMediaAccessEvidenceCache, type AssetReferenceScan, type AssetReferenceIndex } from '#src/features/media/access-evidence';
import { collectReferencedMediaKeys, collectPlacedWidgetMediaKeys } from "#src/features/publish-content/media-references";
import { parseWidgetInstancePayload } from "@jini-ai/cms/widgets";
import { readRequestCookie } from "#src/server/http/request-cookie";
import type { Request, Response } from "express";
import { createHash } from "node:crypto";

import { guardMediaRenditionRepo } from "#src/features/media/guard-rendition-repo";
import { findMediaByIdOrSlug, resolveMediaRendition, sanitizeSvg, sniffContentType, type MediaRecord } from "@jini-ai/cms/media";
import { ImageSourceCorruptError, ImageTransformUnavailableError } from "@jini-ai/cms/media/node";
import { isTrashed, type PostRecord } from "#src/features/post/post";
import { DefaultMemberAccessResolver, resolvePostMemberAccess } from "#src/features/members/access-resolver";
import type { MemberAccessResolver } from "#src/features/members/index";
import { parseRangeHeader } from "#src/server/inbound/admin-http/range";
import type { MediaRenditionRouteDeps, MediaRenditionRouteRegistrar } from "#src/server/inbound/admin-http/routes/media/deps";
import { SVG_CONTENT_SECURITY_POLICY, DISALLOWED_INLINE_CONTENT_TYPES, resolveMediaOriginalBlob, sendMediaOriginalResponse } from "#src/server/inbound/admin-http/routes/media/original";
import { MEMBER_SESSION_COOKIE } from "../../http/members.js";

const CACHE_CONTROL_HEADER = "Cache-Control";

/**
 * @file Public, unauthenticated media rendition serving route (ADR-027 §4
 * frozen URL contract): `GET /m/{assetId}/{transformName}.v{version}/{slug}.{ext}`.
 *
 * Single-workspace v1 (same disclosed assumption as
 * `routes/site/analytics-ingest.ts`'s `resolveWorkspaceForHost` stub): the
 * frozen URL shape has no workspace segment at all, so this route always
 * resolves against `deps.workspaceId`.
 *
 * `slug`/`ext` (the final path segment) are read only to satisfy Express's
 * routing shape — per ADR-027 §4 they are cosmetic and never participate in
 * the lookup (`resolveMediaRendition` never sees them).
 *
 * This file also owns a second, separate public route (2026-08-24, video/embed capability):
 * `GET /m/{assetId}/original` — see {@link registerMediaOriginalVideoRoute}'s own doc for why
 * video needs a route that bypasses the transform pipeline above entirely, rather than a new
 * `TransformFormat`. Two path segments after `/m/`, never three, so it can never collide with the
 * `{transformName}.v{version}/{slug}.{ext}` shape above regardless of registration order.
 */

const TRANSFORM_SPEC_PATTERN = /^(.+)\.v(\d+)$/;

/** The only `Cache-Control` either route's 404 may carry. Named, and written through the single
 *  {@link sendMediaNotFound} helper below, because the 2026-09-05 oracle bug was precisely two
 *  404 call sites drifting apart on this header — a shared constant that two call sites still set
 *  independently would have drifted the same way. */
const PRIVATE_NO_STORE = "private, no-store";

/** Replacement preserves ids and authored URLs, including their old source-hash query.
 *  Current and retired slugs can also resolve to changed bytes after replacement or name reuse.
 *  These routes always resolve the live source rather than a historical content snapshot, so
 *  even a matching `v` cannot promise immutable bytes. Limit reuse to sixty seconds;
 *  the existing ETag lets an unchanged asset return 304. Never used for a gated outcome. */
const REVALIDATING_PUBLIC = "public, max-age=60";

/**
 * The ONE writer for every 404 either public media route emits.
 *
 * Both routes must answer "this asset is gated and you may not read it" and "there is no such
 * rendition" identically — that indistinguishability is the whole point of returning 404 rather
 * than 403 for a denied caller. Before 2026-09-05 each outcome set its own header inline and they
 * disagreed (`private, no-store` vs `public, max-age=60`), handing anyone a free existence oracle.
 * Routing every 404 through one function makes agreement structural instead of a convention four
 * call sites have to remember; the header can only ever be {@link PRIVATE_NO_STORE}, since a
 * session-dependent denial must never be replayable from a shared cache.
 *
 * @complexity O(1).
 */
function sendMediaNotFound(res: Response, error: string): void {
  res.status(404).set(CACHE_CONTROL_HEADER, PRIVATE_NO_STORE).json({ error });
}

/**
 * Parses and validates the `{transformName}.v{version}` path segment against `assetId`,
 * returning either the resolved fields or the one-of-two malformed-URL error messages the route
 * has always distinguished. Isolated from the handler so both validation branches (pattern match,
 * version range) live in one place instead of the caller's own complexity budget.
 *
 * @complexity O(1) — one regex match plus two range/shape checks.
 */
function resolveTransformSpec(
  assetId: string,
  transformSpec: string,
): { transformName: string; version: number } | { errorMessage: string } {
  const match = TRANSFORM_SPEC_PATTERN.exec(transformSpec);
  if (!assetId || !match) {
    return { errorMessage: "malformed media rendition URL" };
  }

  const [, transformName, versionText] = match;
  const version = Number(versionText);
  if (!Number.isInteger(version) || version < 1) {
    return { errorMessage: "malformed transform version" };
  }

  return { transformName, version };
}

/** Local copy of `pages.ts`'s own (file-private) `isPlainObject`/`collectMediaRefAssetIds` walk —
 *  duplicated rather than imported, same "each side owns its own copy of a small pure helper"
 *  precedent `9bf661e9`'s content-API gating fix already followed for `readRawCookie`/
 *  `createMemberAccessResolver` below. Walks a TipTap-shaped `bodyJson` tree collecting every
 *  ref-based media node's `assetId` (ADR-027 §4's `{assetId, transformName}` shape) — both the
 *  legacy image-only ref shape and the generic `media` node (2026-09-11, `render.ts`'s
 *  `renderDocMedia`'s own doc) share this collection, since both key off the same `assetId` attr.
 *  Widened 2026-09-11 (this route's own gating-bypass fix, renamed from `collectImageAssetIds`
 *  accordingly) to match `pages.ts`'s and `resolver-service.ts`'s own collectors, which were
 *  widened the same day — before this fix, a members-only entry embedding an asset through the new
 *  `media` node (the admin composer's Media button/drag-drop/paste all insert it now) produced an
 *  EMPTY gating set here, and {@link resolveMediaAccessDecision}'s fail-open default served it to
 *  anonymous visitors with a year-long immutable CDN header. A legacy `src`-only node still
 *  contributes nothing, matching `render.ts`'s own `image` case, which never reads `src` at all once
 *  a ref shape exists. */
function collectMediaRefAssetIds(root: unknown, out: Set<string>): void {
  // An explicit stack, not recursion: a stored document's nesting depth is attacker/import-controlled
  // and a 5000-deep list overflowed the call stack here (GET /:slug -> 500) before `render.ts`'s own
  // MAX_RENDER_DEPTH placeholder could ever apply. Children are pushed in reverse so the walk stays
  // pre-order, the same visit order the recursive version had.
  // Completeness matters most here: this set gates members-only media, so the walk must never stop
  // early at a depth bound — an asset it misses would be served under the fail-open default.
  // The shared authored-reference collector owns that iterative walk, including placement content.
  for (const key of collectReferencedMediaKeys({ bodyJson: root })) out.add(key);
}

/**
 * The body formats this route's own reference scan knows how to read end to end:
 * `"doc"` through {@link collectMediaRefAssetIds}'s `bodyJson` walk, `"html"` through
 * {@link addHtmlEmbedAssetIds}'s marker scan. Deliberately a runtime set rather than a reliance on
 * `PostBodyFormat` being a closed union at compile time — a `bodyFormat` value arrives from a
 * database column (`repo.sqlite.ts`'s `toRecord`), so a THIRD format added later reaches this
 * function as data long before any type error would point at this file. See
 * {@link EntryAssetScan}'s `readable` flag for what happens when one does.
 */
const READABLE_BODY_FORMATS: ReadonlySet<string> = new Set(["doc", "html"]);

/** Whether the author has marked this entry as anything other than freely public. Extracted so the
 *  three call sites that ask this question (live-referrer candidacy, the public-referrer shortcut,
 *  and opaque-body classification) share one definition of "gated" instead of three inline
 *  `resolvePostMemberAccess(...).visibility` reads that could drift apart. */
function isGatedEntry(entry: Pick<PostRecord, "memberAccessJson">): boolean {
  return resolvePostMemberAccess(entry.memberAccessJson).visibility !== "public";
}

/**
 * Adds every `data-embed-config` MEDIA marker's asset id found in an `"html"`-format Page's
 * `body_html` to `out`.
 *
 * This is the second half of "which entries reference this asset", and it was missing until
 * 2026-09-05. `collectMediaRefAssetIds` walks `bodyJson` only, so it can see a `"doc"`-format entry's
 * ref-based TipTap `image` nodes and nothing else — but an `"html"`-format Page's real content
 * lives in `bodyHtml` (`post.ts`'s own doc: `bodyJson` stays an empty non-null object for those
 * rows), and video has NO TipTap node type in this codebase at all: `render.ts`'s `renderVideoTag`
 * is reached exclusively from `renderWidgetMediaImage`, i.e. from a resolved
 * `data-embed-config='{"type":"media","id":"…"}'` marker. So before this function existed, every
 * embed on an `"html"` Page and every video anywhere was invisible to the gate.
 *
 * Uses the shared authored-reference collector, backed by `scanEmbedMarkers`, rather than `widgets/`'s
 * `scanHtmlEmbeds` wrapper, for two reasons: `scanHtmlEmbeds` truncates at
 * `MAX_HTML_EMBEDS_PER_PAGE` (a render-time resource bound — a gate that stopped scanning at
 * marker 50 would hand marker 51 straight to an anonymous caller), and it discards `rejected`,
 * which is exactly the signal {@link scanEntryAssets} needs to know its own scan was incomplete.
 * `marker.type`/`marker.id` are the parsed `config.type`/`config.id` that
 * `resolver-service.ts`'s `parseMediaEmbedRef` reads as `{assetId, transformName}` — same keys,
 * same parser, so what this gate sees and what the renderer resolves cannot disagree.
 *
 * `scanEmbedMarkers`'s `rejected` list is deliberately NOT treated as "a reference I might have
 * missed" here, unlike in `entry-refs/extractor.ts` where it is the loudest failure in the file.
 * The difference is what each index is for: safe-delete's where-used check must be conservative
 * because a dropped row lets a delete proceed, whereas this gate only has to match what a visitor
 * can actually FETCH. A rejected marker resolves to nothing — `scanHtmlEmbeds` iterates `markers`
 * only, and `substituteHtmlEmbeds` cannot see a rejected one either, so its authored markup
 * survives verbatim into the page and no asset is ever served through it. It is an inert
 * reference, not a hidden one, so counting it would deny live assets to buy no security.
 *
 * @complexity O(n) over `bodyHtml`'s length (one shared regex scan), plus O(k) over the markers found.
 */
function addHtmlEmbedAssetIds(bodyHtml: string, out: Set<string>): void {
  // The same untruncated marker scan now includes compound media, raw tokens and content overlays.
  for (const key of collectReferencedMediaKeys({ bodyHtml })) out.add(key);
}

/** Every asset id one entry references, across BOTH body columns, plus whether this scan knows how
 *  to read the entry's body at all. Both columns are always walked rather than switching on
 *  `bodyFormat`: a `"doc"` row's `bodyHtml` is `null` and an `"html"` row's `bodyJson` is empty, so
 *  the unused half costs nothing, and a row that somehow carries both is fully covered instead of
 *  half-scanned. */
interface EntryAssetScan {
  readonly ids: Set<string>;
  readonly readable: boolean;
}

function scanEntryAssets(entry: PostRecord, savedWidgets?: ReadonlyMap<string, Record<string, unknown>>): EntryAssetScan {
  const ids = new Set<string>();
  collectMediaRefAssetIds(entry.bodyJson, ids);
  if (entry.bodyHtml !== null) addHtmlEmbedAssetIds(entry.bodyHtml, ids);
  // Featured image (2026-10-05): a gated post's header image is gated with it, same as a body image.
  if (entry.featuredMediaId) ids.add(entry.featuredMediaId);
  const widgets = collectPlacedWidgetMediaKeys({ bodyJson: entry.bodyJson, bodyHtml: entry.bodyHtml, savedWidgets });
  for (const key of widgets.keys) ids.add(key);
  return { ids, readable: READABLE_BODY_FORMATS.has(entry.bodyFormat) && widgets.readable };
}

/**
 * Whether this entry's own gating is still a live statement about who may read its media.
 *
 * A PUBLISHED, non-trashed entry always is. A non-published one counts only when it is GATED —
 * the 2026-09-05 fix for "unpublishing a gated post releases its media."
 *
 * The pre-existing rule was `status === "published"` alone, defended for a never-published draft:
 * a draft's content is not public any other way, so excluding it opens no leak. That reasoning does
 * not survive the takedown case. A members-only post that was live and is then reverted to draft
 * has an asset URL its former readers already know; dropping it from this scan flipped that asset
 * from `private, no-store` to `public, max-age=31536000, immutable` — the takedown not only failed,
 * it handed the "removed" bytes to a shared CDN for a year.
 *
 * Keeping a GATED draft as a referrer costs nothing the old rule protected. The admin composer,
 * which `MediaRenditionRouteDeps`'s own doc cites as the reason drafts stay reachable, does not use
 * this route at all — `apps/admin/src/lib/media-image-extension.tsx` resolves editor previews
 * through `api.mediaOriginalUrl(assetId)`, the AUTHENTICATED admin route, precisely because "the
 * editor is itself an authenticated admin surface, unlike the public render path." A PUBLIC draft
 * is still skipped, so a freshly uploaded or draft-only public asset stays reachable exactly as
 * before.
 *
 * TRASHED entries stay excluded, unchanged: `a5c9bac8` (same day) established that a trashed post's
 * stale reference must not gate an asset, and this pass does not reopen that decision.
 */
function isLiveReferrerCandidate(entry: PostRecord): boolean {
  if (isTrashed(entry)) return false;
  return entry.status === "published" || isGatedEntry(entry);
}

/** Index each live entry once per workspace snapshot, sharing one access record across all
 * aliases so a post mentioned by id and slug cannot be double-counted. Unreadable gated bodies
 * remain fail-closed for assets they do not explicitly reference. */
function indexEntryAssets(index: AssetReferenceIndex, entry: PostRecord, savedWidgets?: ReadonlyMap<string, Record<string, unknown>>): void {
  if (!isLiveReferrerCandidate(entry)) return;
  const scan = scanEntryAssets(entry, savedWidgets);
  const access = { memberAccessJson: entry.memberAccessJson };
  for (const key of scan.ids) {
    let references = index.byAsset.get(key);
    if (!references) { references = new Set(); index.byAsset.set(key, references); }
    references.add(access);
  }
  if (!scan.readable && isGatedEntry(entry)) index.opaqueGated.add(access);
}

/**
 * Indexes every live entry (post OR page, `"doc"` OR `"html"`) by the assets it embeds — the derivation
 * this route uses in place of a hand-maintained asset->entry foreign key. There is no such column
 * anywhere in this codebase (`MediaRecord`, `@jini-ai/cms/media`, carries no post/owner reference at
 * all); deriving the relationship from the one place it's actually authored (an entry's own body) is
 * the same choice `resolveMediaAssetMetadataForRender` (`pages.ts`) already made for the unrelated
 * width/height/class override lookup, rather than adding a second, independently-writable copy of
 * the same fact.
 *
 * `postRepo.list` needs no `kind` handling: it is kind-BLIND by contract and by both adapters
 * (`repo.sqlite.ts:98` selects on `workspaceId` alone), so Pages have always come back from it
 * alongside posts. The axis that actually hid content from this scan was `bodyFormat`, not `kind`.
 *
 * @complexity O(p + r) over entries p and references r, once per workspace snapshot (no
 * additional I/O per entry) — the same `postRepo.list` + linear scan shape `buildSitemap`'s
 * `computeSitemapEntries` and `pages.ts`'s `filterVisiblePosts` already use at this codebase's
 * disclosed single-workspace scale.
 */
async function buildAssetReferenceIndex(
  deps: Pick<MediaRenditionRouteDeps, "postRepo" | "workspaceId" | "entryRepo">
): Promise<AssetReferenceIndex> {
  const entries = await deps.postRepo.list({ workspaceId: deps.workspaceId });
  const savedWidgets = await loadSavedWidgetConfigs(deps, entries);
  const index: AssetReferenceIndex = { byAsset: new Map(), opaqueGated: new Set() };
  for (const entry of entries) indexEntryAssets(index, entry, savedWidgets);
  return index;
}

/** One shared reverse index per workspace per sixty seconds, invalidated by post/widget writes.
 * A cold/expired workspace rebuild lists posts once; distinct asset misses only query the index.
 * Failed reads are not retained. Session checks below still run for every gated request.
 * @complexity O(p + r) per workspace refresh; no source bodies retained in the cache. */
async function cachedReferenceIndex(deps: MediaRenditionRouteDeps): Promise<AssetReferenceIndex> {
  const cache = getMediaAccessEvidenceCache({ postRepo: deps.postRepo, entryRepo: deps.entryRepo });
  const key = deps.workspaceId;
  const now = deps.clock.nowMs();
  const cached = cache.get(key);
  if (cached && cached.expiresAt > now) return cached.value;
  const value = buildAssetReferenceIndex(deps);
  cache.set(key, { expiresAt: now + 60_000, value });
  try { return await value; }
  catch (error) {
    if (cache.get(key)?.value === value) cache.delete(key);
    throw error;
  }
}

/** Alias lookups share a record Set: unreadable referrers are not also counted as opaque gates.
 * @complexity O(a + r + o), aliases a, matching references r and opaque gated entries o; no I/O. */
async function cachedAssetReferences(deps: MediaRenditionRouteDeps, aliases: ReadonlySet<string>): Promise<AssetReferenceScan> {
  const index = await cachedReferenceIndex(deps);
  const referencing = new Set<Pick<PostRecord, "memberAccessJson">>();
  for (const alias of aliases) {
    for (const access of index.byAsset.get(alias) ?? []) referencing.add(access);
  }
  return { referencing: [...referencing], opaqueGated: [...index.opaqueGated].filter(access => !referencing.has(access)) };
}

type SavedWidgetRow = Awaited<ReturnType<NonNullable<MediaRenditionRouteDeps["entryRepo"]>["listByWorkspace"]>>[number];

/** Indexes one saved widget's config under both its id and its slug, when it is live and active. */
function addActiveWidgetConfig(savedWidgets: Map<string, Record<string, unknown>>, row: SavedWidgetRow): void {
  if ((row as typeof row & { deletedAt?: string | null }).deletedAt != null) return;
  try {
    const payload = parseWidgetInstancePayload({ fieldsJson: row.fieldsJson });
    if (payload.status !== 'active') return;
    savedWidgets.set(row.id, payload.config);
    savedWidgets.set(row.slug, payload.config);
  } catch { /* Malformed widgets do not render; they cannot serve an asset. */ }
}

/** Saved widget configs (by id and slug), loaded only when an entry repo exists AND some live
 *  entry places a widget whose media this scan cannot read from the entry body alone; otherwise
 *  `undefined`, so {@link scanEntryAssets} never pays for the widget listing.
 *  @complexity O(p) over entries plus O(w) over the workspace's saved widgets. */
async function loadSavedWidgetConfigs(
  deps: Pick<MediaRenditionRouteDeps, "workspaceId" | "entryRepo">,
  entries: readonly PostRecord[]
): Promise<Map<string, Record<string, unknown>> | undefined> {
  const needsWidgets = entries.some(entry => isLiveReferrerCandidate(entry) && !collectPlacedWidgetMediaKeys({ bodyJson: entry.bodyJson, bodyHtml: entry.bodyHtml }).readable);
  if (!deps.entryRepo || !needsWidgets) return undefined;
  const savedWidgets = new Map<string, Record<string, unknown>>();
  for (const row of await deps.entryRepo.listByWorkspace({ workspaceId: deps.workspaceId }, { type: 'widget' })) addActiveWidgetConfig(savedWidgets, row);
  return savedWidgets;
}

/** {@link resolveAssetAliases}'s result: the full alias set to gate on, plus the resolved record
 *  itself (or `null` for an unknown identifier). The rendition writer also uses the record for
 *  its source guard and validator without another lookup. */
interface AssetAliasResolution {
  readonly aliases: ReadonlySet<string>;
  readonly media: MediaRecord | null;
}

/**
 * Every spelling of the SAME asset that could appear either in a request URL or in an entry's
 * authored body — its opaque `id`, its CURRENT editable `slug` (2026-09-07 fix for the audit's
 * claim #2), and every slug it used to have before a rename (`listRetiredSlugs`, readable-slugs
 * plan S2a/S2b).
 *
 * THE BUG THIS CLOSES (id/slug half): both public routes here gate on the RAW `:assetId` path
 * segment, while the byte lookups they guard (`resolveMediaRendition`, `resolveMediaOriginalBlob`)
 * both went through `findMediaByIdOrSlug` the moment media gained an editable slug. So the two
 * halves keyed off different identifiers, and the reference scan simply missed — in BOTH directions:
 *   - a members-only entry embedding an asset BY ID was served anonymously through `/m/{slug}/…`
 *     (no entry body contains the slug, so `gating.length === 0` and the route allowed);
 *   - an entry embedding BY SLUG was served anonymously through `/m/{id}/…`, which is precisely
 *     the URL `render.ts`'s `renderImageTag`/`renderVideoTag` emit for it (they always template the
 *     RESOLVED record's `id`), i.e. the spelling every visitor's browser actually requests.
 * Resolving the request's identifier to a record FIRST, then gating on the full alias set, is what
 * makes the gate and the lookup agree by construction rather than by two call sites happening to
 * spell the same asset the same way.
 *
 * THE SAME GAP REOPENS ON RENAME (retired-slug half, S2b): once a slug can be renamed and an old
 * slug URL still resolves (`findBySlug`'s history fallback), an entry authored against the OLD
 * spelling is a real, live reference — dropping it from the alias set the moment the slug changes
 * would silently un-gate that entry's media, the same failure shape as the id/slug split above.
 *
 * Falls back to the raw value when nothing resolves: that request is a guaranteed 404 from the byte
 * lookup anyway, and inventing an empty alias set here would make an unknown asset take the
 * "nothing references it, allow" path for no benefit.
 *
 * @complexity O(1) — the two indexed lookups `findMediaByIdOrSlug` already performs, plus one more
 * indexed lookup for `listRetiredSlugs`.
 */
async function resolveAssetAliases(
  deps: Pick<MediaRenditionRouteDeps, "mediaRepo" | "workspaceId">,
  idOrSlug: string
): Promise<AssetAliasResolution> {
  const media = await findMediaByIdOrSlug({
    deps: { mediaRepo: deps.mediaRepo },
    input: { workspaceId: deps.workspaceId, idOrSlug },
  });
  if (!media) {
    return { aliases: new Set([idOrSlug]), media: null };
  }
  const retiredSlugs = await deps.mediaRepo.listRetiredSlugs({ workspaceId: deps.workspaceId, mediaId: media.id });
  const aliases = new Set([media.id, ...retiredSlugs]);
  if (media.slug) aliases.add(media.slug);
  return { aliases, media };
}


/** No cookie-parser middleware is mounted. The shared request-cookie reader replaces the
 * route-local copy and handles direct tests whose requests carry no headers bag. */

/** Route-local duplicate of `pages.ts`'s own `createMemberAccessResolver` — built per request from
 *  `deps`, never a module-level singleton, same "tests inject their own in-memory repos per
 *  composition" reason that file's own doc gives. */
function createMemberAccessResolver(
  deps: Pick<MediaRenditionRouteDeps, "memberSessionRepo" | "memberSubscriptionRepo" | "memberTierRepo">
): MemberAccessResolver {
  return new DefaultMemberAccessResolver({
    sessions: deps.memberSessionRepo,
    subscriptions: deps.memberSubscriptionRepo,
    tiers: deps.memberTierRepo,
  });
}

/**
 * Whether `assetId` is gated at all, and — if it is — whether THIS request's caller may read it.
 *
 * `gated: false` ("no need to consult who's asking, always allow") covers TWO cases: no live entry
 * references this asset and none was unreadable (freshly uploaded, only in a public draft, or a
 * legacy/unreferenced asset — nothing to gate on), and an asset referenced by at least one
 * `visibility: "public"` entry.
 * The second case matters for mixed-visibility embeds: `decidePublicAccess` (`access-resolver.ts`)
 * never consults `context` at all, so if even ONE referencing post is public, the outcome is
 * identical for every visitor regardless of session — exactly the property that makes the
 * route's ordinary long-lived, shared-cacheable response safe, and checking it FIRST also skips
 * the session/subscription/tier repo round trip entirely for the common "referenced by an ordinary
 * public post" case.
 *
 * `gated: true` (every referencing post requires SOME entitlement check) allows if the caller may
 * read ANY ONE of them — most-permissive-of-referrers when the same asset is embedded in posts of
 * mixed gated visibility (e.g. both `members` and `paid`). That is a deliberate choice, not an
 * oversight: if a post the caller CAN read embeds this exact asset, the bytes are already reachable
 * to them through that post's own rendered page, so denying the direct asset URL would only break
 * that post's own display for an entitled visitor without hiding anything from anyone the gate was
 * meant to stop.
 *
 * THE UNREADABLE-BODY FALLBACK (2026-09-05) is what stops this default from failing open again.
 * "No referrer found" is only a safe reason to allow while the scan can actually READ every entry
 * it looked at — that assumption is precisely what broke here: `bodyHtml` was never scanned, so
 * every gated `"html"` Page reported "no reference" and every one of its embeds was served to
 * anyone. So when {@link scanEntriesForAsset} reports a live, GATED entry whose body format this
 * scan does not know how to read at all ({@link READABLE_BODY_FORMATS}), those entries become the
 * gating set instead of the empty one, and the caller must satisfy at least one of them. A future
 * third body format therefore denies anonymous access to gated content's media until this scan
 * learns to read it, rather than silently publishing it — which is precisely how this defect
 * arrived, one content type at a time.
 *
 * Deliberately NOT a blanket "deny whenever nothing references this asset": that would be safe only
 * if entry bodies were the sole legitimate producer of a `/m/` URL, and they are not. Measured
 * counter-examples on this route: `Jini/packages/cms/src/seo/seo.ts`'s `resolveShareImages` turns `settings.defaultOgImage`
 * and an entry's own `seoExtJson.ogImage`/`twitterImage` into `/m/{assetId}/…` URLs fetched by
 * anonymous social crawlers, and `resolver-service.ts`'s media resolver resolves a `"media"` marker
 * authored in a THEME template (documented in the theme-authoring guide; zero occurrences across
 * the shipped themes today, but the grammar allows it). Neither is visible to `postRepo`, so a
 * blanket flip would 404 a site's share cards and any theme-authored media. Those need explicit
 * allow paths before the default can flip the rest of the way — see this route's handoff.
 *
 * @complexity O(p) — see {@link scanEntriesForAsset}; `decide` itself is pure O(1) per gating entry.
 */
async function resolveMediaAccessDecision(
  deps: MediaRenditionRouteDeps,
  req: Request,
  assetId: string
): Promise<{ gated: boolean; allowed: boolean; record: MediaRecord | null }> {
  const { aliases, media } = await resolveAssetAliases(deps, assetId);
  // Documents and submitted files are private even when their id/slug is guessed or embedded in published content.
  if (media?.kind === "document" || media?.source.private) return { gated: true, allowed: false, record: media };
  const { referencing, opaqueGated } = await cachedAssetReferences(deps, aliases);
  if (referencing.some((entry) => !isGatedEntry(entry))) {
    return { gated: false, allowed: true, record: media };
  }

  // A real referrer always wins over the fallback: once the scan has actually FOUND the entries
  // that embed this asset, an unrelated unreadable entry has no say in who may read it.
  const gating = referencing.length > 0 ? referencing : opaqueGated;
  if (gating.length === 0) {
    return { gated: false, allowed: true, record: media };
  }

  const resolver = createMemberAccessResolver(deps);
  const context = await resolver.resolveContext({
    workspaceId: deps.workspaceId,
    sessionToken: readRequestCookie({ request: req, name: MEMBER_SESSION_COOKIE }),
    nowIso: new Date().toISOString(),
  });
  const allowed = gating.some(
    (entry) => resolver.decide({ access: resolvePostMemberAccess(entry.memberAccessJson), context }).allowed
  );
  return { gated: true, allowed, record: media };
}

/**
 * Reads and coerces the `:assetId`/`:transformSpec` route params to strings, matching Express's
 * always-string-or-undefined param shape. Isolated purely to keep the two nullish-coalescing
 * defaults out of the handler's own branch count (each `??` costs a cyclomatic-complexity point
 * just like a default-parameter assignment does) — no behavior beyond a straight string read.
 * {@link registerMediaOriginalVideoRoute} reads only `assetId` through it, so both routes share one fallback.
 */
function readRenditionRouteParams(req: Request): { assetId: string; transformSpec: string } {
  return {
    assetId: String(req.params.assetId ?? ""),
    transformSpec: String(req.params.transformSpec ?? ""),
  };
}

/** Source and stored rendition identities identify the deterministic served representation,
 * including SVG sanitization, without reloading bytes for a conditional request. */
async function publicRenditionTag({ deps, media, transformName, version }: {
  deps: MediaRenditionRouteDeps; media: MediaRecord | null; transformName: string; version: number;
}): Promise<string | null> {
  if (!media || media.status !== 'active') return null;
  const input = { workspaceId: deps.workspaceId, assetId: media.id, transformName, version };
  if (!await deps.transformDefinitionRepo.findByNameVersion({ workspaceId: deps.workspaceId, name: transformName, version })) return null;
  const stored = await deps.assetRenditionRepo.findOne(input);
  if (!stored && media.source.contentType !== 'image/svg+xml') return null;
  const identity = JSON.stringify([media.source.sha256, transformName, version, stored?.storageKey ?? 'svg']);
  return `"${createHash('sha256').update(identity).digest('hex')}"`;
}

/** GET validators use weak comparison and accept a list or wildcard, as If-None-Match requires. */
function matchesRenditionTag(req: Request, etag: string): boolean {
  return String(req.headers['if-none-match'] ?? '').split(',').some(value => {
    const candidate = value.trim();
    return candidate === '*' || candidate.replace(/^W\//, '') === etag.replace(/^W\//, '');
  });
}

/** Access is resolved before validators: a gated request can never reuse public evidence. */
async function sendNotModifiedRendition({ deps, req, res, access, transformName, version }: {
  deps: MediaRenditionRouteDeps; req: Request; res: Response;
  access: { gated: boolean; record: MediaRecord | null }; transformName: string; version: number;
}): Promise<boolean> {
  if (access.gated || !req.headers['if-none-match']) return false;
  const etag = await publicRenditionTag({ deps, media: access.record, transformName, version });
  if (!etag || !matchesRenditionTag(req, etag)) return false;
  res.status(304).set(CACHE_CONTROL_HEADER, REVALIDATING_PUBLIC).set('ETag', etag).end();
  return true;
}

/**
 * Resolves the access gate, fetches (or generates) the rendition, and writes the final HTTP
 * response — every outcome branch {@link registerMediaRenditionRoute}'s handler previously held
 * inline. Extracted verbatim (pure extract-method: same checks, same order, same early returns)
 * so the route handler's own cognitive-complexity count only has to account for the malformed-URL
 * guard above it, not this function's outcome fan-out too.
 *
 * @complexity O(1) plus {@link resolveMediaAccessDecision}'s own O(p) cost over the workspace's
 * published posts.
 */
async function sendMediaRenditionResult(
  deps: MediaRenditionRouteDeps,
  req: Request,
  res: Response,
  assetId: string,
  transformName: string,
  version: number
): Promise<void> {
  try {
    const access = await resolveMediaAccessDecision(deps, req, assetId);
    if (!access.allowed) {
      // ADR-030 §4 gate (2026-09-03 sweep): the SAME "rendition not found" 404 an unknown
      // assetId already gets below — a gated asset must be indistinguishable from one that
      // doesn't exist, matching `9bf661e9`'s content-API fix. `private, no-store`, never the
      // short-TTL `public` header the plain not-found branch below uses: this outcome depends on
      // the caller's own session cookie, so a shared/CDN cache must never replay it to a
      // DIFFERENT visitor (see `MediaRenditionRouteDeps`'s own doc).
      sendMediaNotFound(res, "rendition not found");
      return;
    }

    if (await sendNotModifiedRendition({ deps, req, res, access, transformName, version })) return;

    const result = await resolveMediaRendition({
      deps: {
        mediaRepo: deps.mediaRepo,
        blobRepo: deps.assetBlobRepo,
        // The shared service assumes immutable sources. This host's explicit replace
        // command needs an atomic source guard on late preview writes.
        renditionRepo: guardMediaRenditionRepo({ mediaRepo: deps.mediaRepo, renditionRepo: deps.assetRenditionRepo, media: access.record }),
        transformRepo: deps.transformDefinitionRepo,
        blobStore: deps.blobStore,
        imageTransformer: deps.imageTransformer,
        clock: deps.clock,
        idGen: deps.idGen,
      },
      input: { workspaceId: deps.workspaceId, assetId, transformName, version },
    });

    if (result.outcome === "gone") {
      // ADR-027 §4: a purged/gone asset is `410 no-store`. See
      // `rendition-service.ts`'s doc comment for the disclosed
      // trashed-stands-in-for-purged mapping this build uses.
      res.status(410).set(CACHE_CONTROL_HEADER, "no-store").end();
      return;
    }

    if (result.outcome === "not-found") {
      // Not-yet-generated-and-not-generatable-anonymously (or a wholly unknown assetId/transform).
      //
      // `private, no-store`, matching the gate-denied 404 above BYTE FOR BYTE (2026-09-05 fix).
      // This branch used to send `public, max-age=60`, which made the two 404s trivially
      // distinguishable on a header alone: any caller could ask "does this assetId exist and is it
      // gated?" and read the answer off `Cache-Control`, defeating the indistinguishability the
      // gate branch's own comment says it is there to provide. The two headers can only be
      // reconciled downwards — the gate's outcome depends on the caller's session cookie, so it can
      // never be given a shared-cacheable header. The cost is the 60s negative cache on a
      // not-found rendition, which is the correct thing to trade for closing the oracle.
      sendMediaNotFound(res, "rendition not found");
      return;
    }

    if (result.contentType === "image/svg+xml") {
      // Vector passthroughs do not receive the raster pipeline's re-encode protection.
      res.set("X-Content-Type-Options", "nosniff");
      res.set("Content-Security-Policy", SVG_CONTENT_SECURITY_POLICY);
    }
    // Prefer source/rendition identities; legacy sources without stored evidence still hash bytes.
    if (!access.gated) {
      const identity = `${access.record?.source.sha256}:${transformName}:${version}:`;
      const etag = await publicRenditionTag({ deps, media: access.record, transformName, version });
      res.set("ETag", etag ?? `"${createHash("sha256").update(identity).update(result.bytes).digest("hex")}"`);
    }
    res
      .status(200)
      .set(CACHE_CONTROL_HEADER, renditionCacheControl({ access }))
      .set("Content-Type", result.contentType)
      .send(Buffer.from(result.bytes));
  } catch (err) {
    sendRenditionFailure(res, err);
  }
}

/** The `Cache-Control` for an ALLOWED 200 rendition. @complexity O(1). */
function renditionCacheControl({ access }: { access: { gated: boolean } }, _optional: Record<string, never> = {}): string {
  // `access.gated`: a gated asset's ALLOW outcome is per-viewer (it depended on this
  // request's session cookie), so it must never be handed the ungated,
  // shared/CDN-facing headers below — the next, possibly unentitled, visitor to hit a
  // public/shared cache would be served this same cached response.
  //
  // Ids, matching versions and editable/reusable slugs all serve the live source. Header
  // selection adds no reads; access evidence is refreshed within sixty seconds.
  if (access.gated) return PRIVATE_NO_STORE;
  return REVALIDATING_PUBLIC;
}

/** Maps a failure while resolving/generating a rendition to its HTTP response. @complexity O(1). */
function sendRenditionFailure(res: Response, err: unknown): void {
  if (err instanceof ImageTransformUnavailableError) {
    // The transform is valid and generation was allowed, but the real pixel-operation
    // adapter can't run in this environment (disclosed `sharp`-not-installed blocker — see
    // `image-transformer.sharp.ts`). Service-unavailable, not a routine 404/410/500.
    res.status(503).set(CACHE_CONTROL_HEADER, "no-store").json({ error: err.message });
    return;
  }
  if (err instanceof ImageSourceCorruptError) {
    // The asset and transform are both valid, but the STORED bytes cannot actually be
    // decoded/re-encoded by the pixel pipeline (a corrupt or codec-rejected blob — see that
    // error's own doc for how bytes can pass this package's upload allowlist and its
    // magic-byte sniff while still failing here). A data condition on this one asset, not a
    // server fault — 422, never the opaque catch-all 500, and never cached (a future fix to
    // the stored blob must not stay masked by a long-lived negative cache entry).
    res.status(422).set(CACHE_CONTROL_HEADER, "no-store").json({ error: "source image could not be processed" });
    return;
  }
  res.status(500).json({ error: "internal error" });
}

export const registerMediaRenditionRoute: MediaRenditionRouteRegistrar = (app, deps) => {
  app.get("/m/:assetId/:transformSpec/:filename", async (req, res) => {
    const { assetId, transformSpec } = readRenditionRouteParams(req);
    const parsed = resolveTransformSpec(assetId, transformSpec);

    if ("errorMessage" in parsed) {
      res.status(400).json({ error: parsed.errorMessage });
      return;
    }

    const { transformName, version } = parsed;
    await sendMediaRenditionResult(deps, req, res, assetId, transformName, version);
  });
};

/**
 * Public, unauthenticated `GET /m/{assetId}/original` — the video/embed capability's real
 * render-path fix (2026-08-24; see the video-embed handoff report for the full investigation).
 *
 * WHY THIS EXISTS RATHER THAN A NEW TRANSFORM: {@link registerMediaRenditionRoute} above always
 * resolves a request through `resolveMediaRendition` (`rendition-service.ts`), which — for any
 * not-yet-generated rendition — calls `imageTransformer.transform()` with the transform
 * definition's `params.format`. `TransformFormat` (`transform-types.ts`) is a closed
 * `"jpeg" | "png" | "webp" | "gif"` union with no video member, and the one core transform this
 * host registers (`media/bootstrap.ts`'s `"public"`, `format: "webp"`) is a `sharp` re-encode —
 * pointing a `<video>` tag's `src` at that same URL would hand raw video bytes to `sharp`, which
 * cannot process them. Extending `TransformFormat`/`imageTransformer` to understand video would
 * mean teaching the ADR-027 §4 "frozen" contract a passthrough format it was never designed for,
 * for a media kind (video) that has no resize/re-encode step to apply in the first place — video
 * is served byte-identical to how it was uploaded, same as every image's own `"original"`
 * passthrough rendition row already is, just without a transform-definition lookup gating it.
 *
 * So this route bypasses the transform system entirely: {@link resolveMediaOriginalBlob} +
 * {@link sendMediaOriginalResponse} are the SAME functions `routes/admin/media/original.ts`'s
 * authenticated admin-preview route already uses (content-type sniffed fresh from bytes, SVG sanitized, HTML
 * forced to `application/octet-stream` + `attachment`, `nosniff`/CSP/CORP headers, `Range` support
 * for video seeking) — reused, not reimplemented, so the two routes' security posture can't drift
 * apart. The one behavioral difference from the admin route: no `requireAdminSession`/`media.read`
 * gate, since this URL is meant to sit in a `<video src>` on a public page.
 *
 * Video/audio and sanitized SVG share this original-byte path. Raster images still use
 * {@link registerMediaRenditionRoute}'s re-encode. SVG is sanitized before serving even for
 * legacy blobs; unknown bytes and HTML stay 404. Range handling and the member gate keep
 * their existing owners.
 *
 * ADR-030 §4 gate (2026-09-03 sweep): {@link resolveMediaAccessDecision} runs before the blob is
 * even fetched, same as {@link registerMediaRenditionRoute} above — a denied caller gets the SAME
 * "video rendition not found" 404 the not-a-video branch below already uses, so a gated video is
 * indistinguishable from one that was never a video at all. No cache-header special-casing is
 * needed on the ALLOW path here: {@link sendMediaOriginalResponse} already sends `private, no-store`
 * unconditionally for every successful response, gated or not.
 *
 * @complexity O(1) plus the byte copy for a partial range (inherited from
 * {@link sendMediaOriginalResponse}), plus {@link resolveMediaAccessDecision}'s own O(p) cost.
 */
export const registerMediaOriginalVideoRoute: MediaRenditionRouteRegistrar = (app, deps) => {
  // Both URL generations use the same gate, byte sniffing and response headers. The suffix is
  // for static-host MIME inference; it never selects the live response's Content-Type.
  app.get(["/m/:assetId/original", "/m/:assetId/original.:ext"], async (req, res) => {
    const { assetId } = readRenditionRouteParams(req);

    try {
      const access = await resolveMediaAccessDecision(deps, req, assetId);
      if (!access.allowed) {
        sendMediaNotFound(res, "video rendition not found");
        return;
      }

      // Unknown-asset 404s through the SAME `sendMediaNotFound` writer as the gate-denied branch
      // just above (2026-09-23 oracle close, S2b) — `resolveMediaOriginalBlob`'s own default 404
      // (a bare `{error: "media '<x>' was not found"}`, no Cache-Control at all) stays reserved for
      // its authenticated admin caller; see that function's `onNotFound` doc.
      const resolved = await resolveMediaOriginalBlob(deps, res, { workspaceId: deps.workspaceId, mediaId: assetId }, (r) =>
        sendMediaNotFound(r, "video rendition not found")
      );
      if (!resolved) {
        return;
      }
      const { blob } = resolved;

      const sourceBytes = await deps.blobStore.get({ storageKey: blob.storageKey });
      const sniffed = sniffContentType({ bytes: sourceBytes });
      if (sniffed !== "image/svg+xml" && !sniffed.startsWith("video/") && !sniffed.startsWith("audio/")) {
        // Neither recognized video/audio nor SVG (or an unrecognized/corrupt asset).
        // everything else's public URL is `registerMediaRenditionRoute`'s transform-backed one.
        // `private, no-store` for the same reason the rendition route's not-found branch uses it
        // (2026-09-05): it must be byte-identical to this route's own gate-denied 404 just above,
        // or the header alone tells an anonymous caller which of the two they hit.
        sendMediaNotFound(res, "video rendition not found");
        return;
      }

      // Reuse ingest sanitization for legacy blobs before applying byte ranges.
      const bytes = sniffed === "image/svg+xml" ? await sanitizeSvg({ bytes: sourceBytes }) : sourceBytes;
      const totalLength = bytes.byteLength;
      const range = parseRangeHeader({ header: req.get("range"), totalLength });
      sendMediaOriginalResponse(res, bytes, range, {
        safe: sniffed,
        forceDownload: DISALLOWED_INLINE_CONTENT_TYPES.has(sniffed),
      });
    } catch {
      res.status(500).json({ error: "internal error" });
    }
  });
};

import type { Express } from "express";
import { nowIso } from "@jini-ai/core/primitives";

import { resolveMemberSession } from "#src/features/members/access-resolver";
import type { PublicPostRecord as PostRecord } from "#src/features/post/post";
import { readRequestCookie } from "#src/server/http/request-cookie";
import type { RouteDeps } from "#src/server/routes/types";
import { MEMBER_SESSION_COOKIE } from "../../http/members.js";
import { serveVirtualPage } from "./pages.js";

const CODE_REQUEST_VIEW = "code-request";

/**
 * @file Core's member sign-in pages: `/signin` (password, emailed code, emailed link), `/forgot-
 * password`, `/reset-password` (link from the reset email) and `/account` (set or change a
 * password, connect or unlink a login provider, sign out). Owner 2026-10-24: the public "Sign in"
 * is for members with passwords; no minimum length, ever.
 *
 * Login providers (Google login U1): core names no provider. The script lists the enabled,
 * configured ones from `GET …/login-providers` into the empty `data-member-providers` and
 * `data-member-identity-list` slots, so with none enabled nothing extra shows.
 *
 * Each page is a Page built in memory and rendered by `serveVirtualPage`, so it wears the active
 * theme exactly like an authored Page. Registered before `GET /:slug`, so these paths win over a
 * theme's own placeholder `signin.html` mock (tovu-theme). The markup is inert: every view
 * starts `hidden` and `http/site/member-auth-script.ts` (injected by `finalizePublicPageHtml` on
 * any page with `data-member-page`) shows one, wires the forms and talks to the member API. Field
 * classes are the themes' own auth hooks (`.field`, `.btn`), with that script's `:where()` fallback.
 */

/** One labelled input. `tip` adds an ⓘ button beside the label that opens `tip.text` on tap. */
function field(input: { id: string; label: string; name: string; type: string; autocomplete: string; extra?: string;
  tip?: string }): string {
  const tipId = `${input.id}-tip`;
  const label = `<label for="${input.id}">${input.label}</label>`;
  const head = input.tip ? `<span class="member-label-row">${label}${tipButton(tipId)}</span>${tipText(tipId, input.tip)}` : label;
  const control = `<input id="${input.id}" name="${input.name}" type="${input.type}" ` +
    `autocomplete="${input.autocomplete}"${input.type === "password" ? ' spellcheck="false"' : ""}${input.extra ?? ""}>`;
  const body = input.type === "password" ? `<span class="member-password">${control}${passwordToggle(input)}</span>` : control;
  return `<div class="field member-field">${head}${body}</div>`;
}

/** Public-page counterpart of SecretInput: the changing name carries state, outside the label.
 * The member script toggles the native input; no secret is serialized into this markup.
 * @complexity O(n) in the rendered id and label lengths. */
function passwordToggle({ id, label }: { id: string; label: string }, _optional = {}): string {
  return `<button type="button" class="member-password-toggle" aria-controls="${id}" aria-label="Show ${label}" ` +
    `data-member-password-toggle data-show-label="Show ${label}" data-hide-label="Hide ${label}">` +
    '<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
    '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>' +
    '<path class="member-password-slash" d="M2 2l20 20" hidden/></svg></button>';
}

function tipButton(id: string): string {
  return `<button type="button" class="member-tip" aria-label="More about this" aria-expanded="false" aria-controls="${id}">i</button>`;
}

function tipText(id: string, text: string): string {
  return `<span class="member-tip-text" id="${id}" hidden>${text}</span>`;
}

const messages = '<p class="member-note" data-member-error role="alert" hidden></p><p class="member-note" data-member-ok role="status" hidden></p>';

function form(name: string, inner: string, submit: string, after = ""): string {
  return `<form data-member-form="${name}">${inner}${messages}<div class="member-actions">` +
    `<button type="submit" class="btn btn-solid member-submit">${submit}</button>${after}</div></form>`;
}

function view(name: string, inner: string): string {
  return `<section data-member-view="${name}" hidden>${inner}</section>`;
}

function links(...items: string[]): string {
  return `<p class="member-auth-links">${items.join("")}</p>`;
}

function showButton(target: string, label: string): string {
  return `<button type="button" class="member-link" data-member-show="${target}">${label}</button>`;
}

/** A status line a view opens on; `tabindex` lets the script move focus to it so it is read out. */
function note(html: string): string {
  return `<p class="member-note" tabindex="-1" data-member-focus>${html}</p>`;
}

/** Provider buttons (filled by the script) above the email forms, with an "or" rule under them. */
const PROVIDERS = '<div class="member-providers" data-member-providers hidden><div class="member-provider-list" data-member-provider-list></div>' +
  '<p class="member-or"><span>or use your email</span></p></div>';

/** A start/callback refusal lands on /signin#oidcError=<CODE>; the script says it in words here. */
const OIDC_ERROR = '<p class="member-note member-oidc-error" data-member-oidc-error role="alert" tabindex="-1" hidden></p>';

/** Page templates print the body only (an authored Page brings its own heading), so the h1 is here. */
function page(kind: string, title: string, views: string[], top = ""): { title: string; body: string } {
  return { title, body: `<div class="member-auth" data-member-page="${kind}"><h1>${title}</h1><noscript><p>Turn on JavaScript to use this page.</p></noscript>` +
    `${top}${views.join("")}</div>` };
}

