/**
 * @file ADR-046 Phase 3 (SPEC-031) — composes the boot modules `index.ts` runs through
 * `runBootLifecycle()` (ADR-046 Phase 2). Pulled out of `index.ts` so this composition logic is
 * unit-testable (`index.ts` itself is deliberately never imported by a test — see that file's own
 * header note on why boot-only logic lives there). `index.ts` becomes a thin wrapper: build deps,
 * call `buildBootModules`, run the lifecycle, `listen()`.
 *
 * `logCriticalBootFailures` below (2026-09-06 composition-root fix) was, until this fix, hand-copied
 * verbatim between `index.ts` and `cli/commands/serve.ts` — both files' own comments claimed this
 * class of boot-only logic is "never shared via import," which this very file's existence already
 * contradicted (it has been the shared, imported, `buildBootModules` composition for both boot paths
 * since ADR-046 Phase 3). Both call sites now import this one copy instead.
 */

const noop = async (): Promise<void> => {};

/* eslint-disable no-console */
/** Boot's plain log: token imports and the bundled-plugin warnings below. */
const bootLog = { info: (message: string) => console.info(message), warn: (message: string) => console.warn(message) };
/* eslint-enable no-console */

/** One vendor, one switch (`provider-plugin-link.ts`): after seeding, each agent plugin that is a
 *  provider plugin's face follows that plugin's switch — so a face seeded inactive, or one whose mirror
 *  write failed, is right from this start. A failure is logged; the provider plugins still load. */
async function syncProviderFacesAtBoot(deps: NewsletterRouteDeps): Promise<void> {
  try {
    await syncProviderFaces({
      ports: bindProviderFacePorts({ workspaceRoot: () => deps.agentPluginLayout.forWorkspace(deps.workspaceId).root }),
      providerEnabled: async ({ pluginId }) => (await deps.pluginActivationRepo.getActivation({ workspaceId: deps.workspaceId, pluginId }))?.enabled === true,
    });
  } catch (error) {
    // eslint-disable-next-line no-console
    console.warn(`[bundled-agent-plugins] provider plugin faces could not be synced; the next start retries: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/** "Soon" plugins are locked off (`soon-lock.ts`, owner 2026-11-10): one an older build, a retirement
 *  successor or a missing record left on is switched off as `system:soon-lock`, after seeding and the
 *  face sync so neither can turn it back on. Nothing is uninstalled. A failure is logged; the next start retries. */
async function lockSoonAgentPluginsAtBoot(deps: NewsletterRouteDeps): Promise<void> {
  try {
    const switched = await lockSoonAgentPlugins({ catalog: explicitRootSoonCatalog, activations: explicitRootAgentPluginActivations,
      workspaceRoot: deps.agentPluginLayout.forWorkspace(deps.workspaceId).root });
    if (switched.length === 0) return;
    bootLog.info(`[bundled-agent-plugins] switched off plugins that aren't ready yet: ${switched.join(", ")}`);
    await notifyExternalMcpRosterChanged({ lowered: { pluginIds: switched } });
  } catch (error) {
    bootLog.warn(`[bundled-agent-plugins] plugins that aren't ready yet could not be switched off; the next start retries: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/** The three steps of {@link importAgentPluginTokensAtBoot}, injectable for tests. */
export interface AgentPluginTokenBootSteps {
  /** Plugin ids with a create-site onboarding token waiting in `siteDir`. */
  readonly pendingPluginIds: (siteDir: string) => ReadonlySet<string>;
  readonly applyPending: (siteDir: string) => Promise<void>;
  readonly importFromEnv: (skipPluginIds: ReadonlySet<string>) => Promise<void>;
}

function defaultAgentPluginTokenBootSteps(deps: NewsletterRouteDeps): AgentPluginTokenBootSteps {
  return {
    pendingPluginIds: listPendingAgentPluginTokenIds,
    applyPending: (siteDir) =>
      applyPendingAgentPluginTokens(
        { siteDir, sealer: deps.siteAssistantSecretSealer, importToken: (pluginId, token) => importAgentPluginAccessToken(deps, { pluginId, token }) },
        bootLog,
      ),
    importFromEnv: (skipPluginIds) => importAgentPluginAccessTokensFromEnv(deps, process.env, bootLog, { skipPluginIds }),
  };
}

/**
 * After the bundled plugins are seeded (a token needs its plugin installed): connects plugins from
 * tokens typed into create-site onboarding for this site, then from an old env token
 * (`tovuTokenAuth.importFromEnv`, e.g. the retired `TOVU_SUPABASE_MCP_ACCESS_TOKEN`). The onboarding
 * token goes first and the env import skips every plugin that had one: the person chose that token
 * for this site, and an ambient env token (possibly another account's) saved first would make the
 * pending import find the row connected and drop it. Neither overwrites a connection the site
 * already has, and neither can fail boot.
 */
export async function importAgentPluginTokensAtBoot(
  deps: NewsletterRouteDeps,
  options: BuildBootModulesOptions,
  steps: AgentPluginTokenBootSteps = defaultAgentPluginTokenBootSteps(deps),
): Promise<void> {
  let pending: ReadonlySet<string> = new Set();
  if (!options.useMemory) {
    const siteDir = path.dirname(options.defaultContentDbPath());
    pending = steps.pendingPluginIds(siteDir);
    try {
      await steps.applyPending(siteDir);
    } catch (err) {
      bootLog.warn(`[agent-plugins] could not apply this site's pending access tokens: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  await steps.importFromEnv(pending);
}

function logBundledPluginRetirements(
  { retirements }: { retirements: Awaited<ReturnType<typeof seedBundledAgentPlugins>>["retirements"] },
  _options = {},
): void {
  // Retired bundled plugins (`features/agent-plugins/retire-bundled.ts`). A retirement that
  // happened is logged once — the next boot finds nothing and says nothing — and one case is a
  // warning even though it succeeded: the retired plugin was on, and its successor stayed off
  // because an operator had turned it off.
  for (const retirement of retirements) {
    if (retirement.status === "failed") {
      // eslint-disable-next-line no-console
      console.warn(`[bundled-agent-plugins] retired '${retirement.pluginId}' could not be removed: ${retirement.reason}`);
    }
    if (retirement.status === "retired") {
      // eslint-disable-next-line no-console
      // A parked plugin (formspree, 2026-11-10) retires into nothing; Jini reports its successor as "".
      console.info(retirement.successorId === ""
        ? `[bundled-agent-plugins] retired '${retirement.pluginId}' (no successor)`
        : `[bundled-agent-plugins] retired '${retirement.pluginId}' (moved into '${retirement.successorId}'; successor: ${retirement.successor})`);
      if (retirement.successor === "left-disabled-by-operator") {
        // eslint-disable-next-line no-console
        console.warn(
          `[bundled-agent-plugins] '${retirement.pluginId}' was enabled but its successor '${retirement.successorId}' is turned off by an operator and was left off — turn it on in Agent Plugins to keep that capability`,
        );
      }
    }
  }
}

/** What {@link bundledAgentPluginBootWarnings} compares; plain plugin-id lists. */
export interface BundledAgentPluginBootState {
  /** The bundled folder this boot seeded from, for the message. */
  readonly sourceRoot: string;
  /** Every plugin folder the seeder found there, seeded or failed. */
  readonly seededIds: readonly string[];
  /** Plugin ids this build selects from Jini packages (`SELECTED_AGENT_PLUGIN_PACKAGES`). */
  readonly selectedIds: readonly string[];
  /** Plugin ids this workspace's activation records turn on. */
  readonly enabledIds: readonly string[];
  /** Plugin ids with an installed package in this workspace. */
  readonly installedIds: readonly string[];
}

/**
 * Production boot never refuses over a missing bundled plugin (plugins plan v2 §3.4; the build is
 * where a broken composition fails). It says what is missing instead:
 * - the bundled folder seeded nothing although this build selects plugin packages (a stale or partial
 *   build output, or a development root that was never composed);
 * - an enabled plugin has neither a bundled source nor an installed package, so its switch is on with
 *   nothing behind it (a package left the selection, or a build dropped it).
 * @returns One log line per finding, in input order; empty when everything is present.
 * @complexity O(s + i + e) for seeded, installed and enabled ids.
 */
export function bundledAgentPluginBootWarnings(state: BundledAgentPluginBootState, _optional = {}): string[] {
  const warnings: string[] = [];
  if (state.seededIds.length === 0 && state.selectedIds.length > 0) {
    warnings.push(`[bundled-agent-plugins] this build selects ${state.selectedIds.length} plugin packages (${state.selectedIds.join(", ")}) but no bundled plugin was found in ${state.sourceRoot}; rebuild Tovu (in development: npm run agent-plugins:compose, then restart)`);
  }
  const present = new Set([...state.seededIds, ...state.installedIds]);
  for (const pluginId of state.enabledIds.filter((id) => !present.has(id))) {
    warnings.push(`[bundled-agent-plugins] '${pluginId}' is turned on, but this build does not ship it and it is not installed; add its package to the build, or turn it off in Agent Plugins`);
  }
  return warnings;
}

/** Reads this workspace's enabled and installed plugin ids. A read failure only costs the
 *  enabled-plugin check, so it is logged and reported as "nothing enabled".
 *  @complexity O(p) in recorded plus installed plugins. */
async function readEnabledAndInstalledIds(deps: NewsletterRouteDeps): Promise<Pick<BundledAgentPluginBootState, "enabledIds" | "installedIds">> {
  try {
    const workspaceRoot = deps.agentPluginLayout.forWorkspace(deps.workspaceId).root;
    const [activations, installed] = await Promise.all([
      explicitRootAgentPluginActivations.readAgentPluginActivations({ workspaceRoot }),
      listInstalledPlugins(workspaceRoot),
    ]);
    const enabledIds = Object.entries(activations.plugins).filter(([, record]) => record.enabled).map(([pluginId]) => pluginId);
    return { enabledIds, installedIds: installed.map((plugin) => plugin.pluginId) };
  } catch (error) {
    bootLog.warn(`[bundled-agent-plugins] could not compare enabled plugins with this build: ${error instanceof Error ? error.message : String(error)}`);
    return { enabledIds: [], installedIds: [] };
  }
}

/** Logs {@link bundledAgentPluginBootWarnings} for this boot's seed result. Never throws. */
async function warnAboutMissingBundledPlugins(
  deps: NewsletterRouteDeps,
  { result }: { result: Awaited<ReturnType<typeof seedBundledAgentPlugins>> },
): Promise<void> {
  const state = {
    sourceRoot: result.sourceRoot,
    seededIds: result.outcomes.map((outcome) => outcome.pluginId),
    selectedIds: [...SELECTED_AGENT_PLUGIN_PACKAGES.keys()],
    ...await readEnabledAndInstalledIds(deps),
  };
  for (const warning of bundledAgentPluginBootWarnings(state)) bootLog.warn(warning);
}

export interface BuildBootModulesOptions {
  useMemory: boolean;
  defaultContentDbPath: () => string;
  /** Test seam for the `plugin-runtime-attach` module's activation poll; defaults to the poll's own 5 s. */
  pluginActivationPollIntervalMs?: number;
}

/**
 * `database-migration-reconciliation` (ADR-041/043/044/045 re-audit, 2026-07-16,
 * TM-adr041-043-044-045-audit-001, Finding 2 fix) is CRITICAL and runs FIRST — ADR-041 §3's own
 * "never boot into a half-migrated schema" guarantee only holds if this scan actually runs;
 * before this fix, `reconcile-interrupted-migration.ts`'s fully-built, fully-unit-tested scanner
 * was never invoked by any composition root, so `deps.siteStatusRepo` (and therefore the Recovery
 * screen's degraded-banner precedence chain and the `PENDING_MIGRATION` deep-link guard) could
 * never reflect a real crash-interrupted migration. A failure to even RUN this scan (not what it
 * finds — finding an interrupted migration is a successful detection, not a module failure) is
 * critical: boot must not proceed not knowing its own migration-safety state.
 *
 * `settings`/`seo` are ALSO CRITICAL: their promises have no `.catch()` anywhere in their chain
 * (an unhandled-rejection risk before ADR-046 Phase 2), so a failure here must abort boot cleanly.
 * `newsletter`/`comments` are OPTIONAL, matching their pre-existing log-and-continue behavior.
 * Commerce is off: no store/payment declaration or seeding module is constructed in any mode.
 */
export function buildBootModules(deps: NewsletterRouteDeps, options: BuildBootModulesOptions): BootModule[] {
  let pluginActivationPoll: { stop: () => void } | undefined;
  return [
    {
      name: "database-migration-reconciliation",
      owner: "features/database",
      criticality: "critical",
      prepare: async () => {
        await reconcileInterruptedMigrationOnBoot({
          siteId: deps.workspaceId,
          migrationRuns: deps.migrationRunsRepo,
          ledger: deps.databaseLedgerRepo,
          siteStatus: deps.siteStatusRepo,
        });
      },
      start: noop,
      stop: noop,
    },
    { name: "settings", owner: "features/settings", criticality: "critical", prepare: () => deps.settingsReady, start: noop, stop: noop },
    { name: "seo", owner: "seo", criticality: "critical", prepare: () => deps.seoReady, start: noop, stop: noop },
    { name: "newsletter", owner: "newsletter", criticality: "optional", prepare: () => deps.newsletterReady, start: noop, stop: noop },
    { name: "comments", owner: "comments", criticality: "optional", prepare: () => deps.commentsReady, start: noop, stop: noop },
    {
      // P0a fix (2026-09-23): re-attaches every durably-enabled plugin to this process's (fresh,
      // empty) hook registry before the server starts serving — see `deps.pluginRuntimeReady`'s own
      // doc. OPTIONAL: `attachEnabledPluginsAtBoot()` already isolates per-plugin failures itself
      // (logs and continues), so this module's own promise realistically never rejects; optional
      // criticality is a defensive floor, not the primary safety net.
      //
      // `start` keeps this process's registry reconciled with the durable activation table after
      // boot. `plugins_set_enabled` runs in the AGENT DAEMON process, so a chat-driven disable
      // detached the hook only there; without this poll, every save served here kept running the
      // disabled plugin's beforeSave hook until restart. ADR-070 now routes chat writes here too;
      // this server-owned poll still reconciles durable version changes made by other processes
      // (`plugin-activation-polling.ts`), without recreating a daemon hook registry.
      name: "plugin-runtime-attach",
      owner: "features/plugin-runtime",
      criticality: "optional",
      prepare: () => deps.pluginRuntimeReady,
      start: async () => {
        pluginActivationPoll?.stop();
        pluginActivationPoll = startPluginActivationPolling(
          deps,
          options.pluginActivationPollIntervalMs === undefined ? {} : { intervalMs: options.pluginActivationPollIntervalMs },
        );
      },
      stop: async () => {
        pluginActivationPoll?.stop();
        pluginActivationPoll = undefined;
      },
    },
    {
      // Finishes or rolls back an Agent Plugin update a crash interrupted, then removes retained
      // rollback bytes. It runs here, in array order: before the bundled seed touches any package and
      // before the listener serves a run, since no run can hold those paths yet.
      //
      // OPTIONAL, like the seed below: one bad plugin must not stop the server. An unrecovered plugin
      // is switched OFF (the update transaction switches it off before moving any bytes; recovery of
      // an unreadable journal switches it off and rethrows; a restored revision whose MCP servers
      // could not be re-provisioned stays off with an event), and its retained journal refuses any
      // change to it (`PLUGIN_UPDATE_PENDING`, 409) until a later boot recovers it. Refusing to boot
      // the whole site would also lock the operator out of the admin that could fix it. The composed
      // lifecycle binds the real MCP port (`createDeferredAgentPluginUpdateEffects`), so recovery
      // re-provisions a restored revision's servers.
      name: "agent-plugin-update-recovery",
      owner: "features/agent-plugins",
      criticality: "optional",
      prepare: async () => {
        try {
          await deps.agentPluginLifecycle.reconcileAgentPluginUpdates({ workspaceId: deps.workspaceId });
        } catch (error) {
          // eslint-disable-next-line no-console
          console.error(`[agent-plugin-update-recovery] an interrupted Agent Plugin update could not be recovered; it is retried next boot: ${error instanceof Error ? error.message : String(error)}`);
          throw error;
        }
      },
      start: noop,
      stop: noop,
    },
    {
      // Installs the Agent Plugins that ship with Tovu into this workspace's own package store and
      // records each INACTIVE until an operator enables it (see
      // `features/agent-plugins/seed-bundled.ts` for why it re-runs every boot rather than once).
      //
      // OPTIONAL, not critical, and deliberately so: a bundled plugin that fails to seed costs the
      // operator one dormant, disabled capability. Refusing to boot a whole CMS over that would be a
      // wildly disproportionate failure mode for a feature that is switched off by default anyway.
      // Per-plugin failures are captured in the returned report and logged here rather than thrown,
      // so one bad package cannot hide the others.
      name: "bundled-agent-plugins",
      owner: "features/agent-plugins",
      criticality: "optional",
      prepare: async () => {
        const result = await seedBundledAgentPlugins({
          layout: deps.agentPluginLayout,
          workspaceId: deps.workspaceId,
          sourceRoot: bundledAgentPluginsDir(),
        });
        for (const outcome of result.outcomes) {
          if (outcome.status === "failed") {
            // eslint-disable-next-line no-console
            console.warn(`[bundled-agent-plugins] '${outcome.pluginId}' could not be seeded: ${outcome.reason}`);
          }
        }
        if (result.ledgerFailure !== undefined) {
          // Not a seed failure: every package is installed and every activation decision intact.
          // What is lost is this boot's record of WHICH digest the build published, so a bundled
          // plugin that was upgraded in place falls back to being refused as ambiguous until a
          // later boot writes the ledger (`features/agent-plugins/bundled-digests.ts`).
          // eslint-disable-next-line no-console
          console.warn(`[bundled-agent-plugins] the bundled-digest ledger could not be written: ${result.ledgerFailure}`);
        }
        logBundledPluginRetirements({ retirements: result.retirements });
        await warnAboutMissingBundledPlugins(deps, { result });
        await syncProviderFacesAtBoot(deps);
        await lockSoonAgentPluginsAtBoot(deps);
        await importAgentPluginTokensAtBoot(deps, options);
        // A vendor's tool rename (`tovuRenamedTools` in a plugin's `mcp.json`) follows onto the rows
        // that plugin provisioned, so a saved selection never names a tool the server stopped offering.
        await applyAgentPluginToolRenames(
          {
            workspaceId: deps.workspaceId,
            agentPluginLayout: deps.agentPluginLayout,
            externalMcpServerRepo: deps.externalMcpServerRepo,
            clock: deps.clock,
            notifyRosterChanged: () => notifyExternalMcpRosterChanged(),
          },
          bootLog,
        );
        // A plugin that is on with a signed-in account gets the tools it declares even when the
        // sign-in's own grant missed them (bug 2026-11-04) — after the renames, so it grants the new names.
        await grantDeclaredToolsAtBoot(
          {
            workspaceId: deps.workspaceId,
            agentPluginLayout: deps.agentPluginLayout,
            repo: deps.externalMcpServerRepo,
            applyAccess: deps.mcp.applyAccess,
            clock: deps.clock,
            notifyRosterChanged: () => notifyExternalMcpRosterChanged(),
            ...agentPluginMcpPortsOf(deps.mcp),
          },
          bootLog,
        );
      },
      start: noop,
      stop: noop,
    },
  ];
}

/** Logs one line per critical, not-ready module from a failed boot. Called only when
 *  `bootResult.ok` is false — both `index.ts`'s and `cli/commands/serve.ts`'s own `!ok` branches. */
export function logCriticalBootFailures(bootResult: BootResult): void {
  for (const module of bootResult.modules) {
    if (module.criticality === "critical" && module.lifecycle.status !== "ready") {
      console.error(`[boot-lifecycle] critical module "${module.name}" (${module.owner}) is ${module.lifecycle.status}: ${module.lifecycle.reasonCode}`);
    }
  }
}

import type { Tracker } from "@jini-ai/diagnostics/observability";

import { redactedError } from "@jini-ai/diagnostics/observability/node";

/**
 * @file Process-level safety net for an unhandled promise rejection escaping every route/middleware
 * layer beneath it — the systemic half of a live-found crash (2026-08-16): an admin route that
 * decrypts a stored secret (`publish-credentials.ts`'s `POST .../:id/verify`) threw on a missing
 * site key with no surrounding try/catch, Express 4 does not catch an async handler's own rejection
 * (that is an Express 5 behavior change, not available here — `package.json` pins `express` to
 * `^4.21.2`), and nothing anywhere in `src/` was listening for `unhandledRejection` either — so
 * Node's own default (`--unhandled-rejections=throw`, terminate the process when no listener is
 * registered) took down the ENTIRE server on one caller's bad request, not just that one request.
 *
 * The route/store-level fix (`publish-credentials/store.ts`'s `decryptRecord`, now converting a raw
 * keyring/sealer error into the typed `PublishCredentialSecretStoreUnconfiguredError` `publish-
 * credentials.ts`'s `sendStoreError` already knows how to map to a 503) closes THAT specific gap.
 * This module is the fleet-wide half: this codebase has no lint rule or type check that would catch
 * a missing try/catch around a decrypting call in some FUTURE route, so a single bug in one route
 * must not be able to repeat the same whole-server outage again.
 *
 * Deliberately logs and continues rather than logging and exiting: this is a multi-tenant,
 * multi-workspace server (`project_tovu_workspace_multitenancy`), not a single-request process — one
 * caller's bug ending every OTHER workspace's in-flight and future requests is a worse outcome than
 * the one request that actually failed underneath the rejection returning a 500/hanging. This is the
 * mirror image of `index.ts`'s OTHER fail-fast behavior (`process.exit(1)` when a CRITICAL boot
 * module never becomes ready): that one is a startup-time gate deciding whether to accept traffic AT
 * ALL; this one is a runtime guard deciding whether one bad REQUEST gets to end every other request
 * too. Different question, different answer — this file does not touch or weaken the boot gate.
 *
 * `uncaughtException` (a synchronous throw, not an async rejection) is deliberately NOT handled the
 * same way here: Node's own guidance is that resuming normal operation after a truly uncaught
 * synchronous exception is unsafe (the process may be in a corrupted state in a way an unhandled
 * promise rejection is not), and the concrete bug this file fixes is specifically the async-rejection
 * shape (Express 4 swallowing nothing, propagating a rejected promise nowhere). Node's fatal
 * behavior (log to stderr, exit) is retained, with a bounded telemetry drain before exiting
 * when the caller supplies a flush port. Without one, a monitor leaves Node's listeners intact.
 *
 * Architectural role:
 * Boot-time process wiring, `src/server/boot/` sibling to `registerPluginSdkResolver()` (see that
 * file's own header for this directory's shared "one real top-level boot path, testable via an
 * injectable seam" shape, reused here). Called from `index.ts`'s `main()` — `index.ts` is that one
 * real top-level boot path (never imported by a test), so this file itself must expose the actual
 * `process.on()` registration as an exported, directly callable, directly testable unit rather than
 * an inline, untestable side effect of importing `index.ts`.
 */

export interface InstallUnhandledRejectionGuardOptions {
  /** Test seam: defaults to `console.error`. Every unhandled rejection logs unconditionally,
   *  regardless of this override — logging is the whole point of this guard (a rejection that is
   *  caught here must still read as a real bug in whatever log this process writes to, never a
   *  silent drop), so a test can assert on a stub without needing to capture real stdout/stderr. */
  readonly log?: (message: string, reason: unknown) => void;
}

/**
 * Registers a process-wide `unhandledRejection` listener. Node only terminates the process on an
 * unhandled rejection when NO listener is registered at all — installing one, even one that only
 * logs, is itself the entire fix; multiple listeners (e.g. a second call, or a test's own scoped
 * registration) are harmless, Node simply invokes all of them, so this is deliberately NOT guarded
 * against being called more than once the way `registerPluginSdkResolver` is (that function's own
 * "exactly once" contract exists for a security-relevant module-resolution hook; a duplicate log
 * line here carries no equivalent risk).
 *
 * @returns An uninstall function that removes exactly this call's listener — production's one real
 *   caller (`index.ts`'s `main()`) never calls it (the guard should live for the process's entire
 *   life), but a test needs it to avoid leaking a listener into a later, unrelated test in the same
 *   process and eventually tripping Node's `MaxListenersExceededWarning`.
 * @complexity O(1) — one `process.on()` registration.
 * @overallScore 100
 */
export function installUnhandledRejectionGuard(options: InstallUnhandledRejectionGuardOptions = {}): () => void {
  const log =
    options.log ??
    ((message: string, reason: unknown) => {
      // eslint-disable-next-line no-console
      console.error(message, reason);
    });
  const handler = (reason: unknown): void => {
    log("[unhandledRejection] an async operation rejected with no catch anywhere in its chain — logged, not fatal:", reason);
  };
  process.on("unhandledRejection", handler);
  return () => process.off("unhandledRejection", handler);
}

/**
 * Forwards process-level failures to the observability port (provider wave 2, 2026-10-25): an
 * unhandled rejection (`installUnhandledRejectionGuard` above still logs it and keeps the process
 * up) and an uncaught exception (report, drain telemetry, then exit). Installed by each process once
 * its `RouteDeps` exist — the serving process
 * (`index.ts`, `tovu serve`) and the agent daemon — because the port is only built there. Only add
 * this beside the guard: a rejection listener on its own would also suppress Node's default crash.
 * A fatal exception must never resume service: the deadline forces exit even if a provider hangs.
 * @param required The port and which process this is, sent as an attribute.
 * @param optional Event source and optional fatal flush; without flush the monitor only reports.
 * @returns An uninstall function removing exactly these two listeners.
 * @complexity O(1) to install; O(n) per report in the error's text length.
 */
export function installProcessErrorReporting(
  required: { tracker: Tracker; processRole: "server" | "daemon" | "desktop-main" },
  optional: { target?: Pick<NodeJS.EventEmitter, "on" | "off">; flush?: () => Promise<void>;
    exit?: (code: number) => void; timeoutMs?: number; log?: (message: string, error: Error) => void } = {},
): () => void {
  const { tracker, processRole } = required;
  const target = optional.target ?? process;
  const exit = optional.exit ?? ((code: number) => process.exit(code));
  let crashing = false;
  const onRejection = (reason: unknown): void => {
    tracker.error({ error: reason instanceof Error ? reason : redactedError({ error: reason }) }, { context: { operation: "process.unhandled_rejection", attributes: { process: processRole } } });
  };
  const onUncaught = (error: unknown): void => {
    if (crashing) return;
    crashing = true;
    let exited = false;
    const finish = (): void => {
      if (exited) return;
      exited = true;
      clearTimeout(deadline);
      exit(1);
    };
    const deadline = setTimeout(finish, Math.min(optional.timeoutMs ?? 2_000, 2_000));
    try {
      (optional.log ?? ((_message, failure) => console.error(failure)))("[uncaughtException] fatal; exiting after telemetry flush:", error instanceof Error ? error : redactedError({ error }));
    } catch { /* A broken stderr must not skip the report, fatal drain and exit. */ }
    try {
      tracker.error({ error: error instanceof Error ? error : redactedError({ error }) }, { context: { operation: "process.uncaught_exception", attributes: { process: processRole } } });
    } catch { /* A broken diagnostic sink must not skip the fatal drain and exit. */ } finally {
      void Promise.resolve().then(() => optional.flush?.()).catch(() => {}).finally(finish);
    }
  };
  const onMonitor = (error: unknown): void => {
    tracker.error({ error: error instanceof Error ? error : redactedError({ error }) }, { context: { operation: "process.uncaught_exception", attributes: { process: processRole } } });
  };
  const fatalEvent = optional.flush ? 'uncaughtException' : 'uncaughtExceptionMonitor';
  const fatalHandler = optional.flush ? onUncaught : onMonitor;
  target.on("unhandledRejection", onRejection);
  target.on(fatalEvent, fatalHandler);
  return () => { target.off("unhandledRejection", onRejection); target.off(fatalEvent, fatalHandler); };
}

/** Report a rejected Tovu boot and terminate, including when stderr itself fails.
 * A boot failure leaves index.ts's reserved listener serving 503 forever, so it cannot use the
 * request-time rejection guard's log-and-continue policy. Dependencies are injectable for unit tests.
 * The raw reason rides along so an unexpected composition failure keeps its stack in server.log.
 * @param error The rejected startup reason; Error messages and non-Error reasons are retained.
 * @returns Never in production; the injected exit port may return in tests.
 * @complexity O(n) time/space in diagnostic length; one log and one exit.
 */
export function reportFatalBootFailure(
  { error }: { error: unknown },
  { log = console.error, exit = (code: number) => process.exit(code) }: {
    log?: (message: string, reason: unknown) => void; exit?: (code: number) => void;
  } = {},
): void {
  try {
    const reason = error instanceof Error ? error.message : String(error);
    log(`[boot] Tovu failed to start: ${reason.replace(/\s+/g, " ")}. Restart Tovu after resolving this error; if the site is running in another app, stop it there first.`, error);
  } finally {
    exit(1);
  }
}

/** @file Same-origin provider delivery, admitted by the site's existing consent owner. */
import express, { type Express, type Request, type Response } from 'express';
import { getEffective } from '@jini-ai/core/settings';
import { readSiteVisitorConsent } from '../../inbound/public-http/middleware/site-cookie-consent.js';
import type { RouteDeps } from '#src/server/routes/types';
import { createRateLimiter, resolveClientIp } from '#src/contracts/core/rate-limit/rate-limit';
import { resolveSiteConsentOrigin } from '../../inbound/public-http/middleware/site-consent.js';
import { currentCredential } from '../../inbound/admin-http/dev-auth.js';
import { TELEMETRY_CONSENT } from './telemetry-consent.js';

/** Require a same-origin browser POST; never trust a caller's chosen upstream URL. O(1). */
function sameOrigin({ request }: { request: Request }, _options = {}): boolean {
  try { return new URL(request.get('origin') ?? '').origin === resolveSiteConsentOrigin({ request }); }
  catch { return false; }
}

/** Assets are inert until imported by the bridge. Site collection requires full analytics permission;
 * admin collection follows the operator setting, independently of the public banner. O(1) reads. */
export function applyBrowserAnalyticsHttp({ app, deps }: { app: Express; deps: RouteDeps }, _options = {}): void {
  const limiter = createRateLimiter({ profile: { windowSeconds: 60, max: 120, burst: 20 }, clock: deps.clock });
  app.use('/_jini/browser-analytics', express.raw({ type: () => true, limit: '256kb' }), async (request, response, next) => {
    const surface = request.path.split('/')[1];
    if (surface !== 'site' && surface !== 'admin') { next(); return; }
    response.setHeader('Cache-Control', 'private, no-store');
    try {
      const fullPath = '/_jini/browser-analytics' + request.path;
      const contribution = deps.browserAnalytics?.({ surface }).find(item => item.http && fullPath.startsWith(item.http.path + '/'));
      if (!contribution?.http) { response.status(404).end(); return; }
      if (request.method !== 'GET') {
        const allowed = await collectionAllowed({ request, deps, surface });
        if (!allowed) { response.status(403).end(); return; }
        if (!(await limiter.check({ key: resolveClientIp(request) })).allowed) { response.status(429).end(); return; }
      }
      await deliver({ request, response, http: contribution.http, fullPath });
    } catch { response.status(502).end(); }
  });
}

/** No cookie or proof crosses the provider port. Failed policy/setting reads deny delivery. O(1). */
async function collectionAllowed({ request, deps, surface }: {
  request: Request; deps: RouteDeps; surface: 'site' | 'admin';
}, _options = {}): Promise<boolean> {
  if (!sameOrigin({ request })) return false;
  // Generic browser contributions cannot enforce anonymous restrictions; explicit anonymous
  // adapters use the consent plugin collector, which carries their server-owned analytics level.
  if (surface === 'site') return (await readSiteVisitorConsent({ deps, req: request })).analyticsLevel === 'full';
  if ((await currentCredential(deps, request))?.kind !== 'session') return false;
  return (await getEffective({ repo: deps.settingsRepo }, { ...TELEMETRY_CONSENT, scopeContext: { workspaceId: deps.workspaceId } }))?.value === true;
}

/** Forward only the bounded bytes and media type; browser cookies remain inside the host. O(body). */
async function deliver({ request, response, http, fullPath }: {
  request: Request; response: Response; http: NonNullable<import('@jini-ai/analytics/product').BrowserAnalyticsContribution['http']>; fullPath: string;
}, _options = {}): Promise<void> {
  const result = await http.handle({ method: request.method, path: fullPath.slice(http.path.length),
    body: Buffer.isBuffer(request.body) ? request.body : new Uint8Array(), contentType: request.get('content-type') ?? 'application/octet-stream' });
  if (result.contentType) response.setHeader('Content-Type', result.contentType);
  if (request.method === 'GET' && result.cacheControl) response.setHeader('Cache-Control', result.cacheControl);
  response.status(result.status).end(result.body);
}

/** Tovu mounts Jini's raw webhook adapter before JSON, then its member/catalog HTTP adapters. */
import express, { type Express } from "express";
import { registerPaymentsWebhookRoute } from "@jini-ai/commerce/http";
import { COMMERCE_CHECKOUT_SCRIPT } from "@jini-ai/commerce/checkout-browser";
import type { RouteDeps } from "#src/server/routes/types";
import { registerCommerceRoutes } from "#src/server/inbound/public-http/routes/commerce/purchase";
import { registerProductRoutes } from "#src/server/inbound/public-http/routes/site/products";
import { pageShell } from "#src/server/inbound/public-http/http/site/render";
import { resolveRenderThemeId } from "#src/server/inbound/public-http/middleware/render-theme-override";
import { resolveSiteTitleForRender } from "#src/server/inbound/public-http/routes/site/pages";
import { NO_THEME_ID, resolveActiveTheme } from "#src/features/theme/active-theme";

/** Raw bytes must reach the signature verifier before the public JSON parser. O(1) mounting. */
export function registerCommerceWebhooks({ app, deps }: { app: Express; deps: RouteDeps }, _optional = {}): void {
  if (!deps.commerce) return;
  registerPaymentsWebhookRoute({ app, deps: { resolveReceiver: () => deps.commerce?.resolveReceiver() ?? null } }, { prefix: "/api" });
}

/** Off commerce has no public storefront; payment webhooks keep their separate drain route.
 * @complexity O(1) wiring and one activation/readiness check per storefront request.
 */
export function registerCommerceHttp({ app, deps }: { app: Express; deps: RouteDeps }, _optional = {}): void {
  if (!deps.commerce) return;
  // A router, not a second Express app: an app called directly gets its own defaults, so behind a
  // proxy every buyer would share the proxy's address and one rate budget. Requests stay on the host app.
  const storefront = express.Router();
  registerCommerceRoutes({ app: storefront, deps: { ...deps, renderCommercePage: async ({ res, title, body }) => {
    const [themeId, siteTitle] = await Promise.all([resolveRenderThemeId(res, deps), resolveSiteTitleForRender(deps)]);
    const resolved = resolveActiveTheme(deps, themeId);
    // Payment status remains readable even when no theme is installed.
    return pageShell({ title: `${title} | ${siteTitle}`, theme: resolved === NO_THEME_ID ? null : resolved, body });
  } } });
  storefront.get("/commerce/checkout.js", (_req, res) => {
    res.set("Cache-Control", "public, max-age=300").type("text/javascript").send(COMMERCE_CHECKOUT_SCRIPT);
  });
  registerProductRoutes(storefront, deps);
  app.use(async (req, res, next) => {
    // Match the router's case-insensitive paths without changing requested IDs or slugs.
    const requestPath = req.path.toLowerCase();
    // Order APIs keep their own member and write admission, including reads during drain.
    if (requestPath.startsWith("/api/commerce/v1/")) { storefront(req, res, next); return; }
    // The router below ignores one trailing slash, so this gate must too or the route is never reached.
    const productPath = requestPath === "/products" || requestPath.startsWith("/products/");
    if (!productPath && !["/commerce/return", "/commerce/cancel", "/commerce/checkout.js"].includes(requestPath.replace(/\/$/, ""))) { next(); return; }
    try {
      const status = await deps.commerce!.storefrontStatus();
      if (!status.active) { next(); return; }
      if (productPath && !status.ready) {
        res.status(404).type("html").send("<h1>This shop is not accepting purchases.</h1>"); return;
      }
      res.locals.commerceStatus = status;
      storefront(req, res, next);
    } catch {
      res.status(503).type("html").send("<h1>The shop catalog is temporarily unavailable.</h1><p>Please try again shortly.</p>");
    }
  });
}

import type { EventBusPort } from "@jini-ai/cms/core";
import type { Tracker } from "@jini-ai/diagnostics/observability";

function contentEventName({ topic, kind }: { topic: string; kind: string }, _optional = {}): string {
  if (topic === "content.created") return `${kind}_created`;
  return topic === "content.saved" ? "content_saved" : `${kind}_published`;
}

/** Subscribe once per site's bus at boot. Domain IDs let the provider dedupe outbox redelivery.
 * Creates/saves originate inside revision transactions; publishes reuse entry.published, including go-live.
 * @complexity O(1) setup and per event; no content reads or unbounded local dedupe state. */
export async function registerContentAnalytics(
  { deps }: { deps: { bus: EventBusPort; tracker: Tracker; workspaceId: string } },
  _optional: Record<string, never> = {},
): Promise<void> {
  for (const topic of ["content.created", "content.saved", "entry.published"]) {
    await deps.bus.subscribe<{ contentType?: string; entryId?: string; actorId?: string; source?: string; initialStatus?: string }>({
      eventName: topic,
      handler: async event => {
        if (event.workspaceId !== deps.workspaceId) return;
        const payload = event.payload;
        if (payload.contentType !== "post" && payload.contentType !== "page") return;
        const resourceId = payload.entryId ?? event.aggregateId;
        if (!resourceId) return;
        const kind = payload.contentType;
        const name = contentEventName({ topic, kind });
        deps.tracker.capture({ name, userId: payload.actorId ?? `system:${deps.workspaceId}` }, { properties: {
          eventId: event.id, resourceKind: kind, resourceId,
          source: payload.source === "admin" || payload.source === "assistant" ? payload.source : "service",
          ...(payload.initialStatus ? { initialStatus: payload.initialStatus } : {}),
        } });
      },
    });
  }
}

