/**
 * `TOVU_THEMES_DIR` env, then `<site>/themes` — the site's OWN themes root, and the only theme tree
 * anything reads or writes at runtime (`RouteDeps.themesDir`: the Theme Studio's file editor, the
 * agent theme tools, `__original-themes__/` resets, and both static-asset
 * mounts in `server/app.ts`).
 *
 * Seeded from {@link builtInThemesDir} on a site's first boot — see `seedSiteThemes()`'s own header
 * for why that copies the whole ~19MB tree rather than filling in on demand.
 *
 * `optional.siteDir` defaults to {@link siteDir}, same split as {@link mediaUploadsDir}.
 */
export function siteThemesDir(optional: SitePathResolverOptional & { siteDir?: string } = {}): string {
  const env = optional.env ?? process.env;
  return env.TOVU_THEMES_DIR ?? join(optional.siteDir ?? siteDir(), "themes");
}

/**
 * The read-only STOCK content seed a self-hosted container image ships for one specific site:
 * `content/seed-sites/<site>/content.seed.db`, copied there — from the tracked
 * `sites/<site>/content.seed.db` (`npm run seed:site`, development/scripts/seed-site.mjs) — by the
 * Dockerfile's OWN build stage only, deliberately never by the shared `npm run build` that
 * {@link builtInThemesDir} above also relies on: that script also produces the npm-publishable CLI
 * package, which must ship blank starter content, not this owner's own pruned site.
 *
 * SEED SOURCE ONLY, same split as {@link builtInThemesDir}/{@link siteThemesDir}:
 * `hydrateContentDbFromSeed()` copies this into {@link defaultContentDbPath} once, on a site's first
 * boot where `content.db` does not exist yet, and never again — an existing `content.db` is
 * production data, and overwriting it on a later redeploy is unrecoverable data loss. Living under
 * `content/`, not `sites/`, is what lets it survive a hosting plugin's generated volume mount over
 * `/workspace/Tovu/sites`: that mount shadows the ENTIRE image `sites/` tree at runtime, so anything
 * shipped there for a fresh volume to read would be invisible the moment the mount takes effect.
 *
 * The env var is `TOVU_STOCK_CONTENT_SEED_DIR`, mirroring `TOVU_STOCK_THEMES_DIR`'s own escape
 * hatch. `siteName` is the served site's (`siteBinding.name`) — decoupled from
 * `TOVU_CONTENT_DB`, which can relocate `content.db` itself without changing which site's stock
 * seed applies. It used to default to `basename(siteDir())`, the env/cwd site, which is a different
 * one for any composition that does not pin `TOVU_SITE_DIR` (see {@link resolveExportOutputRootDir}).
 */
export function builtInContentSeedDbPath(siteName: string): string {
  const stockRoot = process.env.TOVU_STOCK_CONTENT_SEED_DIR ?? join(resolveProductRoot(), "content", "seed-sites");
  return join(stockRoot, siteName, "content.seed.db");
}

/**
 * The read-only STOCK upload payload a self-hosted container image ships for one specific site:
 * `content/seed-sites/<site>/uploads/`, the sibling the Dockerfile's build stage now stages
 * alongside `content.seed.db` (see that file's comment at the extraction loop). Same stock root as
 * {@link builtInContentSeedDbPath} — deliberately not a second env var: the two are always shipped
 * together, at the same physical location, as one seed payload for one site.
 *
 * SOURCE ONLY, consumed by `hydrateBlobStoreFromSeed()` — see that function's own header for why it
 * tops up the live `blobStore` one content-addressed key at a time rather than copying this
 * directory wholesale the way {@link builtInThemesDir}/`seedSiteThemes()` copy `themes/`.
 */
export function builtInSeedUploadsDir(siteName: string): string {
  const stockRoot = process.env.TOVU_STOCK_CONTENT_SEED_DIR ?? join(resolveProductRoot(), "content", "seed-sites");
  return join(stockRoot, siteName, "uploads");
}



/**
 * `TOVU_PLUGINS_DIR` env, then `<site>/plugins` — the per-site root `discoverPlugins()`
 * scans for site-installed plugins (SPEC-005 REQ-02's `<install-dir>/plugins/<id>/<version>/`
 * layout; this function resolves the `<install-dir>/plugins` segment itself, matching what
 * `discoverPlugins({ installDir })`'s own fixtures pass — see `discovery.ts`'s
 * `listInstalledPluginIdFolders`, which lists `<installDir>/<id>/` directly).
 *
 * Deliberately instance-wide, not per-workspace (unlike `src/features/agent-plugins/layout.ts`'s
 * `ws/<workspaceId>/` tenant isolation, a DIFFERENT feature with its own later, separate tenancy
 * decision): SPEC-005's `plugin_activations` table is already the per-workspace boundary (REQ-07,
 * `workspaceId`+`pluginId` primary key) — an installed plugin ARTIFACT is shared across every
 * workspace on this instance, same as `siteThemesDir()`'s themes; only its enabled/disabled
 * state is workspace-scoped. Read ONCE here, same reasoning (and same served-site
 * `required.siteDir`) as {@link resolveExportOutputRootDir}.
 */
export function pluginsInstallDir(required: { siteDir: string }, optional: SitePathResolverOptional = {}): string {
  const env = optional.env ?? process.env;
  return env.TOVU_PLUGINS_DIR !== undefined ? resolve(env.TOVU_PLUGINS_DIR) : join(required.siteDir, "plugins");
}

/**
 * ADR-041 §2 — the sidecar `ops/database-journal.db` lives as a sibling of `content.db` in the
 * install-dir tree, never inside it (a physically separate SQLite file so a `content.db` restore
 * never erases the incident record narrating that very restore). Defaults to `<dirname of
 * content.db>/ops/database-journal.db`; overridable independently via `TOVU_DATABASE_JOURNAL_DB`
 * for deployments that relocate the sidecar journal on its own.
 */
export function defaultDatabaseJournalDbPath(contentDbPath: string = defaultContentDbPath()): string {
  return process.env.TOVU_DATABASE_JOURNAL_DB ?? join(dirname(contentDbPath), "ops", "database-journal.db");
}

/**
 * `chat.db` lives as a sibling of `content.db` (ADS-memory/reports/2026-09-05-db-split-scoping.md
 * §6), for the same physical-separation reason `defaultDatabaseJournalDbPath` above exists: a
 * whole-file restore/duplicate of `content.db` must never carry (or erase) conversation history.
 * Defaults to `<dirname of content.db>/chat.db`; overridable independently via `TOVU_CHAT_DB`.
 */
export function defaultChatDbPath(contentDbPath: string = defaultContentDbPath()): string {
  if (process.env.TOVU_CHAT_DB !== undefined) return process.env.TOVU_CHAT_DB;
  if (isInMemoryDbPath(contentDbPath)) return join(dirname(contentDbPath), "chat.db");
  const root = resolveSiteDirForDatabase({ dbPath: contentDbPath });
  const paths = resolveSiteDatabasePaths({ dir: root });
  return paths.contentDbPath === contentDbPath ? paths.chatDbPath : join(dirname(contentDbPath), "chat.db");
}

/**
 * Where this site's shares live: `<database dir>/ops/shares` (the site folder for an in-memory database).
 * `ops/` is the site's private runtime folder beside its database, next to the journal and logs, and every
 * backup, duplicate and publish walk already leaves it out. The database placement is the site's
 * identity: an in-site database moves with its folder, an app-data one is keyed by a siteId the sites
 * registry keeps unique, and boot refuses any database not named content.db, so two catalogs collide only
 * when two boots open the same database, and then they are the same site. Keying by workspace id merged
 * every starter site's catalog (`workspace-local`) and a copied `.site-meta.json` id merged a Finder copy's (Codex checks
 * 2026-10-26/27, design 2026-10-27). Only the transient export snapshot must stay out of the site (tmpdir).
 * @throws When the folder is inside a served content root.
 * @complexity O(content roots).
 */
function resolveShareDirectory(required: { siteDir: string; dbPath: string; contentRoots: readonly string[] }): string {
  const shareDirectory = resolve(isInMemoryDbPath(required.dbPath) ? required.siteDir : dirname(required.dbPath), "ops", "shares");
  const refuse = (target: string): void => {
    if (isInsideAny({ target, roots: required.contentRoots })) throw new Error("A site's ops/shares must not be inside a served content folder; give its database its own folder.");
  };
  // Checked before anything is created, so a refused folder is never made inside a served root;
  // checked again on the real path, so a symlink cannot smuggle it back in.
  refuse(shareDirectory);
  mkdirSync(shareDirectory, { recursive: true, mode: 0o700 });
  const physicalShares = realpathSync(shareDirectory);
  refuse(physicalShares);
  return physicalShares;
}

/** `target` equals or sits under one of `roots`, compared as given and as real paths. @complexity O(roots). */
function isInsideAny(required: { target: string; roots: readonly string[] }): boolean {
  return required.roots.some(root => [resolve(root), existsSync(root) ? realpathSync(root) : resolve(root)]
    .some(candidate => required.target === candidate || required.target.startsWith(candidate + sep)));
}

/**
 * SPEC-003 (ADR-PIPE-003 C-010) — an already-opened db + a resolved workspace id, supplied by
 * the install-dir boot path (`site-dir/boot-site-dir.ts`) instead of this function opening its
 * own db. `db`/`workspaceId` are required together or omitted together (validated below) — there
 * is no legal state where only one is supplied. `uploadsDir` is independent of that pair.
 */
export interface CreateSiteRouteDepsOverrides {
  /** Test seam: replaces provider-plugin selection/initialization (fakes; never a vendor call). */
  bootProviderPlugins: typeof bootProviderPlugins;
  /** Test seam: the project store (`project-store.ts`); resolving to undefined means "none". */
  openProjectStore: () => Promise<ProjectStore | undefined>;
  sqliteOpen: ContentDbOpenOptions["open"];
  /** DB placement may differ from the site root or from content.db. */
  chatDbPath: string;
  publishContentPeerHttpClient: RouteDeps["publishContentPeerHttpClient"];
  nativeApprovalMemory: RouteDeps["nativeApprovalMemory"];
  approvalIdentityForRun: RouteDeps["approvalIdentityForRun"];
  db: ContentDb;
  workspaceId: string;
  /** Consecutive plugin hook failures before automatic quarantine. */
  pluginFailureThreshold: number;
  /**
   * Install-dir-relative uploads path — `cli/commands/serve.ts` supplies `<dir>/uploads` (CR-R01
   * fix: uploads used to always default to `mediaUploadsDir()`, which is `process.cwd()`-relative
   * and therefore wrong whenever `tovu serve <dir>` is invoked from outside that dir). Omitted, it
   * falls back to `mediaUploadsDir()` — the legacy same-directory dev boot's existing behavior.
   */
  uploadsDir: string;
  /**
   * Install-dir-relative themes path — `cli/commands/{serve,export}.ts` supply `<dir>/themes`, for
   * exactly the reason `uploadsDir` above exists (CR-R01): the default {@link siteThemesDir} is
   * `process.cwd()`-relative, so `tovu serve <dir>` invoked from outside `<dir>` would otherwise
   * seed and serve a `sites/tovu-dev/themes` next to wherever the operator happened to be standing
   * rather than the site it was told to run. Omitted, it falls back to {@link siteThemesDir}.
   */
  themesDir: string;
  /**
   * The `RouteDeps.siteBinding` value this boot should carry — supplied by `cli/commands/serve.ts`
   * for the install-dir path (`{dir: target, ..., switcherCompatible: false}`, since `target` bears
   * no `{cwd, env}`-relative relationship to any `sites/` folder). Omitted, it falls back to
   * `describeSiteBinding()` — the legacy same-process default boot's existing behavior, unchanged.
   * See `RouteDeps.siteBinding`'s own doc for the full defect this fixes.
   */
  siteBinding: SiteBinding;
  /**
   * Which process opens the site's store (`open-site-store.ts`): the agent daemon passes
   * `"client"`; omitted means `"owner"` (the API process, which also runs the guest-chat sweep).
   */
  storeRole: SiteStoreRole;
  /**
   * The owner's guest-chat expiry sweep timing (`startChatExpirySweep`): its re-run interval and
   * clock. Omitted, the sweep runs hourly on `Date.now`; tests pass a short interval and a
   * controlled clock to observe later passes and closing during one.
   */
  chatExpirySweep: { intervalMs?: number; now?: () => number };
  /**
   * A workspace id to serve, validated against the store this call opens (`resolveWorkspace`
   * rejects an id with no row). The Postgres/PGlite form of `db` + `workspaceId`, which need the
   * SQLite handle the id was validated against; see {@link createSiteRouteDepsForWorkspace}.
   */
  requestedWorkspaceId: string;
  /**
   * An already opened Postgres/PGlite store, supplied with `workspaceId` by the install-dir boot
   * path (`bootSiteDir` opened, migrated and resolved it) — the non-SQLite form of `db`, so one
   * boot never opens a second pool. Its opener closes it, through the store `onStoreOpened` hands
   * back (`closeSiteDirBoot`), so the composition's chat sweep stops first.
   */
  store: SiteStore;
  /**
   * Called once, before the rest of the composition is built, with the composition's store: the one
   * this call opened, or the supplied `store` (a supplied SQLite `db` is still wrapped with the
   * `chat.db` this call opens). Its `close()` stops the guest-chat sweep, waiting for a pass in
   * flight, then closes the underlying store, so the caller closes this one rather than its own
   * reference. The default boot (`index.ts`) closes it on shutdown and hands a PGlite owner's socket
   * to the agent daemon. When the composition fails after this, it has already closed what it opened
   * (and stopped the sweep on a supplied store).
   */
  onStoreOpened: (store: SiteStore) => void;
  /**
   * HARNESS ONLY: exact loopback origins (`http://127.0.0.1:<port>`) the assistant's URL tools may
   * reach — a site-import journey's offline fixture site. Supplied only by
   * `development/e2e/support/site-import-api.ts`; `index.ts` and `tovu serve` never pass it, and
   * omitted it builds exactly the production clients (`platform/http/test-origin-allowlist.ts`).
   */
  outboundTestOrigins: readonly string[];
}

/**
 * 2026-08-20 (complexity pass) — CIC U-001 / Contract Map C-010's paired-override guard, hoisted
 * out of `createSiteRouteDeps`. Each `overrides?.field` read is its own branch under ESLint's
 * `complexity` rule; splitting the two reads plus the comparison `if` into their own 4-line
 * function moves those 3 points of complexity here instead of onto the composition root, without
 * changing what gets checked or when.
 */
function assertOverridesPairedOrAbsent(overrides?: Partial<CreateSiteRouteDepsOverrides>): void {
  const hasOverrideDb = overrides?.db !== undefined || overrides?.store !== undefined;
  const hasOverrideWorkspaceId = overrides?.workspaceId !== undefined;
  if (hasOverrideDb !== hasOverrideWorkspaceId) {
    throw new Error(
      "createSiteRouteDeps: overrides.db (or overrides.store) and overrides.workspaceId must be supplied together or not at all"
    );
  }
}

/**
 * Builds `composePluginRuntime`'s optional `failureThreshold` field from `overrides` — the exact
 * undefined-check-and-conditional-spread shape `server/app.ts`'s `createRouteDeps` repeats for its
 * own optional `composePluginRuntime` fields, hoisted here for the same reason
 * {@link assertOverridesPairedOrAbsent} is: one ternary counted once, not inline in the composition
 * root.
 */
function pluginFailureThresholdOverride(
  overrides?: Partial<CreateSiteRouteDepsOverrides>
): { failureThreshold?: number } {
  return overrides?.pluginFailureThreshold === undefined ? {} : { failureThreshold: overrides.pluginFailureThreshold };
}

/**
 * First-boot-only: turns a deployed container's stock `content.seed.db` into this site's live
 * `content.db`, exactly once — same presence-not-contents gate `seedSiteThemes()` above uses for
 * `themes/`, so a live db from any later boot is never touched (see `hydrateContentDbFromSeed()`'s
 * own header for the full rationale). Hoisted out of `createSiteRouteDeps` for the same reason
 * {@link assertOverridesPairedOrAbsent} is: one branch counted once here, not inline in the
 * composition root. A no-op whenever `overrides.db` is supplied — that caller (`boot-site-dir.ts`'s
 * install-dir path) has already opened its own db before reaching here, so `dbPath` is never even
 * read in that branch.
 */
function hydrateContentDbIfNeeded(dbPath: string, storage: SiteStorage, overrides?: Partial<CreateSiteRouteDepsOverrides>): void {
  if (overrides?.db !== undefined || storage.kind !== "sqlite") return;
  // The served site's stock seed, by its binding's name, not `basename(siteDir())`: see
  // {@link resolveExportOutputRootDir}'s doc for why the env/cwd site can be a different one.
  hydrateContentDbFromSeed({ seedDbPath: builtInContentSeedDbPath(resolveSiteBindingOverride(overrides).name), dbPath });
}

/**
 * 2026-09-03 (complexity pass) — `overrides.themesDir ?? siteThemesDir(...)`, hoisted out of
 * `createSiteRouteDeps` for the same reason {@link assertOverridesPairedOrAbsent} is: one `??`
 * counted once here, not inline in the composition root. The default is under the served
 * `siteBinding`'s directory, not {@link siteDir}'s.
 */
function resolveThemesDirOverride(siteBinding: SiteBinding, overrides?: Partial<CreateSiteRouteDepsOverrides>): string {
  return overrides?.themesDir ?? siteThemesDir({ siteDir: siteBinding.dir });
}

/**
 * `overrides.siteBinding ?? describeSiteBinding()`, hoisted for the same reason
 * {@link resolveThemesDirOverride} is: one `??` counted once here, not inline in the composition
 * root. See `CreateSiteRouteDepsOverrides.siteBinding`'s own doc for why the install-dir boot
 * path (`cli/commands/serve.ts`) must supply an explicit value rather than let this default apply.
 */
function resolveSiteBindingOverride(overrides?: Partial<CreateSiteRouteDepsOverrides>): SiteBinding {
  return overrides?.siteBinding ?? describeSiteBinding();
}

/**
 * `RouteDeps.siteBackupSources`: the directories `site_backup_plan` reads, taken from the SAME
 * resolved values this root serves the site from, so a backup never walks a different folder than
 * the one in use. Media is `null` under `TOVU_MEDIA_BLOB_STORE=s3`: the bytes then live in object
 * storage, and the backup says so instead of copying an unused local folder. A remote provider
 * chosen by the site setting instead is only known when the backup runs, so `isMediaRemote` (the
 * media store's effective answer) is passed through for the backup to ask then.
 *
 * @complexity O(1) — env reads and one small `package.json` read.
 */
function resolveSiteBackupSources(input: { siteDir: string; uploadsDir: string; mediaIsRemoteByEnv: boolean; isMediaRemote: () => Promise<boolean>; themesDir: string; agentPluginLayout: RouteDeps["agentPluginLayout"]; skillLayout: RouteDeps["skillLayout"]; sitePlugins: NonNullable<SiteBackupSources["sitePlugins"]> }): SiteBackupSources {
  return {
    siteDir: input.siteDir,
    mediaUploadsDir: input.mediaIsRemoteByEnv ? null : input.uploadsDir,
    isMediaRemote: input.isMediaRemote,
    themesDir: input.themesDir,
    agentPlugins: input.agentPluginLayout,
    skillsDir: input.skillLayout.root,
    tovuVersion: readTovuVersion(),
    sitePlugins: input.sitePlugins,
  };
}

/** The product's own `package.json` version, stamped into a site backup's manifest. A missing or
 *  unreadable file costs only the stamp, never the boot. */
function readTovuVersion(): string {
  try {
    const parsed = JSON.parse(readFileSync(join(resolveProductRoot(), "package.json"), "utf8")) as { version?: unknown };
    return typeof parsed.version === "string" ? parsed.version : "unknown";
  } catch {
    return "unknown";
  }
}

/**
 * SPEC-050 (NC-2 = B, REQ-13): the served site's display name, `config.json` `name` in the directory
 * holding `dbPath`, read at each render that needs it so a rename shows with no restart. Every boot
 * path keeps `content.db` in its site directory (`tovu serve`/`tovu export` pass `<dir>/content.db`;
 * the default boot and the agent daemon use `siteDir()`'s), so no caller has to thread it. Reads
 * `undefined` while that directory holds no valid `config.json` (a bare `TOVU_CONTENT_DB`, a temp test
 * database) and always for `:memory:`; the site title then falls back to `workspaces.name`.
 */
function createSiteDisplayNameSource(dbPath: string, siteDir?: string): SiteDisplayNameSource {
  if (dbPath === ":memory:") return { read: () => undefined };
  // Database relocation must not relocate the site's name/configuration.
  return createLiveSiteDisplayName({ dir: resolveSiteDirForDatabase({ dbPath, siteDir }) });
}

/** Resolve the served site's key candidates and retain its root for vault contribution discovery.
 * @complexity O(1), one site-metadata read; never reads or creates key material. */
function compositionSiteKeySources({ dbPath, runtimeMode, siteBinding }: {
  dbPath: string; runtimeMode: ReturnType<typeof resolveRuntimeMode>; siteBinding: CreateSiteRouteDepsOverrides["siteBinding"] | undefined;
}, _options = {}) {
  // site-key plan §A3a: both site-key-backed keyrings below need this site's own ordered source
  // list (per-site file first in local mode, mirroring `ensureSiteKey`'s own writer-side ordering —
  // `site-key-sources.ts`). Computed once, here, rather than per-keyring: `dbPath !== ":memory:" ?
  // resolveSiteDirForDatabase(...) : undefined` shares the site-root resolution used by
  // `createSiteDisplayNameSource` above, so a `:memory:` boot (no site directory at all) correctly
  // resolves no `siteKeyId` and therefore no per-site candidate. The database may now be outside
  // that root; its parent must never establish the key's identity.
  // Site keys/config/themes remain at the site root when SQLite is stored elsewhere.
  const siteDirForKeyring = dbPath !== ":memory:" ? resolveSiteDirForDatabase({ dbPath, siteDir: siteBinding?.dir }) : undefined;
  const siteKeyIdForKeyring = siteDirForKeyring ? resolveSiteKeyId({ siteDir: siteDirForKeyring }) : undefined;
  const sources = siteKeySources({
    mode: runtimeMode,
    env: process.env,
    home: homedir(),
    cwd: process.cwd(),
    siteKeyId: siteKeyIdForKeyring,
  });
  return { siteDirForKeyring, sources };
}

function compositionApprovalOverrides({ overrides }: { overrides: Partial<CreateSiteRouteDepsOverrides> }, _options = {}) {
  return {
    ...(overrides.nativeApprovalMemory ? { nativeApprovalMemory: overrides.nativeApprovalMemory } : {}),
    ...(overrides.approvalIdentityForRun ? { approvalIdentityForRun: overrides.approvalIdentityForRun } : {}),
  };
}

function prepareCompositionStorage({ dbPath, overrides }: {
  dbPath: string; overrides: Partial<CreateSiteRouteDepsOverrides>;
}, _options = {}) {
  const anchor = isInMemoryDbPath(dbPath) ? ":memory:" : resolveSiteDirForDatabase({ dbPath, siteDir: overrides.siteBinding?.dir });
  const storage = resolveSiteStorage(anchor);
  if (!isInMemoryDbPath(dbPath) && storage.kind === "sqlite" && !overrides.db) mkdirSync(dirname(dbPath), { recursive: true });
  return storage;
}

/**
 * What a composition hands its store's `onClose`: the disposer a `register*`/`subscribe` call
 * returned, or the promise of one (`EventBusPort.subscribe` is async), so every registration goes
 * through the one collector whatever its return shape.
 */
type StoreCloseRegistration = (() => unknown) | Promise<() => unknown>;

/**
 * The prelude's store step (R1 plan R1d): the site's storage choice from its `.site-meta.json`
 * (absent = SQLite), then the content + chat store it names. When `overrides.db` is supplied (the
 * install-dir `serve` path), that SAME handle is reused rather than opening/migrating a second db —
 * `bootSiteDir` has already validated, migrated, and stamped it (BR-05/BR-06).
 *
 * The API process (`owner`) also starts the hourly guest-chat expiry sweep here, on the chat kernel
 * of that store, plus daily form-submitter IP cleanup when the package/schema gates are ready;
 * the agent daemon (`client`) leaves retention to it. The returned store's `close()`
 * drains boot work before disposing registrations, then stops the sweeps (waiting for a pass in
 * flight) before closing the underlying store, so no pass ever queries a closed store.
 * `release` is what {@link createSiteRouteDeps} runs when the rest of
 * the composition fails: close what this call opened, or only stop the sweep on a supplied store.
 *
 * `onClose` collects the composition's registrations (a resolve-phase handler or slot bound to this
 * store's repos, a bus subscription) so both `close()` and `release` remove them first. Without it, a
 * closed site's handler stays on every request's path, querying a database that is no longer open.
 */
async function openCompositionStore(
  dbPath: string,
  overrides: Partial<CreateSiteRouteDepsOverrides> = {}
): Promise<{ store: SiteStore; release: () => Promise<void>; onClose: (registration: StoreCloseRegistration) => void; beforeClose: (drain: () => Promise<void>) => void }> {
  const storage = prepareCompositionStorage({ dbPath, overrides });
  hydrateContentDbIfNeeded(dbPath, storage, overrides);
  const role = overrides.storeRole ?? "owner";
  const supplied = overrides.store;
  // SQLite: `openSiteContentDb` (open → ADR-023 §2 crash recovery → migrate → watermark + demo
  // seed) unless `overrides.db`, then `chat.db` beside it (`defaultChatDbPath`). `chat.db`'s
  // directory is `dirname(dbPath)`, which the content open already required to exist.
  const opened = supplied ?? (await openSiteStore({ storage, dbPath, chatDbPath: overrides.chatDbPath ?? defaultChatDbPath(dbPath), role }, { db: overrides.db, ...(overrides.sqliteOpen ? { sqliteOpen: overrides.sqliteOpen } : {}) }));
  const stopChatSweep = startOwnerChatExpirySweep(role, opened.chat, overrides.chatExpirySweep);
  // Owner only, just like chat retention. Stop both passes before closing the supplied/opened
  // store, including composition-failure cleanup. Jini's export and migration 0006 gate the IP sweep.
  const stopSubmissionIpSweep = role === "owner"
    ? startSubmissionIpExpirySweep({ kernel: opened.content })
    : async () => {};
  const stopMailRetention = role === "owner" ? startMailRetention({ db: opened.content }) : async () => {};
  const registrations: StoreCloseRegistration[] = [];
  const bootDrains: Array<() => Promise<void>> = [];
  const stopStoreUsers = async (): Promise<void> => {
    // Boot still uses the inventory, journal and repos that the disposers below release.
    await Promise.all(bootDrains.map((drain) => drain()));
    await Promise.all(registrations.splice(0).map(async (registration) => (await registration)()));
    await Promise.all([stopChatSweep(), stopSubmissionIpSweep(), stopMailRetention()]);
  };
  const store: SiteStore = {
    ...opened,
    close: async () => {
      await stopStoreUsers();
      await opened.close();
    },
  };
  overrides.onStoreOpened?.(store);
  return {
    store,
    release: supplied === undefined ? store.close : stopStoreUsers,
    onClose: (registration) => { registrations.push(registration); },
    beforeClose: (drain) => { bootDrains.push(drain); },
  };
}

/** The guest-chat expiry sweep, on the owner only; its stop function (a no-op on a client). */
function startOwnerChatExpirySweep(
  role: SiteStoreRole,
  chat: SiteStore["chat"],
  timing: CreateSiteRouteDepsOverrides["chatExpirySweep"] = {}
): () => Promise<void> {
  return role === "owner" ? startChatExpirySweep(chat, timing) : async () => {};
}

/**
 * 2026-09-03 (complexity pass) — `overrides.workspaceId ?? resolveWorkspace({ kernel }).id`, hoisted
 * for the same reason {@link assertOverridesPairedOrAbsent} is. CIC U-001 (Workspace-id
 * single-source-of-truth) still holds: this remains the sole `resolveWorkspace` call site: moving
 * it into its own function does not add a second one.
 */
async function resolveWorkspaceIdOverride(kernel: ContentKernel, overrides?: Partial<CreateSiteRouteDepsOverrides>): Promise<string> {
  if (overrides?.workspaceId !== undefined) return overrides.workspaceId;
  const requested = overrides?.requestedWorkspaceId;
  return (await resolveWorkspace({ kernel }, requested === undefined ? {} : { workspaceId: requested })).id;
}

/**
 * 2026-09-03 production incident recovery hook — opt-in ONLY: a no-op on every ordinary boot,
 * because it does nothing at all unless the operator has explicitly set `TOVU_ADMIN_RESET_PASSWORD`
 * (e.g. as a host secret) for this one deploy. That opt-in-via-env-var gate is what makes it safe to
 * wire into every boot unconditionally, the same reasoning `hydrateContentDbIfNeeded` above follows
 * for its own presence-not-contents gate.
 *
 * Exists because the admin UI's own reset-password route is not always trustworthy as a recovery
 * path — it is exactly what failed in the incident this closes (see
 * `features/identity/owner-reset-env.ts`'s own header for the full story) — so
 * an operator locked out of the admin panel needs a way to fix the credential that does not depend
 * on the admin panel already working. Jini owner recovery re-reads and verifies the
 * write before this function ever reports success; a failure here is logged loudly but never
 * crashes the boot (mirrors `hydrateBlobStoreFromSeed`'s own catch-and-log posture below) —
 * crashing the ENTIRE public site over a failed ADMIN-only credential fix would be a strictly worse
 * outcome than the incident it is trying to recover from.
 *
 * A no-op whenever `overrides.db` is supplied, same reason and same guard as
 * `hydrateContentDbIfNeeded` above: that caller has already opened its own db (at a path this
 * function cannot assume equals `dbPath`) before reaching here.
 */
function applyAdminPasswordResetFromEnvIfConfigured(required: {
  beforeReset: () => Promise<unknown>;
  workspaceId: string;
  identity: IdentityRouteDepsSlice;
  clock: ClockPort;
  idGen: IdGeneratorPort;
  overrides?: Partial<CreateSiteRouteDepsOverrides>;
}): Promise<void> {
  if (required.overrides?.db !== undefined || required.overrides?.store !== undefined) return Promise.resolve();

  const password = process.env.TOVU_ADMIN_RESET_PASSWORD;
  if (!password) return Promise.resolve();
  const username = process.env.TOVU_ADMIN_RESET_USERNAME;
  const { workspaceId, identity, clock, idGen } = required;
  return identity.identityReady.then(async () => {
    if (!identity.recoveryCodes) throw new Error("Owner recovery storage is unavailable");
    // A secret left set after recovery must not re-salt the same credential, revoke sessions,
    // or copy the whole database on every boot. Capture a backup only before an actual write.
    return applyOwnerPasswordReset({ workspaceId, password, ...(username === undefined ? {} : { username }),
      deps: { auth: identityServiceDepsFrom({ ...identity, clock: { nowMs: () => clock.nowMs(), nowIso: () => new Date(clock.nowMs()).toISOString() }, idGen }),
        codes: identity.recoveryCodes, seededOwnerPrincipalId: await identity.ownerPrincipalId } }, { beforeReset: required.beforeReset });
  }).then((resolvedUsername) => {
    console.error(`[admin-password-reset] SUCCESS — username='${resolvedUsername}' configured password self-verified at boot. Unset TOVU_ADMIN_RESET_PASSWORD now.`);
  }).catch((error: unknown) => {
    const details = formatErrorForLog({ error }, { ...TOVU_ERROR_REDACTION_OPTIONS, exactSecrets: [password] });
    console.error(`[admin-password-reset] FAILED: the owner password could not be reset. Check the owner username and identity database, then retry. Details: boot-owner-reset\n${details}`);
  });
}

/**
 * The site composition root: opens the site's store ({@link openCompositionStore}), then builds every
 * `RouteDeps` service over it ({@link composeSiteRouteDeps}). Async so storage opening can await (R1
 * plan). Bad overrides reject rather than throw. When anything after the open fails, the store this
 * call opened is closed (and the chat sweep stopped) before the rejection propagates, so a failed
 * boot never leaves a PGlite owner lock/socket or a Postgres pool behind.
 */
export async function createSiteRouteDeps(
  dbPath: string = defaultContentDbPath(),
  overrides?: Partial<CreateSiteRouteDepsOverrides>
): Promise<NewsletterRouteDeps & ByokToolSurfaceDeps> {
  assertOverridesPairedOrAbsent(overrides);
  assertContentDbFileName(dbPath);
  const opened = await openCompositionStore(dbPath, overrides);
  try {
    return await composeSiteRouteDeps(dbPath, { store: opened.store, onStoreClose: opened.onClose, beforeStoreClose: opened.beforeClose }, overrides);
  } catch (err) {
    await opened.release();
    throw err;
  }
}

/** The provider-plugin boot to run: the test seam when supplied, else the real selection. */
function providerPluginBoot({ overrides }: { overrides: Partial<CreateSiteRouteDepsOverrides> }): typeof bootProviderPlugins {
  return overrides.bootProviderPlugins ?? bootProviderPlugins;
}

/**
 * Provider settings: the project store (closed with the site store) when one opens; the site vault
 * when there is none (remote production). An unavailable owner store means no shared keys;
 * independently owned local keys remain usable. No key rows are moved during boot.
 */
async function composeProviderConfig({ overrides, runtimeMode, onStoreClose, site, binding, references }: {
  overrides: Partial<CreateSiteRouteDepsOverrides>; runtimeMode: RuntimeMode; onStoreClose: (close: () => void) => void; site: ProviderConfigSource; binding: { dir: string; name: string }; references: SiteKeyReferences;
}): Promise<{ siteId: string; projectStore?: ProjectStore; providerConfigSource: ProviderConfigSource; projectId: string | undefined; projectVault?: ProjectVaultScope }> {
  const siteId = acceptedSiteId(readSiteMetaId(binding.dir), "site meta") ?? "";
  if (!siteId) return { siteId, providerConfigSource: site, projectId: undefined };
  const projectStore = await projectStoreFor({ overrides, runtimeMode });
  if (!projectStore) return { siteId, providerConfigSource: site, projectId: undefined };
  if ("unavailable" in projectStore) return { siteId, providerConfigSource: withUnavailableProject({ site, reason: projectStore.unavailable }), projectId: undefined };
  onStoreClose(() => projectStore.close({}));
  if (siteId) await projectStore.attachments.renameSite({ siteId, siteName: binding.name }).catch(error => {
    console.warn(`[project-store] Site name could not be refreshed; local keys remain available. ${formatErrorForLog({ error }, TOVU_ERROR_REDACTION_OPTIONS)}`);
  });
  const owner = projectStore.vault.repo;
  const repo = attachedOnlyVault({ vault: owner, siteId, attachments: projectStore.attachments });
  return { siteId, projectStore, providerConfigSource: withAttachedProject({ site }, { project: projectStore.config, attachments: projectStore.attachments, siteId, siteName: binding.name, references, transaction: input => projectStore.transaction(input) }),
    projectId: projectStore.projectId, projectVault: { ...projectStore.vault, repo, createRepo: projectKeyCreateVault({ owner, view: repo }), replaceRepo: projectKeyCreateVault({ owner, view: repo }, { allowReplacement: true, transaction: input => projectStore.transaction(input) }), keyring: ownerKeyHandleOnly({ keyring: projectStore.vault.keyring }), sealer: siteGrantedSealer({ allowed: async ({ credentialId }) => projectStore.attachments.isAttached({ siteId, keyId: credentialId }), sealer: projectStore.vault.sealer }) } };
}

/**
 * The project half of a credential store (owner 2026-10-25: keys save to the project by default;
 * `features/custom-credentials/store.ts`'s and `features/deployments/publish-credentials/store.ts`'s
 * scope rule): `repo` builds that store's own repo over the project's vault. Absent where no project
 * store is configured — remote production keeps its site store. Unavailable Shared Keys contributes
 * no shared half; local rows retain their independent ownership.
 */
function credentialProject<R>(projectVault: ProjectVaultScope | undefined, repo: (vault: ProjectVaultScope["repo"]) => R): { project?: { workspaceId: string; repo: R; createRepo?: R; replaceRepo?: R; sealer: ProjectVaultScope["sealer"]; keyring: ProjectVaultScope["keyring"] } } {
  if (!projectVault) return {};
  const { workspaceId, sealer, keyring } = projectVault;
  return { project: { workspaceId, repo: repo(projectVault.repo), ...(projectVault.createRepo ? { createRepo: repo(projectVault.createRepo) } : {}), ...(projectVault.replaceRepo ? { replaceRepo: repo(projectVault.replaceRepo) } : {}), sealer, keyring } };
}

/** A site id from `source`, or undefined (warned) when it is not a short token. */
function acceptedSiteId(value: string | undefined, source: string): string | undefined {
  if (value === undefined || isSiteIdToken(value)) return value;
  console.warn(`[site-identity] ${source} holds ${JSON.stringify(value.slice(0, 80))}, which is not a valid site id; it is ignored`);
  return undefined;
}

/**
 * Which site sends every provider signal. NOT the workspace id: every starter-template site seeds the
 * same one (`workspace-local`), so two sites would report as one. The site's own `.site-meta.json` id
 * (`readSiteMetaId`) names it. A deployed server usually has no meta (production never mints one), so
 * next comes `TOVU_SITE_ID`, which `tovu deploy config` sets from the local site's meta: the deployed
 * copy reports as the same site. The meta wins over the env so one env shared by several local sites
 * can never merge them. The workspace id is only the last resort. The slug is the site folder's name;
 * Fly (production) has no project store, so its project is the site itself. Either source is taken
 * only as a short token (`isSiteIdToken`); anything else is warned about and skipped.
 */
export function siteIdentityFor({ workspaceId, binding, runtimeMode, projectId }: { workspaceId: string; binding: { name: string; dir: string }; runtimeMode: RuntimeMode; projectId: string | undefined }, { env = process.env }: { env?: NodeJS.ProcessEnv } = {}): SiteIdentity {
  const environment = telemetryEnvironment({ env, runtimeMode });
  const siteId = acceptedSiteId(readSiteMetaId(binding.dir), `${binding.dir}/.site-meta.json`)
    ?? acceptedSiteId(env.TOVU_SITE_ID || undefined, "TOVU_SITE_ID") ?? workspaceId;
  return { siteId, siteSlug: binding.name, environment, projectId: projectId ?? siteId };
}

/**
 * The project store both local apps share (`project-store.ts`); production (Fly, single site) has
 * none — the project is the site there. A store that cannot open (its folder can't be created, an
 * unreadable key, a damaged file) is reported and returned as `unavailable`, so a project-level fault
 * never stops a site booting, and its saves are refused rather than sent to the site vault.
 */
async function projectStoreFor({ overrides, runtimeMode }: { overrides: Partial<CreateSiteRouteDepsOverrides>; runtimeMode: RuntimeMode }): Promise<ProjectStore | { unavailable: string } | undefined> {
  const open = overrides.openProjectStore ?? (async () => {
    if (!localOwnerStoreEnabled({ runtimeMode, env: process.env })) return undefined;
    const workspace = createSitesWorkspace({});
    return openProjectStore({ sitesHome: workspace.home({}), home: homedir(), appDataDir: workspace.config({}).appData });
  });
  return open().catch(error => {
    const detail = formatErrorForLog({ error }, TOVU_ERROR_REDACTION_OPTIONS);
    const reason = `Shared Keys could not open. Existing site keys remain available. Retry Shared Keys after reopening the app. Details: P25_OWNER_STORE_UNAVAILABLE; ${detail}`;
    console.warn(`[project-store] ${reason}`);
    return { unavailable: reason };
  });
}

/**
 * Logs each media-generation vendor the registry refused; a refusal is never fatal to boot.
 * @complexity O(refusals).
 */
function logMediaProviderRefusals({ refusals }: { refusals: readonly string[] }, _optional = {}): void {
  for (const refusal of refusals) console.error(`[media-providers] ${refusal}`);
}

/**
 * {@link createSiteRouteDeps}'s body, over the store it opened. Every `await` sits in the prelude
 * (workspace → deny store → orphaned-chat check), before the body starts any fire-and-forget boot
 * promise, so the body still runs to its return synchronously.
 */
async function composeSiteRouteDeps(
  dbPath: string,
  opened: { store: SiteStore; onStoreClose: (registration: StoreCloseRegistration) => void; beforeStoreClose: (drain: () => Promise<void>) => void },
  overrides: Partial<CreateSiteRouteDepsOverrides> = {}
): Promise<NewsletterRouteDeps & ByokToolSurfaceDeps> {
  const { store, onStoreClose } = opened;
  // Plugin recovery may commit a quarantine while providers are still booting. Keep these small
  // lifecycle summaries until the consenting facade exists, rather than reading an uninitialized
  // tracker or sending around its guards. The queue is drained once after provider composition.
  const pendingLifecycleEvents: Array<Parameters<RouteDeps['tracker']['capture']>> = [];
  let lifecycleTracker: Pick<RouteDeps['tracker'], 'capture'> = { capture: (input, options = {}) => { pendingLifecycleEvents.push([input, options]); } };
  const assistantAgentInventory = createAssistantAgentInventory({ runtime: createNativeAgentRuntime({ env: process.env }) });
  onStoreClose(() => assistantAgentInventory.dispose({}));

  // Resolved ONCE and threaded down, the same discipline `exportOutputRootDir`/`themesDir` already
  // follow (see `routes/types.ts`). Seeded before anything discovers themes off it: on a site's
  // first boot `<site>/themes` does not exist yet, and `discoverAllBuiltInThemes` below would
  // otherwise hand the admin an empty theme list. Deliberately NOT done in `server/app.ts`'s
  // in-memory `createRouteDeps()` — that is the hermetic/test path, and seeding there would copy
  // the whole ~19MB stock tree per test run.
  // The served site. Every `<site>/...` default below is rooted at its `dir`, never at `siteDir()`
  // (`TOVU_SITE_DIR` or `<cwd>/sites/<name>`), which only `tovu serve` pins to the same place — see
  // `resolveExportOutputRootDir`'s doc.
  const resolvedSiteBinding = resolveSiteBindingOverride(overrides);
  const agentPluginLayout = resolveAgentPluginLayout({ siteDir: resolvedSiteBinding.dir });
  const agentPluginLifecycle = createTovuAgentPluginLifecycle({ layout: agentPluginLayout }, {
    bundledSourceRoot: bundledAgentPluginsDir(),
    productTracker: () => lifecycleTracker,
    identityAdmission: ({ id, localId, run }) => routeDeps.pluginHost!.withInstallIdentity({ candidate: { id, localId, family: "agent-plugin" }, run }),
    // Boot recovery re-provisions a restored revision's MCP servers through the same store; read
    // lazily because that store is composed below.
    mcpProvisioning: createDeferredAgentPluginUpdateEffects({ resolveDeps: () => routeDeps }),
  });
  const federatedMcpPresetRegistry = createFederatedMcpPresetRegistry({});
  const skillLayout = resolveSkillLayout({ siteDir: resolvedSiteBinding.dir });
  const resolvedThemesDir = resolveThemesDirOverride(resolvedSiteBinding, overrides);
  seedSiteThemes({ stockDir: builtInThemesDir(), siteThemesDir: resolvedThemesDir, siteRoot: resolvedSiteBinding.dir });
  // The one content kernel (SQLite: over `content.db`, one per connection; Postgres: the site's
  // database), read by the prelude below and handed to boot modules as `deps.contentKernel`.
  const kernel = store.content;
  // `observability` comes from provider plugins, initialized below once the site vault is
  // normalized (their key cards are sealed credentials) and before any consumer of the port.
  // Resolved here, before the first fire-and-forget boot promise below: `createMediaBlobStore` throws
  // on an unknown TOVU_MEDIA_BLOB_STORE or an incomplete S3 config, and a throw after those promises
  // start leaves them running against the store `createSiteRouteDeps` then closes — each one rejects
  // unhandled ("The database connection is not open") on top of the operator's real config error.
  // The provider itself (env override > `core.storage.mediaObjectStore` > local) resolves on first
  // media use through the late-bound ports below (`features/object-storage/media-store.ts`).
  const resolvedUploadsDir = overrides.uploadsDir ?? mediaUploadsDir({ siteDir: resolvedSiteBinding.dir });
  // The site's saved connection is read through the same publish credential source shares use
  // (one bucket credential for media and shares); that source needs `routeDeps`, built later.
  let provideMediaCredentials!: (source: ReturnType<typeof composePublishCredentialSource>) => void;
  const mediaCredentials = new Promise<ReturnType<typeof composePublishCredentialSource>>((done) => { provideMediaCredentials = done; });
  const mediaStorePorts = (): MediaObjectStorePorts => ({
    host: { createSigV4Client: createDeployHostKit({}).createSigV4Client, wrapFetch: (fetchFn) => trackFetch({ fetch: fetchFn, observability }) },
    loadBundledRegistry: () => loadBundledObjectStoreRegistry({ uploadsDir: resolvedUploadsDir, sourceRoot: bundledAgentPluginsDir() }),
    loadSiteRegistry: () => loadObjectStoreRegistry({ workspaceId, uploadsDir: resolvedUploadsDir, loadContributions: agentPluginLifecycle.loadPluginContributions }),
    readSetting: () => readMediaObjectStoreSetting({ settingsRepo, workspaceId }),
    resolveSharedCredential: async ({ providerId }) => {
      // Provider ids use underscores; the saved connection is keyed by the deploy target's hyphenated id.
      const resolved = await (await mediaCredentials).resolve({ workspaceId, target: providerId.replace(/_/g, "-") });
      if (!resolved.ok) return undefined;
      const { token, ...fields } = toDeployTargetCredential(resolved);
      return { fields, secret: token };
    },
  });
  const { blobStore, mediaIsRemoteByEnv, isMediaRemote } = createMediaBlobStore({ uploadsDir: resolvedUploadsDir, env: process.env, ports: mediaStorePorts }, { envDeclarations: readBundledObjectStoreEnvDeclarations({ sourceRoot: bundledAgentPluginsDir() }) });
  // Everything below is built from `kernel` / `chat` (the chat kernel) except these, which depend on
  // the storage engine (`store-bound-services.ts`: `sqliteOnlyServices` or `pgOnlyServices`).
  const storeBound = storeBoundServicesFor(store, dbPath);
  // CIC U-001 (Workspace-id single-source-of-truth): ONE resolved variable, reused by every
  // internal construction below that used to read the old seeded-workspace literal directly —
  // this is the sole `resolveWorkspace` call site in this function's call graph
  // (U-001-B1's grep-checkable invariant: zero remaining literal references outside this line;
  // {@link resolveWorkspaceIdOverride} is the one place that calls it). The legacy default path
  // (no overrides) resolves it dynamically too (rather than keeping the literal for that branch
  // only), so both paths share one mechanism instead of two that could drift (REQ-06/REQ-10;
  // every existing seeded fixture has exactly one workspace row, so this is behavior-identical to
  // the old literal for every current caller — see CIC's Design Context).
  const workspaceId = await resolveWorkspaceIdOverride(kernel, overrides);
  // Proves the deny store is readable before anything else is built: a missing or inaccessible
  // table stops boot rather than making every disconnected publisher silently look connected.
  const publishTrustRevocations = await publishTrustRevocationStoreFor(kernel);
  // ADS-memory/reports/2026-09-05-db-split-scoping.md §6 — chat data lives in its own file,
  // sibling to content.db, for the same "a whole-file restore/duplicate must never carry (or
  // erase) chat history" reason `databaseJournalDb` below is separate. Opened with the content
  // store (`openCompositionStore`), so the orphaned-chat check below runs after it.
  const chatDbPath = overrides.chatDbPath ?? defaultChatDbPath(dbPath);
  const chat = store.chat;
  await warnCompositionChatOrphans({}, {});

  async function warnCompositionChatOrphans(_required: Record<string, never>, _options = {}): Promise<void> {
    // The split above was wiring-only: it redirected the chat stores at `chat.db` but never moved
    // the rows an already-deployed `content.db` was holding, and nothing anywhere reported that.
    // Every such conversation is intact but unread, because the stores no longer look in that file.
    // This counts them and prints one warning naming the counts and the migration script —
    // read-only, and completely silent (one bounded `count(*)` per table) on the already-migrated
    // boot. It deliberately does NOT migrate: `applyChatSplit` deletes from content.db after
    // copying, and its own header requires a backup first — see `chat-orphan-check.ts`'s header for
    // the rejected alternatives. A warning only: a failure is logged, never fatal.
    // SQLite only: a Postgres/PGlite site never had chat rows in its content tables.
    if (store.storage.kind === "sqlite") {
      await warnOnOrphanedChatRows({ contentDb: kernel, contentDbPath: dbPath, chatDbPath }).catch((err) => {
        // eslint-disable-next-line no-console
        console.error(`warnOnOrphanedChatRows failed at boot: ${(err as Error).message}`);
      });
    }
  }
  // Media-generation vendors (built-in + Agent Plugin contributed), built ONCE here — see
  // `features/media-generation/media-provider-registry.ts`. A refused plugin vendor is logged, never fatal.
  // Awaited in the prelude, before the first fire-and-forget boot promise below (boot-order rule
  // pinned by composition-boot-order.unit.test.ts); it needs only the workspace and plugin layout.
  const mediaProviders = await loadMediaProviderRegistry({ workspaceId }, { loadContributions: agentPluginLifecycle.loadPluginContributions });
  logMediaProviderRefusals({ refusals: mediaProviders.refusals });
  // Posts written before migration 0022 existed — and the demo content `prepareContentStore` seeds
  // directly into `posts`, bypassing `SqlitePostRepo` entirely — have no FTS projection yet, so
  // `content_post_search` would not find them without an edit. Unconditional, and awaited by every
  // search (`postSearch` below takes it as `ready`), so no consumer can ever observe a
  // half-indexed corpus; on a warm database it is a single indexed anti-join that writes nothing.
  // A failure is logged and search carries on over what is indexed. See
  // `backfillPostSearchIndex`'s own doc for why it fills gaps rather than rebuilding.
  // Rows written by OLDER projection code (e.g. HTML pages indexed before f7ca1e766 projected
  // `body_html`) are re-projected once per site by the same step when the stored projection version
  // is behind the code's — no resave needed (`reindexStalePostSearchIndex`). Not awaited by boot.
  const postSearchBackfillReady = preparePostSearchIndex({ kernel }).catch((err) => {
    console.error(`preparePostSearchIndex failed at boot: ${(err as Error).message}`);
  });
  // Canonical Jini clocks use milliseconds; existing CMS/DB host ports still read ISO timestamps.
  const clock = { nowMs: () => Date.now(), nowIso: () => new Date().toISOString() };
  const idGen = { newId: () => randomUUID() };
  const reportToolAuditError = createSiteAssistantErrorReporter({ ids: idGen, redact: redactSecrets,
    log: entry => console.error("[tool-audit]", entry) });
  // One vendor, one switch (owner 2026-10-25): a provider plugin's linked agent plugin face follows
  // every write of its activation row (`provider-plugin-link.ts`).
  const pluginActivationRepo = followProviderActivations({ repo: sqlitePluginActivationRepoFor({ store: kernel }), workspaceId,
    ports: bindProviderFacePorts({ workspaceRoot: () => agentPluginLayout.forWorkspace(workspaceId).root }) });
  // Provider plugins load (and their SDK asks for the host) before `const routeDeps` below exists;
  // reading `routeDeps` then is a temporal-dead-zone ReferenceError. Until `routeDeps` is built the
  // answer is "no host yet" (the SDK then omits its `plugins` lookup facade).
  let routeDepsBuiltForPluginHost: { readonly pluginHost?: RouteDeps["pluginHost"] } | undefined;
  const pluginRuntime = composePluginRuntime({
    productTracker: () => lifecycleTracker,
    getPluginHost: () => routeDepsBuiltForPluginHost?.pluginHost,
    workspaceId,
    clock,
    activationRepo: pluginActivationRepo,
    // content-analyzer (AW-7 Tier 2) is tier-2: compiled in, disabled until enabled, and its code
    // only ever runs in a fresh worker per call (`plugin-runtime.ts`'s tier-2 import seam).
    sources: [WORD_COUNT_RUNTIME_SOURCE, CONTENT_ANALYZER_RUNTIME_SOURCE, RECHARTS_RUNTIME_SOURCE],
    browserProviderApprovals: [RECHARTS_BROWSER_APPROVAL],
    bundledEnabledIds: [RECHARTS_RUNTIME_SOURCE.manifest.id],
    // Reachability fix: previously omitted entirely, so `discoverPlugins()` only ever scanned the
    // compiled-in built-in registry — a plugin placed on disk (REQ-02's install layout) was
    // invisible to every real boot of this composition root, no matter how it got there.
    installDir: pluginsInstallDir({ siteDir: resolvedSiteBinding.dir }),
    coreClaims: TOVU_CORE_EXTENSION_CLAIMS,
    // AW-7 Tier 1: plugins' declared content types go through core's own `registerContentType`.
    // Deferred: `contentTypeRepo`/`outbox` are declared further down, and enable never runs during
    // composition.
    declaredContentTypes: deferDeclaredContentTypePorts({
      build: () => createDeclaredContentTypePorts({ repo: contentTypeRepo, clock, ids: idGen, outbox }),
    }),
    ...pluginFailureThresholdOverride(overrides),
  });
  // SQLite-backed identity (principals/users/sessions/roles/policies persist in content.db) so a
  // login survives a `tsx watch` restart instead of being silently wiped every file save.
  // Composition root: the ONLY place the serving site reads its first-boot owner login from env.
  const identity = createSqliteIdentityRouteDeps({ db: kernel, workspaceId, clock, idGen, permissionGrants: createAppPermissionGrants({}), ownerCredentials: resolveOwnerCredentials({ env: startupSecretEnvironment({ env: process.env }) }) });
  // Keep the host repository ABI while binding the active/workspace-scoped settings lookup.
  const settingsPrincipals = {
    ...createSettingsPrincipalLookup({ repo: identity.principalRepo }),
    findById: (required: Parameters<typeof identity.principalRepo.findById>[0]) => identity.principalRepo.findById(required),
    list: (required: Parameters<typeof identity.principalRepo.list>[0]) => identity.principalRepo.list(required),
    save: (record: Parameters<typeof identity.principalRepo.save>[0]) => identity.principalRepo.save(record),
  };
  // Fire-and-forget, mirroring `identityReady`/`blobHydrationReady` below — opt-in only (see the
  // function's own doc), so this is a genuine no-op on every ordinary boot. Exposed on the returned
  // deps (like `blobHydrationReady`) so a boot test can await the reset; nothing gates on it.
  const adminPasswordResetReady = applyAdminPasswordResetFromEnvIfConfigured({ beforeReset: () => storeBound.dbOps.captureRestorePoint({ scopeId: "boot-admin-password-reset" }), workspaceId, identity, clock, idGen, overrides });
  const presentationRepo = new SqlitePresentationSettingsRepo(kernel);
  const settingsRepo = new SqliteSettingsRepo(kernel);
  // Fire-and-forget, mirroring `identityReady` (see routes/types.ts's `settingsReady` doc) — this
  // composition root stays synchronous; consumers await `settingsReady` before relying on the
  // settings boot sequence being ready.
  // Presentation remains the live owner; boot must not write a second active-theme value.
  const settingsReady = Promise.resolve();
  // Serial writes avoid nested SQLite transactions; see startSettingsRegistration in app.ts.
  const { seoReady, commentsSettingsReady, assistantSettingsReady, executionSettingsReady, settingsUiTabsReady, analyticsSettingsReady } = startSettingsRegistration({
    deps: { settingsRepo, clock, ids: idGen, principals: settingsPrincipals },
    settingsReady,
    workspaceId: workspaceId,
    systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID,
  });

  // SPEC-050 `core.site.title` (`features/settings/site-title.ts`): registration, then the one-time
  // pin for every workspace the marker migration recorded as pre-existing (REQ-06). Chained after
  // `analyticsSettingsReady` for the single-SQLite-connection-transaction reason every registration
  // above documents; the pin writes through the same ledger.
  const siteTitlePreservationStore = new SqliteSiteTitlePreservationStore(kernel);
  const { siteDisplayName, siteTimeZone } = compositionSiteDisplaySources({ dbPath, overrides, settingsRepo });
  const siteTitleSettingsDeps = { settingsRepo, clock, ids: idGen, principals: settingsPrincipals };
  const siteSettingsReady = analyticsSettingsReady
    // `core.interface` (`features/settings/admin-interface.ts`), chained here for the same
    // one-connection reason as the registrations above.
    .then(() => ensureAdminInterfaceSettingDefinitions(siteTitleSettingsDeps, { systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensureChartProviderSetting({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensureFormDestinationSetting({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensureMediaObjectStoreSetting({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensurePreviewSwitcherSetting({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensureFormDeliverySettings({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    // `core.mail.senderEmail`/`senderName` (`features/settings/mail-sender.ts`): system mail's From.
    .then(() => ensureMailSenderSettings({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    // `core.mail.provider`/`testMode` (`features/settings/mail-provider.ts`): explicit provider per lane.
    .then(() => ensureMailProviderSettings({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    // Site search's per-site `core.search/provider` (default `builtin`); registering it enables nothing.
    .then(() => ensureSearchProviderSetting({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensureSiteTitleSettingDefinition(siteTitleSettingsDeps, { systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    // Bug D: `core.site.timezone` (`features/settings/site-timezone.ts`), the zone post dates render in.
    .then(() => ensureSiteTimeZoneSettingDefinition(siteTitleSettingsDeps, { systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }))
    .then(() => ensureCommerceSetting({ deps: siteTitleSettingsDeps, systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }));
  // Public title reads already handle pending pins; consent must not inherit this migration wait.
  const siteTitleReady = siteSettingsReady
    .then(() =>
      preserveLegacySiteTitles(
        { ...siteTitleSettingsDeps, preservationStore: siteTitlePreservationStore },
        { systemPrincipalId: SETTINGS_MIGRATION_SYSTEM_PRINCIPAL_ID }
      )
    )
    .then(() => undefined);
  // Observed at once: composition awaits provider boot before any consumer reads this tail, and a
  // rejection left unobserved across that pause is an unhandled rejection (Codex check 2026-10-27).
  // Only marks it handled; every consumer below still receives the rejection.
  siteTitleReady.catch(() => undefined);

  // ADR-PIPE-012 D-5/D-8 (T043/T044): the persistent composition root uses the real SQLite
  // adapters for both navigation repo ports, and runs the binding-index rebuild once at boot
  // (after the SQLite db above has already opened) so the derived index starts in sync with
  // whatever menus this content.db already holds. Fire-and-forget, mirroring `settingsReady`'s
  // shape — logged and swallowed rather than aborting boot, matching W-003's "logs and continues
  // on failure" contract (ADR-PIPE-012 Wiring Map).
  const menuRepo = new SqliteMenuRepo(kernel);
  const navLocationBindingRepo = new SqliteNavLocationBindingRepo(kernel);
  const menuBindingsReady = rebuildNavLocationBindings({
    menuRepo,
    bindingRepo: navLocationBindingRepo,
    clock,
    workspaceId: workspaceId,
  })
    .then(() => undefined)
    .catch((err) => {
      // eslint-disable-next-line no-console
      console.error(`rebuildNavLocationBindings failed at boot: ${(err as Error).message}`);
    });

  // SPEC-011 (Newsletter, ADR-PIPE-011 T011/W-010): boot-time `declareDataModule()` invocation for
  // Newsletter's real 5-table manifest, on the storage kernel of the SAME connection as the Drizzle
  // `ContentDb` (`declareDataModule` bridges the handle to its one kernel). Idempotent —
  // `declareDataModule()`'s own skip-if-exists logic makes repeated boot calls safe (T010 proves the
  // failure/rollback path separately). Fire-and-forget, mirroring `menuBindingsReady`'s shape: logged
  // and swallowed rather than aborting boot on failure — a failed install leaves Newsletter's admin
  // routes 404/500ing against missing tables, but never bricks the rest of the server.
  const newsletterListRepo = new SqliteNewsletterListRepo(kernel);
  // T030: seed the workspace's default "all subscribers" list right after the tables exist —
  // idempotent (`ensureDefaultList` is itself a find-or-create), matching `declareDataModule()`'s own
  // skip-if-exists convention.
  const newsletterReady = installNewsletterDataModule({ db: kernel, dbPath })
    .then(() => ensureDefaultList({ deps: { listRepo: newsletterListRepo, clock, ids: idGen }, input: { workspaceId: workspaceId } }))
    .then(() => undefined)
    .catch((err) => {
      // eslint-disable-next-line no-console
      console.error(`installNewsletterDataModule failed at boot: ${(err as Error).message}`);
    });

  /**
   * ADR-031/ADR-023 (SPEC-033) — Comments' `declareDataModule()` call, against the SAME shared
   * connection Newsletter's install just used. Chained AFTER `newsletterReady`
   * resolves (NOT fired in parallel), for the exact same reason `seoReady` is chained after
   * `settingsReady` above: two independent fire-and-forget async chains racing SQLite calls
   * (including SPEC-032's exclusive-lock pragma toggling) against ONE shared connection produced
   * a real, deterministically-reproduced "database is locked" failure — caught via a live
   * multi-boot smoke test, not a synthetic case. This is the identical hazard class this file's
   * own `seoReady` comment already documents; this fixes the same mistake made fresh here.
   */
  const commentsReady = newsletterReady
    .then(() => installCommentsDataModule({ db: kernel, dbPath }))
    .catch((err) => {
      // eslint-disable-next-line no-console
      console.error(`installCommentsDataModule failed at boot: ${(err as Error).message}`);
    });

  // ADR-027 §4 — the core "public" transform definition that lets the unauthenticated `/m/`
  // rendition route serve ANY asset at all (`media/bootstrap.ts`'s file header has the full
  // diagnosis: with zero rows in `transform_registry`, every `/m/` request 404s regardless of
  // what media exists). Hoisted here (rather than down with the other media repos below) so this
  // call and the returned `RouteDeps.transformDefinitionRepo` field share the SAME repo instance
  // rather than two independent wrappers over the same table. Chained after `commentsReady`, not
  // fired in parallel, for the identical single-SQLite-connection transaction hazard every `Ready`
  // chain in this function documents; fire-and-forget and not exposed on `RouteDeps`, mirroring
  // `menuBindingsReady`'s shape — nothing downstream needs to gate a request on this resolving,
  // since `ensureCoreMediaTransform` is idempotent and the window between boot and its single
  // insert completing is a few milliseconds.
  const transformDefinitionRepo = new SqliteTransformDefinitionRepo(kernel);
  const mediaTransformReady = commentsReady
    .then(() =>
      ensureCoreMediaTransform({
        deps: { clock, idGen, transformRepo: transformDefinitionRepo },
        input: { workspaceId: workspaceId },
      })
    )
    .catch((err) => {
      // eslint-disable-next-line no-console
      console.error(`ensureCoreMediaTransform failed at boot: ${(err as Error).message}`);
    });

  // Fills in stock blob BYTES for `media`/`asset_blobs` rows this site inherited from
  // `content.seed.db` (see `hydrate-blob-store-from-seed.ts`'s own header for the incident this
  // closes). Hoisted here — rather than left inline down with the other media fields below — for
  // the same reason `transformDefinitionRepo` above is: this call and the returned
  // `RouteDeps.blobStore` field must share the SAME instance, not two independent adapters over the
  // same backing store. Fired independently, NOT chained after `commentsReady`/`mediaTransformReady`
  // above: unlike those two, this touches no SQLite connection at all — it only reads the seed
  // payload off disk and calls `blobStore.exists`/`put` — so it carries none of the shared-
  // connection hazard the rest of this function's `Ready` chain exists to avoid. Exposed on
  // `RouteDeps` (unlike `mediaTransformReady`) purely so a boot-integration test can await
  // deterministic completion instead of racing a fire-and-forget background copy; no route or
  // caller needs to gate on it — `hydrateBlobStoreFromSeed`'s own per-key gate makes every run after
  // the first an all-`skipped` no-op. It calls `blobStore.putIfAbsent()` — one atomic call per key
  // now, not a separate `exists()`/`put()` pair (see that file's header for the race that closes).
  // `resolvedUploadsDir`/`blobStore` are resolved in the prelude above (a bad
  // TOVU_MEDIA_BLOB_STORE config must throw before any fire-and-forget boot promise starts).
  const blobHydrationReady = hydrateBlobStoreFromSeed({
    seedUploadsDir: builtInSeedUploadsDir(resolvedSiteBinding.name),
    blobStore,
  }).catch((err) => {
    // eslint-disable-next-line no-console
    console.error(`hydrateBlobStoreFromSeed failed at boot: ${(err as Error).message}`);
    return undefined;
  });

  // SPEC-009 (Redirects, ADR-PIPE-009) — FIRST-TIME composition-root wiring of `origin`'s
  // OriginRegistry and `routing`'s registration functions, mirroring `server/app.ts`'s identical
  // wiring. `redirects` DOES get its real `SqliteRedirectRepo` here (unlike the in-memory-only
  // libraries above), since T014 built a full rule-of-two adapter for it.
  // ADR-046 Phase 1 (BR-04 resolution, 2026-07-16 swarm debate): durable SQLite outbox. Events
  // survive a restart; `SqliteChangeSetRepo.insert()`'s co-persisted event and this adapter's
  // `claimPending()`/`markDelivered()`/`markFailed()` share the same `outbox_events` table.
  const outbox = new SqliteOutboxAdapter(kernel);
  const bus = new InMemoryEventBus();
  // ADR-046 Phase 1 (2026-07-16): durable SQLite origin-settings adapter.
  //
  // 2026-09-18 — `planOriginBoot` (`features/origin/configured-origin.ts`) now decides what this
  // boot writes, instead of an unconditional dev seed. Design note:
  // `ADS-memory/reports/2026-09-18-public-origin-registration-design.md`.
  //   - `TOVU_PUBLIC_URL` names a real public https origin -> register it, correcting an existing
  //     dev-capability row in place. This is what finally lets production's sitemap.xml emit
  //     absolute URLs, and what heals the `http://localhost:3000` row the first production boot persisted.
  //   - nothing configured, local mode -> the dev seed below, byte-for-byte unchanged.
  //   - nothing configured, production mode -> write NOTHING. ADR-040 §2 fails closed on an absent
  //     origin; the unconditional seed is what poisoned prod in the first place, and its
  //     find-or-create contract made that row immortal.
  //
  // `devCapabilityScheme` is DERIVED, not the `"https"` literal this used to hardcode (2026-09-05
  // audit finding, Chunk D finding 3): the dev API server only terminates TLS when `resolveDevTls`
  // (`server/runtime/boot/dev-tls.ts`) says so, same as `index.ts`'s own real boot path computes —
  // this composition root calls it independently rather than threading `index.ts`'s result through,
  // mirroring how `isAdminAssistantEnabled()` above is also called directly here rather than passed
  // in. Two real, disclosed cases fall to plain HTTP: a fresh clone with no `.certs/`, and
  // `TOVU_DISABLE_DEV_TLS`, which every hermetic Playwright `webServer` under
  // `development/*.config.ts` sets. A hardcoded `https` in either case silently shipped broken
  // `https://` links (redirects' canonicalOrigin, newsletter confirmation/unsubscribe, site
  // evidence) for a server that only ever answers on `http://`. `REPO_ROOT` is a walk-up
  // (`resolveCheckoutRoot`), not a fixed `../` count: the compiled tree is two levels shallower than
  // the tsx source tree, so a count only ever matched one of them.
  // NOTE: `devCapabilityScheme` stays at this scope, NOT inside the dev-seed branch below — the
  // `derivedPublicOrigin` field near the end of this function is a second consumer (see its own
  // comment). Narrowing it to the branch compiles nowhere and was caught by `tsc`.
  const REPO_ROOT = resolveCheckoutRoot();
  const devCapabilityScheme = deriveDevScheme(resolveDevTls(resolveDevTlsCertPaths(REPO_ROOT)).active);
  const originBoot = planOriginBoot({ now: clock.nowIso() });
  const originReady = registerBootOrigin({}, {});

  function registerBootOrigin(_required: Record<string, never>, _options = {}): Promise<unknown> {
    // The boot write is async (storage kernel); the origin repo's reads wait for it (`after`).
    if (originBoot.kind === "configured") {
      return registerConfiguredOrigin({ db: kernel, workspaceId: workspaceId, origin: originBoot.origin });
    }
    if (originBoot.kind === "dev-seed") {
      const listenerOrigin = readSiteListenerOrigin({ fallbackScheme: devCapabilityScheme });
      return seedDevCapabilityOrigin({
        db: kernel,
        seed: {
          workspaceId: workspaceId,
          origin: createVerifiedOrigin({
            scheme: listenerOrigin.protocol === "https:" ? "https" : "http",
            host: "localhost",
            port: Number(listenerOrigin.port || (listenerOrigin.protocol === "https:" ? 443 : 80)),
            verifiedAt: clock.nowIso(),
            source: "dev-capability",
          }),
          // ADR-PIPE-015 T016: a dev-capability egress allowlist entry so the real
          // isAllowedEgressTarget oracle doesn't fail-closed on every fresh dev server — matches the
          // `example.com` target every integrations fixture/test in this repo already uses.
          egressAllowlist: ["example.com"],
        },
      });
    }
    return Promise.resolve();
  }
  const originRegistry = new OriginRegistry({ repo: new SqliteOriginSettingRepo(kernel, { after: originReady }) });
  const redirectRepo = SqliteRedirectRepo({ store: kernel }, {});
  const redirectHitSink = new RedirectHitSinkImpl();
  // ---------------------------------------------------------------------------
  // Local admin Trash (design: ADS-memory/reports/2026-09-20-trash-delete-architecture.md)
  // ---------------------------------------------------------------------------
  // A plain Map, built here and resolved on every call. NOT a module-level registry: this
  // codebase's registries (`ToolRegistry`, routing's `phaseRegistry`) are append-only with no
  // unregister, so anything that filters at registration time runs exactly once — two real bugs
  // already came from that. Adding a phase-2 domain means one more `set()` here and no migration.
  const assetRenditionRepo = new SqliteAssetRenditionRepo(kernel);
  // `TRASHABLE` (plan §1/§4) — built once here. Adding a type needs
  // no edit below this line, only a new `registry.ts` `Map` entry — the adapter map beneath already
  // loops over every registered entry generically.
  const trashRegistry = buildTrashRegistry();
  const sqliteTrashDb = kernel;
  // Finishes a hide/restore/purge a generic marker flip alone cannot (`follow-ups.ts`), per type.
  // `widget`: an adopted legacy widget keeps its `purged` payload while in the Trash (an older site
  // build still reads it), and its restore makes the payload active again. `routeDeps` is read at
  // restore time, long after it exists below. T5/T6 add their own entries here (menu/taxonomy
  // revision + event follow-ups) — this map stays the one per-type wiring point (plan §2 T1 item 6).
  // Hoisted above `trashFollowUpHooks` (needs `findByEntity` for the term/taxonomy purge
  // follow-ups below) — the constructor takes only `db`, no dependency on
  // `trashAdapters`/`trash` itself, so this is safe to build early (T6, step 3).
  const trashRepo = new SqliteTrashRepo(kernel);
  // Purge-only audit trail for `term`/`taxonomy` (plan §6 Q2): one `taxonomy_revisions` row plus a
  // domain event, matching `deleteTerm`/`deleteTaxonomy`'s own writes — see
  // `taxonomy-trash-follow-ups.ts`'s file header. A second, cheap `SqliteTermRepo`/
  // `SqliteTaxonomyRevisionRepo` instance each (stateless wrappers over the same tables `termRepo`/
  // `taxonomyRevisionRepo` below use) rather than hoisting those out of the return object literal.
  const taxonomyFollowUpTermRepo = new SqliteTermRepo({ db: kernel, workspaceId });
  const taxonomyFollowUpRevisions = new SqliteTaxonomyRevisionRepo({ db: kernel, workspaceId });
  const taxonomyFollowUpOutbox = toTaxonomyOutbox({ outbox, clock, idGen, workspaceId });
  // Built here (stateless over `kernel`) because a form or submission purge scrubs its frozen
  // delivery jobs; the delivery wiring further down reuses the same instance.
  const formDeliveryRepo = new SqlFormDeliveryRepo({ kernel });
  const trashFollowUpHooks = new Map<string, TrashFollowUpHooks>([
    ...(["form_submission", "form"] as const).map(entityType => [entityType, createFormFilePurgeHooks({ kernel, entityType,
      prepareRemoval: async () => {
        const [assets, posts] = await Promise.all([mediaRepo.list({ workspaceId }), postRepo.list({ workspaceId })]);
        // The existing media owner still checks references. Snapshot once under the purge lock,
        // then remove deleted rows so shared blobs observe earlier deletions in this same purge.
        const snapshotMedia = new Proxy(mediaRepo, { get(target, key) {
          if (key === "list") return async () => assets;
          // Tombstoning runs inside purgeMedia, so its snapshot must lose the removed owner
          // before that check rather than only after purgeMedia returns.
          if (key === "remove") return async (input: { workspaceId: string; id: string }) => {
            await target.remove(input);
            const index = assets.findIndex(row => row.id === input.id);
            if (index >= 0) assets.splice(index, 1);
          };
          const value = Reflect.get(target, key);
          return typeof value === "function" ? value.bind(target) : value;
        } });
        const snapshotPosts = new Proxy(postRepo, { get(target, key) {
          if (key === "list") return async () => posts;
          const value = Reflect.get(target, key);
          return typeof value === "function" ? value.bind(target) : value;
        } });
        return async ({ workspaceId: ws, mediaId }) => {
          const asset = await mediaRepo.findById({ workspaceId: ws, id: mediaId });
          if (!asset) return;
          // A filename is visitor-influenced display data, never proof of attachment ownership.
          // Legacy public references stay intact when their ownership cannot be established.
          if (!asset.source.private) throw new Error(`Form attachment ${mediaId} has no proven form upload owner. The submission and file were kept.`);
          await trashFormMedia({ deps: { mediaRepo, clock }, input: { workspaceId: ws, id: mediaId } });
          await purgeFormMedia({ deps: { mediaRepo: snapshotMedia, blobRepo: assetBlobRepo, renditionRepo: assetRenditionRepo, blobStore, clock, entryRefsRepo, postRepo: snapshotPosts,
            ...createFormMediaCleanup({ kernel, outbox, clock, graceMs: DEFAULT_GC_GRACE_MS }) }, input: { workspaceId: ws, id: mediaId } });
        };
      },
      scrub: ({ workspaceId: ws, entityId }) => formDeliveryRepo.scrubPurged({ workspaceId: ws, purged: entityType === "form" ? { formId: entityId } : { submissionId: entityId } }),
    })] as [string, TrashFollowUpHooks]),
    [
      "widget",
      {
        afterUnhide: (required) =>
          restoreWidgetPriorStatus({
            deps: buildWidgetsDeps(routeDeps),
            input: { workspaceId: required.workspaceId, widgetInstanceId: required.entityId, priorStatus: required.priorMarker },
          }),
      },
    ],
    ["menu", buildMenuTrashFollowUpHooks({ menuRepo, outbox, idGen, clock })],
    [
      "term",
      createTermPurgeFollowUp({
        termRepo: taxonomyFollowUpTermRepo,
        trash: trashRepo,
        revisions: taxonomyFollowUpRevisions,
        outbox: taxonomyFollowUpOutbox,
        clock,
      }),
    ],
    [
      "taxonomy",
      createTaxonomyPurgeFollowUp({
        termRepo: taxonomyFollowUpTermRepo,
        trash: trashRepo,
        revisions: taxonomyFollowUpRevisions,
        outbox: taxonomyFollowUpOutbox,
        clock,
      }),
    ],
  ]);
  const pluginTrashAdapter = createDirectoryTrashAdapter({
    entityType: PLUGIN_ENTITY_TYPE,
    locate: ({ entityId }) => pluginRuntime.locatePluginPackageDirs(entityId),
    forget: ({ entityId }) => forgetPluginActivations({ pluginId: entityId, deps: { repo: pluginActivationRepo } }),
  });
  const trashAdapters = new Map<string, TrashAdapter>([
    [POST_ENTITY_TYPE, createPostTrashAdapter(kernel)],
    [REDIRECT_ENTITY_TYPE, createRedirectTrashAdapter(kernel)],
    [COMMENT_ENTITY_TYPE, createCommentTrashAdapter(kernel)],
    [PLUGIN_ENTITY_TYPE, pluginTrashAdapter],
    [
      MEDIA_ENTITY_TYPE,
      createMediaTrashAdapter({
        db: kernel,
        // Media's hard delete is not a row delete: rendition rows hang off it and the blob store
        // holds bytes. `purgeMedia` owns that ladder, so the adapter delegates rather than
        // reimplementing it in SQL and silently orphaning bytes.
        purgeAsset: async ({ workspaceId: ws, entityId }) => {
          await purgeMedia({
            deps: { mediaRepo, entryRefsRepo, postRepo, blobRepo: assetBlobRepo, renditionRepo: assetRenditionRepo, blobStore, clock },
            input: { workspaceId: ws, id: entityId },
          });
        },
      }),
    ],
    [
      USER_ENTITY_TYPE,
      createUserTrashAdapter({
        eventValues: outboxEventValues,
        db: kernel,
        assertAccountAction: async (required, optional) => {
          const service = identityServiceDepsFrom({ ...identity, clock, idGen });
          await service.repos.transactions.run({ workspaceId: required.workspaceId, execute: async () => {
            await assertUserAccountAction({ ...required, deps: service },
              { ...optional, seededOwnerPrincipalId: await identity.ownerPrincipalId });
          } });
        },
        // A fresh instance, not `identity.userPurge` (removed — see `wiring.ts`'s
        // `IdentityRouteDepsSlice.removeUser` doc): `purge`'s hard-delete is now reached only
        // through this adapter's own `purge()`, never directly from the route layer.
        purge: new SqliteUserPurge({ kernel, eventValues: outboxEventValues }),
        idGen: { next: () => randomUUID() },
        clock,
      }),
    ],
    // One generic adapter per `TRASHABLE` entry — `createTableTrashAdapter` is
    // written once and driven entirely by each entry's own registration, so this line never changes
    // as G2-G4 add more entries.
    ...[...trashRegistry.values()].map((entry) => {
      const tableAdapter = createTableTrashAdapter({ entry, db: sqliteTrashDb });
      const adapter = entry.entityType === "member"
        ? createMemberTrashAdapter({ adapter: tableAdapter, db: sqliteTrashDb })
        : tableAdapter;
      const hooks = trashFollowUpHooks.get(entry.entityType);
      return [entry.entityType, hooks ? withFollowUps({ adapter }, hooks) : adapter] as const;
    }),
  ]);
  // Reentrant: `deletePost` and `tombstoneRedirect` already open their own transaction around
  // "marker + revision append", and `remove` is called from inside it (a nested one joins). Named (not inlined) because
  // the comments moderation service needs the SAME runner to wrap its own two writes.
  const trashTransaction = createContentDbTransactionRunner(kernel);
  const trash = createTrashService({
    repo: trashRepo,
    adapters: trashAdapters,
    idGen: { newId: () => randomUUID() },
    // Trash flips post and widget markers through the kernel, past the repositories that clear media
    // access evidence on a save. Cleared after commit, so a read during the transaction cannot keep old
    // evidence. Cost: O(256) map clear per Trash action, then one rescan per asset on its next request.
    transaction: ({ work }) => trashTransaction(work).finally(() => invalidateMediaAccessEvidence({ owner: postRepo })),
    entityPolicy: ({ entityType }) => (trashAdapters).has(entityType)
  }, {
    retentionDays: TRASH_RETENTION_DAYS,
    onError: ({ error }) => console.error("[trash] onChanged hook failed; the trash/restore/purge it followed already committed", error)
  });
  // Folder moves before the Trash row is written; if that write throws, move the folder back.
  const removePlugin: RemovePluginFn = unhideIfRemoveThrows(pluginTrashAdapter, bindRemoveEntity({
    trash: trash,
    entityType: PLUGIN_ENTITY_TYPE
  }));
  // Delete-user plan v2 Slice 2 — `identity`'s `removeUser`/`isInTrash` overrides (see
  // `wiring.ts`'s `IdentityRouteDepsSlice.removeUser` doc for why identity itself cannot build
  // these: it wires before `trash`/`trashRepo` exist).
  const removeUser = bindRemoveEntity({
    trash: trash,
    entityType: USER_ENTITY_TYPE
  });
  const isInTrash = async (principalId: string): Promise<boolean> =>
    (await trashRepo.findByEntity({ workspaceId, entityType: USER_ENTITY_TYPE, entityId: principalId })) !== null;

  const redirectsWriteDeps: RedirectsWriteDeps = {
    repo: redirectRepo,
    remove: removeEntityWithoutBlocker({ remove: bindRemoveEntity({
      trash: trash,
      entityType: REDIRECT_ENTITY_TYPE
    }) }),
    // S7 (web-high fix plan 2026-09-24) — same identity `isInTrash` shape as above, pre-bound to
    // this domain's entity type. `trash.restore` is the real `TrashPort` method, not a bespoke one.
    isInTrash: async (required) =>
      (await trashRepo.findByEntity({ workspaceId: required.workspaceId, entityType: REDIRECT_ENTITY_TYPE, entityId: required.id })) !== null,
    restore: (required) =>
      trash.restore({
        workspaceId: required.workspaceId,
        entityType: REDIRECT_ENTITY_TYPE,
        entityId: required.id,
        at: required.at      }, {
        actor: required.actor      }),
    db: redirectRepo,
    transaction: (fn) => redirectRepo.transaction(fn),
    reservedSegments: RESERVED_SEGMENTS,
    matcher: redirectMatcher,
    originRegistry,
    clock,
    idGen,
    outbox,
  };
  // Disposed with the store: the resolver and the slug capture close over this site's
  // `redirectRepo`, and the phase registry and capture slot are process-wide, so neither may outlive
  // the database it queries. The hit fold's bus is this site's own; it leaves with the site too.
  onStoreClose(registerRedirectsPhaseHandlers({
    repo: redirectRepo,
    matcher: redirectMatcher,
    originRegistry,
    reservedSegments: RESERVED_SEGMENTS,
  }, { hits: { outbox, clock, idGen } }));
  onStoreClose(registerSlugChangeCapture({ impl: new RedirectSlugChangeCapture({ reservedSegments: RESERVED_SEGMENTS, repo: redirectRepo, db: redirectRepo, clock, idGen }) }));
  onStoreClose(registerRedirectHitOutboxHandler({ bus, hitSink: redirectHitSink }));

  // ADR-041 §2 — opens the sidecar ops journal alongside content.db. `mkdirSync` (recursive) is
  // required first: unlike `openContentDb`'s target (the process cwd, which already exists),
  // `ops/` is a new subdirectory better-sqlite3 will not create for us.
  const databaseJournalDbPath = defaultDatabaseJournalDbPath(dbPath);
  mkdirSync(dirname(databaseJournalDbPath), { recursive: true });
  const databaseJournalDb = openDatabaseJournalDb(databaseJournalDbPath);
  // The ops journal owns a separate SQLite connection on every content dialect.
  onStoreClose(() => databaseJournalDb.close());
  // `siteId` reuses `workspaceId` for v1's single-workspace-per-content.db topology — ADR-041 §7
  // names `siteId` vs `workspaceId` as SPEC-003 OQ-04, explicitly unresolved by that ADR; this
  // composition root does not resolve it either, it just picks the only value available today.
  const databaseLedgerRepo = new SqliteDatabaseLedgerRepo({ db: databaseJournalDb, siteId: workspaceId });
  // ADR-041/043/044/045 re-audit (2026-07-16, TM-adr041-043-044-045-audit-001, Finding 2 fix) —
