export const BYOK_TURN_PATH = "/api/admin/v1/assistant/byok-turn";

/** Exported so `assistant-byok-routes.test.ts` can assert the exact composed `system` string against
 *  this same literal rather than duplicating it — see {@link resolveByokSystemPrompt}'s doc for the
 *  composition this constant is the fixed half of. */
export const SYSTEM_PREAMBLE =
  SITE_GUIDE_POINTER +
  ASSISTANT_CONTENT_EDIT_GUIDANCE +
  "You are the Tovu admin assistant, running with the operator's own AI provider key (BYOK mode). " +
  "Use the tools you are given to inspect and manage this Tovu site on the operator's behalf. " +
  "Keep replies short and direct: lead with the answer, skip preamble and skip restating the " +
  "request. Use headers, lists, or tables only when they carry real structure. Give full detail " +
  "when asked, and never trade correctness for brevity — error text, failing output, and " +
  "confirmations for destructive actions keep their full content. " +
  "Only call tools that exist in your tool list; never invent one. " + CREDENTIAL_GUIDANCE + " " + PERMANENT_DELETE_GUIDANCE;

/** How long one BYOK turn waits on `ByokToolSurface.awaitFederation` before giving up and running
 *  with whatever tools are searchable so far — see that method's own doc for why the wait is bounded
 *  rather than open-ended. Only a turn that lands before the lazy boot pass has settled (normally just the
 *  first API-mode turn after boot) can actually wait this long; a roster-change reload is never
 *  awaited here, and every later turn finds the boot pass already settled and returns at once. 5s, per the owner's own sizing
 *  (`design-byok-external-mcp-2026-09-24.md` §2.1 item 6). */
export const FEDERATION_TURN_WAIT_MS = 5_000;

/** Appended to the system prompt (see {@link resolveByokSystemPrompt}) on a turn whose
 *  `awaitFederation` call timed out rather than settling — the same "no silent withholding" rule
 *  `agent-daemon-server.ts:643-647` already enforces for its own turns: a model that cannot yet see a
 *  just-registered external-MCP tool is told WHY a search might come up empty, rather than being left
 *  to guess the tool does not exist. */
export const FEDERATION_STILL_CONNECTING_NOTE =
  "External MCP servers are still connecting, so their tools may not be searchable yet. If a tool you need is missing, say so and suggest asking again in a moment.";

/** Bounds one BYOK turn's history the same way `assistant-transport.ts`'s `MAX_TRANSCRIPT_TURNS`
 *  bounds the daemon path's flattened prompt — each turn is a fresh provider request billed for its
 *  whole input, so an unbounded history would make every later message in a long chat more
 *  expensive than the last. */
const MAX_HISTORY_MESSAGES = 40;

/** Raises the bound each `run*ToolTurn` adapter would otherwise take from its own
 *  `DEFAULT_MAX_TOOL_TURNS` (8 — verified directly in all four of `@jini-ai/agent-runtime`'s
 *  `providers/{anthropic-messages,openai-chat,azure-chat,google-messages}.ts`, each of which reads
 *  `options.maxToolTurns ?? DEFAULT_MAX_TOOL_TURNS`). 8 is sized for a caller that names a real tool
 *  per action; this route's meta-tool surface costs up to 3 calls per real action
 *  (`search_tools` → `describe_tool` → `execute_delegated_tool`), so 8 truncates an ordinary
 *  multi-step task at roughly its second or third real operation — silently, because a truncated
 *  turn is reported to the client as an ordinary stop. 24 keeps ~6-8 real actions in reach at that
 *  3-calls-each cost. */
const BYOK_MAX_TOOL_TURNS = 24;

/** SSE framing. Local to this module, same convention (and same reason: kept in one place so event
 *  names cannot drift between branches) as `site-assistant.ts`'s identical helper — not shared
 *  cross-module because both are a few lines and neither has a second real caller yet. */
function sse(res: Response, event: string, data: unknown): void {
  res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function beginStream(req: Request, res: Response): void {
  res.status(200).set({
    "content-type": "text/event-stream",
    "cache-control": "no-cache, no-transform",
    // Same reasoning as `site-assistant.ts`'s identical guard: HTTP/2 throws
    // `ERR_HTTP2_INVALID_CONNECTION_HEADER` on a `connection` header, and dropping it changes
    // nothing observable for an HTTP/1.1 client (keep-alive is already its default there).
    ...(req.httpVersionMajor < 2 ? { connection: "keep-alive" } : {}),
    "x-accel-buffering": "no",
  });
  res.flushHeaders?.();
}

function isPlainMessage(value: unknown): value is { role: unknown; content: unknown; secretRedacted?: unknown } {
  return typeof value === "object" && value !== null;
}

/**
 * Transforms one `SurfaceEmission` into the bare `RunAgentPayload`-shaped object this route's own
 * `sse(res, "agent", ...)` writes onto the wire.
 *
 * Mirrors `@jini-ai/daemon`'s `delegated-tool-bridge.ts` `emitSurface` closure byte-for-byte (traced
 * directly, not inferred): `emission.channel` becomes the payload's `type`, `emission.payload`'s own
 * fields are spread in beside it (after stripping any `type`/`toolUseId` a handler tried to smuggle
 * in, so a handler cannot forge either), and `toolUseId` is injected only for the `'mcp-ui'` channel —
 * the one channel whose client-side renderer (`McpUiSurfaceCard`) actually reads it for correlation.
 * This is what lets `apps/admin/src/lib/assistant-transport.ts`'s already-shipped
 * `translateRunAgentPayload` switch render a BYOK-mode surface exactly like a daemon-mode one, with no
 * new frontend branching — see this module's own header for the full trace.
 *
 * Verified end-to-end for `'mcp-ui'` only (`assistant-byok-routes.test.ts`), the one channel a real
 * catalog tool (`content_post_delete`) uses today. Kept channel-agnostic, like its daemon
 * counterpart, so a future channel is not silently dropped — but an untested channel inherits that
 * counterpart's own disclosed scope, not a new guarantee this function makes.
 *
 * @complexity O(k) in `emission.payload`'s own key count.
 * @overallScore 100
 */
export function toWireSurfacePayload(emission: SurfaceEmission, toolUseId: string): Record<string, unknown> {
  const safePayload: Record<string, unknown> = { ...emission.payload };
  delete safePayload.type;
  delete safePayload.toolUseId;
  return {
    ...safePayload,
    type: emission.channel,
    ...(emission.channel === "mcp-ui" ? { toolUseId } : {}),
  };
}

/** Validate the BYOK wire entry before either current-turn selection or redaction. @complexity O(1). */
function readByokHistoryMessage({ entry }: { entry: unknown }, _options = {}): (ByokChatMessage & { secretRedacted: unknown }) | null {
  if (!isPlainMessage(entry)) return null;
  const role = entry.role === "user" || entry.role === "assistant" ? entry.role : null;
  if (role === null) return null;
  if (typeof entry.content !== "string" || entry.content.length === 0) return null;
  return { role, content: entry.content, secretRedacted: entry.secretRedacted };
}

/** ES2022-compatible reverse scan; malformed user entries never claim the current turn. @complexity O(n). */
function lastUserMessageIndex({ entries }: { entries: readonly unknown[] }, _options = {}): number {
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const entry = readByokHistoryMessage({ entry: entries[index] }, {});
    if (entry && entry.role === "user") return index;
  }
  return -1;
}

/** One raw history entry -> a valid {@link ByokChatMessage}, or `null` if it isn't one — the single
 *  per-entry validation `resolveMessages` below loops over. Always redacts user text; only the
 *  current user turn receives a notice. Does not mutate the entry or perform I/O.
 *  @complexity Redaction cost in the message content; constant validation work. */
function toByokChatMessage({ entry, currentUserTurn }: { entry: unknown; currentUserTurn: boolean }, _optional = {}): ByokChatMessage | null {
  const message = readByokHistoryMessage({ entry }, {});
  if (message === null) return null;
  const { role, content, secretRedacted } = message;
  const modelContent = role === "user" ? guardUserText({ text: content }, {
    modelNote: currentUserTurn ? CREDENTIAL_PASTE_MODEL_NOTE : "", secretRedacted: secretRedacted === true,
  }) : content;
  return { role, content: modelContent };
}

/** Validates and bounds the client-supplied history. Fail-soft on individual malformed entries
 *  (dropped, not rejected) — mirrors `site-assistant.ts`'s own `resolveBoundedHistory` posture for
 *  the sibling visitor-assistant route: history is passive background context the caller did not
 *  just author this instant, so a malformed entry degrades the turn's context rather than the whole
 *  request.
 *  @complexity O(n) entries plus per-message redaction cost; O(n) output space, no I/O. */
export function resolveMessages(raw: unknown): ByokChatMessage[] {
  if (!Array.isArray(raw)) return [];
  // Redact every user turn, but notify only for the latest valid user message. Historical flags
  // and raw historical secrets must not turn an unrelated request into another rotation warning.
  const currentUserIndex = lastUserMessageIndex({ entries: raw }, {});
  const messages: ByokChatMessage[] = [];
  for (const [index, entry] of raw.entries()) {
    const message = toByokChatMessage({ entry, currentUserTurn: index === currentUserIndex }, {});
    if (message) messages.push(message);
  }
  return messages.slice(-MAX_HISTORY_MESSAGES);
}

/**
 * Composes this route's `system` prompt in the fixed order §2.1 item 6 of
 * `design-byok-external-mcp-2026-09-24.md` specifies: {@link SYSTEM_PREAMBLE}, then the federation
 * runtime's own `refusalPrefix()` (when this turn's surface actually has drift to report), then
 * {@link FEDERATION_STILL_CONNECTING_NOTE} (when this turn's `awaitFederation` call timed out rather
 * than settling), then the admin Instructions tab's custom overlay (`core.instructions.custom`), when
 * the operator has set one — every present part joined with the Local CLI path's own separator
 * (`agent-daemon-server.ts`: `` `${base}\n\n${custom}` ``), so an operator's custom instructions still
 * apply identically in both execution modes rather than only to Local CLI runs, and a still-connecting
 * federation boot pass never silently withholds a tool the model would otherwise assume does not exist
 * (the same rule `agent-daemon-server.ts:643-647` already enforces for its own turns).
 *
 * `federation.refusalPrefix`/`federation.stillConnecting` are `handleTurn`'s own read of THIS turn's
 * `awaitFederation(FEDERATION_TURN_WAIT_MS)` outcome and `ByokToolSurface.federation?.refusalPrefix()`
 * — passed in rather than resolved here, since this function has no surface of its own to ask.
 *
 * Re-reads `core.instructions.custom` fresh on every call rather than caching it at module load or
 * across turns: this route has no long-lived process to refresh a cache against between requests (each
 * `handleTurn` invocation is its own request/response lifecycle), so a plain re-read is both simpler
 * and sufficient here — unlike the Local CLI path, which needs `custom-instructions.ts`'s
 * `createCustomInstructionsCache` bridge specifically because `PromptAugmenter.systemOverlay()` is
 * called synchronously inside the daemon's `run()`. `resolveCustomInstructions` never throws (fails
 * open to `""` on any read error) and `formatCustomInstructionsOverlay` returns `null` for unset,
 * empty, or whitespace-only text, so a turn with no federation drift/timeout and an operator who has
 * never opened the Instructions tab gets exactly {@link SYSTEM_PREAMBLE} back, unchanged.
 *
 * @complexity O(1) — one `resolveCustomInstructions` read (itself O(1)) plus a trim/length check.
 * @overallScore 100
 */
/**
 * How a BYOK turn ended, for its agent-run span. An abort (the browser went away) is `canceled`
 * whatever else happened; a throw is `failed` with that error. Provider adapters report their own
 * failures (an HTTP error, a blocked prompt, a bad baseUrl) as an `error` event and still resolve, so
 * a turn that resolved after reporting one is `failed` too: resolving alone is not success.
 * @complexity O(1), pure.
 */
export function byokTurnOutcome(
  { aborted, reportedError }: { aborted: boolean; reportedError: boolean },
  { thrown }: { thrown?: { error: unknown } } = {},
): { status: AgentRunStatus; error?: unknown } {
  if (aborted) return { status: "canceled" };
  if (thrown) return { status: "failed", error: thrown.error };
  return { status: reportedError ? "failed" : "succeeded" };
}

/**
 * Stamps each provider `usage` event with the wall time since the previous one (the first since
 * `startedAt`). Provider adapters report tokens only, and the chat's "Done · 16s" line needs a
 * `durationMs` (it shows nothing without time or cost); the client sums a turn's usage events, so
 * per-event deltas add up to the turn's elapsed time however many usage frames a provider streams.
 * No `costUsd`: there is no pricing table and the chat never estimates money from tokens.
 * @complexity O(1) per event; holds one timestamp.
 */
export function createByokUsageTimer(
  { startedAt }: { startedAt: number },
  { now = Date.now }: { now?: () => number } = {},
): (event: ByokTurnEvent) => ByokTurnEvent & { durationMs?: number } {
  let mark = startedAt;
  return (event) => {
    if (event.type !== "usage") return event;
    const at = now();
    const durationMs = Math.max(0, at - mark);
    mark = at;
    return { ...event, durationMs };
  };
}

async function resolveByokSystemPrompt(
  routeDeps: RouteDeps,
  federation: { readonly refusalPrefix: string; readonly stillConnecting: boolean },
): Promise<string> {
  const customInstructions = await resolveCustomInstructions(
    {
      settingsRepo: routeDeps.settingsRepo,
      settingsReady: routeDeps.settingsUiTabsReady,
      getEffective: routeDeps.getEffective,
      instructionsNamespace: routeDeps.instructionsNamespace,
    },
    { workspaceId: routeDeps.workspaceId },
  );
  const customOverlay = formatCustomInstructionsOverlay(customInstructions);
  const parts = [SYSTEM_PREAMBLE];
  if (federation.refusalPrefix.length > 0) parts.push(federation.refusalPrefix);
  if (federation.stillConnecting) parts.push(FEDERATION_STILL_CONNECTING_NOTE);
  if (customOverlay !== null) parts.push(customOverlay);
  return parts.join("\n\n");
}

/**
 * Return type widened past the generic {@link ServerModuleHandle} to also expose the composed
 * `toolSurface` — specifically so `app.ts` can capture `.toolSurface.surfaceExchanges` and hand it to
 * `createAssistantModule`'s redemption proxy WITHOUT importing `byok-tool-surface.ts` directly
 * itself. That's not a style preference: `app.ts` already transitively reaches `byok-tool-surface.ts`
 * through this module (which has always imported it), so reading the value off this return object
 * costs the composition root zero new edges in the dependency graph; a direct
 * `import { createByokToolSurface } from "../assistant/byok-tool-surface"` in `app.ts` would add one,
 * and — traced empirically via `npm run check:architecture` before landing this — that one new edge
 * from the highest-fan-out file in the whole codebase was enough to flip ~17 other files into the
 * "core" classification (both fan-in and fan-out above the graph median), regressing that ratcheted
 * metric. This shape gets the identical runtime behavior (one surface, built once, shared by both
 * modules) for zero graph cost.
 */
export interface AssistantByokModuleHandle extends ServerModuleHandle {
  readonly toolSurface: ByokToolSurface;
  /** Mounts the agent daemon's tool RPC over `toolSurface` (`assistant-tool-exec.ts`). */
  readonly registerToolExecRoutes: (required: { readonly router: ToolExecutionRouteTarget }) => void;
  /** Serving owner only: export/preview compositions must never replace its listener or reader. */
  readonly activateServerFederation: (required: { readonly router: ToolExecutionRouteTarget }, optional?: Record<string, never>) => void;
}

/**
 * @param toolSurface - Defaults to a fresh `createByokToolSurface(routeDeps)`, built once right here
 * when the caller doesn't supply one — the production path (`app.ts`) always takes this default, so
 * it never needs its own `byok-tool-surface.ts` import (see {@link AssistantByokModuleHandle}'s doc
 * for why that specifically matters). The explicit parameter exists for tests that need to observe or
 * override the composed surface — e.g. injecting a short-TTL `surfaceExchangeStore` via
 * `createByokToolSurface`'s own override to prove the no-hang bound in milliseconds rather than the
 * production 5.5-minute ceiling — without which this module would have no seam to reach it through.
 * Optional (rather than a plain default parameter) specifically so
 * `installFirstPartyToolContributors()` below is guaranteed to run BEFORE the default
 * `createByokToolSurface(routeDeps)` construction, not as part of evaluating this function's own
 * argument list — a default-parameter expression evaluates before the function body starts, which
 * would be too early for the install call to have any effect on the surface it composes.
 */
type ByokTurnInputs = { messages: ByokChatMessage[]; principal: Principal; credential: ResolvedByokCredential };

/** BYOK bypasses the daemon lifecycle, but publishes the same normalized model/tool events.
 * Reuse its recorder so both execution modes report generations with the same semantics. */
function startByokTrace(
  { routeDeps, run, credential, messages }: { routeDeps: Pick<RouteDeps, "aiTraceSink">; run: { id: string }; credential: ResolvedByokCredential; messages: ByokChatMessage[] },
  _optional = {},
) {
  const trace = routeDeps.aiTraceSink ? createAiTraceRecorder({ sink: routeDeps.aiTraceSink, runId: run.id, agentId: credential.protocol },
    { provider: credential.protocol, model: credential.model, exactSecrets: [credential.apiKey] }) : undefined;
  trace?.start(routeDeps.aiTraceSink?.capture === "full" ? { input: messages.at(-1)?.content ?? null } : {});
  return trace;
}

function byokTraceOutcome({ aborted, reportedError }: { aborted: boolean; reportedError: boolean }, _optional = {}): "cancelled" | "failed" | "succeeded" {
  const { status } = byokTurnOutcome({ aborted, reportedError });
  if (status === "canceled") return "cancelled";
  return status === "succeeded" ? "succeeded" : "failed";
}

/**
 * The two gates `handleTurn` must clear before it opens a stream: the client-supplied history must
 * resolve to a non-empty, user-ending message list, and a usable BYOK credential (request-supplied
 * or the admin's own stored row) must resolve. Both can end the request on their own; consolidated
 * here so `handleTurn` itself is a single `if (!inputs) return;` rather than two separate guards.
 */
async function resolveTurnInputsOrRespond(
  req: Request,
  res: Response,
  credentialPort: ExecutionCredentialPort,
  routeDeps: RouteDeps,
): Promise<ByokTurnInputs | null> {
  const body = (req.body ?? {}) as { messages?: unknown; byok?: RequestSuppliedByokConfig; pageContext?: unknown; attachmentIds?: unknown; folders?: unknown };
  const history = resolveMessages(body.messages);
  if (history.length === 0 || history[history.length - 1]?.role !== "user") {
    res.status(400).json({ error: "'messages' must end with a non-empty user message", code: "VALIDATION_ERROR" });
    return null;
  }
  // The admin screen block, same as a Local CLI run's (`run-page-context.ts`): degrade-only, so a
  // malformed `pageContext` means "the turn does not know the screen", never a rejected request.
  let folders: string[];
  try { folders = readPickedFolders({ value: body.folders }, {}); }
  catch { res.status(400).json({ error: "Invalid picked folders", code: "VALIDATION_ERROR" }); return null; }
  const messages = [...withPageContextBlock({ messages: history, pageContext: readRunPageContext(body.pageContext), folders })];

  const authed = getAuthedPrincipal(res);
  const credential = await credentialPort.resolve({
    requestBody: body.byok ?? {},
    workspaceId: routeDeps.workspaceId,
    principalId: authed.id,
  });
  if (!credential) {
    res.status(400).json({
      error:
        "no usable BYOK credential — supply 'byok' with a supported protocol, a non-empty apiKey, and a model, or save one first in Settings",
      code: "VALIDATION_ERROR",
    });
    return null;
  }

  if (!await attachTurnMessagesOrRespond({ attachmentIds: body.attachmentIds, messages, principalId: authed.id, routeDeps, res })) return null;
  return { messages, principal: { id: authed.id }, credential };
}

/** Validates attachment references and adds the owner-scoped byte preparation to the newest message.
 * Invalid or unavailable attachments stop the request before SSE begins; omitted references do nothing.
 * At most ten references are passed to the existing attachment preparation owner.
 * @complexity O(attachment bytes) preparation, with at most ten references; mutates the last message. */
async function attachTurnMessagesOrRespond({ attachmentIds, messages, principalId, routeDeps, res }: {
  attachmentIds: unknown; messages: ByokChatMessage[]; principalId: string; routeDeps: RouteDeps; res: Response;
}, _options: Record<string, never> = {}): Promise<boolean> {
  if (attachmentIds !== undefined) {
    if (!Array.isArray(attachmentIds) || attachmentIds.length > 10 ||
      attachmentIds.some(ref => typeof ref !== "string" || !ref)) {
      res.status(400).json({ error: "Invalid message attachments", code: "VALIDATION_ERROR" });
      return false;
    }
    try {
      const prepared = await prepareByokMessageAttachments({ refs: attachmentIds, principalId, uploadDirectory: routeDeps.siteStoragePaths.chatAttachmentsDir }, {});
      const last = messages[messages.length - 1]!;
      messages[messages.length - 1] = { ...last, content: last.content + prepared.notice, images: prepared.images };
    } catch {
      res.status(400).json({ error: "Attachment is unavailable. Reattach it before sending.", code: "VALIDATION_ERROR" });
      return false;
    }
  }
  return true;
}

interface LiveByokToolRun extends ToolAccessRun {
  serverIds: readonly string[]; pluginIds: readonly string[];
  readonly abort: AbortController; readonly done: Promise<void>; lowered: boolean; readonly res: Response;
}

/** Retain every source this dynamic BYOK catalog admitted, including sources later withdrawn.
 * @complexity O(admitted source IDs), memory only; no configuration or network reads. */
function rememberByokSources(run: LiveByokToolRun, sources: ReturnType<typeof admittedToolSources>): void {
  run.serverIds = [...new Set([...run.serverIds, ...sources.serverIds])];
  run.pluginIds = [...new Set([...run.pluginIds, ...sources.pluginIds])];
}

/** Access revocation is an owner's Stop even when a provider reports its aborted socket as error. */
function endByokResponse({ res, lowered, reason }: { res: Response; lowered: boolean; reason: string }): void {
  sse(res, 'end', { reason: lowered ? 'stop' : reason });
  res.end();
}

/** Preserve partial answer text and the access-change status emitted through the existing stream. */
function endFailedByokResponse({ res, error, lowered }: { res: Response; error: unknown; lowered: boolean }): void {
  if (!lowered) sse(res, 'error', { type: 'error', message: error instanceof Error ? error.message : String(error) });
  endByokResponse({ res, lowered, reason: 'error' });
}

/** A provider ignoring Stop must produce a failure rather than leave the OFF request hanging.
 * Existing handlers receive the aborted turn signal; this deadline never claims they completed.
 * @complexity O(1), one cleared timer per affected live provider turn. */
async function awaitByokCleanup(done: Promise<void>): Promise<void> {
  let timer: NodeJS.Timeout | undefined;
  try {
    await Promise.race([done, new Promise<void>((_resolve, reject) => {
      timer = setTimeout(() => reject(new ToolAccessLoweringError()), 4_000);
    })]);
  } finally { if (timer) clearTimeout(timer); }
}

/** @param optional.attachmentLookup Test seam for the daemon's attachment store (`assistant-tool-exec.ts`).
 * @param optional.federationConnect Existing transport port, forwarded for hermetic federation tests. */
export function createAssistantByokModule(
  routeDeps: RouteDeps & ByokToolSurfaceDeps,
  toolSurface?: ByokToolSurface,
  { attachmentLookup, federationConnect }: { attachmentLookup?: AttachmentLookup;
    federationConnect?: NonNullable<Parameters<typeof createByokToolSurface>[1]>["federationConnect"] } = {},
): AssistantByokModuleHandle {
  // Must run before `createByokToolSurface` (below, or the caller's own instance's earlier
  // construction) calls `buildAssistantToolRegistrations`: that function reads whatever
  // this composition's explicit core registries hold, and those registries start empty every
  // process boot. ADR-070 leaves this server as the site-tool registrar; the daemon discovers its
  // descriptors through RPC. Idempotent, so a test supplying its own `toolSurface`
  // (built from an already-installed registry) pays nothing extra for this still running.
  const contributions = {
    contributors: createContributionRegistry({ keyOf: ({ contribution }: { contribution: ToolContributor<AssistantToolRegistryDeps, AssistantSurfaceDeps> }) => contribution.domain }),
    derivedContributors: createContributionRegistry({ keyOf: ({ contribution }: { contribution: DerivedToolContributor<AssistantToolRegistryDeps, AssistantSurfaceDeps> }) => contribution.domain }),
  };
  let serverFederation: ReturnType<typeof createAssistantServerFederation>;
  const liveToolRuns = new Map<string, LiveByokToolRun>();
  /** Abort is the provider turn's existing Stop path and closes its signal-bound cards/tools.
   * No credentials are minted for provider-direct execution. Await the existing turn finally.
   * @complexity O(live runs), no I/O besides the existing Stop/cleanup paths. */
  async function lowerLocal(change: ToolAccessChange): Promise<void> {
    const selected = new Map(liveToolRuns);
    const current = admittedToolSources({ tools: resolvedToolSurface.registry.list({}) });
    for (const run of selected.values()) rememberByokSources(run, current);
    const result = await stopRunsForToolAccessChange({ runs: [...selected.values()], change,
      revoke: ({ runId }) => { const entry = selected.get(runId)!; entry.lowered = true; entry.abort.abort(); },
      cancel: async ({ runId }) => { automaticPluginRuns.forget({ runId }); },
      waitForCleanup: ({ runId }) => awaitByokCleanup(selected.get(runId)!.done),
      notice: async ({ runId, message }) => { const response = selected.get(runId)!.res; sse(response, 'agent', { type: 'status', label: message }); sse(response, 'agent', { type: 'text_delta', delta: `\n\n${message}` }); },
    }, {});
    if (result.failedRunIds.length) throw new ToolAccessLoweringError();
  }

  // `outboundTestOrigins` is set only by the site-import journey harness; absent, this factory is
  // `createDefaultHttpClient` itself (`platform/http/test-origin-allowlist.ts`).
  // The agent daemon's tool RPC runs on this same surface (`assistant-tool-exec.ts`); the daemon-call
  // adapters below change nothing for a BYOK turn.
  installFirstPartyToolContributors({ contributions }, { readAdmissions: () => serverFederation.admissions(),
    readExternalMcpToolNames: required => resolvedToolSurface.readExternalMcpToolNames(required, {}), observability: routeDeps.observability, chatAttachmentsDir: routeDeps.siteStoragePaths.chatAttachmentsDir,
    createHttpClient: createTestOriginHttpClientFactory({ allowedOrigins: routeDeps.outboundTestOrigins ?? [] }),
    readInstallAttachment: createDaemonAwareInstallAttachmentReader({ uploadDirectory: routeDeps.siteStoragePaths.chatAttachmentsDir }) });
  const surfaceDeps = routeDeps.conversationToolApprovals ? { ...routeDeps, nativeApprovalMemory: routeDeps.nativeApprovalMemory ?? createDaemonApprovalMemory({
    store: routeDeps.conversationToolApprovals, workspaceId: routeDeps.workspaceId, clock: routeDeps.clock }) } : routeDeps;
  // The public contract and both roots require complete BYOK dependencies;
  // no cast may conceal a missing runtime port.
  let automaticPluginRuns: ReturnType<typeof createAutomaticPluginRuns>;
  const resolvedToolSurface =
    toolSurface ??
    createByokToolSurface(surfaceDeps, {
      contributions,
      ...(federationConnect ? { federationConnect } : {}),
      // Preserve the daemon's remembered approval contract on the existing server confirmer.
      // Async call context supplies the current chat; no process-global last-chat binding.
      federationApprovals: {
        ...(routeDeps.externalMcpToolApprovalRepo ? { always: routeDeps.externalMcpToolApprovalRepo } : {}),
        ...(routeDeps.conversationToolApprovals ? { chat: routeDeps.conversationToolApprovals } : {}),
        conversationIdForRun: () => readDaemonCallContext()?.conversationId,
      },
      hostRegistrations: ({ registrations }) => buildDaemonAttachmentTools({ deps: routeDeps, registrations }, attachmentLookup ? { getLookup: () => attachmentLookup } : {}),
      prepareGuidance: (required, optional) => automaticPluginRuns.prepareGuidance(required, optional),
      // The root injects the audit sink; see RouteDeps.toolAttemptAuditSink for why
      // consumers must not open their own database. A supplied toolSurface bypasses this branch.
      toolAttemptAudit: { sink: routeDeps.toolAttemptAuditSink, workspaceId: routeDeps.workspaceId },
      // Feature registrars `assistant/` must not import by value (module cycles) — injected here.
      registerInstalledExtensions: async (registry, deps, log) => {
        await registerInstalledExtensionTools(registry, deps, log);
        // The awaited extension pass also lets the run controller bind to this surface below.
        registry.register(automaticPluginRuns.loadRegistration);
      },
    });
  automaticPluginRuns = createAutomaticPluginRuns({ deps: routeDeps, askAgentPluginChoice,
    surfaces: { surfaceExchanges: resolvedToolSurface.surfaceExchanges, assertAccessApprover: createAccessApprover(routeDeps) } });
  // Reuse the server's admission-aware adapters. No daemon federation or second registrar:
  // both catalog demand and execution await this same server surface's lazy startup.
  serverFederation = createAssistantServerFederation({ toolSurface: resolvedToolSurface }, { lowerLocal });
  const runStore = routeDeps.chatRunLedger.durable;
  if (runStore) assistantRunFinalizerFor({ ledger: routeDeps.chatRunLedger, tracker: routeDeps.tracker, observability: routeDeps.observability,
    onAttemptEnded: async ({ runId }) => {
      await findLiveSiteToolRun({ runId, runStore, workspaceId: routeDeps.workspaceId, plugins: { controller: automaticPluginRuns } });
    },
  }, {});
  const credentialPort = createStoredExecutionCredentialPort({
    repo: routeDeps.adminExecutionCredentialRepo,
    sealer: routeDeps.siteAssistantSecretSealer,
  });

  return {
    name: "assistant-byok",
    toolSurface: resolvedToolSurface,
    activateServerFederation: ({ router }) => {
      routeDeps.externalMcpAdmissions = serverFederation.admissions;
      serverFederation.registerRosterListener({}, {});
      registerDesktopMcpHandoff({ router, runtime: desktopMcpRuntime, reload: async () => {
        await serverFederation.reload({}, {});
        const report = await resolvedToolSurface.readFederationAdmissions({}, {});
        return report.connections.some(connection => connection.connectionId === "tovu-desktop");
      } }, {});
    },
    registerToolExecRoutes: ({ router }) => registerAssistantToolExecRoutes({ router, toolSurface: { daemonCalls: serverFederation.daemonCalls },
      runStore: routeDeps.chatRunLedger.durable, workspaceId: routeDeps.workspaceId, components: routeDeps, core: routeDeps,
      plugins: { controller: automaticPluginRuns, emit: publishDaemonPluginEvent,
        pinnedPrefix: async ({ pluginRefIds }) => {
          await Promise.all([routeDeps.pluginRuntimeReady, routeDeps.siteTitleReady]);
          const result = await resolveAgentPluginRefs(translateRetiredPluginRefs(pluginRefIds), routeDeps.agentPluginLayout.forWorkspace(routeDeps.workspaceId), 'inject');
          return result.ok ? result.promptPrefix : null;
        },
        refusalPrefix: () => resolvedToolSurface.federation?.refusalPrefix() ?? "",
      },
    }, {}),
    registerRoutes: (app: Express) => {
      app.use(BYOK_TURN_PATH, requireAdminSession(routeDeps));
      app.post(BYOK_TURN_PATH, (req: Request, res: Response, next: NextFunction) => {
        void handleTurn(req, res).catch((error: unknown) => {
          console.error("[assistant-byok] unhandled error", error);
          if (res.headersSent) {
            sse(res, "error", { message: "assistant failed" });
            res.end();
          } else {
            next(error);
          }
        });
      });
    },
  };

  /** Loads explicit picks independently, so one unavailable plugin cannot discard the others.
   * Returns the ordered prompt suffix and whether any pick failed; failures never escape.
   * @complexity One sequential lifecycle resolution per pinned reference; O(guidance bytes) space. */
  async function loadPinnedPluginGuidance({ pinned }: { pinned: string[] }, _options: Record<string, never> = {}): Promise<{ prefix: string; skippedPinned: boolean }> {
    let skippedPinned = false;
    let prefix = "";
    for (const pluginId of pinned) {
      // Explicit attachments bypass relevance matching, but a failed attachment must not end a run
      // or discard guidance from the other picks. The lifecycle still enforces activation and trust.
      try {
        const resolved = await resolveAgentPluginRefs([pluginId], routeDeps.agentPluginLayout.forWorkspace(routeDeps.workspaceId), 'inject');
        if (resolved.ok) prefix += `\n\n${resolved.promptPrefix}`;
        else skippedPinned = true;
      } catch { skippedPinned = true; }
    }
    return { prefix, skippedPinned };
  }

  /** Starts the existing automatic plugin lifecycle and appends its guidance; failure leaves the prompt intact.
   * Emits consent/usage surfaces through this turn's response and logs a preflight failure.
   * @complexity One automatic-use preparation; candidate discovery/ranking belongs to that owner. */
  async function appendAutomaticPluginGuidance({ run, principal, conversationId, pluginBody, messages, pinned, abort, res, system }: {
    run: { id: string }; principal: Principal; conversationId: string;
    pluginBody: { agentPluginState?: unknown; userPrompt?: unknown }; messages: ByokChatMessage[];
    pinned: string[]; abort: AbortController; res: Response; system: string;
  }, _options: Record<string, never> = {}): Promise<string> {
    try {
      const guidance = await automaticPluginRuns.start({ runId: run.id, context: {
        principal, conversationId, state: readChatAgentPluginState({ value: pluginBody.agentPluginState }),
        query: typeof pluginBody.userPrompt === 'string' ? pluginBody.userPrompt.slice(0, 16000) : messages[messages.length - 1]?.content ?? '', pinned, signal: abort.signal,
        emitSurface: async emission => { sse(res, 'agent', toWireSurfacePayload(emission, `agent-plugins:${run.id}`)); },
        publish: async value => { sse(res, 'agent', { type: 'agent_plugins', ...value }); },
      } });
      if (guidance) system += `\n\n${guidance}`;
    } catch { console.warn('[agent-plugins] automatic BYOK preflight unavailable'); }

    return system;
  }

  /** Composes pinned and automatic guidance before provider planning; plugin failures remain fail-soft.
   * Registers response-close cleanup and returns the augmented prompt.
   * @complexity O(pinned references + guidance bytes), plus the automatic lifecycle's preparation. */
  async function preparePluginGuidance({ req, res, run, principal, messages, abort, system }: {
    req: Request; res: Response; run: { id: string }; principal: Principal; messages: ByokChatMessage[]; abort: AbortController; system: string;
  }, _options: Record<string, never> = {}): Promise<string> {
    // Preflight uses the same catalog/consent/guidance owner as CLI, before the provider plans.
    const pluginBody = (req.body ?? {}) as { conversationId?: unknown; agentPluginState?: unknown; pluginRefIds?: unknown; userPrompt?: unknown };
    const conversationId = typeof pluginBody.conversationId === 'string' ? pluginBody.conversationId : undefined;
    const pinned = Array.isArray(pluginBody.pluginRefIds) ? pluginBody.pluginRefIds.filter((id): id is string => typeof id === 'string') : [];
    const { prefix, skippedPinned } = await loadPinnedPluginGuidance({ pinned });
    system += prefix;
    if (skippedPinned) sse(res, 'agent', { type: 'status', label: 'Some selected Agent Plugins could not be loaded and were skipped.' });
    res.on('close', () => automaticPluginRuns.forget({ runId: run.id }));
    if (!conversationId) return system;
    return appendAutomaticPluginGuidance({ run, principal, conversationId, pluginBody, messages, pinned, abort, res, system });
  }

  async function handleTurn(req: Request, res: Response): Promise<void> {
    const inputs = await resolveTurnInputsOrRespond(req, res, credentialPort, routeDeps);
    if (!inputs) return undefined;
    const { messages, principal, credential } = inputs;

    // `ready` resolves once the installed-extension-tools pass (Agent Plugins, Agent Skills, enabled
    // plugin-capability tools) has been applied to `resolvedToolSurface`'s registry AND its
    // `search_tools`/`describe_tool` catalog rebuilt to include them — see `ByokToolSurface.ready`'s
    // own doc. Awaited here, once per turn, so `search_tools` can find a just-registered extension
    // tool before the model's first tool call this turn, not only after it. Resolves instantly for
    // every turn after the first (the promise is already settled) and for a caller-supplied
    // `toolSurface` that predates this field, which has no `ready` to wait on at all.
    await (resolvedToolSurface.ready ?? Promise.resolve());

    // Starts (or awaits) this surface's lazy federation boot pass, bounded to
    // `FEDERATION_TURN_WAIT_MS` — see `ByokToolSurface.awaitFederation`'s own doc. Only a turn that
    // lands before the boot pass has settled can actually wait (a roster-change reload is never
    // awaited here); every later turn finds the boot pass already settled and this resolves at
    // once. `federation?.refusalPrefix()` reads whatever drift THIS surface has accumulated so far,
    // live — empty before federation has admitted anything, and always when this surface was built
    // with `installExtensions: false` (`federation` is `undefined` there).
    const federationOutcome = await resolvedToolSurface.awaitFederation(FEDERATION_TURN_WAIT_MS);
    let system = await resolveByokSystemPrompt(routeDeps, {
      refusalPrefix: resolvedToolSurface.federation?.refusalPrefix() ?? "",
      stillConnecting: !federationOutcome.settled,
    });

    const run = { id: randomUUID() };

    beginStream(req, res);
    // Same reasoning as `site-assistant.ts`'s identical guard: a browser tab closing must stop the
    // upstream provider call and any in-flight tool execution, not run to completion unobserved.
    const abort = new AbortController();
    let finishCleanup!: () => void;
    const done = new Promise<void>(resolve => { finishCleanup = resolve; });
    const liveToolRun = { runId: run.id, agentId: `api:${credential.protocol}`, ...admittedToolSources({ tools: resolvedToolSurface.registry.list({}) }), abort, done, lowered: false, res };
    liveToolRuns.set(run.id, liveToolRun);
    try {
      res.on("close", () => {
        if (!res.writableEnded) abort.abort();
      });

      system = await preparePluginGuidance({ req, res, run, principal, messages, abort, system });

      // Older injected surfaces retain their wrapper contract; production creates one exposure per run.
      const toolRun = resolvedToolSurface.createRun?.({ principal, run });

      // Starts with the meta-tool set and promotes concrete definitions after describe_tool.
      // The legacy dispatch below is owned by the same surface: `call.name` is one of
      // `search_tools`/`describe_tool`/`execute_delegated_tool`, and a real tool id arrives as the
      // third one's `toolId` argument. The unwrap, the status mapping, and the "model named something
      // that isn't callable" case all live in `byok-tool-surface.ts` beside the descriptors that
      // create them, so the two cannot drift apart. Authorization is unmoved by any of this — see
      // `META_TOOL_DESCRIPTORS`' own doc.
      //
      // `emitSurface` is built fresh per call (not once for the whole turn), because it needs THIS
      // call's own `call.id` as the correlation `toolUseId` a rendered mcp-ui card is tagged with —
      // `runByokProviderTurn`'s adapters invoke `executeTool` once per model-issued tool call, so a new
      // closure per invocation costs nothing a turn with real tool calls wasn't already paying.
      const executeTool = (call: { id: string; name: string; input: unknown }) => {
        abort.signal.throwIfAborted();
        rememberByokSources(liveToolRun, admittedToolSources({ tools: resolvedToolSurface.registry.list({}) }));
        const emitSurface: SurfaceEmitter = async (emission) => {
          sse(res, "agent", toWireSurfacePayload(emission, call.id));
        };
        if (toolRun) return toolRun.executeTool(call, { signal: abort.signal, emitSurface });
        return resolvedToolSurface.executeMetaTool(principal, run, call, abort.signal, emitSurface);
      };

      // One agent-run span per turn (its own trace root); the turn runs inside it, so its tool calls'
      // DB and outbound spans nest under the run rather than the long-lived request.
      return await routeDeps.tracker.trace({ name: "assistant.run", run: async (span) => {
        const aiTrace = startByokTrace({ routeDeps, run, credential, messages });
        routeDeps.tracker.capture({ name: "assistant_run_started", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.id, eventId: `assistant-start:${run.id}` } });
        let reportedError = false;
        // A failed turn (a provider error event or a throw, not an owner's cancel) is an incident for
        // the error tracker too: the protocol and run id only, the key blanked even without a known shape.
        const reportRunFailure = (error: unknown) => routeDeps.tracker.error({ error: error instanceof Error ? error : redactedError({ error }) }, { context: { operation: "assistant.run", attributes: { agent: credential.protocol, runId: run.id }, exactSecrets: [credential.apiKey] } });
        const stampUsage = createByokUsageTimer({ startedAt: Date.now() });
        function finishFailedTurn({ error }: { error: unknown }, _optional = {}): void {
          aiTrace?.observe({ type: "error", message: error instanceof Error ? error.message : String(error) });
          aiTrace?.finish({ outcome: abort.signal.aborted ? "cancelled" : "failed" });
          routeDeps.tracker.capture({ name: "assistant_run_finished", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.id, outcome: abort.signal.aborted ? "cancelled" : "failed", eventId: `assistant-finish:${run.id}` } });
          span.setOutcome(byokTurnOutcome({ aborted: abort.signal.aborted, reportedError }, { thrown: { error } }));
          if (!abort.signal.aborted && !reportedError) reportRunFailure(error);
          endFailedByokResponse({ res, error, lowered: liveToolRun.lowered });
        }
        let result: ByokProviderTurnResult;
        try {
          result = await runByokProviderTurn({
            protocol: credential.protocol,
            apiKey: credential.apiKey,
            ...(credential.baseUrl ? { baseUrl: credential.baseUrl } : {}),
            model: credential.model,
            ...(credential.maxTokens !== undefined ? { maxTokens: credential.maxTokens } : {}),
            maxToolTurns: BYOK_MAX_TOOL_TURNS,
            system,
            messages,
            // 3 descriptors, not all 131. The full catalog is ~119 KB (~30 k tokens) of `inputSchema`
            // re-sent on EVERY message; the meta-set is under 1 KB and initially reaches the same tools through
            // `search_tools` → `describe_tool` → `execute_delegated_tool`. See `META_TOOL_DESCRIPTORS`.
            tools: toolRun?.getToolSnapshot() ?? resolvedToolSurface.metaTools,
            getToolSnapshot: toolRun?.getToolSnapshot,
            onSchemaFallback: ({ toolId, protocol, reason }) => {
              console.warn("[assistant-byok] tool schema fallback", { toolId, protocol, reason });
            },
            executeTool,
            signal: abort.signal,
            // `error`-typed events get their OWN SSE event name, not folded into `agent` — mirrors the
            // daemon path's distinct `source.addEventListener("error", ...)` on the client
            // (`assistant-transport.ts`), which is what actually calls `handlers.onError` rather than
            // rendering an unrecognized `ext` event. Everything else rides `agent` unchanged, reusing
            // `translateRunAgentPayload`'s existing switch on the client with zero new cases.
            onEvent: (event: ByokTurnEvent) => {
              if (liveToolRun.lowered) return;
              aiTrace?.observe(event as unknown as Record<string, unknown>);
              // Reporting a disconnect's AbortError would mark this active span failed despite its canceled outcome.
              if (event.type === "error" && !abort.signal.aborted && !reportedError) { reportedError = true; reportRunFailure(new Error(event.message)); }
              sse(res, event.type === "error" ? "error" : "agent", stampUsage(event));
            },
          });
        } catch (error) {
          finishFailedTurn({ error });
          return;
        }

        span.setOutcome(byokTurnOutcome({ aborted: abort.signal.aborted, reportedError }));
        aiTrace?.finish({ outcome: byokTraceOutcome({ aborted: abort.signal.aborted, reportedError }) });
        routeDeps.tracker.capture({ name: "assistant_run_finished", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.id, outcome: byokTraceOutcome({ aborted: abort.signal.aborted, reportedError }), eventId: `assistant-finish:${run.id}` } });
        endByokResponse({ res, lowered: liveToolRun.lowered, reason: result.stopReason ?? 'stop' });
      } }, { agent: { runId: run.id, agentName: credential.protocol } });
    } catch (error) {
      if (!liveToolRun.lowered) throw error;
      return endByokResponse({ res, lowered: true, reason: 'stop' });
    } finally { liveToolRuns.delete(run.id); finishCleanup(); }
  }
}

import { readPickedFolders } from "#src/assistant/run-page-context";
/**
 * @file Durable chat history for the admin assistant — `GET/POST/PATCH/DELETE /api/assistant/chats`.
 *
 * Unlike its sibling `assistant.ts`, nothing here is proxied. Run execution belongs to the agent
 * daemon because that is where run state lives; transcripts belong to `content.db` because that is
 * where Tovu's data lives and where its backup, snapshot, and workspace scoping already work.
 * Splitting them that way means the daemon can restart, crash, or be replaced without history
 * being affected.
 *
 * Authorization is structural rather than per-route. `requireAdminSession` establishes *who* the
 * caller is, and `deps.chatHistory(principal)` hands back a store that can only see that
 * principal's own conversations (`assistant/persistence/tenant-scope.ts`). No handler below holds
 * a database handle, so none of them can accidentally write a query that omits the owner — the
 * omission this design exists to prevent.
 *
 * Not mounted here, deliberately: anything for anonymous visitors. The public assistant is
 * default-off (`assistant/public-assistant-settings.ts`) and its routes will need their own
 * cookie-based principal, its own rate limiting, and its own TTL. Reusing an admin-session-gated
 * router for it by loosening this middleware would be the easiest way to hand a visitor an admin
 * scope, so the two get separate mounts.
 */
import type { Express, Request, Response } from "express";
import { Readable, pipeline } from "node:stream";
import { readPreviousAssistantDaemon } from "../../lifecycle/assistant-daemon-registry.js";

import { deriveContentConversationTitle } from "#src/assistant/content-chat-title";
import { MAX_CONVERSATION_TITLE_LENGTH, deriveConversationTitle, redactUserMessage, redactUserText } from "@jini-ai/chat/core";
import type { ChatHistoryStore, ChatMessage } from "@jini-ai/chat/core";

import { getAuthedPrincipal, requireAdminSession } from "#src/server/inbound/admin-http/dev-auth";
import type { RouteDeps } from "#src/server/routes/types";
import { runEventsForSave } from "#src/contracts/core/assistant-run-events";
import type { ServerModuleHandle } from "./types.js";
import { assistantRunFinalizerFor, createHttpRunDaemonClient, type AssistantRunFinalizer } from "./assistant-run-finalizer.js";
import { createNoopObservabilityPort } from "#src/platform/observability/index";

/** Preserve a standalone resource name (including skill slugs) verbatim. Prose still follows
 * the shared heuristic; injected guidance never enters the stored user message. */
function deriveAssistantConversationTitle(text: string): string {
  return deriveContentConversationTitle({ prompt: text, deriveFallback: deriveConversationTitle });
}

/** Rejects a body that is not a plain object, so `req.body.title` can never be an array or null. */
function bodyOf(req: Request): Record<string, unknown> {
  const body = req.body as unknown;
  return body !== null && typeof body === "object" && !Array.isArray(body)
    ? (body as Record<string, unknown>)
    : {};
}

/**
 * Naming happens on append, not only at create time, because the admin dock creates the
 * conversation when "New" is clicked — before any prompt has been typed — so the create route's
 * `firstMessage` seed is never populated on that path and every admin chat stayed permanently
 * "Untitled". Deriving on append is what actually names them.
 *
 * Guarded on the title still being empty rather than on `title_source`: the store's no-clobber
 * guard only applies to `generated`, and a `fallback` rename would happily overwrite a manual one.
 * "Only name a chat that has no name" cannot do that, and it also self-limits — once a title
 * lands, this stops firing. A first prompt that yields no usable title (a bare URL, only
 * punctuation) leaves the chat unnamed and lets the next message name it, which is better than
 * locking in a blank.
 *
 * Deliberately swallows its own errors: a naming failure must never turn a successfully persisted
 * message into an error response. Only fires for a `user` message — an assistant reply is never
 * the source of a conversation's title.
 */
async function maybeNameFromFirstUserMessage(
  store: ChatHistoryStore,
  id: string,
  message: ChatMessage,
): Promise<void> {
  if (message.role !== "user") return;
  try {
    const conversation = await store.get({ id });
    if (!conversation || conversation.title) return;
    // The already-redacted message, never the raw request body: a credential pasted into the first
    // prompt must not survive into the title, which is stored and listed in plain text.
    const derived = deriveAssistantConversationTitle(message.content);
    if (derived) await store.rename({ id, title: derived }, { source: "fallback" });
  } catch {
    // Leave it untitled; the next user message gets another chance.
  }
}

export interface AssistantChatsModuleOptions {
  /** Tests inject one with a fake daemon; production builds the real one over `deps.chatRunLedger`. */
  readonly finalizer?: AssistantRunFinalizer;
  /** Only the site-serving composition opts in; export apps must never repair live turns. */
  readonly recoverInterrupted?: boolean;
  readonly onBootWork?: (work: Promise<void>) => void;
}

export function createAssistantChatsModule(deps: RouteDeps, options: AssistantChatsModuleOptions = {}): ServerModuleHandle {
  const finalizer = options.finalizer ?? assistantRunFinalizerFor({
    ledger: deps.chatRunLedger, tracker: deps.tracker, observability: deps.observability,
    ...(options.recoverInterrupted && deps.siteBinding?.dir ? {
      recoveryDaemon: createHttpRunDaemonClient({ observability: deps.observability ?? createNoopObservabilityPort({}) }, {
        previousDaemon: () => readPreviousAssistantDaemon({ siteDir: deps.siteBinding.dir }, {}),
      }),
    } : {}),
  });
  return {
    name: "assistant-chats",
    registerRoutes: (app: Express) => {
      /*
       * Serving-boot repair, before chat routes answer: a queued/running turn may still belong to
       * a live detached daemon, so dispatch each unfinished binding to the shared coordinator. It
       * reattaches live attempts, waits for uncertainty, and continues dead attempts within the
       * saved budget. Child teardown is best
       * effort, not proof of death. Route registration also happens during static exports inside the
       * daemon (and eagerly on importing app.ts); those are not restarts and must never sweep.
       */
      const reconciled = (options.recoverInterrupted ? finalizer.reconcileInterrupted({}, {}) : Promise.resolve(0)).then(
        (repaired) => {
          if (repaired > 0) console.log(`[assistant-chats] dispatched ${repaired} unfinished chat turn(s) to recovery`);
        },
        (error: unknown) => {
          // A failed repair leaves rows `running` (the pane shows them spinning); it must not keep
          // every chat route down with it.
          console.error("[assistant-chats] boot-time repair of interrupted chat turns failed", error);
        }
      );
      if (options.recoverInterrupted) options.onBootWork?.(reconciled);

      app.use("/api/assistant/chats", requireAdminSession(deps));
      // The repair is async now (storage kernel); no chat route answers until it has finished.
      app.use("/api/assistant/chats", (_req, _res, next) => {
        void reconciled.then(() => next());
      });

      /** The store for whoever is making this request, and nobody else. */
      function storeFor(res: Response) {
        const principal = getAuthedPrincipal(res);
        return deps.chatHistory({
          kind: "user",
          workspaceId: deps.workspaceId,
          userId: principal.id,
        });
      }

      app.get("/api/assistant/chats", (_req, res, next) => {
        storeFor(res)
          .list()
          .then((conversations) => res.json({ conversations }))
          .catch(next);
      });

      app.post("/api/assistant/chats", (req, res, next) => {
        const body = bodyOf(req);
        const id = typeof body.id === "string" && body.id ? body.id : crypto.randomUUID();
        // A title derived from the first prompt, when the client sends one. Local and synchronous
        // — a conversation needs a name the moment it appears in the list, and a model call to
        // produce one would put a spinner in front of every "New chat".
        const seed = typeof body.firstMessage === "string" ? deriveAssistantConversationTitle(redactUserText({ text: body.firstMessage }).text) : "";
        storeFor(res)
          .create({
            id,
            ...(seed ? { title: seed, titleSource: "fallback" as const } : {}),
          })
          .then((conversation) => {
            // Owner-action product event (consent-gated port): a chat was started; never its text.
            deps.tracker.capture({ name: "assistant_chat_started", userId: getAuthedPrincipal(res).id }, { properties: { chatSurface: "admin", conversationId: conversation.id, source: "admin", eventId: `assistant-chat:${conversation.id}` } });
            res.status(201).json({ conversation });
          })
          .catch(next);
      });

      app.patch("/api/assistant/chats/:id", (req, res, next) => {
        const body = bodyOf(req);
        const title = typeof body.title === "string" ? body.title.trim() : "";
        if (!title) {
          res.status(400).json({ error: "'title' must be a non-empty string", code: "VALIDATION_ERROR" });
          return;
        }
        if (title.length > MAX_CONVERSATION_TITLE_LENGTH) {
          res.status(400).json({ error: `'title' must be at most ${MAX_CONVERSATION_TITLE_LENGTH} characters`, code: "VALIDATION_ERROR" });
          return;
        }
        // `source` defaults to `manual` in the store. A caller may pass `generated` for an
        // agent-produced title, which the store then refuses to apply over a manual rename.
        const source = body.source === "generated" ? ("generated" as const) : ("manual" as const);
        storeFor(res)
          .rename({ id: req.params.id!, title }, { source })
          .then((conversation) =>
            // `null` means the id does not exist *or* belongs to someone else. Both answer 404, on
            // purpose: distinguishing them would confirm the existence of another admin's chat.
            conversation ? res.json({ conversation }) : res.status(404).json({ error: "not found" }),
          )
          .catch(next);
      });

      app.delete("/api/assistant/chats/:id", (req, res, next) => {
        // Cancel before deleting the binding. Once cascaded away, recovery cannot recreate it.
        const store = storeFor(res);
        store.messages({ conversationId: req.params.id! }, { includeEvents: false }).then(async (messages) => {
          for (const message of messages) {
            if (!message.runId || !["queued", "running"].includes(message.runStatus ?? "")) continue;
            await deps.chatRunLedger.durable?.cancel({ runId: message.runId, reason: "conversation-deleted" }, {});
            await finalizer.recover({ messageId: message.id, trigger: "browser" }, {});
          }
          await store.delete({ id: req.params.id! });
        })
          .then(() => res.status(204).end())
          .catch(next);
      });

      app.get("/api/assistant/chats/:id/messages", (req, res, next) => {
        const store = storeFor(res);
        // Resolve the cheap validator before borrowing any raw history strings. Keep the version
        // read before the payload read: a racing write then invalidates the next refresh safely.
        void (async () => {
          const version = await store.messagesVersion?.({ conversationId: req.params.id! }, {});
          if (version != null) {
            const etag = '"' + encodeURIComponent(version) + '"';
            res.setHeader('ETag', etag);
            res.setHeader('Cache-Control', 'private, no-store');
            if (req.query?.ifVersion === etag) { res.json({ unchanged: true }); return; }
          }
          if (store.messagesJson) {
            // Native stream piping honors socket backpressure without building one enormous JSON body.
            const chunks = await store.messagesJson({ conversationId: req.params.id! }, {});
            pipeline(Readable.from(chunks, { objectMode: false }), res.type("json"), error => {
              if (error && (error as NodeJS.ErrnoException).code !== 'ERR_STREAM_PREMATURE_CLOSE') next(error);
            });
            return;
          }
          res.json({ messages: await store.messages({ conversationId: req.params.id! }) });
        })().catch(next);
      });

      app.put("/api/assistant/chats/:id/messages/:messageId", (req, res, next) => {
        const body = bodyOf(req);
        if (body.role !== "user" && body.role !== "assistant") {
          res.status(400).json({ error: "'role' must be 'user' or 'assistant'", code: "VALIDATION_ERROR" });
          return;
        }
        if (typeof body.content !== "string") {
          res.status(400).json({ error: "'content' must be a string", code: "VALIDATION_ERROR" });
          return;
        }
        try { readPickedFolders({ value: body.folders }, {}); }
        catch { res.status(400).json({ error: "Invalid picked folders", code: "VALIDATION_ERROR" }); return; }
        const sent = body as unknown as ChatMessage;
        const message: ChatMessage = redactUserMessage({ message: {
          ...sent,
          id: req.params.messageId!,
          // Streamed text deltas saved as one event per run, the same shape the server finalizer writes.
          ...(Array.isArray(sent.events) ? { events: runEventsForSave(sent.events) } : {}),
        } }).message;
        const id = req.params.id!;
        const store = storeFor(res);
        store
          .appendMessage({ conversationId: id, message })
          .then(async (saved) => {
            if (!saved) {
              res.status(404).json({ error: "not found" });
              return;
            }
            if (saved.role === "user") deps.tracker.capture({ name: "assistant_message_sent", userId: getAuthedPrincipal(res).id }, { properties: { chatSurface: "admin", conversationId: id, inputKind: "text", eventId: `assistant-message:${saved.id}` } });
            await maybeNameFromFirstUserMessage(store, id, message);
            // The in-flight stub of a daemon run is the one moment the server learns which row a
            // run belongs to. From here the server saves the finished turn itself, so it no longer
            // depends on this browser staying connected (`assistant-run-finalizer.ts`). A no-op for
            // anything that is not an in-flight daemon run.
            // Acceptance already starts the authoritative watch; a browser save merely returns
            // that row. Re-reading its attempt base prevents a replay from erasing prior segments.
            const runStore = deps.chatRunLedger.durable;
            const durable = runStore && await (runStore.head ?? runStore.load)({ messageId: saved.id }, { events: false });
            finalizer.watch({ principalId: getAuthedPrincipal(res).id, conversationId: id, message: saved }, { attemptBase: [...(durable?.attemptBase ?? [])] });
            res.json({ message: saved });
          })
          .catch(next);
      });
    },
  };
}

import { assistantDaemonToken } from "../../lifecycle/assistant-daemon-connection.js";
import { redactSecrets } from '@jini-ai/core';
import { maskLocalPaths } from '@jini-ai/diagnostics';
import { redactAdminRunContextRef } from "#src/assistant/credential-chat-intake";
import { tryRestoreSurface } from '@jini-ai/daemon/http';
/**
 * @file ADR-049 (process-shape correction) — Tovu never spawns a coding-agent CLI itself. This
 * module is a thin, session-authenticated reverse proxy in front of the standalone agent daemon
 * (`src/assistant/agent-daemon-server.ts`, a separate OS process `src/index.ts` spawns after its
 * own boot completes). It owns exactly one thing the daemon cannot: verifying the browser's admin
 * session. Everything downstream of that is the daemon's to decide, so this module's job is to
 * report the verified principal accurately and nothing more — stamped into a new run's
 * `contextRef` at creation, and asserted in `RUN_PRINCIPAL_HEADER` on every request thereafter so
 * the daemon can compare it against the run's recorded owner (`src/assistant/run-ownership.ts`).
 * Authorization deliberately does NOT live here: the daemon owns run state, so it is the only
 * process where an ownership record and the run it protects share a lifetime.
 *
 * `/api/delegated-tool-calls` is NOT mounted here. Tool execution moved into the daemon process
 * entirely (see that file's module doc for why: `DelegatedToolBridge` writes `tool_use`/
 * `tool_result` straight into the run's own event log via `lifecycle.emit()`, so it has to live
 * wherever that `RunLifecycle` really is). A spawned CLI's injected `.mcp.json` calls the
 * daemon's own origin directly — this module is never in that path.
 *
 * Authentication, both directions: inbound, `requireAdminSession` gates every route below.
 * Outbound, `forwardToAgentDaemon` attaches `Authorization: Bearer <TOVU_AGENT_DAEMON_TOKEN>` —
 * the daemon rejects any request without it (`src/assistant/daemon-auth.ts`), so this proxy is the
 * only thing on the machine that can reach it. That env var is read INSIDE the request path, never
 * at module scope: ES module imports are all evaluated before `src/index.ts`'s own top-level
 * `main()` call runs, and `main()` is what mints the token — a module-scope read would capture
 * `undefined` forever. `getAgentDaemonUrl()` below (2026-08-28 dispatch) is now resolved the same
 * way, for a related but distinct reason: see `runtime/lifecycle/agent-daemon-port.ts`'s header.
 *
 * Header forwarding: `Last-Event-ID` is forwarded on every proxied request. The daemon's SSE route
 * (`@jini-ai/http-kit`'s `requestedAfterCursor`) reads exactly that header to resume a stream after
 * a cursor; dropping it made a browser tab's automatic `EventSource` reconnect replay the run's
 * entire event history from the start, duplicating every message already shown in the chat pane.
 *
 * MCP-UI redemption is no longer a pure passthrough. `proxyMcpUiToolCall` now tries LOCAL delivery
 * first, against `byokSurfaceExchanges` — the same `SurfaceExchangeStore` reference
 * `modules/assistant-byok.ts` composed its tool surface with, passed in by `app.ts` at boot (not
 * rebuilt here; a second instance would leave every BYOK-mode exchange unreachable). Only when that
 * store reports `unknown-or-closed` — meaning the exchange isn't one of this process's own BYOK
 * parks — does the request fall through to the daemon, on the theory that it belongs to a Local CLI
 * run instead. A `binding-mismatch` is answered locally without forwarding: that reason means the
 * exchange WAS found here, just not for this caller, and forwarding an id the daemon has never seen
 * would only spend a wasted round trip discovering the same 409 the local store already knows.
 *
 * The daemon-talking plumbing below (`getAgentDaemonUrl`, `outboundHeaders`, the retry/known-failed
 * `fetch` wrapper) moved to `assistant-daemon-client.ts` (2026-08-18, ADR-059) so
 * `assistant-ag-ui.ts` can reach the same daemon process without duplicating it. Pure extraction —
 * every function this file still calls has the exact body it had inline here before the split.
 */
import { ensureAssistantDaemonReady, isAssistantDaemonReady } from "../../lifecycle/daemon-supervisor.js";
import type { AgentSummary } from "@jini-ai/daemon/http";
import type { Express, NextFunction, Request, Response } from "express";

import {
  A2UI_ACTIONS_PATH,
  a2uiNotPendingBody,
  deliverA2uiAction,
  createLiveModelDiscovery,
  fetchLiveClaudeModels,
  type LiveModelDiscovery,
  unionModels,
  isMcpUiToolCallPermitted,
  MCP_UI_TYPED_ANSWER_REFUSAL,
  isTypedSurfaceAnswer,
  MCP_UI_TOOL_CALLS_PATH,
  readA2uiAction,
  RUN_PRINCIPAL_HEADER,
  SURFACE_EXCHANGE_ID_PARAM,
  type SurfaceExchangeStore,
} from "#src/assistant/index";
import { getAuthedPrincipal, rejectUnlessSessionCredential, requireAdminSession } from "#src/server/inbound/admin-http/dev-auth";
import { registerAdminChatAttachmentReadRoute } from "#src/server/inbound/admin-http/routes/assistant/get-chat-attachment";
import type { RouteDeps } from "#src/server/routes/types";

import { daemonFetch, getAgentDaemonUrl, fetchAgentDaemon, forwardToAgentDaemon, parkColdFrontendStream, awaitDaemonForResponse, respondIfDaemonKnownFailed, type DaemonCallOptions } from "./assistant-daemon-client.js";
import type { ServerModuleHandle } from "./types.js";
import { randomUUID } from "node:crypto";
import { createRunAcceptance } from "#src/assistant/durable-runs/accept";
import { assistantRunFinalizerFor, createHttpRunDaemonClient } from "./assistant-run-finalizer.js";
import type { DurableRun, DurableRunHead, DurableRunPoll } from "#src/assistant/durable-runs/ports";
import { RunSlotBusyError } from "#src/assistant/persistence/durable-run-store";

/** The API composition uses the real lifecycle; route tests inject discovery-free demand ports. */
type AssistantRouteDeps = RouteDeps & {
  assistantDaemonDemand?: { ensureReady: typeof ensureAssistantDaemonReady; isReady: () => boolean };
};

/** Streams `upstream`'s response back onto `res` as it arrives — required for the SSE run-events
 * endpoint, where buffering the whole body first would defeat live streaming entirely.
 *
 * Cancels on `res`'s `"close"`, not `req`'s. Node's `IncomingMessage` ("`req`") emits `"close"` once
 * its body has been fully consumed — for a request with a JSON body (e.g. `POST /api/runs`, whose
 * body Express's global `express.json()` parser (`src/server/app.ts`) already reads in full before
 * this function ever runs), that happens almost immediately, independent of the actual client
 * connection. A listener attached here — necessarily AFTER the `await fetch(...)` to the daemon in
 * `forwardToAgentDaemon`, itself after body-parsing — is registered too late to ever observe that
 * emission, so `req.on("close", ...)` was silently inert for every proxied POST: measured directly
 * (2026-08-05, isolated repro against this exact Express/Node version — see QA/E2E's report), an
 * identical EARLY listener caught `"close"` ~1ms after body-parsing, ~200ms before the response was
 * even sent, while a LATE listener at this function's real placement never fired at all. `res.on
 * ("close")`, by contrast, ties to the response's own lifecycle (finishes normally, or the
 * connection is torn down) — measured to fire correctly in both directions: never early on a
 * healthy request (POST or a fully-read multi-chunk SSE stream), and immediately on a genuine
 * mid-flight disconnect (POST or SSE). Same remedy `@jini-ai/daemon`'s http-kit commit `898303a5`
 * documents for the identical failure. */
async function relayResponse(upstream: globalThis.Response, req: Request, res: Response): Promise<void> {
  res.status(upstream.status);
  const contentType = upstream.headers.get("content-type");
  if (contentType) res.setHeader("Content-Type", contentType);
  if (!upstream.body) {
    res.end();
    return;
  }
  const reader = upstream.body.getReader();
  res.on("close", () => {
    reader.cancel().catch(() => undefined);
  });
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      res.write(value);
    }
  } finally {
    res.end();
  }
}

/** True for a JSON object body, false for an array/null/primitive — same guard
 *  `mcp-ui-tool-calls-route.ts` uses for the identical `body.params` shape on the daemon side. */
function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** The one route that needs its body rewritten before forwarding: stamps the session-authenticated
 * principal into `contextRef` so the daemon (no cookie of its own) can answer `resolveDelegatedPrincipal`
 * for this run later, and can record who owns it. Every other route is a transparent pass-through
 * — they carry the same principal in a header instead, since they have no body to stamp. */
async function proxyRunStart(req: Request, res: Response, daemon: DaemonCallOptions, deps: AssistantRouteDeps): Promise<void> {
  const principal = getAuthedPrincipal(res);
  const body = (req.body ?? {}) as { contextRef?: unknown; agentId?: unknown; idempotencyKey?: unknown };

  let decoded: Record<string, unknown>;
  try {
    decoded = JSON.parse(redactAdminRunContextRef({ contextRef: typeof body.contextRef === "string" ? body.contextRef : "{}" }, {})) as Record<string, unknown>;
  } catch {
    res.status(400).json({ error: "'contextRef' must be a JSON-encoded object", code: "VALIDATION_ERROR" });
    return;
  }

  if (!isPlainObject(decoded)) {
    res.status(400).json({ error: "'contextRef' must be a JSON-encoded object", code: "VALIDATION_ERROR" }); return;
  }
  // Recovery session choices are server decisions, never client-controlled launch fields.
  delete decoded.recoveryMode;
  delete decoded.recoverySessionId;
  if (await proxyAcceptedRun({ decoded, body, deps, res }, {})) return;
  const upstream = await forwardToAgentDaemon(req, res, {
    ...body,
    contextRef: JSON.stringify({ ...decoded, principalId: principal.id }),
  }, daemon);
  if (!upstream) return;
  await relayResponse(upstream, req, res);
}

async function proxyAcceptedRun(
  { decoded, body, deps, res }: { decoded: Record<string, unknown>; body: { agentId?: unknown }; deps: AssistantRouteDeps; res: Response }, _optional = {},
): Promise<boolean> {
  const principal = getAuthedPrincipal(res);
  const durable = deps.chatRunLedger.durable;
  if (durable && typeof decoded.conversationId === "string" && typeof decoded.assistantMessageId === "string") {
    const finalizer = assistantRunFinalizerFor({ ledger: deps.chatRunLedger, tracker: deps.tracker, observability: deps.observability }, {});
    const client = createHttpRunDaemonClient({ observability: deps.observability }, { ensureReady: deps.assistantDaemonDemand?.ensureReady });
    const acceptance = createRunAcceptance({ store: durable, now: Date.now, mintRunId: randomUUID,
      onAccepted: ({ run }) => deps.tracker.capture({ name: "assistant_run_started", userId: principal.id }, { properties: { chatSurface: "admin", logicalRunId: run.messageId, eventId: `assistant-start:${run.messageId}` } }),
      launch: (required, optional) => client.launch!(required, optional),
      attach: (run) => finalizer.watch({ principalId: principal.id, conversationId: run.conversationId, message: run.message }),
    }, {});
    const run = await acceptance.accept({ principalId: principal.id, workspaceId: deps.workspaceId,
      conversationId: decoded.conversationId, messageId: decoded.assistantMessageId,
      request: { ...(typeof body.agentId === "string" ? { agentId: body.agentId } : {}), contextRef: JSON.stringify({ ...decoded, principalId: principal.id }) },
    }, {});
    if (!run) { res.status(404).json({ error: "not found" }); return true; }
    res.status(201).json({ run: { id: run.runId }, messageId: run.messageId, conversationId: run.conversationId });
    return true;
  }
  return false;
}

async function proxyPassthrough(req: Request, res: Response, daemon: DaemonCallOptions): Promise<void> {
  const upstream = await forwardToAgentDaemon(req, res, req.method === "GET" || req.method === "HEAD" ? undefined : req.body, daemon);
  if (!upstream) return;
  await relayResponse(upstream, req, res);
}

/** Prove intake is still accepting before asking the browser to rebind. Discovery alone can race
 * idle teardown; the existing cheap context read resets idle credit and retries a park refusal.
 * @complexity At most two bounded demand sends; no session or mutating request is created. */
export async function activateFrontendDaemon({ req, res }: { req: Request; res: Response }, daemon: DaemonCallOptions = {}): Promise<void> {
  const response = await fetchAgentDaemon(req, res, { ...daemon, path: "/api/active", method: "GET" });
  if (!response) return;
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => undefined);
    const detail = maskLocalPaths({ text: redactSecrets({ input: JSON.stringify(body ?? { status: response.status }) },
      { exactSecrets: [assistantDaemonToken({}, {})].filter((value): value is string => Boolean(value)) }) }).slice(0, 2048);
    res.status(response.status).json({ error: 'The assistant could not attach to this page. Retry your message; if it keeps failing, restart the site.',
      code: 'FRONTEND_ACTIVATION_FAILED', detail: `GET /api/active: HTTP ${response.status}; ${detail}` });
    return;
  }
  await response.body?.cancel();
  res.sendStatus(204);
}

async function ownedDurableRun({ req, res, deps }: { req: Request; res: Response; deps: AssistantRouteDeps }, _optional = {}): Promise<DurableRunHead | null> {
  const store = deps.chatRunLedger.durable;
  if (!store) return null;
  const principalId = getAuthedPrincipal(res).id;
  const messageId = req.method === "GET" ? req.query.messageId : (req.body as { messageId?: unknown } | undefined)?.messageId;
  const run = typeof messageId === "string" ? await (store.head ?? store.load)({ messageId }, {}) : await store.find({ runId: req.params.runId!, principalId }, {});
  return run?.principalId === principalId && run.workspaceId === deps.workspaceId ? run : null;
}

/** Write raw JSON from the store without reserializing its event tree. An unchanged owned
 * projection is an empty 304, so cancelled/quiet polls do not churn multi-MB bodies.
 */
function sendDurableCheckpoint({ res, result }: { res: Response; result: DurableRunPoll }, _options = {}): void {
  res.setHeader('ETag', '"' + result.cursor + '"');
  res.setHeader('Cache-Control', 'private, no-store');
  if (result.messageJson === undefined) { res.status(304).end(); return; }
  res.type('json');
  res.write('{"conversationId":' + JSON.stringify(result.conversationId) + ',"message":');
  res.write(result.messageJson);
  res.end('}');
}

/** Routine polls read the owned saved projection; only recovery signals invoke the finalizer. */
async function readDurableCheckpoint({ req, res, deps }: { req: Request; res: Response; deps: AssistantRouteDeps }, _optional = {}): Promise<void> {
  const store = deps.chatRunLedger.durable;
  const messageId = req.query.messageId;
  if (store?.poll && typeof messageId === 'string') {
    const etag = req.get('If-None-Match');
    const cursor = etag?.match(/^"([a-zA-Z0-9%:-]{1,256})"$/)?.[1];
    const result = await store.poll({ messageId, principalId: getAuthedPrincipal(res).id, workspaceId: deps.workspaceId },
      cursor === undefined ? {} : { cursor });
    if (!result) { res.status(404).json({ error: 'not found' }); return; }
    sendDurableCheckpoint({ res, result });
    return;
  }
  const run = await ownedDurableRun({ req, res, deps }, {});
  if (!run) { res.status(404).json({ error: "not found" }); return; }
  res.json({ message: run.message, conversationId: run.conversationId });
}

async function recoverDurableRun({ req, res, deps }: { req: Request; res: Response; deps: AssistantRouteDeps }, _optional = {}): Promise<void> {
  const run = await ownedDurableRun({ req, res, deps }, {});
  if (!run) { res.status(404).json({ error: "not found" }); return; }
  const finalizer = assistantRunFinalizerFor({ ledger: deps.chatRunLedger, tracker: deps.tracker, observability: deps.observability }, {});
  await finalizer.recover({ messageId: run.messageId, trigger: "browser" }, {});
  const store = deps.chatRunLedger.durable!;
  const current = await (store.head ?? store.load)({ messageId: run.messageId }, {});
  if (!current) { res.status(404).json({ error: "not found" }); return; }
  res.json({ message: current.message, conversationId: current.conversationId });
}

async function cancelDurableRun({ req, res, deps, daemon }: { req: Request; res: Response; deps: AssistantRouteDeps; daemon: DaemonCallOptions }, _optional = {}): Promise<void> {
  let run = await ownedDurableRun({ req, res, deps }, {});
  if (!run) run = await cancelBeforeAcceptance({ req, res, deps }, {});
  if (!run) { await proxyPassthrough(req, res, daemon); return; }
  await deps.chatRunLedger.durable!.cancel({ runId: run.runId, reason: "user-stop" }, {});
  await assistantRunFinalizerFor({ ledger: deps.chatRunLedger, tracker: deps.tracker, observability: deps.observability }, {})
    .recover({ messageId: run.messageId, trigger: "browser" }, {});
  res.json({ run: { id: run.runId, state: "cancelled" } });
}

async function cancelBeforeAcceptance({ req, res, deps }: { req: Request; res: Response; deps: AssistantRouteDeps }, _optional = {}): Promise<DurableRun | null> {
  const body = (req.body ?? {}) as { messageId?: unknown; conversationId?: unknown };
  if (typeof body.messageId !== "string" || typeof body.conversationId !== "string") return null;
  return deps.chatRunLedger.durable?.cancelPending({ messageId: body.messageId, conversationId: body.conversationId,
    runId: randomUUID(), workspaceId: deps.workspaceId, principalId: getAuthedPrincipal(res).id, now: Date.now(),
  }, {}) ?? null;
}

/**
 * `GET /api/agents` / `POST /api/agents/rescan`'s dedicated handler — the one route pair that
 * reads the API-owned inventory, preserving the daemon route's existing response contract.
 * Design: `ADS-memory/reports/local-cli-live-model-discovery-design-2026-08-05.md` §3.1.
 *
 * Both routes answer the identical `{agents: AgentSummary[]}` shape (`@jini-ai/http-kit`'s
 * `agentListRoute`/`rescanAgentsRoute`, both `ok({agents: await ...()})`), so one handler serves
 * both. For the one entry with `id === "claude"`, enriches `models`/`modelsSource` with a live
 * discovery call against the ADMIN's own stored `anthropic` execution credential (never the SITE's
 * — see `live-model-cache.ts`'s header) — UNIONED into the static fallback list, never replacing
 * it (design §3.5: the bare `sonnet`/`opus`/`haiku` aliases are resolved by the CLI itself at spawn
 * time and must never be at risk of being dropped by an API-account-scoped live list that doesn't
 * contain them). `modelsSource` is only overwritten to `"live"` when the live call actually
 * contributed at least one entry — a `null`/empty result leaves the daemon's own
 * `models`/`modelsSource: "fallback"` byte-identical, which is what makes the credential branch a
 * pure enrichment step rather than something the picker can be gated or degraded by.
 *
 */
/** Enriches one agent's `models`/`modelsSource` with a live discovery call — the `claude` entry
 *  only, unioned into its static fallback list. See {@link respondWithEnrichedAgentList}'s own doc
 *  for the full union/never-replace/never-hard-fail contract this implements. */
async function enrichAgentWithLiveModels(
  { agent, liveModels, workspaceId, principalId }: { agent: AgentSummary; liveModels: LiveModelDiscovery; workspaceId: string; principalId: string },
  _options = {},
): Promise<AgentSummary> {
  if (agent.id !== "claude") return agent;
  const live = await liveModels.getLiveClaudeModels({ workspaceId, principalId });
  if (!live || live.length === 0) return agent;
  return { ...agent, models: unionModels(agent.models ?? [], live), modelsSource: "live" };
}

export async function respondWithEnrichedAgentList(
  { req, res, routeDeps, liveModels }: { req: Request; res: Response; routeDeps: AssistantRouteDeps; liveModels: LiveModelDiscovery },
  _options = {},
): Promise<void> {
  if (respondIfDaemonKnownFailed(res)) return;
  const inventory = routeDeps.assistantAgentInventory;
  if (!inventory) { res.status(503).json({ error: "the agent inventory is not configured", code: "AGENT_DAEMON_UNAVAILABLE" }); return; }
  const agents = await (req.method === "POST" ? inventory.rescanAssistantAgents({}, {}) : inventory.listAssistantAgents({}, {}));

  const principal = getAuthedPrincipal(res);
  const enriched = await Promise.all(agents.map((agent) => enrichAgentWithLiveModels({ agent, liveModels, workspaceId: routeDeps.workspaceId, principalId: principal.id })));

  res.json({ agents: enriched });
}

/**
 * `POST /api/admin/v1/mcp-ui/tool-calls` (ADR-053 Decision 3, extended for BYOK below) — the
 * redemption half of the MCP-UI confirmation pattern: a human clicked a rendered dialog
 * (`McpUiSurfaceCard` / `useMcpUiHost`), and `@jini-ai/chat`'s `createMcpUiToolCaller` posted
 * `{toolName, params}` here.
 *
 * Not `proxyPassthrough`: that client deliberately validates neither field (its own module doc says
 * so — a View's HTML is untrusted, so a client-side check would be a check the attacker writes both
 * sides of), which makes the allowlist check below load-bearing rather than decorative. Checked
 * again, authoritatively, by `mcp-ui-tool-calls-route.ts` on the daemon side and, for a locally-held
 * exchange, by `SurfaceExchangeStore.deliver`'s own binding check below — either way, THIS check
 * exists only to fail fast and keep an obviously-bad request off the wire at all; removing it would
 * not reopen a hole, but would turn a cheap 403 into wasted work.
 *
 * Two possible destinations now, tried in order:
 * 1. **Local delivery**, against `byokSurfaceExchanges` — reachable because this route and
 *    `modules/assistant-byok.ts`'s tool surface share ONE process and were handed the SAME store
 *    reference by `app.ts` at boot. Tried first because it costs one in-memory map lookup, vs. an
 *    HTTP round trip for the daemon fallback. A `binding-mismatch` is answered here, not forwarded —
 *    see this file's own header for why that reason specifically must not fall through.
 * 2. **Forward to the daemon** — the pre-existing behavior, unchanged, for anything the local store
 *    reports `unknown-or-closed` (including every request with no `exchangeId` at all, which never
 *    reaches the local branch below): `forwardToAgentDaemon` attaches the daemon bearer token and
 *    {@link RUN_PRINCIPAL_HEADER} exactly like every other route in this module, and the daemon-side
 *    route trusts both the same way `run-ownership.ts`'s routes do.
 */
/**
 * Tries LOCAL delivery against `byokSurfaceExchanges` for a redeemable `exchangeId`. Returns
 * `true` once it has already fully answered `res` (a genuine 202 success or a definitive 409
 * rejection) — `false` means the caller must fall through to the daemon, either because there was
 * no usable `exchangeId` at all or because the local store reported `unknown-or-closed` (this
 * exchange may belong to the DAEMON's own store, a Local CLI run this process cannot see).
 */
function tryLocalMcpUiDelivery(
  res: Response,
  byokSurfaceExchanges: SurfaceExchangeStore,
  exchangeId: unknown,
  params: Record<string, unknown>,
  toolName: string,
): boolean {
  if (typeof exchangeId !== "string" || exchangeId.length === 0) return false;

  const principalId = getAuthedPrincipal(res).id;
  const delivered = byokSurfaceExchanges.deliver({ exchangeId, params, principalId }, { toolId: toolName });
  if (delivered.ok) {
    // Deliberately not the tool's result — same reasoning as the daemon-side route's identical
    // 202: the agent's own held-open call is what returns that, to the model, where it belongs.
    res.status(202).json({ delivered: true });
    return true;
  }
  if (delivered.reason === "binding-mismatch") {
    // Found locally, just not for this caller/tool — a real rejection, not "try elsewhere". Same
    // 409 shape `mcp-ui-tool-calls-route.ts` uses for its own version of this same check.
    res.status(409).json({
      error: "that dialog is no longer waiting for an answer",
      code: "SURFACE_NOT_PENDING",
      reason: delivered.reason,
    });
    return true;
  }
  // `delivered.reason === "unknown-or-closed"`: fall through, let the daemon answer authoritatively.
  return false;
}

/**
 * `POST /api/admin/v1/a2ui/actions` — the browser relaying an A2UI renderer message (an action, or
 * the renderer's refusal of a surface). BYOK-first, like {@link proxyMcpUiToolCall}: a BYOK run's
 * A2UI exchange (`assistant_render_ui`, `assistant_demo_a2ui`) lives in `byokSurfaceExchanges`, in
 * this process, and the daemon cannot see it. Forwarded blindly, the renderer's refusal got a 409,
 * `assistant_render_ui` waited out its grace period, and reported a refused surface as rendered.
 *
 * Validated here with the daemon route's own `readA2uiAction`, so a malformed post is refused the
 * same way whichever store would have held it. A `binding-mismatch` is final (the exchange is here,
 * just not this caller's, or not an A2UI one); only `unknown-or-closed` falls through to the daemon.
 */
async function proxyA2uiAction(req: Request, res: Response, byokSurfaceExchanges: SurfaceExchangeStore, daemon: DaemonCallOptions): Promise<void> {
  const action = readA2uiAction(req.body);
  if (!action.ok) {
    res.status(400).json(action.error);
    return;
  }
  const principalId = getAuthedPrincipal(res).id;
  const delivered = deliverA2uiAction(byokSurfaceExchanges, { exchangeId: action.exchangeId, principalId, message: action.message });
  if (delivered.ok) {
    res.status(202).json({ delivered: true });
    return;
  }
  if (delivered.reason === "binding-mismatch") {
    res.status(409).json(a2uiNotPendingBody(delivered.reason));
    return;
  }
  await proxyPassthrough(req, res, daemon);
}

/** Resolves the local typed-answer target when there is no nonempty explicit id.
 * Returns the typed target or the original correlation value; principal binding stays store-owned.
 * @complexity O(open exchanges) for typed lookup, otherwise O(1); no delivery or execution. */
function localMcpUiTarget({ exchangeId, params, toolName, res, byokSurfaceExchanges }: {
  exchangeId: unknown; params: Record<string, unknown>; toolName: string; res: Response; byokSurfaceExchanges: SurfaceExchangeStore;
}, _options: Record<string, never> = {}): unknown {
  // A TYPED answer (prose from the chat composer) names no exchange — the human never saw one. The
  // daemon-side route recovers the correlation from its own store; this hop does the same against
  // the BYOK store first, for the identical reason the exchange-id branch tries local first: a
  // Local-CLI run's exchange lives HERE and the daemon cannot see it. An unmatched typed answer
  // falls through below exactly like an unknown exchange id does, so the daemon still answers
  // authoritatively for every run it owns.
  const namesAnExchange = typeof exchangeId === "string" && exchangeId.length > 0;
  const typedTarget =
    !namesAnExchange && isTypedSurfaceAnswer(params)
      ? byokSurfaceExchanges.findTypedAnswerTarget({ principalId: getAuthedPrincipal(res).id, toolId: toolName })
      : undefined;
  return typedTarget ?? exchangeId;
}

/** Admit answers only from an active person's browser session, before either exchange store sees them.
 * Session authentication alone can resolve a nonhuman principal, so both facts are required.
 * @returns False after sending the refusal; no delivery or daemon call occurs.
 * @complexity O(1), using the identity freshly resolved by requireAdminSession. */
function admitHumanSurfaceAnswer({ res }: { res: Response }, _optional = {}): boolean {
  if (!rejectUnlessSessionCredential(res, {
    message: "Answer this dialog from your signed-in browser session. Nothing was changed.",
    permission: "assistant.confirm",
  })) return false;
  const principal = getAuthedPrincipal(res);
  if (principal.kind === "user" && principal.status === "active") return true;
  res.status(403).json({ error: "An active, signed-in person must answer this dialog. Nothing was changed.", code: "FORBIDDEN" });
  return false;
}

/** Validate the callback envelope before looking up an exchange or forwarding to the daemon.
 * @returns The admitted fields, or undefined after sending the validation refusal.
 * @complexity O(1); tool metadata membership is a set lookup. */
function readAllowedMcpUiCallback({ body, res }: {
  body: { toolName?: unknown; params?: unknown; exchangeId?: unknown }; res: Response;
}, _optional = {}): {
  toolName: string; params: Record<string, unknown>; exchangeId: unknown;
} | undefined {
  const toolName = body.toolName;
  if (typeof toolName !== "string" || toolName.length === 0) {
    res.status(400).json({ error: "'toolName' must be a non-empty string", code: "VALIDATION_ERROR" });
    return;
  }
  // Same extraction `mcp-ui-tool-calls-route.ts` uses on the daemon side: a top-level `exchangeId`
  // for a channel that can name one directly, falling back to the MCP-UI-specific callback param
  // (an mcp-ui surface can only answer by issuing a tool call, so its correlation has to ride inside
  // that call's own params — see `surface-exchanges.ts`'s doc on `SURFACE_EXCHANGE_ID_PARAM`).
  const params = isPlainObject(body.params) ? body.params : {};
  const exchangeId = typeof body.exchangeId === "string" ? body.exchangeId : params[SURFACE_EXCHANGE_ID_PARAM];
  // The same rule the daemon route applies: a federated id (G3's per-call card) may only ANSWER an
  // open card, never be executed.
  const typedAnswer = isTypedSurfaceAnswer(params);
  const answersAnExchange = (typeof exchangeId === "string" && exchangeId.length > 0) || typedAnswer;
  if (!isMcpUiToolCallPermitted(toolName, answersAnExchange, { typedAnswer })) {
    res.status(403).json({ error: typedAnswer ? MCP_UI_TYPED_ANSWER_REFUSAL : `'${toolName}' is not an MCP-UI-redeemable tool`, code: "TOOL_NOT_ALLOWLISTED" });
    return;
  }
  return { toolName, params, exchangeId };
}

async function proxyMcpUiToolCall(req: Request, res: Response, byokSurfaceExchanges: SurfaceExchangeStore, daemon: DaemonCallOptions): Promise<void> {
  if (!admitHumanSurfaceAnswer({ res })) return;
  const callback = readAllowedMcpUiCallback({ body: req.body ?? {}, res });
  if (!callback) return;
  const { toolName, params, exchangeId } = callback;
  const target = localMcpUiTarget({ exchangeId, params, toolName, res, byokSurfaceExchanges });
  const restoreOnly = (req.body as { restore?: unknown } | undefined)?.restore === true;
  if (!restoreOnly && tryLocalMcpUiDelivery(res, byokSurfaceExchanges, target, params, toolName)) return;
  if (typeof target === 'string' && await tryRestoreSurface({
    res, store: byokSurfaceExchanges, exchangeId: target, principalId: getAuthedPrincipal(res).id, toolId: toolName,
  }, restoreOnly ? {} : { params })) return;

  // `forwardToAgentDaemon` deliberately does NOT relay (see its doc comment) — each caller relays
  // for itself. Without the relay in `proxyPassthrough` this route fetches the daemon's answer and
  // then never writes to `res`, so the fall-through above hangs the browser until it times out and
  // the MCP-UI confirmation dialog never resolves.
  await proxyPassthrough(req, res, daemon);
}

/**
 * `POST /api/attachments`'s dedicated proxy — every other route in this module forwards through
 * `forwardToAgentDaemon`'s `JSON.stringify(req.body)` path, which is wrong here on purpose: the
 * real (and only) client, `@jini-ai/chat/react`'s `createDaemonAttachmentUploader`, always sends
 * `content-type: application/octet-stream` with the raw file bytes as the body — re-serializing
 * `req.body` as JSON would send `"{}"` (an empty object, `express.json()`'s default for a body it
 * did not parse) instead of the file.
 *
 * That `content-type` mismatch is exactly what keeps this safe to read directly: Tovu's app-wide
 * `app.use(express.json({limit:"15mb"}))` (`server/app.ts`) only consumes a request whose
 * `content-type` it recognizes as JSON — for anything else it calls `next()` without touching the
 * stream at all, so `req` (a `http.IncomingMessage`, itself an async-iterable readable stream)
 * reaches this handler completely intact regardless of where in the middleware stack this route
 * was registered relative to that parser. `@jini-ai/http-kit`'s `attachments.ts` module doc calls
 * out exactly this class of bug ("a dropped `.json` file... `express.json()` eats the body") for
 * the daemon's OWN mount of this route pack — the same reasoning applies one hop earlier, here.
 *
 * `RUN_PRINCIPAL_HEADER` IS stamped here, even though (unlike every other forwarded route) an
 * attachment upload has no `runId` yet to compare it against (a run doesn't exist until
 * `POST /api/runs`, which happens after the composer has already staged its uploads) — so it is not
 * for `run-ownership.ts`'s own check. `agent-daemon-server.ts` instead reads it via
 * `AttachmentsHttpDeps.resolveOwnerId` and records it as the attachment's `ownerId`
 * (`@jini-ai/http-kit`'s `attachments.ts`), which is what lets `chat_list_pending_attachments`
 * later find an attachment the model was never told about in-run. Safe to assert here for the same
 * reason `outboundHeaders` already asserts it for every JSON-proxied route: this function is only
 * ever reached downstream of `requireAdminSession` (mounted on this whole path below), so the value
 * is always a server-verified session principal, never anything the browser chose. Authentication
 * is still enforced twice: `requireAdminSession` (browser session) and the bearer token this
 * function still attaches (proves the call came from Tovu's own proxy, not an arbitrary local
 * process) — see `daemon-auth.ts`.
 */
async function forwardAttachmentUpload(req: Request, res: Response, daemon: DaemonCallOptions): Promise<void> {
  if (!(await awaitDaemonForResponse({ res }, daemon))) return;
  const target = `${getAgentDaemonUrl()}${req.originalUrl}`;
  const headers: Record<string, string> = {
    "content-type": req.get("content-type") ?? "application/octet-stream",
  };
  const token = assistantDaemonToken({}, {});
  if (token) headers.Authorization = `Bearer ${token}`;
  // See this function's own doc: not for run ownership (no run exists yet), but so the daemon can
  // record who this attachment belongs to.
  headers[RUN_PRINCIPAL_HEADER] = getAuthedPrincipal(res).id;

  let upstream: globalThis.Response;
  try {
    upstream = await daemonFetch(daemon)(target, {
      method: "POST",
      headers,
      // `req` is a Node `Readable` (an `IncomingMessage`), which Node's `fetch` accepts directly as
      // a streaming request body — `duplex: "half"` is what the Fetch spec requires to opt into
      // that; omitting it throws synchronously before any request is even sent.
      body: req as unknown as BodyInit,
      duplex: "half",
    } as RequestInit);
  } catch (error) {
    console.error(`[assistant] agent daemon unreachable at ${getAgentDaemonUrl()}`, error);
    res.status(502).json({ error: "assistant is unavailable", code: "BAD_GATEWAY" });
    return;
  }
  await relayResponse(upstream, req, res);
}

/**
 * @param byokSurfaceExchanges - The SAME `SurfaceExchangeStore` `modules/assistant-byok.ts`'s tool
 * surface was composed with (`ByokToolSurface.surfaceExchanges`), built once by `app.ts` and passed
 * to both modules. Required, not defaulted: a locally-constructed fallback here would silently
 * diverge from the BYOK module's own store the first time someone forgot to thread it through, and
 * every confirmation would 404/409 against an exchange this store never opened.
 */
export function createAssistantModule(routeDeps: AssistantRouteDeps, byokSurfaceExchanges: SurfaceExchangeStore): ServerModuleHandle {
  // Every proxied daemon call is an outbound span under the admin request that caused it.
  const daemon: DaemonCallOptions = { observability: routeDeps.observability, ensureReady: routeDeps.assistantDaemonDemand?.ensureReady };
  // Each host owns its cache for its lifetime; unrelated applications cannot share a model slot.
  const liveModels = createLiveModelDiscovery({
    repo: routeDeps.adminExecutionCredentialRepo,
    sealer: routeDeps.siteAssistantSecretSealer,
    clock: routeDeps.clock,
    discover: fetchLiveClaudeModels,
  });
  return {
    name: "assistant",
    registerRoutes: (app: Express) => {
      app.use("/api/runs", requireAdminSession(routeDeps));
      app.post("/api/runs", (req: Request, res: Response, next: NextFunction) => {
        proxyRunStart(req, res, daemon, routeDeps).catch((error: unknown) => {
          if (error instanceof RunSlotBusyError) { res.status(409).json({ error: error.message, code: "CHAT_RUN_BUSY" }); return; }
          next(error);
        });
      });
      // `@jini-ai/http-kit`'s `registerRunRoutes` mounts `GET /api/runs` (list runs, optionally
      // filtered by `?contextRef=`) on the daemon alongside the `:runId` routes. It was missing
      // here, so the daemon's list endpoint was unreachable and 404'd at Tovu's own router.
      // Registered ahead of `GET /api/runs/:runId` to keep the exact-path match unambiguous.
      // The daemon answers it with the caller's own runs only — http-kit's version lists every
      // run on the box, which would hand one admin the ids of every other admin's runs.
      app.get("/api/runs", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));
      app.post("/api/runs/:runId/recover", (req, res, next) => recoverDurableRun({ req, res, deps: routeDeps }, {}).catch(next));
      app.get("/api/runs/:runId/checkpoint", (req, res, next) => readDurableCheckpoint({ req, res, deps: routeDeps }, {}).catch(next));
      app.get("/api/runs/:runId", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));
      app.get("/api/runs/:runId/events", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));
      app.post("/api/runs/:runId/cancel", (req, res, next) => cancelDurableRun({ req, res, deps: routeDeps, daemon }, {}).catch(next));
      // A message the operator sent mid-run, for the live agent (`@jini-ai/daemon`'s run-messages
      // route). Passed through untouched: the daemon's 202 / 409 `details.delivery` tells the chat
      // pane whether to deliver live or queue the text after the current run. A durable run's id is the
      // daemon's own (`launch` hands it over), so no ledger lookup is needed.
      app.post("/api/runs/:runId/messages", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));

      app.use("/api/agents", requireAdminSession(routeDeps));
      app.get("/api/agents", (req, res, next) => respondWithEnrichedAgentList({ req, res, routeDeps, liveModels }).catch(next));
      app.post("/api/agents/rescan", (req, res, next) => respondWithEnrichedAgentList({ req, res, routeDeps, liveModels }).catch(next));

      // Browser-reachable tool CATALOG enumeration — `search`/`describe` over the same 131-tool
      // registry `buildAssistantToolRegistrations` populates (`tool-catalog-query.ts`), proxied
      // from `@jini-ai/http-kit`'s `registerToolCatalogRoutes` (mounted daemon-side by
      // `agent-daemon-server.ts`). That daemon route is `requireSameOrigin`-gated and, before this,
      // reachable only by the spawned `jini-mcp` subprocess's own loopback `fetch` (no `Origin`
      // header, so it passes the daemon's same-origin check the way a browser's cross-origin
      // request never could) plus the daemon bearer token. `proxyPassthrough` satisfies both of
      // those the identical way that subprocess does: `forwardToAgentDaemon`'s outbound `fetch`
      // carries no `Origin` header either (Node's `fetch`, not a browser's) and attaches the same
      // bearer token every other route in this module does — so this proxy reaches the daemon route
      // exactly like its one existing legitimate caller, without loosening `requireSameOrigin`
      // itself by one bit. `requireAdminSession` below is the ONLY new gate a browser caller must
      // pass, replacing "must be that subprocess" with "must be a signed-in admin".
      //
      // BOUNDARY, stated plainly because the next reader will otherwise conflate it with item 1's
      // MCP-UI allowlist: this exposes tool **names and descriptions** to an authenticated admin
      // session, in the admin's own page. It is **read-only enumeration, never execution** — no
      // `toolName`/`params` body is accepted here, there is no POST/PUT/DELETE mounted on this
      // path, and nothing on this path can reach `ToolExecutor.execute`. A tool becomes callable
      // from the browser only through `MCP_UI_TOOL_CALLS_PATH`'s own allowlist
      // (`mcp-ui-tool-calls.ts`) — a completely separate trust decision this route does not make or
      // widen.
      //
      // Proxy failure remains bounded: known-failed daemon boots return 503 without a fetch,
      // and unreachable daemons return 502. Enumeration cannot hang on an unavailable daemon.
      app.use("/api/tools", requireAdminSession(routeDeps));
      app.get("/api/tools/search", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));
      app.get("/api/tools/:id", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));

      // Agent-driven control of the admin's own tab (`page.navigate`, `page.scroll_to`, …). The
      // stream carries invocations down to the browser and the response route carries answers
      // back; both are `@jini-ai/http-kit`'s, mounted on the daemon by `agent-daemon-server.ts`.
      //
      // Proxied rather than reached directly for the same reason every other route here is: the
      // daemon requires a bearer token the browser must never hold, and `requireAdminSession`
      // is what proves a caller is an admin at all. The stream in particular depends on
      // `relayResponse` above streaming rather than buffering — it is SSE, exactly like
      // `/api/runs/:runId/events`, and buffering it would mean the tab never receives an
      // invocation until the connection closed.
      app.use("/api/frontend-sessions", requireAdminSession(routeDeps));
      // Session-gated like every other chat POST (POST /api/runs wakes the daemon the same way).
      app.post("/api/frontend-sessions/activate", (req, res, next) => {
        activateFrontendDaemon({ req, res }, daemon).catch(next);
      });
      app.post("/api/frontend-sessions/request", (req, res, next) => {
        proxyPassthrough(req, res, daemon).catch(next);
      });
      app.get("/api/frontend-sessions/stream", (req, res, next) => {
        if (parkColdFrontendStream({ res, isReady: routeDeps.assistantDaemonDemand?.isReady ?? isAssistantDaemonReady }, {})) return;
        proxyPassthrough(req, res, { ...daemon, passive: true }).catch(next);
      });
      app.post("/api/frontend-sessions/:sessionId/responses", (req, res, next) =>
        proxyPassthrough(req, res, daemon).catch(next),
      );

      // Composer image/file uploads (`@jini-ai/chat/react`'s `uploadAttachments` prop,
      // `AssistantDock.tsx`). Same session-auth requirement as every other route in this module —
      // an unauthenticated upload endpoint is an arbitrary-file-write primitive reachable by
      // anyone who can reach this port, so this gate is not optional. `POST` needs the dedicated
      // raw-stream proxy above; `DELETE`'s body is real small JSON
      // (`{batchId, paths}` — `create-daemon-attachment-uploader.ts`'s `deletePartialUpload`), so
      // the ordinary `proxyPassthrough` JSON path is correct for it unchanged.
      app.use("/api/attachments", requireAdminSession(routeDeps));
      app.post("/api/attachments", (req: Request, res: Response, next: NextFunction) => {
        forwardAttachmentUpload(req, res, daemon).catch(next);
      });
      app.delete("/api/attachments", (req, res, next) => proxyPassthrough(req, res, daemon).catch(next));

      // Reading a staged attachment's bytes BACK — the half `@jini-ai/http-kit`'s route pack never
      // had, so until now bytes could be uploaded and never fetched again and the admin's preview
      // modal could only show attachments from the current session out of a client-side `File`
      // cache. See `routes/assistant/get-chat-attachment.ts` for the security model and
      // `features/media/read-chat-attachment.ts` for the authorization rule (owner-scoped, and an
      // attachment with no recorded owner is readable by nobody).
      //
      // Deliberately NOT a proxy, unlike the two routes above, and this is the one thing about it
      // that will surprise the next reader: the daemon owns the live `AttachmentStore`, but that
      // port exposes no non-mutating owner-scoped read (`resolveForRun` CLAIMS what it resolves,
      // and `listPendingForOwner` returns no path and excludes exactly the already-claimed
      // attachments this feature exists for). Serving it here instead also means the principal is
      // compared in the same process that mints it, with no trusted-header hop between the check
      // and the value being checked.
      //
      // Registered inside this module rather than as its own, for the `app.use` two lines above:
      // Express matches that session gate on the `/api/attachments` prefix AND every subpath, so
      // this route is covered by the same mount that covers the upload it reads back. A separate
      // module would have to re-mount the same guard, which is a second thing to keep in sync.
      registerAdminChatAttachmentReadRoute(app, { uploadDirectory: routeDeps.siteStoragePaths.chatAttachmentsDir });

      // The MCP-UI confirmation redemption endpoint (ADR-053 Decision 3) — see
      // `proxyMcpUiToolCall`'s own doc. Session-gated like every route above; distinct from
      // `/api/delegated-tool-calls`, which is intentionally NOT mounted in this module at all (see
      // this file's header) and whose trust boundary this endpoint does not reuse or widen.
      app.use(MCP_UI_TOOL_CALLS_PATH, requireAdminSession(routeDeps));
      app.post(MCP_UI_TOOL_CALLS_PATH, (req: Request, res: Response, next: NextFunction) => {
        proxyMcpUiToolCall(req, res, byokSurfaceExchanges, daemon).catch(next);
      });

      // A2UI's own inbound endpoint (`a2ui-actions-route.ts`) — BYOK store first, then the daemon;
      // see `proxyA2uiAction`'s doc. No allowlist: there is no `toolName` on an A2UI action (the
      // daemon-side route has none either — A2UI has no execution surface to allowlist).
      app.use(A2UI_ACTIONS_PATH, requireAdminSession(routeDeps));
      app.post(A2UI_ACTIONS_PATH, (req: Request, res: Response, next: NextFunction) => {
        proxyA2uiAction(req, res, byokSurfaceExchanges, daemon).catch(next);
      });
    },
  };
}

import { registerAuthRoutes, requireAdminSession, type AdminSignInPort } from "#src/server/inbound/admin-http/dev-auth";
import { requirePublishTrust } from "#src/server/inbound/admin-http/publish-trust-auth";
import { registerHealthRoute, registerHealthzRoute, registerReadyzRoute } from "#src/server/inbound/public-http/routes/ops/health";
import { registerPublishTrustHandshakeRoutes } from "#src/server/inbound/public-http/routes/publish-trust/handshake";
import { InMemoryPublishChallengeStore } from "#src/features/publish-trust/challenge";
import { deriveInstallationId } from "#src/features/publish-trust/keys";
import { createPublishTrustGrantResolver } from "../publish-trust-grants.js";
import { createPublishTrustRevocationReader } from "../publish-trust-revocations.js";
import type { RouteDeps } from "#src/server/routes/types";
import type { ServerModuleHandle } from "./types.js";

/**
 * @file ADR-046 Phase 3 (SPEC-039) — the `core` module: health/readiness routes, login/logout/me,
 * and the `/api/admin` session gate.
 *
 * Scope note (SPEC-039, correcting SPEC-031's deferral): SPEC-031 and SPEC-034 both declined to
 * move `requireAdminSession`'s `app.use("/api/admin", ...)` mount here, because
 * `registerAuthRoutes` registers `POST /api/admin/v1/auth/login` — an `/api/admin`-prefixed route
 * — and Express matches middleware/routes strictly in registration order. If the session gate
 * mounted before login registered, login would 401 against its own gate and nobody could ever
 * obtain a session (total lockout, no recovery path). The user decision recorded in SPEC-039
 * resolves this by keeping BOTH concerns — the login/logout/me route registration AND the gate
 * mount — inside this single `registerRoutes(app)` call, in the same relative order every other
 * module already has full control over its own internal registration order. That preserves the
 * load-bearing property (login registers before the gate mounts) without widening
 * `ServerModuleHandle` itself to support cross-module ordered/interleaved registration, which was
 * explicitly rejected as higher blast radius for this one edge case.
 *
 * This is the one module in this repo's `ServerModuleHandle` convention that takes the full
 * `RouteDeps` bag rather than a narrow `Pick` — `registerAuthRoutes` is still typed against full
 * `RouteDeps` upstream in `inbound/admin-http/dev-auth.ts` (this module's own `deps` param has to stay a
 * full `RouteDeps` on its account). `requireAdminSession` takes `SessionAuthDeps`;
 * passing the full `deps` below satisfies it
 * because `RouteDeps` is a strict superset of `SessionAuthDeps`.
 */
export function createCoreModule(deps: RouteDeps, optional: { onAdminSignIn?: AdminSignInPort } = {}): ServerModuleHandle {
  // This install's own publishing identity — the audience every publishing token must name.
  // Derived once per process rather than per request: it is a pure function of the site key and
  // the workspace, so it cannot change while the process runs. Awaited inside each consumer, so a
  // slow keyring delays the first handshake rather than boot.
  const targetInstallationId = deriveInstallationId({
    keyring: deps.siteAssistantSecretKeyring,
    workspaceId: deps.workspaceId,
  });
  // Marks a missing site key as handled at boot. Each consumer still awaits the same rejection and
  // refuses that one request; without this, a keyless process logs an unhandled rejection at startup.
  targetInstallationId.catch(() => undefined);
  const challengeStore = new InMemoryPublishChallengeStore(deps.clock);
  const grants = createPublishTrustGrantResolver();
  // The other half of the admission question. Its SQLite adapter proves the table is readable
  // during real-process boot; this module gives the request path a read-only view and re-reads it
  // for every publishing request so a disconnect bites immediately.
  const revocationStore = deps.publishTrustRevocations;

  return {
    name: "core",
    registerRoutes: (app) => {
      registerHealthRoute(app);
      registerHealthzRoute(app);
      registerReadyzRoute(app);

      // Unauthenticated by design and deliberately NOT under `/api/admin`: a source that has not
      // yet proved possession has no credential to present. See `handshake.ts`'s own header for
      // what `/identity` discloses and why that is acceptable.
      registerPublishTrustHandshakeRoutes(app, {
        keyring: deps.siteAssistantSecretKeyring,
        workspaceId: deps.workspaceId,
        clock: deps.clock,
        idGen: deps.idGen,
        challengeStore,
        targetInstallationId,
        grants,
      });

      // Order is load-bearing: `registerAuthRoutes` registers the ungated
      // `POST /api/admin/v1/auth/login` (plus logout/me) route BEFORE the
      // gate below mounts, so login itself is never caught by its own gate.
      registerAuthRoutes(app, deps, { onAdminSignIn: optional.onAdminSignIn });

      // Order is load-bearing here too, and in the other direction: the publishing gate runs
      // BEFORE the admin session gate, because a publishing token is presented in the same
      // `Authorization` header an API key uses and only this gate can tell them apart. It leaves
      // every request it does not recognise completely untouched, so the session gate behind it
      // behaves exactly as it did before.
      app.use("/api/admin", requirePublishTrust({
        keyring: deps.siteAssistantSecretKeyring,
        workspaceId: deps.workspaceId,
        clock: deps.clock,
        targetInstallationId,
        grants,
        // `list` alone: the gate must never hold a handle that can edit the deny list it is judged
        // against, and an unreadable list has to reach it as a refusal rather than as a throw.
        revocations: createPublishTrustRevocationReader(revocationStore),
      }));
      app.use("/api/admin", requireAdminSession(deps));
    },
  };
}

/**
 * @file `registerFormNotifySubscriber` — the Forms-owned outbox subscriber (SPEC-010 REQ-12,
 * ADR-PIPE-010 C-009).
 *
 * Purpose:
 * Subscribes `form.submission.received`; on a notify-enabled definition, calls `MailerPort.send()`
 * per configured recipient through an isolated durable job. The one piece of Forms-owned business logic riding the outbox — kept
 * separate from the webhook-fanout forwarding (which is not Forms-owned logic; see
 * `server/app.ts`'s wiring). Legacy hosts log failures; durable recipient jobs propagate
 * failures to their own outbox row, outside the source `EventBusPort.publish()` subscriber loop (`core/events/memory-bus.ts`'s `publish`
 * does not catch handler errors itself — a subscriber that fails to catch its own errors would
 * break every OTHER subscriber to the same event, including the webhook fan-out). Recipient jobs
 * keep those failures separate while preserving retry and terminal status.
 *
 * Deliberately duplicates the `'form.submission.received'` topic-name literal rather than
 * importing it from `./manifest` — see `types.ts`'s file header for why domain code never reads
 * the manifest back.
 */
import { registerFormAttachmentCleanup, registerFormNotifySubscriber, type FormDefinitionRepoPort, type FormSubmissionRepoPort } from "@jini-ai/cms/forms";
import type { Tracker } from "@jini-ai/diagnostics/observability";
import type { EventBusPort } from "@jini-ai/cms/core";
import { mailSenderIdentityFor, type MailerPort, type MailSenderIdentityPort } from "#src/platform/mail/index";
import type { ServerModuleHandle } from "./types.js";

export interface FormsModuleDeps {
  bus: EventBusPort;
  outbox?: import("@jini-ai/cms/core").OutboxPort;
  fileCleanup?: Omit<Parameters<typeof registerFormAttachmentCleanup>[0], "bus">;
  tracker: Tracker;
  mailer: MailerPort;
  formDefinitionRepo: FormDefinitionRepoPort;
  formSubmissionRepo: FormSubmissionRepoPort;
  visitorAnalyticsDeliveryAllowed?: import('#src/server/inbound/public-http/visitor-analytics').VisitorAnalyticsDeps['visitorAnalyticsDeliveryAllowed'];
  /** Resolves each notification's From (`platform/mail/sender-identity.ts`); absent, the placeholder
   *  is used only while `mailer` is non-delivering. */
  senderIdentity?: MailSenderIdentityPort;
}

/** Placeholder From for a non-delivering mailer; real providers get the site's configured sender. */
const FORMS_FALLBACK_SENDER = { email: "no-reply@forms.local", name: "Forms" } as const;

/**
 * @file ADR-046 Phase 3 (SPEC-031) — the `forms` module: owns starting the C-009 notify
 * subscriber (`registerFormNotifySubscriber`, SPEC-010/ADR-PIPE-010 W-004) — Forms' own,
 * business-logic subscription to `form.submission.received`. The SIBLING webhook-fanout
 * subscription to the same event is deliberately NOT here — see `modules/integrations.ts`'s file
 * header for why cross-feature integration is Integrations' job, not Forms'.
 */
export function createFormsModule(deps: FormsModuleDeps): ServerModuleHandle {
  return {
    name: "forms",
    start: () => {
      if (deps.fileCleanup) void registerFormAttachmentCleanup({ bus: deps.bus, ...deps.fileCleanup });
      void deps.bus.subscribe<{ workspaceId: string; formDefinitionId: string; deliveryMode?: string;
        analyticsProvenance?: import('#src/features/forms/index').FormAnalyticsProvenance }>({
        eventName: "form.submission.received",
        handler: async (event) => {
          const proof = event.payload.analyticsProvenance;
          if (proof?.granted !== true || !proof.subjectId) return;
          const definition = await deps.formDefinitionRepo.findById({ workspaceId: event.payload.workspaceId, id: event.payload.formDefinitionId });
          if (!definition) return;
          // The definition read can yield; recheck visitor consent immediately before delivery.
          if (!proof.consentProof || !await deps.visitorAnalyticsDeliveryAllowed?.({ proof: proof.consentProof })) return;
          // The provider dedupes retries with this committed domain event id; no form answers leave.
          deps.tracker.capture({ name: "form_submitted", userId: proof.subjectId }, { properties: {
            eventId: event.id, formId: definition.id, formSlug: definition.slug,
            deliveryMode: event.payload.deliveryMode === "remote_import" ? "remote_import" : "live",
          } });
        },
      });
      const senderIdentity = mailSenderIdentityFor({ mailer: deps.mailer }, { senderIdentity: deps.senderIdentity });
      void registerFormNotifySubscriber({
        ...deps,
        // The Jini subscriber takes one fixed sender, but the From is per workspace and read fresh
        // per send, so the mailer seam below replaces it. A `SenderIdentityNotConfiguredError` thrown
        // there is logged by the subscriber as a failed send, like any other send failure.
        sender: FORMS_FALLBACK_SENDER,
        logger: { warn: ({ message }, { error } = {}) => console.warn(message, ...(error === undefined ? [] : [error])) },
        mailer: {
          send: async ({ message, options }) => {
            const from = await senderIdentity.resolve({ workspaceId: message.workspaceId, fallback: FORMS_FALLBACK_SENDER });
            return deps.mailer.send({ ...message, from }, options);
          },
        },
      }, {});
    },
  };
}

